const permissionEligibleRoles = new Map(delegablePortalPermissionCatalog
  .filter((entry) => Array.isArray(entry.eligibleRoles))
  .map((entry) => [entry.id, new Set(entry.eligibleRoles)]));

function portalPermissionAllowedForRole(permission, role) {
  if (String(role || "") === "developer") return true;
  const eligibleRoles = permissionEligibleRoles.get(String(permission || ""));
  return !eligibleRoles || eligibleRoles.has(String(role || ""));
}

function portalPermissionRoleRestrictionError(permissions) {
  const restricted = Array.isArray(permissions) ? permissions : [];
  if (restricted.length && restricted.every((permission) => protectedAmuPermissionIds.has(permission))) {
    return httpError(403, "Geschützte AUM-Rechte dürfen nur Personalleitung und höheren Rollen zugewiesen werden.", "AMU_PERMISSION_ROLE_RESTRICTED");
  }
  if (restricted.length && restricted.every((permission) => SALES_ANALYTICS_PERMISSION_IDS.includes(permission))) {
    return httpError(403, "Verkaufsanalyse-Rechte dürfen nur dafür vorgesehenen kaufmännischen Rollen zugewiesen werden.", "SALES_ANALYTICS_PERMISSION_ROLE_RESTRICTED");
  }
  if (restricted.length && restricted.every((permission) => CRM_PERMISSION_IDS.includes(permission))) {
    return httpError(403, "CRM-Rechte dürfen nur dafür vorgesehenen kaufmännischen Rollen zugewiesen werden.", "CRM_PERMISSION_ROLE_RESTRICTED");
  }
  if (restricted.length && restricted.every(
    (permission) => SALES_ARTICLE_CATALOG_PERMISSION_IDS.includes(permission),
  )) {
    return httpError(403, "Artikelstamm-Rechte dürfen nur dafür vorgesehenen kaufmännischen Rollen zugewiesen werden.", "SALES_ARTICLE_CATALOG_PERMISSION_ROLE_RESTRICTED");
  }
  if (restricted.length && restricted.every((permission) => PERSONNEL_LEARNING_PERMISSION_IDS.includes(permission))) {
    return httpError(403, "Schulungs- und Wissensrechte dürfen nur den dafür vorgesehenen persönlichen Fachrollen zugewiesen werden.", "PERSONNEL_LEARNING_PERMISSION_ROLE_RESTRICTED");
  }
  if (restricted.length && restricted.every(
    (permission) => CROSS_LOCATION_SCHEDULE_PERMISSION_IDS.includes(permission),
  )) {
    return httpError(403, "Standortübergreifende Dienstplan- und Einsatzanfragerechte dürfen nur den dafür vorgesehenen persönlichen Fachrollen zugewiesen werden.", "CROSS_LOCATION_SCHEDULE_PERMISSION_ROLE_RESTRICTED");
  }
  if (restricted.length && restricted.every(
    (permission) => PORTAL_BIRTHDAY_PRESENTATION_PERMISSION_IDS.includes(permission),
  )) {
    return httpError(403, "Rechte für Geburtstagsdarstellungen dürfen nur den dafür vorgesehenen persönlichen Leitungsrollen zugewiesen werden.", "PORTAL_BIRTHDAY_PRESENTATION_PERMISSION_ROLE_RESTRICTED");
  }
  return httpError(403, "Diese Personalakt-Rechte sind für die gewählte App-Rolle nicht zulässig.", "PORTAL_PERMISSION_ROLE_RESTRICTED");
}

function assertPortalPermissionDependencies(permissions) {
  const projected = new Set(Array.isArray(permissions) ? permissions : []);
  if (projected.has("amu:local:manage") && !projected.has("sickness:read")) {
    throw httpError(400,
      "AUM im eigenen Verantwortungsbereich kann nur zusammen mit dem Leserecht für Krankmeldungen vergeben werden.",
      "PORTAL_PERMISSION_DEPENDENCY");
  }
  const requirePermission = (permission, dependency, message) => {
    if (projected.has(permission) && !projected.has(dependency)) {
      throw httpError(400, message, "PORTAL_PERMISSION_DEPENDENCY");
    }
  };
  const requireAnyPermission = (permission, dependencies, message) => {
    if (projected.has(permission) && !dependencies.some((dependency) => projected.has(dependency))) {
      throw httpError(400, message, "PORTAL_PERMISSION_DEPENDENCY");
    }
  };
  const personnelLearningDependencies = resolvePersonnelLearningPermissionDependencies(
    [...projected],
  );
  if (!personnelLearningDependencies.valid) {
    throw httpError(
      400,
      "Schulungs- und Wissensrechte können nur zusammen mit ihren erforderlichen Basisrechten vergeben werden.",
      "PORTAL_PERMISSION_DEPENDENCY",
    );
  }
  const crossLocationScheduleDependencies = resolveCrossLocationSchedulePermissionDependencies(
    [...projected],
  );
  if (!crossLocationScheduleDependencies.valid) {
    throw httpError(
      400,
      "Standortübergreifende Dienstplan- und Einsatzanfragerechte können nur zusammen mit ihren erforderlichen Leserechten vergeben werden.",
      "PORTAL_PERMISSION_DEPENDENCY",
    );
  }
  const crmDependencies = resolveCrmPermissionDependencies([...projected]);
  if (!dataImportPermissionDependencies([...projected]).valid) {
    throw httpError(400, "Gesamtimportrechte benötigen ihre getrennten Basis- und Gesamtfirmenrechte.", "PORTAL_PERMISSION_DEPENDENCY");
  }
  if (!salesHistoryPermissionDependencies([...projected]).valid) {
    throw httpError(400, "Einzelverkaufs-, Mitarbeiter-, Kundenkauf- und Kassenrechte benötigen ihre getrennten Basis- und Bereichsrechte.", "PORTAL_PERMISSION_DEPENDENCY");
  }
  if (!crmDependencies.valid) {
    throw httpError(
      400,
      "CRM-Rechte können nur zusammen mit ihren erforderlichen Basisrechten vergeben werden.",
      "PORTAL_PERMISSION_DEPENDENCY",
    );
  }
  const salesArticleCatalogDependencies = resolveSalesArticleCatalogPermissionDependencies(
    [...projected],
  );
  if (!salesArticleCatalogDependencies.valid) {
    throw httpError(
      400,
      "Artikelstamm-Rechte können nur zusammen mit den erforderlichen Zugangs- und Leserechten vergeben werden.",
      "PORTAL_PERMISSION_DEPENDENCY",
    );
  }
  for (const permission of SALES_ANALYTICS_PERMISSION_IDS.filter(
    (permission) => permission !== SALES_ANALYTICS_PERMISSIONS.ACCESS,
  )) {
    requirePermission(
      permission,
      SALES_ANALYTICS_PERMISSIONS.ACCESS,
      "Verkaufsdatenrechte können nur zusammen mit dem Zugang zu Verkaufsanalysen vergeben werden.",
    );
  }
  for (const permission of [
    SALES_ANALYTICS_PERMISSIONS.INVENTORY_READ,
    SALES_ANALYTICS_PERMISSIONS.MARGIN_READ,
    SALES_ANALYTICS_PERMISSIONS.IMPORT_MANAGE,
  ]) {
    requireAnyPermission(
      permission,
      [SALES_ANALYTICS_PERMISSIONS.LOCATION_READ, SALES_ANALYTICS_PERMISSIONS.COMPANY_READ],
      "Bestands-, Kosten- und Rohertragsrechte benötigen eine wirksame Filial- oder Gesamtfirmenprojektion.",
    );
  }
  requirePermission(
    SALES_ANALYTICS_PERMISSIONS.IMPORT_MANAGE,
    SALES_ANALYTICS_PERMISSIONS.MARGIN_READ,
    "Der PDF-Statistikimport benötigt wegen der enthaltenen Rohertragswerte zusätzlich das Rohertragsrecht.",
  );
  requirePermission(
    "personnel:applications:write",
    "personnel:candidates:read",
    "Bewerbungen können nur zusammen mit dem Leserecht für Bewerber bearbeitet werden.",
  );
  requirePermission(
    "personnel:candidates:write",
    "personnel:candidates:read",
    "Bewerber können nur zusammen mit dem Leserecht angelegt oder bearbeitet werden.",
  );
  requirePermission(
    "personnel:candidates:confidential:read",
    "personnel:candidates:read",
    "Vertrauliche Bewerberdaten setzen das Bewerber-Leserecht voraus.",
  );
  requirePermission(
    "personnel:candidates:confidential:write",
    "personnel:candidates:confidential:read",
    "Vertrauliche Bewerberdaten können nur mit dem zugehörigen Leserecht bearbeitet werden.",
  );
  requirePermission(
    "personnel:candidates:confidential:write",
    "personnel:applications:write",
    "Vertrauliche Bewerbungsdaten setzen das Bearbeitungsrecht für Bewerbungen voraus.",
  );
  requirePermission(
    "personnel:candidates:convert",
    "personnel:candidates:confidential:write",
    "Die kontrollierte Einstellung setzt die vollständigen zentralen Bewerberrechte voraus.",
  );
  requirePermission(
    "personnel:candidates:convert",
    "personnel:candidates:write",
    "Die kontrollierte Einstellung setzt das zentrale Schreibrecht für Bewerber voraus.",
  );
  requirePermission(
    PERSONNEL_WORKFLOW_PERMISSIONS.DRAFT_WRITE,
    PERSONNEL_WORKFLOW_PERMISSIONS.READ,
    "Workflow-Entwürfe können nur zusammen mit dem Workflow-Leserecht bearbeitet werden.",
  );
  requirePermission(
    PERSONNEL_WORKFLOW_PERMISSIONS.REVIEW,
    PERSONNEL_WORKFLOW_PERMISSIONS.READ,
    "Die fachliche Workflow-Prüfung setzt das Workflow-Leserecht voraus.",
  );
  requirePermission(
    PERSONNEL_WORKFLOW_PERMISSIONS.PUBLISH,
    PERSONNEL_WORKFLOW_PERMISSIONS.DRAFT_WRITE,
    "Workflow-Versionen können nur mit dem zugehörigen Entwurfsrecht veröffentlicht werden.",
  );
  requirePermission(
    PERSONNEL_WORKFLOW_PERMISSIONS.LOCAL_SUPPLEMENT,
    PERSONNEL_WORKFLOW_PERMISSIONS.DRAFT_WRITE,
    "Lokale Workflow-Ergänzungen setzen das zugehörige Entwurfsrecht voraus.",
  );
  requirePermission(
    PERSONNEL_WORKFLOW_PERMISSIONS.CONFIDENTIAL_READ,
    PERSONNEL_WORKFLOW_PERMISSIONS.READ,
    "Vertrauliche Workflow-Inhalte setzen das Workflow-Leserecht voraus.",
  );
  requirePermission(
    PERSONNEL_WORKFLOW_PERMISSIONS.CONFIDENTIAL_WRITE,
    PERSONNEL_WORKFLOW_PERMISSIONS.CONFIDENTIAL_READ,
    "Vertrauliche Workflow-Inhalte können nur mit dem zugehörigen Leserecht bearbeitet werden.",
  );
  requirePermission(
    PERSONNEL_WORKFLOW_PERMISSIONS.CONFIDENTIAL_WRITE,
    PERSONNEL_WORKFLOW_PERMISSIONS.DRAFT_WRITE,
    "Vertrauliche Workflow-Inhalte setzen das normale Entwurfsrecht voraus.",
  );
  requirePermission(
    PERSONNEL_WORKFLOW_PERMISSIONS.DELEGATE,
    PERSONNEL_WORKFLOW_PERMISSIONS.READ,
    "Die Freigabe lokaler Workflow-Rechte setzt das Workflow-Leserecht voraus.",
  );
  requirePermission(
    PERSONNEL_PROFILE_PERMISSIONS.MASTER_READ,
    PERSONNEL_PROFILE_PERMISSIONS.READ,
    "Mitarbeiter-Stammdaten können nur zusammen mit dem Profil-Leserecht gelesen werden.",
  );
  requirePermission(
    PERSONNEL_PROFILE_PERMISSIONS.DOCUMENTS_READ,
    PERSONNEL_PROFILE_PERMISSIONS.READ,
    "Personalakt-Dokumente können nur zusammen mit dem Profil-Leserecht gelesen werden.",
  );
  for (const permission of [
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.ONBOARDING_PREPARE,
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.ONBOARDING_APPROVE,
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.ONBOARDING_EXECUTE,
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.ONBOARDING_CLOSE,
  ]) {
    requirePermission(
      permission,
      PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.ONBOARDING_READ,
      "Onboarding-Aktionen setzen das ausdrückliche Onboarding-Leserecht voraus.",
    );
  }
  for (const permission of [
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.OFFBOARDING_PREPARE,
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.OFFBOARDING_COMMUNICATION_RELEASE,
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.OFFBOARDING_INFORMATION_CONFIRM,
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.OFFBOARDING_EXECUTE,
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.OFFBOARDING_CLOSE,
  ]) {
    requirePermission(
      permission,
      PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.OFFBOARDING_CONFIDENTIAL_READ,
      "Vertrauliche Offboarding-Aktionen setzen das eigenständige vertrauliche Leserecht voraus.",
    );
  }
  requirePermission(
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.PACKAGES_WRITE,
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.PACKAGES_READ,
    "Lifecycle-Pakete können nur zusammen mit dem Paket-Leserecht bearbeitet werden.",
  );
  requirePermission(
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.PACKAGES_PUBLISH,
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.PACKAGES_WRITE,
    "Lifecycle-Pakete können nur nach freigegebener Bearbeitung veröffentlicht werden.",
  );
  requirePermission(
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.OPERATIONAL_UPDATE,
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.OPERATIONAL_READ,
    "Operative Lifecycle-Aufgaben können nur zusammen mit dem operativen Leserecht bearbeitet werden.",
  );
  requirePermission(
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.CONFIDENTIAL_AUDIT_READ,
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.AUDIT_READ,
    "Die vertrauliche Lifecycle-Zugriffsspur setzt das allgemeine Lifecycle-Auditrecht voraus.",
  );
  for (const permission of [
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.ASSIGNMENTS_WRITE,
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.EXCEPTIONS_APPROVE,
  ]) {
    if (projected.has(permission)
      && !projected.has(PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.ONBOARDING_READ)
      && !projected.has(PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.OFFBOARDING_CONFIDENTIAL_READ)) {
      throw httpError(
        400,
        "Lifecycle-Zuweisungen und Ausnahmen setzen mindestens einen ausdrücklich lesbaren Falltyp voraus.",
        "PORTAL_PERMISSION_DEPENDENCY",
      );
    }
  }
  for (const domain of ["training", "asset", "access"]) {
    const readPermission = `personnel:lifecycle:interfaces:${domain}:read`;
    for (const capability of ["manage", "dispatch", "reconcile"]) {
      requirePermission(
        `personnel:lifecycle:interfaces:${domain}:${capability}`,
        readPermission,
        "O6-Schnittstellenaktionen setzen das ausdrückliche Leserecht derselben Domäne voraus.",
      );
    }
  }
  const automationCapabilitiesByDomain = Object.freeze({
    deadlines: ["manage", "recalculate", "reconcile"],
    substitutions: ["manage", "apply", "reconcile"],
    reminders: ["manage", "dispatch", "reconcile"],
    escalations: ["manage", "trigger", "reconcile"],
  });
  for (const [domain, capabilities] of Object.entries(automationCapabilitiesByDomain)) {
    const readPermission = PERSONNEL_LIFECYCLE_AUTOMATION_READ_PERMISSIONS[domain];
    for (const capability of capabilities) {
      requirePermission(
        `personnel:lifecycle:automation:${domain}:${capability}`,
        readPermission,
        "O7-Automationsaktionen setzen das ausdrückliche Leserecht derselben Domäne voraus.",
      );
    }
  }
  for (const [permission, prerequisite, message] of [
    [
      PERSONNEL_LIFECYCLE_EDITOR_PERMISSIONS.DRAFT_WRITE,
      PERSONNEL_LIFECYCLE_EDITOR_PERMISSIONS.READ,
      "O8-Workflow-Entwürfe können nur zusammen mit dem Editor-Leserecht bearbeitet werden.",
    ],
    [
      PERSONNEL_LIFECYCLE_EDITOR_PERMISSIONS.VALIDATE,
      PERSONNEL_LIFECYCLE_EDITOR_PERMISSIONS.DRAFT_WRITE,
      "O8-Workflow-Entwürfe können nur mit dem zugehörigen Entwurfsrecht geprüft werden.",
    ],
    [
      PERSONNEL_LIFECYCLE_EDITOR_PERMISSIONS.REVIEW,
      PERSONNEL_LIFECYCLE_EDITOR_PERMISSIONS.VALIDATE,
      "Die fachliche O8-Prüfung setzt die technische Entwurfsprüfung voraus.",
    ],
    [
      PERSONNEL_LIFECYCLE_EDITOR_PERMISSIONS.PUBLISH,
      PERSONNEL_LIFECYCLE_EDITOR_PERMISSIONS.REVIEW,
      "Eine O8-Veröffentlichung setzt die fachliche Prüfung voraus.",
    ],
    [
      PERSONNEL_LIFECYCLE_EDITOR_PERMISSIONS.ARCHIVE,
      PERSONNEL_LIFECYCLE_EDITOR_PERMISSIONS.PUBLISH,
      "Eine O8-Archivierung setzt das Veröffentlichungsrecht voraus.",
    ],
  ]) {
    requirePermission(permission, prerequisite, message);
  }
}

