function formatVersionLabel(version) {
  const match = String(version).match(/^(\d+)\.(\d+)\.(\d+)-beta/);
  if (!match) return `v${version}`;
  return match[3] === "0" ? `v${match[1]}.${match[2]} Beta` : `v${match[1]}.${match[2]}.${match[3]} Beta`;
}

