function organizationAccountRoleName(accountType) {
  return accountType === "terminal" ? "Terminalkonto" : "Filialkonto";
}

function portalActorId(session) {
  return String(session?.actorId || session?.employeeNumber || "local");
}

function parsePortalPermissionScopes(value) {
  if (Array.isArray(value)) return value;
  try {
    const parsed = JSON.parse(String(value || "[]"));
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function parseCrmPhotoMultipart(request, { maxFileBytes = MAX_CANDIDATE_PHOTO_INPUT_BYTES } = {}) {
  return new Promise((resolve, reject) => {
    const contentType = String(request.headers["content-type"] || "");
    const boundaryMatch = contentType.match(/^multipart\/form-data\s*;[\s\S]*?boundary=(?:"([^"]+)"|([^;\s]+))/i);
    const boundary = String(boundaryMatch?.[1] || boundaryMatch?.[2] || "");
    if (!boundary || boundary.length > 70 || /[\r\n]/.test(boundary)) {
      reject(httpError(415, "Bitte das Kundenfoto als Formular senden.", "CRM_PHOTO_MULTIPART_REQUIRED"));
      return;
    }
    const chunks = [];
    let totalBytes = 0;
    let settled = false;
    const fail = (error) => {
      if (settled) return;
      settled = true;
      reject(error);
    };
    request.on("data", (chunk) => {
      if (settled) return;
      totalBytes += chunk.length;
      if (totalBytes > maxFileBytes + (128 * 1024)) {
        fail(httpError(413, "Das Kundenfoto darf höchstens 10 MB groß sein.", "CRM_PHOTO_TOO_LARGE"));
        return;
      }
      chunks.push(chunk);
    });
    request.on("error", () => fail(httpError(400, "Das Kundenfoto konnte nicht gelesen werden.", "CRM_PHOTO_MULTIPART_INVALID")));
    request.on("end", () => {
      if (settled) return;
      try {
        const body = Buffer.concat(chunks);
        const delimiter = Buffer.from(`--${boundary}`, "utf8");
        const nextDelimiter = Buffer.from(`\r\n--${boundary}`, "utf8");
        let photo = null;
        let position = body.indexOf(delimiter);
        let partCount = 0;
        if (position !== 0) throw httpError(400, "Das Fotoformular ist ungültig.", "CRM_PHOTO_MULTIPART_INVALID");
        while (position >= 0) {
          position += delimiter.length;
          if (body.subarray(position, position + 2).toString("ascii") === "--") break;
          if (body.subarray(position, position + 2).toString("ascii") !== "\r\n") {
            throw httpError(400, "Das Fotoformular ist ungültig.", "CRM_PHOTO_MULTIPART_INVALID");
          }
          position += 2;
          const headerEnd = body.indexOf(Buffer.from("\r\n\r\n"), position);
          if (headerEnd < 0 || headerEnd - position > 8192) {
            throw httpError(400, "Ein Fototeil hat ungültige Kopfzeilen.", "CRM_PHOTO_MULTIPART_INVALID");
          }
          const headers = body.subarray(position, headerEnd).toString("utf8");
          const dataStart = headerEnd + 4;
          const dataEnd = body.indexOf(nextDelimiter, dataStart);
          if (dataEnd < 0) throw httpError(400, "Das Fotoformular ist unvollständig.", "CRM_PHOTO_MULTIPART_INVALID");
          const data = body.subarray(dataStart, dataEnd);
          const disposition = headers.split("\r\n").find((line) => /^content-disposition:/i.test(line)) || "";
          const name = disposition.match(/(?:^|;)\s*name="([^"]*)"/i)?.[1] || "";
          const encodedFilename = disposition.match(/(?:^|;)\s*filename\*=UTF-8''([^;]+)/i)?.[1];
          const plainFilename = disposition.match(/(?:^|;)\s*filename="([^"]*)"/i)?.[1];
          let filename = plainFilename || "";
          if (encodedFilename) { try { filename = decodeURIComponent(encodedFilename); } catch {} }
          partCount += 1;
          if (partCount > 2) throw httpError(413, "Das Fotoformular enthält zu viele Teile.", "CRM_PHOTO_TOO_MANY_PARTS");
          if (name !== "photo" || !filename) {
            throw httpError(400, "Das Fotoformular enthält ein unbekanntes Feld.", "CRM_PHOTO_MULTIPART_INVALID");
          }
          if (photo) throw httpError(413, "Bitte genau ein Kundenfoto auswählen.", "CRM_PHOTO_TOO_MANY_FILES");
          if (!data.length) throw httpError(400, "Das Kundenfoto ist leer.", "CRM_PHOTO_EMPTY");
          if (data.length > maxFileBytes) throw httpError(413, "Das Kundenfoto darf höchstens 10 MB groß sein.", "CRM_PHOTO_TOO_LARGE");
          photo = { originalName: filename, buffer: Buffer.from(data) };
          position = dataEnd + 2;
        }
        if (!photo) throw httpError(400, "Bitte ein Kundenfoto auswählen.", "CRM_PHOTO_REQUIRED");
        settled = true;
        resolve(photo);
      } catch (error) {
        fail(error.status ? error : httpError(400, "Das Fotoformular ist ungültig.", "CRM_PHOTO_MULTIPART_INVALID"));
      }
    });
  });
}

function sessionPortalAccessScopeProjection(row = {}) {
  const explicitScopes = portalAccessScopesForPrincipal({
    role: "employee",
    scopesValue: row.access_scopes,
  });
  if (Number(row.access_scope_assignment_count || 0) > 0) {
    return {
      explicitScopes,
      scopes: portalAccessScopesForPrincipal({
        role: row.role,
        scopesValue: row.access_scopes,
      }),
    };
  }
  const homeLocationActive = row.home_location_active === true
    || Number(row.home_location_active || 0) === 1;
  const preferredDepartmentActive = row.preferred_department_active === true
    || Number(row.preferred_department_active || 0) === 1;
  return {
    explicitScopes,
    scopes: portalAccessScopesForPrincipal({
      employeeNumber: row.employee_number,
      role: row.role,
      homeLocationId: homeLocationActive ? row.home_location_id : "",
      preferredDepartmentId: preferredDepartmentActive
        ? row.preferred_department_id
        : null,
      scopesValue: [],
    }),
  };
}

async function loadPortalSessionFromRequest(request, { touch = true, repository = portalAccessRepository } = {}) {
  const token = parseCookies(request)[PORTAL_SESSION_COOKIE];
  if (!token) return null;
  const currentDate = new Date();
  const now = currentDate.toISOString();
  const tokenHash = sha256(token);
  const timeoutMinutes = portalSessionTimeoutMinutes();
  const refreshedExpiresAt = new Date(currentDate.getTime() + timeoutMinutes * 60000).toISOString();
  const session = await repository.getEmployeeSessionByToken({
    tokenHash,
    now,
    businessDate: viennaTodayIso(currentDate),
  });
  if (session) {
    if (isReservedEmployeePrincipal(session.employee_number)) return null;
    if (touch) {
      await repository.touchEmployeeSession({ id: session.id, expiresAt: refreshedExpiresAt });
      session.expires_at = refreshedExpiresAt;
    }
    const { explicitScopes, scopes } = sessionPortalAccessScopeProjection(session);
    const permissionState = effectivePortalPermissionState(
      session.employee_number,
      session.role,
      session.permissions,
      session.granted_permissions,
      session.denied_permissions,
      session.amu_local_access_mode,
    );
    return {
      id: session.id,
      sessionKind: "employee",
      actorId: session.employee_number,
      isEmployee: true,
      accountId: null,
      loginName: session.employee_number,
      accountType: "employee",
      employeeNumber: session.employee_number,
      fullName: session.full_name,
      nickname: session.nickname,
      color: session.color,
      homeLocationId: session.home_location_id,
      positionId: session.position_id || null,
      positionName: session.position_name || "",
      role: session.role,
      roleName: session.role_name || session.role,
      roleLocked: Boolean(session.role_locked),
      permissions: permissionState.effectivePermissions,
      rolePermissions: permissionState.rolePermissions,
      grantedPermissions: permissionState.grantedPermissions,
      deniedPermissions: permissionState.deniedPermissions,
      explicitScopes,
      permissionScopes: parsePortalPermissionScopes(session.permission_scopes),
      scopes,
      timeConfirmationLevel: normalizeTimeConfirmationLevel(session.time_confirmation_level),
      amuLocalAccessMode: normalizedManagerAmuAccessMode(session.amu_local_access_mode),
      personnelFieldPermissions: parsePersonnelFieldPermissionProjection(session.personnel_field_permissions),
      mustChangePassword: Boolean(session.must_change_password),
      expiresAt: session.expires_at,
    };
  }
  const organizationSession = await repository
    .getOrganizationSessionByToken({ tokenHash, now });
  if (!organizationSession) return null;
  if (touch) {
    await repository.touchOrganizationSession({ id: organizationSession.id, expiresAt: refreshedExpiresAt });
    organizationSession.expires_at = refreshedExpiresAt;
  }
  const scopes = portalAccessScopesForPrincipal({
    role: "organization_account",
    scopesValue: organizationSession.access_scopes,
  });
  const permissions = normalizedOrganizationAccountPermissions(
    organizationSession.account_type,
    parsePortalPermissions(organizationSession.permissions),
  );
  return {
    id: organizationSession.id,
    sessionKind: "organization",
    actorId: `account:${organizationSession.account_id}`,
    isEmployee: false,
    accountId: organizationSession.account_id,
    loginName: organizationSession.login_name,
    accountType: organizationSession.account_type,
    employeeNumber: null,
    fullName: organizationSession.display_name,
    nickname: organizationSession.display_name,
    color: "#276e55",
    homeLocationId: scopes[0]?.locationId || "",
    positionId: null,
    positionName: "",
    role: "organization_account",
    roleName: organizationAccountRoleName(organizationSession.account_type),
    roleLocked: true,
    permissions,
    rolePermissions: [],
    grantedPermissions: permissions,
    deniedPermissions: [],
    explicitScopes: scopes,
    permissionScopes: [],
    scopes,
    mustChangePassword: false,
    expiresAt: organizationSession.expires_at,
  };
}

async function resolveSalesReportPrincipal(employeeNumber) {
  if (isReservedEmployeePrincipal(employeeNumber)) return null;
  const row = await portalAccessRepository.getReportPrincipal({ employeeNumber, businessDate: viennaTodayIso(new Date()) });
  if (!row) return null;
  const { explicitScopes, scopes } = sessionPortalAccessScopeProjection(row);
  const permissionState = effectivePortalPermissionState(row.employee_number, row.role, row.permissions,
    row.granted_permissions, row.denied_permissions, row.amu_local_access_mode);
  return { sessionKind: 'employee', isEmployee: true, employeeNumber: row.employee_number, accountId: null,
    role: row.role, homeLocationId: row.home_location_id, permissions: permissionState.effectivePermissions,
    permissionScopes: parsePortalPermissionScopes(row.permission_scopes), explicitScopes, scopes,
    mustChangePassword: Boolean(row.must_change_password) };
}

function portalSessionFromRequest(request) {
  return request?.portalSession || null;
}

