async function amuResponsibilityForReport(report) {
  if (report?.protected_payload) {
    const payload = parseProtectedJson(report.protected_payload, amuReportProtectionContext(report));
    const routing = payload.routing;
    if (routing && ["local", "hr"].includes(routing.stage)
      && Array.isArray(routing.assignedTo)) {
      return {
        stage: routing.stage,
        label: routing.stage === "local" ? "Filialleitung" : "Personalleitung",
        reason: String(routing.reason || "persisted"),
        reviewerEmployeeNumbers: routing.assignedTo.map(String).filter(Boolean),
      };
    }
  }
  return {
    stage: "hr",
    label: "Personalleitung",
    reason: "routing_pending",
    reviewerEmployeeNumbers: await requestReviewerRecipients(
      report?.location_id,
      report?.department_id,
      "hr",
      report?.employee_number,
    ),
  };
}

async function getCostCenterTypes(includeInactive = true) {
  const [typeRows, rawPositionRows] = await Promise.all([
    organizationPersonnelRepository.listCostCenterTypes(includeInactive),
    organizationPersonnelRepository.listCostCenterTypePositions(),
  ]);
  const positionRows = rawPositionRows.map(serializePosition);
  const positionsByType = new Map();
  for (const position of positionRows) {
    const typeId = String(position.cost_center_type_id);
    if (!positionsByType.has(typeId)) positionsByType.set(typeId, []);
    const { cost_center_type_id: _typeId, ...serialized } = position;
    positionsByType.get(typeId).push(serialized);
  }
  return typeRows.map((row) => serializeCostCenterType(row, positionsByType.get(String(row.id)) || []));
}

async function validateCostCenterTypeExists(value, options = {}) {
  const key = String(value || "").trim();
  if (!key) throw httpError(400, "Bitte einen Kostenstellentyp auswählen.", "COST_CENTER_TYPE_REQUIRED");
  const row = (await organizationPersonnelRepository.listCostCenterTypes(true))
    .find((entry) => String(entry.id) === key
      || String(entry.code || "").toLowerCase() === key.toLowerCase());
  if (!row) throw httpError(404, "Der Kostenstellentyp wurde nicht gefunden.", "COST_CENTER_TYPE_NOT_FOUND");
  if (!options.allowInactive && !row.active) {
    throw httpError(409, "Der Kostenstellentyp ist archiviert und kann nicht neu zugeordnet werden.", "COST_CENTER_TYPE_INACTIVE");
  }
  return row;
}

function serializeCostCenter(row) {
  return {
    id: String(row.id),
    code: String(row.code || ""),
    name: String(row.name || ""),
    type: String(row.cost_center_type_id || row.type || "other"),
    typeId: String(row.cost_center_type_id || ""),
    typeCode: String(row.cost_center_type_code || row.type || ""),
    typeName: String(row.cost_center_type_name || ""),
    isBranch: Boolean(row.cost_center_type_is_branch),
    typeActive: Boolean(row.cost_center_type_active),
    description: String(row.description || ""),
    active: Boolean(row.active),
    sortOrder: Number(row.sort_order || 0),
    employeeCount: Number(row.employee_count || 0),
    activeEmployeeCount: Number(row.active_employee_count || 0),
    locationCount: Number(row.location_count || 0),
    locationId: String(row.location_id || ""),
    locationName: String(row.location_name || ""),
    createdBy: String(row.created_by || ""),
    updatedBy: String(row.updated_by || ""),
    createdAt: row.created_at || null,
    updatedAt: row.updated_at || null,
  };
}

async function getCostCenters(includeInactive = true) {
  return (await organizationPersonnelRepository.listCostCenters(includeInactive)).map(serializeCostCenter);
}

async function validateCostCenterExists(value, options = {}) {
  const repository = options.repository || organizationPersonnelRepository;
  const id = String(value || "").trim();
  if (!id) throw httpError(400, "Bitte eine Kostenstelle auswählen.", "COST_CENTER_REQUIRED");
  const row = (await repository.listCostCenters(true))
    .find((entry) => String(entry.id) === id);
  if (!row) throw httpError(404, "Die Kostenstelle wurde nicht gefunden.", "COST_CENTER_NOT_FOUND");
  if (!options.allowInactive && !row.active) {
    throw httpError(409, "Die Kostenstelle ist archiviert und kann nicht neu zugeordnet werden.", "COST_CENTER_INACTIVE");
  }
  if (options.requireBranch && (!row.cost_center_type_active || !row.cost_center_type_is_branch)) {
    throw httpError(409, "Einem Standort kann nur eine aktive Filialkostenstelle zugeordnet werden.", "LOCATION_COST_CENTER_TYPE_REQUIRED");
  }
  return row;
}

function legacyCostCenterType(type) {
  return ["branch", "administration", "production", "other"].includes(String(type?.id || ""))
    ? String(type.id)
    : "other";
}

async function validateCostCenterPayload(body = {}, existing = null) {
  const code = String(body.code ?? existing?.code ?? "").trim().toUpperCase();
  const name = String(body.name ?? existing?.name ?? "").trim().replace(/\s+/g, " ");
  const typeKey = String(
    body.costCenterTypeId ?? body.typeId ?? body.type
      ?? existing?.cost_center_type_id ?? existing?.type ?? "other",
  ).trim();
  const selectedType = await validateCostCenterTypeExists(typeKey, {
    allowInactive: Boolean(existing && String(existing.cost_center_type_id || "") === typeKey),
  });
  const description = String(body.description ?? existing?.description ?? "").trim();
  const active = body.active === undefined
    ? Boolean(existing?.active ?? true)
    : ![false, 0, "0", "false"].includes(body.active);
  const sortOrder = Number(body.sortOrder ?? body.sort_order ?? existing?.sort_order ?? 0);
  if (!/^[A-Z0-9][A-Z0-9._-]{0,29}$/.test(code)) {
    throw httpError(400, "Der Kostenstellencode muss aus 1 bis 30 Buchstaben, Ziffern, Punkten, Strichen oder Unterstrichen bestehen.", "COST_CENTER_CODE_INVALID");
  }
  if (!name || name.length > 100) {
    throw httpError(400, "Der Name der Kostenstelle muss 1 bis 100 Zeichen lang sein.", "COST_CENTER_NAME_INVALID");
  }
  if (active && !selectedType.active) {
    throw httpError(
      409,
      "Eine aktive Kostenstelle kann keinem archivierten Kostenstellentyp zugeordnet werden.",
      "COST_CENTER_TYPE_INACTIVE",
    );
  }
  if (description.length > 500) throw httpError(400, "Die Beschreibung darf höchstens 500 Zeichen lang sein.", "COST_CENTER_DESCRIPTION_INVALID");
  if (!Number.isInteger(sortOrder) || sortOrder < 0 || sortOrder > 9999) {
    throw httpError(400, "Die Sortierung der Kostenstelle muss zwischen 0 und 9999 liegen.", "COST_CENTER_SORT_INVALID");
  }
  return {
    code,
    name,
    type: legacyCostCenterType(selectedType),
    costCenterTypeId: String(selectedType.id),
    costCenterType: selectedType,
    description,
    active: active ? 1 : 0,
    sortOrder,
  };
}

async function validateCostCenterTypePayload(body = {}, existing = null) {
  const [storedTypes, storedPositionRows, positions] = await Promise.all([
    organizationPersonnelRepository.listCostCenterTypes(true),
    organizationPersonnelRepository.listCostCenterTypePositions(),
    getPositions(),
  ]);
  const code = String(body.code ?? existing?.code ?? "")
    .trim()
    .toLowerCase();
  const name = String(body.name ?? existing?.name ?? "").trim().replace(/\s+/g, " ");
  const description = String(body.description ?? existing?.description ?? "").trim();
  const submittedIsBranch = body.isBranch ?? body.is_branch;
  const isBranch = submittedIsBranch === undefined
    ? Boolean(existing?.is_branch)
    : [true, 1, "1", "true"].includes(submittedIsBranch);
  const active = body.active === undefined
    ? Boolean(existing?.active ?? true)
    : ![false, 0, "0", "false"].includes(body.active);
  const nextSortOrder = existing?.sort_order
    ?? Math.min(9999, Math.max(0, ...storedTypes.map((type) => Number(type.sort_order || 0))) + 10);
  const sortOrder = Number(body.sortOrder ?? body.sort_order ?? nextSortOrder);
  const submittedPositionIds = body.positionIds ?? body.position_ids;
  const currentPositionIds = existing
    ? storedPositionRows
      .filter((row) => String(row.cost_center_type_id) === String(existing.id))
      .map((row) => String(row.id))
    : [];
  if (!/^[a-z0-9][a-z0-9._-]{0,39}$/.test(code)) {
    throw httpError(
      400,
      "Der Typ-Code muss aus 1 bis 40 Kleinbuchstaben, Ziffern, Punkten, Strichen oder Unterstrichen bestehen.",
      "COST_CENTER_TYPE_CODE_INVALID",
    );
  }
  if (!name || name.length > 80) {
    throw httpError(400, "Der Name des Kostenstellentyps muss 1 bis 80 Zeichen lang sein.", "COST_CENTER_TYPE_NAME_INVALID");
  }
  if (description.length > 500) {
    throw httpError(400, "Die Beschreibung darf höchstens 500 Zeichen lang sein.", "COST_CENTER_TYPE_DESCRIPTION_INVALID");
  }
  if (!Number.isInteger(sortOrder) || sortOrder < 0 || sortOrder > 9999) {
    throw httpError(400, "Die Sortierung des Kostenstellentyps muss zwischen 0 und 9999 liegen.", "COST_CENTER_TYPE_SORT_INVALID");
  }
  if (submittedPositionIds !== undefined && !Array.isArray(submittedPositionIds)) {
    throw httpError(400, "Die erlaubten Positionen müssen als Liste übermittelt werden.", "COST_CENTER_TYPE_POSITIONS_INVALID");
  }
  const positionIds = [...new Set((submittedPositionIds === undefined ? currentPositionIds : submittedPositionIds)
    .map((value) => String(value || "").trim())
    .filter(Boolean))];
  if (positionIds.length > 100) {
    throw httpError(400, "Ein Kostenstellentyp kann höchstens 100 Positionen enthalten.", "COST_CENTER_TYPE_POSITIONS_LIMIT");
  }
  if (positionIds.length) {
    const knownPositions = new Set(positions.map((row) => String(row.id)));
    const unknown = positionIds.filter((id) => !knownPositions.has(id));
    if (unknown.length) {
      throw httpError(400, "Mindestens eine ausgewählte Position wurde nicht gefunden.", "COST_CENTER_TYPE_POSITION_NOT_FOUND");
    }
  }
  return {
    code,
    name,
    description,
    isBranch: isBranch ? 1 : 0,
    active: active ? 1 : 0,
    sortOrder,
    positionIds,
  };
}

async function assertCostCenterTypeNameUnique(name, excludeId = "") {
  const duplicate = (await organizationPersonnelRepository.listCostCenterTypes(true))
    .find((type) => String(type.id) !== String(excludeId || "")
      && String(type.name || "").toLowerCase() === String(name || "").toLowerCase());
  if (duplicate) {
    throw httpError(409, "Dieser Name für einen Kostenstellentyp ist bereits vergeben.", "COST_CENTER_TYPE_NAME_DUPLICATE");
  }
}

async function assertCostCenterTypeChangeAllowed(existing, value) {
  const storedType = (await organizationPersonnelRepository.listCostCenterTypes(true))
    .find((type) => String(type.id) === String(existing.id));
  if (existing.active && !value.active && Number(storedType?.active_cost_center_count || 0)) {
    throw httpError(
      409,
      "Ein verwendeter Kostenstellentyp kann nicht archiviert werden. Bitte zuerst die aktiven Kostenstellen neu zuordnen.",
      "COST_CENTER_TYPE_IN_USE",
    );
  }
  if (existing.is_branch && !value.isBranch && Number(storedType?.location_count || 0)) {
    throw httpError(
      409,
      "Der Filialstatus kann nicht entfernt werden, solange Standorte Kostenstellen dieses Typs verwenden.",
      "COST_CENTER_TYPE_BRANCH_IN_USE",
    );
  }
  if (Array.isArray(value.positionIds)) {
    const allowedPositionIds = new Set(value.positionIds.map(String));
    const incompatibleEmployee = (await organizationPersonnelRepository.listEmployees())
      .find((employee) => String(employee.cost_center_type_id || "") === String(existing.id)
        && !allowedPositionIds.has(String(employee.position_id || "")));
    if (incompatibleEmployee) {
      throw httpError(
        409,
        `Die Position „${incompatibleEmployee.position_name}“ wird in ${incompatibleEmployee.cost_center_code} noch verwendet und kann deshalb nicht aus diesem Typ entfernt werden.`,
        "COST_CENTER_TYPE_POSITION_IN_USE",
      );
    }
  }
}

async function defaultCostCenterId(
  locationId = "",
  repository = organizationPersonnelRepository,
) {
  const [locations, costCenters] = await Promise.all([
    repository.listLocations(true),
    repository.listCostCenters(false),
  ]);
  const locationCostCenterId = locationId
    ? locations.find((location) => String(location.id) === String(locationId))?.cost_center_id
    : "";
  const locationCostCenter = costCenters.find((center) => center.id === locationCostCenterId);
  return locationCostCenter?.id
    || costCenters.find((center) => center.cost_center_type_id === "administration")?.id
    || costCenters[0]?.id
    || "";
}

async function employeeAssignmentForCostCenter(value, options = {}) {
  const center = await validateCostCenterExists(value, {
    allowInactive: Boolean(options.allowInactive),
    repository: options.repository,
  });
  if (!options.allowInactive && !center.cost_center_type_active) {
    throw httpError(
      409,
      "Die Kostenstelle verwendet einen archivierten Kostenstellentyp und kann nicht neu zugeordnet werden.",
      "COST_CENTER_TYPE_INACTIVE",
    );
  }
  const repository = options.repository || organizationPersonnelRepository;
  const location = (await repository.listLocations(true))
    .find((entry) => String(entry.cost_center_id || "") === String(center.id));
  const isBranch = Boolean(center.cost_center_type_is_branch);
  if (isBranch && !location && !options.allowUnlinkedBranch) {
    throw httpError(
      409,
      "Diese Filialkostenstelle ist noch keinem Standort zugeordnet und kann deshalb keinem Personalstamm zugewiesen werden.",
      "EMPLOYEE_COST_CENTER_LOCATION_REQUIRED",
    );
  }
  if (isBranch && location && !location.active
    && String(location.id) !== String(options.allowInactiveLocationId || "")) {
    throw httpError(
      409,
      "Der aus der Kostenstelle abgeleitete Standort ist archiviert und kann nicht neu zugeordnet werden.",
      "EMPLOYEE_LOCATION_INACTIVE",
    );
  }
  return {
    center,
    typeId: String(center.cost_center_type_id || ""),
    isBranch,
    homeLocationId: isBranch && location ? String(location.id) : null,
    homeLocationName: isBranch && location ? String(location.name || "") : "",
  };
}

async function validateEmployeePositionForAssignment(
  positionId,
  assignment,
  repository = organizationPersonnelRepository,
  options = {},
) {
  const positions = await getPositions(repository, true);
  const requestedPositionId = String(positionId || "").trim();
  const position = requestedPositionId
    ? positions.find((entry) => String(entry.id) === requestedPositionId)
    : positions.find((entry) => entry.active && entry.isDefault)
      || positions.find((entry) => entry.active);
  if (!position) {
    throw httpError(400, "Bitte eine gültige Position auswählen.", "EMPLOYEE_POSITION_INVALID");
  }
  if (!position.active) {
    if (options.allowInactive === true) return position;
    throw httpError(
      409,
      `Die Position „${position.name}“ ist archiviert und kann nicht neu zugeordnet werden.`,
      "EMPLOYEE_POSITION_INACTIVE",
    );
  }
  const allowed = position.costCenterTypeIds.includes(String(assignment.typeId));
  if (!allowed) {
    throw httpError(
      409,
      `Die Position „${position.name}“ ist für den Kostenstellentyp „${assignment.center.cost_center_type_name || assignment.typeId}“ nicht freigegeben.`,
      "EMPLOYEE_POSITION_NOT_ALLOWED_FOR_COST_CENTER",
    );
  }
  return position;
}

function sessionCanManageCentralPersonnel(session, permission = "personnel:central:write") {
  if (!getPortalStatus().portalEnabled) return true;
  return Boolean(session && RIGHTS_ADMIN_PORTAL_ROLES.has(session.role) && session.permissions?.includes(permission));
}

function serializeLocation(row, departments = []) {
  return {
    ...row,
    cost_center_id: row.cost_center_id || "",
    cost_center_code: row.cost_center_code || "",
    cost_center_name: row.cost_center_name || "",
    cost_center_type: row.cost_center_type_id || row.cost_center_type || "",
    cost_center_type_id: row.cost_center_type_id || "",
    cost_center_type_name: row.cost_center_type_name || "",
    cost_center_is_branch: Boolean(row.cost_center_is_branch),
    min_staff: Number(row.min_staff || 0),
    day_settings: daySettingsFromStoredJson(row.day_settings_json),
    time_tracking_enabled: Boolean(row.time_tracking_enabled),
    time_tracking_access_mode: row.time_tracking_access_mode === "trusted_network" ? "trusted_network" : "anywhere",
    time_tracking_allowed_networks: String(row.time_tracking_allowed_networks || ""),
    time_tracking_variance_minutes: Math.max(0, Number(row.time_tracking_variance_minutes || 0)),
    active: Boolean(row.active),
    departments,
  };
}

function serializeDepartment(row) {
  return {
    ...row,
    id: Number(row.id),
    min_staff: Number(row.min_staff || 0),
    active: Boolean(row.active),
    sort_order: Number(row.sort_order || 0),
  };
}

function serializePosition(row) {
  const costCenterTypeIds = String(row.cost_center_type_ids || "")
    .split("|")
    .map((value) => value.trim())
    .filter(Boolean);
  return {
    ...row,
    builtin: Boolean(row.builtin),
    active: Boolean(row.active),
    is_default: Boolean(row.is_default),
    isDefault: Boolean(row.is_default),
    sort_order: Number(row.sort_order || 0),
    revision: Number(row.revision || 1),
    employee_count: Number(row.employee_count || 0),
    active_employee_count: Number(row.active_employee_count || 0),
    cost_center_type_ids: costCenterTypeIds,
    costCenterTypeIds,
  };
}

async function getPositions(repository = organizationPersonnelRepository, includeInactive = false) {
  const positions = (await repository.listPositions()).map(serializePosition);
  return includeInactive ? positions : positions.filter((position) => position.active);
}

async function getLocations(includeInactive = true) {
  const [locationRows, departmentRows] = await Promise.all([
    organizationPersonnelRepository.listLocations(includeInactive),
    organizationPersonnelRepository.listDepartments(includeInactive),
  ]);
  const serializedDepartments = departmentRows.map(serializeDepartment);
  return locationRows.map((location) =>
    serializeLocation(
      location,
      serializedDepartments.filter((department) => department.location_id === location.id),
    ),
  );
}

async function getLocationsForSession(session, includeInactive = true) {
  const locations = await getLocations(includeInactive);
  const canReadTimeSettings = !session || isLocalSystemSession(session) || session.permissions?.includes("time:settings");
  const visibleLocation = (location) => canReadTimeSettings ? location : { ...location, time_tracking_allowed_networks: "" };
  if (sessionHasGlobalScope(session)) return locations.map(visibleLocation);
  const allowed = new Map();
  for (const scope of session.scopes || []) {
    const key = String(scope.locationId || "");
    if (!allowed.has(key)) allowed.set(key, { wholeLocation: false, departmentIds: new Set() });
    const entry = allowed.get(key);
    if (scope.departmentId) entry.departmentIds.add(Number(scope.departmentId));
    else entry.wholeLocation = true;
  }
  return locations.filter((location) => allowed.has(String(location.id))).map((location) => {
    const scope = allowed.get(String(location.id));
    return {
      ...visibleLocation(location),
      departments: scope.wholeLocation
        ? location.departments
        : location.departments.filter((department) => scope.departmentIds.has(Number(department.id))),
    };
  });
}

function normalizeLocationId(value) {
  const id = String(value || "").trim();
  if (!/^\d{2}$/.test(id)) {
    throw httpError(400, "Die Filial-ID muss aus genau 2 Ziffern bestehen.");
  }
  return id;
}

function normalizeDepartmentId(value, allowEmpty = true) {
  if ((value === undefined || value === null || value === "") && allowEmpty) return null;
  const id = Number(value);
  if (!Number.isInteger(id) || id <= 0) {
    throw httpError(400, "Die Abteilung ist ungültig.");
  }
  return id;
}

async function validateLocationExists(locationId, repository = organizationPersonnelRepository) {
  const location = (await repository.listLocations(true))
    .find((entry) => String(entry.id) === String(locationId));
  if (!location) throw httpError(404, "Die Filiale wurde nicht gefunden.");
  return location;
}

async function validateActiveLocationExists(locationId, repository = organizationPersonnelRepository) {
  const location = await validateLocationExists(locationId, repository);
  if (!location.active) {
    throw httpError(
      409,
      "Berechtigungsbereiche duerfen nur auf aktive Filialen verweisen.",
      "PORTAL_SCOPE_LOCATION_INACTIVE",
    );
  }
  return location;
}

function normalizeTimeTrackingNetworks(value) {
  const entries = [...new Set((Array.isArray(value) ? value : String(value || "").split(/[\s,;]+/))
    .map((entry) => String(entry || "").trim().toLowerCase())
    .filter(Boolean))];
  if (entries.length > 20) throw httpError(400, "Es können höchstens 20 vertrauenswürdige IP-Adressen oder Netze hinterlegt werden.");
  for (const entry of entries) {
    const [address, prefix, ...remainder] = entry.split("/");
    const version = net.isIP(address);
    if (!version || remainder.length || (prefix !== undefined && (
      !/^\d+$/.test(prefix) || Number(prefix) < 0 || Number(prefix) > (version === 4 ? 32 : 128)
    ))) {
      throw httpError(400, `Die Netzwerkangabe „${entry}“ ist ungültig.`);
    }
  }
  return entries.join("\n");
}

async function validateDepartmentExists(
  departmentId,
  locationId = null,
  repository = organizationPersonnelRepository,
) {
  if (!departmentId) return null;
  const department = (await repository.listDepartments(true))
    .find((entry) => Number(entry.id) === Number(departmentId));
  if (!department) throw httpError(404, "Die Abteilung wurde nicht gefunden.");
  if (locationId && department.location_id !== locationId) {
    throw httpError(400, "Die Abteilung gehört nicht zur ausgewählten Filiale.");
  }
  return department;
}

async function validateActiveDepartmentExists(
  departmentId,
  locationId = null,
  repository = organizationPersonnelRepository,
) {
  const department = await validateDepartmentExists(departmentId, locationId, repository);
  if (department && !department.active) {
    throw httpError(
      409,
      "Berechtigungsbereiche duerfen nur auf aktive Abteilungen verweisen.",
      "PORTAL_SCOPE_DEPARTMENT_INACTIVE",
    );
  }
  return department;
}

async function validateLocationPayload(body, isNew = false) {
  const id = normalizeLocationId(body.id || body.locationId);
  const name = String(body.name || "").trim();
  const minStaff = Number(body.minStaff ?? body.min_staff ?? 0);
  if (!name) throw httpError(400, "Bitte einen Namen für die Filiale eingeben.");
  if (name.length > 80) throw httpError(400, "Der Filialname darf maximal 80 Zeichen lang sein.");
  if (!Number.isInteger(minStaff) || minStaff < 0 || minStaff > 99) {
    throw httpError(400, "Die Mindestbesetzung der Filiale muss zwischen 0 und 99 liegen.");
  }
  if (!isNew) await validateLocationExists(id);
  const daySettings = validateDaySettings(body.daySettings
    || (isNew ? legacyDaySettingsSnapshot() : await daySettingsFromLocation(id)));
  const timeTrackingAccessMode = body.timeTrackingAccessMode === "trusted_network" || body.time_tracking_access_mode === "trusted_network"
    ? "trusted_network"
    : "anywhere";
  const timeTrackingVarianceMinutes = Number(body.timeTrackingVarianceMinutes ?? body.time_tracking_variance_minutes ?? 15);
  if (!Number.isInteger(timeTrackingVarianceMinutes) || timeTrackingVarianceMinutes < 0 || timeTrackingVarianceMinutes > 240) {
    throw httpError(400, "Die Toleranz der Zeiterfassung muss zwischen 0 und 240 Minuten liegen.");
  }
  const costCenterSubmitted = own(body, "costCenterId") || own(body, "cost_center_id");
  const costCenterId = costCenterSubmitted ? String(body.costCenterId ?? body.cost_center_id ?? "").trim() : "";
  if (costCenterSubmitted) {
    await validateCostCenterExists(costCenterId, { requireBranch: true });
    const usedBy = (await organizationPersonnelRepository.listLocations(true))
      .find((location) => String(location.cost_center_id || "") === costCenterId
        && String(location.id) !== (isNew ? "" : id));
    if (usedBy) {
      throw httpError(
        409,
        `Diese Filialkostenstelle ist bereits dem Standort ${usedBy.id} zugeordnet.`,
        "LOCATION_COST_CENTER_IN_USE",
      );
    }
  }
  return {
    id,
    name,
    minStaff,
    daySettings,
    timeTrackingEnabled: body.timeTrackingEnabled === true || body.time_tracking_enabled === true ? 1 : 0,
    timeTrackingAccessMode,
    timeTrackingAllowedNetworks: normalizeTimeTrackingNetworks(body.timeTrackingAllowedNetworks ?? body.time_tracking_allowed_networks),
    timeTrackingVarianceMinutes,
    costCenterSubmitted,
    costCenterId,
    active: body.active === false || body.active === 0 ? 0 : 1,
  };
}

function validateDaySettings(submittedDays = {}) {
  const result = {};
  for (const [day] of planningDays) {
    const submitted = submittedDays[day] || {};
    const open = submitted.open !== false;
    const start = String(submitted.start || "");
    const end = String(submitted.end || "");
    const lunchEnabled = submitted.lunchEnabled === true;
    const lunchStart = String(submitted.lunchStart || "13:00");
    const lunchEnd = String(submitted.lunchEnd || "14:00");
    const minStaff = Number(submitted.minStaff || 0);
    const minFrom = String(submitted.minFrom || start);
    const minTo = String(submitted.minTo || end);
    if (![start, end, lunchStart, lunchEnd, minFrom, minTo].every(isTime)) throw httpError(400, `Bitte gültige Zeiten für ${day} eingeben.`);
    if (open && end <= start) throw httpError(400, `Das Dienstende für ${day} muss nach dem Beginn liegen.`);
    if (lunchEnabled && (lunchEnd <= lunchStart || lunchStart < start || lunchEnd > end)) throw httpError(400, `Die Mittagspause für ${day} muss innerhalb der Dienstzeit liegen.`);
    if (!Number.isInteger(minStaff) || minStaff < 0 || minStaff > 99) throw httpError(400, `Die Mindestbesetzung für ${day} ist ungültig.`);
    if (open && (minTo <= minFrom || minFrom < start || minTo > end)) throw httpError(400, `Der Zeitraum der Mindestbesetzung für ${day} muss innerhalb der Dienstzeit liegen.`);
    result[day] = { open, start, end, lunchEnabled, lunchStart, lunchEnd, minStaff, minFrom, minTo };
  }
  return result;
}

async function validateDepartmentPayload(body, existingId = null) {
  const locationId = normalizeLocationId(body.locationId || body.location_id);
  await validateLocationExists(locationId);
  const name = String(body.name || "").trim();
  const minStaff = Number(body.minStaff ?? body.min_staff ?? 0);
  if (!name) throw httpError(400, "Bitte einen Namen für die Abteilung eingeben.");
  if (name.length > 80) throw httpError(400, "Der Abteilungsname darf maximal 80 Zeichen lang sein.");
  if (!Number.isInteger(minStaff) || minStaff < 0 || minStaff > 99) {
    throw httpError(400, "Die Mindestbesetzung der Abteilung muss zwischen 0 und 99 liegen.");
  }
  const active = body.active === false ? 0 : 1;
  const departmentCount = (await organizationPersonnelRepository.listDepartments(true))
    .filter((department) => department.location_id === locationId
      && Number(department.id) !== Number(existingId || 0)).length;
  if (departmentCount >= 3) {
    throw httpError(400, "Pro Filiale können maximal 3 Abteilungen angelegt werden.");
  }
  return { locationId, name, minStaff, active };
}

async function resolvePlanningContext(input = {}) {
  (await ensureDefaultLocation());
  const locations = await organizationPersonnelRepository.listLocations(true);
  const activeLocations = locations.filter((location) => location.active);
  const fallbackLocation = activeLocations[0] || locations[0];
  let locationId = String(input.locationId || input.location || "").trim();
  if (!locationId) locationId = fallbackLocation?.id || "01";
  locationId = normalizeLocationId(locationId);
  const location = await validateLocationExists(locationId);
  let departmentId = normalizeDepartmentId(input.departmentId ?? input.department, true);
  const department = await validateDepartmentExists(departmentId, locationId);
  return {
    locationId,
    locationName: location.name,
    departmentId,
    departmentName: department?.name || "",
  };
}

async function staffingFloorForContext(context = {}) {
  if (!context.locationId) return 0;
  const [locations, departments] = await Promise.all([
    organizationPersonnelRepository.listLocations(true),
    organizationPersonnelRepository.listDepartments(true),
  ]);
  const location = locations.find((entry) => String(entry.id) === String(context.locationId));
  const locationMinimum = Number(location?.min_staff || 0);
  if (context.departmentId) {
    const department = departments.find((entry) => Number(entry.id) === Number(context.departmentId));
    return Math.max(locationMinimum, Number(department?.min_staff || 0));
  }
  const departmentSum = departments
    .filter((entry) => String(entry.location_id) === String(context.locationId) && entry.active)
    .reduce((sum, entry) => sum + Number(entry.min_staff || 0), 0);
  return Math.max(locationMinimum, Number(departmentSum || 0));
}

function pdfDepartmentKey(context = {}) {
  return context.departmentId ? String(context.departmentId) : "";
}

const SCHEDULE_MATRIX_TIME_FONT_SIZES = Object.freeze(["6", "8.5", "11", "14.5", "18"]);
const SCHEDULE_MATRIX_DETAIL_FONT_SIZES = Object.freeze(["6", "8", "9.5"]);

function normalizeScheduleMatrixFontSize(value, allowed, fallback, { strict = false } = {}) {
  const normalized = String(value ?? "").trim().replace(",", ".");
  if (allowed.includes(normalized)) return normalized;
  if (strict) {
    throw httpError(400, "Die gewählte Schriftgröße für die Wochenmatrix ist ungültig.", "SCHEDULE_MATRIX_FONT_SIZE_INVALID");
  }
  return fallback;
}

function normalizeScheduleMatrixHeaderText(value, { strict = false } = {}) {
  const normalized = String(value ?? "").trim();
  if (normalized.length <= 200 && !/[\x00-\x1F\x7F]/.test(normalized)) return normalized;
  if (strict) {
    throw httpError(400, "Der Kopftext der Wochenmatrix muss einzeilig sein und darf höchstens 200 Zeichen enthalten.", "SCHEDULE_MATRIX_HEADER_TEXT_INVALID");
  }
  return "Design 2";
}

function defaultSchedulePdfSettings(context = {}) {
  const titleParts = [`${context.departmentName ? "Abteilungsplan" : "Dienstplan"} ${context.locationName || "Hauptstandort"}`];
  if (context.departmentName) titleParts.push(context.departmentName);
  const title = titleParts.join(" · ");
  return {
    pdf_title: title,
    pdf_filename_prefix: title,
    pdf_filename_include_kw: "1",
    pdf_filename_include_timestamp: "0",
    pdf_schedule_designs: JSON.stringify(DEFAULT_SCHEDULE_PDF_DESIGN_IDS),
    pdf_schedule_design_names: "{}",
    pdf_schedule_matrix_time_font_size: "14.5",
    pdf_schedule_matrix_time_font_bold: "0",
    pdf_schedule_matrix_time_employee_color: "0",
    pdf_schedule_matrix_show_position: "1",
    pdf_schedule_matrix_show_duty_label: "0",
    pdf_schedule_matrix_detail_font_size: "6",
    pdf_schedule_matrix_header_text: "Design 2",
  };
}

function defaultVacationPdfSettings(context = {}) {
  const title = `Urlaubsplanung ${context.locationName || "Hauptstandort"}`;
  return {
    vacation_pdf_title: title,
    vacation_pdf_filename_prefix: title,
    vacation_pdf_filename_include_period: "1",
    vacation_pdf_filename_include_timestamp: "0",
    vacation_pdf_show_balance: "1",
    vacation_pdf_balance_show_entitlement: "1",
    vacation_pdf_balance_show_planned: "1",
    vacation_pdf_balance_show_consumed: "0",
    vacation_pdf_calendar_style: "bars",
  };
}

function getScopedPdfSettings(scopeType, context) {
  const departmentKey = scopeType === "schedule" ? pdfDepartmentKey(context) : "";
  const rows = planningSettingsReadModel.pdfSettings.filter((row) => (
    row.scope_type === scopeType
    && String(row.location_id) === String(context.locationId)
    && String(row.department_key || "") === departmentKey
  ));
  return Object.fromEntries(rows.map((row) => [row.key, row.value]));
}

function applyScopedPdfSettings(settings, context, scopeType) {
  const defaults = scopeType === "vacation"
    ? defaultVacationPdfSettings(context)
    : defaultSchedulePdfSettings(context);
  const scopedSettings = {
    ...settings,
    ...defaults,
    ...getScopedPdfSettings(scopeType, context),
  };
  if (scopeType !== "schedule") return scopedSettings;
  const designIds = normalizeSchedulePdfDesignIds(scopedSettings.pdf_schedule_designs);
  const designNames = normalizeSchedulePdfDesignNames(scopedSettings.pdf_schedule_design_names);
  return {
    ...scopedSettings,
    pdf_schedule_designs: JSON.stringify(designIds),
    pdf_schedule_design_names: JSON.stringify(designNames),
    pdf_schedule_matrix_time_font_size: normalizeScheduleMatrixFontSize(
      scopedSettings.pdf_schedule_matrix_time_font_size,
      SCHEDULE_MATRIX_TIME_FONT_SIZES,
      "14.5",
    ),
    pdf_schedule_matrix_time_font_bold: scopedSettings.pdf_schedule_matrix_time_font_bold === "1" ? "1" : "0",
    pdf_schedule_matrix_time_employee_color: scopedSettings.pdf_schedule_matrix_time_employee_color === "1" ? "1" : "0",
    pdf_schedule_matrix_show_position: scopedSettings.pdf_schedule_matrix_show_position === "0" ? "0" : "1",
    pdf_schedule_matrix_show_duty_label: scopedSettings.pdf_schedule_matrix_show_duty_label === "1" ? "1" : "0",
    pdf_schedule_matrix_detail_font_size: normalizeScheduleMatrixFontSize(
      scopedSettings.pdf_schedule_matrix_detail_font_size,
      SCHEDULE_MATRIX_DETAIL_FONT_SIZES,
      "6",
    ),
    pdf_schedule_matrix_header_text: normalizeScheduleMatrixHeaderText(scopedSettings.pdf_schedule_matrix_header_text),
    pdf_schedule_design_ids: designIds,
    schedule_pdf_design_catalog: schedulePdfDesignCatalogPayload(designNames),
  };
}

async function saveScopedPdfSettings(
  scopeType,
  context,
  values,
  repository = planningSettingsRepository,
) {
  const departmentKey = scopeType === "schedule" ? pdfDepartmentKey(context) : "";
  for (const [key, value] of Object.entries(values)) {
    await repository.upsertPdfSetting({
      scopeType,
      locationId: context.locationId,
      departmentKey,
      key,
      value: String(value),
    });
  }
  if (repository === planningSettingsRepository) await refreshPlanningSettingsReadModel();
}

function validatePdfText(value, fieldName, { min = 1, max = 80 } = {}) {
  const text = String(value || "").trim();
  if (!text) throw httpError(400, `Bitte ${fieldName} eingeben.`);
  if (text.length < min || text.length > max) {
    throw httpError(400, `${fieldName} muss zwischen ${min} und ${max} Zeichen lang sein.`);
  }
  return text;
}

const SCHEDULE_PDF_SCOPED_SETTING_KEYS = Object.freeze([
  "pdf_title",
  "pdf_filename_prefix",
  "pdf_filename_include_kw",
  "pdf_filename_include_timestamp",
  "pdf_schedule_designs",
  "pdf_schedule_design_names",
  "pdf_schedule_matrix_time_font_size",
  "pdf_schedule_matrix_time_font_bold",
  "pdf_schedule_matrix_time_employee_color",
  "pdf_schedule_matrix_show_position",
  "pdf_schedule_matrix_show_duty_label",
  "pdf_schedule_matrix_detail_font_size",
  "pdf_schedule_matrix_header_text",
]);

function schedulePdfScopedSettingsPayload(settings = {}) {
  return {
    ...Object.fromEntries(SCHEDULE_PDF_SCOPED_SETTING_KEYS.map((key) => [key, settings[key]])),
    pdf_schedule_design_ids: [...(settings.pdf_schedule_design_ids || [])],
    schedule_pdf_design_catalog: [...(settings.schedule_pdf_design_catalog || [])],
  };
}

function validateBrandText(value, fallback, max = 100) {
  const text = String(value ?? "").replace(/[\x00-\x1F]/g, " ").replace(/\s+/g, " ").trim();
  return text.slice(0, max) || fallback;
}

function validateBrandOptionalText(value, max = 120) {
  return String(value ?? "").replace(/[\x00-\x1F]/g, " ").replace(/\s+/g, " ").trim().slice(0, max);
}

function validateBrandLogoUrl(value, fallback = defaultBranding.logo_url) {
  const text = validateBrandOptionalText(value, 300) || fallback;
  if (/^javascript:/i.test(text)) throw httpError(400, "Die Logo-Adresse ist ungültig.");
  return text;
}

function validateBrandEmail(value) {
  const text = validateBrandOptionalText(value, 180);
  if (text && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(text)) throw httpError(400, "Bitte eine gültige Admin-E-Mail eingeben oder leer lassen.");
  return text;
}

function brandingValuesFromBody(body = {}) {
  return {
    branding_company_name: validateBrandOptionalText(body.companyName ?? body.brandingCompanyName ?? body.branding_company_name, 100),
    branding_logo_url: validateBrandLogoUrl(body.logoUrl ?? body.brandingLogoUrl ?? body.branding_logo_url),
    branding_icon_url: validateBrandLogoUrl(body.iconUrl ?? body.brandingIconUrl ?? body.branding_icon_url, defaultBranding.icon_url),
    branding_logo_alt: validateBrandText(body.logoAlt ?? body.brandingLogoAlt ?? body.branding_logo_alt, defaultBranding.logo_alt, 120),
    branding_admin_email: validateBrandEmail(body.adminEmail ?? body.brandingAdminEmail ?? body.branding_admin_email),
  };
}

function brandingKitFromSettings(settings = getSettings()) {
  const branding = brandingFromSettings(settings);
  return {
    format: "grabenplaner-branding-kit",
    version: 1,
    exportedAt: new Date().toISOString(),
    branding,
    pdf: {
      scheduleTitle: settings.pdf_title || defaultSettings.pdf_title,
      scheduleFilenamePrefix: settings.pdf_filename_prefix || defaultSettings.pdf_filename_prefix,
      vacationTitle: settings.vacation_pdf_title || defaultSettings.vacation_pdf_title,
      vacationFilenamePrefix: settings.vacation_pdf_filename_prefix || defaultSettings.vacation_pdf_filename_prefix,
    },
  };
}

function runPowerShell(command, args = []) {
  const invocation = `${String(command || "").trim()}${args.length ? ` ${args.map((value) => `'${String(value ?? "").replaceAll("'", "''")}'`).join(" ")}` : ""}`;
  return childProcess.execFileSync(
    "powershell.exe",
    ["-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", invocation],
    { stdio: "pipe", windowsHide: true },
  );
}

function createZipArchive(sourcePath, zipPath) {
  runPowerShell(
    "& { param($sourcePath, $zipPath) $ErrorActionPreference = 'Stop'; Compress-Archive -LiteralPath $sourcePath -DestinationPath $zipPath -Force }",
    [sourcePath, zipPath],
  );
}

function inspectZipArchive(zipPath, {
  maximumEntries = 300,
  maximumUncompressedBytes = 75 * 1024 * 1024,
  maximumEntryBytes = 20 * 1024 * 1024,
  maximumPathLength = 240,
  maximumPathDepth = 12,
  maximumSegmentLength = 100,
} = {}) {
  const output = runPowerShell(`
& {
  param($zipPath)
  $ErrorActionPreference = 'Stop'
  Add-Type -AssemblyName System.IO.Compression.FileSystem
  $archive = [System.IO.Compression.ZipFile]::OpenRead($zipPath)
  try {
    $count = 0
    [Int64]$total = 0
    [Int64]$largest = 0
    $unsafe = $false
    $unsafeName = $false
    foreach ($entry in $archive.Entries) {
      $count += 1
      [Int64]$length = $entry.Length
      $total += $length
      if ($length -gt $largest) { $largest = $length }
      $name = ([string]$entry.FullName).Replace('\\', '/')
      if ([System.IO.Path]::IsPathRooted($name) -or $name -match '^[A-Za-z]:' -or @($name.Split('/') | Where-Object { $_ -eq '..' }).Count -gt 0) { $unsafe = $true }
      $segments = @($name.Split('/') | Where-Object { $_ -ne '' })
      if ($name.Length -gt ${Number(maximumPathLength)} -or $segments.Count -gt ${Number(maximumPathDepth)} -or @($segments | Where-Object { $_.Length -gt ${Number(maximumSegmentLength)} -or $_ -match ':' }).Count -gt 0) { $unsafeName = $true }
    }
    [PSCustomObject]@{ entries = $count; totalBytes = $total; largestBytes = $largest; unsafePath = $unsafe; unsafeName = $unsafeName } | ConvertTo-Json -Compress
  } finally {
    $archive.Dispose()
  }
}
`, [zipPath]).toString("utf8").replace(/^\uFEFF/, "").trim();
  let inspection;
  try { inspection = JSON.parse(output); }
  catch { throw httpError(400, "Die Branding-ZIP-Datei konnte nicht sicher geprüft werden.", "BRANDING_ARCHIVE_INVALID"); }
  if (inspection.unsafePath || inspection.unsafeName || Number(inspection.entries) > maximumEntries
    || Number(inspection.totalBytes) > maximumUncompressedBytes
    || Number(inspection.largestBytes) > maximumEntryBytes) {
    throw httpError(400, "Die Branding-ZIP-Datei ist zu groß oder enthält unzulässige Pfade.", "BRANDING_ARCHIVE_LIMIT");
  }
  return inspection;
}

function validateExtractedBrandingArchive(extractPath, limits = {}) {
  const maximumEntries = Number(limits.maximumEntries || 300);
  const maximumUncompressedBytes = Number(limits.maximumUncompressedBytes || 75 * 1024 * 1024);
  const maximumPathLength = Number(limits.maximumPathLength || 240);
  const maximumPathDepth = Number(limits.maximumPathDepth || 12);
  const maximumSegmentLength = Number(limits.maximumSegmentLength || 100);
  let entries = 0;
  let totalBytes = 0;
  const walk = (directory) => {
    for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
      entries += 1;
      if (entries > maximumEntries) throw httpError(400, "Die Branding-ZIP-Datei enthält zu viele Dateien.", "BRANDING_ARCHIVE_LIMIT");
      const entryPath = path.join(directory, entry.name);
      const relativePath = path.relative(extractPath, entryPath);
      const segments = relativePath.split(path.sep).filter(Boolean);
      if (relativePath.length > maximumPathLength || segments.length > maximumPathDepth
        || segments.some((segment) => segment.length > maximumSegmentLength || segment.includes(":"))) {
        throw httpError(400, "Die Branding-ZIP-Datei enthält unzulässig lange oder tiefe Pfade.", "BRANDING_ARCHIVE_LIMIT");
      }
      const stat = fs.lstatSync(entryPath);
      if (stat.isSymbolicLink()) throw httpError(400, "Verknüpfungen sind in Branding-Kits nicht erlaubt.", "BRANDING_ARCHIVE_LINK");
      if (stat.isDirectory()) walk(entryPath);
      else if (stat.isFile()) {
        totalBytes += stat.size;
        if (totalBytes > maximumUncompressedBytes) throw httpError(400, "Die Branding-ZIP-Datei ist entpackt zu groß.", "BRANDING_ARCHIVE_LIMIT");
      }
    }
  };
  walk(extractPath);
}

function extractZipArchive(zipPath, extractPath) {
  const limits = {
    maximumEntries: 300,
    maximumUncompressedBytes: 75 * 1024 * 1024,
    maximumEntryBytes: 20 * 1024 * 1024,
    maximumPathLength: 240,
    maximumPathDepth: 12,
    maximumSegmentLength: 100,
  };
  inspectZipArchive(zipPath, limits);
  runPowerShell(
    "& { param($zipPath, $extractPath) $ErrorActionPreference = 'Stop'; Expand-Archive -LiteralPath $zipPath -DestinationPath $extractPath -Force }",
    [zipPath, extractPath],
  );
  validateExtractedBrandingArchive(extractPath, limits);
}

function walkFiles(directory) {
  const result = [];
  if (!fs.existsSync(directory)) return result;
  for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
    const entryPath = path.join(directory, entry.name);
    if (entry.isDirectory()) result.push(...walkFiles(entryPath));
    if (entry.isFile()) result.push(entryPath);
  }
  return result;
}

function safeBrandingAssetFilename(fileName) {
  const extension = path.extname(String(fileName || "")).toLowerCase();
  if (![".svg", ".png", ".jpg", ".jpeg", ".webp", ".ico"].includes(extension)) {
    throw httpError(400, "Das Branding-Logo muss eine Bilddatei sein.");
  }
  const base = path.basename(String(fileName || "branding-logo"), extension)
    .replace(/[^a-z0-9_-]+/gi, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 48) || "branding-logo";
  return `${base}${extension}`;
}

function findKitJsonFile(extractPath) {
  const files = walkFiles(extractPath);
  return files.find((file) => path.basename(file).toLowerCase() === "branding-kit.json")
    || files.find((file) => path.basename(file).toLowerCase() === "grabenplaner-branding-kit.json")
    || files.find((file) => path.extname(file).toLowerCase() === ".json");
}

function findBrandingAssetFile(extractPath, kit) {
  const files = walkFiles(extractPath);
  const candidates = [
    kit.assets?.logo,
    kit.logoAsset,
    kit.branding?.logoAsset,
    kit.branding?.logoFile,
    kit.branding?.logoUrl,
  ].filter(Boolean).map((value) => String(value).replace(/\\/g, "/"));
  for (const candidate of candidates) {
    const baseName = path.basename(candidate);
    if (!baseName || /^https?:/i.test(candidate)) continue;
    const found = files.find((file) => path.basename(file).toLowerCase() === baseName.toLowerCase());
    if (found) return found;
  }
  return files.find((file) => ["assets", "logo"].some((part) => file.toLowerCase().includes(part))
    && [".svg", ".png", ".jpg", ".jpeg", ".webp", ".ico"].includes(path.extname(file).toLowerCase()));
}

function findBrandingIconFile(extractPath, kit) {
  const files = walkFiles(extractPath);
  const candidates = [
    kit.assets?.icon,
    kit.assets?.favicon,
    kit.assets?.webicon,
    kit.iconAsset,
    kit.branding?.iconAsset,
    kit.branding?.iconFile,
    kit.branding?.iconUrl,
  ].filter(Boolean).map((value) => String(value).replace(/\\/g, "/"));
  for (const candidate of candidates) {
    const baseName = path.basename(candidate);
    if (!baseName || /^https?:/i.test(candidate)) continue;
    const found = files.find((file) => path.basename(file).toLowerCase() === baseName.toLowerCase());
    if (found) return found;
  }
  return files.find((file) => ["webicon", "favicon", "icon"].some((part) => path.basename(file).toLowerCase().includes(part))
    && [".svg", ".png", ".jpg", ".jpeg", ".webp", ".ico"].includes(path.extname(file).toLowerCase()));
}

function importBrandingAssetFromZip(extractPath, kit, brandingValues) {
  const assetFile = findBrandingAssetFile(extractPath, kit);
  if (!assetFile) return brandingValues;
  const targetDirectory = path.join(__dirname, "public", "assets", "branding");
  fs.mkdirSync(targetDirectory, { recursive: true });
  const safeName = safeBrandingAssetFilename(path.basename(assetFile));
  const targetPath = path.join(targetDirectory, safeName);
  fs.copyFileSync(assetFile, targetPath);
  return {
    ...brandingValues,
    branding_logo_url: `/assets/branding/${safeName}`,
  };
}

async function applyBrandingKit(
  kit,
  contextInput = {},
  actor = "",
  {
    manageTransaction = true,
    repository = planningSettingsRepository,
    resolvedScheduleContext = null,
    resolvedVacationContext = null,
  } = {},
) {
  const brandingSource = kit.branding || kit;
  const pdfSource = kit.pdf || {};
  const brandingValues = brandingValuesFromBody(brandingSource);
  const scheduleContext = resolvedScheduleContext || await resolvePlanningContext(contextInput);
  const vacationContext = resolvedVacationContext
    || await resolvePlanningContext({ ...contextInput, departmentId: null, department: null });
  const scheduleTitle = pdfSource.scheduleTitle ? validatePdfText(pdfSource.scheduleTitle, "den Dienstplan-PDF-Titel") : null;
  const schedulePrefix = pdfSource.scheduleFilenamePrefix ? validatePdfText(pdfSource.scheduleFilenamePrefix, "der Dienstplan-PDF-Dateiname", { min: 5, max: 80 }) : null;
  const vacationTitle = pdfSource.vacationTitle ? validatePdfText(pdfSource.vacationTitle, "den Urlaubsplaner-PDF-Titel") : null;
  const vacationPrefix = pdfSource.vacationFilenamePrefix ? validatePdfText(pdfSource.vacationFilenamePrefix, "der Urlaubsplaner-PDF-Dateiname", { min: 5, max: 80 }) : null;
  const persist = async (boundRepository) => {
    await saveLocationBrandingSnapshot(
      scheduleContext.locationId,
      kit.id || "custom",
      brandingValues,
      actor,
      boundRepository,
    );
    const scheduleValues = {};
    if (scheduleTitle) {
      scheduleValues.pdf_title = scheduleTitle;
    }
    if (schedulePrefix) {
      scheduleValues.pdf_filename_prefix = schedulePrefix;
    }
    const vacationValues = {};
    if (vacationTitle) {
      vacationValues.vacation_pdf_title = vacationTitle;
    }
    if (vacationPrefix) {
      vacationValues.vacation_pdf_filename_prefix = vacationPrefix;
    }
    if (Object.keys(scheduleValues).length) {
      await saveScopedPdfSettings("schedule", scheduleContext, scheduleValues, boundRepository);
    }
    if (Object.keys(vacationValues).length) {
      await saveScopedPdfSettings("vacation", vacationContext, vacationValues, boundRepository);
    }
  };
  if (manageTransaction) await planningSettingsRepository.transaction(persist);
  else await persist(repository);
  if (!manageTransaction) {
    return {
      ok: true,
      settings: null,
      branding: brandingFromSettings(brandingValues),
      locationId: scheduleContext.locationId,
    };
  }
  await refreshPlanningSettingsReadModel();
  const settings = await settingsForLocation(scheduleContext.locationId);
  return { ok: true, settings, branding: brandingFromSettings(settings), locationId: scheduleContext.locationId };
}

async function brandingKitForExport(requestQuery) {
  const scheduleContext = await resolvePlanningContext(requestQuery);
  const vacationContext = await resolvePlanningContext({ ...requestQuery, departmentId: null, department: null });
  const baseSettings = await settingsForLocation(scheduleContext.locationId);
  const scheduleSettings = applyScopedPdfSettings(baseSettings, scheduleContext, "schedule");
  const vacationSettings = applyScopedPdfSettings(baseSettings, vacationContext, "vacation");
  return brandingKitFromSettings({
    ...baseSettings,
    pdf_title: scheduleSettings.pdf_title,
    pdf_filename_prefix: scheduleSettings.pdf_filename_prefix,
    vacation_pdf_title: vacationSettings.vacation_pdf_title,
    vacation_pdf_filename_prefix: vacationSettings.vacation_pdf_filename_prefix,
  });
}

function localAssetPathFromUrl(logoUrl) {
  const text = String(logoUrl || "");
  if (text.startsWith("/branding-kits/") && !text.includes("..")) {
    const assetPath = path.join(dataDirectory, ...text.split("/").filter(Boolean).slice(1));
    const normalizedAssetPath = path.resolve(assetPath);
    if (!normalizedAssetPath.startsWith(path.resolve(brandingKitsDirectory))) return null;
    return fs.existsSync(normalizedAssetPath) ? normalizedAssetPath : null;
  }
  if (!text.startsWith("/assets/") || text.includes("..")) return null;
  const assetPath = path.join(__dirname, "public", ...text.split("/").filter(Boolean));
  const normalizedAssetsRoot = path.join(__dirname, "public", "assets");
  const normalizedAssetPath = path.resolve(assetPath);
  if (!normalizedAssetPath.startsWith(path.resolve(normalizedAssetsRoot))) return null;
  return fs.existsSync(normalizedAssetPath) ? normalizedAssetPath : null;
}

function writeBrandingKitZip(kit, zipPath) {
  const tempRoot = fs.mkdtempSync(path.join(os.tmpdir(), "grabenplaner-branding-export-"));
  const kitRoot = path.join(tempRoot, "grabenplaner-branding-kit");
  const assetsRoot = path.join(kitRoot, "assets");
  fs.mkdirSync(assetsRoot, { recursive: true });
  const logoPath = localAssetPathFromUrl(kit.branding?.logoUrl);
  if (logoPath) {
    const safeName = safeBrandingAssetFilename(path.basename(logoPath));
    fs.copyFileSync(logoPath, path.join(assetsRoot, safeName));
    kit.assets = { ...(kit.assets || {}), logo: `assets/${safeName}` };
    kit.branding.logoUrl = `/assets/branding/${safeName}`;
  }
  const iconPath = localAssetPathFromUrl(kit.branding?.iconUrl);
  if (iconPath) {
    const safeName = safeBrandingAssetFilename(path.basename(iconPath));
    fs.copyFileSync(iconPath, path.join(assetsRoot, safeName));
    kit.assets = { ...(kit.assets || {}), icon: `assets/${safeName}` };
    kit.branding.iconUrl = `/assets/branding/${safeName}`;
  }
  fs.writeFileSync(path.join(kitRoot, "branding-kit.json"), JSON.stringify(kit, null, 2), "utf8");
  createZipArchive(kitRoot, zipPath);
  return tempRoot;
}

function slugifyKitPart(value, fallback = "branding-kit") {
  return String(value || fallback)
    .normalize("NFKD")
    .replace(/[^\w\s-]/g, "")
    .trim()
    .replace(/\s+/g, "-")
    .replace(/_+/g, "-")
    .replace(/-+/g, "-")
    .toLowerCase()
    .slice(0, 48) || fallback;
}

function brandingKitName(kit = {}) {
  return String(kit.name || kit.branding?.companyName || kit.branding?.company_name || kit.branding?.logoAlt || "Branding-Kit").trim() || "Branding-Kit";
}

function copyKitAssetToLibrary(assetFile, kitDirectory, kitId) {
  if (!assetFile) return "";
  const assetsDirectory = path.join(kitDirectory, "assets");
  fs.mkdirSync(assetsDirectory, { recursive: true });
  const safeName = safeBrandingAssetFilename(path.basename(assetFile));
  fs.copyFileSync(assetFile, path.join(assetsDirectory, safeName));
  return `/branding-kits/${encodeURIComponent(kitId)}/assets/${encodeURIComponent(safeName)}`;
}

function installBrandingKit(kit, { extractPath = "", fileName = "" } = {}) {
  const sourceName = brandingKitName(kit);
  const kitId = `${slugifyKitPart(sourceName)}-${backupTimestamp().replace(/[^0-9A-Za-z-]/g, "").slice(0, 17)}`;
  const kitDirectory = path.join(brandingKitsDirectory, kitId);
  fs.mkdirSync(kitDirectory, { recursive: true });

  const installedKit = {
    ...kit,
    id: kitId,
    name: sourceName,
    installedAt: new Date().toISOString(),
    sourceFile: validateBrandOptionalText(fileName, 180),
    branding: { ...(kit.branding || kit) },
    assets: { ...(kit.assets || {}) },
  };
  installedKit.branding.appName = defaultBranding.app_name;

  if (extractPath) {
    const logoFile = findBrandingAssetFile(extractPath, kit);
    const iconFile = findBrandingIconFile(extractPath, kit);
    const logoUrl = copyKitAssetToLibrary(logoFile, kitDirectory, kitId);
    const iconUrl = copyKitAssetToLibrary(iconFile, kitDirectory, kitId);
    if (logoUrl) {
      installedKit.branding.logoUrl = logoUrl;
      installedKit.assets.logo = logoUrl;
    }
    if (iconUrl) {
      installedKit.branding.iconUrl = iconUrl;
      installedKit.assets.icon = iconUrl;
    }
  }

  fs.writeFileSync(path.join(kitDirectory, "manifest.json"), JSON.stringify(installedKit, null, 2), "utf8");
  return installedKit;
}

function neutralBrandingKit() {
  return {
    id: "neutral",
    name: "Grabenplaner Standard",
    builtin: true,
    branding: {
      appName: defaultBranding.app_name,
      companyName: defaultBranding.company_name,
      logoUrl: defaultBranding.logo_url,
      iconUrl: defaultBranding.icon_url,
      logoAlt: defaultBranding.logo_alt,
      adminEmail: defaultBranding.admin_email,
    },
    pdf: {
      scheduleTitle: defaultSettings.pdf_title,
      scheduleFilenamePrefix: defaultSettings.pdf_filename_prefix,
      vacationTitle: defaultSettings.vacation_pdf_title,
      vacationFilenamePrefix: defaultSettings.vacation_pdf_filename_prefix,
    },
  };
}

function readBrandingKitManifest(kitId) {
  if (kitId === "neutral") return neutralBrandingKit();
  if (!/^[a-z0-9-]+$/i.test(String(kitId || ""))) throw httpError(400, "Ungültiges Branding-Kit.");
  const manifestPath = path.join(brandingKitsDirectory, kitId, "manifest.json");
  if (!fs.existsSync(manifestPath)) throw httpError(404, "Branding-Kit wurde nicht gefunden.");
  return JSON.parse(fs.readFileSync(manifestPath, "utf8").replace(/^\uFEFF/, ""));
}

function listBrandingKits(locationId = "") {
  const assignment = locationId ? locationBrandingRow(locationId) : null;
  const current = locationId ? brandingForLocation(locationId) : brandingFromSettings(getSettings());
  const kits = [neutralBrandingKit()];
  for (const entry of fs.readdirSync(brandingKitsDirectory, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    try {
      kits.push(readBrandingKitManifest(entry.name));
    } catch {}
  }
  return kits.map((kit) => {
    const branding = brandingFromSettings(kit.branding || {});
    return {
      id: kit.id || "neutral",
      name: kit.name || branding.companyName || "Branding-Kit",
      builtin: Boolean(kit.builtin),
      installedAt: kit.installedAt || "",
      branding,
      pdf: kit.pdf || {},
      active: assignment?.kit_id
        ? String(kit.id || "neutral") === assignment.kit_id
        : branding.logoUrl === current.logoUrl
          && branding.iconUrl === current.iconUrl
          && branding.companyName === current.companyName
          && branding.adminEmail === current.adminEmail,
    };
  }).sort((a, b) => Number(b.builtin) - Number(a.builtin) || String(a.name).localeCompare(String(b.name), "de"));
}

async function validateBrandingAssignmentInput(input = {}) {
  const locationId = normalizeLocationId(input.locationId || input.location);
  await validateLocationExists(locationId);
  const kitId = String(input.kitId ?? "").trim();
  if (kitId && kitId !== "custom") readBrandingKitManifest(kitId);
  if (kitId === "custom" && !input.branding) {
    throw httpError(400, "Fuer ein individuelles Branding fehlen die Branding-Daten.", "BRANDING_ASSIGNMENT_INVALID");
  }
  return { locationId, kitId, branding: input.branding || input };
}

async function prepareBrandingAssignment(input = {}) {
  const assignment = await validateBrandingAssignmentInput(input);
  if (!assignment.kitId || assignment.kitId === "custom") {
    return { assignment, scheduleContext: null, vacationContext: null };
  }
  const scheduleContext = await resolvePlanningContext({ locationId: assignment.locationId });
  const vacationContext = await resolvePlanningContext({
    locationId: assignment.locationId,
    departmentId: null,
  });
  return { assignment, scheduleContext, vacationContext };
}

async function applyBrandingAssignment(
  input,
  actor,
  {
    manageTransaction = true,
    repository = planningSettingsRepository,
    auditRepository = organizationPersonnelRepository,
    prepared = null,
  } = {},
) {
  const preparedAssignment = prepared || await prepareBrandingAssignment(input);
  if (manageTransaction) {
    const result = await persistenceProvider.transaction(async (executor) => {
      const repositories = createApplicationRepositories(executor);
      return (await applyBrandingAssignment(input, actor, {
        manageTransaction: false,
        repository: repositories.planningSettings,
        auditRepository: repositories.organizationPersonnel,
        prepared: preparedAssignment,
      }));
    });
    await refreshPlanningSettingsReadModel();
    return {
      ...result,
      settings: await settingsForLocation(result.locationId),
      branding: brandingForLocation(result.locationId),
    };
  }
  const { assignment, scheduleContext, vacationContext } = preparedAssignment;
  let result;
  if (!assignment.kitId) {
    await repository.deleteLocationBranding({ locationId: assignment.locationId });
    result = {
      ok: true,
      locationId: assignment.locationId,
      settings: null,
      branding: brandingFromSettings(defaultSettings),
    };
  } else if (assignment.kitId === "custom") {
    const branding = await saveLocationBrandingSnapshot(
      assignment.locationId,
      "custom",
      assignment.branding,
      actor.employeeNumber,
      repository,
    );
    result = { ok: true, locationId: assignment.locationId, settings: null, branding };
  } else {
    const kit = readBrandingKitManifest(assignment.kitId);
    result = await applyBrandingKit(
      kit,
      { locationId: assignment.locationId },
      actor.employeeNumber,
      {
        manageTransaction: false,
        repository,
        resolvedScheduleContext: scheduleContext,
        resolvedVacationContext: vacationContext,
      },
    );
  }
  await auditRepository.insertAudit(
    actor.employeeNumber,
    "branding.assignment.update",
    "location",
    assignment.locationId,
    JSON.stringify({ kitId: assignment.kitId || "default" }),
  );
  return result;
}

async function deleteInstalledBrandingKit(kitId, actor = "") {
  const normalizedKitId = String(kitId || "").trim();
  if (normalizedKitId === "neutral") throw httpError(400, "Das Standard-Branding kann nicht geloescht werden.", "BRANDING_KIT_BUILTIN");
  const kit = readBrandingKitManifest(normalizedKitId);
  const locationNames = new Map(
    portalScopeProjectionSnapshot.locations.map((row) => [String(row.id), row.name]),
  );
  const assignedLocations = planningSettingsReadModel.locationBranding
    .filter((row) => row.kit_id === normalizedKitId)
    .map((row) => ({
      location_id: row.location_id,
      location_name: locationNames.get(String(row.location_id)) || "",
    }));
  const selectedForManagement = String(getSettings().branding_management_kit_id || "") === normalizedKitId;
  if (assignedLocations.length || selectedForManagement) {
    const locations = assignedLocations.map((row) => `${row.location_id}${row.location_name ? ` ${row.location_name}` : ""}`);
    const error = httpError(409, "Das Branding-Kit ist noch in Verwendung und kann erst nach dem Aufheben der Zuordnung geloescht werden.", "BRANDING_KIT_IN_USE");
    error.details = { locations, selectedForManagement };
    throw error;
  }
  const kitDirectory = path.resolve(brandingKitsDirectory, normalizedKitId);
  const libraryRoot = path.resolve(brandingKitsDirectory);
  if (!kitDirectory.startsWith(`${libraryRoot}${path.sep}`) || !fs.existsSync(kitDirectory)) {
    throw httpError(404, "Branding-Kit wurde nicht gefunden.");
  }
  const stagedDirectory = `${kitDirectory}.deleting-${crypto.randomUUID()}`;
  fs.renameSync(kitDirectory, stagedDirectory);
  try {
    (await auditPortal(actor, "branding.kit.delete", "branding_kit", normalizedKitId, JSON.stringify({ name: brandingKitName(kit) })));
    fs.rmSync(stagedDirectory, { recursive: true, force: true });
  } catch (error) {
    if (fs.existsSync(stagedDirectory) && !fs.existsSync(kitDirectory)) fs.renameSync(stagedDirectory, kitDirectory);
    throw error;
  }
  return { id: normalizedKitId, name: brandingKitName(kit) };
}

function employeeLocationFilterSql(context, alias = "e") {
  const prefix = alias ? `${alias}.` : "";
  const sql = [`${prefix}home_location_id = ?`];
  const values = [context.locationId];
  if (context.departmentId) {
    sql.push(`${prefix}preferred_department_id = ?`);
    values.push(context.departmentId);
  }
  return { sql: sql.join(" AND "), values };
}

function scheduleEmployeeFilterSql(context, weekStart, weekEnd, alias = "e") {
  const prefix = alias ? `${alias}.` : "";
  if (!context.departmentId) {
    return {
      sql: `(${prefix}home_location_id = ? OR EXISTS (
        SELECT 1
        FROM shifts sx
        WHERE sx.employee_number = ${prefix}personnel_number
          AND sx.location_id = ?
          AND sx.shift_date BETWEEN ? AND ?
      ))`,
      values: [context.locationId, context.locationId, weekStart, weekEnd],
    };
  }
  return {
    sql: `((${prefix}home_location_id = ? AND ${prefix}preferred_department_id = ?) OR EXISTS (
      SELECT 1
      FROM shifts sx
      WHERE sx.employee_number = ${prefix}personnel_number
        AND sx.location_id = ?
        AND sx.shift_date BETWEEN ? AND ?
        AND sx.department_id = ?
    ))`,
    values: [context.locationId, context.departmentId, context.locationId, weekStart, weekEnd, context.departmentId],
  };
}

function resolveBackupDirectory(value) {
  const raw = String(value || defaultBackupDirectorySetting).trim()
    .replace(/%GRABENPLANER_ROOT%/gi, path.basename(__dirname).toLowerCase() === "app" ? path.dirname(__dirname) : __dirname)
    .replace(/%USERPROFILE%/gi, os.homedir())
    .replace(/%HOME%/gi, os.homedir());
  if (raw === "~") return os.homedir();
  if (raw.startsWith("~/") || raw.startsWith("~\\")) return path.join(os.homedir(), raw.slice(2));
  return raw;
}

function backupDirectoryFromSettings(settings = getSettings()) {
  return process.env.BACKUP_DIR || resolveBackupDirectory(settings.backup_directory || defaultBackupDirectorySetting);
}

function validateBackupDirectory(value) {
  const stored = String(value || "").trim();
  if (!stored) throw httpError(400, "Bitte einen Backup-Ordner angeben.");
  const backupDirectory = process.env.BACKUP_DIR || resolveBackupDirectory(stored);
  if (!path.isAbsolute(backupDirectory)) {
    throw httpError(400, "Bitte einen vollständigen Backup-Pfad angeben.");
  }
  fs.mkdirSync(backupDirectory, { recursive: true });
  fs.accessSync(backupDirectory, fs.constants.W_OK);
  return { stored: process.env.BACKUP_DIR || stored, resolved: backupDirectory };
}

function backupIntervalMs(settings = getSettings()) {
  const hours = Number(settings.backup_interval_hours || 24);
  return Math.min(24, Math.max(1, Number.isFinite(hours) ? hours : 24)) * 60 * 60 * 1000;
}

function scheduleAutomaticBackups() {
  if (backupInterval) clearInterval(backupInterval);
  backupInterval = null;
  if (serverModeActive) return;
  backupInterval = setInterval(async () => {
    try {
      const settings = getSettings();
      const backup = settings.external_backup_enabled === "0" ? null
        : await createDatabaseBackupInBackground(backupDirectoryFromSettings(settings), "scheduled", "external");
      if (backup) {
        lastBackup = {
          path: backup.path,
          createdAt: backup.createdAt,
          reason: "scheduled",
          appBackup: lastBackup?.appBackup || null,
          externalBackup: backup,
        };
      }
    } catch (error) {
      console.error("Backup konnte nicht erstellt werden:", error);
    }
  }, backupIntervalMs());
  backupInterval.unref();
}

const dayKeyByNumber = {
  1: "monday",
  2: "tuesday",
  3: "wednesday",
  4: "thursday",
  5: "friday",
  6: "saturday",
};

function dayKeyForDate(isoDate) {
  return dayKeyByNumber[new Date(`${isoDate}T12:00:00Z`).getUTCDay()] || null;
}

function parseFixedWorkdays(value) {
  return String(value || "")
    .split(",")
    .map((day) => day.trim())
    .filter(Boolean);
}

function normalizeFixedWorkdays(value) {
  const submitted = Array.isArray(value) ? value : parseFixedWorkdays(value);
  const normalized = [...new Set(submitted.map((day) => String(day || "").trim()).filter(Boolean))];
  if (!normalized.every((day) => fixedWorkdayKeys.includes(day))) {
    throw httpError(400, "Die fixen Arbeitstage sind ungültig.");
  }
  return normalized;
}

function employeeCanWorkOnDate(employee, isoDate) {
  const fixedDays = parseFixedWorkdays(employee.fixed_workdays);
  return fixedDays.length === 0 || fixedDays.includes(dayKeyForDate(isoDate));
}

async function dayConfiguration(isoDate, settings, context = null) {
  const key = dayKeyForDate(isoDate);
  if (!key) return null;
  const configuredMinStaff = Number(settings[`${key}_min_staff`] || 0);
  const contextMinStaff = context ? await staffingFloorForContext(context) : 0;
  return {
    key,
    open: settings[`${key}_open`] !== "0",
    start: settings[`${key}_start_time`],
    end: settings[`${key}_end_time`],
    lunchEnabled: settingEnabled(settings, `${key}_lunch_enabled`),
    lunchStart: settings[`${key}_lunch_start`],
    lunchEnd: settings[`${key}_lunch_end`],
    minStaff: Math.max(configuredMinStaff, contextMinStaff),
    configuredMinStaff,
    contextMinStaff,
    minFrom: settings[`${key}_min_from`],
    minTo: settings[`${key}_min_to`],
  };
}

async function operatingHours(isoDate, settings) {
  const config = await dayConfiguration(isoDate, settings);
  return config?.open ? { start: config.start, end: config.end } : null;
}

function projectBranchSupervisionShifts(storedShifts, planningChange, {
  locationId,
  weekStart,
  weekEnd,
}) {
  let shifts = (storedShifts || []).map((shift) => ({ ...shift }));
  const deletedShiftIds = new Set(
    Array.isArray(planningChange?.deletedShiftIds)
      ? planningChange.deletedShiftIds.map((id) => String(id))
      : [],
  );
  if (planningChange?.deleted === true && planningChange.id) {
    deletedShiftIds.add(String(planningChange.id));
  }
  if (deletedShiftIds.size) {
    shifts = shifts.filter((shift) => !deletedShiftIds.has(String(shift.id)));
  }
  const replaceRange = planningChange?.replaceRange;
  if (replaceRange) {
    shifts = shifts.filter((shift) => !(
      String(shift.location_id || "") === String(replaceRange.locationId || locationId)
      && shift.shift_date >= String(replaceRange.dateFrom || weekStart)
      && shift.shift_date <= String(replaceRange.dateTo || weekEnd)
      && (!replaceRange.departmentId
        || Number(shift.department_id || 0) === Number(replaceRange.departmentId))
    ));
  }
  const submittedShifts = Array.isArray(planningChange?.addedShifts)
    ? planningChange.addedShifts
    : (planningChange && planningChange.deleted !== true && !replaceRange ? [planningChange] : []);
  for (const [index, submitted] of submittedShifts.entries()) {
    if (!submitted || typeof submitted !== "object") continue;
    const shiftDate = String(submitted.shiftDate ?? submitted.shift_date ?? "");
    const submittedLocationId = String(submitted.locationId ?? submitted.location_id ?? locationId);
    if (submittedLocationId !== String(locationId) || shiftDate < weekStart || shiftDate > weekEnd) continue;
    const candidateId = Number(submitted.id || 0);
    if (candidateId) shifts = shifts.filter((shift) => Number(shift.id) !== candidateId);
    shifts.push({
      id: candidateId ? `candidate-${candidateId}` : `candidate-new-${index}`,
      employee_number: String(submitted.employeeNumber ?? submitted.employee_number ?? ""),
      location_id: submittedLocationId,
      department_id: submitted.departmentId ?? submitted.department_id ?? null,
      duty_code: submitted.dutyCode ?? submitted.duty_code ?? "",
      shift_date: shiftDate,
      start_time: String(submitted.startTime ?? submitted.start_time ?? ""),
      end_time: String(submitted.endTime ?? submitted.end_time ?? ""),
    });
  }
  return shifts;
}

async function branchSupervisionAssessmentForSchedule(
  weekStart,
  locationId,
  planningChange = null,
  { dates = null } = {},
) {
  const weekEnd = addDays(weekStart, 6);
  const planningQuery = {
    locationId: String(locationId),
    departmentId: null,
    weekStart,
    weekEnd,
  };
  const [settings, employees, storedShifts] = await Promise.all([
    settingsForLocation(locationId),
    planningSettingsRepository.listScheduleEmployees(planningQuery),
    planningSettingsRepository.listScheduleShifts(planningQuery),
  ]);
  const shifts = projectBranchSupervisionShifts(storedShifts, planningChange, {
    locationId: String(locationId),
    weekStart,
    weekEnd,
  });
  const knownEmployeeNumbers = new Set(employees.map((employee) => String(employee.personnel_number)));
  const submittedShifts = Array.isArray(planningChange?.addedShifts)
    ? planningChange.addedShifts
    : (planningChange && planningChange.deleted !== true ? [planningChange] : []);
  for (const submitted of submittedShifts) {
    const employeeNumber = String(submitted?.employeeNumber ?? submitted?.employee_number ?? "");
    if (!employeeNumber || knownEmployeeNumbers.has(employeeNumber)) continue;
    const employee = await planningSettingsRepository.getActivePlanningEmployee({ employeeNumber });
    if (!employee) continue;
    employees.push(employee);
    knownEmployeeNumbers.add(employeeNumber);
  }
  const blockedDates = new Set([
    ...getGlobalDayBlocksForRange(weekStart, weekEnd, locationId).map((block) => block.block_date),
    ...publicHolidaysForRange(weekStart, weekEnd).map((holiday) => holiday.date),
  ]);
  return assessBranchSupervision({
    weekStart,
    weekEnd,
    locationId,
    settings,
    employees,
    shifts,
    blockedDates: [...blockedDates],
    dates,
  });
}

async function evaluateBranchSupervisionMutation(
  weekStart,
  locationId,
  planningChange,
  dates,
) {
  const before = await branchSupervisionAssessmentForSchedule(
    weekStart,
    locationId,
    null,
    { dates },
  );
  const after = await branchSupervisionAssessmentForSchedule(
    weekStart,
    locationId,
    planningChange,
    { dates },
  );
  return { before, after };
}

function branchSupervisionBlockingError(after, messagePrefix = "Die Änderung würde die Filialaufsicht") {
  const issue = after.issues?.[0];
  const period = issue
    ? `${issue.dayLabel}, ${issue.date} (${issue.openingTime}–${issue.closingTime} Uhr)`
    : "im betroffenen Planungszeitraum";
  const error = httpError(
    409,
    `${messagePrefix} ${period} verletzen. Bitte zuerst einen Dienst für Teamleitung/FL oder FL Stellvertretung ergänzen; eine Abteilungsleitung darf nur die konfigurierte Lücke überbrücken.`,
    "BRANCH_SUPERVISION_BLOCKED",
  );
  error.details = { branchSupervisionAssessment: after };
  return error;
}

function assertBranchSupervisionAllowsMutation(evaluation) {
  const before = evaluation?.before;
  const after = evaluation?.after;
  if (!after?.blocking || Number(after.deficitScore || 0) <= Number(before?.deficitScore || 0)) return;
  throw branchSupervisionBlockingError(after);
}

function assertBranchSupervisionComplete(evaluation) {
  const after = evaluation?.after;
  if (!after?.blocking) return;
  throw branchSupervisionBlockingError(
    after,
    "Der automatisch erzeugte Dienstplan würde die Filialaufsicht",
  );
}

async function evaluateBranchSupervisionChanges(shiftRows, planningChange = null) {
  const targets = new Map();
  const candidateRows = [
    ...(Array.isArray(shiftRows) ? shiftRows : []),
    ...(Array.isArray(planningChange?.addedShifts) ? planningChange.addedShifts : []),
  ];
  for (const shift of candidateRows) {
    const locationId = String(shift?.location_id ?? shift?.locationId ?? "").trim();
    const shiftDate = String(shift?.shift_date ?? shift?.shiftDate ?? "");
    if (!locationId || !isIsoDate(shiftDate)) continue;
    const weekStart = getMonday(shiftDate);
    const key = `${locationId}|${weekStart}`;
    if (!targets.has(key)) targets.set(key, { locationId, weekStart, dates: new Set() });
    targets.get(key).dates.add(shiftDate);
  }
  const evaluations = [];
  for (const target of targets.values()) {
    const evaluation = await evaluateBranchSupervisionMutation(
      target.weekStart,
      target.locationId,
      planningChange,
      [...target.dates],
    );
    assertBranchSupervisionAllowsMutation(evaluation);
    evaluations.push(evaluation);
  }
  return evaluations;
}

async function evaluateBranchSupervisionShiftUpdate(existing, shift, id) {
  const existingWeekStart = getMonday(existing.shift_date);
  const nextWeekStart = getMonday(shift.shiftDate);
  const sameLocationWeek = String(existing.location_id) === String(shift.locationId)
    && existingWeekStart === nextWeekStart;
  if (sameLocationWeek) {
    const evaluation = await evaluateBranchSupervisionMutation(
      nextWeekStart,
      shift.locationId,
      { id, ...shift },
      [...new Set([existing.shift_date, shift.shiftDate])],
    );
    assertBranchSupervisionAllowsMutation(evaluation);
    return evaluation.after;
  }
  const previousEvaluation = await evaluateBranchSupervisionMutation(
    existingWeekStart,
    existing.location_id,
    { id, deleted: true },
    [existing.shift_date],
  );
  const nextEvaluation = await evaluateBranchSupervisionMutation(
    nextWeekStart,
    shift.locationId,
    { id, ...shift },
    [shift.shiftDate],
  );
  assertBranchSupervisionAllowsMutation(previousEvaluation);
  assertBranchSupervisionAllowsMutation(nextEvaluation);
  return nextEvaluation.after;
}

function serializeGlobalDayBlock(row) {
  const holidayName = publicHolidayName(row.block_date);
  return {
    ...row,
    location_id: row.location_id || "01",
    is_public_holiday: Boolean(row.is_public_holiday),
    holiday_name: holidayName,
  };
}

function getGlobalDayBlocksForRange(start, end, locationId = null) {
  return planningSettingsReadModel.globalDayBlocks
    .filter((row) => row.block_date >= start && row.block_date <= end)
    .filter((row) => !locationId || String(row.location_id) === String(locationId))
    .map(serializeGlobalDayBlock);
}

function getGlobalDayBlockForDate(isoDate, locationId = null) {
  const row = planningSettingsReadModel.globalDayBlocks.find((entry) => (
    entry.block_date === isoDate
    && (!locationId || String(entry.location_id) === String(locationId))
  ));
  return row ? serializeGlobalDayBlock(row) : null;
}

function publicHolidaysForRange(start, end) {
  const holidays = [];
  for (let date = start; date <= end; date = addDays(date, 1)) {
    const name = publicHolidayName(date);
    if (name) holidays.push({ date, name });
  }
  return holidays;
}

function isVacationHoliday(isoDate, locationId = null) {
  if (publicHolidayName(isoDate)) return true;
  const block = getGlobalDayBlockForDate(isoDate, locationId);
  return Boolean(block?.is_public_holiday);
}

function holidayCreditMinutes(employee) {
  return Math.round((Number(employee.contracted_hours || 0) * 60) / 5);
}

function overlapMinutes(start, end, rangeStart, rangeEnd) {
  return Math.max(0, Math.min(end, rangeEnd) - Math.max(start, rangeStart));
}

function finiteNumberInRange(value, fallback, minimum, maximum) {
  const numeric = Number(value);
  return Number.isFinite(numeric) && numeric >= minimum && numeric <= maximum
    ? numeric
    : fallback;
}

function saturdayBonusSettings(settings = {}) {
  const defaultFrom = isTime(defaultSettings.saturday_bonus_from)
    ? defaultSettings.saturday_bonus_from
    : "13:00";
  const defaultFactor = finiteNumberInRange(
    defaultSettings.saturday_bonus_factor,
    1.5,
    1,
    5,
  );
  return {
    from: isTime(settings.saturday_bonus_from) ? settings.saturday_bonus_from : defaultFrom,
    factor: finiteNumberInRange(settings.saturday_bonus_factor, defaultFactor, 1, 5),
  };
}

function finiteScheduleMinutes(value, fallback = 0) {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : fallback;
}

function scheduleShiftMinuteBasis(shift) {
  const rawMinutes = Math.max(0, finiteScheduleMinutes(shift.raw_minutes));
  const breakMinutes = Math.min(
    rawMinutes,
    Math.max(0, finiteScheduleMinutes(shift.break_minutes)),
  );
  const plannedMinutes = rawMinutes - breakMinutes;
  const bonusMinutes = Math.max(0, finiteScheduleMinutes(shift.bonus_minutes));
  const countedMinutes = Math.max(
    0,
    finiteScheduleMinutes(shift.counted_minutes, plannedMinutes + bonusMinutes),
  );
  return { plannedMinutes, bonusMinutes, countedMinutes };
}

function addScheduleMinutes(current, addition, fallback = 0) {
  return finiteScheduleMinutes(current) + finiteScheduleMinutes(addition, fallback);
}

async function overlappingWeekOption(employeeNumber, date, startTime, endTime) {
  return (await planningSettingsRepository.listWeekOptionsForEmployeeDate({
    employeeNumber,
    date,
  }))
    .find((option) => optionOverlapsTime(option, startTime, endTime));
}

async function shiftMetrics(shift, settings, { legacyOnly = false } = {}) {
  const saturdayContext = !legacyOnly && shift.employee_number && isIsoDate(shift.shift_date)
    ? await saturdayCreditService.status(shift.employee_number, shift.shift_date) : null;
  const cutover = saturdayContext?.cutover;
  if (cutover && shift.shift_date < cutover.effectiveDate) {
    const saved = cutover.legacySettings[String(shift.location_id || '')] || cutover.legacySettings['*'];
    if (saved) settings = { ...settings, saturday_bonus_enabled: saved.enabled ? '1' : '0', saturday_bonus_from: saved.from, saturday_bonus_factor: String(saved.factor) };
  }
  const start = timeToMinutes(shift.start_time);
  let end = timeToMinutes(shift.end_time);
  if (end <= start) end += 24 * 60;
  const rawMinutes = end - start;
  const defaultBreakAfter = finiteNumberInRange(defaultSettings.break_after_minutes, 360, 0, 1440);
  const defaultBreakDuration = finiteNumberInRange(defaultSettings.break_duration_minutes, 30, 0, 240);
  const breakAfterMinutes = finiteNumberInRange(settings.break_after_minutes, defaultBreakAfter, 0, 1440);
  const breakDurationMinutes = finiteNumberInRange(settings.break_duration_minutes, defaultBreakDuration, 0, 240);
  const ruleBreakMinutes =
    settingEnabled(settings, "break_rule_enabled") &&
    rawMinutes > breakAfterMinutes
      ? breakDurationMinutes
      : 0;
  const dayConfig = await dayConfiguration(shift.shift_date, settings);
  const lunchBreakMinutes = dayConfig?.lunchEnabled
    && isTime(dayConfig.lunchStart)
    && isTime(dayConfig.lunchEnd)
    ? overlapMinutes(
        start,
        end,
        timeToMinutes(dayConfig.lunchStart),
        timeToMinutes(dayConfig.lunchEnd),
      )
    : 0;
  const breakMinutes = Math.max(ruleBreakMinutes, lunchBreakMinutes);

  let countedMinutes = rawMinutes - breakMinutes;
  let bonusMinutes = 0;
  const isSaturday = new Date(`${shift.shift_date}T12:00:00Z`).getUTCDay() === 6;

  if (isSaturday && settingEnabled(settings, "saturday_bonus_enabled")) {
    const saturdayBonus = saturdayBonusSettings(settings);
    const bonusStart = timeToMinutes(saturdayBonus.from);
    let eligibleMinutes = Math.max(0, end - Math.max(start, bonusStart));
    if (dayConfig?.lunchEnabled && isTime(dayConfig.lunchStart) && isTime(dayConfig.lunchEnd)) {
      eligibleMinutes -= overlapMinutes(
        Math.max(start, bonusStart),
        end,
        timeToMinutes(dayConfig.lunchStart),
        timeToMinutes(dayConfig.lunchEnd),
      );
    }
    bonusMinutes = Math.round(Math.max(0, eligibleMinutes) * (saturdayBonus.factor - 1));
    countedMinutes += bonusMinutes;
  }

  const metrics = {
    raw_minutes: rawMinutes,
    break_minutes: breakMinutes,
    lunch_break_minutes: lunchBreakMinutes,
    bonus_minutes: bonusMinutes,
    counted_minutes: countedMinutes,
  };
  if (!cutover || shift.shift_date < cutover.effectiveDate) return metrics;
  metrics.bonus_minutes = 0; metrics.counted_minutes = rawMinutes - breakMinutes;
  metrics.saturday_eligible_minutes = 0;
  if (!isSaturday) return metrics;
  const peers = (await timeTrackingRepository.listPlannedDayShifts({ employeeNumber: shift.employee_number,
    date: shift.shift_date, departmentId: null, filterDepartment: 0, locationId: '', filterLocation: 0 }))
    .filter(peer => shift.id ? String(peer.id) !== String(shift.id)
      : !(peer.start_time === shift.start_time && peer.end_time === shift.end_time && String(peer.location_id || '') === String(shift.location_id || '')));
  peers.push(shift);
  const groups = [], netMinutes = [];
  let breaksResolved = true, holiday = false;
  for (const peer of peers) {
    const peerSettings = peer === shift ? settings : await settingsForLocation(peer.location_id);
    const base = peer === shift ? metrics : await shiftMetrics(peer, peerSettings, { legacyOnly: true });
    const config = await dayConfiguration(peer.shift_date, peerSettings);
    const from = timeToMinutes(peer.start_time); let to = timeToMinutes(peer.end_time); if (to <= from) to += 1440;
    const lunch = config?.lunchEnabled && isTime(config.lunchStart) && isTime(config.lunchEnd);
    groups.push(plannedWorkSegments(from, to, lunch ? timeToMinutes(config.lunchStart) : null, lunch ? timeToMinutes(config.lunchEnd) : null));
    netMinutes.push(base.raw_minutes - base.break_minutes);
    if (base.break_minutes > base.lunch_break_minutes) breaksResolved = false;
    if (isVacationHoliday(peer.shift_date, peer.location_id)) holiday = true;
  }
  const valued = await saturdayCreditService.evaluate({ employeeNumber: shift.employee_number, workDate: shift.shift_date,
    source: 'planned', segments: groups.flat(), dayComplete: true, breaksResolved, publicHoliday: holiday,
    legacy: { workedMinutes: netMinutes.reduce((sum, n) => sum + n, 0) } });
  if (valued.saturdayCreditStatus === 'calculated') {
    const allocated = allocateSaturdayMinutes(groups).at(-1);
    metrics.bonus_minutes = allocated.bonusMinutes; metrics.saturday_eligible_minutes = allocated.eligibleMinutes;
    metrics.counted_minutes += allocated.bonusMinutes;
  }
  metrics.saturday_credit_status = valued.saturdayCreditStatus;
  metrics.saturday_credit_receipt = valued.saturdayCreditReceipt;
  return metrics;
}

function serializeEmployee(row, options = {}) {
  const serialized = {
    ...row,
    target_workdays_per_week: normalizeTargetWorkdays(row.target_workdays_per_week),
    fixed_workdays: row.fixed_workdays || "",
    position_id: row.position_id || "verkaufsmitarbeiter",
    position_name: row.position_name || "Verkaufsmitarbeiter",
    time_confirmation_level: ["A", "B", "C"].includes(String(row.time_confirmation_level || "").toUpperCase())
      ? String(row.time_confirmation_level).toUpperCase()
      : "C",
    home_location_id: row.home_location_id || "",
    home_location_name: row.home_location_name || "",
    preferred_department_id: row.preferred_department_id ? Number(row.preferred_department_id) : null,
    preferred_department_name: row.preferred_department_name || "",
    cost_center_id: row.cost_center_id || "",
    cost_center_code: row.cost_center_code || "",
    cost_center_name: row.cost_center_name || "",
    cost_center_type: row.cost_center_type_id || row.cost_center_type || "",
    cost_center_type_id: row.cost_center_type_id || "",
    cost_center_type_name: row.cost_center_type_name || "",
    cost_center_is_branch: Boolean(row.cost_center_is_branch),
    active: Boolean(row.active),
    sickness_without_aum_enabled: Boolean(row.sickness_without_aum_enabled),
  };
  if (options.includeTimeConfirmationLevel === false) delete serialized.time_confirmation_level;
  if (options.includeSicknessAllowance === false) delete serialized.sickness_without_aum_enabled;
  return serialized;
}

function isReservedEmployeePrincipal(value) {
  return String(value || "").trim().toLowerCase() === "local";
}

function assertEmployeePrincipalNotReserved(value) {
  if (!isReservedEmployeePrincipal(value)) return;
  throw httpError(
    409,
    "Diese Personalnummer ist fuer den internen lokalen Systemzugang reserviert.",
    "EMPLOYEE_PRINCIPAL_RESERVED",
  );
}

async function assertEmployeePrincipalLoginAvailable(
  personnelNumber,
  repository = organizationPersonnelRepository,
) {
  const normalized = String(personnelNumber || "").trim();
  if (!normalized) return;
  assertEmployeePrincipalNotReserved(normalized);
  const collision = await repository.organizationAccountLoginCollision(normalized);
  if (collision) {
    throw httpError(
      409,
      "Diese Personalnummer ist bereits als Organisationskonto vergeben.",
      "PORTAL_PRINCIPAL_LOGIN_CONFLICT",
    );
  }
}

async function validateEmployee(body, isNew, options = {}) {
  const personnelNumber = String(body.personnelNumber || "").trim();
  assertEmployeePrincipalNotReserved(personnelNumber);
  const fullName = String(body.fullName || "").trim();
  const nickname = String(body.nickname || "").trim();
  const color = /^#[0-9a-f]{6}$/i.test(body.color || "") ? body.color : "#0b84c6";
  const contractedHours = Number(body.contractedHours);
  const submittedTargetWorkdays = Number(body.targetWorkdaysPerWeek ?? body.target_workdays_per_week ?? 5);
  const targetWorkdaysPerWeek = normalizeTargetWorkdays(submittedTargetWorkdays);
  const preferredDayOff = String(body.preferredDayOff || "").trim();
  const fixedWorkdays = normalizeFixedWorkdays(body.fixedWorkdays ?? body.fixed_workdays);
  const requestedPositionId = String(body.positionId || body.position_id || "").trim();
  let positionId = requestedPositionId;
  const employeeActive = body.active === false || body.active === 0 ? 0 : 1;
  const submittedTimeConfirmationLevel = body.timeConfirmationLevel ?? body.time_confirmation_level
    ?? options.defaultTimeConfirmationLevel ?? "C";
  const timeConfirmationLevel = String(submittedTimeConfirmationLevel).trim().toUpperCase();
  const sicknessWithoutAumEnabled = body.sicknessWithoutAumEnabled === true
    || body.sickness_without_aum_enabled === true || Number(body.sickness_without_aum_enabled) === 1;
  const allowedPreferredDays = ["", "monday", "tuesday", "wednesday", "thursday", "friday"];
  const costCenterSubmitted = own(body, "costCenterId") || own(body, "cost_center_id");
  const costCenterId = costCenterSubmitted
    ? String(body.costCenterId ?? body.cost_center_id ?? "").trim()
    : String(options.defaultCostCenterId || "").trim();
  const assignment = await employeeAssignmentForCostCenter(costCenterId, {
    allowInactive: costCenterId === options.allowInactiveCostCenterId,
    allowInactiveLocationId: options.allowInactiveLocationId,
    allowUnlinkedBranch: Boolean(options.allowUnlinkedBranch),
    repository: options.repository,
  });
  const homeLocationSubmitted = own(body, "homeLocationId") || own(body, "home_location_id");
  const submittedHomeLocationValue = homeLocationSubmitted
    ? String(body.homeLocationId ?? body.home_location_id ?? "").trim()
    : "";
  const submittedHomeLocationId = submittedHomeLocationValue
    ? normalizeLocationId(submittedHomeLocationValue)
    : null;
  const homeLocationId = assignment.homeLocationId;
  if (submittedHomeLocationId && submittedHomeLocationId !== homeLocationId) {
    throw httpError(
      409,
      "Der Standort wird automatisch aus der Kostenstelle abgeleitet und kann nicht separat zugeordnet werden.",
      "EMPLOYEE_HOME_LOCATION_DERIVED",
    );
  }
  const preferredDepartmentId = normalizeDepartmentId(body.preferredDepartmentId ?? body.preferred_department_id, true);
  if (preferredDepartmentId && !homeLocationId) {
    throw httpError(
      400,
      "Ohne einen aus der Kostenstelle abgeleiteten Standort kann keine bevorzugte Abteilung zugeordnet werden.",
      "EMPLOYEE_DEPARTMENT_WITHOUT_LOCATION",
    );
  }
  if (preferredDepartmentId) {
    const department = await validateDepartmentExists(
      preferredDepartmentId,
      homeLocationId,
      options.repository || organizationPersonnelRepository,
    );
    if (!department.active
      && Number(preferredDepartmentId) !== Number(options.allowInactiveDepartmentId || 0)) {
      throw httpError(
        409,
        "Die bevorzugte Abteilung ist archiviert und kann nicht neu zugeordnet werden.",
        "EMPLOYEE_DEPARTMENT_INACTIVE",
      );
    }
  }
  const position = await validateEmployeePositionForAssignment(
    positionId,
    assignment,
    options.repository || organizationPersonnelRepository,
    { allowInactive: employeeActive === 0 },
  );
  positionId = String(position.id);

  if (isNew) {
    await assertEmployeePrincipalLoginAvailable(
      personnelNumber,
      options.repository || organizationPersonnelRepository,
    );
  }
  if (isNew && !/^[A-Za-z0-9._-]{1,24}$/.test(personnelNumber)) {
    throw httpError(400, "Bitte eine gültige Personalnummer eingeben.");
  }
  if (!fullName) throw httpError(400, "Bitte den Namen eingeben.");
  if (!nickname) throw httpError(400, "Bitte den Dienstplan-Namen eingeben.");
  if (!Number.isFinite(contractedHours) || contractedHours < 0 || contractedHours > 80) {
    throw httpError(400, "Die Wochen-Sollzeit muss zwischen 0 und 80 Stunden liegen.");
  }
  if (!Number.isInteger(submittedTargetWorkdays) || submittedTargetWorkdays < 1 || submittedTargetWorkdays > 6) {
    throw httpError(400, "Die vertraglichen Soll-Arbeitstage müssen zwischen 1 und 6 liegen.", "EMPLOYEE_TARGET_WORKDAYS_INVALID");
  }
  if (!allowedPreferredDays.includes(preferredDayOff)) {
    throw httpError(400, "Der bevorzugte freie Tag ist ungültig.");
  }
  if (!["A", "B", "C"].includes(timeConfirmationLevel)) {
    throw httpError(400, "Bitte eine gültige Vertrauensstufe A, B oder C auswählen.", "EMPLOYEE_CONFIRMATION_LEVEL_INVALID");
  }

  return {
    personnelNumber,
    fullName,
    nickname,
    color,
    contractedHours,
    targetWorkdaysPerWeek,
    preferredDayOff: preferredDayOff || null,
    fixedWorkdays: fixedWorkdays.join(","),
    positionId,
    timeConfirmationLevel,
    sicknessWithoutAumEnabled: sicknessWithoutAumEnabled ? 1 : 0,
    homeLocationId,
      preferredDepartmentId,
      costCenterId,
      active: employeeActive,
    };
}

async function validateShift(body, contextInput = {}, actor = null) {
  const employeeNumber = String(body.employeeNumber || "").trim();
  const shiftDate = String(body.date || "");
  const startTime = String(body.startTime || "");
  const endTime = String(body.endTime || "");
  const area = String(body.area || "").trim();
  const note = String(body.note || "").trim();
  const existing = contextInput.existingShift || null;
  const hasDepartmentInput = Object.hasOwn(body, "departmentId") || Object.hasOwn(body, "department_id");
  const departmentId = normalizeDepartmentId(hasDepartmentInput
    ? body.departmentId ?? body.department_id
    : existing?.department_id, true);
  const submittedLocationId = String(
    body.locationId ?? body.location_id ?? body.location
      ?? contextInput.locationId ?? contextInput.location_id ?? contextInput.location ?? "",
  ).trim();
  const existingId = Number(contextInput.existingId || 0);

  if (!employeeNumber) throw httpError(400, "Bitte ein Teammitglied auswählen.");
  if (!isIsoDate(shiftDate)) throw httpError(400, "Das Datum ist ungültig.");
  if (!isTime(startTime) || !isTime(endTime)) throw httpError(400, "Die Arbeitszeit ist ungültig.");
  const employee = await planningSettingsRepository.getPlanningEmployee({ employeeNumber });
  if (!employee) {
    throw httpError(404, "Die ausgewählte Person wurde nicht gefunden.");
  }
  const hasDutyInput = Object.hasOwn(body, "dutyCode") || Object.hasOwn(body, "duty_code");
  const rawDutyCode = body.dutyCode ?? body.duty_code;
  if (hasDutyInput && (typeof rawDutyCode !== "string"
    || !["", "branch_supervision", "department", "general"].includes(rawDutyCode))) {
    throw httpError(400, "Die Dienstzuordnung ist ungültig.", "SHIFT_DUTY_INVALID");
  }
  const departmentChanged = existing && hasDepartmentInput
    && Number(departmentId || 0) !== Number(existing.department_id || 0);
  const dutyCode = !hasDutyInput && existing && !departmentChanged
    ? String(existing.duty_code || "")
    : (rawDutyCode || (departmentId ? "department" : defaultScheduleDutyCode(employee)));
  if ((dutyCode === "department" && !departmentId)
    || (["branch_supervision", "general"].includes(dutyCode) && departmentId)) {
    throw httpError(400, "Dienstzuordnung und Abteilung passen nicht zusammen.", "SHIFT_DUTY_DEPARTMENT_MISMATCH");
  }
  const department = departmentId ? await validateDepartmentExists(departmentId) : null;
  const locationId = submittedLocationId
    ? normalizeLocationId(submittedLocationId)
    : String(department?.location_id || employee.home_location_id || "").trim();
  if (!locationId) throw httpError(400, "Bitte eine Einsatzfiliale auswählen.", "SHIFT_LOCATION_REQUIRED");
  await validateLocationExists(locationId);
  if (department) await validateDepartmentExists(departmentId, locationId);
  const homeLocationId = String(employee.home_location_id || "").trim();
  if (locationId === homeLocationId) {
    const awayAssignment = (await sqliteEmployeeLocationLendingOperations.overlapForShift(
      employeeNumber,
      shiftDate,
      startTime,
      endTime,
    ));
    if (awayAssignment) {
      throw httpError(
        409,
        `${employee.nickname} ist in diesem Zeitraum einer anderen Filiale zugewiesen.`,
        "STAFF_ASSIGNMENT_HOME_SHIFT_CONFLICT",
      );
    }
  } else {
    const assignment = (await sqliteEmployeeLocationLendingOperations.coverageForShift(
      employeeNumber,
      locationId,
      shiftDate,
      startTime,
      endTime,
    ));
    if (!assignment) {
      if (actor && !sessionHasGlobalScope(actor)) {
        throw httpError(
          403,
          "Dieses Teammitglied ist für den vollständigen Dienstzeitraum nicht dieser Filiale zugewiesen.",
          "SHIFT_FOREIGN_EMPLOYEE_SCOPE_DENIED",
        );
      }
      throw httpError(
        409,
        `${employee.nickname} besitzt für diesen vollständigen Zeitraum keinen temporären Einsatz in der gewählten Filiale.`,
        "STAFF_ASSIGNMENT_COVERAGE_REQUIRED",
      );
    }
    if (assignment.destinationDepartmentId
      && Number(assignment.destinationDepartmentId) !== Number(departmentId || 0)) {
      throw httpError(
        409,
        "Der Dienst muss der für den temporären Filialeinsatz festgelegten Zielabteilung entsprechen.",
        "STAFF_ASSIGNMENT_DEPARTMENT_MISMATCH",
      );
    }
  }
  if (!employeeCanWorkOnDate(employee, shiftDate)) {
    throw httpError(409, `${employee.nickname} hat an diesem Wochentag keinen fix vereinbarten Arbeitstag.`);
  }
  const settings = await settingsForLocation(locationId);
  await assertDateEditable(shiftDate, settings, actor, locationId);
  const globalBlock = getGlobalDayBlockForDate(shiftDate, locationId);
  if (globalBlock) {
    throw httpError(409, `Dieser Tag ist für alle gesperrt: ${globalBlock.reason || globalBlock.holiday_name || "gesperrt"}.`);
  }
  const hours = manualPlanningHours();
  if (startTime < hours.start || endTime > hours.end || endTime <= startTime) {
    throw httpError(
      400,
      `Der Dienst muss innerhalb der Dienstzeit ${hours.start}–${hours.end} Uhr liegen.`,
      "SHIFT_PLANNING_WINDOW_INVALID",
    );
  }
  const dayConfig = await dayConfiguration(shiftDate, settings);
  if (
    dayConfig?.lunchEnabled &&
    startTime >= dayConfig.lunchStart &&
    endTime <= dayConfig.lunchEnd
  ) {
    throw httpError(400, "Der Dienst liegt vollständig innerhalb der eingestellten Mittagspause.");
  }
  const conflict = await overlappingWeekOption(employeeNumber, shiftDate, startTime, endTime);
  if (conflict) {
    throw httpError(
      409,
      `${conflict.nickname} ist zu dieser Zeit bereits als „${optionLabel(conflict.option_type)}“ eingetragen.`,
    );
  }
  if ((await activeSicknessEmployeeNumbers(shiftDate)).has(employeeNumber)) {
    throw httpError(409, `${employee.nickname} ist an diesem Tag krankgemeldet.`, "SICKNESS_SHIFT_CONFLICT");
  }
  const overlappingShift = await planningSettingsRepository.getOverlappingShift({
    employeeNumber,
    shiftDate,
    existingId,
    endTime,
    startTime,
  });
  if (overlappingShift) {
    const locationText = overlappingShift.location_name ? ` in ${overlappingShift.location_name}` : "";
    throw httpError(
      409,
      `${employee.nickname} ist von ${overlappingShift.start_time} bis ${overlappingShift.end_time} Uhr bereits${locationText} eingeteilt.`,
      "SHIFT_TIME_CONFLICT",
    );
  }

  return { employeeNumber, locationId, departmentId, dutyCode, shiftDate, startTime, endTime, area, note };
}

function staffAssignmentShiftConstraintError(error) {
  let current = error;
  while (current) {
    const message = String(current.message || "");
    if (current.messageKey === "staff-assignment-home-shift-conflict"
      || message.includes("STAFF_ASSIGNMENT_HOME_SHIFT_CONFLICT")) {
      return httpError(
        409,
        "Der Dienst überschneidet sich mit einem temporären Einsatz in einer anderen Filiale.",
        "STAFF_ASSIGNMENT_HOME_SHIFT_CONFLICT",
      );
    }
    if (current.messageKey === "staff-assignment-coverage-required"
      || message.includes("STAFF_ASSIGNMENT_COVERAGE_REQUIRED")) {
      return httpError(
        409,
        "Für den vollständigen Dienstzeitraum besteht kein passender temporärer Filialeinsatz.",
        "STAFF_ASSIGNMENT_COVERAGE_REQUIRED",
      );
    }
    current = current.cause;
  }
  return error;
}

function staffAssignmentAbsenceConstraintError(error) {
  if (error?.messageKey !== "staff-assignment-direct-absence-conflict") return error;
  return httpError(
    409,
    "Die direkte Abwesenheit überschneidet sich mit einem temporären Filialeinsatz. Bitte verwenden Sie für ZA den regulären Antrag.",
    "STAFF_ASSIGNMENT_DIRECT_ABSENCE_CONFLICT",
  );
}

async function assertShiftEmployeeAssignmentScope(session, shift, existing = null) {
  if (sessionHasGlobalScope(session)) return;
  const employee = (await sqliteEmployeeLocationLendingOperations.employee(shift.employeeNumber));
  const homeLocationId = String(employee?.home_location_id || "");
  if (homeLocationId === shift.locationId) return;
  const assignment = (await sqliteEmployeeLocationLendingOperations.coverageForShift(
    shift.employeeNumber,
    shift.locationId,
    shift.shiftDate,
    shift.startTime,
    shift.endTime,
  ));
  if (assignment && (!assignment.destinationDepartmentId
    || Number(assignment.destinationDepartmentId) === Number(shift.departmentId || 0))) return;
  throw httpError(
    403,
    "Dieses Teammitglied ist für den vollständigen Dienstzeitraum nicht dieser Filiale zugewiesen.",
    "SHIFT_FOREIGN_EMPLOYEE_SCOPE_DENIED",
  );
}

const alwaysFullDayOptionTypes = new Set(["vacation", "sick", "branch", "vocational_school", "special_leave"]);
const timedOptionTypes = new Set(["school", "time_off", "external_appointment", "team_meeting", "other"]);
const manualAllDayCreditTypes = new Set(["school", "external_appointment", "team_meeting", "other"]);
const directlyApprovedAbsenceOptionTypes = new Set(["vacation", "time_off"]);
const TEAM_MEETING_GROUP_PREFIX = "team-meeting:";
const allowedWeekOptionTypes = [
  "vacation",
  "sick",
  "branch",
  "vocational_school",
  "school",
  "time_off",
  "special_leave",
  "external_appointment",
  "team_meeting",
  "other",
];

function isTeamMeetingGroupId(value) {
  return String(value || "").startsWith(TEAM_MEETING_GROUP_PREFIX);
}

function isTeamWideMeetingOption(option) {
  return String(option?.option_type || option?.optionType || "") === "team_meeting"
    && isTeamMeetingGroupId(option?.group_id || option?.groupId);
}

function weekOptionOverlapAllowed(optionType, groupId, overlappingOption) {
  const creatingTeamMeeting = optionType === "team_meeting" && isTeamMeetingGroupId(groupId);
  const existingTeamMeeting = isTeamWideMeetingOption(overlappingOption);
  return (creatingTeamMeeting && overlappingOption.option_type === "sick")
    || (optionType === "sick" && existingTeamMeeting);
}

function assertApprovedAbsenceEntryAccess(session, optionType) {
  if (session?.role !== "location_planner") return;
  if (!session.permissions?.includes("absence_entries:write")) {
    throw httpError(
      403,
      "Für die direkte Erfassung bereits genehmigter Abwesenheiten fehlt die Berechtigung.",
      "APPROVED_ABSENCE_PERMISSION_DENIED",
    );
  }
  if (!directlyApprovedAbsenceOptionTypes.has(String(optionType || ""))) {
    throw httpError(
      403,
      "Die Planungsverantwortung darf hier ausschließlich bereits genehmigten Urlaub oder vereinbarten Zeitausgleich eintragen.",
      "APPROVED_ABSENCE_TYPE_DENIED",
    );
  }
}

function approvedAbsenceAuditDetail(option) {
  const optionType = String(option.optionType || option.option_type || "");
  return JSON.stringify({
    employeeNumber: String(option.employeeNumber || option.employee_number || ""),
    optionType,
    dateFrom: String(option.dateFrom || option.date_from || ""),
    dateTo: String(option.dateTo || option.date_to || ""),
    allDay: Number(option.allDay ?? option.all_day ?? 1) === 1,
  });
}

async function auditApprovedAbsenceEntry(session, action, entityId, option) {
  const optionType = String(option.optionType || option.option_type || "");
  if (!directlyApprovedAbsenceOptionTypes.has(optionType)) return;
  (await auditPortal(
    session?.employeeNumber || "local",
    action,
    "approved_absence",
    String(entityId || ""),
    approvedAbsenceAuditDetail(option),
  ));
}

function optionIsAllDay(option) {
  return Number(option.all_day ?? 1) === 1;
}

function optionTimeRange(option) {
  if (optionIsAllDay(option)) return { start: "00:00", end: "23:59" };
  return { start: option.start_time, end: option.end_time };
}

function timeRangesOverlap(startA, endA, startB, endB) {
  return startA < endB && startB < endA;
}

function optionOverlapsTime(option, startTime, endTime) {
  if (optionIsAllDay(option)) return true;
  if (!isTime(option.start_time) || !isTime(option.end_time)) return true;
  return timeRangesOverlap(startTime, endTime, option.start_time, option.end_time);
}

async function validateWeekOption(body, existingId = 0, actor = null) {
  const employeeNumber = String(body.employeeNumber || "").trim();
  const weekStart = getMonday(String(body.weekStart || ""));
  const dateFrom = String(body.dateFrom || "");
  const dateTo = String(body.dateTo || "");
  const optionType = String(body.optionType || "");
  const note = String(body.note || "").trim();
  const groupId = String(body.groupId || "").trim() || null;
  const allDay = alwaysFullDayOptionTypes.has(optionType) || body.allDay === true;
  const startTime = String(body.startTime || "");
  const endTime = String(body.endTime || "");
  const manualHours = body.manualHours === "" || body.manualHours === undefined
    ? null
    : Number(body.manualHours);

  const employee = await planningSettingsRepository.getPlanningEmployee({ employeeNumber });
  if (!employee) {
    throw httpError(404, "Die ausgewählte Person wurde nicht gefunden.");
  }
  if (!isIsoDate(dateFrom) || !isIsoDate(dateTo) || dateTo < dateFrom) {
    throw httpError(400, "Bitte einen gültigen Zeitraum eingeben.");
  }
  if (dateFrom < weekStart || dateTo > addDays(weekStart, 6)) {
    throw httpError(400, "Der Zeitraum muss innerhalb der ausgewählten Woche liegen.");
  }
  await assertWeekEditable(
    weekStart,
    await settingsForLocation(employee.home_location_id),
    actor,
    employee.home_location_id,
  );
  if (!allowedWeekOptionTypes.includes(optionType)) throw httpError(400, "Bitte eine gültige Option auswählen.");
  if (!alwaysFullDayOptionTypes.has(optionType) && !timedOptionTypes.has(optionType)) {
    throw httpError(400, "Bitte eine gültige Option auswählen.");
  }
  if (!allDay) {
    if (!isTime(startTime) || !isTime(endTime) || endTime <= startTime) {
      throw httpError(400, "Bitte eine gültige Uhrzeit für die Planungsoption eingeben.");
    }
  }
  if (allDay && manualAllDayCreditTypes.has(optionType)) {
    if (!Number.isFinite(manualHours) || manualHours < 0 || manualHours > 24) {
      throw httpError(400, "Bitte die anrechenbaren Stunden pro Tag zwischen 0 und 24 eingeben.");
    }
  }
  if (directlyApprovedAbsenceOptionTypes.has(optionType)) {
    const assignment = (await sqliteEmployeeLocationLendingOperations.overlapForPeriod({
      employeeNumber,
      dateFrom,
      dateTo,
      allDay,
      startTime: allDay ? null : startTime,
      endTime: allDay ? null : endTime,
    }));
    if (assignment) {
      throw httpError(
        409,
        optionType === "time_off"
          ? "Während eines temporären Filialeinsatzes muss ZA über den regulären ZA-Antrag an die zuständige Zielfiliale gestellt werden."
          : "Während eines temporären Filialeinsatzes kann genehmigter Urlaub hier nicht direkt eingetragen werden.",
        "STAFF_ASSIGNMENT_DIRECT_ABSENCE_CONFLICT",
      );
    }
  }
  const overlappingOptions = await planningSettingsRepository.listOverlappingWeekOptions({
    employeeNumber,
    dateFrom,
    dateTo,
    existingId: Number(existingId || 0),
    excludedGroupId: isTeamMeetingGroupId(groupId) ? groupId : null,
  });
  const overlappingOption = overlappingOptions.some((option) => (
      (allDay || optionOverlapsTime(option, startTime, endTime))
      && !weekOptionOverlapAllowed(optionType, groupId, option)
    ));
  if (overlappingOption) {
    throw httpError(409, "Für diesen Zeitraum ist bereits eine überschneidende Planungsoption eingetragen.");
  }
  let sicknessOverlap = optionType === "team_meeting" && isTeamMeetingGroupId(groupId)
    && overlappingOptions.some((option) => option.option_type === "sick");
  if (!sicknessOverlap && optionType === "team_meeting" && isTeamMeetingGroupId(groupId)) {
    for (let date = dateFrom; date <= dateTo; date = addDays(date, 1)) {
      if ((await activeSicknessEmployeeNumbers(date)).has(employeeNumber)) {
        sicknessOverlap = true;
        break;
      }
    }
  }
  const existingShift = sicknessOverlap ? null : (await planningSettingsRepository.listShiftConflictsForRange({
    employeeNumber,
    dateFrom,
    dateTo,
  }))
    .find((shift) => allDay || timeRangesOverlap(startTime, endTime, shift.start_time, shift.end_time));
  if (existingShift) {
    throw httpError(
      409,
      `Für ${existingShift.shift_date} ist bereits ein Dienst von ${existingShift.start_time} bis ${existingShift.end_time} Uhr eingetragen.`,
    );
  }

  const governanceExcludeGroupId = String(body.groupId || "").trim()
    || (existingId ? `legacy-${existingId}` : null);
  if (optionType === "vacation") {
    await assertVacationGovernanceAvailable(
      employeeNumber,
      { dateFrom, dateTo },
      governanceExcludeGroupId,
    );
  } else if (optionType === "time_off") {
    await assertDirectTimeOffGovernanceAvailable(
      employeeNumber,
      { dateFrom, dateTo, allDay, startTime, endTime },
      governanceExcludeGroupId,
    );
  }

  return {
    employeeNumber,
    weekStart,
    dateFrom,
    dateTo,
    optionType,
    note,
    groupId,
    allDay: allDay ? 1 : 0,
    startTime: allDay ? null : startTime,
    endTime: allDay ? null : endTime,
    creditedMinutesPerDay: allDay && manualAllDayCreditTypes.has(optionType) ? Math.round(manualHours * 60) : null,
  };
}

function optionMinutesPerDay(option, contractedHours) {
  if (alwaysFullDayOptionTypes.has(option.option_type)) {
    return Math.round((Number(contractedHours) * 60) / 5);
  }
  if (option.option_type === "time_off") return 0;
  if (!optionIsAllDay(option) && isTime(option.start_time) && isTime(option.end_time)) {
    return Math.max(0, timeToMinutes(option.end_time) - timeToMinutes(option.start_time));
  }
  return Math.max(0, Number(option.credited_minutes_per_day || 0));
}

function vacationDayCount(dateFrom, dateTo, locationId = null) {
  // Product rule: every holiday in the booked range reduces the vacation balance,
  // including holidays that fall on a weekend.
  let weekdays = 0;
  let holidays = 0;
  for (let date = dateFrom; date <= dateTo; date = addDays(date, 1)) {
    const day = new Date(`${date}T12:00:00Z`).getUTCDay();
    if (day !== 0 && day !== 6) weekdays += 1;
    if (isVacationHoliday(date, locationId)) holidays += 1;
  }
  return Math.max(0, weekdays - holidays);
}

function countCreditedOptionDaysInRange(
  option,
  rangeStart,
  rangeEnd,
  locationId = null,
) {
  return creditedOptionDatesInRange(
    option,
    rangeStart,
    rangeEnd,
    locationId,
  ).length;
}

function creditedOptionDatesInRange(
  option,
  rangeStart,
  rangeEnd,
  locationId = null,
) {
  const optionStart = String(option?.date_from || "");
  const optionEnd = String(option?.date_to || "");
  if (!isIsoDate(optionStart) || !isIsoDate(optionEnd) || optionEnd < optionStart) return [];
  const dateFrom = optionStart < rangeStart ? rangeStart : optionStart;
  const dateTo = optionEnd > rangeEnd ? rangeEnd : optionEnd;
  if (dateTo < dateFrom) return [];
  const dates = [];
  for (let date = dateFrom; date <= dateTo; date = addDays(date, 1)) {
    if (option.option_type === "vacation") {
      if (vacationDayCount(date, date, locationId) === 1) dates.push(date);
      continue;
    }
    if (new Date(`${date}T12:00:00Z`).getUTCDay() !== 0) dates.push(date);
  }
  return optionIsAllDay(option) && alwaysFullDayOptionTypes.has(option.option_type)
    ? dates.slice(0, 5)
    : dates;
}

function claimEmployeeDate(
  employeeNumber,
  date,
  blockedEmployeeDates,
  claimedEmployeeDates,
) {
  if (!isIsoDate(date)) return false;
  const key = `${employeeNumber}|${date}`;
  if (blockedEmployeeDates.has(key) || claimedEmployeeDates.has(key)) return false;
  claimedEmployeeDates.add(key);
  return true;
}

function employeeDateHasSickness(options, sicknessCreditDates, employeeNumber, date) {
  const key = `${employeeNumber}|${date}`;
  if (sicknessCreditDates?.has(key)) return true;
  return options.some((option) => (
    option.employee_number === employeeNumber
    && option.option_type === "sick"
    && date >= option.date_from
    && date <= option.date_to
  ));
}

function claimCreditedOptionDaysInRange(
  option,
  rangeStart,
  rangeEnd,
  locationId,
  blockedEmployeeDates,
  claimedEmployeeDates,
) {
  let claimed = 0;
  for (const date of creditedOptionDatesInRange(
    option,
    rangeStart,
    rangeEnd,
    locationId,
  )) {
    if (claimEmployeeDate(
      option.employee_number,
      date,
      blockedEmployeeDates,
      claimedEmployeeDates,
    )) claimed += 1;
  }
  return claimed;
}

function hasNonVacationCreditOnDate(options, employeeNumber, date) {
  return options.some((option) =>
    option.employee_number === employeeNumber &&
    option.option_type !== "vacation" &&
    date >= option.date_from &&
    date <= option.date_to &&
    optionMinutesPerDay(option, option.contracted_hours) > 0,
  );
}

function countSaturdaysInRange(startDate, endDate) {
  if (!startDate || !endDate || startDate > endDate) return 0;
  let count = 0;
  for (let date = startDate; date <= endDate; date = addDays(date, 1)) {
    if (new Date(`${date}T12:00:00Z`).getUTCDay() === 6) count += 1;
  }
  return count;
}

function saturdayShiftFilterSql(context, prefix = "s") {
  const clauses = [
    "strftime('%w', shift_date) = '6'",
    "((CAST(substr(end_time, 1, 2) AS INTEGER) * 60 + CAST(substr(end_time, 4, 2) AS INTEGER)) - (CAST(substr(start_time, 1, 2) AS INTEGER) * 60 + CAST(substr(start_time, 4, 2) AS INTEGER))) >= 120",
  ];
  if (context.departmentId) clauses.push(`${prefix}.department_id = ?`);
  return clauses.join(" AND ");
}

async function buildSaturdayServiceStats(weekStart, context, employees, currentWeekShifts, settings) {
  const employeeNumbers = employees.map((employee) => employee.personnel_number);
  if (!employeeNumbers.length || !settingEnabled(settings, "show_saturday_service_stats")) {
    return { byEmployee: {}, estimated: false };
  }
  const employeeNumberSet = new Set(employeeNumbers);
  const history = (await planningSettingsRepository.listSaturdayServiceShifts({
    locationId: context.locationId,
    departmentId: context.departmentId || null,
    endDate: addDays(weekStart, -1),
  })).filter((shift) => employeeNumberSet.has(shift.employee_number));
  const earliest = history[0]?.shift_date || null;
  const saturdayDate = addDays(weekStart, 5);
  const currentSaturdayStaff = new Set(
    currentWeekShifts
      .filter((shift) => shift.shift_date === saturdayDate)
      .filter((shift) => (shift.raw_minutes || 0) >= 120)
      .map((shift) => shift.employee_number),
  ).size;
  const fallbackStaffPerSaturday = Math.max(
    currentSaturdayStaff,
    Math.min(employees.length, Math.max(2, Number((await dayConfiguration(saturdayDate, settings, context))?.minStaff || 0))),
  );
  const fallbackPerEmployee = employees.length ? fallbackStaffPerSaturday / employees.length : 0;

  function statsForWindow(startDate, endDate) {
    const totalSaturdays = countSaturdaysInRange(startDate, endDate);
    const complete = Boolean(earliest && earliest <= startDate);
    const observedStart = earliest && earliest > startDate ? earliest : startDate;
    const observedSaturdays = earliest && observedStart <= endDate ? countSaturdaysInRange(observedStart, endDate) : 0;
    const values = Object.fromEntries(employeeNumbers.map((number) => [number, 0]));
    if (earliest && observedStart <= endDate) {
      const datesByEmployee = new Map(employeeNumbers.map((number) => [number, new Set()]));
      for (const shift of history) {
        if (shift.shift_date < observedStart || shift.shift_date > endDate) continue;
        if (new Date(`${shift.shift_date}T12:00:00Z`).getUTCDay() !== 6) continue;
        if (timeToMinutes(shift.end_time) - timeToMinutes(shift.start_time) < 120) continue;
        datesByEmployee.get(shift.employee_number)?.add(shift.shift_date);
      }
      for (const number of employeeNumbers) values[number] = datesByEmployee.get(number).size;
    }
    const estimated = !complete;
    const fallbackValue = estimated && observedSaturdays === 0 ? totalSaturdays * fallbackPerEmployee : 0;
    return {
      estimated,
      values: Object.fromEntries(
        employeeNumbers.map((number) => [
          number,
          estimated
            ? observedSaturdays > 0
              ? values[number] * (totalSaturdays / observedSaturdays)
              : fallbackValue
            : values[number],
        ]),
      ),
    };
  }

  const fourWeeks = statsForWindow(addDays(weekStart, -28), addDays(weekStart, -1));
  const threeMonths = statsForWindow(addMonths(weekStart, -3), addDays(weekStart, -1));
  return {
    byEmployee: Object.fromEntries(
      employeeNumbers.map((number) => [
        number,
        {
          fourWeeks: fourWeeks.values[number] || 0,
          fourWeeksEstimated: fourWeeks.estimated,
          threeMonths: threeMonths.values[number] || 0,
          threeMonthsEstimated: threeMonths.estimated,
        },
      ]),
    ),
    estimated: fourWeeks.estimated || threeMonths.estimated,
  };
}

function workRuleEvaluationRange(weekStart) {
  return {
    start: addDays(weekStart, -(16 * 7)),
    end: addDays(weekStart, 6),
  };
}

function workRuleFindingTouchesPeriod(finding, periodFrom, periodTo) {
  const scope = finding?.scope || {};
  const evidence = finding?.evidence || {};
  const date = String(scope.date || evidence.date || "");
  if (isIsoDate(date)) return date >= periodFrom && date <= periodTo;
  if (Array.isArray(scope.dates) && scope.dates.some((entry) => (
    isIsoDate(entry) && entry >= periodFrom && entry <= periodTo
  ))) return true;
  const from = String(scope.start || scope.weekStart || scope.from || "").slice(0, 10);
  const to = String(scope.end || scope.weekEnd || scope.to || "").slice(0, 10);
  if (isIsoDate(from) && isIsoDate(to)) return from <= periodTo && to >= periodFrom;
  return ["employee", "evaluation_range"].includes(scope.type)
    || ["at.applicability.adult", "at.applicability.youth", "at.input.shift"].includes(finding?.ruleId);
}

function presentWorkRuleFinding(finding, employeeNumber, employeeName, catalog, periodFrom, periodTo) {
  const displayState = finding.state === "pass"
    ? "pass"
    : (finding.state === "unknown"
      ? "manual_review"
      : (finding.effectiveEnforcement === "block" ? "blocked" : "attention"));
  const ageNotConfirmed = finding?.evidence?.reason === "age_not_confirmed"
    && ["at.applicability.adult", "at.applicability.youth"].includes(finding?.ruleId);
  return {
    ...finding,
    resultState: finding.state,
    state: displayState,
    title: ageNotConfirmed
      ? "Geburtsdatum im Personalakt ergänzen"
      : (catalog.rules[finding.ruleId]?.title || finding.ruleId),
    employeeNumber,
    employeeName,
    periodFrom,
    periodTo,
    category: ageNotConfirmed ? "personnel_data" : "schedule_rule",
    snoozable: ageNotConfirmed,
    snoozeDays: ageNotConfirmed ? 4 : null,
  };
}

async function scheduleWorkRuleFacts(weekStart, context, employees, candidateShift = null) {
  const range = workRuleEvaluationRange(weekStart);
  const employeeNumbers = [...new Set(employees.map((employee) => String(employee.personnel_number)))];
  if (!employeeNumbers.length) {
    return { range, employees: [], shifts: [], holidays: [], candidateShift: null };
  }
  const employeeNumberSet = new Set(employeeNumbers);
  let shifts = (await planningSettingsRepository.listWorkRuleShiftsForRange({
    dateFrom: range.start,
    dateTo: range.end,
  })).filter((shift) => employeeNumberSet.has(String(shift.employee_number)));

  const deletedShiftIds = new Set(
    Array.isArray(candidateShift?.deletedShiftIds)
      ? candidateShift.deletedShiftIds.map((id) => String(id))
      : [],
  );
  if (candidateShift?.deleted === true && candidateShift.id) {
    deletedShiftIds.add(String(candidateShift.id));
  }
  if (deletedShiftIds.size) {
    shifts = shifts.filter((shift) => !deletedShiftIds.has(String(shift.id)));
  }
  const replaceRange = candidateShift?.replaceRange;
  if (replaceRange) {
    shifts = shifts.filter((shift) => !(
      shift.shift_date >= replaceRange.dateFrom
      && shift.shift_date <= replaceRange.dateTo
      && String(shift.location_id || "") === String(replaceRange.locationId || "")
      && (!replaceRange.departmentId
        || Number(shift.department_id || 0) === Number(replaceRange.departmentId))
    ));
  }
  const batchedPlanningShifts = Array.isArray(candidateShift?.addedShifts);
  const submittedShifts = batchedPlanningShifts
    ? candidateShift.addedShifts
    : (candidateShift && candidateShift.deleted !== true && !replaceRange
      ? [candidateShift]
      : []);
  for (const [index, submitted] of submittedShifts.entries()) {
    if (!submitted || typeof submitted !== "object") continue;
    const submittedEmployeeNumber = String(
      submitted.employeeNumber ?? submitted.employee_number ?? "",
    );
    const submittedShiftDate = String(
      submitted.shiftDate ?? submitted.shift_date ?? "",
    );
    const candidateId = Number(submitted.id || 0);
    if (candidateId) shifts = shifts.filter((shift) => Number(shift.id) !== candidateId);
    if (!employeeNumbers.includes(submittedEmployeeNumber)
      || submittedShiftDate < range.start
      || submittedShiftDate > range.end) continue;
    shifts.push({
      id: candidateId
        ? `candidate-${candidateId}`
        : (batchedPlanningShifts ? `candidate-new-${index}` : "candidate-new"),
      employee_number: submittedEmployeeNumber,
      location_id: submitted.locationId ?? submitted.location_id,
      department_id: submitted.departmentId ?? submitted.department_id ?? null,
      duty_code: submitted.dutyCode ?? submitted.duty_code ?? "",
      shift_date: submittedShiftDate,
      start_time: submitted.startTime ?? submitted.start_time,
      end_time: submitted.endTime ?? submitted.end_time,
    });
  }

  const normalizedShifts = await Promise.all(shifts.map(async (shift) => {
    const metrics = await shiftMetrics(shift, await settingsForLocation(shift.location_id || context.locationId));
    return {
      id: String(shift.id),
      employeeId: String(shift.employee_number),
      date: shift.shift_date,
      startTime: shift.start_time,
      endTime: shift.end_time,
      breakMinutes: metrics.break_minutes,
      breakSource: metrics.lunch_break_minutes > 0 ? "planned_window" : (metrics.break_minutes > 0 ? "configured_assumption" : "none"),
      locationId: String(shift.location_id || ""),
      departmentId: shift.department_id ? Number(shift.department_id) : null,
      dutyCode: String(shift.duty_code || ""),
    };
  }));
  const holidays = getGlobalDayBlocksForRange(range.start, range.end, context.locationId)
    .filter((block) => block.is_public_holiday)
    .map((block) => block.block_date);
  return {
    range,
    employees: employeeNumbers,
    shifts: normalizedShifts,
    holidays,
    candidateShift: candidateShift && !batchedPlanningShifts
      && candidateShift.deleted !== true && !replaceRange ? {
      employeeNumber: candidateShift.employeeNumber,
      date: candidateShift.shiftDate,
      startTime: candidateShift.startTime,
      endTime: candidateShift.endTime,
    } : null,
  };
}

function workRuleEvaluationEmployees(employees, candidateShift = null) {
  const result = Array.isArray(employees) ? [...employees] : [];
  const candidateEmployeeNumber = String(candidateShift?.employeeNumber || "").trim();
  if (!candidateEmployeeNumber
    || result.some((employee) => String(employee.personnel_number) === candidateEmployeeNumber)) return result;
  const candidateEmployee = portalScopeProjectionSnapshot.employees.find((employee) => (
    String(employee.personnel_number) === candidateEmployeeNumber
    && Boolean(employee.active)
  ));
  if (candidateEmployee) result.push(candidateEmployee);
  return result;
}

function workRuleAssignmentGroups(facts, context, employeeNumber, assignments, birthDate = "") {
  const groups = new Map();
  const defaultProfile = getBuiltinWorkRuleProfile("at-retail-adult-monitor");
  const youthProfile = getBuiltinWorkRuleProfile("at-retail-youth-monitor");
  const defaultAssignment = {
    id: null,
    profileId: defaultProfile.id,
    profileVersionId: profileVersionId(defaultProfile),
    enforcementMode: "monitor",
    applicabilityConfirmed: false,
  };
  const employeeShifts = facts.shifts.filter((shift) => shift.employeeId === employeeNumber);
  for (let date = facts.range.start; date <= facts.range.end; date = addDays(date, 1)) {
    const dateShifts = employeeShifts.filter((shift) => shift.date === date);
    const dateContexts = new Map();
    if (dateShifts.length) {
      for (const shift of dateShifts) {
        const value = {
          locationId: String(shift.locationId || context.locationId),
          departmentId: Number(shift.departmentId || 0) || null,
        };
        const key = `${value.locationId}|${value.departmentId || ""}`;
        if (!dateContexts.has(key)) dateContexts.set(key, { ...value, shiftIds: [] });
        dateContexts.get(key).shiftIds.push(String(shift.id));
      }
    } else {
      dateContexts.set(`${context.locationId}|${context.departmentId || ""}`, {
        locationId: context.locationId,
        departmentId: context.departmentId,
        shiftIds: [],
      });
    }
    for (const dateContext of dateContexts.values()) {
      const resolvedAssignments = resolveWorkRuleAssignmentsFromList(assignments, {
        date,
        locationId: dateContext.locationId,
        departmentId: dateContext.departmentId,
        employeeNumber,
      });
      if (!resolvedAssignments.some((assignment) => (
        ["at-retail-adult-monitor", "at-retail-youth-monitor"].includes(String(
          assignment.profileId || String(assignment.profileVersionId || "").split("@")[0],
        ))
      ))) resolvedAssignments.push(defaultAssignment);
      const age = workRuleAgeOnDate(String(birthDate || ""), date);
      for (const assignment of resolvedAssignments) {
        const assignedProfileId = String(
          assignment.profileId || String(assignment.profileVersionId || "").split("@")[0],
        );
        const useAutomaticYouthProfile = age !== null
          && age < 18
          && assignedProfileId === "at-retail-adult-monitor";
        const effectiveAssignment = useAutomaticYouthProfile
          ? {
            ...assignment,
            profileId: youthProfile.id,
            profileVersionId: profileVersionId(youthProfile),
            applicabilityConfirmed: true,
            automaticByBirthDate: true,
          }
          : assignment;
        const key = [
          effectiveAssignment.profileVersionId,
          effectiveAssignment.enforcementMode || "monitor",
          effectiveAssignment.applicabilityConfirmed === true ? "confirmed" : "unconfirmed",
        ].join("|");
        if (!groups.has(key)) {
          groups.set(key, {
            assignmentIds: new Set(),
            dates: new Set(),
            shiftIds: new Set(),
            profileVersionId: effectiveAssignment.profileVersionId,
            profileId: effectiveAssignment.profileId || assignedProfileId,
            enforcementMode: effectiveAssignment.enforcementMode || "monitor",
            applicabilityConfirmed: effectiveAssignment.applicabilityConfirmed === true,
            automaticByBirthDate: effectiveAssignment.automaticByBirthDate === true,
            assignment: {
              id: effectiveAssignment.id || "",
              scopeType: effectiveAssignment.scopeType || "installation",
              scopeKey: effectiveAssignment.scopeKey || "",
              validFrom: effectiveAssignment.validFrom || facts.range.start,
              validTo: effectiveAssignment.validTo || null,
              enforcementMode: effectiveAssignment.enforcementMode || "monitor",
              applicabilityConfirmed: effectiveAssignment.applicabilityConfirmed === true,
            },
          });
        }
        const group = groups.get(key);
        if (effectiveAssignment.id) group.assignmentIds.add(effectiveAssignment.id);
        group.dates.add(date);
        for (const shiftId of dateContext.shiftIds) group.shiftIds.add(shiftId);
      }
    }
  }
  return [...groups.values()];
}

function workRuleFindingAppliesToDates(finding, dates, targetFrom, targetTo) {
  const assignedDates = dates instanceof Set ? dates : new Set(dates || []);
  const containsRange = (from, to = from) => {
    if (!isIsoDate(from) || !isIsoDate(to)) return false;
    for (let date = from; date <= to; date = addDays(date, 1)) {
      if (!assignedDates.has(date)) return false;
    }
    return true;
  };
  const scope = finding?.scope || {};
  const evidence = finding?.evidence || {};
  const directDate = String(scope.date || evidence.date || "").slice(0, 10);
  if (isIsoDate(directDate)) return assignedDates.has(directDate);
  const from = String(scope.start || scope.weekStart || scope.from || "").slice(0, 10);
  const to = String(scope.end || scope.weekEnd || scope.to || "").slice(0, 10);
  if (isIsoDate(from)) return containsRange(from, isIsoDate(to) ? to : from);
  for (const date of assignedDates) {
    if (date >= targetFrom && date <= targetTo) return true;
  }
  return false;
}

function workRuleAssignmentBoundaryFinding(profileEvaluations, employeeNumber, range) {
  if (!Array.isArray(profileEvaluations) || profileEvaluations.length < 2) return null;
  const assignments = profileEvaluations.map((entry) => {
    const dates = [...entry.dates].sort();
    return {
      profileVersionId: entry.profileVersionId,
      enforcementMode: entry.enforcementMode,
      applicabilityConfirmed: entry.applicabilityConfirmed,
      dateFrom: dates[0] || null,
      dateTo: dates.at(-1) || null,
    };
  });
  const primary = profileEvaluations[0];
  const core = {
    ruleId: "at.system.profile-boundary",
    profileId: primary.profile.id,
    profileVersion: primary.profile.version,
    state: "unknown",
    severity: "warning",
    baseEnforcement: "manual_review",
    effectiveEnforcement: profileEvaluations.some((entry) => entry.enforcementMode === "enforced")
      ? "manual_review"
      : "advisory",
    message: "Im Prüfzeitraum wechseln Regelprofil oder Durchsetzungsmodus. Wochen-, Durchschnitts- und Ruhezeitgrenzen müssen an der Profilgrenze fachlich geprüft werden.",
    scope: {
      type: "evaluation_range",
      start: range.start,
      end: range.end,
    },
    evidence: {
      metric: "profile_assignment_continuity",
      employeeNumber,
      assignments,
    },
    sourceRefs: [],
  };
  return { ...core, fingerprint: workRuleSha256(core) };
}

async function evaluateScheduleWorkRules(weekStart, context, employees, candidateShift = null) {
  const evaluationEmployees = workRuleEvaluationEmployees(employees, candidateShift);
  const facts = await scheduleWorkRuleFacts(weekStart, context, evaluationEmployees, candidateShift);
  const weekEnd = addDays(weekStart, 6);
  const catalog = getRuleCatalog();
  const assignments = [
    ...await listWorkRuleAssignments(workRuleStoreRepository),
    ...await listGovernedWorkRuleAssignments(workRuleGovernanceRepository),
  ];
  const employeeResults = await Promise.all(evaluationEmployees.map(async (employee) => {
    const employeeNumber = String(employee.personnel_number);
    const sensitive = await personnelSensitiveProfile(employeeNumber);
    const groups = workRuleAssignmentGroups(
      facts,
      context,
      employeeNumber,
      assignments,
      sensitive.identity.birthDate || "",
    );
    const profileEvaluations = await Promise.all(groups.map(async (group) => {
      const version = await getWorkRuleProfileVersion(
        workRuleStoreRepository,
        group.profileVersionId,
      );
      const profile = version?.profile || getBuiltinWorkRuleProfile(
        version?.profileId || String(group.profileVersionId || "").split("@")[0],
      );
      if (!profile) throw new Error(`Die zugewiesene Regelprofil-Version ${group.profileVersionId} ist nicht auswertbar.`);
      const shifts = facts.shifts.filter((shift) => (
        shift.employeeId === employeeNumber && group.shiftIds.has(String(shift.id))
      ));
      const rangeStart = [...group.dates].sort()[0] || facts.range.start;
      const rangeEnd = [...group.dates].sort().at(-1) || facts.range.end;
      const customProfile = profile.applicability?.sector === "custom"
        || String(profile.id || "").startsWith("custom:");
      const evaluated = customProfile
        ? evaluateCustomPlannedSchedule({
          profile: {
            ...profile,
            rules: version?.rules || [],
            sources: version?.sources || [],
          },
          assignment: group.assignment,
          shifts,
          employee: {
            id: employeeNumber,
            birthDate: sensitive.identity.birthDate || undefined,
            positionId: employee.position_id || undefined,
            isApprentice: employee.position_employment_classification === "apprentice",
          },
          employeeNumber,
          locationId: context.locationId,
          departmentId: context.departmentId,
          rangeStart,
          rangeEnd,
        })
        : evaluatePlannedSchedule({
          basis: "planned_schedule",
          profileId: profile.id,
          profile,
          enforcementMode: group.enforcementMode,
          shifts,
          employee: {
            id: employeeNumber,
            birthDate: sensitive.identity.birthDate || undefined,
            positionId: employee.position_id || undefined,
            isApprentice: employee.position_employment_classification === "apprentice",
          },
          rangeStart,
          rangeEnd,
          holidays: facts.holidays,
          applicabilityConfirmed: group.applicabilityConfirmed,
          timeZone: "Europe/Vienna",
          ruleDefinitions: version?.rules,
          sourceCatalog: version?.sources,
        });
      return {
        ...group,
        assignmentIds: [...group.assignmentIds],
        shiftIds: [...group.shiftIds],
        profile,
        layer: version?.layer || "law",
        sources: version?.sources || [],
        result: {
          ...evaluated,
          findings: evaluated.findings.filter((finding) => workRuleFindingAppliesToDates(
            finding,
            group.dates,
            weekStart,
            weekEnd,
          )),
        },
      };
    }));
    const findings = profileEvaluations.flatMap((entry) => entry.result.findings);
    const boundaryFinding = workRuleAssignmentBoundaryFinding(
      profileEvaluations.filter((entry) => String(entry.profile?.id || "").startsWith("at-retail-")),
      employeeNumber,
      facts.range,
    );
    if (boundaryFinding) findings.push(boundaryFinding);
    const primary = profileEvaluations.find((entry) => (
      [...entry.dates].some((date) => date >= weekStart && date <= weekEnd)
    )) || profileEvaluations[0];
    const resultCore = {
      engineVersion: WORK_RULE_ENGINE_VERSION,
      catalogVersion: catalog.version,
      basis: "planned_schedule",
      timeZone: "Europe/Vienna",
      profile: primary?.result.profile || { id: "unassigned", version: "unknown" },
      enforcementMode: profileEvaluations.some((entry) => entry.result.enforcementMode === "enforced")
        ? "enforced"
        : "monitor",
      range: { start: facts.range.start, end: facts.range.end, valid: true },
      employeeId: employeeNumber,
      findings,
      profileAssignments: profileEvaluations.map((entry) => ({
        assignmentIds: entry.assignmentIds,
        profileVersionId: entry.profileVersionId,
        enforcementMode: entry.enforcementMode,
        applicabilityConfirmed: entry.applicabilityConfirmed,
        dates: [...entry.dates].sort(),
      })),
    };
    const result = {
      ...resultCore,
      summary: summarizeWorkRuleFindings(findings),
      fingerprint: workRuleSha256(resultCore),
      legalNotice: catalog.legalNotice,
    };
    return {
      employeeNumber,
      employeeName: employee.nickname || employee.full_name || employeeNumber,
      profileVersionIds: profileEvaluations.map((entry) => entry.profileVersionId),
      profileEvaluations: profileEvaluations.map((entry) => ({
        profileVersionId: entry.profileVersionId,
        profile: entry.profile,
        layer: entry.layer,
        sources: entry.sources,
      })),
      result,
    };
  }));

  const allFindings = employeeResults.flatMap((entry) => entry.result.findings);
  const presentationFindings = [];
  for (const entry of employeeResults) {
    const applicability = entry.result.findings.find((finding) => (
      ["at.applicability.adult", "at.applicability.youth"].includes(finding.ruleId)
    ));
    const profileUnconfirmed = applicability?.evidence?.reason === "profile_not_confirmed";
    const ageUnconfirmed = applicability?.evidence?.reason === "age_not_confirmed";
    const candidates = profileUnconfirmed
      ? [applicability]
      : (ageUnconfirmed
        ? [
          applicability,
          ...entry.result.findings.filter((finding) => (
            finding !== applicability
            && workRuleFindingTouchesPeriod(finding, weekStart, weekEnd)
            && (
              finding.evidence?.conditionalResult === "fail"
              || finding.ruleId === "at.system.profile-boundary"
            )
          )),
        ]
        : entry.result.findings.filter((finding) => (
          finding.state !== "pass" && workRuleFindingTouchesPeriod(finding, weekStart, weekEnd)
        )));
    const seen = new Set();
    for (const finding of candidates.filter(Boolean)) {
      const key = `${finding.ruleId}|${finding.scope?.type || ""}|${finding.scope?.date || finding.scope?.weekStart || finding.scope?.start || ""}`;
      if (seen.has(key)) continue;
      seen.add(key);
      presentationFindings.push(presentWorkRuleFinding(
        finding,
        entry.employeeNumber,
        entry.employeeName,
        catalog,
        weekStart,
        weekEnd,
      ));
    }
  }

  const hasBlocked = allFindings.some((finding) => finding.state === "fail" && finding.effectiveEnforcement === "block");
  const hasUnknown = allFindings.some((finding) => finding.state === "unknown");
  const hasManual = allFindings.some((finding) => finding.state === "fail"
    && ["manual_review", "exception_required", "acknowledge"].includes(finding.baseEnforcement));
  const hasFailure = allFindings.some((finding) => finding.state === "fail");
  const outcome = hasBlocked ? "blocked" : ((hasUnknown || hasManual) ? "manual_review" : (hasFailure ? "attention" : "pass"));
  const employeeOutcome = (entry) => {
    const findings = entry.result.findings;
    if (findings.some((finding) => finding.state === "fail" && finding.effectiveEnforcement === "block")) return "blocked";
    if (findings.some((finding) => finding.state === "unknown"
      || (finding.state === "fail" && ["manual_review", "exception_required", "acknowledge"].includes(finding.baseEnforcement)))) return "manualReview";
    if (findings.some((finding) => finding.state === "fail")) return "attention";
    return "pass";
  };
  const counts = { pass: 0, attention: 0, manualReview: 0, blocked: 0 };
  for (const entry of employeeResults) counts[employeeOutcome(entry)] += 1;
  const profiles = [...new Map(employeeResults.flatMap((entry) => entry.profileEvaluations).map((entry) => {
    const builtin = BUILTIN_WORK_RULE_PROFILES[entry.profile.id];
    return [entry.profileVersionId, {
      id: entry.profile.id,
      version: entry.profile.version,
      versionId: entry.profileVersionId,
      name: catalog.profiles[entry.profile.id]?.title || entry.profile.title || entry.profile.id,
      title: catalog.profiles[entry.profile.id]?.title || entry.profile.title || entry.profile.id,
      layer: entry.layer === "company"
        ? "Unternehmensregel"
        : (entry.layer === "collective_agreement"
          ? "Kollektivvertrag"
          : (builtin?.applicability?.sector ? "Branchenprofil" : "Gesetzliches Profil")),
      sources: entry.sources.length ? entry.sources : (builtin?.sources || []),
    }];
  })).values()].filter((profile) => profile.id);
  const sources = [...new Map(presentationFindings.flatMap((finding) => finding.sourceRefs || [])
    .map((source) => [source.id, source])).values()];
  const mode = employeeResults.some((entry) => entry.result.enforcementMode === "enforced") ? "enforced" : "monitor";
  const assessment = {
    engineVersion: WORK_RULE_ENGINE_VERSION,
    catalogVersion: catalog.version,
    targetType: "planned_schedule",
    mode,
    outcome,
    periodFrom: weekStart,
    periodTo: weekEnd,
    evaluatedEmployees: employeeResults.length,
    counts,
    profiles,
    findings: presentationFindings,
    sources,
    disclaimer: catalog.legalNotice,
  };
  const receipt = {
    ...assessment,
    evaluationRange: facts.range,
    employeeResults,
  };
  return {
    assessment,
    receipt,
    inputSha256: workRuleSha256(facts),
    profileVersionIds: profiles.map((profile) => profile.versionId).filter(Boolean),
  };
}

async function recordEvaluatedWorkRuleEvaluation(repository, evaluated, context, actor) {
  if (!evaluated.profileVersionIds.length) return evaluated.assessment;
  await recordWorkRuleEvaluation(repository, {
    targetType: "planned_schedule",
    scopeType: context.departmentId ? "department" : "location",
    scopeKey: context.departmentId ? String(context.departmentId) : String(context.locationId),
    periodFrom: evaluated.assessment.periodFrom,
    periodTo: evaluated.assessment.periodTo,
    profileVersionIds: evaluated.profileVersionIds,
    inputSha256: evaluated.inputSha256,
    result: evaluated.receipt,
    outcome: evaluated.assessment.outcome,
    actor,
  });
  return evaluated.assessment;
}

function assertWorkRuleAssessmentAllowsMutation(assessment) {
  if (assessment?.outcome === "blocked") {
    throw httpError(
      409,
      "Die geplante Änderung verletzt eine aktiv durchgesetzte Arbeitszeitregel. Details stehen in der Arbeitszeit-Regelprüfung.",
      "WORK_RULE_PLAN_BLOCKED",
    );
  }
}

function runWorkRuleMutationTransaction(callback) {
  if (typeof callback !== "function") throw new TypeError("Eine Planungsmutation wird benötigt.");
  return workRuleStoreRepository.transaction(callback);
}

async function crossLocationSchedulePrincipal(
  session,
  repository = organizationPersonnelRepository,
) {
  if (!session || session.sessionKind !== "employee" || session.isEmployee !== true) return null;
  const [employee, scopeContext] = await Promise.all([
    repository.getEmployeeScopeProjection(session.employeeNumber),
    personnelLearningScopeContext(repository),
  ]);
  if (!employee) return null;
  return {
    employeeNumber: session.employeeNumber,
    role: session.role,
    active: true,
    configured: true,
    sessionKind: "employee",
    isEmployee: true,
    homeLocationId: String(employee.home_location_id || session.homeLocationId || ""),
    preferredDepartmentId: Number(employee.preferred_department_id || 0) || null,
    permissions: Array.isArray(session.permissions) ? session.permissions : [],
    effectiveScopes: personnelLearningEffectiveScopes({ scopes: session.scopes || [] }, scopeContext),
  };
}

function settingsObjectFromRows(rows = []) {
  return Object.fromEntries((Array.isArray(rows) ? rows : [])
    .map((row) => [String(row?.key || ""), String(row?.value ?? "")])
    .filter(([key]) => key));
}

async function crossLocationScheduleSettingsFromRepository(repository = planningSettingsRepository) {
  return normalizeCrossLocationScheduleSettings(
    settingsObjectFromRows(await repository.listSettings()),
  );
}

async function assertCrossLocationScheduleSettingsManagement(
  session,
  repository = organizationPersonnelRepository,
) {
  if (isLocalSystemSession(session)) return session;
  const actor = await crossLocationSchedulePrincipal(session, repository);
  const access = createCrossLocationScheduleAccessSnapshot(actor || {});
  if (!access.canManageSettings) {
    throw httpError(
      403,
      "Die Dienstplan-Einstellungen dürfen nur von einer persönlichen PL+-Sitzung mit wirksamem Einstellungsrecht geändert werden.",
      "CROSS_LOCATION_SCHEDULE_SETTINGS_DENIED",
    );
  }
  return actor;
}

function publicCrossLocationScheduleSettings(configurationValue) {
  const configuration = configurationValue?.horizonWeeks
    ? configurationValue
    : normalizeCrossLocationScheduleSettings(configurationValue);
  return {
    enabled: configuration.enabled,
    horizonWeeks: configuration.horizonWeeks,
    managerRequestCreateEnabled: configuration.managerRequestCreateEnabled,
    departmentManagerRequestCreateEnabled: configuration.departmentManagerRequestCreateEnabled,
    departmentManagerRequestReviewEnabled: configuration.departmentManagerRequestReviewEnabled,
    emailSubmittedEnabled: configuration.emailSubmittedEnabled,
    emailDecisionEnabled: configuration.emailDecisionEnabled,
    changePolicy: configuration.changePolicy,
    cancellationPolicy: configuration.cancellationPolicy,
  };
}

async function crossLocationScheduleSettingsPayload(session) {
  await assertCrossLocationScheduleSettingsManagement(
    session,
    organizationPersonnelRepository,
  );
  return publicCrossLocationScheduleSettings(
    normalizeCrossLocationScheduleSettings(getSettings()),
  );
}

async function updateCrossLocationScheduleSettings(session, input = {}) {
  let proposed;
  try {
    proposed = crossLocationScheduleSettingsValuesFromInput(input);
  } catch (error) {
    throw httpError(
      400,
      String(error?.message || "Die Dienstplan-Einstellungen sind ungültig."),
      "CROSS_LOCATION_SCHEDULE_SETTINGS_INVALID",
    );
  }
  const outcome = await persistenceProvider.transaction(async (executor) => {
    const repositories = createApplicationRepositories(executor);
    const organization = repositories.organizationPersonnel;
    let liveSession = session;
    if (!isLocalSystemSession(session)) {
      liveSession = await livePersonnelLearningRoleAdministrationActor(session, organization);
      assertLivePortalRoutePermission(
        liveSession,
        CROSS_LOCATION_SCHEDULE_PERMISSIONS.SETTINGS_WRITE,
      );
    }
    await assertCrossLocationScheduleSettingsManagement(liveSession, organization);
    const currentRows = await repositories.planningSettings.listSettings();
    const currentValues = settingsObjectFromRows(currentRows);
    const changedKeys = Object.keys(proposed).filter(
      (key) => String(currentValues[key] ?? CROSS_LOCATION_SCHEDULE_DEFAULT_SETTINGS[key] ?? "")
        !== String(proposed[key]),
    ).sort();
    if (!changedKeys.length) {
      return normalizeCrossLocationScheduleSettings({ ...currentValues, ...proposed });
    }
    for (const key of changedKeys) {
      await repositories.planningSettings.upsertSetting({ key, value: proposed[key] });
    }
    const before = normalizeCrossLocationScheduleSettings(currentValues);
    const after = normalizeCrossLocationScheduleSettings({ ...currentValues, ...proposed });
    await organization.insertAudit(
      liveSession?.employeeNumber || "local",
      "schedule.cross-location.settings.update",
      "schedule_settings",
      "cross_location",
      JSON.stringify({ changedKeys, before, after }),
    );
    return after;
  }, { isolation: "serializable" });
  await refreshPlanningSettingsReadModel();
  return publicCrossLocationScheduleSettings(outcome);
}

function publicCrossLocationScheduleLocations(locations, access) {
  const ownLocationId = String(access.organizationScope?.locationId || "");
  return locations
    .filter((location) => location.active && String(location.id || "") !== ownLocationId)
    .map((location) => ({
      id: String(location.id || ""),
      name: String(location.name || ""),
      departments: (location.departments || [])
        .filter((department) => department.active)
        .map((department) => ({ id: Number(department.id), name: String(department.name || "") })),
    }))
    .filter((location) => location.id && location.name)
    .sort((left, right) => left.name.localeCompare(right.name, "de-AT") || left.id.localeCompare(right.id));
}

function crossLocationScheduleEmployeeDepartment(employee, sourceLocationId, shifts, lendings) {
  const preferredDepartmentId = Number(employee.preferred_department_id || 0) || null;
  if (String(employee.home_location_id || "") === sourceLocationId && preferredDepartmentId) {
    return preferredDepartmentId;
  }
  const assignedShift = shifts.find((shift) => (
    String(shift.employee_number || "") === String(employee.personnel_number || "")
      && Number(shift.department_id || 0) > 0
  ));
  if (assignedShift) return Number(assignedShift.department_id);
  const incoming = lendings.find((lending) => (
    String(lending.employee_number || "") === String(employee.personnel_number || "")
      && String(lending.destination_location_id || "") === sourceLocationId
      && Number(lending.destination_department_id || 0) > 0
  ));
  return incoming ? Number(incoming.destination_department_id) : null;
}

async function crossLocationScheduleSource(location, weekStart) {
  const weekEnd = addDays(weekStart, 6);
  const locationId = String(location.id || "");
  const planningQuery = {
    locationId,
    departmentId: null,
    weekStart,
    weekEnd,
  };
  const [employees, shifts, weekOptions, lendings] = await Promise.all([
    planningSettingsRepository.listScheduleEmployees(planningQuery),
    planningSettingsRepository.listScheduleShifts(planningQuery),
    planningSettingsRepository.listScheduleWeekOptions(planningQuery),
    planningSettingsRepository.listScheduleLendings(planningQuery),
  ]);
  const departments = (location.departments || []).filter((department) => department.active);
  const departmentNames = new Map(
    departments.map((department) => [Number(department.id), String(department.name || "")]),
  );
  const teamMembers = employees.map((employee) => {
    const departmentId = crossLocationScheduleEmployeeDepartment(
      employee,
      locationId,
      shifts,
      lendings,
    );
    return {
      employeeNumber: String(employee.personnel_number || ""),
      displayName: String(employee.nickname || `MA ${employee.personnel_number || ""}`).trim(),
      departmentId,
      departmentName: departmentId ? departmentNames.get(departmentId) || "" : "",
      color: employee.color,
      requestEligible: String(employee.home_location_id || "") === locationId,
    };
  });
  const unavailability = [
    ...weekOptions.map((option) => ({
      employeeNumber: option.employee_number,
      dateFrom: option.date_from,
      dateTo: option.date_to,
      allDay: Number(option.all_day ?? 1) === 1,
      startTime: option.start_time,
      endTime: option.end_time,
    })),
    ...lendings
      .filter((lending) => String(lending.home_location_id || "") === locationId)
      .map((lending) => ({
        employeeNumber: lending.employee_number,
        dateFrom: lending.date_from,
        dateTo: lending.date_to,
        allDay: Number(lending.all_day ?? 1) === 1,
        startTime: lending.start_time,
        endTime: lending.end_time,
      })),
  ];
  return {
    location: { id: locationId, name: String(location.name || ""), active: Boolean(location.active) },
    departments,
    teamMembers,
    shifts: shifts.map((shift) => ({
      employeeNumber: shift.employee_number,
      date: shift.shift_date,
      startTime: shift.start_time,
      endTime: shift.end_time,
      departmentId: Number(shift.department_id || 0) || null,
      departmentName: String(shift.department_name || ""),
    })),
    unavailability,
  };
}

async function crossLocationSchedulePayload(session, input = {}) {
  const actor = await crossLocationSchedulePrincipal(session);
  const access = createCrossLocationScheduleAccessSnapshot(actor || {});
  const configuration = normalizeCrossLocationScheduleSettings(getSettings());
  if (!crossLocationScheduleOperationAllowed(access, configuration, "read")) {
    throw httpError(
      403,
      configuration.enabled
        ? "Für die eingeschränkte Ansicht fremder Dienstpläne fehlt die fachliche Berechtigung oder ein gültiger Verantwortungsbereich."
        : "Die standortübergreifende Dienstplanansicht ist in den Dienstplan-Einstellungen deaktiviert.",
      "CROSS_LOCATION_SCHEDULE_READ_DENIED",
    );
  }
  const current = currentWeekStart();
  const requestedWeek = String(input.week || current).trim();
  const weekStart = isIsoDate(requestedWeek) ? getMonday(requestedWeek) : "";
  if (!weekStart || requestedWeek !== weekStart
    || !allowedCrossLocationScheduleWeek(
      weekStart,
      viennaTodayIso(),
      configuration.horizonWeeks,
    )) {
    throw httpError(
      400,
      configuration.horizonWeeks === 1
        ? "Fremde Dienstpläne können ausschließlich für die aktuelle Kalenderwoche geöffnet werden."
        : "Fremde Dienstpläne können ausschließlich für die aktuelle oder die nächste Kalenderwoche geöffnet werden.",
      "CROSS_LOCATION_SCHEDULE_WEEK_DENIED",
    );
  }
  const allLocations = await getLocations(false);
  const locations = publicCrossLocationScheduleLocations(allLocations, access);
  const destinationLocation = allLocations.find((location) => (
    location.active
      && String(location.id || "") === String(access.organizationScope?.locationId || "")
  ));
  const destinationDepartmentId = access.role === "department_manager"
    ? Number(access.organizationScope?.departmentId || 0) || null
    : null;
  const requestDestination = crossLocationScheduleOperationAllowed(
    access,
    configuration,
    "create",
  ) && destinationLocation ? {
    id: String(destinationLocation.id || ""),
    name: String(destinationLocation.name || ""),
    departments: (destinationLocation.departments || [])
      .filter((department) => department.active
        && (!destinationDepartmentId || Number(department.id) === destinationDepartmentId))
      .map((department) => ({ id: Number(department.id), name: String(department.name || "") })),
  } : null;
  const requestedLocationId = String(input.locationId || input.location || "").trim();
  const selectedLocationId = requestedLocationId || locations[0]?.id || "";
  const selectedLocation = allLocations.find((location) => (
    String(location.id || "") === selectedLocationId
      && locations.some((visible) => visible.id === selectedLocationId)
  ));
  if (requestedLocationId && !selectedLocation) {
    throw httpError(
      403,
      "Diese Filiale ist für die eingeschränkte Fremdansicht nicht verfügbar.",
      "CROSS_LOCATION_SCHEDULE_LOCATION_DENIED",
    );
  }
  let schedule = null;
  if (selectedLocation) {
    schedule = projectCrossLocationScheduleView({
      actor,
      sourceLocationId: selectedLocationId,
      weekStart,
      today: viennaTodayIso(),
      settings: configuration,
      schedule: await crossLocationScheduleSource(selectedLocation, weekStart),
    });
    if (!schedule) {
      throw httpError(
        403,
        "Der fremde Dienstplan konnte nicht datensparsam freigegeben werden.",
        "CROSS_LOCATION_SCHEDULE_PROJECTION_DENIED",
      );
    }
  }
  return {
    mode: "foreign_read_only",
    locations,
    weeks: Array.from(
      { length: configuration.horizonWeeks },
      (_, index) => addDays(current, index * 7),
    ).map((start) => ({
      weekStart: start,
      weekEnd: addDays(start, 6),
      calendarWeek: getIsoWeek(start),
    })),
    configuration: {
      horizonWeeks: configuration.horizonWeeks,
      changePolicy: configuration.changePolicy,
      cancellationPolicy: configuration.cancellationPolicy,
    },
    selectedLocationId: selectedLocation?.id ? String(selectedLocation.id) : null,
    requestDestination,
    schedule,
  };
}

function publicSubmittedStaffAssignmentRequest(history) {
  const current = history?.current;
  const request = history?.request;
  if (!request || !current || current.status !== "submitted") {
    throw httpError(
      503,
      "Die eingereichte Einsatzanfrage konnte nicht sicher bestätigt werden.",
      "STAFF_ASSIGNMENT_REQUEST_SUBMISSION_INTEGRITY_FAILED",
    );
  }
  return {
    id: String(request.id || ""),
    status: "submitted",
    revisionNumber: Number(current.revisionNumber),
    sourceLocationId: String(current.sourceLocationId || ""),
    destinationLocationId: String(current.destinationLocationId || ""),
    destinationDepartmentId: Number(current.destinationDepartmentId),
    periodStartDate: String(current.periodStartDate || ""),
    periodEndDate: String(current.periodEndDate || ""),
    timeKind: String(current.timeKind || ""),
    startTime: current.startTime || null,
    endTime: current.endTime || null,
    preferredEmployeeNumber: current.preferredEmployeeNumber || null,
  };
}

function staffAssignmentRequestHttpError(error) {
  if (!(error instanceof StaffAssignmentRequestError)) return error;
  const conflictCodes = new Set([
    "STAFF_ASSIGNMENT_REQUEST_REVISION_CONFLICT",
    "EMPLOYEE_LENDING_OVERLAP",
    "EMPLOYEE_LENDING_APPROVED_ABSENCE_CONFLICT",
    "EMPLOYEE_LENDING_PENDING_ABSENCE_REQUEST_CONFLICT",
    "EMPLOYEE_LENDING_SHIFT_CONFLICT",
  ]);
  const status = conflictCodes.has(error.code) ? 409
    : error.code === "STAFF_ASSIGNMENT_REQUEST_NOT_FOUND" ? 404
      : 400;
  return httpError(status, error.message, error.code);
}

function staffAssignmentRequestEmployeeMap(employees = []) {
  return new Map(employees.map((employee) => [
    String(employee.personnel_number || employee.employeeNumber || ""),
    employee,
  ]).filter(([employeeNumber]) => employeeNumber));
}

function staffAssignmentRequestSourceDepartmentId(current, employeesByNumber) {
  const preferredEmployeeNumber = String(current?.preferredEmployeeNumber || "");
  if (!preferredEmployeeNumber) return null;
  const preferred = employeesByNumber.get(preferredEmployeeNumber);
  if (!preferred?.active
    || String(preferred.home_location_id || "") !== String(current.sourceLocationId || "")) {
    return null;
  }
  return Number(preferred.preferred_department_id || 0) || null;
}

function staffAssignmentRequestReviewerPrincipal(user, scopeContext) {
  return {
    employeeNumber: String(user.employeeNumber || ""),
    role: String(user.role || ""),
    active: Boolean(user.active && user.employeeActive),
    configured: Boolean(user.configured),
    sessionKind: "employee",
    isEmployee: true,
    homeLocationId: String(user.homeLocationId || ""),
    preferredDepartmentId: Number(user.preferredDepartmentId || 0) || null,
    rolePermissions: user.rolePermissions || [],
    grantedPermissions: user.grantedPermissions || [],
    deniedPermissions: user.deniedPermissions || [],
    effectiveScopes: personnelLearningEffectiveScopes({ scopes: user.scopes || [] }, scopeContext),
  };
}

async function staffAssignmentRequestReviewerEmployeeNumbers(
  sourceLocationId,
  sourceDepartmentId,
  configuration = normalizeCrossLocationScheduleSettings(getSettings()),
) {
  const [users, scopeContext] = await Promise.all([
    portalUsersForAdmin(),
    personnelLearningScopeContext(),
  ]);
  return [...new Set(users
    .filter((user) => ["manager", "department_manager"].includes(user.role))
    .filter((user) => {
      const actor = staffAssignmentRequestReviewerPrincipal(user, scopeContext);
      return crossLocationScheduleOperationAllowed(actor, configuration, "review")
        && canReviewStaffAssignmentRequest({
          actor,
          sourceLocationId,
          sourceDepartmentId,
        });
    })
    .map((user) => String(user.employeeNumber || ""))
    .filter(Boolean))];
}

async function notifyStaffAssignmentRequest(
  kind,
  employeeNumbers,
  requestId,
  { enabled = true } = {},
) {
  const recipients = [...new Set((Array.isArray(employeeNumbers) ? employeeNumbers : [])
    .map((employeeNumber) => String(employeeNumber || "").trim())
    .filter(Boolean))];
  const result = { kind, eligible: recipients.length, delivered: 0, skipped: 0, failed: 0 };
  const failureCodes = new Set();
  if (!enabled) {
    result.skipped = recipients.length;
    failureCodes.add("disabled_by_schedule_settings");
  } else if (!externalNotificationAdapter.canSendEvent("email", "staff_assignment_request")) {
    result.skipped = recipients.length;
    failureCodes.add("event_unavailable");
  } else {
    for (const employeeNumber of recipients) {
      try {
        const target = await verifiedPersonalNotificationTarget(employeeNumber, "email", {
          requireEnabled: true,
        });
        if (!target) {
          result.skipped += 1;
          failureCodes.add("verified_enabled_target_missing");
          continue;
        }
        await externalNotificationAdapter.sendStaffAssignmentRequestAlert({
          recipient: target.destination,
          kind,
        });
        result.delivered += 1;
      } catch (error) {
        result.failed += 1;
        failureCodes.add(String(error?.code || "delivery_failed").slice(0, 120));
      }
    }
  }
  try {
    (await auditPortal(
      "system",
      "staff-assignment-request.email",
      "staff_assignment_request",
      requestId,
      JSON.stringify({ ...result, failureCodes: [...failureCodes].sort() }),
    ));
  } catch {}
  return result;
}

function staffAssignmentRequestReviewProjection({
  current,
  actor,
  employeesByNumber,
  locationsById,
  departmentsById,
}) {
  const sourceDepartmentId = staffAssignmentRequestSourceDepartmentId(
    current,
    employeesByNumber,
  );
  if (!canReviewStaffAssignmentRequest({
    actor,
    sourceLocationId: current.sourceLocationId,
    sourceDepartmentId,
  })) return null;
  const access = createCrossLocationScheduleAccessSnapshot(actor);
  const requester = employeesByNumber.get(String(current.createdByEmployeeNumber || ""));
  const preferred = employeesByNumber.get(String(current.preferredEmployeeNumber || ""));
  const candidates = [...employeesByNumber.values()]
    .filter((employee) => employee.active
      && String(employee.home_location_id || "") === String(current.sourceLocationId || "")
      && (access.role !== "department_manager"
        || Number(employee.preferred_department_id || 0) === access.organizationScope.departmentId))
    .map((employee) => {
      const departmentId = Number(employee.preferred_department_id || 0) || null;
      return {
        employeeNumber: String(employee.personnel_number || ""),
        displayName: String(employee.nickname || `MA ${employee.personnel_number || ""}`).trim(),
        departmentId,
        departmentName: departmentId
          ? String(departmentsById.get(departmentId)?.name || "")
          : "",
      };
    })
    .filter((employee) => employee.employeeNumber)
    .sort((left, right) => left.displayName.localeCompare(right.displayName, "de-AT")
      || left.employeeNumber.localeCompare(right.employeeNumber));
  const sourceLocation = locationsById.get(String(current.sourceLocationId || ""));
  const destinationLocation = locationsById.get(String(current.destinationLocationId || ""));
  const destinationDepartment = departmentsById.get(Number(current.destinationDepartmentId));
  return {
    id: String(current.requestId || ""),
    status: "submitted",
    revisionNumber: Number(current.revisionNumber),
    createdAt: String(current.createdAt || ""),
    submittedAt: String(current.changedAt || ""),
    sourceLocation: {
      id: String(current.sourceLocationId || ""),
      name: String(sourceLocation?.name || current.sourceLocationId || ""),
    },
    destinationLocation: {
      id: String(current.destinationLocationId || ""),
      name: String(destinationLocation?.name || current.destinationLocationId || ""),
    },
    destinationDepartment: {
      id: Number(current.destinationDepartmentId),
      name: String(destinationDepartment?.name || current.destinationDepartmentId || ""),
    },
    periodStartDate: String(current.periodStartDate || ""),
    periodEndDate: String(current.periodEndDate || ""),
    timeKind: String(current.timeKind || ""),
    startTime: current.startTime || null,
    endTime: current.endTime || null,
    requestReason: String(current.requestReason || ""),
    requestedBy: {
      employeeNumber: String(current.createdByEmployeeNumber || ""),
      displayName: String(requester?.nickname
        || `MA ${current.createdByEmployeeNumber || ""}`).trim(),
    },
    preferredEmployee: current.preferredEmployeeNumber ? {
      employeeNumber: String(current.preferredEmployeeNumber),
      displayName: String(preferred?.nickname
        || `MA ${current.preferredEmployeeNumber}`).trim(),
      departmentId: sourceDepartmentId,
    } : null,
    candidates,
  };
}

async function staffAssignmentRequestReviewPayload(session) {
  const liveSession = await livePersonnelLearningRoleAdministrationActor(
    session,
    organizationPersonnelRepository,
  );
  assertLivePortalRoutePermission(
    liveSession,
    CROSS_LOCATION_SCHEDULE_PERMISSIONS.REQUEST_REVIEW,
  );
  const actor = await crossLocationSchedulePrincipal(
    liveSession,
    organizationPersonnelRepository,
  );
  const access = createCrossLocationScheduleAccessSnapshot(actor || {});
  const configuration = normalizeCrossLocationScheduleSettings(getSettings());
  if (!crossLocationScheduleOperationAllowed(access, configuration, "review")) {
    throw httpError(
      403,
      access.role === "department_manager" && !configuration.departmentManagerRequestReviewEnabled
        ? "Abteilungsleitungen sind in den Dienstplan-Einstellungen nicht für Entscheidungen freigeschaltet."
        : "Für die Prüfung von Einsatzanfragen fehlt ein gültiger fachlicher Verantwortungsbereich.",
      "STAFF_ASSIGNMENT_REQUEST_REVIEW_DENIED",
    );
  }
  const [requestRows, employees, locations, departments] = await Promise.all([
    staffAssignmentRequestRepository.listRequests(),
    organizationPersonnelRepository.listEmployees(),
    organizationPersonnelRepository.listLocations(false),
    organizationPersonnelRepository.listDepartments(false),
  ]);
  const rows = (await Promise.all(requestRows.map(async (request) => {
    const current = await staffAssignmentRequestRepository.getLatestRevision(request.id);
    return current?.status === "submitted" ? {
      ...current,
      createdByEmployeeNumber: request.createdByEmployeeNumber,
      createdAt: request.createdAt,
    } : null;
  }))).filter(Boolean);
  const employeesByNumber = staffAssignmentRequestEmployeeMap(employees);
  const locationsById = new Map(locations.map((location) => [String(location.id || ""), location]));
  const departmentsById = new Map(departments.map((department) => [Number(department.id), department]));
  return {
    requests: rows.map((current) => staffAssignmentRequestReviewProjection({
      current,
      actor,
      employeesByNumber,
      locationsById,
      departmentsById,
    })).filter(Boolean),
  };
}

async function decideStaffAssignmentRequest(session, requestId, input = {}) {
  try {
    const decision = String(input.decision || "").trim().toLowerCase();
    if (!(["accepted", "rejected"].includes(decision))) {
      throw httpError(
        400,
        "Bitte die Einsatzanfrage genehmigen oder ablehnen.",
        "STAFF_ASSIGNMENT_REQUEST_DECISION_INVALID",
      );
    }
    const expectedRevision = Number(input.expectedRevision);
    if (!Number.isSafeInteger(expectedRevision) || expectedRevision < 1) {
      throw httpError(
        400,
        "Die erwartete Anfragerevision ist ungültig.",
        "STAFF_ASSIGNMENT_REQUEST_REVISION_INVALID",
      );
    }
    const outcome = await persistenceProvider.transaction(async (executor) => {
      const repositories = createApplicationRepositories(executor);
      const organization = repositories.organizationPersonnel;
      const requests = repositories.staffAssignmentRequests;
      const liveSession = await livePersonnelLearningRoleAdministrationActor(session, organization);
      assertLivePortalRoutePermission(
        liveSession,
        CROSS_LOCATION_SCHEDULE_PERMISSIONS.REQUEST_REVIEW,
      );
      const actor = await crossLocationSchedulePrincipal(liveSession, organization);
      const configuration = await crossLocationScheduleSettingsFromRepository(
        repositories.planningSettings,
      );
      if (!crossLocationScheduleOperationAllowed(actor, configuration, "review")) {
        throw httpError(
          403,
          "Die Entscheidung ist nach den aktuellen Dienstplan-Einstellungen nicht freigegeben.",
          "STAFF_ASSIGNMENT_REQUEST_REVIEW_DENIED",
        );
      }
      const current = await requests.getLatestRevision(requestId);
      const request = await requests.getRequest(requestId);
      if (!current || !request) {
        throw new StaffAssignmentRequestError(
          "STAFF_ASSIGNMENT_REQUEST_NOT_FOUND",
          "Die Einsatzanfrage wurde nicht gefunden.",
        );
      }
      const [employees, locations, departments] = await Promise.all([
        organization.listEmployees(),
        organization.listLocations(false),
        organization.listDepartments(false),
      ]);
      const employeesByNumber = staffAssignmentRequestEmployeeMap(employees);
      const sourceDepartmentId = staffAssignmentRequestSourceDepartmentId(
        current,
        employeesByNumber,
      );
      if (!canReviewStaffAssignmentRequest({
        actor,
        sourceLocationId: current.sourceLocationId,
        sourceDepartmentId,
      })) {
        throw httpError(
          403,
          "Diese Einsatzanfrage liegt außerhalb des eigenen Prüfbereichs.",
          "STAFF_ASSIGNMENT_REQUEST_REVIEW_DENIED",
        );
      }
      const sourceLocation = locations.find((location) => (
        location.active && String(location.id || "") === String(current.sourceLocationId || "")
      ));
      const destinationLocation = locations.find((location) => (
        location.active
          && String(location.id || "") === String(current.destinationLocationId || "")
      ));
      const destinationDepartment = departments.find((department) => (
        department.active
          && Number(department.id) === Number(current.destinationDepartmentId)
          && String(department.location_id || "") === String(current.destinationLocationId || "")
      ));
      if (!sourceLocation || !destinationLocation || !destinationDepartment) {
        throw httpError(
          409,
          "Die Organisationsstruktur der Einsatzanfrage hat sich geändert.",
          "STAFF_ASSIGNMENT_REQUEST_TOPOLOGY_CHANGED",
        );
      }
      const access = createCrossLocationScheduleAccessSnapshot(actor || {});
      let confirmedEmployeeNumber = null;
      let preparedAssignment = null;
      if (decision === "accepted") {
        confirmedEmployeeNumber = String(input.confirmedEmployeeNumber || "").trim();
        const confirmed = employeesByNumber.get(confirmedEmployeeNumber);
        if (!confirmed?.active
          || String(confirmed.home_location_id || "") !== String(current.sourceLocationId || "")
          || (access.role === "department_manager"
            && Number(confirmed.preferred_department_id || 0)
              !== Number(access.organizationScope?.departmentId || 0))) {
          throw httpError(
            409,
            "Das bestätigte Teammitglied gehört nicht aktiv zum eigenen Prüfbereich der Quellfiliale.",
            "STAFF_ASSIGNMENT_REQUEST_CONFIRMED_EMPLOYEE_INVALID",
          );
        }
        preparedAssignment = boundAssignmentFromRequest({
          requestId,
          current,
          confirmedEmployeeNumber,
          actorEmployeeNumber: liveSession.employeeNumber,
          timestamp: new Date().toISOString(),
        });
      }
      const history = await transitionStaffAssignmentRequestHistory(
        requests,
        requestId,
        decision,
        {
          confirmedEmployeeNumber,
          decisionReason: String(input.decisionReason || "").trim(),
        },
        liveSession.employeeNumber,
        { expectedRevision },
      );
      const result = history.current;
      let assignmentId = null;
      if (decision === "accepted") {
        await assertStaffAssignmentRequestAssignmentAvailable(
          preparedAssignment,
          repositories.absenceManagement,
        );
        const assignment = boundAssignmentFromRequest({
          requestId,
          current,
          confirmedEmployeeNumber,
          actorEmployeeNumber: liveSession.employeeNumber,
          timestamp: result.changedAt,
        });
        const insertion = await requests.insertBoundAssignment(assignment);
        if (Number(insertion?.rowsAffected) !== 1) {
          throw new StaffAssignmentRequestError(
            "STAFF_ASSIGNMENT_REQUEST_FULFILLMENT_FAILED",
            "Der temporäre Filialeinsatz konnte nicht verbindlich angelegt werden.",
          );
        }
        assignmentId = assignment.id;
      }
      await organization.insertAudit(
        liveSession.employeeNumber,
        `staff-assignment-request.${decision}`,
        "staff_assignment_request",
        requestId,
        JSON.stringify({
          revisionNumber: Number(result.revisionNumber),
          sourceLocationId: String(result.sourceLocationId || ""),
          destinationLocationId: String(result.destinationLocationId || ""),
          confirmedEmployeeSelected: Boolean(result.confirmedEmployeeNumber),
          decisionReasonRecorded: Boolean(result.decisionReason),
          assignmentCreated: Boolean(assignmentId),
          assignmentId,
        }),
      );
      return {
        request: {
          id: String(requestId),
          status: decision,
          revisionNumber: Number(result.revisionNumber),
          confirmedEmployeeNumber: result.confirmedEmployeeNumber || null,
          decisionReason: String(result.decisionReason || ""),
          assignmentId,
        },
        requesterEmployeeNumber: String(request.createdByEmployeeNumber || ""),
        emailDecisionEnabled: configuration.emailDecisionEnabled,
      };
    }, { isolation: "serializable" });
    await notifyStaffAssignmentRequest(
      decision,
      [outcome.requesterEmployeeNumber],
      requestId,
      { enabled: outcome.emailDecisionEnabled },
    );
    return outcome.request;
  } catch (error) {
    throw staffAssignmentRequestHttpError(error);
  }
}

async function submitStaffAssignmentRequest(session, input = {}) {
  try {
    const outcome = await persistenceProvider.transaction(async (executor) => {
      const repositories = createApplicationRepositories(executor);
      const organization = repositories.organizationPersonnel;
      const liveSession = await livePersonnelLearningRoleAdministrationActor(session, organization);
      assertLivePortalRoutePermission(
        liveSession,
        CROSS_LOCATION_SCHEDULE_PERMISSIONS.REQUEST_CREATE,
      );
      const actor = await crossLocationSchedulePrincipal(liveSession, organization);
      const access = createCrossLocationScheduleAccessSnapshot(actor || {});
      const configuration = await crossLocationScheduleSettingsFromRepository(
        repositories.planningSettings,
      );
      const sourceLocationId = String(input.sourceLocationId || "").trim();
      const destinationLocationId = String(access.organizationScope?.locationId || "");
      const destinationDepartmentId = Number(input.destinationDepartmentId || 0);
      if (!crossLocationScheduleOperationAllowed(access, configuration, "create")
        || !canCreateStaffAssignmentRequest({
        actor,
        sourceLocationId,
        destinationLocationId,
        destinationDepartmentId,
      })) {
        throw httpError(
          403,
          access.role === "department_manager" && !configuration.departmentManagerRequestCreateEnabled
            ? "Abteilungsleitungen sind in den Dienstplan-Einstellungen nicht für neue Einsatzanfragen freigeschaltet."
            : "Die Einsatzanfrage darf nicht für diese Quellfiliale oder Zielabteilung erstellt werden.",
          "STAFF_ASSIGNMENT_REQUEST_SCOPE_DENIED",
        );
      }

      const [locations, departments] = await Promise.all([
        organization.listLocations(false),
        organization.listDepartments(false),
      ]);
      const sourceLocation = locations.find((location) => (
        String(location.id || "") === sourceLocationId && location.active
      ));
      const destinationLocation = locations.find((location) => (
        String(location.id || "") === destinationLocationId && location.active
      ));
      const destinationDepartment = departments.find((department) => (
        Number(department.id) === destinationDepartmentId
          && department.active
          && String(department.location_id || "") === destinationLocationId
      ));
      if (!sourceLocation || !destinationLocation || !destinationDepartment) {
        throw httpError(
          409,
          "Quellfiliale oder Zielabteilung ist nicht mehr aktiv verfügbar.",
          "STAFF_ASSIGNMENT_REQUEST_TOPOLOGY_CHANGED",
        );
      }

      const normalized = normalizeStaffAssignmentRequestInput({
        sourceLocationId,
        destinationLocationId,
        destinationDepartmentId,
        periodStartDate: input.periodStartDate,
        periodEndDate: input.periodEndDate,
        timeKind: input.timeKind,
        startTime: input.startTime ?? null,
        endTime: input.endTime ?? null,
        preferredEmployeeNumber: input.preferredEmployeeNumber || null,
        confirmedEmployeeNumber: null,
        requestReason: input.requestReason,
        decisionReason: "",
      }, { requestStatus: "submitted" });
      const today = viennaTodayIso();
      const maximum = addDays(
        currentWeekStart(),
        configuration.horizonWeeks * 7 - 1,
      );
      if (normalized.periodStartDate < today || normalized.periodEndDate > maximum) {
        throw httpError(
          400,
          configuration.horizonWeeks === 1
            ? "Einsatzanfragen sind nur ab heute bis zum Ende der aktuellen Kalenderwoche möglich."
            : "Einsatzanfragen sind nur ab heute bis zum Ende der nächsten Kalenderwoche möglich.",
          "STAFF_ASSIGNMENT_REQUEST_PERIOD_OUT_OF_RANGE",
        );
      }
      let sourceDepartmentId = null;
      if (normalized.preferredEmployeeNumber) {
        const preferred = await organization.getEmployeeForUpdate(
          normalized.preferredEmployeeNumber,
        );
        if (!preferred?.active
          || String(preferred.home_location_id || "") !== sourceLocationId) {
          throw httpError(
            409,
            "Das bevorzugte Teammitglied gehört nicht mehr aktiv zur Quellfiliale.",
            "STAFF_ASSIGNMENT_REQUEST_PREFERRED_EMPLOYEE_INVALID",
          );
        }
        sourceDepartmentId = Number(preferred.preferred_department_id || 0) || null;
      }

      const history = await insertInitialStaffAssignmentRequestHistory(
        repositories.staffAssignmentRequests,
        normalized,
        liveSession.employeeNumber,
        { submit: true },
      );
      const result = publicSubmittedStaffAssignmentRequest(history);
      await organization.insertAudit(
        liveSession.employeeNumber,
        "staff-assignment-request.submit",
        "staff_assignment_request",
        result.id,
        JSON.stringify({
          sourceLocationId: result.sourceLocationId,
          destinationLocationId: result.destinationLocationId,
          destinationDepartmentId: result.destinationDepartmentId,
          periodStartDate: result.periodStartDate,
          periodEndDate: result.periodEndDate,
          timeKind: result.timeKind,
          preferredEmployeeRequested: Boolean(result.preferredEmployeeNumber),
        }),
      );
      return {
        request: result,
        sourceDepartmentId,
        configuration,
      };
    }, { isolation: "serializable" });
    try {
      const reviewers = await staffAssignmentRequestReviewerEmployeeNumbers(
        outcome.request.sourceLocationId,
        outcome.sourceDepartmentId,
        outcome.configuration,
      );
      await notifyStaffAssignmentRequest(
        "submitted",
        reviewers,
        outcome.request.id,
        { enabled: outcome.configuration.emailSubmittedEnabled },
      );
    } catch {
      try {
        (await auditPortal(
          "system",
          "staff-assignment-request.email",
          "staff_assignment_request",
          outcome.request.id,
          JSON.stringify({ kind: "submitted", eligible: 0, delivered: 0, skipped: 0, failed: 1, failureCodes: ["recipient_resolution_failed"] }),
        ));
      } catch {}
    }
    return outcome.request;
  } catch (error) {
    throw staffAssignmentRequestHttpError(error);
  }
}

const SCHEDULE_SEARCH_MAX_RANGE_DAYS = 731;
const SCHEDULE_SEARCH_MAX_LIMIT = 100;
const SCHEDULE_SEARCH_MAX_OFFSET = 5000;
const SCHEDULE_SEARCH_SORT_KEYS = new Set([
  "date",
  "employee",
  "personnelNumber",
  "homeLocation",
  "location",
  "department",
  "startTime",
  "duration",
  "area",
  "assignment",
]);
const SCHEDULE_SEARCH_ASSIGNMENTS = new Set(["all", "home", "cross_location"]);
const scheduleSearchCollator = new Intl.Collator("de-AT", { numeric: true, sensitivity: "base" });

function scheduleSearchQueryScalar(query, key) {
  const submitted = query?.[key];
  if (Array.isArray(submitted) || (submitted !== null && typeof submitted === "object")) {
    throw httpError(400, `Der Suchparameter „${key}“ darf nur einmal angegeben werden.`, "SCHEDULE_SEARCH_QUERY_INVALID");
  }
  const rawValue = String(submitted ?? "");
  if (/[\u0000-\u001f\u007f]/.test(rawValue)) {
    throw httpError(400, `Der Suchparameter „${key}“ enthält unzulässige Zeichen.`, "SCHEDULE_SEARCH_QUERY_INVALID");
  }
  return rawValue.trim();
}

function scheduleSearchText(query, key, maximumLength) {
  const value = scheduleSearchQueryScalar(query, key);
  if (value.length > maximumLength) {
    throw httpError(400, `Der Suchparameter „${key}“ ist zu lang.`, "SCHEDULE_SEARCH_QUERY_INVALID");
  }
  return value;
}

function scheduleSearchIdentifier(query, key, { allowAll = false } = {}) {
  const value = scheduleSearchText(query, key, 80);
  if (!value || (allowAll && value === "all")) return "";
  if (!/^[A-Za-z0-9._:-]+$/.test(value)) {
    throw httpError(400, `Der Suchparameter „${key}“ ist ungültig.`, "SCHEDULE_SEARCH_QUERY_INVALID");
  }
  return value;
}

function scheduleSearchInteger(query, key, fallback, { minimum, maximum }) {
  const value = scheduleSearchQueryScalar(query, key);
  if (!value) return fallback;
  if (!/^\d+$/.test(value)) {
    throw httpError(400, `Der Suchparameter „${key}“ muss eine ganze Zahl sein.`, "SCHEDULE_SEARCH_QUERY_INVALID");
  }
  const parsed = Number(value);
  if (!Number.isSafeInteger(parsed) || parsed < minimum || parsed > maximum) {
    throw httpError(400, `Der Suchparameter „${key}“ liegt außerhalb des zulässigen Bereichs.`, "SCHEDULE_SEARCH_QUERY_INVALID");
  }
  return parsed;
}

function normalizeScheduleSearchText(value) {
  return String(value || "")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLocaleLowerCase("de-AT")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizedScheduleSearchQuery(query = {}) {
  const submittedDateFrom = scheduleSearchQueryScalar(query, "dateFrom");
  const submittedDateTo = scheduleSearchQueryScalar(query, "dateTo");
  if ((submittedDateFrom && !isIsoDate(submittedDateFrom))
    || (submittedDateTo && !isIsoDate(submittedDateTo))) {
    throw httpError(400, "Bitte einen gültigen Suchzeitraum angeben.", "SCHEDULE_SEARCH_RANGE_INVALID");
  }
  const dateFrom = submittedDateFrom || (submittedDateTo ? addDays(submittedDateTo, -182) : viennaTodayIso());
  const dateTo = submittedDateTo || addDays(dateFrom, 182);
  if (dateTo < dateFrom || daysBetweenInclusive(dateFrom, dateTo) > SCHEDULE_SEARCH_MAX_RANGE_DAYS) {
    throw httpError(400, `Der Suchzeitraum darf höchstens ${SCHEDULE_SEARCH_MAX_RANGE_DAYS} Tage umfassen.`, "SCHEDULE_SEARCH_RANGE_INVALID");
  }
  const sort = scheduleSearchText(query, "sort", 40) || "date";
  if (!SCHEDULE_SEARCH_SORT_KEYS.has(sort)) {
    throw httpError(400, "Die gewählte Sortierung ist für die Dienstsuche nicht verfügbar.", "SCHEDULE_SEARCH_SORT_INVALID");
  }
  const direction = scheduleSearchText(query, "direction", 4) || "asc";
  if (!["asc", "desc"].includes(direction)) {
    throw httpError(400, "Die Sortierrichtung ist ungültig.", "SCHEDULE_SEARCH_SORT_INVALID");
  }
  const assignment = scheduleSearchText(query, "assignment", 20) || "all";
  if (!SCHEDULE_SEARCH_ASSIGNMENTS.has(assignment)) {
    throw httpError(400, "Der gewählte Einsatzfilter ist ungültig.", "SCHEDULE_SEARCH_ASSIGNMENT_INVALID");
  }
  const departmentValue = scheduleSearchQueryScalar(query, "departmentId");
  if (departmentValue && !/^\d+$/.test(departmentValue)) {
    throw httpError(400, "Die gewählte Abteilung ist ungültig.", "SCHEDULE_SEARCH_QUERY_INVALID");
  }
  const departmentId = departmentValue ? Number(departmentValue) : null;
  if (departmentValue && (!Number.isSafeInteger(departmentId) || departmentId <= 0)) {
    throw httpError(400, "Die gewählte Abteilung ist ungültig.", "SCHEDULE_SEARCH_QUERY_INVALID");
  }
  return {
    employee: scheduleSearchText(query, "employee", 120),
    employeeNumber: scheduleSearchIdentifier(query, "employeeNumber"),
    dateFrom,
    dateTo,
    locationId: scheduleSearchIdentifier(query, "locationId", { allowAll: true }),
    departmentId,
    homeLocationId: scheduleSearchIdentifier(query, "homeLocationId", { allowAll: true }),
    assignment,
    area: scheduleSearchText(query, "area", 120),
    sort,
    direction,
    limit: scheduleSearchInteger(query, "limit", 50, { minimum: 1, maximum: SCHEDULE_SEARCH_MAX_LIMIT }),
    offset: scheduleSearchInteger(query, "offset", 0, { minimum: 0, maximum: SCHEDULE_SEARCH_MAX_OFFSET }),
  };
}

function scheduleSearchTargetContexts(session, locations, query) {
  let selectedLocations = locations;
  if (query.locationId) {
    const requested = locations.find((location) => String(location.id) === query.locationId);
    if (!requested) {
      throw httpError(403, "Die gewählte Filiale ist für diesen Zugang nicht freigegeben.", "SCHEDULE_SEARCH_SCOPE_DENIED");
    }
    selectedLocations = [requested];
  }
  if (query.departmentId) {
    selectedLocations = selectedLocations.filter((location) => (
      (location.departments || []).some((department) => Number(department.id) === query.departmentId)
    ));
    if (selectedLocations.length !== 1) {
      throw httpError(403, "Die gewählte Abteilung ist für diesen Zugang nicht freigegeben.", "SCHEDULE_SEARCH_SCOPE_DENIED");
    }
  }
  return selectedLocations.flatMap((location) => {
    const locationId = String(location.id);
    const wholeLocation = sessionHasGlobalScope(session) || (session.scopes || []).some((scope) => (
      String(scope.locationId) === locationId && !Number(scope.departmentId || 0)
    ));
    const departmentIds = query.departmentId
      ? [query.departmentId]
      : wholeLocation
        ? [null]
        : (location.departments || []).map((department) => Number(department.id));
    return departmentIds.map((departmentId) => {
      const context = { locationId, departmentId, location };
      assertSessionContextScope(session, context);
      return context;
    });
  });
}

function scheduleSearchResultSortValue(result, key) {
  if (key === "employee") return result.employeeName;
  if (key === "personnelNumber") return result.personnelNumber;
  if (key === "homeLocation") return result.homeLocationName;
  if (key === "location") return result.locationName;
  if (key === "department") return result.departmentName;
  if (key === "startTime") return result.startTime;
  if (key === "duration") return result.durationMinutes;
  if (key === "area") return result.area;
  if (key === "assignment") return result.crossLocation ? "standortübergreifend" : "stammfiliale";
  return result.shiftDate;
}

function compareScheduleSearchResults(left, right, query) {
  const leftValue = scheduleSearchResultSortValue(left, query.sort);
  const rightValue = scheduleSearchResultSortValue(right, query.sort);
  const primary = query.sort === "duration"
    ? Number(leftValue) - Number(rightValue)
    : scheduleSearchCollator.compare(String(leftValue || ""), String(rightValue || ""));
  if (primary) return primary * (query.direction === "desc" ? -1 : 1);
  return scheduleSearchCollator.compare(
    `${left.shiftDate}|${left.startTime}|${left.personnelNumber}|${left.shiftId}`,
    `${right.shiftDate}|${right.startTime}|${right.personnelNumber}|${right.shiftId}`,
  );
}

async function searchScheduleShifts(session, input = {}) {
  const query = normalizedScheduleSearchQuery(input);
  const locations = await getLocationsForSession(session, false);
  const contexts = scheduleSearchTargetContexts(session, locations, query);
  const bundles = await Promise.all(contexts.map(async (context) => {
    const planningQuery = {
      locationId: context.locationId,
      departmentId: context.departmentId,
      weekStart: query.dateFrom,
      weekEnd: query.dateTo,
    };
    const [employees, shifts] = await Promise.all([
      planningSettingsRepository.listScheduleEmployees(planningQuery),
      planningSettingsRepository.listScheduleShifts(planningQuery),
    ]);
    return { ...context, employees, shifts };
  }));

  const unfilteredResults = bundles.flatMap((bundle) => {
    const employeeByNumber = new Map(bundle.employees.map((employee) => (
      [String(employee.personnel_number), employee]
    )));
    return bundle.shifts.map((shift) => {
      const employee = employeeByNumber.get(String(shift.employee_number)) || shift;
      const shiftDate = String(shift.shift_date || "");
      const startTime = String(shift.start_time || "");
      const endTime = String(shift.end_time || "");
      const homeLocationId = String(employee.home_location_id || "");
      const locationId = String(bundle.locationId);
      return {
        shiftId: shift.id,
        personnelNumber: String(shift.employee_number || ""),
        employeeName: String(employee.full_name || shift.full_name || employee.nickname || shift.nickname || ""),
        employeeNickname: String(employee.nickname || shift.nickname || ""),
        homeLocationId,
        homeLocationName: String(employee.home_location_name || homeLocationId),
        locationId,
        locationName: String(bundle.location.name || locationId),
        departmentId: Number(shift.department_id || 0) || null,
        departmentName: String(shift.department_name || ""),
        shiftDate,
        startTime,
        endTime,
        durationMinutes: isTime(startTime) && isTime(endTime)
          ? Math.max(0, timeToMinutes(endTime) - timeToMinutes(startTime))
          : 0,
        area: String(shift.area || "").slice(0, 180),
        crossLocation: Boolean(homeLocationId && homeLocationId !== locationId),
        weekStart: isIsoDate(shiftDate) ? getMonday(shiftDate) : "",
        calendarWeek: isIsoDate(shiftDate) ? getIsoWeek(shiftDate) : null,
      };
    });
  });

  const normalizedEmployee = normalizeScheduleSearchText(query.employee);
  const normalizedArea = normalizeScheduleSearchText(query.area);
  const results = unfilteredResults.filter((result) => {
    if (query.employeeNumber
      && normalizeScheduleSearchText(result.personnelNumber) !== normalizeScheduleSearchText(query.employeeNumber)) return false;
    if (normalizedEmployee && !normalizeScheduleSearchText([
      result.employeeName,
      result.employeeNickname,
      result.personnelNumber,
    ].join(" ")).includes(normalizedEmployee)) return false;
    if (query.homeLocationId && result.homeLocationId !== query.homeLocationId) return false;
    if (query.assignment === "home" && result.crossLocation) return false;
    if (query.assignment === "cross_location" && !result.crossLocation) return false;
    if (normalizedArea && !normalizeScheduleSearchText(result.area).includes(normalizedArea)) return false;
    return true;
  }).sort((left, right) => compareScheduleSearchResults(left, right, query));

  const homeLocationMap = new Map(unfilteredResults
    .filter((result) => result.homeLocationId)
    .map((result) => [result.homeLocationId, {
      id: result.homeLocationId,
      name: result.homeLocationName || result.homeLocationId,
    }]));
  const paged = results.slice(query.offset, query.offset + query.limit);
  const targetLocationMap = new Map(contexts.map((context) => [context.locationId, context.location]));
  return {
    query,
    paging: {
      limit: query.limit,
      offset: query.offset,
      total: results.length,
      returned: paged.length,
      hasMore: query.offset + paged.length < results.length,
    },
    filters: {
      locations: [...targetLocationMap.entries()].map(([id, location]) => ({ id, name: String(location.name || id) })),
      departments: [...targetLocationMap.entries()].flatMap(([locationId, location]) => (location.departments || [])
        .filter((department) => !query.departmentId || Number(department.id) === query.departmentId)
        .map((department) => ({
          id: Number(department.id),
          name: String(department.name || ""),
          locationId,
        }))),
      homeLocations: [...homeLocationMap.values()].sort((left, right) => (
        scheduleSearchCollator.compare(left.name, right.name)
      )),
    },
    results: paged,
  };
}

async function getSchedule(weekValue, contextInput = {}, session = null) {
  const weekStart = getMonday(isIsoDate(weekValue) ? weekValue : undefined);
  const weekEnd = addDays(weekStart, 6);
  const context = await resolvePlanningContext(contextInput);
  assertSessionContextScope(session, context);
  const settings = applyScopedPdfSettings(await settingsForLocation(context.locationId), context, "schedule");
  const allowPastWeekEditing = await pastWeekEditingAllowedForActor(session, settings);
  settings.allow_past_week_editing = allowPastWeekEditing ? "1" : "0";
  const globalDayBlocks = getGlobalDayBlocksForRange(weekStart, weekEnd, context.locationId);
  const globalBlockDates = new Set(globalDayBlocks.map((block) => block.block_date));
  const planningQuery = {
    locationId: context.locationId,
    departmentId: context.departmentId || null,
    weekStart,
    weekEnd,
  };
  const xoffiQuery = {
    locationId: context.locationId,
    departmentId: context.departmentId || null,
    filterDepartment: context.departmentId ? 1 : 0,
    weekStart,
  };
  const [employeeRows, shiftRows, employeeWeekShiftRows, storedWeekOptions, employeeLendings, xoffiWeekRows, xoffiWeekDays, xoffiBalanceRows] = await Promise.all([
    planningSettingsRepository.listScheduleEmployees(planningQuery),
    planningSettingsRepository.listScheduleShifts(planningQuery),
    planningSettingsRepository.listAutoPlanningEmployeeShifts(planningQuery),
    planningSettingsRepository.listScheduleWeekOptions(planningQuery),
    planningSettingsRepository.listScheduleLendings(planningQuery),
    timeTrackingRepository.listActiveXoffiWeekRows(xoffiQuery),
    timeTrackingRepository.listActiveXoffiWeekDays(xoffiQuery),
    timeTrackingRepository.listLatestXoffiBalances(xoffiQuery),
  ]);
  const employees = employeeRows.map(serializeEmployee);
  const visibleEmployeeNumbers = new Set(employees.map((employee) => employee.personnel_number));
  const homeEmployeeNumbers = new Set(employees
    .filter((employee) => String(employee.home_location_id) === String(context.locationId))
    .map((employee) => employee.personnel_number));
  const shifts = await Promise.all(
    shiftRows.map(async (shift) => ({ ...shift, ...await shiftMetrics(shift, settings) })),
  );
  const externalShiftRows = employeeWeekShiftRows.filter((shift) => (
    visibleEmployeeNumbers.has(shift.employee_number)
    && homeEmployeeNumbers.has(shift.employee_number)
    && String(shift.location_id || context.locationId) !== String(context.locationId)
  ));
  const externalLocationIds = [...new Set(externalShiftRows
    .map((shift) => String(shift.location_id || ""))
    .filter(Boolean))];
  const externalLocationSettings = new Map(await Promise.all(externalLocationIds.map(async (locationId) => (
    [locationId, await settingsForLocation(locationId)]
  ))));
  const externalShifts = await Promise.all(externalShiftRows.map(async (shift) => ({
    ...shift,
    ...await shiftMetrics(
      shift,
      externalLocationSettings.get(String(shift.location_id || "")) || settings,
    ),
  })));
  const countedWeekShifts = [...shifts, ...externalShifts];
  const pdfStaffAssignmentShifts = externalShifts.flatMap((shift) => {
    const assignment = employeeLendings.find((item) => (
      String(item.employee_number) === String(shift.employee_number)
      && String(item.home_location_id) === String(context.locationId)
      && String(item.destination_location_id) === String(shift.location_id)
      && item.date_from <= shift.shift_date && item.date_to >= shift.shift_date
      && (!item.destination_department_id
        || Number(item.destination_department_id) === Number(shift.department_id || 0))
      && (Number(item.all_day ?? 1) === 1
        || (item.start_time <= shift.start_time && item.end_time >= shift.end_time))
    ));
    if (!assignment) return [];
    return [{
      employee_number: shift.employee_number,
      shift_date: shift.shift_date,
      start_time: shift.start_time,
      end_time: shift.end_time,
      department_id: shift.department_id || null,
      department_name: shift.department_name || assignment.destination_department_name || "",
      duty_code: shift.duty_code || "",
      location_id: shift.location_id,
      location_name: assignment.destination_location_name || "",
    }];
  });
  const weekOptions = storedWeekOptions.map((option) => ({ ...option }));
  const pendingTimeOff = (await absenceManagementRepository.pendingTimeOffForRange({
    dateFrom: weekStart,
    dateTo: weekEnd,
  })).filter((item) => visibleEmployeeNumbers.has(item.employee_number)).map((item) => ({
    ...item,
    id: `pending-za-${item.id}`,
    group_id: null,
    week_start: weekStart,
    option_type: "time_off",
    note: `Beantragt${item.note ? ` · ${item.note}` : ""}`,
    credited_minutes_per_day: 0,
    soft_pending: true,
  }));
  weekOptions.push(...pendingTimeOff);
  const sicknessCredits = (await Promise.all(employees.map(async (employee) => (
    (await sicknessCreditsForRange(employee.personnel_number, weekStart, weekEnd))
      .filter((credit) => !weekOptions.some((option) => option.employee_number === employee.personnel_number
        && option.option_type === "sick" && credit.date >= option.date_from && credit.date <= option.date_to))
      .map((credit) => ({ employee_number: employee.personnel_number, ...credit }))
  )))).flat();

  const totals = {};
  const plannedTotals = {};
  const inStoreTotals = {};
  const bonusTotals = {};
  const optionCreditTotals = {};
  const sicknessCreditTotals = {};
  for (const employee of employees) {
    totals[employee.personnel_number] = 0;
    plannedTotals[employee.personnel_number] = 0;
    inStoreTotals[employee.personnel_number] = 0;
    bonusTotals[employee.personnel_number] = 0;
    optionCreditTotals[employee.personnel_number] = 0;
    sicknessCreditTotals[employee.personnel_number] = 0;
  }
  for (const shift of countedWeekShifts) {
    const minuteBasis = scheduleShiftMinuteBasis(shift);
    totals[shift.employee_number] = addScheduleMinutes(
      totals[shift.employee_number],
      minuteBasis.countedMinutes,
    );
    plannedTotals[shift.employee_number] = addScheduleMinutes(
      plannedTotals[shift.employee_number],
      minuteBasis.plannedMinutes,
    );
    bonusTotals[shift.employee_number] = addScheduleMinutes(
      bonusTotals[shift.employee_number],
      minuteBasis.bonusMinutes,
    );
  }
  for (const shift of shifts) {
    const minuteBasis = scheduleShiftMinuteBasis(shift);
    inStoreTotals[shift.employee_number] = addScheduleMinutes(
      inStoreTotals[shift.employee_number],
      minuteBasis.plannedMinutes,
    );
  }
  const scheduledEmployeeDates = new Set(
    countedWeekShifts.map((shift) => `${shift.employee_number}|${shift.shift_date}`),
  );
  const sicknessCreditDates = new Set(
    sicknessCredits
      .filter((credit) => Number(credit.minutes || 0) > 0)
      .map((credit) => `${credit.employee_number}|${credit.date}`),
  );
  const claimedOptionDates = new Set();
  for (const option of weekOptions) {
    option.credited_minutes_per_day_effective = Math.max(
      0,
      finiteScheduleMinutes(optionMinutesPerDay(option, option.contracted_hours)),
    );
    const creditedDates = creditedOptionDatesInRange(option, weekStart, weekEnd, context.locationId)
      .filter((date) => !isTeamWideMeetingOption(option) || !employeeDateHasSickness(
        weekOptions,
        sicknessCreditDates,
        option.employee_number,
        date,
      ));
    const creditedDays = isTeamWideMeetingOption(option)
      ? creditedDates.length
      : optionIsAllDay(option) && option.credited_minutes_per_day_effective > 0
        ? claimCreditedOptionDaysInRange(
          option,
          weekStart,
          weekEnd,
          context.locationId,
          scheduledEmployeeDates,
          claimedOptionDates,
        )
        : creditedDates.length;
    option.credited_minutes = option.credited_minutes_per_day_effective * Math.max(
      0,
      finiteScheduleMinutes(creditedDays),
    );
    optionCreditTotals[option.employee_number] = addScheduleMinutes(
      optionCreditTotals[option.employee_number],
      option.credited_minutes,
    );
    totals[option.employee_number] = addScheduleMinutes(
      totals[option.employee_number],
      option.credited_minutes,
    );
    if (!optionIsAllDay(option) && option.credited_minutes > 0) {
      for (const date of creditedDates) claimedOptionDates.add(`${option.employee_number}|${date}`);
    }
  }
  const sicknessBlockedDates = new Set([
    ...scheduledEmployeeDates,
    ...claimedOptionDates,
  ]);
  const claimedSicknessDates = new Set();
  for (const credit of sicknessCredits) {
    const creditMinutes = Math.max(0, finiteScheduleMinutes(credit.minutes));
    if (creditMinutes === 0 || !claimEmployeeDate(
      credit.employee_number,
      credit.date,
      sicknessBlockedDates,
      claimedSicknessDates,
    )) continue;
    sicknessCreditTotals[credit.employee_number] = addScheduleMinutes(
      sicknessCreditTotals[credit.employee_number],
      creditMinutes,
    );
    optionCreditTotals[credit.employee_number] = addScheduleMinutes(
      optionCreditTotals[credit.employee_number],
      creditMinutes,
    );
    totals[credit.employee_number] = addScheduleMinutes(
      totals[credit.employee_number],
      creditMinutes,
    );
  }
  const saturdayStats = await buildSaturdayServiceStats(weekStart, context, employees, shifts, settings);
  const creditedHolidayDates = new Set();
  for (const holiday of publicHolidaysForRange(weekStart, weekEnd)) {
    const day = new Date(`${holiday.date}T12:00:00Z`).getUTCDay();
    if (day === 0 || day === 6) continue;
    for (const employee of employees) {
      const employeeDate = `${employee.personnel_number}|${holiday.date}`;
      if (scheduledEmployeeDates.has(employeeDate) || claimedSicknessDates.has(employeeDate)) continue;
      if (hasNonVacationCreditOnDate(weekOptions, employee.personnel_number, holiday.date)) continue;
      const credit = Math.max(0, finiteScheduleMinutes(holidayCreditMinutes(employee)));
      optionCreditTotals[employee.personnel_number] = addScheduleMinutes(optionCreditTotals[employee.personnel_number], credit);
      totals[employee.personnel_number] = addScheduleMinutes(totals[employee.personnel_number], credit);
    }
    creditedHolidayDates.add(holiday.date);
  }
  for (const block of globalDayBlocks) {
    if (!block.is_public_holiday || creditedHolidayDates.has(block.block_date)) continue;
    const day = new Date(`${block.block_date}T12:00:00Z`).getUTCDay();
    if (day === 0 || day === 6) continue;
    for (const employee of employees) {
      const employeeDate = `${employee.personnel_number}|${block.block_date}`;
      if (scheduledEmployeeDates.has(employeeDate) || claimedSicknessDates.has(employeeDate)) continue;
      if (hasNonVacationCreditOnDate(weekOptions, employee.personnel_number, block.block_date)) continue;
      const credit = Math.max(0, finiteScheduleMinutes(holidayCreditMinutes(employee)));
      optionCreditTotals[employee.personnel_number] = addScheduleMinutes(optionCreditTotals[employee.personnel_number], credit);
      totals[employee.personnel_number] = addScheduleMinutes(totals[employee.personnel_number], credit);
    }
  }
  const [workRuleAssessment, branchSupervisionAssessment, manualScheduleLock] = await Promise.all([
    sessionCanReadWorkRules(session)
      ? evaluateScheduleWorkRules(weekStart, context, employees).then((result) => result.assessment)
      : Promise.resolve(null),
    branchSupervisionAssessmentForSchedule(weekStart, context.locationId),
    getScheduleManualLock(context.locationId, weekStart, session),
  ]);
  const xoffiWeekByEmployee = {};
  const selectedXoffiImports = new Set();
  for (const row of xoffiWeekRows) {
    if (xoffiWeekByEmployee[row.employee_number]) continue;
    xoffiWeekByEmployee[row.employee_number] = {
      importId: row.import_id,
      useAsActual: Number(row.use_as_actual || 0) === 1,
      importedAt: row.imported_at,
      actualMinutes: Number(row.weekly_actual_minutes || 0),
      valuedMinutes: Number(row.weekly_valued_minutes || 0),
      surchargeMinutes: Number(row.weekly_surcharge_minutes || 0),
      closingBalanceMinutes: row.closing_balance_minutes === null ? null : Number(row.closing_balance_minutes),
      days: [],
    };
    selectedXoffiImports.add(`${row.import_id}|${row.employee_number}`);
  }
  for (const row of xoffiWeekDays) {
    if (!selectedXoffiImports.has(`${row.import_id}|${row.employee_number}`)) continue;
    const target = xoffiWeekByEmployee[row.employee_number];
    if (!target) continue;
    let intervals = [];
    try { intervals = JSON.parse(row.intervals_json || "[]"); } catch {}
    target.days.push({
      workDate: row.work_date,
      actualMinutes: Number(row.actual_minutes || 0),
      valuedMinutes: Number(row.valued_minutes || 0),
      surchargeMinutes: Number(row.surcharge_minutes || 0),
      intervals: Array.isArray(intervals) ? intervals : [],
      absence: row.absence_code || "",
    });
  }
  const xoffiBalanceByEmployee = {};
  for (const row of xoffiBalanceRows) {
    if (xoffiBalanceByEmployee[row.employee_number]) continue;
    xoffiBalanceByEmployee[row.employee_number] = {
      minutes: Number(row.closing_balance_minutes || 0),
      weekStart: row.balance_week_start,
    };
  }

  return {
    weekStart,
    weekEnd,
    calendarWeek: getIsoWeek(weekStart),
    context,
    locations: await getLocationsForSession(session, true),
    settings,
    currentWeekStart: currentWeekStart(),
    isPastWeek: isPastWeekStart(weekStart),
    isPastWeekLocked: (isPastWeekStart(weekStart) && !allowPastWeekEditing)
      || (weekStart === currentWeekStart() && settingEnabled(settings, "current_week_auto_lock") && viennaNowLocal() >= currentWeekLockPoint(settings)),
    currentWeekLockPoint: currentWeekLockPoint(settings),
    manualScheduleLock,
    employees,
    shifts,
    weekOptions,
    staffAssignments: employeeLendings,
    pdfStaffAssignmentShifts,
    globalDayBlocks,
    scheduleNote: await getScheduleNote(weekStart, context),
    globalBlockDates: Array.from(globalBlockDates),
    publicHolidays: publicHolidaysForRange(weekStart, weekEnd),
    totals,
    plannedTotals,
    inStoreTotals,
    bonusTotals,
    optionCreditTotals,
    sicknessCredits,
    sicknessCreditTotals,
    saturdayStats,
    xoffiTime: {
      weekByEmployee: xoffiWeekByEmployee,
      balanceByEmployee: xoffiBalanceByEmployee,
    },
    workRuleAssessment,
    branchSupervisionAssessment,
  };
}

function validateYear(value = new Date().getFullYear()) {
  const year = Number(value);
  if (!Number.isInteger(year) || year < 2000 || year > 2100) {
    throw httpError(400, "Bitte ein gültiges Jahr auswählen.");
  }
  return year;
}

function daysBetweenInclusive(startDate, endDate) {
  return Math.round((new Date(`${endDate}T12:00:00Z`) - new Date(`${startDate}T12:00:00Z`)) / 86400000) + 1;
}

function overlapDateRange(startA, endA, startB, endB) {
  return startA <= endB && startB <= endA;
}

function monthStart(year, monthIndex) {
  return `${year}-${String(monthIndex + 1).padStart(2, "0")}-01`;
}

function monthEnd(year, monthIndex) {
  const date = new Date(Date.UTC(year, monthIndex + 1, 0, 12));
  return date.toISOString().slice(0, 10);
}

function vacationGroupKey(row) {
  return row.group_id || `legacy-${row.id}`;
}

async function getVacationPlan(yearValue, contextInput = {}, session = null) {
  const year = validateYear(yearValue);
  const yearStart = `${year}-01-01`;
  const yearEnd = `${year}-12-31`;
  const today = new Date().toISOString().slice(0, 10);
  const consumedEnd = today < yearStart ? null : today > yearEnd ? yearEnd : today;
  const context = await resolvePlanningContext(contextInput);
  assertSessionContextScope(session, context);
  const settings = applyScopedPdfSettings(await settingsForLocation(context.locationId), context, "vacation");
  const vacationQuery = {
    locationId: context.locationId,
    departmentId: context.departmentId || null,
    year,
    yearStart,
    yearEnd,
  };
  const publicHolidays = publicHolidaysForRange(yearStart, yearEnd);
  const globalHolidayBlocks = getGlobalDayBlocksForRange(yearStart, yearEnd, context.locationId)
    .filter((block) => block.is_public_holiday)
    .map((block) => ({ date: block.block_date, name: block.reason || block.holiday_name || "Feiertag" }));
  const vacationHolidays = [...publicHolidays];
  for (const holiday of globalHolidayBlocks) {
    if (!vacationHolidays.some((item) => item.date === holiday.date)) vacationHolidays.push(holiday);
  }
  const [employeeRows, entitlementRows, optionRows] = await Promise.all([
    planningSettingsRepository.listVacationEmployees(vacationQuery),
    planningSettingsRepository.listVacationEntitlements(vacationQuery),
    planningSettingsRepository.listVacationOptions(vacationQuery),
  ]);
  const employees = employeeRows.map(serializeEmployee);
  const entitlements = Object.fromEntries(employees.map((employee) => [employee.personnel_number, 0]));
  const entitlementsSaved = Object.fromEntries(employees.map((employee) => [employee.personnel_number, false]));
  for (const row of entitlementRows) {
    entitlements[row.employee_number] = Number(row.days || 0);
    entitlementsSaved[row.employee_number] = true;
  }

  const grouped = new Map();
  for (const row of optionRows) {
    const key = vacationGroupKey(row);
    const existing = grouped.get(key);
    if (!existing) {
      grouped.set(key, {
        group_id: key,
        employee_number: row.employee_number,
        nickname: row.nickname,
        full_name: row.full_name,
        color: row.color,
        date_from: row.date_from,
        date_to: row.date_to,
        note: row.note || "",
        ids: [row.id],
      });
    } else {
      existing.date_from = existing.date_from < row.date_from ? existing.date_from : row.date_from;
      existing.date_to = existing.date_to > row.date_to ? existing.date_to : row.date_to;
      existing.note = existing.note || row.note || "";
      existing.ids.push(row.id);
    }
  }

  const vacations = Array.from(grouped.values())
    .map((vacation) => {
      const clippedFrom = vacation.date_from < yearStart ? yearStart : vacation.date_from;
      const clippedTo = vacation.date_to > yearEnd ? yearEnd : vacation.date_to;
      return {
        ...vacation,
        days: vacationDayCount(clippedFrom, clippedTo, context.locationId),
        calendar_days: daysBetweenInclusive(clippedFrom, clippedTo),
      };
    })
    .sort((a, b) => a.date_from.localeCompare(b.date_from) || a.nickname.localeCompare(b.nickname));

  const plannedByEmployee = Object.fromEntries(employees.map((employee) => [employee.personnel_number, 0]));
  const consumedByEmployee = Object.fromEntries(employees.map((employee) => [employee.personnel_number, 0]));
  for (const vacation of vacations) {
    plannedByEmployee[vacation.employee_number] = (plannedByEmployee[vacation.employee_number] || 0) + vacation.days;
    if (consumedEnd && vacation.date_from <= consumedEnd) {
      const clippedFrom = vacation.date_from < yearStart ? yearStart : vacation.date_from;
      const clippedTo = vacation.date_to > consumedEnd ? consumedEnd : vacation.date_to;
      consumedByEmployee[vacation.employee_number] =
        (consumedByEmployee[vacation.employee_number] || 0) + vacationDayCount(clippedFrom, clippedTo, context.locationId);
    }
  }
  const totals = Object.fromEntries(
    employees.map((employee) => {
      const entitlement = Number(entitlements[employee.personnel_number] || 0);
      const planned = Number(plannedByEmployee[employee.personnel_number] || 0);
      const consumed = Number(consumedByEmployee[employee.personnel_number] || 0);
      return [
        employee.personnel_number,
        {
          entitlement,
          entitlement_saved: Boolean(entitlementsSaved[employee.personnel_number]),
          used: planned,
          planned,
          consumed,
          remaining: entitlement - planned,
        },
      ];
    }),
  );

  return {
    year,
    context,
    locations: await getLocationsForSession(session, true),
    settings,
    employees,
    entitlements,
    entitlementsSaved,
    vacations,
    totals,
    publicHolidays: vacationHolidays.sort((a, b) => a.date.localeCompare(b.date)),
  };
}

async function getCentralVacationPlan(yearValue, filters = {}) {
  const year = validateYear(yearValue);
  const yearStart = `${year}-01-01`;
  const yearEnd = `${year}-12-31`;
  const today = viennaTodayIso();
  const consumedEnd = today < yearStart ? null : today > yearEnd ? yearEnd : today;
  const costCenterId = String(filters.costCenterId || filters.cost_center_id || "").trim();
  const locationId = String(filters.locationId || filters.location || "").trim();
  const departmentId = normalizeDepartmentId(filters.departmentId ?? filters.department, true);
  const includeInactive = String(filters.includeInactive ?? "1") !== "0";
  if (costCenterId) await validateCostCenterExists(costCenterId, { allowInactive: true });
  if (locationId) await validateLocationExists(normalizeLocationId(locationId));
  if (departmentId) await validateDepartmentExists(departmentId, locationId || null);

  const centralQuery = {
    includeInactive: includeInactive ? 1 : 0,
    costCenterId,
    locationId,
    departmentId: departmentId || null,
    year,
    yearStart,
    yearEnd,
  };
  const [employeeRows, entitlementRows, centralOptionRows] = await Promise.all([
    planningSettingsRepository.listCentralVacationEmployees(centralQuery),
    planningSettingsRepository.listVacationEntitlements(centralQuery),
    planningSettingsRepository.listCentralVacationOptions(centralQuery),
  ]);
  const employees = employeeRows.map(serializeEmployee);
  const employeeLookup = new Map(employees.map((employee) => [employee.personnel_number, employee]));
  const employeeNumbers = [...employeeLookup.keys()];
  const entitlements = Object.fromEntries(employeeNumbers.map((employeeNumber) => [employeeNumber, 0]));
  const entitlementsSaved = Object.fromEntries(employeeNumbers.map((employeeNumber) => [employeeNumber, false]));
  for (const row of entitlementRows) {
    if (!employeeLookup.has(row.employee_number)) continue;
    entitlements[row.employee_number] = Number(row.days || 0);
    entitlementsSaved[row.employee_number] = true;
  }

  const grouped = new Map();
  if (employeeNumbers.length) {
    const vacationRequestSources = new Map(
      (await absenceManagementRepository.vacationRequestSources())
        .map((row) => [String(row.vacation_group_id || ""), row.source]),
    );
    const rows = centralOptionRows
      .filter((row) => employeeLookup.has(row.employee_number))
      .map((row) => ({
        ...row,
        source: vacationRequestSources.get(String(row.group_id || "")) || "direct",
      }));
    for (const row of rows) {
      const key = vacationGroupKey(row);
      const employee = employeeLookup.get(row.employee_number);
      const existing = grouped.get(key);
      if (existing) {
        existing.date_from = existing.date_from < row.date_from ? existing.date_from : row.date_from;
        existing.date_to = existing.date_to > row.date_to ? existing.date_to : row.date_to;
        existing.has_note ||= Boolean(String(row.note || "").trim());
        existing.ids.push(Number(row.id));
        continue;
      }
      grouped.set(key, {
        group_id: key,
        employee_number: row.employee_number,
        nickname: employee?.nickname || "",
        full_name: employee?.full_name || "",
        color: employee?.color || "#0b84c6",
        cost_center_id: employee?.cost_center_id || "",
        cost_center_code: employee?.cost_center_code || "",
        cost_center_name: employee?.cost_center_name || "",
        home_location_id: employee?.home_location_id || "",
        home_location_name: employee?.home_location_name || "",
        preferred_department_id: employee?.preferred_department_id || null,
        preferred_department_name: employee?.preferred_department_name || "",
        date_from: row.date_from,
        date_to: row.date_to,
        source: row.source || "direct",
        has_note: Boolean(String(row.note || "").trim()),
        ids: [Number(row.id)],
      });
    }
  }
  const vacations = (await Promise.all([...grouped.values()].map(async (vacation) => {
    const employee = employeeLookup.get(vacation.employee_number);
    const employeeLocationId = employee?.home_location_id || null;
    const clippedFrom = vacation.date_from < yearStart ? yearStart : vacation.date_from;
    const clippedTo = vacation.date_to > yearEnd ? yearEnd : vacation.date_to;
    return {
      ...vacation,
      days: vacationDayCount(clippedFrom, clippedTo, employeeLocationId),
      calendar_days: daysBetweenInclusive(clippedFrom, clippedTo),
    };
  }))).sort((left, right) => left.date_from.localeCompare(right.date_from)
    || left.cost_center_code.localeCompare(right.cost_center_code, "de-AT")
    || left.employee_number.localeCompare(right.employee_number, "de-AT", { numeric: true }));

  const totals = Object.fromEntries(await Promise.all(employees.map(async (employee) => {
    const employeeVacations = vacations.filter((vacation) => vacation.employee_number === employee.personnel_number);
    const planned = employeeVacations.reduce((sum, vacation) => sum + Number(vacation.days || 0), 0);
    let consumed = 0;
    if (consumedEnd) {
      for (const vacation of employeeVacations.filter((entry) => entry.date_from <= consumedEnd)) {
        const from = vacation.date_from < yearStart ? yearStart : vacation.date_from;
        const to = vacation.date_to > consumedEnd ? consumedEnd : vacation.date_to;
        if (to >= from) consumed += vacationDayCount(from, to, employee.home_location_id || null);
      }
    }
    const entitlement = Number(entitlements[employee.personnel_number] || 0);
    return [employee.personnel_number, {
      entitlement, entitlement_saved: Boolean(entitlementsSaved[employee.personnel_number]),
      used: planned, planned, consumed, remaining: entitlement - planned,
    }];
  })));
  return {
    year,
    scope: "global",
    filters: { costCenterId, locationId, departmentId, includeInactive },
    employees,
    entitlements,
    entitlementsSaved,
    vacations,
    approvedVacations: vacations,
    totals,
    costCenters: await getCostCenters(true),
    locations: await getLocations(true),
    privacy: { notesIncluded: false },
  };
}

async function validateVacationEntry(
  body,
  excludeGroupId = null,
  repository = absenceManagementRepository,
) {
  const employeeNumber = String(body.employeeNumber || "").trim();
  const dateFrom = String(body.dateFrom || "");
  const dateTo = String(body.dateTo || "");
  const note = String(body.note || "").trim();

  if (!await repository.vacationEntryEmployee(employeeNumber)) {
    throw httpError(404, "Das ausgewählte Teammitglied wurde nicht gefunden.");
  }
  if (!isIsoDate(dateFrom) || !isIsoDate(dateTo) || dateTo < dateFrom) {
    throw httpError(400, "Bitte einen gültigen Urlaubszeitraum eingeben.");
  }
  const overlappingOption = await repository.vacationEntryOverlap({
    employeeNumber,
    dateFrom,
    dateTo,
    excludeGroupId: String(excludeGroupId || ""),
  });
  if (overlappingOption) {
    throw httpError(
      409,
      `In diesem Zeitraum ist bereits „${optionLabel(overlappingOption.option_type)}“ eingetragen.`,
    );
  }
  const existingShift = await repository.vacationEntryShiftConflict({
    employeeNumber,
    dateFrom,
    dateTo,
  });
  if (existingShift) {
    throw httpError(
      409,
      `Für ${existingShift.shift_date} ist bereits ein Dienst von ${existingShift.start_time} bis ${existingShift.end_time} Uhr eingetragen.`,
    );
  }

  return { employeeNumber, dateFrom, dateTo, note };
}

async function validateGlobalDayBlock(body, existingId = 0, actor = null) {
  const context = await resolvePlanningContext({ ...body, departmentId: null, department: null });
  const blockDate = String(body.blockDate || body.date || "").trim();
  const weekStart = getMonday(String(body.weekStart || blockDate || ""));
  const reason = String(body.reason || "").trim();
  const isPublicHoliday = body.isPublicHoliday === true ? 1 : 0;

  if (!isIsoDate(blockDate)) throw httpError(400, "Bitte ein gültiges Datum für den Sperrtag auswählen.");
  if (blockDate < weekStart || blockDate > addDays(weekStart, 6)) {
    throw httpError(400, "Der Sperrtag muss innerhalb der ausgewählten Kalenderwoche liegen.");
  }
  if (!reason) throw httpError(400, "Bitte einen Grund für den Sperrtag eintragen.");
  await assertWeekEditable(
    weekStart,
    await settingsForLocation(context.locationId),
    actor,
    context.locationId,
  );

  const existingBlock = planningSettingsReadModel.globalDayBlocks.find((entry) => (
    String(entry.location_id) === String(context.locationId)
    && entry.block_date === blockDate
    && Number(entry.id) !== Number(existingId || 0)
  ));
  if (existingBlock) {
    throw httpError(409, "Für diesen Tag ist bereits eine ganztägige Sperre eingetragen.");
  }

  const shiftCount = (await planningSettingsRepository.countShiftsForDateLocation({
    date: blockDate,
    locationId: context.locationId,
  }))?.count || 0;
  if (Number(shiftCount) > 0) {
    throw httpError(409, "Für diesen Tag sind bereits Dienste eingetragen. Bitte zuerst die Dienste entfernen.");
  }

  return { locationId: context.locationId, weekStart, blockDate, reason, isPublicHoliday };
}

const scheduleNoteMaxLength = 900;

function stripEmoji(value) {
  return String(value || "")
    .replace(/[\p{Extended_Pictographic}\uFE0F\u200D]/gu, "")
    .replace(/[\u2600-\u27BF]/gu, "")
    .replace(/\uFEFF/g, "");
}

function decodeBasicEntities(value) {
  return String(value || "")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

function textFromScheduleNoteHtml(html) {
  return decodeBasicEntities(
    String(html || "")
      .replace(/<\/(div|p)>/gi, "\n")
      .replace(/<br\s*\/?>/gi, "\n")
      .replace(/<[^>]*>/g, ""),
  )
    .replace(/\u00a0/g, " ")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function sanitizeScheduleNoteHtml(input) {
  let html = stripEmoji(String(input || ""));
  html = html.replace(/<script[\s\S]*?<\/script>/gi, "").replace(/<style[\s\S]*?<\/style>/gi, "");
  html = html.replace(/<span[^>]*class\s*=\s*["'][^"']*\bql-cursor\b[^"']*["'][^>]*>[\s\S]*?<\/span>/gi, "");
  html = html.replace(/<[^>]*>/g, (tag) => {
    const lower = tag.toLowerCase();
    if (/^<(b|strong)(\s[^>]*)?>$/.test(lower)) return "<b>";
    if (/^<\/(b|strong)>$/.test(lower)) return "</b>";
    if (/^<(i|em)(\s[^>]*)?>$/.test(lower)) return "<i>";
    if (/^<\/(i|em)>$/.test(lower)) return "</i>";
    if (/^<u(\s[^>]*)?>$/.test(lower)) return "<u>";
    if (/^<\/u>$/.test(lower)) return "</u>";
    if (/^<br\s*\/?>$/.test(lower)) return "<br>";
    if (/^<(div|p)(\s[^>]*)?>$/.test(lower)) return "<div>";
    if (/^<\/(div|p)>$/.test(lower)) return "</div>";
    if (/^<span\b/i.test(lower)) {
      const size = lower.match(/data-size\s*=\s*["']?(small|normal|large)["']?/i)?.[1]
        || lower.match(/class\s*=\s*["'][^"']*\bql-size-(small|large)\b/i)?.[1]
        || "normal";
      return `<span data-size="${size}">`;
    }
    if (/^<\/span>$/.test(lower)) return "</span>";
    return "";
  });
  return html.trim();
}

async function getScheduleNote(weekStart, context) {
  const row = await organizationPersonnelRepository.getScheduleNote(
    context.locationId,
    pdfDepartmentKey(context),
    weekStart,
  );
  if (!row || !String(row.note_text || "").trim()) return null;
  return {
    location_id: row.location_id,
    department_key: row.department_key,
    week_start: row.week_start,
    note_text: row.note_text,
    note_html: row.note_html || "",
    font_size: row.font_size,
    bold: Boolean(row.bold),
    italic: Boolean(row.italic),
    underline: Boolean(row.underline),
    updated_at: row.updated_at,
  };
}

async function validateScheduleNote(body, actor = null) {
  const weekStart = getMonday(isIsoDate(body.weekStart) ? body.weekStart : undefined);
  const context = await resolvePlanningContext(body);
  await assertWeekEditable(
    weekStart,
    await settingsForLocation(context.locationId),
    actor,
    context.locationId,
  );
  const noteHtml = sanitizeScheduleNoteHtml(body.noteHtml || "");
  const noteText = stripEmoji(
    textFromScheduleNoteHtml(noteHtml) || String(body.noteText || body.text || ""),
  ).trim();
  if (!noteText) throw httpError(400, "Bitte eine Bemerkung eingeben.");
  if (noteText.length > scheduleNoteMaxLength) {
    throw httpError(400, `Die Bemerkung ist zu lang. Maximal ${scheduleNoteMaxLength} Zeichen.`);
  }
  return {
    weekStart,
    context,
    noteText,
    noteHtml: noteHtml || noteText,
    fontSize: "medium",
    bold: 0,
    italic: 0,
    underline: 0,
  };
}

function createVacationGroupId() {
  return `vac-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

async function insertVacationEntries(vacation, groupId, repository = absenceManagementRepository) {
  let date = vacation.dateFrom;
  let created = 0;
  while (date <= vacation.dateTo) {
    const weekStart = getMonday(date);
    const weekEnd = addDays(weekStart, 6);
    const segmentEnd = weekEnd < vacation.dateTo ? weekEnd : vacation.dateTo;
    await repository.insertVacationOption({
      employeeNumber: vacation.employeeNumber,
      groupId,
      weekStart,
      dateFrom: date,
      dateTo: segmentEnd,
      note: vacation.note,
    });
    created += 1;
    date = addDays(segmentEnd, 1);
  }
  return created;
}

async function vacationGroupSnapshot(groupId, repository = absenceManagementRepository) {
  const rows = String(groupId).startsWith("legacy-")
    ? await repository.vacationRowsByNumericId(
      Number(String(groupId).replace("legacy-", "")),
    )
    : await repository.vacationRowsByGroupId(String(groupId));
  if (!rows.length) return null;
  return {
    groupId: String(groupId),
    employeeNumber: rows[0].employee_number,
    dateFrom: rows[0].date_from,
    dateTo: rows.at(-1).date_to,
    segments: rows.map((row) => ({
      id: Number(row.id),
      weekStart: row.week_start,
      dateFrom: row.date_from,
      dateTo: row.date_to,
      note: row.note || "",
      createdAt: row.created_at,
    })),
  };
}

async function recordVacationHistory(
  action,
  groupId,
  snapshot,
  actor = "system",
  repository = absenceManagementRepository,
) {
  if (!snapshot?.employeeNumber) return null;
  const id = crypto.randomUUID();
  const createdAt = new Date().toISOString();
  const receipt = {
    schemaVersion: 1,
    id,
    action,
    groupId: String(groupId),
    employeeNumber: snapshot.employeeNumber,
    snapshot,
    createdBy: String(actor || "system"),
    createdAt,
  };
  const receiptSha256 = sha256(JSON.stringify(receipt));
  await repository.insertVacationHistory({
    id,
    groupId: String(groupId),
    employeeNumber: snapshot.employeeNumber,
    action,
    snapshotJson: protectJson(snapshot, {
      namespace: "vacation-history-event",
      recordId: id,
      field: "snapshot",
      employeeNumber: String(snapshot.employeeNumber),
    }),
    receiptSha256,
    createdBy: String(actor || "system"),
    createdAt,
  });
  return { ...receipt, receiptSha256 };
}

async function deleteVacationRows(groupId, repository = absenceManagementRepository) {
  if (String(groupId).startsWith("legacy-")) {
    const id = Number(String(groupId).replace("legacy-", ""));
    if (!Number.isInteger(id)) return 0;
    return (await repository.deleteVacationByNumericId({ id })).rowsAffected;
  }
  return (await repository.deleteVacationByGroupId({ groupId: String(groupId) })).rowsAffected;
}

async function createVacationEntries(vacation, actor = "system", options = {}) {
  const groupId = createVacationGroupId();
  const boundRepository = options.repository || null;
  const mutate = async (repository) => {
    await assertNoVacationLendingOverlap(
      vacation.employeeNumber,
      vacation.dateFrom,
      vacation.dateTo,
      repository,
    );
    const assessment = options.assessment || await assertVacationGovernanceAvailable(
      vacation.employeeNumber,
      vacation,
    );
    const created = await insertVacationEntries(vacation, groupId, repository);
    await recordVacationHistory(
      "created",
      groupId,
      await vacationGroupSnapshot(groupId, repository),
      actor,
      repository,
    );
    if (options.auditAction) {
      await auditAbsence(
        repository,
        actor,
        options.auditAction,
        "approved_absence",
        groupId,
        approvedAbsenceAuditDetail({ ...vacation, optionType: "vacation", allDay: 1 }),
      );
    }
    return { groupId, created, assessment };
  };
  return boundRepository
    ? mutate(boundRepository)
    : absenceManagementRepository.transaction(mutate);
}

async function vacationGroupExists(groupId) {
  if (String(groupId).startsWith("legacy-")) {
    const id = Number(String(groupId).replace("legacy-", ""));
    return Number.isInteger(id)
      && Boolean(await absenceManagementRepository.vacationExistsByNumericId(id));
  }
  return Boolean(
    await absenceManagementRepository.vacationExistsByGroupId(String(groupId)),
  );
}

async function replaceVacationGroup(groupId, vacation, actor = "system", options = {}) {
  const boundRepository = options.repository || null;
  const mutate = async (repository) => {
    await assertNoVacationLendingOverlap(
      vacation.employeeNumber,
      vacation.dateFrom,
      vacation.dateTo,
      repository,
    );
    const assessment = options.assessment || await assertVacationGovernanceAvailable(
      vacation.employeeNumber,
      vacation,
      groupId,
    );
    const before = await vacationGroupSnapshot(groupId, repository);
    if (!before) throw httpError(404, "Der Urlaubseintrag wurde nicht gefunden.");
    await deleteVacationRows(groupId, repository);
    const created = await insertVacationEntries(vacation, groupId, repository);
    await recordVacationHistory("replaced", groupId, {
      ...await vacationGroupSnapshot(groupId, repository),
      previous: before,
    }, actor, repository);
    if (options.auditAction) {
      await auditAbsence(
        repository,
        actor,
        options.auditAction,
        "approved_absence",
        groupId,
        approvedAbsenceAuditDetail({ ...vacation, optionType: "vacation", allDay: 1 }),
      );
    }
    return { groupId, created, assessment };
  };
  return boundRepository
    ? mutate(boundRepository)
    : absenceManagementRepository.transaction(mutate);
}

async function deleteVacationGroup(
  groupId,
  actor = "system",
  action = "deleted",
  boundRepository = null,
  auditAction = "",
) {
  const mutate = async (repository) => {
    const snapshot = await vacationGroupSnapshot(groupId, repository);
    const changes = await deleteVacationRows(groupId, repository);
    if (changes && snapshot) {
      await recordVacationHistory(action, groupId, snapshot, actor, repository);
      if (auditAction) {
        await auditAbsence(
          repository,
          actor,
          auditAction,
          "approved_absence",
          String(groupId),
          approvedAbsenceAuditDetail({ ...snapshot, optionType: "vacation", allDay: 1 }),
        );
      }
    }
    return changes;
  };
  return boundRepository
    ? mutate(boundRepository)
    : absenceManagementRepository.transaction(mutate);
}

function databasePragmaValue(name) {
  return postgresqlActive ? null : sqliteSystemDiagnosticsOperations.pragmaValue(name);
}

function directoryDiagnostics(directory) {
  try {
    fs.mkdirSync(directory, { recursive: true });
    fs.accessSync(directory, fs.constants.R_OK | fs.constants.W_OK);
    const stats = typeof fs.statfsSync === "function" ? fs.statfsSync(directory) : null;
    return {
      writable: true,
      freeBytes: stats ? Number(stats.bavail) * Number(stats.bsize) : null,
      volume: path.parse(path.resolve(directory)).root,
    };
  } catch (error) {
    return { writable: false, freeBytes: null, volume: path.parse(path.resolve(directory)).root, error: error.message };
  }
}

function latestDatabaseBackup(backupDirectory, onError = () => {}, expectedStream = "app") {
  try {
    let archived = [], archiveNeedsReview = false;
    try {
      const archive = prepareLocalBackupArchive({ backupDirectory, keep: backupKeep, vault: integrationSecretVault, expectedStream, cachedMetadataOnly: true });
      archived = archive ? archive.listMetadata({ verifyInventory: false }) : [];
    } catch (error) {
      // An archive lock/journal failure must remain visible without hiding an
      // independently committed raw rollback point that is still present.
      archiveNeedsReview = true;
      onError(error);
    }
    const committed = listCommittedBackupMetadata(backupDirectory, { limit: 1 })[0];
    const legacy = listLegacyBackupMetadata(backupDirectory, { limit: 1 })[0];
    const selected = [committed, legacy, ...archived].filter(Boolean).sort((left, right) => right.modifiedMs - left.modifiedMs)[0];
    if (!selected) return null;
    return {
      name: selected.databaseFileName || path.basename(selected.databasePath),
      path: selected.databasePath || null,
      marker: selected.markerPath || null,
      modifiedAt: selected.modifiedAt,
      modifiedMs: selected.modifiedMs,
      committed: selected.committed,
      legacy: selected.legacy,
      verified: selected.verified,
      archived: selected.archived === true,
      archiveSnapshotId: selected.archiveSnapshotId || null,
      verificationCached: true,
      archiveNeedsReview,
    };
  } catch (error) { onError(error); return null; }
}

const BACKUP_FUTURE_TOLERANCE_MS = 5 * 60 * 1000;

function backupAgeState(backup, nowMs = Date.now()) {
  if (!backup || !Number.isFinite(Number(backup.modifiedMs))) {
    return { ageHours: null, timestampValid: false, future: false };
  }
  const difference = Number(nowMs) - Number(backup.modifiedMs);
  const future = difference < -BACKUP_FUTURE_TOLERANCE_MS;
  return {
    ageHours: future ? null : Math.max(0, difference / 3600000),
    timestampValid: !future,
    future,
  };
}

function newestDatabaseBackup(...backups) {
  return backups.filter((backup) => backup && Number.isFinite(Number(backup.modifiedMs)))
    .sort((left, right) => Number(right.modifiedMs) - Number(left.modifiedMs))[0] || null;
}

async function serverDiagnostics() {
  const settings = getSettings();
  const portal = getPortalStatus();
  const migration = (await sqliteSystemDiagnosticsOperations.latestMigration());
  const warnings = [];
  const alerts = [];
  const addAlert = (id, severity, title, message, category = "system", action = "open-server-status") => {
    alerts.push({ id, severity, category, title, message, action });
    warnings.push(message);
  };
  const requiredStorageDirectories = {
    database: path.dirname(path.resolve(databasePath)),
    appBackups: appBackupDirectory,
    brandingKits: brandingKitsDirectory,
    privateData: privateDataDirectory,
    amu: amuStorageDirectory,
  };
  const requiredStorageHealth = Object.fromEntries(Object.entries(requiredStorageDirectories)
    .map(([name, directory]) => [name, { directory, ...directoryDiagnostics(directory) }]));
  const requiredStorageVolumes = Object.values(requiredStorageHealth).map((item) => item.volume).filter(Boolean);
  const requiredStorageFreeBytes = Object.values(requiredStorageHealth).map((item) => item.freeBytes).filter(Number.isFinite);
  const dataHealth = {
    writable: Object.values(requiredStorageHealth).every((item) => item.writable),
    freeBytes: requiredStorageFreeBytes.length ? Math.min(...requiredStorageFreeBytes) : null,
    volume: requiredStorageVolumes[0] || path.parse(path.resolve(dataRootDirectory)).root,
    directories: requiredStorageHealth,
  };
  let externalDirectory = "";
  if (!serverModeActive) {
    try { externalDirectory = backupDirectoryFromSettings(settings); } catch (error) {
      warnings.push(`Das externe Backupziel ist ungültig: ${error.message}`);
      alerts.push({ id: "EXTERNAL_BACKUP_TARGET_INVALID", severity: "critical", category: "backup", title: "Sicherungsziel ungültig", message: "Das konfigurierte externe Sicherungsziel muss durch die technische Administration geprüft werden.", action: "open-server-status" });
    }
  }
  const backupHealth = externalDirectory ? directoryDiagnostics(externalDirectory) : { writable: false, freeBytes: null, volume: "" };
  const backupMetadataError = () => addAlert("BACKUP_METADATA_UNAVAILABLE", "critical", "Sicherungsarchiv prüfen",
    "Die Sicherungsmetadaten oder die lokale Archivkonfiguration konnten nicht sicher geprüft werden.", "backup");
  const latestExternalBackup = externalDirectory ? latestDatabaseBackup(externalDirectory, backupMetadataError, "external") : null;
  const postgresqlStatus = postgresqlActive && !persistenceConfiguration.rehearsal
    ? require('./lib/persistence/postgresql/operations/status').readStatus(persistenceConfiguration.binding) : null;
  const latestAppBackup = postgresqlActive ? postgresqlStatus?.backup || null : latestDatabaseBackup(appBackupDirectory, backupMetadataError);
  if (postgresqlStatus?.code) addAlert('PG_OPERATIONS_ATTENTION', 'warning', 'Datenbankwartung prüfen',
    'Der letzte Wartungs- oder Sicherungsstatus muss durch die technische Administration geprüft werden.', 'backup');
  const backgroundBackup = localBackupArchiveEnabled()
    ? require("./lib/background-backup-process").backgroundBackupStatus() : null;
  if (backgroundBackup?.lastErrorCode) addAlert("LOCAL_ARCHIVE_BACKGROUND_FAILED", "warning", "Archivierung prüfen",
    "Die letzte Hintergrundsicherung wurde nicht sicher abgeschlossen. Vorhandene Sicherungspunkte bleiben erhalten.", "backup");
  const latestBackup = serverModeActive
    ? latestAppBackup
    : newestDatabaseBackup(latestExternalBackup, latestAppBackup);
  const latestBackupState = backupAgeState(latestBackup);
  const latestExternalBackupState = backupAgeState(latestExternalBackup);
  const latestAppBackupState = backupAgeState(latestAppBackup);
  const latestBackupAgeHours = latestBackupState.ageHours;
  const latestExternalBackupAgeHours = latestExternalBackupState.ageHours;
  const backupFreshnessHours = Math.max(6, Number(settings.backup_interval_hours || 24) * 3);
  const externalBackupReady = !serverModeActive
    && settingEnabled(settings, "external_backup_enabled") && backupHealth.writable
    && latestExternalBackup?.committed === true
    && latestExternalBackupState.timestampValid
    && latestExternalBackupAgeHours !== null && latestExternalBackupAgeHours <= backupFreshnessHours;
  const offsiteConfigurationClaim = String(
    process.env.GRABENPLANER_OFFSITE_CONFIGURED || "",
  ).trim();
  const offsiteConfigured = offsiteConfigurationClaim === "1";
  const offsiteStatus = readOffsiteBackupStatus({
    configured: offsiteConfigurationClaim === "1"
      ? true
      : offsiteConfigurationClaim === "0"
        ? false
        : undefined,
  });
  const offsiteApplicable = serverModeActive || offsiteConfigured || offsiteStatus.statusAvailable;
  const recoveryAssurance = readRecoveryAssuranceStatus({ configured: offsiteConfigured });
  const configuredOffsiteProviderId = String(
    process.env.GRABENPLANER_OFFSITE_PROVIDER || "",
  ).trim();
  const offsiteProviderBindingMatches = offsiteStatus.statusAvailable === true
    && offsiteStatus.configured === true
    && configuredOffsiteProviderId.length > 0
    ? offsiteStatus.providerId === configuredOffsiteProviderId
    : undefined;
  const offsiteProviderPolicy = evaluateOffsiteProviderPolicy({
    selectedProviderId: configuredOffsiteProviderId,
    configured: offsiteStatus.configured === true,
    providerBindingMatches: offsiteProviderBindingMatches,
    reachable: offsiteStatus.statusAvailable === true
      ? offsiteStatus.state === "ok"
      : undefined,
    backupCurrent: offsiteStatus.statusAvailable === true
      ? offsiteStatus.state === "ok"
      && offsiteStatus.unresolvedFailures?.backup !== true
      && Number.isFinite(offsiteStatus.agesHours?.backup)
      : undefined,
    repositoryCheckPassed: offsiteStatus.statusAvailable === true
      ? offsiteStatus.state === "ok"
      && offsiteStatus.unresolvedFailures?.fullCheck !== true
      && Number.isFinite(offsiteStatus.agesHours?.repositoryCheck)
      && Number.isFinite(offsiteStatus.agesHours?.fullCheck)
      : undefined,
    isolatedRestorePassed: offsiteStatus.statusAvailable === true
      ? offsiteStatus.state === "ok"
      && offsiteStatus.unresolvedFailures?.restoreTest !== true
      && Number.isFinite(offsiteStatus.agesHours?.restoreTest)
      : undefined,
    recoveryAssurancePassed: recoveryAssurance.configured === true
      && recoveryAssurance.statusAvailable === true
      ? recoveryAssurance.state === "ok"
      && recoveryAssurance.integrityVerified === true
      && recoveryAssurance.stale !== true
      : undefined,
  });
  const offsite = {
    ...offsiteStatus,
    applicable: offsiteApplicable,
    provider: {
      selectionRequired: true,
      selectedProviderId: offsiteProviderPolicy.selectedProviderId,
      boundProviderId: offsiteStatus.providerId || null,
      bindingVerified: offsiteProviderBindingMatches === true,
      preferredProviderId: offsiteProviderPolicy.preferredProviderId,
      available: listOffsiteProviders(),
    },
    providerPolicy: offsiteProviderPolicy,
  };
  const offsiteBackupReady = offsiteProviderPolicy.systemCenterOk === true;
  const selectedOffsiteProvider = offsite.provider.available
    .find((provider) => provider.id === offsite.provider.selectedProviderId) || null;
  const monitorConfiguration = String(process.env.GRABENPLANER_MONITOR_CONFIGURED || "").trim();
  const monitorConfigured = monitorConfiguration === "1"
    || (monitorConfiguration !== "0" && serverModeActive && process.platform === "linux");
  const monitor = readServerMonitorStatus({ configured: monitorConfigured });
  const hostSecurityConfiguration = String(process.env.GRABENPLANER_HOST_SECURITY_CONFIGURED || "").trim();
  const hostSecurity = readHostSecurityStatus({
    configured: hostSecurityConfiguration === "1" ? true : (hostSecurityConfiguration === "0" ? false : undefined),
  });
  const amu = amuStorage ? amuStorage.diagnostics() : { ok: false, writable: false, error: amuStorageStartupError };
  const protectedIntegrationConnectionCount = (await sqliteSystemDiagnosticsOperations
    .protectedIntegrationConnectionCount());
  const integrationSecretsReady = protectedIntegrationConnectionCount === 0 || Boolean(integrationSecretVault);
  const runtimeErrors = runtimeValidationErrors(runtimeConfiguration);
  const publicHttpsReady = /^https:\/\//i.test(publicUrl);
  if (serverModeActive && !/^https:\/\//i.test(publicUrl)) addAlert("PUBLIC_HTTPS_MISSING", "critical", "HTTPS-Konfiguration fehlt", "Für den Serverbetrieb fehlt eine gültige öffentliche HTTPS-Adresse.", "security");
  if (serverModeActive && portal.adminSetupState !== "configured") addAlert("ADMIN_SETUP_REQUIRED", "critical", "Admin-Ersteinrichtung offen", "Vor der Freigabe muss ein geschützter Admin-Zugang eingerichtet sein.", "security");
  if (serverModeActive && !loopbackHosts.has(HOST.toLowerCase())) addAlert("LISTENER_NOT_LOOPBACK", "critical", "Interne Bindung prüfen", "Die Anwendung ist nicht ausschließlich an die interne Loopback-Schnittstelle gebunden.", "security");
  if (runtimeErrors.length) {
    warnings.push(...runtimeErrors);
    alerts.push({ id: "RUNTIME_CONFIGURATION_INVALID", severity: "critical", category: "system", title: "Serverkonfiguration prüfen", message: "Mindestens eine erforderliche Laufzeitkonfiguration ist ungültig oder unvollständig.", action: "open-server-status" });
  }
  if (!serverModeActive && settings.external_backup_enabled === "0") {
    addAlert("EXTERNAL_BACKUP_DISABLED", "warning", "Externe Sicherung deaktiviert", "Die zusätzliche externe Datensicherung ist deaktiviert.", "backup");
  }
  if (!dataHealth.writable) {
    const failedDirectories = Object.entries(requiredStorageHealth).filter(([, item]) => !item.writable).map(([name]) => name);
    warnings.push(`Mindestens ein benötigtes Server-Datenverzeichnis ist nicht beschreibbar: ${failedDirectories.join(", ")}.`);
    alerts.push({ id: "DATA_STORAGE_UNWRITABLE", severity: "critical", category: "storage", title: "Datenspeicher nicht beschreibbar", message: "Mindestens ein benötigter geschützter Datenbereich ist nicht beschreibbar.", action: "open-server-status" });
  }
  if (!serverModeActive) {
    if (settingEnabled(settings, "external_backup_enabled") && !backupHealth.writable) addAlert("EXTERNAL_BACKUP_TARGET_UNWRITABLE", "critical", "Sicherungsziel nicht beschreibbar", "Das externe Sicherungsziel ist derzeit nicht beschreibbar.", "backup");
    if (latestExternalBackup?.legacy) addAlert("EXTERNAL_BACKUP_LEGACY", "warning", "Älterer Sicherungsstand", "Der neueste externe Sicherungsstand besitzt noch keinen atomaren Abschlussmarker.", "backup");
    if (latestExternalBackupState.future) addAlert("EXTERNAL_BACKUP_TIMESTAMP_FUTURE", "critical", "Unplausible Sicherungszeit", "Der Zeitstempel der externen Sicherung liegt unplausibel in der Zukunft; Serverzeit und Sicherung müssen geprüft werden.", "backup");
    else if (latestExternalBackupAgeHours === null || latestExternalBackupAgeHours > backupFreshnessHours) addAlert("EXTERNAL_BACKUP_STALE", "critical", "Externe Sicherung fehlt oder ist zu alt", "Es wurde kein ausreichend aktueller verifizierter externer Sicherungsstand gefunden.", "backup");
  }
  if (latestAppBackupState.future) addAlert("APP_BACKUP_TIMESTAMP_FUTURE", "warning", "Unplausible interne Sicherungszeit", "Der Zeitstempel der internen Sicherung liegt unplausibel in der Zukunft.", "backup");
  if (!serverModeActive && externalDirectory && offsite.state !== "ok"
    && path.parse(path.resolve(databasePath)).root.toLowerCase() === path.parse(path.resolve(externalDirectory)).root.toLowerCase()) {
    addAlert("BACKUP_SAME_VOLUME", "warning", "Sicherung nicht getrennt", "Datenbank und zusätzliches Sicherungsziel liegen auf demselben Datenträger.", "backup");
  }
  if (!amu.ok) {
    warnings.push(`Der geschützte AUM-Speicher ist nicht betriebsbereit${amu.error ? `: ${amu.error}` : "."}`);
    alerts.push({ id: "AMU_STORAGE_UNAVAILABLE", severity: "critical", category: "storage", title: "AUM-Speicher nicht bereit", message: "Der geschützte Dokumentenspeicher ist derzeit nicht betriebsbereit.", action: "open-server-status" });
  }
  if (!integrationSecretsReady) addAlert("INTEGRATION_SECRET_UNAVAILABLE", "critical", "Schnittstellenschlüssel fehlt", "Für mindestens eine aktive direkte Verbindung fehlt der geschützte Integrationsschlüssel.", "security");
  const offsiteProviderSelectionReady = offsite.providerPolicy?.checks
    ?.find((check) => check.id === "selection")?.state === "pass";
  if (serverModeActive && !offsiteProviderSelectionReady) {
    addAlert(
      "OFFSITE_PROVIDER_SELECTION_REQUIRED",
      "warning",
      "Offsite-Anbieter auswählen",
      "Für die Offsite-Sicherung muss genau ein unterstützter Anbieter ausgewählt werden.",
      "backup",
    );
  } else if (serverModeActive && !offsite.configured) {
    addAlert("OFFSITE_BACKUP_NOT_CONFIGURED", "warning", "Offsite-Sicherung nicht eingerichtet", "Das verschlüsselte Offsite-Backup ist noch nicht eingerichtet.", "backup");
  } else if (offsite.configured && offsite.providerPolicy?.systemCenterOk !== true) {
    addAlert("OFFSITE_BACKUP_ATTENTION", offsite.state === "error" ? "critical" : "warning", "Offsite-Sicherung prüfen", "Die verschlüsselte Offsite-Sicherung oder eine Wiederherstellungsprüfung benötigt Aufmerksamkeit.", "backup");
  }
  if (recoveryAssurance.configured && recoveryAssurance.state !== "ok") {
    addAlert(
      "RECOVERY_ASSURANCE_ATTENTION",
      recoveryAssurance.state === "error" ? "critical" : "warning",
      "Recovery Assurance prüfen",
      recoveryAssurance.integrityVerified
        ? "Der letzte vollständige Recovery-Assurance-Lauf ist offen oder fehlgeschlagen."
        : "Die signierte Recovery-Prüfhistorie konnte nicht sicher bestätigt werden.",
      "backup",
    );
  }
  if (monitor.configured && monitor.state !== "ok") {
    addAlert("SERVER_MONITOR_ATTENTION", monitor.state === "error" ? "critical" : "warning", "Automatische Serverprüfung meldet ein Problem", "Mindestens eine automatische Serverprüfung ist fehlgeschlagen, unvollständig oder überfällig.", "monitoring");
  }
  for (const alert of buildHostSecurityAlerts(hostSecurity)) {
    addAlert(alert.id, alert.severity, alert.title, alert.message, alert.category);
  }
  if (serverModeActive && serviceControlToken.length < 32) addAlert("SERVICE_CONTROL_TOKEN_MISSING", "critical", "Dienststeuerung nicht abgesichert", "Der sichere Token für die Dienststeuerung fehlt.", "security");
  const lockedAccounts = (await sqliteSystemDiagnosticsOperations.lockedPortalAccountCount());
  if (lockedAccounts) addAlert("PORTAL_ACCOUNTS_LOCKED", "warning", "Zugänge vorübergehend gesperrt", `${lockedAccounts} Zugang/Zugänge sind derzeit wegen fehlgeschlagener Anmeldungen gesperrt.`, "security");
  const productionChecks = [
    { id: "mode", label: "Servermodus", ok: serverModeActive, detail: serverModeActive ? "aktiv" : "nicht aktiv" },
    { id: "runtime", label: "Produktionslaufzeit", ok: runtimeErrors.length === 0, detail: `${deploymentKind} / NODE_ENV=${process.env.NODE_ENV || "nicht gesetzt"}` },
    { id: "listener", label: "Interne Bindung", ok: loopbackHosts.has(HOST.toLowerCase()), detail: `${HOST}:${PORT}` },
    { id: "proxy", label: "Proxy-Vertrauen", ok: trustProxySetting.toLowerCase() === "loopback", detail: trustProxySetting },
    { id: "https", label: "HTTPS-Adresse", ok: publicHttpsReady, detail: publicUrl || "nicht konfiguriert" },
    { id: "admin", label: "Admin-Zugang", ok: portal.adminSetupState === "configured", detail: portal.adminSetupState },
    { id: "database", label: "Datenbankprüfung", ok: startupIntegrity[0] === "ok", detail: startupIntegrity[0] || "unbekannt" },
    { id: "data", label: "Datenverzeichnis", ok: dataHealth.writable, detail: dataHealth.writable ? "beschreibbar" : "nicht beschreibbar" },
    {
      id: "backup",
      label: serverModeActive ? "Verschlüsseltes Offsite-Backup" : "Externes Backup",
      ok: serverModeActive ? offsiteBackupReady : externalBackupReady,
      detail: serverModeActive
        ? (selectedOffsiteProvider
          ? `${selectedOffsiteProvider.label} · ${offsite.lastSuccessAt || offsite.lastErrorCode || "noch kein verifizierter Offsite-Stand"}`
          : "kein Offsite-Anbieter ausgewählt")
        : (latestExternalBackup ? latestExternalBackup.modifiedAt : "noch kein verifiziertes Backup"),
    },
    { id: "amu", label: "AUM-Speicher", ok: amu.ok, detail: amu.ok ? "verschlüsselt und beschreibbar" : (amu.error || "nicht bereit") },
    { id: "integration-secrets", label: "Schnittstellenschlüssel", ok: integrationSecretsReady, detail: protectedIntegrationConnectionCount ? `${protectedIntegrationConnectionCount} geschützte Verbindung(en)` : "derzeit nicht benötigt" },
    { id: "scanner", label: "AUM-Virenscanner", ok: !amu.requireScanner || (amu.scannerChecked && amu.scannerAvailable && amu.ok), detail: amu.scannerEngine || (amu.scannerChecked ? "nicht verfügbar" : "Prüfung läuft") },
    { id: "service-stop", label: "Dienststopp", ok: serviceControlToken.length >= 32, detail: serviceControlToken.length >= 32 ? "Token konfiguriert" : "Token fehlt" },
    ...(monitor.configured ? [{ id: "monitor", label: "Automatische Serverprüfung", ok: monitor.state === "ok", detail: monitor.generatedAt || monitor.lastErrorCode || "noch kein Status" }] : []),
    ...(hostSecurity.configured ? [{ id: "host-security", label: "Ubuntu-Host-Sicherheit", ok: hostSecurity.state === "ok", detail: hostSecurity.checkedAt || hostSecurity.lastErrorCode || "noch kein Status" }] : []),
    ...(recoveryAssurance.configured ? [{ id: "recovery-assurance", label: "Recovery Assurance", ok: recoveryAssurance.state === "ok" && recoveryAssurance.integrityVerified === true, detail: recoveryAssurance.generatedAt || recoveryAssurance.lastErrorCode || "noch kein signierter Lauf" }] : []),
  ];
  return {
    ready: startupIntegrity.length === 1 && startupIntegrity[0] === "ok" && dataHealth.writable
      && (!serverModeActive || (runtimeErrors.length === 0 && publicHttpsReady && portal.adminSetupState === "configured"
        && amu.ok && integrationSecretsReady && serviceControlToken.length >= 32)),
    mode: portal.operationMode,
    publicUrl: portal.publicUrl,
    httpsRequired: portal.httpsRequired,
    listenHost: HOST,
    port: PORT,
    trustProxy: portal.trustProxy,
    passwordMinLength: portal.passwordMinLength,
    database: {
      providerId: persistenceConfiguration.providerId,
      file: path.basename(databasePath),
      integrity: startupIntegrity[0] || "unknown",
      journalMode: databasePragmaValue("journal_mode"),
      synchronous: databasePragmaValue("synchronous"),
      busyTimeoutMs: Number(databasePragmaValue("busy_timeout") || 0),
      foreignKeys: Boolean(databasePragmaValue("foreign_keys")),
      migration,
    },
    instanceLock: { enabled: Boolean(instanceLockPath), held: instanceLockHeld },
    process: { pid: process.pid, uptimeSeconds: Math.floor(process.uptime()), startedAt: new Date(Date.now() - process.uptime() * 1000).toISOString() },
    storage: { dataRoot: dataRootDirectory, data: dataHealth, amu },
    backups: {
      freshnessHours: backupFreshnessHours,
      appDirectory: appBackupDirectory,
      externalEnabled: !serverModeActive && settingEnabled(settings, "external_backup_enabled"),
      externalDirectory: serverModeActive ? "" : externalDirectory,
      externalWritable: !serverModeActive && backupHealth.writable,
      freeBytes: serverModeActive ? null : backupHealth.freeBytes,
      latest: latestBackup,
      latestAgeHours: latestBackupAgeHours,
      latestTimestampValid: latestBackupState.timestampValid,
      latestApp: latestAppBackup,
      latestAppAgeHours: latestAppBackupState.ageHours,
      latestAppTimestampValid: latestAppBackupState.timestampValid,
      latestExternal: serverModeActive ? null : latestExternalBackup,
      latestExternalAgeHours: serverModeActive ? null : latestExternalBackupAgeHours,
      latestExternalTimestampValid: serverModeActive ? false : latestExternalBackupState.timestampValid,
      retentionCount: backupKeep,
      retentionUnit: 'calendar-days',
      background: backgroundBackup,
      lastVerified: postgresqlActive ? latestAppBackup?.verified === true : Boolean(lastBackup?.appBackup?.verified || lastBackup?.externalBackup?.verified),
      offsite,
    },
    monitor,
    hostSecurity,
    recoveryAssurance,
    productionChecks,
    pilotChecks: productionChecks,
    security: {
      lockedAccounts,
      activeSessions: (await sqliteSystemDiagnosticsOperations.activePortalSessionCount()),
      loginRateLimitActive: serverModeActive,
      secureCookies: serverModeActive,
      serviceControlConfigured: serviceControlToken.length >= 32,
    },
    alerts,
    warnings,
  };
}

function publicBackupPoint(backup, ageHours, timestampValid) {
  return {
    available: Boolean(backup),
    createdAt: backup?.modifiedAt || null,
    ageHours: Number.isFinite(ageHours) ? ageHours : null,
    verified: backup?.verified === true,
    committed: backup?.committed === true,
    timestampValid: backup ? timestampValid === true : null,
  };
}

async function serverStatusSummary(diagnostics) {
  if (!diagnostics) diagnostics = (await serverDiagnostics());
  const offsite = diagnostics.backups?.offsite || {};
  const monitor = diagnostics.monitor || {};
  const hostSecurity = diagnostics.hostSecurity || {};
  const recoveryAssurance = diagnostics.recoveryAssurance || {};
  return {
    checkedAt: new Date().toISOString(),
    mode: diagnostics.mode,
    publicUrl: diagnostics.publicUrl || "",
    live: { ok: true },
    ready: { ok: diagnostics.ready === true },
    alerts: (diagnostics.alerts || []).map((alert) => ({
      id: String(alert.id || "SERVER_ATTENTION"),
      severity: ["info", "warning", "critical"].includes(alert.severity) ? alert.severity : "warning",
      category: String(alert.category || "system"),
      title: String(alert.title || "Serverzustand prüfen"),
      message: String(alert.message || "Die technische Administration muss den Serverzustand prüfen."),
      action: "open-server-status",
    })),
    checks: (diagnostics.productionChecks || []).map((check) => ({
      id: String(check.id || "check"),
      label: String(check.label || "Prüfung"),
      ok: check.ok === true,
    })),
    backups: {
      freshnessHours: Number.isFinite(diagnostics.backups?.freshnessHours)
        ? diagnostics.backups.freshnessHours : null,
      internal: publicBackupPoint(
        diagnostics.backups?.latestApp,
        diagnostics.backups?.latestAppAgeHours,
        diagnostics.backups?.latestAppTimestampValid,
      ),
      external: {
        enabled: diagnostics.backups?.externalEnabled === true,
        writable: diagnostics.backups?.externalWritable === true,
        ...publicBackupPoint(
          diagnostics.backups?.latestExternal,
          diagnostics.backups?.latestExternalAgeHours,
          diagnostics.backups?.latestExternalTimestampValid,
        ),
      },
      offsite: {
        applicable: offsite.applicable === true,
        configured: offsite.configured === true,
        provider: {
          selectionRequired: offsite.provider?.selectionRequired === true,
          selectedProviderId: offsite.provider?.selectedProviderId || null,
          boundProviderId: offsite.provider?.boundProviderId || null,
          bindingVerified: offsite.provider?.bindingVerified === true,
          preferredProviderId: offsite.provider?.preferredProviderId || "google_drive",
          available: Array.isArray(offsite.provider?.available)
            ? offsite.provider.available.map((provider) => ({
              id: String(provider.id || ""),
              label: String(provider.label || ""),
              preferred: provider.preferred === true,
            }))
            : [],
        },
        providerPolicy: {
          state: String(offsite.providerPolicy?.state || "blocked"),
          systemCenterOk: offsite.providerPolicy?.systemCenterOk === true,
          reasonCodes: Array.isArray(offsite.providerPolicy?.reasonCodes)
            ? offsite.providerPolicy.reasonCodes.map(String)
            : ["OFFSITE_PROVIDER_NOT_SELECTED"],
          checks: Array.isArray(offsite.providerPolicy?.checks)
            ? offsite.providerPolicy.checks.map((check) => ({
              id: String(check.id || ""),
              state: String(check.state || "unknown"),
              reasonCode: String(check.reasonCode || "OFFSITE_PROVIDER_POLICY_INPUT_INVALID"),
            }))
            : [],
        },
        state: String(offsite.state || "unconfigured"),
        lastSuccessAt: offsite.lastSuccessAt || null,
        lastRepositoryCheckAt: offsite.lastRepositoryCheckAt || null,
        lastFullCheckAt: offsite.lastFullCheckAt || null,
        lastRestoreTestAt: offsite.lastRestoreTestAt || null,
        lastAttemptAt: offsite.lastAttemptAt || null,
        lastFailureAt: offsite.lastFailureAt || null,
        lastErrorCode: offsite.lastErrorCode || null,
        unresolvedFailures: {
          backup: offsite.unresolvedFailures?.backup === true,
          fullCheck: offsite.unresolvedFailures?.fullCheck === true,
          restoreTest: offsite.unresolvedFailures?.restoreTest === true,
        },
        agesHours: {
          backup: Number.isFinite(offsite.agesHours?.backup) ? offsite.agesHours.backup : null,
          repositoryCheck: Number.isFinite(offsite.agesHours?.repositoryCheck) ? offsite.agesHours.repositoryCheck : null,
          fullCheck: Number.isFinite(offsite.agesHours?.fullCheck) ? offsite.agesHours.fullCheck : null,
          restoreTest: Number.isFinite(offsite.agesHours?.restoreTest) ? offsite.agesHours.restoreTest : null,
        },
        retention: {
          daily: Number(offsite.retention?.daily || 14),
          weekly: Number(offsite.retention?.weekly || 8),
          monthly: Number(offsite.retention?.monthly || 12),
        },
      },
    },
    monitor: {
      configured: monitor.configured === true,
      state: String(monitor.state || "unconfigured"),
      statusAvailable: monitor.statusAvailable === true,
      complete: monitor.complete === true,
      generatedAt: monitor.generatedAt || null,
      ageHours: Number.isFinite(monitor.ageHours) ? monitor.ageHours : null,
      consecutiveLiveFailures: Number(monitor.consecutiveLiveFailures || 0),
      lastRestartAt: monitor.lastRestartAt || null,
      failedChecks: Array.isArray(monitor.failedChecks) ? monitor.failedChecks.map(String) : [],
      recovery: {
        attempted: monitor.recovery?.attempted === true,
        successful: monitor.recovery?.successful === true,
        suppressed: monitor.recovery?.suppressed === true,
      },
      lastErrorCode: monitor.lastErrorCode || null,
    },
    hostSecurity: {
      configured: hostSecurity.configured === true,
      statusAvailable: hostSecurity.statusAvailable === true,
      state: String(hostSecurity.state || "unconfigured"),
      checkedAt: hostSecurity.checkedAt || null,
      ageHours: Number.isFinite(hostSecurity.ageHours) ? hostSecurity.ageHours : null,
      pendingConfirmation: hostSecurity.pendingConfirmation === true,
      rebootRequired: hostSecurity.rebootRequired === true,
      failedChecks: Array.isArray(hostSecurity.failedChecks) ? hostSecurity.failedChecks.map(String) : [],
      unknownChecks: Array.isArray(hostSecurity.unknownChecks) ? hostSecurity.unknownChecks.map(String) : [],
      lastErrorCode: hostSecurity.lastErrorCode || null,
    },
    recoveryAssurance: {
      configured: recoveryAssurance.configured === true,
      state: String(recoveryAssurance.state || "unconfigured"),
      statusAvailable: recoveryAssurance.statusAvailable === true,
      integrityVerified: recoveryAssurance.integrityVerified === true,
      severity: ["info", "warning", "critical"].includes(recoveryAssurance.severity)
        ? recoveryAssurance.severity : "info",
      generatedAt: recoveryAssurance.generatedAt || null,
      ageHours: Number.isFinite(recoveryAssurance.ageHours) ? recoveryAssurance.ageHours : null,
      maximumAgeHours: Number.isFinite(recoveryAssurance.maximumAgeHours) ? recoveryAssurance.maximumAgeHours : null,
      stale: recoveryAssurance.stale === true,
      eventCount: Number(recoveryAssurance.eventCount || 0),
      lastSequence: Number(recoveryAssurance.lastSequence || 0),
      lastErrorCode: recoveryAssurance.lastErrorCode || null,
      summary: String(recoveryAssurance.summary || "Recovery Assurance ist nicht eingerichtet."),
      events: Array.isArray(recoveryAssurance.events) ? recoveryAssurance.events : [],
      recentRuns: Array.isArray(recoveryAssurance.recentRuns) ? recoveryAssurance.recentRuns : [],
    },
    recovery: {
      isolatedRestoreTestAt: offsite.lastRestoreTestAt || null,
      isolatedRestoreTestAgeHours: Number.isFinite(offsite.agesHours?.restoreTest) ? offsite.agesHours.restoreTest : null,
      isolatedRestoreTestPending: offsite.applicable === true
        && (offsite.unresolvedFailures?.restoreTest === true || !offsite.lastRestoreTestAt),
      requiresSupervisedMaintenance: true,
    },
  };
}

async function sendReadiness(response) {
  const diagnostics = (await serverDiagnostics());
  response.setHeader("Cache-Control", "no-store");
  response.status(diagnostics.ready ? 200 : 503).json({
    ok: diagnostics.ready,
    hostBootGeneration,
  });
}

function integrationActor(request, permission) {
  return requirePortalAdminOrLocal(request, permission);
}

function parseIntegrationJson(value, fallback = {}) {
  try {
    const parsed = JSON.parse(String(value || "{}"));
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : fallback;
  } catch {
    return fallback;
  }
}

function requireIntegrationSecretVault() {
  if (!integrationSecretVault) {
    throw httpError(503, "Der geschützte Schlüsselspeicher für direkte Verbindungen ist nicht konfiguriert.", "INTEGRATION_SECRET_KEY_UNAVAILABLE");
  }
  return integrationSecretVault;
}

function integrationCredentialContext(connection) {
  return {
    namespace: "integration-connection",
    connectorId: String(connection.id || ""),
    field: "credentials",
    purpose: String(connection.kind || "integration"),
  };
}

function serializeIntegrationConnection(row) {
  const configuration = parseIntegrationJson(row.configuration_json);
  const serialized = toPublicIntegrationConnection({
    id: row.id,
    version: 1,
    kind: row.kind,
    provider: row.provider,
    name: row.name,
    active: Boolean(row.active),
    configuration,
    status: row.active ? (row.last_test_status || "untested") : "disabled",
    lastTestedAt: row.last_test_at || null,
    lastErrorCode: row.last_error_code || "",
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  }, { credentialsConfigured: Boolean(row.protected_credentials) });
  return { ...serialized, revision: Math.max(1, Number(row.revision || 1)) };
}

async function integrationConnectionRows(kind = "") {
  const normalizedKind = ["personnel_sql_source", "payroll_https_target"].includes(kind) ? kind : "";
  return (await integrationRuntimeRepository.listConnections({
    kind: normalizedKind,
  })).map(serializeIntegrationConnection);
}

async function integrationConnectionById(
  id,
  kind = "",
  options = {},
  repository = integrationRuntimeRepository,
) {
  const row = await repository.getConnection({
    id: String(id || ""),
    includeInactive: Boolean(options.includeInactive),
  });
  if (!row || (kind && row.kind !== kind)) {
    throw httpError(404, "Die direkte Verbindung wurde nicht gefunden.", "INTEGRATION_CONNECTION_NOT_FOUND");
  }
  return { row, public: serializeIntegrationConnection(row) };
}

function normalizeIntegrationConnectionRequest(body, existing = null) {
  const previous = existing?.public || null;
  if (previous && body?.kind !== undefined && String(body.kind) !== previous.kind) {
    throw httpError(400, "Die Art einer bestehenden direkten Verbindung kann nicht geändert werden.", "INTEGRATION_CONNECTION_KIND_LOCKED");
  }
  if (previous && body?.provider !== undefined && String(body.provider) !== previous.provider) {
    throw httpError(400, "Der Provider einer bestehenden direkten Verbindung kann nicht geändert werden.", "INTEGRATION_CONNECTION_PROVIDER_LOCKED");
  }
  const merged = {
    ...(previous || {}),
    ...(body || {}),
    configuration: {
      ...(previous?.configuration || {}),
      ...((body?.configuration && typeof body.configuration === "object") ? body.configuration : {}),
    },
  };
  if (body && Object.hasOwn(body, "credentials")) merged.credentials = body.credentials;
  else delete merged.credentials;
  if (previous?.kind === "payroll_https_target"
    && merged.configuration.authenticationType === "none"
    && previous.configuration.authenticationType !== "none"
    && !Object.hasOwn(body || {}, "credentials")) merged.credentials = {};
  if (previous?.kind === "payroll_https_target"
    && merged.configuration.authenticationType !== previous.configuration.authenticationType
    && merged.configuration.authenticationType !== "none"
    && !Object.hasOwn(body || {}, "credentials")) {
    throw httpError(400, "Bei einer geänderten Authentifizierungsart müssen neue Zugangsdaten gesetzt werden.", "INTEGRATION_CONNECTION_CREDENTIALS_REQUIRED");
  }
  try {
    return normalizeIntegrationConnection(merged, {
      existingCredentialsConfigured: Boolean(existing?.row?.protected_credentials),
    });
  } catch (error) {
    throw httpError(400, error.message && !/^INTEGRATION_/.test(error.message)
      ? error.message : "Die Angaben der direkten Verbindung sind ungültig.", error.code || "INTEGRATION_CONNECTION_INVALID");
  }
}

function protectIntegrationCredentials(connectionId, kind, credentials) {
  if (!credentials || !Object.keys(credentials).length) return { protectedCredentials: "", keyId: "" };
  const vault = requireIntegrationSecretVault();
  const protectedCredentials = vault.seal(JSON.stringify(credentials), integrationCredentialContext({ id: connectionId, kind }));
  return { protectedCredentials, keyId: vault.inspect(protectedCredentials).keyId };
}

async function withIntegrationCredentials(connection, consumer) {
  if (typeof consumer !== "function") throw new TypeError("consumer required");
  if (!connection.row.protected_credentials) return consumer({});
  const vault = requireIntegrationSecretVault();
  let result;
  await vault.useSecret(connection.row.protected_credentials, integrationCredentialContext(connection.row), async (buffer) => {
    let credentials;
    try {
      credentials = JSON.parse(buffer.toString("utf8"));
      result = await consumer(credentials);
    } finally {
      if (credentials && typeof credentials === "object") {
        for (const key of Object.keys(credentials)) credentials[key] = "";
      }
    }
  });
  return result;
}

function assertIntegrationConnectionScope(actor, connection, context = {}) {
  assertSessionContextScope(actor, context);
  const scope = connection.public.configuration.scope || {};
  const locationId = String(context.locationId || "");
  const departmentId = String(context.departmentId || "");
  if (scope.locationIds?.length && (!locationId || !scope.locationIds.includes(locationId))) {
    throw httpError(403, "Diese Verbindung ist für den gewählten Standort nicht freigegeben.", "INTEGRATION_CONNECTION_SCOPE_DENIED");
  }
  if (scope.departmentIds?.length && (!departmentId || !scope.departmentIds.includes(departmentId))) {
    throw httpError(403, "Diese Verbindung ist für die gewählte Abteilung nicht freigegeben.", "INTEGRATION_CONNECTION_SCOPE_DENIED");
  }
}

function assertIntegrationPermission(actor, permission) {
  if (isLocalSystemSession(actor)) return;
  if (!actor.permissions?.includes(permission)) {
    throw httpError(403, "Für diese Schnittstellenaktion fehlt die Berechtigung.", "PORTAL_PERMISSION_DENIED");
  }
}

function apiAuthenticationHeaders(connection, credentials) {
  const configuration = connection.public.configuration;
  if (configuration.authenticationType === "none") return {};
  if (configuration.authenticationType === "bearer") return { authorization: `Bearer ${credentials.token}` };
  if (configuration.authenticationType === "api_key") return { [configuration.apiKeyHeader]: credentials.apiKey };
  if (configuration.authenticationType === "basic") {
    return { authorization: `Basic ${Buffer.from(`${credentials.username}:${credentials.password}`, "utf8").toString("base64")}` };
  }
  throw httpError(400, "Die Authentifizierung des API-Ziels ist ungültig.", "INTEGRATION_CONNECTION_AUTHENTICATION_INVALID");
}

function apiDeliveryClient(connection) {
  const configuration = connection.public.configuration;
  return createSafeApiDelivery({
    timeoutMs: configuration.timeoutMs,
    maxRequestBytes: configuration.requestLimitBytes,
    maxResponseBytes: configuration.responseLimitBytes,
    allowedHeaders: [
      "accept", "authorization", "content-type", "idempotency-key", "user-agent", "x-api-key",
      ...(configuration.apiKeyHeader ? [configuration.apiKeyHeader] : []),
    ],
  });
}

const forbiddenSqlPersonnelColumnTokens = [
  "svnr", "svnummer", "sozialversicherung", "iban", "bank", "konto", "adresse", "anschrift", "strasse",
  "telefon", "phone", "passwort", "password", "token", "secret", "aum", "diagnose",
];

function normalizedSqlColumnToken(value) {
  return String(value || "").normalize("NFKD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]/g, "");
}

function assertSqlPersonnelColumns(columns) {
  const blocked = columns.filter((column) => forbiddenSqlPersonnelColumnTokens
    .some((token) => normalizedSqlColumnToken(column.name).includes(token)));
  if (blocked.length) {
    throw httpError(422,
      "Die freigegebene SQL-View enthält sensible oder für den Personalimport nicht erforderliche Spalten. Bitte dafür eine datensparsame View bereitstellen.",
      "SQL_VIEW_SENSITIVE_COLUMNS_FORBIDDEN");
  }
}

function allowedSqlPersonnelColumns(configuration, columns) {
  const available = new Map(columns.map((column) => [String(column.name || "").toLocaleLowerCase("de-AT"), column]));
  const selected = (configuration.allowedColumns || []).map((name) => available.get(String(name).toLocaleLowerCase("de-AT")));
  if (!selected.length || selected.some((column) => !column)) {
    throw httpError(409,
      "Mindestens eine freigegebene SQL-Spalte ist nicht mehr in der View vorhanden. Bitte die Verbindung pr\u00fcfen.",
      "SQL_VIEW_ALLOWED_COLUMNS_CHANGED");
  }
  assertSqlPersonnelColumns(selected);
  return selected;
}

async function sqlPersonnelScopeContext(input = {}, repository = integrationRuntimeRepository) {
  if (!input || typeof input !== "object" || Array.isArray(input)) input = {};
  const costCenterId = String(input.costCenterId || input.defaultCostCenterId || "");
  const derivedLocationId = costCenterId
    ? String((await repository.locationForCostCenter({
      costCenterId,
    }))?.id || "")
    : "";
  return {
    locationId: String(input.locationId || input.defaultLocationId || derivedLocationId),
    departmentId: String(input.departmentId || input.defaultDepartmentId || ""),
  };
}

function assertGlobalSqlPersonnelImportActor(actor) {
  if (!sessionHasGlobalScope(actor)) {
    throw httpError(403,
      "Der direkte SQL-Personalimport ist nur f\u00fcr Zug\u00e4nge mit globalem Unternehmensbereich verf\u00fcgbar.",
      "INTEGRATION_SQL_GLOBAL_SCOPE_REQUIRED");
  }
}

function assertGlobalIntegrationConnectionActor(actor) {
  if (!sessionHasGlobalScope(actor)) {
    throw httpError(403,
      "Direkte Verbindungen können nur von Zugängen mit globalem Unternehmensbereich verwaltet werden.",
      "INTEGRATION_CONNECTION_GLOBAL_SCOPE_REQUIRED");
  }
}

function integrationConnectionConfigurationFingerprint(connection) {
  const value = connection?.public || connection || {};
  return sha256(JSON.stringify({
    id: String(value.id || ""),
    kind: String(value.kind || ""),
    provider: String(value.provider || ""),
    configuration: value.configuration || {},
  }));
}

async function revalidateSqlPersonnelPreviewConnection(
  actor,
  preview,
  repository = integrationRuntimeRepository,
) {
  assertGlobalSqlPersonnelImportActor(actor);
  assertIntegrationPermission(actor, "integrations:connections:read");
  if (!preview.connectionId || !preview.connectionFingerprint) {
    throw httpError(409, "Die SQL-Importvorschau ist veraltet. Bitte die Daten erneut einlesen.", "INTEGRATION_CONNECTION_CHANGED");
  }
  let connection;
  try {
    connection = await integrationConnectionById(
      preview.connectionId,
      "personnel_sql_source",
      {},
      repository,
    );
  } catch (error) {
    if (error.code === "INTEGRATION_CONNECTION_NOT_FOUND") {
      throw httpError(409, "Die SQL-Verbindung wurde deaktiviert oder entfernt. Bitte die Daten erneut einlesen.", "INTEGRATION_CONNECTION_CHANGED");
    }
    throw error;
  }
  if (connection.public.status !== "ready") {
    throw httpError(409, "Die SQL-Verbindung ist nicht mehr einsatzbereit. Bitte die Verbindung erneut pr\u00fcfen und die Daten neu einlesen.", "INTEGRATION_CONNECTION_CHANGED");
  }
  assertIntegrationConnectionScope(
    actor,
    connection,
    await sqlPersonnelScopeContext(preview.connectionScopeContext, repository),
  );
  if (integrationConnectionConfigurationFingerprint(connection) !== preview.connectionFingerprint) {
    throw httpError(409, "Die SQL-Verbindung wurde seit der Vorschau ge\u00e4ndert. Bitte die Daten erneut einlesen.", "INTEGRATION_CONNECTION_CHANGED");
  }
  return connection;
}

function publicPersonnelInspection(parsed, session) {
  return {
    inspectionId: session.id,
    expiresAt: session.expiresAt,
    format: parsed.format,
    sourceTransport: parsed.sourceTransport || "file",
    sourceLabel: parsed.sourceLabel || parsed.format.toUpperCase(),
    sourceContractId: parsed.sourceContractId || null,
    encoding: parsed.encoding,
    delimiter: parsed.delimiter === "\t" ? "tab" : parsed.delimiter,
    byteSize: parsed.byteSize,
    sheets: parsed.summaries.map((summary) => {
      const sheet = parsed.sheets.find((item) => item.name === summary.name);
      const header = sheet?.rows?.[summary.suggestedHeaderRow - 1] || [];
      return {
        ...summary,
        headerFingerprint: headerFingerprint(header),
        suggestedMapping: suggestPersonnelMapping(header),
        headerCandidates: (sheet?.rows || []).slice(0, 20).map((candidate, index) => ({
          rowNumber: index + 1,
          headerFingerprint: headerFingerprint(candidate),
          suggestedMapping: suggestPersonnelMapping(candidate),
        })),
      };
    }),
  };
}

function sqlSourceConfiguration(connection) {
  const config = connection.public.configuration;
  return {
    providerId: connection.public.provider,
    host: config.host,
    port: config.port,
    database: config.database,
    instanceName: config.instanceName,
    schemaName: config.schemaName,
    objectName: config.objectName,
    tlsMode: config.tlsMode,
    timeoutMs: config.timeoutMs,
  };
}

function sqlInspectionFromResult(connection, result, scopeContext = {}) {
  const header = result.columns.map((column) => ({ text: column.name, formula: false, error: false }));
  const rows = [header, ...result.rows.map((row) => row.map((text) => ({ text: String(text ?? ""), formula: false, error: false })))];
  const sheetName = `${result.view.schema}.${result.view.name}`;
  const serializedRows = JSON.stringify(result.rows);
  const contentSha256 = crypto.createHash("sha256")
    .update(JSON.stringify({ connectionId: connection.public.id, sheetName }), "utf8")
    .update("\n", "utf8")
    .update(serializedRows, "utf8")
    .digest("hex");
  return {
    format: "csv",
    sourceTransport: "sql_view",
    sourceLabel: "SQL-View",
    sourceContractId: connection.public.configuration.contractId || CONTRACT_IDS.personnelSqlView,
    connectionId: connection.public.id,
    connectionFingerprint: integrationConnectionConfigurationFingerprint(connection),
    connectionScopeContext: {
      locationId: String(scopeContext.locationId || scopeContext.defaultLocationId || ""),
      departmentId: String(scopeContext.departmentId || scopeContext.defaultDepartmentId || ""),
    },
    contentSha256,
    byteSize: Number(result.byteSize || Buffer.byteLength(serializedRows, "utf8")),
    encoding: "utf8",
    delimiter: ",",
    sheets: [{ name: sheetName, rows }],
    summaries: [{
      name: sheetName,
      rowCount: result.rowCount,
      columnCount: result.columns.length,
      suggestedHeaderRow: 1,
      topRows: rows.slice(0, 20).map((row) => row.map((cell) => cell.text)),
      headers: result.columns.map((column, columnIndex) => ({ columnIndex, label: column.name })),
    }],
  };
}

function serializeIntegrationProfile(row) {
  return {
    id: row.id,
    direction: row.direction,
    kind: row.kind,
    name: row.name,
    format: row.format,
    configuration: parseIntegrationJson(row.configuration_json),
    active: Boolean(row.active),
    createdBy: row.created_by || "",
    updatedBy: row.updated_by || "",
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

async function integrationProfiles(filters = {}) {
  const direction = ["import", "export"].includes(filters.direction) ? filters.direction : "";
  const kind = ["personnel", "payroll"].includes(filters.kind) ? filters.kind : "";
  return (await integrationRuntimeRepository.listProfiles({
    direction,
    kind,
  })).map(serializeIntegrationProfile);
}

function normalizeIntegrationProfile(body = {}, existing = null) {
  if (existing && body.direction !== undefined && String(body.direction) !== existing.direction) {
    throw httpError(400, "Die Richtung eines bestehenden Schnittstellenprofils kann nicht geändert werden.", "INTEGRATION_PROFILE_KIND_LOCKED");
  }
  if (existing && body.kind !== undefined && String(body.kind) !== existing.kind) {
    throw httpError(400, "Die Art eines bestehenden Schnittstellenprofils kann nicht geändert werden.", "INTEGRATION_PROFILE_KIND_LOCKED");
  }
  const direction = String(body.direction || existing?.direction || "");
  const kind = String(body.kind || existing?.kind || "");
  if (!((direction === "import" && kind === "personnel") || (direction === "export" && kind === "payroll"))) {
    throw httpError(400, "Dieses Schnittstellenprofil wird nicht unterst\u00fctzt.", "INTEGRATION_PROFILE_KIND_INVALID");
  }
  const name = String(body.name || existing?.name || "").trim().replace(/\s+/g, " ");
  if (name.length < 2 || name.length > 80) throw httpError(400, "Der Profilname muss 2 bis 80 Zeichen lang sein.", "INTEGRATION_PROFILE_NAME_INVALID");
  let configuration;
  try {
    configuration = direction === "import"
      ? normalizeProfileConfiguration(body.configuration || existing?.configuration || {})
      : normalizePayrollConfiguration(body.configuration || existing?.configuration || {});
  } catch (error) {
    throw httpError(400, "Die Profilkonfiguration ist ung\u00fcltig.", error.message || "INTEGRATION_PROFILE_INVALID");
  }
  const format = configuration.format;
  return { direction, kind, name, format, configuration, active: body.active !== false };
}

function serializeIntegrationRun(row) {
  return {
    id: row.id,
    profileId: row.profile_id || null,
    direction: row.direction,
    kind: row.kind,
    format: row.format,
    status: row.status,
    totalCount: Number(row.total_count || 0),
    createdCount: Number(row.created_count || 0),
    updatedCount: Number(row.updated_count || 0),
    skippedCount: Number(row.skipped_count || 0),
    errorCount: Number(row.error_count || 0),
    actorEmployeeNumber: row.actor_employee_number || "",
    options: parseIntegrationJson(row.options_json),
    result: parseIntegrationJson(row.result_json),
    errorCode: row.error_code || "",
    startedAt: row.started_at,
    completedAt: row.completed_at || null,
  };
}

async function insertIntegrationRun(run, repository = integrationRuntimeRepository) {
  const id = run.id || crypto.randomUUID();
  await repository.insertRun({
    id,
    profileId: run.profileId || null,
    direction: run.direction,
    kind: run.kind,
    format: run.format,
    contentSha256: run.contentSha256 || "",
    status: run.status || "completed",
    totalCount: Number(run.totalCount || 0),
    createdCount: Number(run.createdCount || 0),
    updatedCount: Number(run.updatedCount || 0),
    skippedCount: Number(run.skippedCount || 0),
    errorCount: Number(run.errorCount || 0),
    actor: run.actor || "",
    optionsJson: JSON.stringify(run.options || {}),
    resultJson: JSON.stringify(run.result || {}),
    errorCode: run.errorCode || "",
  });
  return id;
}

async function integrationProfileById(id, direction = "", kind = "", options = {}) {
  const row = await integrationRuntimeRepository.getProfile({
    id: String(id || ""),
    includeInactive: Boolean(options.includeInactive),
  });
  if (!row || (direction && row.direction !== direction) || (kind && row.kind !== kind)) {
    throw httpError(404, "Das Schnittstellenprofil wurde nicht gefunden.", "INTEGRATION_PROFILE_NOT_FOUND");
  }
  return serializeIntegrationProfile(row);
}

async function personnelImportReferenceData(actor = null) {
  const centralPersonnelAccess = sessionCanManageCentralPersonnel(actor);
  const [locations, costCenterTypeRows, positions, costCenters] = await Promise.all([
    getLocationsForSession(actor, true),
    getCostCenterTypes(true),
    getPositions(),
    getCostCenters(true),
  ]);
  const visibleCostCenterIds = new Set(locations
    .map((location) => String(location.cost_center_id || ""))
    .filter(Boolean));
  const costCenterTypes = new Map(costCenterTypeRows
    .map((type) => [String(type.id), type]));
  return {
    positions: positions.map((position) => ({
      id: position.id,
      name: position.name,
      active: true,
      costCenterTypeIds: position.costCenterTypeIds,
    })),
    costCenters: costCenters
      .filter((costCenter) => centralPersonnelAccess || visibleCostCenterIds.has(String(costCenter.id)))
      .map((costCenter) => ({
      id: costCenter.id,
      code: costCenter.code,
      name: costCenter.name,
      type: costCenter.type,
      typeId: costCenter.typeId,
      typeName: costCenter.typeName,
      isBranch: costCenter.isBranch,
      active: costCenter.active,
      locationId: costCenter.locationId,
      positionIds: costCenterTypes.get(String(costCenter.typeId))?.positionIds || [],
    })),
    locations: locations.map((location) => ({
      id: location.id,
      name: location.name,
      active: location.active,
      costCenterId: String(location.cost_center_id || ""),
      departments: location.departments.map((department) => ({ id: department.id, name: department.name, active: department.active })),
    })),
  };
}

async function employeeImportRow(personnelNumber, repository = integrationRuntimeRepository) {
  return repository.getEmployeeImportRow({ personnelNumber });
}

async function employeeImportRowsCaseInsensitive(personnelNumber, repository = integrationRuntimeRepository) {
  return repository.listEmployeeImportRowsCaseInsensitive({ personnelNumber });
}

function employeeImportFingerprint(row) {
  if (!row) return "";
  return sha256(JSON.stringify([
    row.personnel_number, row.full_name, row.nickname, row.color, Number(row.contracted_hours),
    normalizeTargetWorkdays(row.target_workdays_per_week), row.preferred_day_off || "",
    row.fixed_workdays || "", row.position_id || "", row.time_confirmation_level || "C",
    Number(row.sickness_without_aum_enabled || 0), row.home_location_id || "",
    Number(row.preferred_department_id || 0), row.cost_center_id || "", Number(row.active || 0),
  ]));
}

function uniqueReferenceByName(rows, name, typeLabel) {
  const normalized = String(name || "").trim().toLocaleLowerCase("de-AT");
  const matches = rows.filter((row) => String(row.name || "").trim().toLocaleLowerCase("de-AT") === normalized);
  if (matches.length === 1) return matches[0];
  if (!matches.length) throw httpError(400, `${typeLabel} wurde nicht gefunden.`, "IMPORT_REFERENCE_NOT_FOUND");
  throw httpError(400, `${typeLabel} ist nicht eindeutig. Bitte die ID importieren.`, "IMPORT_REFERENCE_AMBIGUOUS");
}

function importFieldMapped(mapping, ...fields) {
  return fields.some((field) => Object.hasOwn(mapping, field));
}

async function resolvePersonnelImportCandidate(incoming, mapping, existing, actor) {
  const creating = !existing;
  const centralPersonnelAccess = sessionCanManageCentralPersonnel(actor);
  if (existing) {
    assertSessionContextScope(actor, {
      locationId: existing.home_location_id,
      departmentId: existing.preferred_department_id,
    });
  }
  const base = existing ? {
    personnelNumber: existing.personnel_number,
    fullName: existing.full_name,
    nickname: existing.nickname,
    color: existing.color,
    contractedHours: Number(existing.contracted_hours),
    targetWorkdaysPerWeek: normalizeTargetWorkdays(existing.target_workdays_per_week),
    preferredDayOff: existing.preferred_day_off || "",
    fixedWorkdays: String(existing.fixed_workdays || "").split(",").filter(Boolean),
    positionId: existing.position_id,
    timeConfirmationLevel: existing.time_confirmation_level || "C",
    sicknessWithoutAumEnabled: Boolean(existing.sickness_without_aum_enabled),
    homeLocationId: existing.home_location_id,
    preferredDepartmentId: existing.preferred_department_id || "",
    costCenterId: existing.cost_center_id,
    active: Boolean(existing.active),
  } : {
    personnelNumber: incoming.personnelNumber,
    fullName: incoming.fullName,
    nickname: incoming.nickname,
    color: incoming.color,
    contractedHours: incoming.contractedHours,
    targetWorkdaysPerWeek: 5,
    preferredDayOff: incoming.preferredDayOff,
    fixedWorkdays: incoming.fixedWorkdays,
    positionId: incoming.positionId,
    timeConfirmationLevel: "C",
    sicknessWithoutAumEnabled: false,
    homeLocationId: incoming.homeLocationId,
    preferredDepartmentId: incoming.preferredDepartmentId,
    costCenterId: incoming.costCenterId,
    active: incoming.active,
  };
  const use = (field) => creating || importFieldMapped(mapping, field);
  if (use("fullName")) base.fullName = incoming.fullName;
  if (use("nickname")) base.nickname = incoming.nickname;
  if (use("color")) base.color = incoming.color;
  if (use("contractedHours")) base.contractedHours = incoming.contractedHours;
  if (use("preferredDayOff")) base.preferredDayOff = incoming.preferredDayOff;
  if (use("fixedWorkdays")) base.fixedWorkdays = incoming.fixedWorkdays;
  if (use("active")) base.active = incoming.active;

  const references = await personnelImportReferenceData(actor);
  const assignmentMapped = importFieldMapped(mapping, "costCenterId", "homeLocationId", "homeLocationName");
  const legacyLocationUsed = creating || importFieldMapped(mapping, "homeLocationId", "homeLocationName");
  let legacyLocation = null;
  if (creating || assignmentMapped) {
    if (importFieldMapped(mapping, "costCenterId") && !centralPersonnelAccess) {
      throw httpError(403, "Kostenstellen können nur in der zentralen Personalverwaltung importiert werden.", "PERSONNEL_CENTRAL_WRITE_REQUIRED");
    }
    const hasLegacyLocation = legacyLocationUsed && Boolean(incoming.homeLocationId || incoming.homeLocationName);
    legacyLocation = hasLegacyLocation
      ? (incoming.homeLocationId && references.locations.find((item) => String(item.id) === String(incoming.homeLocationId)))
        || (incoming.homeLocationName
          ? uniqueReferenceByName(references.locations, incoming.homeLocationName, "Der Standort")
          : null)
      : null;
    if (hasLegacyLocation && !legacyLocation) {
      throw httpError(400, "Die bisherige Standortzuordnung konnte keiner Kostenstelle zugeordnet werden.", "IMPORT_LOCATION_REQUIRED");
    }
    const submittedCostCenterId = String(incoming.costCenterId || legacyLocation?.costCenterId || "").trim();
    if (!submittedCostCenterId) {
      throw httpError(400, "Bitte eine gültige Standardkostenstelle auswählen.", "IMPORT_COST_CENTER_REQUIRED");
    }
    const costCenter = references.costCenters.find((item) => String(item.id) === submittedCostCenterId);
    if (!costCenter) {
      throw httpError(400, "Bitte eine gültige Kostenstellen-ID zuordnen.", "IMPORT_COST_CENTER_INVALID");
    }
    if (legacyLocation?.costCenterId
      && String(legacyLocation.costCenterId) !== String(costCenter.id)) {
      throw httpError(
        409,
        "Der importierte Standort widerspricht der Kostenstelle. Der Standort wird ausschließlich aus der Kostenstelle abgeleitet.",
        "EMPLOYEE_HOME_LOCATION_DERIVED",
      );
    }
    base.costCenterId = costCenter.id;
  }
  const assignment = await employeeAssignmentForCostCenter(base.costCenterId, {
    allowInactive: Boolean(existing && String(existing.cost_center_id) === String(base.costCenterId)),
    allowInactiveLocationId: existing?.home_location_id || "",
  });
  if (legacyLocation && String(assignment.homeLocationId || "") !== String(legacyLocation.id)) {
    throw httpError(
      409,
      "Der importierte Standort widerspricht der Kostenstelle. Der Standort wird ausschließlich aus der Kostenstelle abgeleitet.",
      "EMPLOYEE_HOME_LOCATION_DERIVED",
    );
  }
  base.homeLocationId = assignment.homeLocationId;

  if (creating || importFieldMapped(mapping, "positionId", "positionName")) {
    const position = incoming.positionId && references.positions.find((item) => item.id === incoming.positionId)
      || (incoming.positionName ? uniqueReferenceByName(references.positions, incoming.positionName, "Die Position") : null);
    if (!position) throw httpError(400, "Bitte eine g\u00fcltige Position zuordnen.", "IMPORT_POSITION_REQUIRED");
    base.positionId = position.id;
  }
  if (creating || importFieldMapped(mapping, "preferredDepartmentId", "preferredDepartmentName")) {
    const location = references.locations.find((item) => String(item.id) === String(base.homeLocationId || ""));
    if (!incoming.preferredDepartmentId && !incoming.preferredDepartmentName) base.preferredDepartmentId = "";
    else {
      const departmentId = Number(incoming.preferredDepartmentId || 0);
      const department = departmentId && location?.departments.find((item) => Number(item.id) === departmentId)
        || (incoming.preferredDepartmentName ? uniqueReferenceByName(location?.departments || [], incoming.preferredDepartmentName, "Die Abteilung") : null);
      if (!department) throw httpError(400, "Bitte eine gültige Abteilung zuordnen.", "IMPORT_DEPARTMENT_INVALID");
      base.preferredDepartmentId = department.id;
    }
  }
  const candidate = await validateEmployee(base, creating, {
    defaultTimeConfirmationLevel: existing?.time_confirmation_level || "C",
    defaultCostCenterId: existing?.cost_center_id || base.costCenterId,
    allowInactiveCostCenterId: existing?.cost_center_id || "",
    allowInactiveLocationId: existing?.home_location_id || "",
    allowInactiveDepartmentId: existing?.preferred_department_id || 0,
  });
  if (existing && existing.active && !candidate.active) {
    await assertEmployeeDestructiveMutationAllowed(actor, existing.personnel_number);
  }
  if (existing) {
    const portalTarget = await organizationPersonnelRepository
      .getPortalMutationTarget(existing.personnel_number);
    assertPersonnelLearningOrganizationAssignmentMutationAllowed({
      actor,
      beforeEmployee: existing,
      afterEmployee: candidate,
      beforeRole: portalTarget?.role || "employee",
      afterRole: portalTarget?.role || "employee",
    });
  }
  assertSessionContextScope(actor, { locationId: candidate.homeLocationId, departmentId: candidate.preferredDepartmentId });
  return candidate;
}

async function personnelImportPreview(actor, inspection, body = {}) {
  const sheetName = String(body.sheetName || inspection.sheets[0]?.name || "");
  const sheet = inspection.sheets.find((item) => item.name === sheetName);
  if (!sheet) throw httpError(400, "Das ausgew\u00e4hlte Tabellenblatt wurde nicht gefunden.", "IMPORT_SHEET_NOT_FOUND");
  const headerRow = Number(body.headerRow || 1);
  if (!Number.isInteger(headerRow) || headerRow < 1 || headerRow > 20 || headerRow > sheet.rows.length) {
    throw httpError(400, "Die Kopfzeile ist ung\u00fcltig.", "IMPORT_HEADER_ROW_INVALID");
  }
  const headerCells = sheet.rows[headerRow - 1] || [];
  let mapping;
  try { mapping = normalizePersonnelImportMapping(body.mapping || {}, headerCells.length); }
  catch (error) {
    const message = error.message === "IMPORT_MAPPING_REQUIRED_FIELDS"
      ? "Personalnummer und vollst\u00e4ndiger Name m\u00fcssen zugeordnet sein."
      : "Die Feldzuordnung ist ung\u00fcltig.";
    throw httpError(400, message, error.message || "IMPORT_MAPPING_INVALID");
  }
  const fingerprint = headerFingerprint(headerCells);
  if (body.headerFingerprint && body.headerFingerprint !== fingerprint) {
    throw httpError(409, "Die Spalten stimmen nicht mehr mit dem ausgew\u00e4hlten Profil \u00fcberein.", "IMPORT_HEADER_CHANGED");
  }
  const duplicateStrategy = body.duplicateStrategy === "update" ? "update" : "skip";
  const profile = body.profileId ? await integrationProfileById(body.profileId, "import", "personnel") : null;
  assertPersonnelImportProfileSource(profile, inspection);
  const defaults = body.defaults && typeof body.defaults === "object" ? body.defaults : (profile?.configuration?.defaults || {});
  const rows = [];
  const seen = new Map();
  const sourceRows = sheet.rows.slice(headerRow);
  for (const [offset, sourceRow] of sourceRows.entries()) {
    const rowNumber = headerRow + offset + 1;
    if (!sourceRow.some((cell) => cell.text || cell.formula || cell.error)) continue;
    const incoming = mappedPersonnelRow(sourceRow, mapping, defaults);
    const errors = [];
    const warnings = [];
    for (const [field, meta] of Object.entries(incoming.sourceMeta || {})) {
      if (meta.formula) errors.push({ code: "FORMULA_CELL", field, message: "Formelzellen werden im Personalimport nicht \u00fcbernommen." });
      if (meta.error) errors.push({ code: "ERROR_CELL", field, message: "Die Quelldatei enth\u00e4lt in diesem Feld einen Excel-Fehler." });
    }
    if (!incoming.personnelNumber) errors.push({ code: "PERSONNEL_NUMBER_REQUIRED", field: "personnelNumber", message: "Personalnummer fehlt." });
    if (!incoming.fullName) errors.push({ code: "FULL_NAME_REQUIRED", field: "fullName", message: "Name fehlt." });
    if (incoming.derivedNickname) warnings.push({ code: "NICKNAME_DERIVED", field: "nickname", message: "Der Anzeigename wird aus dem ersten Namensteil gebildet." });
    const key = incoming.personnelNumber.toLocaleLowerCase("de-AT");
    if (key && seen.has(key)) {
      errors.push({ code: "DUPLICATE_IN_FILE", field: "personnelNumber", message: "Diese Personalnummer kommt in der Datei mehrfach vor." });
      seen.get(key).errors.push({ code: "DUPLICATE_IN_FILE", field: "personnelNumber", message: "Diese Personalnummer kommt in der Datei mehrfach vor." });
    } else if (key) seen.set(key, { errors });
    const existingMatches = incoming.personnelNumber
      ? await employeeImportRowsCaseInsensitive(incoming.personnelNumber)
      : [];
    if (existingMatches.length > 1) {
      errors.push({ code: "PERSONNEL_NUMBER_AMBIGUOUS", field: "personnelNumber", message: "Diese Personalnummer ist im Bestand nicht eindeutig. Bitte die Stammdaten zuerst bereinigen." });
    }
    const existing = existingMatches.length === 1 ? existingMatches[0] : null;
    if (existing && existing.personnel_number !== incoming.personnelNumber) {
      warnings.push({ code: "PERSONNEL_NUMBER_CASE_MATCH", field: "personnelNumber", message: `Die Personalnummer entspricht dem bestehenden Eintrag ${existing.personnel_number}; Groß-/Kleinschreibung wird nicht als neue Person behandelt.` });
    }
    let candidate = null;
    let action = existing ? (duplicateStrategy === "update" ? "update" : "skip") : "create";
    if (existing && duplicateStrategy === "skip") warnings.push({ code: "EXISTING_SKIPPED", message: "Die vorhandene Personalnummer wird nicht ver\u00e4ndert." });
    if (!errors.length && action !== "skip") {
      try {
        candidate = await resolvePersonnelImportCandidate(incoming, mapping, existing, actor);
        if (existing && employeeImportFingerprint(existing) === employeeImportFingerprint({
          personnel_number: candidate.personnelNumber,
          full_name: candidate.fullName,
          nickname: candidate.nickname,
          color: candidate.color,
          contracted_hours: candidate.contractedHours,
          target_workdays_per_week: candidate.targetWorkdaysPerWeek,
          preferred_day_off: candidate.preferredDayOff,
          fixed_workdays: candidate.fixedWorkdays,
          position_id: candidate.positionId,
          time_confirmation_level: candidate.timeConfirmationLevel,
          sickness_without_aum_enabled: candidate.sicknessWithoutAumEnabled,
          home_location_id: candidate.homeLocationId,
          preferred_department_id: candidate.preferredDepartmentId,
          cost_center_id: candidate.costCenterId,
          active: candidate.active,
        })) {
          action = "skip";
          warnings.push({ code: "UNCHANGED", message: "Es sind keine \u00c4nderungen erforderlich." });
        }
      } catch (error) {
        errors.push({ code: error.code || "ROW_INVALID", message: error.message || "Die Zeile ist ung\u00fcltig." });
      }
    }
    if (errors.length) action = "error";
    rows.push({
      rowNumber,
      action,
      candidate,
      existingFingerprint: employeeImportFingerprint(existing),
      errors,
      warnings,
      display: {
        personnelNumber: incoming.personnelNumber,
        fullName: incoming.fullName,
        nickname: incoming.nickname,
        contractedHours: incoming.contractedHours,
        location: candidate?.homeLocationId || incoming.homeLocationId || incoming.homeLocationName,
        department: candidate?.preferredDepartmentId || incoming.preferredDepartmentId || incoming.preferredDepartmentName,
        position: candidate?.positionId || incoming.positionId || incoming.positionName,
        active: candidate ? Boolean(candidate.active) : incoming.active,
      },
    });
  }
  if (!rows.length) {
    throw httpError(400, "Unterhalb der Kopfzeile wurden keine Importdaten gefunden.", "IMPORT_DATA_ROWS_REQUIRED");
  }
  for (const row of rows) if (row.errors.length) row.action = "error";
  const summary = {
    total: rows.length,
    create: rows.filter((row) => row.action === "create").length,
    update: rows.filter((row) => row.action === "update").length,
    skip: rows.filter((row) => row.action === "skip").length,
    errors: rows.filter((row) => row.action === "error").length,
    warnings: rows.reduce((sum, row) => sum + row.warnings.length, 0),
  };
  return { sheetName, headerRow, mapping, headerFingerprint: fingerprint, duplicateStrategy, profileId: profile?.id || null, rows, summary };
}

function assertPersonnelImportProfileSource(profile, inspection) {
  if (!profile) return;
  const actualSourceType = inspection.sourceTransport === "sql_view" ? "sql" : "file";
  if (profile.configuration.sourceType !== actualSourceType) {
    throw httpError(409, "Das Importprofil ist an eine andere Quellenart gebunden.", "INTEGRATION_PROFILE_SOURCE_MISMATCH");
  }
  if (actualSourceType === "sql" && profile.configuration.connectionId !== inspection.connectionId) {
    throw httpError(409, "Das Importprofil ist an eine andere SQL-Personalquelle gebunden.", "INTEGRATION_PROFILE_CONNECTION_MISMATCH");
  }
}

function publicPersonnelPreview(preview, previewSession) {
  const errorRows = preview.rows.filter((row) => row.action === "error");
  const regularRows = preview.rows.filter((row) => row.action !== "error");
  const visibleRows = preview.rows.length <= 200
    ? preview.rows
    : [...errorRows.slice(0, 200), ...regularRows.slice(0, Math.max(0, 200 - errorRows.length))];
  return {
    previewId: previewSession.id,
    expiresAt: previewSession.expiresAt,
    summary: preview.summary,
    rows: visibleRows.map(({ candidate: _candidate, existingFingerprint: _fingerprint, ...row }) => row),
    truncated: preview.rows.length > 200,
    hiddenErrorCount: Math.max(0, errorRows.length - visibleRows.filter((row) => row.action === "error").length),
  };
}

async function applyPersonnelImport(actor, preview) {
  if (preview.summary.errors) throw httpError(422, "Der Import enth\u00e4lt noch fehlerhafte Zeilen.", "IMPORT_HAS_ERRORS");
  const preparedRows = [];
  for (const row of preview.rows) {
    if (!["create", "update"].includes(row.action)) continue;
    const candidate = row.candidate;
    const currentMatches = await employeeImportRowsCaseInsensitive(candidate.personnelNumber);
    const current = currentMatches.length === 1 ? currentMatches[0] : null;
    if (row.action === "create" && currentMatches.length) {
      throw httpError(409, "Die Importvorschau ist veraltet. Eine Personalnummer wurde inzwischen angelegt.", "IMPORT_PREVIEW_STALE");
    }
    if (row.action === "update" && currentMatches.length !== 1) {
      throw httpError(409, "Die Importvorschau ist veraltet. Die Personalnummer ist nicht mehr eindeutig.", "IMPORT_PREVIEW_STALE");
    }
    if (row.action === "update" && employeeImportFingerprint(current) !== row.existingFingerprint) {
      throw httpError(409, "Die Importvorschau ist veraltet. Stammdaten wurden inzwischen ge\u00e4ndert.", "IMPORT_PREVIEW_STALE");
    }
    if (row.action === "update") {
      assertSessionContextScope(actor, {
        locationId: current.home_location_id,
        departmentId: current.preferred_department_id,
      });
    }
    const validated = await validateEmployee(candidate, row.action === "create", {
      defaultTimeConfirmationLevel: candidate.timeConfirmationLevel || "C",
      defaultCostCenterId: current?.cost_center_id || candidate.costCenterId,
      allowInactiveCostCenterId: current?.cost_center_id || "",
      allowInactiveLocationId: current?.home_location_id || "",
      allowInactiveDepartmentId: current?.preferred_department_id || 0,
    });
    assertSessionContextScope(actor, {
      locationId: validated.homeLocationId,
      departmentId: validated.preferredDepartmentId,
    });
    if (row.action === "update" && current.active && !validated.active) {
      await assertEmployeeDestructiveMutationAllowed(actor, current.personnel_number);
    }
    const portalTarget = current
      ? await organizationPersonnelRepository.getPortalMutationTarget(validated.personnelNumber)
      : null;
    if (current) {
      assertPersonnelLearningOrganizationAssignmentMutationAllowed({
        actor,
        beforeEmployee: current,
        afterEmployee: validated,
        beforeRole: portalTarget?.role || "employee",
        afterRole: portalTarget?.role || "employee",
      });
    }
    preparedRows.push({
      action: row.action,
      expectedFingerprint: row.existingFingerprint,
      validated,
      deactivate: Boolean(row.action === "update" && current.active && !validated.active),
    });
  }

  const runId = crypto.randomUUID();
  try {
    await runPersonnelLifecycleSerializableMutation(() => persistenceProvider.transaction(async (executor) => {
      const repositories = createApplicationRepositories(executor);
      const repository = repositories.integrationRuntime;
      const organization = repositories.organizationPersonnel;
      const liveLearningActor = await livePersonnelLearningRoleAdministrationActor(
        actor,
        organization,
      );
      assertLivePortalRoutePermission(liveLearningActor, "employees:import");
      if (preview.sourceTransport === "sql_view") {
        await revalidateSqlPersonnelPreviewConnection(
          liveLearningActor,
          preview,
          repository,
        );
      }
      const learningOrganizationScopeDeltas = [];
      for (const row of preparedRows) {
        const preparedCandidate = row.validated;
        const currentMatches = await employeeImportRowsCaseInsensitive(preparedCandidate.personnelNumber, repository);
        const current = currentMatches.length === 1 ? currentMatches[0] : null;
        if (row.action === "create" && currentMatches.length) throw httpError(409, "Die Importvorschau ist veraltet. Eine Personalnummer wurde inzwischen angelegt.", "IMPORT_PREVIEW_STALE");
        if (row.action === "update" && currentMatches.length !== 1) throw httpError(409, "Die Importvorschau ist veraltet. Die Personalnummer ist nicht mehr eindeutig.", "IMPORT_PREVIEW_STALE");
        if (row.action === "update" && employeeImportFingerprint(current) !== row.expectedFingerprint) {
          throw httpError(409, "Die Importvorschau ist veraltet. Stammdaten wurden inzwischen ge\u00e4ndert.", "IMPORT_PREVIEW_STALE");
        }
        if (current) {
          assertSessionContextScope(liveLearningActor, {
            locationId: current.home_location_id,
            departmentId: current.preferred_department_id,
          });
        }
        const candidate = await validateEmployee(preparedCandidate, row.action === "create", {
          defaultTimeConfirmationLevel: current?.time_confirmation_level || "C",
          defaultCostCenterId: current?.cost_center_id || preparedCandidate.costCenterId,
          allowInactiveCostCenterId: current?.cost_center_id || "",
          allowInactiveLocationId: current?.home_location_id || "",
          allowInactiveDepartmentId: current?.preferred_department_id || 0,
          repository: organization,
        });
        const centralCostCenterDelta = importFieldMapped(preview.mapping, "costCenterId")
          && (!current
            || String(current.cost_center_id || "") !== String(candidate.costCenterId || ""));
        if (centralCostCenterDelta && !sessionCanManageCentralPersonnel(liveLearningActor)) {
          throw httpError(
            403,
            "Kostenstellen können nur in der zentralen Personalverwaltung importiert werden.",
            "PERSONNEL_CENTRAL_WRITE_REQUIRED",
          );
        }
        const livePortalTarget = current
          ? await organization.getPortalMutationTarget(candidate.personnelNumber)
          : null;
        if (current) {
          assertPersonnelLearningOrganizationAssignmentMutationAllowed({
            actor: liveLearningActor,
            beforeEmployee: current,
            afterEmployee: candidate,
            beforeRole: livePortalTarget?.role || "employee",
            afterRole: livePortalTarget?.role || "employee",
          });
        }
        const observeLearningOrganizationScope = Boolean(
          roleHasPersonnelLearningDefaults(livePortalTarget?.role),
        );
        const learningOrganizationScopeBefore = observeLearningOrganizationScope
          ? await personnelLearningEmployeeOrganizationScopeSnapshot(
            organization,
            candidate.personnelNumber,
          )
          : null;
        assertSessionContextScope(liveLearningActor, {
          locationId: candidate.homeLocationId,
          departmentId: candidate.preferredDepartmentId,
        });
        const deactivate = Boolean(row.action === "update" && current.active && !candidate.active);
        const mutation = {
          personnelNumber: candidate.personnelNumber,
          fullName: candidate.fullName,
          nickname: candidate.nickname,
          color: candidate.color,
          contractedHours: candidate.contractedHours,
          targetWorkdaysPerWeek: candidate.targetWorkdaysPerWeek,
          preferredDayOff: candidate.preferredDayOff,
          fixedWorkdays: candidate.fixedWorkdays,
          positionId: candidate.positionId,
          timeConfirmationLevel: candidate.timeConfirmationLevel,
          sicknessWithoutAumEnabled: candidate.sicknessWithoutAumEnabled ? 1 : 0,
          homeLocationId: candidate.homeLocationId,
          preferredDepartmentId: candidate.preferredDepartmentId || "",
          costCenterId: candidate.costCenterId,
          active: candidate.active ? 1 : 0,
        };
        if (row.action === "create") {
          await repository.insertEmployee(mutation);
        } else {
          if (deactivate) {
            await assertEmployeeDestructiveMutationAllowed(
              liveLearningActor,
              candidate.personnelNumber,
              organization,
            );
          }
          await repository.updateEmployee(mutation);
          if (deactivate) {
            await repository.deactivateImportedPortalUser({ personnelNumber: candidate.personnelNumber });
            await repository.revokeImportedPortalSessions({ personnelNumber: candidate.personnelNumber });
            await repository.revokeImportedMobileSessions({
              personnelNumber: candidate.personnelNumber,
              reason: "employee_deactivated",
            });
          }
        }
        if (observeLearningOrganizationScope) {
          const learningOrganizationScopeAfter = await personnelLearningEmployeeOrganizationScopeSnapshot(
            organization,
            candidate.personnelNumber,
          );
          const learningOrganizationScopeDelta = personnelLearningEmployeeOrganizationScopeDelta(
            candidate.personnelNumber,
            learningOrganizationScopeBefore,
            learningOrganizationScopeAfter,
          );
          if (learningOrganizationScopeDelta) {
            learningOrganizationScopeDeltas.push(learningOrganizationScopeDelta);
          }
        }
      }
      learningOrganizationScopeDeltas.sort(
        (left, right) => left.employeeNumber.localeCompare(right.employeeNumber, "de-AT"),
      );
      await insertIntegrationRun({
        id: runId,
        profileId: preview.profileId,
        direction: "import",
        kind: "personnel",
        format: ["csv", "xlsx"].includes(preview.format) ? preview.format : "csv",
        contentSha256: preview.contentSha256,
        actor: actor.employeeNumber,
        totalCount: preview.summary.total,
        createdCount: preview.summary.create,
        updatedCount: preview.summary.update,
        skippedCount: preview.summary.skip,
        errorCount: 0,
        options: {
          duplicateStrategy: preview.duplicateStrategy,
          sheetName: preview.sheetName,
          headerRow: preview.headerRow,
          sourceTransport: preview.sourceTransport || "file",
          connectionId: preview.connectionId || null,
        },
        result: { rows: preview.rows.map((row) => ({ rowNumber: row.rowNumber, action: row.action })) },
      }, repository);
      await persistPersonnelLearningOrganizationScopeDeltas(
        organization,
        liveLearningActor,
        "personnel-import",
        runId,
        learningOrganizationScopeDeltas,
        "PRINCIPAL_ORGANIZATION_SCOPE_CHANGED",
      );
      await organization.insertAudit(
        liveLearningActor.employeeNumber,
        "integration.personnel.import.applied",
        "integration_run",
        runId,
        JSON.stringify({
          profileId: preview.profileId,
          total: preview.summary.total,
          created: preview.summary.create,
          updated: preview.summary.update,
          skipped: preview.summary.skip,
          contentSha256: preview.contentSha256,
        }),
      );
    }, { isolation: "serializable" }));
  } catch (error) {
    if (isUniquePersistenceViolation(error)) {
      throw httpError(
        409,
        "Die Importvorschau ist veraltet. Eine Personalnummer wurde inzwischen angelegt.",
        "IMPORT_PREVIEW_STALE",
      );
    }
    throw error;
  }
  return { runId, ...preview.summary };
}

const payrollAbsenceCodeByOption = Object.freeze({
  vacation: "vacation",
  sick: "sickness",
  time_off: "time_off",
  branch: "branch_assignment",
  vocational_school: "vocational_school",
  school: "training",
  special_leave: "special_leave",
  external_appointment: "external_appointment",
  team_meeting: "team_meeting",
  other: "other",
});

function payrollOptionCreditedOnDate(option, date, locationId) {
  if (!optionIsAllDay(option)) return true;
  if (option.option_type === "vacation") return vacationDayCount(date, date, locationId) === 1;
  const day = new Date(`${date}T12:00:00Z`).getUTCDay();
  if (day === 0) return false;
  if (!alwaysFullDayOptionTypes.has(option.option_type)) return true;
  let creditedBeforeOrOnDate = 0;
  for (let current = option.date_from; current <= date; current = addDays(current, 1)) {
    if (new Date(`${current}T12:00:00Z`).getUTCDay() !== 0) creditedBeforeOrOnDate += 1;
  }
  return creditedBeforeOrOnDate <= 5;
}

async function payrollAbsencesForDay(employee, date, locationId, activeSickness = null, departmentId = null) {
  const employeeNumber = employee.personnel_number;
  if (String(employee.home_location_id || "") !== String(locationId || "")) return [];
  if (departmentId && Number(employee.preferred_department_id || 0) !== Number(departmentId)) return [];
  const rows = await integrationRuntimeRepository.listPayrollAbsencesForDay({
    employeeNumber,
    date,
  });
  const activeSicknessSet = activeSickness || await activeSicknessEmployeeNumbers(date);
  const sicknessActive = rows.some((row) => row.option_type === "sick")
    || activeSicknessSet.has(employeeNumber);
  const absences = rows
    .filter((row) => payrollOptionCreditedOnDate(row, date, locationId))
    .filter((row) => !(sicknessActive && isTeamWideMeetingOption(row)))
    .map((row) => {
      const internalCode = payrollAbsenceCodeByOption[row.option_type] || "other";
      const quantityMinutes = !row.all_day && isTime(row.start_time) && isTime(row.end_time)
        ? Math.max(0, timeToMinutes(row.end_time) - timeToMinutes(row.start_time))
        : optionMinutesPerDay(row, employee.contracted_hours);
      return {
        internalCode,
        referenceType: "week_option",
        referenceId: Number(row.id),
        quantityMinutes,
        quantityDays: row.all_day ? 1 : 0,
        unit: row.all_day ? "days" : "minutes",
        allDay: Boolean(row.all_day),
        startTime: row.start_time || "",
        endTime: row.end_time || "",
      };
    });
  const weekDay = new Date(`${date}T12:00:00Z`).getUTCDay();
  const sicknessCredit = await sicknessCreditForEmployeeDate(employeeNumber, date);
  if (sicknessCredit.minutes > 0 && activeSicknessSet.has(employeeNumber)
    && !absences.some((absence) => absence.internalCode === "sickness")) {
    absences.push({
      internalCode: "sickness", referenceType: "sickness_case", referenceId: sicknessCredit.caseId,
      quantityMinutes: sicknessCredit.minutes, quantityDays: 1,
      unit: "days", allDay: true, startTime: "", endTime: "",
    });
  }
  const holidayCredited = weekDay >= 1 && weekDay <= 5;
  const hasCreditedAbsence = absences.some((absence) => Number(absence.quantityMinutes || 0) > 0);
  if (employee.active && holidayCredited && !hasCreditedAbsence && isVacationHoliday(date, locationId)) {
    absences.push({
      internalCode: "public_holiday", referenceType: "public_holiday", referenceId: null,
      quantityMinutes: Math.round((Number(employee.contracted_hours || 0) * 60) / 5), quantityDays: 1,
      unit: "days", allDay: true, startTime: "", endTime: "",
    });
  }
  const unique = new Map();
  for (const absence of absences) {
    const key = `${absence.internalCode}:${absence.referenceType}:${absence.referenceId ?? date}`;
    if (!unique.has(key)) unique.set(key, absence);
  }
  return [...unique.values()];
}

async function payrollEmployeesForContext(context, dateFrom, dateTo) {
  const employees = await integrationRuntimeRepository.listPayrollEmployees({
    locationId: context.locationId,
    dateFrom,
    dateTo,
  });
  const visible = await Promise.all(employees.map(async (employee) => {
    if (!context.departmentId) return true;
    if (Number(employee.preferred_department_id || 0) === Number(context.departmentId)) return true;
    return Boolean(await integrationRuntimeRepository.hasPayrollDepartmentActivity({
      employeeNumber: employee.personnel_number,
      dateFrom,
      dateTo,
      departmentId: context.departmentId,
    }));
  }));
  return employees.filter((_employee, index) => visible[index]);
}

async function payrollCorrectionState(employeeNumber, date, locationId, departmentId = null) {
  const row = await integrationRuntimeRepository.getPayrollCorrectionState({
    employeeNumber,
    date,
    locationId,
    departmentId,
  });
  return row?.status || "none";
}

function payrollWorkRanges(evaluation, sourceMode) {
  if (sourceMode === "planned") {
    return (evaluation.planned?.blocks || []).map((block) => ({ start: block.start_time, end: block.end_time }));
  }
  return (evaluation.actual?.segments || []).map((segment) => ({
    start: viennaNowLocal(segment.start).slice(11, 16),
    end: viennaNowLocal(segment.end).slice(11, 16),
  }));
}

function payrollAbsenceOverlapsWork(absence, ranges) {
  if (!ranges.length) return false;
  if (absence.allDay) return true;
  if (!isTime(absence.startTime) || !isTime(absence.endTime)) return true;
  return ranges.some((range) => isTime(range.start) && isTime(range.end)
    && timeRangesOverlap(absence.startTime, absence.endTime, range.start, range.end));
}

async function payrollPreflight(actor, body = {}) {
  const dateFrom = String(body.dateFrom || body.from || "");
  const dateTo = String(body.dateTo || body.to || "");
  if (!isIsoDate(dateFrom) || !isIsoDate(dateTo) || dateTo < dateFrom || daysBetweenInclusive(dateFrom, dateTo) > 93) {
    throw httpError(400, "Bitte einen g\u00fcltigen Zeitraum von h\u00f6chstens 93 Tagen ausw\u00e4hlen.", "PAYROLL_RANGE_INVALID");
  }
  const context = await resolvePlanningContext(body);
  assertSessionContextScope(actor, context);
  let configuration = body.configuration || {};
  const profile = body.profileId ? await integrationProfileById(body.profileId, "export", "payroll") : null;
  if (profile) configuration = { ...profile.configuration, ...configuration };
  const config = normalizePayrollConfiguration(configuration);
  const employees = await payrollEmployeesForContext(context, dateFrom, dateTo);
  const sicknessByDate = new Map();
  const days = [];
  const blockers = [];
  const warnings = [{
    code: "CURRENT_RULES_USED",
    message: "Vertragsstunden und Zuschlagsregeln sind noch nicht historisiert; f\u00fcr den Zeitraum gilt der aktuell gespeicherte Regelstand.",
  }];
  for (const employee of employees) {
    for (let date = dateFrom; date <= dateTo; date = addDays(date, 1)) {
      if (!sicknessByDate.has(date)) sicknessByDate.set(date, await activeSicknessEmployeeNumbers(date));
      const activeSickness = sicknessByDate.get(date);
      const dayEntries = await timeEntriesForDay(employee.personnel_number, date);
      const evaluation = await evaluateTimeDay(employee.personnel_number, date, new Date(), context.departmentId, dayEntries, {
        locationId: context.locationId,
        filterLocation: true,
        activeSickness,
        includeInactive: true,
      });
      const conflictAbsences = await payrollAbsencesForDay(employee, date, context.locationId, activeSickness, null);
      const absences = context.departmentId
        ? await payrollAbsencesForDay(employee, date, context.locationId, activeSickness, context.departmentId)
        : conflictAbsences;
      const relevant = evaluation.plannedMinutes > 0 || evaluation.actualMinutes > 0 || absences.length > 0
        || evaluation.pendingCorrection || Boolean(evaluation.review);
      if (!relevant) continue;
      const reviewState = config.sourceMode === "planned" ? "not_required"
        : !evaluation.review ? "missing" : evaluation.review.stale ? "stale" : "reviewed";
      const correctionState = await payrollCorrectionState(employee.personnel_number, date, context.locationId, context.departmentId);
      const issueCodes = (evaluation.issues || []).map((issue) => issue.code);
      const departmentIds = new Set([
        ...(evaluation.planned?.blocks || []).map((block) => Number(block.department_id || 0)),
        ...dayEntries.filter((entry) => String(entry.location_id || employee.home_location_id) === context.locationId)
          .map((entry) => Number(entry.department_id || 0)),
      ].filter(Boolean));
      if (!context.departmentId && departmentIds.size > 1) {
        issueCodes.push("mixed_departments");
        blockers.push({ code: "MIXED_DEPARTMENTS", employeeNumber: employee.personnel_number, workDate: date });
      }
      const exportedDepartmentId = context.departmentId
        || (departmentIds.size === 1 ? [...departmentIds][0] : (departmentIds.size ? "" : employee.preferred_department_id || ""));
      const workRanges = payrollWorkRanges(evaluation, config.sourceMode);
      const overlappingAbsence = conflictAbsences.find((absence) => absence.internalCode !== "public_holiday"
        && payrollAbsenceOverlapsWork(absence, workRanges));
      const hasWork = (config.sourceMode === "planned" ? evaluation.plannedMinutes : evaluation.actualMinutes) > 0;
      if (config.sourceMode === "actual_reviewed" && employee.home_location_id !== context.locationId && evaluation.actualMinutes > 0) {
        blockers.push({ code: "CROSS_LOCATION_REVIEW_UNAVAILABLE", employeeNumber: employee.personnel_number, workDate: date });
      }
      if (config.sourceMode === "actual_reviewed" && hasWork && reviewState !== "reviewed") {
        blockers.push({ code: reviewState === "stale" ? "STALE_REVIEW" : "MISSING_REVIEW", employeeNumber: employee.personnel_number, workDate: date });
      }
      if (config.sourceMode === "actual_reviewed" && correctionState === "pending") {
        blockers.push({ code: "PENDING_CORRECTION", employeeNumber: employee.personnel_number, workDate: date });
      }
      if (config.sourceMode === "actual_reviewed" && (evaluation.incomplete || (evaluation.issues || []).some((issue) => issue.severity === "error"))) {
        blockers.push({ code: "TIME_EVALUATION_ERROR", employeeNumber: employee.personnel_number, workDate: date });
      }
      if (overlappingAbsence && (config.sourceMode === "planned" ? evaluation.plannedMinutes : evaluation.actualMinutes) > 0) {
        blockers.push({ code: "WORK_ABSENCE_OVERLAP", employeeNumber: employee.personnel_number, workDate: date });
      }
      if (!employee.active) {
        warnings.push({ code: "INACTIVE_EMPLOYEE_INCLUDED", employeeNumber: employee.personnel_number, workDate: date, message: "Ein inaktives Teammitglied hat Bewegungen im Exportzeitraum; der Beschäftigungszeitraum ist noch nicht historisiert." });
        blockers.push({ code: "INACTIVE_EMPLOYMENT_HISTORY_REQUIRED", employeeNumber: employee.personnel_number, workDate: date });
      }
      const settings = await settingsForLocation(context.locationId);
      const newSaturdayRule = Boolean(evaluation.actual?.saturdayCreditStatus || evaluation.planned?.blocks?.some(block => block.saturday_credit_status));
      const saturdayFactor = newSaturdayRule ? 1.5 : Number(settings.saturday_bonus_factor || 1);
      const plannedEligible = newSaturdayRule ? Number(evaluation.planned?.saturdayEligibleMinutes || 0) : saturdayFactor > 1
        ? Math.round(Number(evaluation.planned?.saturdayBonusMinutes || 0) / (saturdayFactor - 1))
        : 0;
      if (config.sourceMode === 'planned' && evaluation.planned?.saturdayCreditReviewRequired) {
        blockers.push({ code: 'SATURDAY_CREDIT_REVIEW_REQUIRED', employeeNumber: employee.personnel_number, workDate: date });
      }
      days.push({
        personnelNumber: employee.personnel_number,
        fullName: employee.full_name,
        workDate: date,
        locationId: context.locationId,
        departmentId: exportedDepartmentId,
        sourceMode: config.sourceMode,
        plannedMinutes: Number(evaluation.plannedMinutes || 0),
        actualMinutes: Number(evaluation.actualMinutes || 0),
        breakMinutes: Number(evaluation.breakMinutes || 0),
        saturdayBonusMinutes: config.sourceMode === "planned"
          ? Number(evaluation.planned?.saturdayBonusMinutes || 0)
          : Number(evaluation.saturdayBonusMinutes || 0),
        saturdayEligibleMinutes: config.sourceMode === "planned"
          ? plannedEligible
          : Number(evaluation.actual?.saturdayEligibleMinutes || 0),
        saturdayFactor,
        valuedMinutes: config.sourceMode === "planned" ? Number(evaluation.plannedValuedMinutes || 0) : Number(evaluation.actualValuedMinutes || 0),
        differenceMinutes: Number(evaluation.differenceMinutes || 0),
        absences,
        reviewState,
        correctionState,
        issueCodes,
      });
    }
  }
  const built = buildPayrollRows(days, config);
  const fingerprint = sha256(JSON.stringify({ dateFrom, dateTo, context, config: built.config, rows: built.rows }));
  return {
    dateFrom,
    dateTo,
    context,
    profileId: profile?.id || null,
    configuration: built.config,
    columns: built.columns,
    rows: built.rows,
    rowCount: built.rows.length,
    employeeCount: new Set(days.map((day) => day.personnelNumber)).size,
    dayCount: days.length,
    blockers,
    warnings: warnings.slice(0, 200),
    fingerprint,
  };
}

function payrollFileName(preflight, draft = false) {
  const extension = preflight.configuration.format === "xlsx" ? "xlsx" : "csv";
  const mode = preflight.configuration.sourceMode === "planned" ? "planwerte" : "istzeiten";
  return `${draft ? "ENTWURF-" : ""}grabenplaner-lohnexport-${mode}-${preflight.dateFrom}-${preflight.dateTo}.${extension}`;
}

function payrollRowsForCsv(preflight) {
  if (preflight.configuration.decimalSeparator !== "comma") return preflight.rows;
  return preflight.rows.map((row) => Object.fromEntries(Object.entries(row).map(([key, value]) => [
    key,
    typeof value === "number" && !Number.isInteger(value) ? String(value).replace(".", ",") : value,
  ])));
}

function serializeIntegrationDelivery(row) {
  return {
    id: row.id,
    connectionId: row.connection_id,
    profileId: row.profile_id || null,
    dateFrom: row.date_from,
    dateTo: row.date_to,
    locationId: row.location_id,
    departmentId: row.department_id || null,
    connectionRevision: Math.max(1, Number(row.connection_revision || 1)),
    connectionFingerprint: row.connection_fingerprint || "",
    payloadSha256: row.payload_sha256,
    rowCount: Number(row.row_count || 0),
    status: row.status,
    attemptCount: Number(row.attempt_count || 0),
    httpStatus: row.http_status === null ? null : Number(row.http_status),
    errorCode: row.error_code || "",
    actorEmployeeNumber: row.actor_employee_number || "",
    startedAt: row.started_at,
    completedAt: row.completed_at || null,
    updatedAt: row.updated_at,
  };
}

async function reconcileInterruptedIntegrationDeliveries() {
  if (!tableExists("integration_deliveries")) return 0;
  const interrupted = await integrationRuntimeRepository.listSendingDeliveryIds();
  if (!interrupted.length) return 0;
  const recoveredIds = await integrationRuntimeRepository.transaction(async (repository) => {
    const recovered = [];
    for (const row of interrupted) {
      const result = await repository.markDeliveryInterrupted({ id: row.id });
      if (result.rowsAffected) {
        recovered.push(row.id);
      }
    }
    return recovered;
  });
  for (const id of recoveredIds) {
    (await auditPortal("system", "integration.payroll.delivery.recovered", "integration_delivery", id,
      JSON.stringify({ status: "unknown", errorCode: "PROCESS_INTERRUPTED" })));
  }
  return recoveredIds.length;
}

function minimizedPayrollApiPayload(preflight, deliveryId, generatedAt) {
  const columns = preflight.columns.filter((column) => column.id !== "fullName")
    .map((column) => ({ id: column.id, label: column.label, type: column.type }));
  const rows = preflight.rows.map((row) => Object.fromEntries(columns.map((column) => [column.id, row[column.id] ?? ""])));
  const dataSha256 = payloadSha256({ columns, rows });
  return {
    schema: CONTRACT_IDS.payrollHttpsJson,
    deliveryId,
    generatedAt,
    source: {
      dateFrom: preflight.dateFrom,
      dateTo: preflight.dateTo,
      locationId: preflight.context.locationId,
      departmentId: preflight.context.departmentId || null,
      sourceMode: preflight.configuration.sourceMode,
      layout: preflight.configuration.layout,
    },
    columns,
    rows,
    dataSha256,
  };
}

async function payrollHandoffPreflight(actor, body = {}) {
  const month = String(body.month || "");
  if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)) {
    throw httpError(400, "Bitte einen gültigen Abrechnungsmonat auswählen.", "PAYROLL_HANDOFF_MONTH_INVALID");
  }
  const context = await resolvePlanningContext({
    locationId: body.locationId,
    departmentId: body.departmentId || "",
  });
  assertSessionContextScope(actor, context);
  const allStatements = await requireGovernanceStore()
    .listTimeStatements({ month, includeArchived: false });
  const statementByEmployee = new Map(allStatements.map((statement) => [String(statement.employeeNumber), statement]));
  const employees = await integrationRuntimeRepository.listPayrollHandoffEmployees({
    locationId: context.locationId,
    departmentId: String(context.departmentId || ""),
  });
  const relevant = employees.filter((employee) => employee.active || statementByEmployee.has(String(employee.personnel_number)));
  const blockers = [];
  const statements = [];
  for (const employee of relevant) {
    const statement = statementByEmployee.get(String(employee.personnel_number));
    if (!statement) {
      blockers.push({
        code: "MONTHLY_STATEMENT_MISSING",
        employeeNumber: String(employee.personnel_number),
        message: "Für dieses Teammitglied fehlt der aktuelle Monatsnachweis.",
      });
      continue;
    }
    if (statement.status !== "finalized" || statement.archived) {
      blockers.push({
        code: "MONTHLY_STATEMENT_NOT_FINALIZED",
        employeeNumber: String(employee.personnel_number),
        statementId: statement.id,
        status: statement.status,
        message: "Der aktuelle Monatsnachweis ist noch nicht finalisiert.",
      });
      continue;
    }
    statements.push({
      employeeId: String(employee.personnel_number),
      statementId: statement.id,
      statementRevision: Number(statement.revision),
      statementReceiptSha256: statement.receiptSha256,
      actualMinutes: Number(statement.actualMinutes || 0),
      breakMinutes: Number(statement.breakMinutes || 0),
      status: "finalized",
    });
  }
  const fingerprint = sha256(JSON.stringify({
    month,
    context,
    statements: statements.map((statement) => ({
      employeeId: statement.employeeId,
      statementId: statement.statementId,
      receipt: statement.statementReceiptSha256,
    })),
    blockers: blockers.map(({ code, employeeNumber, statementId = "" }) => ({ code, employeeNumber, statementId })),
  }));
  return {
    month,
    context,
    employeeCount: relevant.length,
    finalizedCount: statements.length,
    blockers,
    statements,
    fingerprint,
    notice: "Die Übergabe enthält ausschließlich finalisierte tatsächliche Zeitnachweise. Sie berechnet weder Entgelt noch Sozialversicherungsbeiträge und ersetzt keine mBGM-Übermittlung.",
  };
}

function publicPayrollHandoffPreflight(preflight) {
  return {
    month: preflight.month,
    context: preflight.context,
    employeeCount: preflight.employeeCount,
    finalizedCount: preflight.finalizedCount,
    blockers: preflight.blockers.slice(0, 200),
    fingerprint: preflight.fingerprint,
    notice: preflight.notice,
  };
}

async function payrollHandoffForActor(actor, id) {
  const value = await requireGovernanceStore().payrollHandoffRow(id);
  if (!value) throw httpError(404, "Die Monatsübergabe wurde nicht gefunden.", "PAYROLL_HANDOFF_NOT_FOUND");
  assertSessionContextScope(actor, {
    locationId: value.handoff.scope.locationId,
    departmentId: value.handoff.scope.departmentId || "",
  });
  return value;
}

app.post("/api/integrations/payroll-handoffs/preflight", async (request, response) => {
  const actor = integrationActor(request, "payroll:export");
  response.json(publicPayrollHandoffPreflight(
    await payrollHandoffPreflight(actor, request.body || {}),
  ));
});

app.get("/api/integrations/payroll-handoffs", async (request, response) => {
  const actor = requirePortalAnyPermissionOrLocal(
    request,
    ["integrations:read", "payroll:export", "payroll:deliver"],
    { csrf: true },
  );
  const accessibleLocations = new Set((await getLocationsForSession(actor, true))
    .map((location) => String(location.id)));
  const month = String(request.query.month || "");
  const locationId = String(request.query.locationId || "");
  if (locationId && !accessibleLocations.has(locationId)) {
    throw httpError(403, "Auf diesen Standort besteht kein Zugriff.", "PORTAL_SCOPE_FORBIDDEN");
  }
  const handoffs = (await requireGovernanceStore().listPayrollHandoffs({
    month,
    locationId,
    includeSuperseded: String(request.query.includeSuperseded || "") === "1",
  })).filter((handoff) => accessibleLocations.has(String(handoff.locationId)));
  response.json({
    handoffs,
    completionRule: "Ohne erfasstes externes Protokoll bleibt die Übergabe offen.",
    directEldaTransmission: false,
  });
});

app.post("/api/integrations/payroll-handoffs", async (request, response) => {
  const actor = integrationActor(request, "payroll:export");
  const preflight = await payrollHandoffPreflight(actor, request.body || {});
  if (!request.body.fingerprint || request.body.fingerprint !== preflight.fingerprint) {
    throw httpError(409, "Die Monatsnachweise haben sich seit der Vorprüfung geändert. Bitte erneut prüfen.", "PAYROLL_HANDOFF_PREFLIGHT_STALE");
  }
  if (preflight.blockers.length) {
    const error = httpError(
      422,
      "Die Monatsübergabe kann erst nach Finalisierung aller Monatsnachweise erstellt werden.",
      "PAYROLL_HANDOFF_BLOCKED",
    );
    error.details = { blockers: preflight.blockers.slice(0, 200) };
    throw error;
  }
  if (!preflight.statements.length) {
    throw httpError(422, "Für diesen Umfang sind keine finalisierten Monatsnachweise vorhanden.", "PAYROLL_HANDOFF_EMPTY");
  }
  const value = await requireGovernanceStore().createPayrollHandoffRecord({
    month: preflight.month,
    scope: {
      locationId: preflight.context.locationId,
      departmentId: preflight.context.departmentId || "",
    },
    statements: preflight.statements,
    actor: actor.employeeNumber,
  });
  const summary = requireGovernanceStore().payrollHandoffSummary(value);
  (await auditPortal(actor.employeeNumber, value.reused ? "integration.payroll.handoff.reused" : "integration.payroll.handoff.created",
    "payroll_handoff", summary.id, JSON.stringify({
      month: summary.month,
      locationId: summary.locationId,
      departmentId: summary.departmentId,
      revision: summary.revision,
      statementCount: summary.statementCount,
      receiptSha256: summary.receiptSha256,
    })));
  response.status(value.reused ? 200 : 201).json({ handoff: summary, reused: Boolean(value.reused) });
});

app.get("/api/integrations/payroll-handoffs/:id/file", async (request, response) => {
  const actor = integrationActor(request, "payroll:export");
  let value = await payrollHandoffForActor(actor, request.params.id);
  value = await requireGovernanceStore()
    .appendPayrollHandoffEvent(value.row.id, { eventType: "exported" }, actor.employeeNumber);
  (await auditPortal(actor.employeeNumber, "integration.payroll.handoff.exported", "payroll_handoff", value.row.id,
    JSON.stringify({ receiptSha256: value.handoff.receiptSha256 })));
  const document = {
    contract: CONTRACT_IDS.payrollPeriodHandoff,
    handoff: value.handoff,
    externalTransmission: {
      required: true,
      directEldaTransmissionByGrabenplaner: false,
      completionRequiresExternalProtocol: true,
    },
  };
  const fileName = `grabenplaner-monatsuebergabe-${value.handoff.month}-${value.handoff.scope.locationId}-r${value.handoff.revision}.json`;
  response.setHeader("Content-Type", "application/json; charset=utf-8");
  response.setHeader("Cache-Control", "private, no-store");
  response.setHeader("Content-Disposition", `attachment; filename="${fileName}"`);
  response.send(`${JSON.stringify(document, null, 2)}\n`);
});

app.post("/api/integrations/payroll-handoffs/:id/events", async (request, response) => {
  const actor = integrationActor(request, "payroll:deliver");
  const current = await payrollHandoffForActor(actor, request.params.id);
  const action = String(request.body?.action || "");
  let eventType;
  if (action === "mark_external_transfer") eventType = "external_transfer_marked";
  else if (action === "record_protocol") eventType = "protocol_recorded";
  else throw httpError(400, "Die gewünschte Übergabeaktion ist nicht unterstützt.", "PAYROLL_HANDOFF_ACTION_INVALID");
  const value = await requireGovernanceStore().appendPayrollHandoffEvent(current.row.id, {
    eventType,
    protocolResult: request.body?.protocolResult || "",
    protocolNumber: request.body?.protocolNumber || "",
    note: request.body?.note || "",
  }, actor.employeeNumber);
  const summary = requireGovernanceStore().payrollHandoffSummary(value);
  (await auditPortal(actor.employeeNumber, `integration.payroll.handoff.${action}`, "payroll_handoff", summary.id,
    JSON.stringify({
      state: summary.state,
      protocolResult: summary.protocolResult,
      protocolNumber: summary.protocolNumber,
    })));
  response.json({ handoff: summary });
});

app.get("/api/integrations/contracts", (request, response) => {
  integrationActor(request, "integrations:read");
  response.json({
    contracts: contractSummaries().map((contract) => ({
      ...contract,
      documentUrl: `/api/integrations/contracts/${encodeURIComponent(contract.id)}?download=1`,
    })),
  });
});

app.get("/api/integrations/contracts/:id", (request, response) => {
  integrationActor(request, "integrations:read");
  const contract = contractById(request.params.id);
  if (!contract) throw httpError(404, "Der Schnittstellenvertrag wurde nicht gefunden.", "INTEGRATION_CONTRACT_NOT_FOUND");
  const sha256 = contractSha256(contract);
  response.setHeader("ETag", `\"sha256-${sha256}\"`);
  response.setHeader("Cache-Control", "private, no-store");
  if (String(request.query.download || "") === "1") {
    response.setHeader("Content-Type", "application/json; charset=utf-8");
    response.setHeader("Content-Disposition", `attachment; filename=\"${contract.id}.json\"`);
  }
  response.json({ contract, documentSha256: sha256 });
});

