const SERVER_MONITOR_CONTROL_ROLES = new Set(["admin", "it_admin", "developer"]);
const SERVER_MONITOR_RESTART_COOLDOWN_MS = 5 * 60 * 1000;
let serverManagedRestartRequested = false;
let hostManagedRebootRequested = false;

function serverMonitorRestartCooldownSeconds(lastAcceptedAt, now = new Date()) {
  if (!lastAcceptedAt) return 0;
  const acceptedMilliseconds = Date.parse(`${String(lastAcceptedAt).replace(" ", "T").replace(/Z$/i, "")}Z`);
  if (!Number.isFinite(acceptedMilliseconds)) return SERVER_MONITOR_RESTART_COOLDOWN_MS / 1000;
  return Math.max(0, Math.ceil(
    (acceptedMilliseconds + SERVER_MONITOR_RESTART_COOLDOWN_MS - now.getTime()) / 1000,
  ));
}

async function currentServerMonitorRestartCooldownSeconds(now = new Date()) {
  const latestAcceptedAt = (await sqliteSystemDiagnosticsOperations
    .latestAuditActionCreatedAt("system.server_monitor.restart.accepted"));
  return serverMonitorRestartCooldownSeconds(latestAcceptedAt, now);
}

async function serverMonitorActionCapabilities(
  actor,
  {
    managedRestartAvailable = serverManagedRestartAvailable,
    restartCooldownSeconds,
    managedHostRebootAvailable = currentHostManagedRebootAvailable(),
    hostSecurityConfigured = false,
    hostSecurityStatusAvailable = false,
    hostSecurityStatusErrorCode = null,
    hostRebootRequired = false,
    hostSecurityPendingConfirmation = false,
    hostRebootInProgress = hostManagedRebootRequested,
  } = {},
) {
if (restartCooldownSeconds === undefined) restartCooldownSeconds = (await currentServerMonitorRestartCooldownSeconds());

  const vpsRebootVisible = Boolean(actor && actor.role === "developer");
  let vpsRebootUnavailableReason = null;
  if (vpsRebootVisible) {
    if (!actor.permissions?.includes("system:write")
      || !actor.permissions?.includes("system:diagnostics:technical")) {
      vpsRebootUnavailableReason = "VPS_REBOOT_PERMISSION_REQUIRED";
    } else if (hostRebootInProgress) {
      vpsRebootUnavailableReason = "VPS_REBOOT_IN_PROGRESS";
    } else if (!hostSecurityConfigured || !hostSecurityStatusAvailable || hostSecurityStatusErrorCode) {
      vpsRebootUnavailableReason = "VPS_REBOOT_STATUS_UNVERIFIED";
    } else if (hostSecurityPendingConfirmation) {
      vpsRebootUnavailableReason = "VPS_REBOOT_SECURITY_CONFIRMATION_PENDING";
    } else if (!managedHostRebootAvailable) {
      vpsRebootUnavailableReason = "VPS_REBOOT_CONTROL_UNAVAILABLE";
    } else if (!hostRebootRequired) {
      vpsRebootUnavailableReason = "VPS_REBOOT_NOT_REQUIRED";
    }
  }
  return {
    canRefresh: Boolean(actor),
    canRestart: Boolean(
      actor
      && managedRestartAvailable
      && restartCooldownSeconds === 0
      && SERVER_MONITOR_CONTROL_ROLES.has(actor.role)
       && actor.permissions?.includes("system:write")
       && actor.permissions?.includes("system:diagnostics:technical"),
    ),
    canVpsReboot: vpsRebootVisible && vpsRebootUnavailableReason === null,
    vpsRebootVisible,
    vpsRebootUnavailableReason,
  };
}

async function serverStatusForActor(diagnostics, actor) {
  return {
    ...(await serverStatusSummary(diagnostics)),
    monitorActions: (await serverMonitorActionCapabilities(actor, {
      hostSecurityConfigured: diagnostics?.hostSecurity?.configured === true,
      hostSecurityStatusAvailable: diagnostics?.hostSecurity?.statusAvailable === true,
      hostSecurityStatusErrorCode: diagnostics?.hostSecurity?.lastErrorCode || null,
      hostRebootRequired: diagnostics?.hostSecurity?.rebootRequired === true,
      hostSecurityPendingConfirmation: diagnostics?.hostSecurity?.pendingConfirmation === true,
    })),
  };
}

function assertServerRestartConfirmation(body) {
  if (!body || typeof body !== "object" || Array.isArray(body)
    || Object.keys(body).length !== 1 || body.confirmation !== "SERVER_RESTART") {
    throw httpError(
      400,
      "Der kontrollierte Serverneustart wurde nicht eindeutig bestätigt.",
      "SERVER_RESTART_CONFIRMATION_REQUIRED",
    );
  }
}

function assertVpsRebootConfirmation(body) {
  if (!body || typeof body !== "object" || Array.isArray(body)
    || Object.keys(body).length !== 2
    || body.confirmation !== "VPS_REBOOT"
    || typeof body.currentPassword !== "string"
    || body.currentPassword.length < 1
    || body.currentPassword.length > 512) {
    throw httpError(
      400,
      "Der kontrollierte VPS-Neustart wurde nicht eindeutig bestätigt.",
      "VPS_REBOOT_CONFIRMATION_REQUIRED",
    );
  }
}

function currentHostSecurityStatus() {
  const configured = String(process.env.GRABENPLANER_HOST_SECURITY_CONFIGURED || "").trim();
  return readHostSecurityStatus({
    configured: configured === "1" ? true : (configured === "0" ? false : undefined),
  });
}

function hostRebootHttpError(error, response) {
  const code = String(error?.code || "UNAVAILABLE");
  if (code === "RATE_LIMITED") {
    const retryAfterSeconds = Number.isSafeInteger(error?.retryAfterSeconds)
      ? Math.max(1, Math.min(error.retryAfterSeconds, 900))
      : 900;
    response.setHeader("Retry-After", String(retryAfterSeconds));
    return httpError(
      429,
      `Der kontrollierte VPS-Neustart ist noch ${retryAfterSeconds} Sekunden gesperrt.`,
      "VPS_REBOOT_RATE_LIMITED",
    );
  }
  if (code === "BACKUP_REQUIRED") {
    return httpError(
      503,
      "Der root-geschützte Sicherungsbeleg wurde nicht bestätigt. Der VPS wurde nicht neu gestartet.",
      "VPS_REBOOT_BACKUP_FAILED",
    );
  }
  if (code === "MAINTENANCE_BUSY") {
    return httpError(
      409,
      "Eine andere geschützte Wartung ist aktiv. Der VPS wurde nicht neu gestartet.",
      "VPS_REBOOT_MAINTENANCE_BUSY",
    );
  }
  if (code === "SECURITY_PENDING") {
    return httpError(
      409,
      "Eine Host-Sicherheitsänderung wartet noch auf Bestätigung. Der VPS wurde nicht neu gestartet.",
      "VPS_REBOOT_SECURITY_CONFIRMATION_PENDING",
    );
  }
  if (code === "BUSY") {
    return httpError(409, "Ein kontrollierter VPS-Neustart wird bereits vorbereitet.", "VPS_REBOOT_IN_PROGRESS");
  }
  if (code === "NOT_REQUIRED") {
    return httpError(
      409,
      "Der Ubuntu-Host meldet derzeit keinen erforderlichen Sicherheitsneustart.",
      "VPS_REBOOT_NOT_REQUIRED",
    );
  }
  return httpError(
    503,
    "Die geschützte VPS-Neustartsteuerung ist derzeit nicht verfügbar.",
    "VPS_REBOOT_CONTROL_UNAVAILABLE",
  );
}

async function queuePostgresqlLifecycle(request, response, actor, action, requestId) {
  await auditPortal(actor.employeeNumber, 'system.postgresql.maintenance.requested', 'system', action, JSON.stringify({ requestId }));
  if (!await authorizePersistenceOperation({ readOnly: false })) throw httpError(403,
    'Die Berechtigung hat sich geändert. Der Wartungsauftrag wurde nicht übergeben.', 'PG_LIFECYCLE_AUTHORIZATION_CHANGED');
  let result;
  try { result = await require('./lib/persistence/postgresql/lifecycle-control').requestControl({ action, requestId }); }
  catch (error) {
    await auditPortal(actor.employeeNumber, 'system.postgresql.maintenance.failed', 'system', action,
      JSON.stringify({ requestId, code: String(error.code || error.message || 'PG_LIFECYCLE_FAILED').slice(0, 80) }));
    throw httpError(503, 'Die Serverwartung konnte nicht beauftragt werden. Der aktuelle Zustand wird in der Diagnose angezeigt.', 'PG_LIFECYCLE_UNAVAILABLE');
  }
  return response.status(202).json({ ok: true, requestId, acceptedAt: result.acceptedAt, backupVerified: false,
    code: action === 'restart' ? 'SERVER_RESTART_ACCEPTED' : action === 'vps-reboot' ? 'VPS_REBOOT_ACCEPTED' : 'SERVER_SHUTDOWN_ACCEPTED',
    ...(action === 'vps-reboot' ? { previousHostBootGeneration: hostBootGeneration } : {}),
    message: 'Die Serverwartung wurde beauftragt. Vor dem Abschluss wird ein gemeinsamer Sicherungspunkt beider Datenbanken erstellt.' });
}

app.post("/api/portal/v1/server-monitor/restart", async (request, response) => {
  const actor = requirePortalAdminOrLocal(request, "system:write");
  if (isLocalSystemSession(actor) || !SERVER_MONITOR_CONTROL_ROLES.has(actor.role)) {
    throw httpError(
      403,
      "Nur Developer, IT-Administration oder Administration dürfen den Server kontrolliert neu starten.",
      "SERVER_RESTART_ROLE_DENIED",
    );
  }
  if (!actor.permissions?.includes("system:diagnostics:technical")) {
    throw httpError(
      403,
      "Für den kontrollierten Serverneustart fehlt die technische Diagnoseberechtigung.",
      "SERVER_RESTART_DIAGNOSTICS_PERMISSION_REQUIRED",
    );
  }
  assertServerRestartConfirmation(request.body);
  if (!serverManagedRestartAvailable) {
    throw httpError(
      409,
      "Der kontrollierte Neustart ist ausschließlich im verwalteten Ubuntu-Serverdienst verfügbar.",
      "SERVER_RESTART_SERVICE_REQUIRED",
    );
  }
  if (serverManagedRestartRequested) {
    throw httpError(409, "Ein kontrollierter Serverneustart wurde bereits eingeleitet.", "SERVER_RESTART_IN_PROGRESS");
  }
  const cooldownSeconds = (await currentServerMonitorRestartCooldownSeconds());
  if (cooldownSeconds > 0) {
    response.setHeader("Retry-After", String(cooldownSeconds));
    throw httpError(
      429,
      `Nach einem kontrollierten Neustart ist die Aktion noch ${cooldownSeconds} Sekunden gesperrt.`,
      "SERVER_RESTART_COOLDOWN",
    );
  }

  const requestId = crypto.randomUUID();
  serverManagedRestartRequested = true;
  if (postgresqlActive) {
    try { return await queuePostgresqlLifecycle(request, response, actor, 'restart', requestId); }
    catch (error) { serverManagedRestartRequested = false; throw error; }
  }
  try {
    await createDatabaseBackup("server-monitor-restart");
    (await auditPortal(
      actor.employeeNumber,
      "system.server_monitor.restart.accepted",
      "system",
      "server-monitor",
      JSON.stringify({ requestId, result: "accepted" }),
    ));
  } catch (error) {
    serverManagedRestartRequested = false;
    throw error;
  }
  response.status(202).json({
    ok: true,
    code: "SERVER_RESTART_ACCEPTED",
    requestId,
    message: "Der verifizierte Sicherungspunkt wurde erstellt. Grabenplaner wird kontrolliert neu gestartet.",
  });
  response.on("finish", () => {
    setTimeout(() => shutdown({
      reason: "server-monitor-restart",
      skipBackup: true,
      exitCode: 75,
    }), 350);
  });
});

app.post("/api/portal/v1/server-monitor/vps-reboot", async (request, response) => {
  const actor = requirePortalSession(request, "system:write");
  if (actor.role !== "developer") {
    throw httpError(
      403,
      "Nur die Developer-Rolle darf den vollständigen VPS kontrolliert neu starten.",
      "VPS_REBOOT_ROLE_DENIED",
    );
  }
  if (!actor.permissions?.includes("system:diagnostics:technical")) {
    throw httpError(
      403,
      "Für den kontrollierten VPS-Neustart fehlt die technische Diagnoseberechtigung.",
      "VPS_REBOOT_DIAGNOSTICS_PERMISSION_REQUIRED",
    );
  }
  assertVpsRebootConfirmation(request.body);
  if (!currentHostManagedRebootAvailable()) {
    throw httpError(
      409,
      "Der kontrollierte VPS-Neustart ist nur in der verwalteten Ubuntu-Serverlaufzeit verfügbar.",
      "VPS_REBOOT_SERVICE_REQUIRED",
    );
  }
  if (hostManagedRebootRequested) {
    throw httpError(409, "Ein kontrollierter VPS-Neustart wurde bereits eingeleitet.", "VPS_REBOOT_IN_PROGRESS");
  }

  const hostSecurity = currentHostSecurityStatus();
  if (hostSecurity.configured !== true
    || hostSecurity.statusAvailable !== true
    || hostSecurity.lastErrorCode) {
    throw httpError(
      409,
      "Vor einem VPS-Neustart ist ein aktueller, sicher lesbarer Ubuntu-Host-Audit erforderlich.",
      "VPS_REBOOT_STATUS_UNVERIFIED",
    );
  }
  if (hostSecurity.rebootRequired !== true
    || hostSecurity.pendingConfirmation === true) {
    throw httpError(
      409,
      "Der Ubuntu-Host meldet derzeit keinen sicher bestätigten Neustartbedarf.",
      "VPS_REBOOT_NOT_REQUIRED",
    );
  }
  try {
    if (!postgresqlActive) assertSafeHostRebootSocket();
  } catch {
    throw httpError(
      503,
      "Die geschützte VPS-Neustartsteuerung ist derzeit nicht verfügbar.",
      "VPS_REBOOT_CONTROL_UNAVAILABLE",
    );
  }

  const { session } = await requireBackupAdminReauthentication(request, {
    permission: "system:write",
    operation: "vps-reboot",
  });
  if (hostManagedRebootRequested) {
    throw httpError(409, "Ein kontrollierter VPS-Neustart wurde bereits eingeleitet.", "VPS_REBOOT_IN_PROGRESS");
  }

  const requestId = crypto.randomUUID();
  hostManagedRebootRequested = true;
  if (postgresqlActive) {
    try { return await queuePostgresqlLifecycle(request, response, session, 'vps-reboot', requestId); }
    catch (error) { hostManagedRebootRequested = false; throw error; }
  }
  let result;
  try {
    result = await prepareControlledHostReboot({
      requestId,
      createBackup: () => createDatabaseBackup("vps-reboot"),
      recordRequest: async () => (await auditPortal(
        session.employeeNumber,
        "system.host_reboot.requested",
        "system",
        "vps-reboot",
        JSON.stringify({ requestId }),
      )),
      requestControl: requestHostReboot,
    });
  } catch (error) {
    hostManagedRebootRequested = false;
    try {
      (await auditPortal(
        session.employeeNumber,
        "system.host_reboot.failed",
        "system",
        "vps-reboot",
        JSON.stringify({
          requestId,
          errorCode: String(error?.code || "VPS_REBOOT_CONTROL_UNAVAILABLE").slice(0, 80),
        }),
      ));
    } catch {
      console.error("VPS-Reboot-Fehler konnte nicht revisionssicher protokolliert werden.");
    }
    if (error?.code === "HOST_REBOOT_BACKUP_FAILED") {
      throw httpError(
        503,
        "Der verifizierte Sicherungspunkt konnte nicht erstellt werden. Der VPS wurde nicht neu gestartet.",
        "VPS_REBOOT_BACKUP_FAILED",
      );
    }
    if (error?.status) throw error;
    throw hostRebootHttpError(error, response);
  }
  try {
    (await auditPortal(
      session.employeeNumber,
      "system.host_reboot.accepted",
      "system",
      "vps-reboot",
      JSON.stringify({ requestId, result: "accepted" }),
    ));
  } catch {
    console.error("Angenommener VPS-Reboot konnte nicht nachträglich protokolliert werden.");
  }
  response.status(202).json({
    ok: true,
    code: "VPS_REBOOT_ACCEPTED",
    requestId,
    acceptedAt: result.acceptedAt,
    previousHostBootGeneration: hostBootGeneration,
    message: "Der verifizierte Sicherungspunkt wurde erstellt. Der VPS wird kontrolliert neu gestartet.",
  });
});

app.post("/api/system/exit", async (request, response) => {
  if (serverModeActive) {
    const session = requirePortalSession(request, "system:write");
    if (!["developer", "it_admin", "admin"].includes(session.role)) {
      throw httpError(403, "Nur Developer, IT-Administration oder Administration dürfen den Server beenden.", "SERVER_SHUTDOWN_ROLE_DENIED");
    }
    if (postgresqlActive) return queuePostgresqlLifecycle(request, response, session, 'shutdown', crypto.randomUUID());
  }
  const driveInfo = runtimeDriveInfo();
  let backup = null;
  try {
    backup = await createDatabaseBackup("shutdown");
  } catch (error) {
    console.error("Backup beim Beenden konnte nicht erstellt werden:", error);
    if (localBackupArchiveEnabled()) throw httpError(503,
      "Die Sicherung konnte nicht bestätigt werden. Der Server wurde nicht beendet; bitte zuerst den Sicherungsstatus prüfen.",
      "SERVER_SHUTDOWN_BACKUP_UNVERIFIED");
  }
  response.json({
    ok: true,
    message: serverModeActive
      ? "Der Grabenplaner-Server wird sicher beendet."
      : "Grabenplaner wird sicher beendet. Bitte dieses Fenster danach schließen.",
    backup,
    drive: driveInfo.drive,
  });
  response.on("finish", () => setTimeout(() => shutdown({ reason: "api", skipBackup: true }), 350));
});

function scheduleBackupImport(importPath) {
  const tempRoot = fs.mkdtempSync(path.join(os.tmpdir(), "grabenplaner-db-import-"));
  const scriptPath = path.join(tempRoot, "apply-db-import.ps1");
  const launcherPath = path.join(tempRoot, "launch-db-import.cmd");
  const safeAppDir = __dirname.replaceAll("'", "''");
  const safeDatabasePath = databasePath.replaceAll("'", "''");
  const safeImportPath = importPath.replaceAll("'", "''");
  const safeTempRoot = tempRoot.replaceAll("'", "''");
  const safeVersionLabel = APP_VERSION_LABEL.replaceAll("'", "''");
  const script = `
$ErrorActionPreference = 'Stop'
$appDir = '${safeAppDir}'
$databasePath = '${safeDatabasePath}'
$importPath = '${safeImportPath}'
$workDir = '${safeTempRoot}'
$versionLabel = '${safeVersionLabel}'
$pidToWait = ${process.pid}
$logPath = Join-Path $appDir 'data\\import-last.log'
function Write-ImportLog([string]$message) {
  $line = "[{0}] {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $message
  Add-Content -LiteralPath $logPath -Value $line -Encoding UTF8
}
try {
  New-Item -ItemType Directory -Path (Split-Path -Parent $logPath) -Force | Out-Null
  Set-Content -LiteralPath $logPath -Value ("[{0}] Datenbank-Import gestartet" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss')) -Encoding UTF8
  Write-ImportLog "App-Verzeichnis: $appDir"
  Write-ImportLog "Warte auf Server-Prozess $pidToWait ..."
  $deadline = (Get-Date).AddMinutes(2)
  while (Get-Process -Id $pidToWait -ErrorAction SilentlyContinue) {
    if ((Get-Date) -gt $deadline) { throw "Server-Prozess $pidToWait wurde nicht rechtzeitig beendet." }
    Start-Sleep -Milliseconds 300
  }
  Start-Sleep -Milliseconds 800
  Remove-Item -LiteralPath "$databasePath-wal" -Force -ErrorAction SilentlyContinue
  Remove-Item -LiteralPath "$databasePath-shm" -Force -ErrorAction SilentlyContinue
  Copy-Item -LiteralPath $importPath -Destination $databasePath -Force
  Remove-Item -LiteralPath $importPath -Force -ErrorAction SilentlyContinue
  Write-ImportLog "Datenbank ersetzt."
  $startFile = Join-Path $appDir "Grabenplaner $versionLabel starten.cmd"
  if (-not (Test-Path $startFile)) { $startFile = Join-Path $appDir 'Dienstplan starten.cmd' }
  Write-ImportLog "Starte neu: $startFile"
  Start-Process -FilePath $startFile -WorkingDirectory $appDir
  Start-Sleep -Seconds 3
  Write-ImportLog "Datenbank-Import erfolgreich abgeschlossen."
  Remove-Item -LiteralPath $workDir -Recurse -Force -ErrorAction SilentlyContinue
} catch {
  try {
    Write-ImportLog ("FEHLER: " + $_.Exception.Message)
    Write-ImportLog ("Details: " + $_.ScriptStackTrace)
  } catch {}
  exit 1
}
`;
  fs.writeFileSync(scriptPath, script, "utf8");
  fs.writeFileSync(
    launcherPath,
    `@echo off\r\nstart "" /min powershell.exe -NoProfile -ExecutionPolicy Bypass -File "${scriptPath}"\r\n`,
    "utf8",
  );
  setTimeout(() => {
    childProcess.spawn("cmd.exe", ["/d", "/c", launcherPath], {
      detached: true,
      stdio: "ignore",
      windowsHide: true,
    }).unref();
    setTimeout(shutdown, 900);
  }, 450);
}

