function verifyImportedProtectedPersonnelPayloads(inspection) {
  const storage = requireAmuStorage();
  const protectedRows = inspection?.protected || {};
  let verified = 0;
  const onboardingProtectedGroups = [
    [protectedRows.personnelEmploymentEpisodes || [], "personnel-employment-episode"],
    [protectedRows.personnelLifecycleCases || [], "personnel-lifecycle-case"],
    [protectedRows.personnelLifecycleReferenceDates || [], "personnel-lifecycle-reference-dates"],
    [protectedRows.personnelLifecycleCaseEvents || [], "personnel-lifecycle-case-event"],
  ];
  for (const [rows, namespace] of onboardingProtectedGroups) {
    for (const row of rows) {
      if (!row.protected_payload) throw new Error(`missing protected ${namespace} payload`);
      const payload = storage.unprotectRecord(row.protected_payload, {
        namespace,
        recordId: String(row.id || ""),
        field: "payload",
        employeeNumber: String(row.employee_number || ""),
      });
      const parsed = JSON.parse(payload);
      if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
        throw new Error(`invalid protected ${namespace} payload`);
      }
      verified += 1;
    }
  }
  for (const profile of protectedRows.personnelProfiles || []) {
    if (!profile.protected_payload) throw new Error("missing protected personnel profile payload");
    const payload = storage.unprotectRecord(
      profile.protected_payload,
      personnelSensitiveProtectionContext(profile),
      { allowLegacy: true },
    );
    const parsed = JSON.parse(payload);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("invalid protected personnel profile payload");
    if (parsed.privateEmail && !normalizePersonalEmailAddress(parsed.privateEmail)) {
      throw new Error("invalid protected personnel profile email address");
    }
    verified += 1;
  }
  const importedPersonnelDocumentVersions = protectedRows.personnelDocumentVersions || [];
  const versionedPersonnelDocumentIds = new Set(importedPersonnelDocumentVersions.map((document) => (
    String(document.id || document.document_id || "")
  )));
  const importedPersonnelDocumentPayloads = [
    ...(protectedRows.personnelDocuments || []).filter((document) => (
      !versionedPersonnelDocumentIds.has(String(document.id || ""))
    )),
    ...importedPersonnelDocumentVersions,
  ];
  for (const documentRow of importedPersonnelDocumentPayloads) {
    const document = {
      ...documentRow,
      id: documentRow.id || documentRow.document_id,
    };
    if (!document.protected_payload) throw new Error("missing protected personnel document payload");
    const payload = storage.unprotectRecord(
      document.protected_payload,
      personnelRecordDocumentProtectionContext(document),
      { allowLegacy: true },
    );
    const parsed = JSON.parse(payload);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("invalid protected personnel document payload");
    verified += 1;
  }
  const candidateProtectedGroups = [
    [protectedRows.candidates || [], candidateProtectionContext, "candidate"],
    [protectedRows.candidateApplications || [], candidateApplicationProtectionContext, "candidate application"],
    [protectedRows.candidateConversions || [], candidateConversionProtectionContext, "candidate conversion"],
    [protectedRows.candidateDocuments || [], candidateDocumentProtectionContext, "candidate document"],
    [protectedRows.candidateDocumentVersions || [], candidateDocumentVersionProtectionContext, "candidate document version"],
    [protectedRows.candidateEvents || [], candidateEventProtectionContext, "candidate event"],
  ];
  for (const [rows, contextFor, label] of candidateProtectedGroups) {
    for (const row of rows) {
      if (!row.protected_payload) throw new Error(`missing protected ${label} payload`);
      const payload = storage.unprotectRecord(row.protected_payload, contextFor(row));
      const parsed = JSON.parse(payload);
      if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
        throw new Error(`invalid protected ${label} payload`);
      }
      verified += 1;
    }
  }
  for (const report of protectedRows.amuReports || []) {
    const payload = storage.unprotectRecord(report.protected_payload, amuReportProtectionContext(report), { allowLegacy: true });
    const parsed = JSON.parse(payload);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("invalid protected report payload");
    verified += 1;
  }
  for (const alert of protectedRows.sicknessAlerts || []) {
    if (!alert.protected_payload) throw new Error("missing protected sickness alert payload");
    const payload = storage.unprotectRecord(alert.protected_payload, sicknessAlertProtectionContext(alert), { allowLegacy: true });
    const parsed = JSON.parse(payload);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("invalid protected sickness alert payload");
    verified += 1;
  }
  for (const report of protectedRows.legacyAmuNotes || []) {
    for (const value of [report.employee_note, report.review_note]) {
      if (!String(value || "").startsWith("enc:v1:")) continue;
      storage.unprotectText(value);
      verified += 1;
    }
  }
  for (const document of protectedRows.amuDocuments || []) {
    const payload = storage.unprotectRecord(document.protected_payload, amuDocumentProtectionContext(document), { allowLegacy: true });
    const parsed = JSON.parse(payload);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("invalid protected document payload");
    verified += 1;
  }
  for (const document of protectedRows.legacyAmuDocumentNames || []) {
    storage.unprotectText(document.original_filename);
    verified += 1;
  }
  for (const sicknessCase of protectedRows.sicknessCases || []) {
    if (!sicknessCase.protected_payload) throw new Error("missing protected sickness case payload");
    const payload = storage.unprotectRecord(
      sicknessCase.protected_payload,
      sicknessCaseProtectionContext(sicknessCase),
      { allowLegacy: true },
    );
    const parsed = JSON.parse(payload);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("invalid protected sickness case payload");
    verified += 1;
  }
  for (const job of protectedRows.outboundNotificationJobs || []) {
    if (!job.protected_payload) throw new Error("missing protected outbound notification payload");
    const payload = storage.unprotectRecord(
      job.protected_payload,
      outboundNotificationProtectionContext(job),
      { allowLegacy: true },
    );
    const parsed = JSON.parse(payload);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)
      || Object.hasOwn(parsed, "destination")) {
      throw new Error("invalid protected outbound notification payload");
    }
    verified += 1;
  }
  return verified;
}

async function verifyImportedPersonnelLifecycleState(importPath) {
  let importedDatabase = null;
  let importedProvider = null;
  try {
    importedDatabase = openSqliteLegacyDatabase(importPath, {
      readOnly: true,
      initializeConnection: false,
    });
    const schema = inspectSqlitePersonnelLifecycleSchema(importedDatabase);
    const conversionSchema = inspectSqlitePersonnelLifecycleConversionSchema(importedDatabase);
    if (schema.absent) {
      if (!conversionSchema.absent) {
        throw new Error("personnel lifecycle conversion schema without foundation");
      }
      return Object.freeze({ present: false });
    }
    if (!schema.valid) {
      throw new Error("invalid personnel lifecycle schema");
    }
    if (!conversionSchema.absent && !conversionSchema.valid) {
      throw new Error("invalid personnel lifecycle conversion schema");
    }

    if (!inspectSqliteImportForeignKeyIntegrity(importedDatabase).valid) {
      throw new Error("invalid personnel lifecycle foreign keys");
    }

    importedProvider = createSqlitePersistenceProvider({
      database: importedDatabase,
      catalog: SQLITE_APPLICATION_CATALOG,
      closeDatabase: false,
      initializeConnection: false,
    });
    const importedRepository = createPersonnelLifecycleRepository(importedProvider);
    const integrity = await createPersonnelLifecycleService(importedRepository, {
      protectJson,
      parseProtectedJson,
      conversionAvailable: conversionSchema.valid,
    }).verifyIntegrity();
    return Object.freeze({
      present: true,
      conversionSchema: conversionSchema.valid ? "m3" : "m2-compatible",
      ...integrity,
    });
  } finally {
    try {
      await importedProvider?.close();
    } finally {
      try { importedDatabase?.close(); } catch {}
    }
  }
}

async function verifyImportedIntegrationCredentials(connections = []) {
  if (!connections.length) return 0;
  const vault = requireIntegrationSecretVault();
  for (const connection of connections) {
    await vault.useSecret(connection.protected_credentials, integrationCredentialContext(connection), async (buffer) => {
      const parsed = JSON.parse(buffer.toString("utf8"));
      if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("invalid protected integration credential");
    });
  }
  return connections.length;
}

app.post("/api/backup/import", express.raw({ type: "application/octet-stream", limit: "200mb" }), async (request, response) => {
  if (getPortalStatus().portalEnabled && !["developer", "it_admin"].includes(request.portalSession?.role)) {
    throw httpError(403, "Datenbankimporte dürfen im geschützten Betrieb nur durch Developer oder IT-Admin ausgeführt werden.", "BACKUP_IMPORT_ROLE_DENIED");
  }
  const {
    amuDocuments: currentAmuDocuments,
    personnelDocuments: currentPersonnelDocuments,
  } = await runtimeRecoveryRepository.protectedDocumentCounts();
  const currentProtectedSnapshot = await protectedSicknessStorageForApplication();
  const currentCandidateDocuments = currentProtectedSnapshot.candidateDocuments.length;
  const currentPersonnelDocumentVersions = currentProtectedSnapshot.personnelDocumentVersions.length;
  if (currentAmuDocuments + currentPersonnelDocuments + currentCandidateDocuments
    + currentPersonnelDocumentVersions > 0) {
    throw httpError(409, "Diese Datenbank enthält geschützte Personalakt-Dokumente. Bitte Datenbank und private Dateisicherung gemeinsam über die Wartungswerkzeuge wiederherstellen.", "AMU_FULL_RESTORE_REQUIRED");
  }
  if (serverModeActive) throw httpError(409, "Datenbankimporte sind im laufenden Serverbetrieb gesperrt und müssen in einem Wartungsfenster am Server durchgeführt werden.", "SERVER_MAINTENANCE_REQUIRED");
  if (!Buffer.isBuffer(request.body) || request.body.length < 1024) {
    throw httpError(400, "Bitte eine gültige Backup-Datei auswählen.");
  }
  fs.mkdirSync(dataDirectory, { recursive: true });
  const importPath = path.join(dataDirectory, `pending-import-${backupTimestamp()}.db`);
  fs.writeFileSync(importPath, request.body);
  let importedInspection;
  let importedAmuDocuments = 0;
  let importedPersonnelDocuments = 0;
  let importedPersonnelDocumentVersions = 0;
  let importedCandidateDocuments = 0;
  let importedProtectedPayloadError = false;
  let importedIntegrationCredentialError = false;
  let importedDatabaseReadError = false;
  try {
    importedInspection = inspectSqliteImportFile(importPath);
  } catch {
    importedDatabaseReadError = true;
  }
  if (importedInspection) {
    importedAmuDocuments = importedInspection.amuDocuments;
    importedPersonnelDocuments = importedInspection.personnelDocuments;
    importedPersonnelDocumentVersions = importedInspection.protected
      ?.personnelDocumentVersions?.length || 0;
    importedCandidateDocuments = importedInspection.candidateDocuments;
    importedProtectedPayloadError = importedInspection.protectedInspectionError;
    importedIntegrationCredentialError = importedInspection.integrationInspectionError;
    if (!importedAmuDocuments && !importedPersonnelDocuments
      && !importedPersonnelDocumentVersions && !importedCandidateDocuments) {
      try {
        verifyImportedProtectedPersonnelPayloads(importedInspection);
        await verifyImportedPersonnelLifecycleState(importPath);
      }
      catch { importedProtectedPayloadError = true; }
    }
    try {
      await verifyImportedIntegrationCredentials(importedInspection.integrationConnections);
    } catch {
      importedIntegrationCredentialError = true;
    }
  }
  if (importedDatabaseReadError) {
    fs.rmSync(importPath, { force: true });
    throw httpError(400, "Die ausgewählte Datei ist keine lesbare SQLite-Backup-Datei.");
  }
  if (importedProtectedPayloadError) {
    fs.rmSync(importPath, { force: true });
    throw httpError(409, "Die geschützten Personalakt-Daten dieses Backups gehören zu einem anderen Schlüsselsatz. Bitte die vollständige Datenbank und die zugehörige private Datensicherung gemeinsam wiederherstellen.", "AMU_FULL_RESTORE_REQUIRED");
  }
  if (importedIntegrationCredentialError) {
    fs.rmSync(importPath, { force: true });
    throw httpError(409, "Die geschützten Zugangsdaten direkter Verbindungen gehören zu einem anderen Schlüsselsatz. Bitte die vollständige Serversicherung mit dem zugehörigen Integrationsschlüssel wiederherstellen oder die Verbindungen im Quellsystem entfernen.", "INTEGRATION_FULL_RESTORE_REQUIRED");
  }
  if (importedAmuDocuments + importedPersonnelDocuments + importedPersonnelDocumentVersions
    + importedCandidateDocuments > 0) {
    fs.rmSync(importPath, { force: true });
    throw httpError(409, "Das ausgewählte Backup enthält geschützte Personalakt-Dokumente. Bitte die vollständige Datenbank- und private Dateisicherung gemeinsam wiederherstellen.", "AMU_FULL_RESTORE_REQUIRED");
  }
  const preserveBranding = String(request.query.preserveBranding ?? "1") !== "0";
  if (preserveBranding) {
    applyBrandingSnapshotToDatabase(importPath, await currentBrandingSnapshot());
  }
  const safetyBackup = await createDatabaseBackup("before-import");
  response.status(202).json({
    ok: true,
    message: preserveBranding
      ? "Backup wurde übernommen, aktuelles Branding bleibt erhalten. Grabenplaner wird sicher neu gestartet."
      : "Backup wurde vollständig übernommen. Grabenplaner wird sicher neu gestartet.",
    safetyBackup,
    preserveBranding,
  });
  scheduleBackupImport(importPath);
});

function governanceSource(source) {
  return {
    id: source.id,
    authority: source.authority,
    title: source.title,
    url: source.url,
    jurisdiction: source.jurisdiction,
    reference: source.reference || "",
  };
}

function defaultRetentionRuleInputs() {
  const gdprSource = governanceSource(OFFICIAL_RETENTION_SOURCES.eu_gdpr);
  const azgSource = governanceSource(OFFICIAL_TIME_RECORD_SOURCES[0]);
  const timeRecordRetentionSource = governanceSource(
    OFFICIAL_TIME_RECORD_SOURCES.find(({ id }) => id === "at-usp-arbeitszeitaufzeichnungen")
      || OFFICIAL_TIME_RECORD_SOURCES[0],
  );
  const urlgSource = governanceSource(OFFICIAL_LEAVE_SOURCES.find(({ id }) => id === "at-urlg-8")
    || OFFICIAL_LEAVE_SOURCES[0]);
  const base = {
    schemaVersion: 1,
    validFrom: "2026-01-01",
    validTo: null,
    legalHold: { behavior: "exclude_while_active" },
    disposition: "manual_review",
  };
  return [
    {
      ...base,
      id: "retention-time-records-v1",
      version: "1",
      category: "time_records",
      title: "Arbeitszeitaufzeichnungen – gesetzliches Minimum und manuelle Prüfung",
      status: "active",
      sources: [azgSource, timeRecordRetentionSource, gdprSource],
      startTrigger: "record_closed",
      retention: { value: 1, unit: "years" },
    },
    {
      ...base,
      id: "retention-vacation-records-v1",
      version: "1",
      category: "vacation_records",
      title: "Urlaubsaufzeichnungen – fachlich zu bestätigende Aufbewahrung",
      status: "draft",
      sources: [urlgSource, gdprSource],
      startTrigger: "record_closed",
      retention: { value: 2, unit: "years" },
    },
    {
      ...base,
      id: "retention-sickness-aum-v1",
      version: "1",
      category: "sickness_aum",
      title: "Krankenstands- und AUM-Daten – zweckgebundene manuelle Prüfung",
      status: "draft",
      sources: [gdprSource],
      startTrigger: "case_resolved",
      retention: { value: 2, unit: "years" },
    },
    {
      ...base,
      id: "retention-privacy-requests-v1",
      version: "1",
      category: "privacy_requests",
      title: "Betroffenenanfragen und Bearbeitungsnachweise",
      status: "draft",
      sources: [gdprSource],
      startTrigger: "case_resolved",
      retention: { value: 3, unit: "years" },
    },
  ];
}

function ensureDefaultRetentionRules(actor = "system") {
  return requireGovernanceStore().seedRetentionRules(defaultRetentionRuleInputs(), actor);
}

async function retentionPreviewRecords() {
  const records = [];
  const [
    timeEntries,
    vacationHistory,
    privacyRequests,
    amuReports,
  ] = await Promise.all([
    governanceStoreRepository.retentionTimeEntries(),
    governanceStoreRepository.retentionVacationHistory(),
    governanceStoreRepository.retentionPrivacyRequests(),
    governanceStoreRepository.retentionAmuReports(),
  ]);
  for (const row of timeEntries) {
    records.push({
      id: `time-entry:${row.id}`,
      category: "time_records",
      subjectId: row.employee_number,
      startTrigger: "record_closed",
      startAt: String(row.entry_timestamp || row.created_at).slice(0, 10),
    });
  }
  for (const row of vacationHistory) {
    records.push({
      id: `vacation-history:${row.id}`,
      category: "vacation_records",
      subjectId: row.employee_number,
      startTrigger: "record_closed",
      startAt: String(row.created_at).slice(0, 10),
    });
  }
  for (const row of privacyRequests) {
    records.push({
      id: row.id,
      category: "privacy_requests",
      subjectId: row.employee_number,
      startTrigger: "case_resolved",
      startAt: String(["fulfilled", "partially_fulfilled", "rejected", "withdrawn"].includes(row.status)
        ? row.updated_at
        : row.received_at).slice(0, 10),
    });
  }
  for (const row of amuReports) {
    records.push({
      id: `amu-report:${row.id}`,
      category: "sickness_aum",
      subjectId: row.employee_number,
      startTrigger: "case_resolved",
      startAt: String(["approved", "rejected", "withdrawn", "purged"].includes(row.status)
        ? row.updated_at
        : row.submitted_at).slice(0, 10),
    });
  }
  return records;
}

async function openPrivacyRequestLegalHolds(asOf) {
  const categories = ["time_records", "vacation_records", "sickness_aum", "privacy_requests"];
  const rows = await governanceStoreRepository.openPrivacyRequests();
  return rows.flatMap((row) => categories.map((category) => ({
    id: `open-request-hold:${row.id}:${category}`,
    status: "active",
    recordId: "",
    subjectId: row.employee_number,
    category,
    validFrom: String(row.received_at).slice(0, 10),
    validTo: null,
    reasonCode: "open_data_subject_request",
  }))).filter((hold) => hold.validFrom <= asOf);
}

function privacyRequestTypeCatalog() {
  return PRIVACY_REQUEST_TYPES.map((id) => ({ id, label: PRIVACY_TYPE_LABELS[id] || id }));
}

function privacyRequestScope(type, input) {
  const supplied = Array.isArray(input) ? input.map((item) => String(item || "").trim()).filter(Boolean) : [];
  if (supplied.length) return supplied;
  if (type === "rectification") return ["personnel_master_data"];
  if (type === "erasure" || type === "restriction") return ["all_personal_data"];
  if (type === "objection") return ["processing_scope"];
  return ["personnel_master_data", "time_records", "vacation_records", "sickness_metadata"];
}

async function privacyRequestExportBundle(state) {
  if (!state || state.identity?.status !== "verified"
    || !["approved", "partially_approved", "fulfilled", "partially_fulfilled"].includes(state.status)) {
    throw httpError(409, "Eine Datenauskunft setzt bestätigte Identität und eine dokumentierte Freigabe voraus.",
      "PRIVACY_EXPORT_NOT_APPROVED");
  }
  const scope = new Set(state.decision?.approvedScope || []);
  const employeeNumber = state.subjectId;
  const bundle = {
    schemaVersion: 1,
    generatedAt: new Date().toISOString(),
    requestId: state.id,
    subjectId: employeeNumber,
    scope: [...scope],
    notice: "Maschinenlesbare, auf die dokumentiert freigegebenen Kategorien begrenzte Auskunft. Keine automatische rechtliche Entscheidung.",
    data: {},
  };
  if (scope.has("personnel_master_data") || scope.has("all_personal_data")) {
    const [employee, sensitive, personalNotificationContact] = await Promise.all([
      governanceStoreRepository.privacyExportEmployee(employeeNumber),
      personnelSensitiveProfile(employeeNumber),
      personalNotificationPrivacyExport(employeeNumber),
    ]);
    bundle.data.personnelMasterData = employee ? {
      ...employee,
      sensitiveProfile: {
        identity: sensitive.identity,
        socialSecurityNumber: sensitive.socialSecurityNumber,
        iban: sensitive.iban,
        bic: sensitive.bic,
        accountHolder: sensitive.accountHolder,
        address: sensitive.address,
        phone: sensitive.phone,
        alternatePhone: sensitive.alternatePhone,
        privateEmail: sensitive.privateEmail,
        employment: sensitive.employment,
      },
      personalNotificationContact,
    } : null;
  }
  if (scope.has("all_personal_data")) {
    bundle.data.portalBirthdayPresentationClaims = (
      await portalBirthdayPresentationsRepository.listClaimsForEmployee(employeeNumber)
    ).map((claim) => ({
      eventYear: Number(claim.eventYear),
      presentationId: String(claim.presentationId || ""),
    }));
  }
  if (scope.has("time_records") || scope.has("all_personal_data")) {
    [
      bundle.data.timeRecords,
      bundle.data.timeCorrections,
    ] = await Promise.all([
      governanceStoreRepository.privacyExportTimeEntries(employeeNumber),
      governanceStoreRepository.privacyExportTimeCorrections(employeeNumber),
    ]);
  }
  if (scope.has("vacation_records") || scope.has("all_personal_data")) {
    const [entitlements, history] = await Promise.all([
      governanceStoreRepository.privacyExportVacationEntitlements(employeeNumber),
      governanceStoreRepository.privacyExportVacationHistory(employeeNumber),
    ]);
    bundle.data.vacationEntitlements = entitlements;
    bundle.data.vacationHistory = history.map((row) => ({
      group_id: row.group_id,
      action: row.action,
      snapshot: parseVacationHistorySnapshot(row),
      receipt_sha256: row.receipt_sha256,
      created_at: row.created_at,
    }));
  }
  if (scope.has("sickness_metadata") || scope.has("all_personal_data")) {
    bundle.data.sicknessMetadata = await governanceStoreRepository
      .privacyExportSicknessMetadata(employeeNumber);
  }
  return bundle;
}

async function recordPrivacyExportReceipt(state, bundle, actor) {
  const content = Buffer.from(JSON.stringify(bundle, null, 2), "utf8");
  const contentSha256 = crypto.createHash("sha256").update(content).digest("hex");
  const id = `privacy-export:${crypto.randomUUID()}`;
  const expiresAt = new Date(Date.now() + 15 * 60 * 1000).toISOString();
  await governanceStoreRepository.insertPrivacyExportReceipt({
    id,
    requestId: state.id,
    employeeNumber: state.subjectId,
    contentSha256,
    categoriesJson: JSON.stringify(bundle.scope),
    expiresAt,
    createdBy: actor,
    createdAt: bundle.generatedAt,
    downloadedAt: bundle.generatedAt,
  });
  (await auditPortal(actor, "privacy-request.export", "privacy_request", state.id,
    JSON.stringify({ exportId: id, contentSha256, categories: bundle.scope })));
  return { id, content };
}

async function sessionCanAccessEmployee(session, employeeNumber) {
  if (session?.employeeNumber && String(session.employeeNumber) === String(employeeNumber)) return true;
  try {
    await assertSessionEmployeeScope(session, employeeNumber);
    return true;
  } catch (error) {
    if (Number(error?.status) === 403) return false;
    throw error;
  }
}

async function vacationAccountsForYear(year, actor = "system", employeeNumber = "", session = null) {
  const plan = await getCentralVacationPlan(year, { includeInactive: 1 });
  const accounts = [];
  for (const employee of plan.employees) {
    if (employeeNumber && employee.personnel_number !== employeeNumber) continue;
    if (!await sessionCanAccessEmployee(session, employee.personnel_number)) continue;
    if (!plan.entitlementsSaved?.[employee.personnel_number]) continue;
    const row = await requireGovernanceStore()
      .vacationAccountRow(employee.personnel_number, year);
    if (!row) continue;
    accounts.push(requireGovernanceStore().vacationSummary(row, {
      consumedDays: Number(plan.totals?.[employee.personnel_number]?.consumed || 0),
      plannedDays: Number(plan.totals?.[employee.personnel_number]?.planned || 0),
    }));
  }
  return accounts;
}

async function backfillVacationAccountsFromEntitlements(actor = "system") {
  const entitlements = await governanceStoreRepository.vacationEntitlementsForBackfill();
  const store = requireGovernanceStore();
  const accounts = [];
  for (const entitlement of entitlements) {
    let employmentStart = "";
    try {
      employmentStart = (await personnelSensitiveProfile(entitlement.employee_number)).employment?.startDate || "";
    } catch {}
    accounts.push(await store.ensureVacationAccount({
      employeeNumber: entitlement.employee_number,
      year: Number(entitlement.year),
      totalDays: Number(entitlement.days || 0),
      consumedDays: 0,
      plannedDays: 0,
      weeklyWorkdays: Number(entitlement.target_workdays_per_week || 5),
      employmentStart,
      actor,
    }));
  }
  return accounts;
}

function timeEntriesForStatement(employeeNumber, month) {
  if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)) {
    throw httpError(400, "Bitte einen gültigen Monat im Format YYYY-MM auswählen.", "TIME_RECORD_MONTH_INVALID");
  }
  return governanceStoreRepository.timeEntriesForStatement({
    employeeNumber,
    periodStart: `${month}-01`,
    periodEnd: monthEnd(Number(month.slice(0, 4)), Number(month.slice(5, 7)) - 1),
  });
}

function drawTimeRecordStatementPdf(response, statementRow, employee) {
  const statement = statementRow.statement;
  const doc = new PDFDocument({ size: "A4", margin: 42, info: {
    Title: `Arbeitszeitnachweis ${statement.month}`,
    Author: APP_NAME,
  } });
  response.type("application/pdf");
  response.setHeader("Cache-Control", "private, no-store");
  response.setHeader("Content-Disposition",
    `attachment; filename="Arbeitszeitnachweis-${statement.employeeId}-${statement.month}.pdf"`);
  doc.pipe(response);
  doc.font("Helvetica-Bold").fontSize(18).text("Monatlicher Arbeitszeitnachweis");
  doc.moveDown(0.4).font("Helvetica").fontSize(10)
    .text(`${employee?.full_name || statement.employeeId} · Personalnummer ${statement.employeeId} · ${statement.month}`);
  doc.moveDown(0.3).fillColor("#52606d")
    .text("Ausschließlich tatsächliche Zeitbuchungen; Dienstplanwerte werden nicht als Ist-Zeit verwendet.");
  doc.moveDown().fillColor("#111827");
  for (const day of statement.days) {
    if (doc.y > 730) doc.addPage();
    doc.font("Helvetica-Bold").fontSize(10).text(day.workDate, { continued: true, width: 90 });
    doc.font("Helvetica").text(
      `  ${day.beginningAt ? new Date(day.beginningAt).toLocaleTimeString("de-AT", { hour: "2-digit", minute: "2-digit", timeZone: "Europe/Vienna" }) : "–"}`
      + ` – ${day.endingAt ? new Date(day.endingAt).toLocaleTimeString("de-AT", { hour: "2-digit", minute: "2-digit", timeZone: "Europe/Vienna" }) : "offen"}`
      + ` · Pause ${day.breakMinutes} min · Ist ${Math.floor(day.actualMinutes / 60)}:${String(day.actualMinutes % 60).padStart(2, "0")} h`,
    );
  }
  doc.moveDown().font("Helvetica-Bold")
    .text(`Summe Ist: ${Math.floor(statement.totals.actualMinutes / 60)}:${String(statement.totals.actualMinutes % 60).padStart(2, "0")} h`);
  doc.font("Helvetica").fontSize(8).fillColor("#52606d")
    .text(`Revision ${statement.revision} · Beleg ${statement.receiptSha256}`);
  doc.end();
}

function governanceRouteError(error, fallbackStatus = 400) {
  if (Number.isInteger(error?.status)) throw error;
  throw httpError(fallbackStatus, error?.message || "Die Governance-Aktion konnte nicht ausgeführt werden.",
    error?.code || "GOVERNANCE_ACTION_FAILED");
}

