app.post("/api/time-record-statements/generate", async (request, response) => {
  const actor = requirePortalAdminOrLocal(request, "time_records:generate");
  const month = String(request.body?.month || viennaTodayIso().slice(0, 7));
  const selected = Array.isArray(request.body?.employeeNumbers)
    ? new Set(request.body.employeeNumbers.map((value) => String(value)))
    : null;
  const employees = [];
  for (const employee of await organizationPersonnelRepository.listEmployees()) {
    if (!employee.active || (selected && !selected.has(employee.personnel_number))) continue;
    if (await sessionCanAccessEmployee(actor, employee.personnel_number)) employees.push(employee);
  }
  const statements = [];
  const errors = [];
  for (const employee of employees) {
    try {
      statements.push(await requireGovernanceStore().generateTimeStatement({
        employeeNumber: employee.personnel_number,
        month,
        entries: await timeEntriesForStatement(employee.personnel_number, month),
        actor: actor.employeeNumber,
      }));
    } catch (error) {
      errors.push({
        employeeNumber: employee.personnel_number,
        code: error?.code || "TIME_RECORD_GENERATION_FAILED",
        message: error?.message || "Nachweis konnte nicht erzeugt werden.",
      });
    }
  }
  (await auditPortal(actor.employeeNumber, "time-record-statements.generate", "time_record_statement", month,
    JSON.stringify({ generated: statements.length, errors: errors.length })));
  response.status(errors.length && !statements.length ? 422 : 201).json({ month, statements, errors });
});

