async function customWorkRuleDraftVisibleToSession(session, draft) {
  if (sessionHasGlobalScope(session)) return draft;
  const currentVersionId = String(draft?.currentVersionId || "");
  const currentScopes = currentVersionId
    ? await workRuleGovernanceVersionScopes(currentVersionId)
    : [];
  if (!currentScopes.length || !currentScopes.every((scope) => (
    workRuleGovernanceScopeVisible(session, scope)
  ))) return null;
  const visibleVersions = await Promise.all((draft.versions || []).map(async (version) => {
    const scopes = await workRuleGovernanceVersionScopes(version.id);
    return scopes.length && scopes.every((scope) => (
      workRuleGovernanceScopeVisible(session, scope)
    )) ? version : null;
  }));
  const versions = visibleVersions.filter(Boolean);
  const visibleVersionIds = new Set(versions.map((version) => version.id));
  const currentVersion = versions.find((version) => version.id === currentVersionId) || null;
  if (!currentVersion) return null;
  return {
    ...draft,
    title: currentVersion.definition.title,
    description: currentVersion.definition.description,
    status: currentVersion.status,
    currentVersionId: currentVersion.id,
    currentVersion,
    effectiveVersionId: visibleVersionIds.has(draft.effectiveVersionId) ? draft.effectiveVersionId : null,
    publishedVersion: visibleVersionIds.has(draft.publishedVersion?.id) ? draft.publishedVersion : null,
    hasUnreleasedDraft: currentVersion.versionKind === "draft" && !currentVersion.releasedAsVersionId,
    lifecycleStatus: currentVersion.status === "published" ? "published" : "draft",
    createdBy: currentVersion.createdBy,
    updatedBy: currentVersion.createdBy,
    createdAt: currentVersion.createdAt,
    updatedAt: currentVersion.createdAt,
    versions,
  };
}

async function customWorkRuleDraftRegistryPayload(session) {
  const canAudit = !session || isLocalSystemSession(session)
    || session.permissions?.includes("work_rules:audit");
  const drafts = (await Promise.all((await listCustomWorkRuleDrafts(customWorkRulesRepository))
    .map((draft) => customWorkRuleDraftVisibleToSession(session, draft))))
    .filter(Boolean)
    .map((draft) => (canAudit ? draft : redactWorkRuleGovernanceAuditFields(draft)));
  const governance = await workRuleGovernancePayload(session);
  const globalScope = sessionHasGlobalScope(session);
  const sessionScopes = Array.isArray(session?.scopes) ? session.scopes : [];
  const locations = portalScopeProjectionSnapshot.locations
    .filter((location) => location.active)
    .sort((left, right) => String(left.name).localeCompare(String(right.name), "de")
      || String(left.id).localeCompare(String(right.id)))
    .filter((location) => globalScope || sessionScopes.some((scope) => (
    String(scope.locationId || "") === String(location.id)
  ))).map((location) => ({
    id: String(location.id),
    name: location.name,
    departments: portalScopeProjectionSnapshot.departments
      .filter((department) => department.active
        && String(department.location_id) === String(location.id))
      .sort((left, right) => String(left.name).localeCompare(String(right.name), "de")
        || Number(left.id) - Number(right.id))
      .filter((department) => globalScope || sessionScopes.some((scope) => (
      String(scope.locationId || "") === String(location.id)
      && (!Number(scope.departmentId || 0) || Number(scope.departmentId) === Number(department.id))
    ))).map((department) => ({
      id: String(department.id),
      name: department.name,
    })),
  }));
  const visibleBusinessUnitScope = collectiveAgreementBusinessUnitScopeMatcher(session);
  const businessUnits = (await listBusinessUnits(collectiveAgreementsRepository)).filter((unit) => (
    globalScope || unit.scopes.some(visibleBusinessUnitScope)
  )).map((unit) => ({
    id: unit.id,
    code: unit.code,
    name: unit.name,
    legalEntityName: unit.legalEntityName,
  }));
  const canDraft = !session || isLocalSystemSession(session)
    || session.permissions?.includes("work_rules:draft");
  const humanActor = Boolean(session && !isLocalSystemSession(session));
  const canReview = Boolean(humanActor && session.permissions?.includes("work_rules:review"));
  const canPublish = Boolean(humanActor && session.permissions?.includes("work_rules:publish"));
  const canAssign = Boolean(humanActor && session.permissions?.includes("work_rules:assign"));
  const requests = Array.isArray(governance.requests) ? governance.requests : [];
  return {
    generatedAt: new Date().toISOString(),
    notice: CUSTOM_WORK_RULE_NOTICE,
    capabilities: {
      canDraft,
      canRevise: canDraft,
      canSubmitForReview: humanActor && canDraft,
      canReview,
      canApprove: canReview,
      canPublish,
      canAssign,
      canActivate: canAssign,
      canDeactivate: canAssign || canPublish,
      canAudit,
      approvalBlock: null,
    },
    summary: {
      drafts: drafts.length,
      revisions: drafts.reduce((sum, draft) => sum + draft.versions.length, 0),
      pendingReview: requests.filter((entry) => ["in_review", "approved"].includes(entry.state)).length,
      active: Array.isArray(governance.assignments)
        ? governance.assignments.filter((entry) => entry.state === "active").length
        : 0,
      published: Array.isArray(governance.publications)
        ? governance.publications.filter((entry) => entry.state === "published").length
        : 0,
      intendedBlocking: drafts.filter((draft) => draft.currentVersion?.definition?.reaction === "block").length,
    },
    catalogs: {
      ruleTypes: CUSTOM_WORK_RULE_TYPES,
      topics: CUSTOM_WORK_RULE_TOPICS,
      scopes: CUSTOM_WORK_RULE_SCOPES,
      metrics: CUSTOM_WORK_RULE_METRICS,
      reactions: CUSTOM_WORK_RULE_REACTIONS,
      severities: CUSTOM_WORK_RULE_SEVERITIES,
    },
    organizationalScopes: {
      businessUnits,
      locations,
    },
    drafts,
  };
}

