app.post("/api/work-rules/evaluate", async (request, response) => {
  if (request.body.targetType && request.body.targetType !== "planned_schedule") {
    throw httpError(400, "Diese Prüfung bewertet ausschließlich geplante Dienste, keine Ist-Zeiterfassung.");
  }
  const weekStart = getMonday(isIsoDate(request.body.weekStart) ? request.body.weekStart : request.body?.shift?.date);
  const context = await resolvePlanningContext(request.body);
  assertSessionContextScope(request.portalSession, context);
  const schedule = await getSchedule(weekStart, context, request.portalSession);
  const submittedValue = request.body.shift ?? request.body.candidateShift;
  const submitted = submittedValue && typeof submittedValue === "object" ? submittedValue : null;
  let candidate = null;
  if (submitted) {
    const id = Number(submitted.id || 0);
    const existing = id
      ? await planningSettingsRepository.getShiftById({ id })
      : null;
    if (id && !existing) throw httpError(404, "Der bestehende Dienst wurde nicht gefunden.");
    if (existing) {
      assertSessionContextScope(request.portalSession, {
        locationId: existing.location_id,
        departmentId: existing.department_id,
      });
    }
    candidate = await validateShift({
      ...submitted,
      locationId: submitted.locationId ?? context.locationId,
      departmentId: Object.hasOwn(submitted, "departmentId") ? submitted.departmentId
        : Object.hasOwn(submitted, "department_id") ? submitted.department_id
          : existing?.department_id ?? context.departmentId,
    }, {
      locationId: context.locationId,
      existingId: id,
      existingShift: existing,
    }, request.portalSession);
    if (id) candidate.id = id;
    assertSessionContextScope(request.portalSession, { locationId: candidate.locationId, departmentId: candidate.departmentId });
    await assertShiftEmployeeAssignmentScope(request.portalSession, candidate, existing);
  }
  const evaluated = await evaluateScheduleWorkRules(
    weekStart,
    context,
    schedule.employees,
    candidate,
  );
  response.json({
    ...evaluated.assessment,
    candidate: candidate ? {
      employeeNumber: candidate.employeeNumber,
      date: candidate.shiftDate,
      startTime: candidate.startTime,
      endTime: candidate.endTime,
    } : null,
  });
});

