app.put("/api/portal/v1/trust-level-settings", async (request, response) => {
  const actor = requireAdminHrOrLocal(request, "wifi:settings");
  const policy = validateTrustLevelPolicy(request.body || {});
  const levels = request.body?.levels === undefined ? [] : await validateWifiConfirmationLevels(request.body || {});
  const values = {
    trust_levels_enabled: policy.enabled ? "1" : "0",
    trust_levels_visible_to_managers: policy.visibleToManagers ? "1" : "0",
    trust_levels_visible_to_department_managers: policy.visibleToDepartmentManagers ? "1" : "0",
    trust_levels_visible_to_employees: policy.visibleToEmployees ? "1" : "0",
  };
  const changed = await wifiAutomationRepository.transaction(async (repository) => {
    const updated = [];
    for (const [key, value] of Object.entries(values)) {
      await repository.upsertPortalSetting({ key, value });
    }
    for (const item of levels) {
      const current = await repository.getEmployeeConfirmationLevel({
        employeeNumber: item.employeeNumber,
        activeOnly: 0,
      });
      const before = normalizeTimeConfirmationLevel(current?.time_confirmation_level);
      if (before === item.level) continue;
      await repository.updateEmployeeConfirmationLevel(item);
      updated.push({ ...item, before });
    }
    return updated;
  });
  await refreshPortalSettingsSnapshot();
  await auditPortal(actor.employeeNumber, "trust_levels.settings.update", "portal_settings", "trust_levels", JSON.stringify(policy));
  for (const item of changed) {
    await auditPortal(actor.employeeNumber, "employee.time_confirmation_level.update", "employee", item.employeeNumber,
      JSON.stringify({ before: item.before, after: item.level }));
  }
  response.json({
    ...getTrustLevelPolicy(),
    changed: changed.length,
    canChange: true,
    employees: await wifiConfirmationLevels(),
  });
});

