const CANDIDATE_EVALUATION_PDF_PREFERENCE_KEY = "candidate_evaluation_pdf_v1";
const CANDIDATE_EVALUATION_PDF_PAGE_MODES = new Set(["single", "two"]);
const CANDIDATE_EVALUATION_PDF_ORIENTATIONS = new Set(["portrait", "landscape"]);
const CANDIDATE_EVALUATION_PDF_DEFAULT_RGB = Object.freeze([35, 95, 77]);
const CANDIDATE_EVALUATION_PDF_PREFERENCE_KEYS = new Set([
  "version",
  "pageMode",
  "orientation",
  "colorRgb",
  "applyBranding",
  "includeLogo",
  "showOverallSummary",
  "showCriteriaRatings",
  "showFlComments",
  "showEmployeeComments",
  "showReviewerNames",
  "showRoleTitle",
  "showGeneratedAt",
  "includeDatePrefix",
  "filenameTemplate",
]);

function defaultCandidateEvaluationPdfPreferences() {
  return {
    version: 1,
    pageMode: "two",
    orientation: "landscape",
    colorRgb: [...CANDIDATE_EVALUATION_PDF_DEFAULT_RGB],
    applyBranding: false,
    includeLogo: false,
    showOverallSummary: true,
    showCriteriaRatings: true,
    showFlComments: true,
    showEmployeeComments: true,
    showReviewerNames: true,
    showRoleTitle: true,
    showGeneratedAt: true,
    includeDatePrefix: true,
    filenameTemplate: "Bewerbungsbewertung {Name}",
  };
}

function normalizedCandidateEvaluationPdfFilenameTemplate(value, fallback) {
  const normalized = String(value ?? "")
    .replace(/[\x00-\x1F\x7F]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 80);
  return normalized || fallback;
}

function normalizeCandidateEvaluationPdfPreferences(value) {
  const fallback = defaultCandidateEvaluationPdfPreferences();
  if (!value || typeof value !== "object" || Array.isArray(value) || Number(value.version) !== 1) {
    return fallback;
  }
  const colorRgb = Array.isArray(value.colorRgb) && value.colorRgb.length === 3
    && value.colorRgb.every((channel) => Number.isInteger(channel) && channel >= 0 && channel <= 255)
    ? value.colorRgb.map(Number)
    : [...fallback.colorRgb];
  const boolean = (key) => typeof value[key] === "boolean" ? value[key] : fallback[key];
  return {
    version: 1,
    pageMode: CANDIDATE_EVALUATION_PDF_PAGE_MODES.has(String(value.pageMode))
      ? String(value.pageMode)
      : fallback.pageMode,
    orientation: CANDIDATE_EVALUATION_PDF_ORIENTATIONS.has(String(value.orientation))
      ? String(value.orientation)
      : fallback.orientation,
    colorRgb,
    applyBranding: boolean("applyBranding"),
    includeLogo: boolean("includeLogo"),
    showOverallSummary: boolean("showOverallSummary"),
    showCriteriaRatings: boolean("showCriteriaRatings"),
    showFlComments: boolean("showFlComments"),
    showEmployeeComments: boolean("showEmployeeComments"),
    showReviewerNames: boolean("showReviewerNames"),
    showRoleTitle: boolean("showRoleTitle"),
    showGeneratedAt: boolean("showGeneratedAt"),
    includeDatePrefix: boolean("includeDatePrefix"),
    filenameTemplate: normalizedCandidateEvaluationPdfFilenameTemplate(
      value.filenameTemplate,
      fallback.filenameTemplate,
    ),
  };
}

function validateCandidateEvaluationPdfPreferences(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)
    || Object.keys(value).some((key) => !CANDIDATE_EVALUATION_PDF_PREFERENCE_KEYS.has(key))
    || value.version !== 1
    || !CANDIDATE_EVALUATION_PDF_PAGE_MODES.has(String(value.pageMode || ""))
    || !CANDIDATE_EVALUATION_PDF_ORIENTATIONS.has(String(value.orientation || ""))
    || !Array.isArray(value.colorRgb) || value.colorRgb.length !== 3
    || value.colorRgb.some((channel) => !Number.isInteger(channel) || channel < 0 || channel > 255)) {
    throw httpError(400, "Bitte gültige persönliche PDF-Exportoptionen übermitteln.", "UI_PREFERENCES_INVALID");
  }
  for (const key of [...CANDIDATE_EVALUATION_PDF_PREFERENCE_KEYS].filter((entry) => (
    !["version", "pageMode", "orientation", "colorRgb", "filenameTemplate"].includes(entry)
  ))) {
    if (typeof value[key] !== "boolean") {
      throw httpError(400, "Bitte gültige persönliche PDF-Exportoptionen übermitteln.", "UI_PREFERENCES_INVALID");
    }
  }
  const filenameTemplate = normalizedCandidateEvaluationPdfFilenameTemplate(value.filenameTemplate, "");
  const unsupportedPlaceholder = /[{}]/.test(
    filenameTemplate.replace(/\{(?:Name|Position)\}/g, ""),
  );
  if (filenameTemplate.length < 3 || filenameTemplate.length > 80
    || unsupportedPlaceholder) {
    throw httpError(400, "Der PDF-Dateiname darf nur die Platzhalter {Name} und {Position} enthalten.", "UI_PREFERENCES_INVALID");
  }
  if (![value.showOverallSummary, value.showCriteriaRatings, value.showFlComments, value.showEmployeeComments]
    .some(Boolean)) {
    throw httpError(400, "Bitte mindestens einen Bewertungsinhalt für die PDF auswählen.", "UI_PREFERENCES_INVALID");
  }
  return normalizeCandidateEvaluationPdfPreferences({ ...value, filenameTemplate });
}

async function candidateEvaluationPdfPreferencesForActor(actor) {
  if (!actor?.employeeNumber || isLocalSystemSession(actor)) {
    return defaultCandidateEvaluationPdfPreferences();
  }
  const stored = await uiPreferencesRepository.get(
    actor.employeeNumber,
    CANDIDATE_EVALUATION_PDF_PREFERENCE_KEY,
  );
  try {
    return normalizeCandidateEvaluationPdfPreferences(JSON.parse(stored?.value || "null"));
  } catch {
    return defaultCandidateEvaluationPdfPreferences();
  }
}

function candidateEvaluationPdfBrandingForActor(actor, application) {
  const desiredLocationId = String(
    application?.desiredLocationId || actor?.homeLocationId || "",
  ).trim();
  if (desiredLocationId) return loanPdfBranding(desiredLocationId);
  const branding = brandingForPortalSession(actor);
  const source = mobileBrandingSourceForSession(actor);
  return {
    companyName: branding.companyName,
    logo: localAssetPathFromUrl(branding.logoUrl),
    colors: mobileBrandingTheme(source.raw),
  };
}

function candidateEvaluationPdfFilename(preferences, candidateName, desiredRoleTitle, generatedAt) {
  const template = String(
    preferences?.filenameTemplate || defaultCandidateEvaluationPdfPreferences().filenameTemplate,
  );
  const substituted = template
    .replaceAll("{Name}", String(candidateName || "Bewerbung"))
    .replaceAll("{Position}", String(desiredRoleTitle || ""))
    .replace(/\.pdf$/i, "");
  const base = sanitizeFilenamePart(substituted) || `Bewerbungsbewertung ${sanitizeFilenamePart(candidateName)}`;
  const isoDate = viennaTodayIso(generatedAt);
  const datePrefix = preferences?.includeDatePrefix
    ? `${isoDate.slice(2).replaceAll("-", "")}_`
    : "";
  return `${datePrefix}${base}.pdf`;
}

function uiPreferenceActor(request, { write = false } = {}) {
  if (!getPortalStatus().portalEnabled && isLoopbackRequest(request)) {
    return {
      employeeNumber: "local",
      role: "admin",
      permissions: [],
      sessionKind: "local",
      localSystem: true,
    };
  }
  const session = requireEmployeePortalSession(request);
  if (write) assertPortalCsrf(request);
  return session;
}

async function uiPreferencesForActor(actor, overrides = {}) {
  const pageThemes = Object.fromEntries(UI_PREFERENCE_VIEWS.map((view) => [view, "light"]));
  let appFontScalePercent = APP_FONT_SCALE_DEFAULT;
  let employeeDisplayColumns = [...UI_DEFAULT_EMPLOYEE_DISPLAY_COLUMNS];
  let employeeDisplaySort = { key: "personnel_number", direction: "asc" };
  let workRuleAssessmentExpanded = false;
  let allowPastWeekEditing = isLocalSystemSession(actor)
    ? settingEnabled(getSettings(), "allow_past_week_editing")
    : false;
  let vacationCalendarView = defaultVacationCalendarView();
  let personnelDashboardLayout = defaultPersonnelDashboardLayout();
  let startDashboardPreferences = defaultStartDashboardPreferences();
  let mobilePortalNavigation = defaultMobilePortalNavigation();
  let mobilePortalAppearance = defaultMobilePortalAppearance();
  let mobilePortalHome = defaultMobilePortalHome();
  let candidateEvaluationPdfPreferences = defaultCandidateEvaluationPdfPreferences();
  let mobilePortalNavigationCustomized = false;
  let mobilePortalAppearanceCustomized = false;
  let mobilePortalHomeCustomized = false;
  if (actor?.employeeNumber && !isLocalSystemSession(actor)) {
    const rows = await uiPreferencesRepository.list(actor.employeeNumber);
    const lookup = new Map(rows.map((row) => [row.preferenceKey, row.value]));
    for (const view of UI_PREFERENCE_VIEWS) {
      const stored = lookup.get(`page_theme_${view}`)
        || (view === "rightsDashboard" ? lookup.get("rights_dashboard_theme") : "");
      if (UI_PAGE_THEMES.has(stored)) pageThemes[view] = stored;
    }
    const storedFontScale = normalizeAppFontScalePercent(lookup.get("app_font_scale_percent"), null)
      ?? normalizeAppFontScalePercent(lookup.get("dashboard_font_size"), null);
    if (storedFontScale !== null) appFontScalePercent = storedFontScale;
    try {
      const storedColumns = JSON.parse(lookup.get("employee_display_columns") || "null");
      if (Array.isArray(storedColumns) && storedColumns.length && storedColumns.every((column) => UI_EMPLOYEE_DISPLAY_COLUMNS.has(String(column)))) {
        employeeDisplayColumns = [...new Set(storedColumns.map(String))];
      }
    } catch {}
    try {
      const storedSort = JSON.parse(lookup.get("employee_display_sort") || "null");
      if (storedSort && UI_EMPLOYEE_DISPLAY_COLUMNS.has(String(storedSort.key)) && ["asc", "desc"].includes(storedSort.direction)) {
        employeeDisplaySort = { key: String(storedSort.key), direction: storedSort.direction };
      }
    } catch {}
    workRuleAssessmentExpanded = lookup.get("work_rule_assessment_expanded") === "1";
    allowPastWeekEditing = Boolean(actor.permissions?.includes("schedule:write")
      && actor.permissions?.includes("settings:write")
      && lookup.get("allow_past_week_editing") === "1");
    try {
      vacationCalendarView = normalizeVacationCalendarView(
        JSON.parse(lookup.get("vacation_calendar_view_v1") || "null"),
      );
    } catch {}
    try {
      personnelDashboardLayout = normalizePersonnelDashboardLayout(
        JSON.parse(lookup.get("personnel_dashboard_layout_v1") || "null"),
      );
    } catch {}
    try {
      startDashboardPreferences = normalizeStartDashboardPreferences(
        JSON.parse(lookup.get("start_dashboard_preferences_v3") || lookup.get("start_dashboard_preferences_v2") || lookup.get("start_dashboard_preferences_v1") || "null"),
      );
    } catch {}
    try {
      mobilePortalNavigation = normalizeMobilePortalNavigation(
        JSON.parse(lookup.get("mobile_portal_navigation_v1") || "null"),
      );
      mobilePortalNavigationCustomized = lookup.has("mobile_portal_navigation_v1");
    } catch {}
    try {
      mobilePortalAppearance = normalizeMobilePortalAppearance(
        JSON.parse(lookup.get("mobile_portal_appearance_v1") || "null"),
      );
      mobilePortalAppearanceCustomized = lookup.has("mobile_portal_appearance_v1");
    } catch {}
    try {
      mobilePortalHome = normalizeMobilePortalHome(
        JSON.parse(lookup.get("mobile_portal_home_v1") || "null"),
      );
      mobilePortalHomeCustomized = lookup.has("mobile_portal_home_v1");
    } catch {}
    try {
      candidateEvaluationPdfPreferences = normalizeCandidateEvaluationPdfPreferences(
        JSON.parse(lookup.get(CANDIDATE_EVALUATION_PDF_PREFERENCE_KEY) || "null"),
      );
    } catch {}
  }
  for (const [view, theme] of Object.entries(overrides.pageThemes || {})) {
    if (UI_PREFERENCE_VIEWS.includes(view) && UI_PAGE_THEMES.has(theme)) pageThemes[view] = theme;
  }
  const overriddenFontScale = normalizeAppFontScalePercent(overrides.appFontScalePercent, null);
  if (overriddenFontScale !== null) appFontScalePercent = overriddenFontScale;
  if (Array.isArray(overrides.employeeDisplayColumns)) employeeDisplayColumns = [...overrides.employeeDisplayColumns];
  if (overrides.employeeDisplaySort) employeeDisplaySort = { ...overrides.employeeDisplaySort };
  if (typeof overrides.workRuleAssessmentExpanded === "boolean") {
    workRuleAssessmentExpanded = overrides.workRuleAssessmentExpanded;
  }
  if (typeof overrides.allowPastWeekEditing === "boolean") {
    allowPastWeekEditing = overrides.allowPastWeekEditing;
  }
  if (overrides.vacationCalendarView) {
    vacationCalendarView = normalizeVacationCalendarView(overrides.vacationCalendarView);
  }
  if (overrides.personnelDashboardLayout) {
    personnelDashboardLayout = normalizePersonnelDashboardLayout(overrides.personnelDashboardLayout);
  }
  if (overrides.startDashboardPreferences) {
    startDashboardPreferences = normalizeStartDashboardPreferences(overrides.startDashboardPreferences);
  }
  if (overrides.mobilePortalNavigation) {
    mobilePortalNavigation = normalizeMobilePortalNavigation(overrides.mobilePortalNavigation);
    mobilePortalNavigationCustomized = true;
  }
  if (overrides.mobilePortalAppearance) {
    mobilePortalAppearance = normalizeMobilePortalAppearance(overrides.mobilePortalAppearance);
    mobilePortalAppearanceCustomized = true;
  }
  if (overrides.mobilePortalHome) {
    mobilePortalHome = normalizeMobilePortalHome(overrides.mobilePortalHome);
    mobilePortalHomeCustomized = true;
  }
  if (overrides.candidateEvaluationPdfPreferences) {
    candidateEvaluationPdfPreferences = normalizeCandidateEvaluationPdfPreferences(
      overrides.candidateEvaluationPdfPreferences,
    );
  }
  return {
    actor: actor?.employeeNumber || "local",
    pageThemes,
    appFontScalePercent,
    employeeDisplayColumns,
    employeeDisplaySort,
    workRuleAssessmentExpanded,
    allowPastWeekEditing,
    vacationCalendarView,
    personnelDashboardLayout,
    startDashboardPreferences,
    mobilePortalNavigation,
    mobilePortalAppearance,
    mobilePortalHome,
    candidateEvaluationPdfPreferences,
    mobilePortalLocationDisplay: mobilePortalLocationDisplayForSession(actor),
    mobilePortalNavigationCustomized,
    mobilePortalAppearanceCustomized,
    mobilePortalHomeCustomized,
  };
}

async function saveUiPreferencesForActor(actor, input = {}) {
  const submittedThemes = input.pageThemes === undefined ? {} : input.pageThemes;
  if (!submittedThemes || typeof submittedThemes !== "object" || Array.isArray(submittedThemes)) {
    throw httpError(400, "Bitte gültige Seitendarstellungen übermitteln.", "UI_PREFERENCES_INVALID");
  }
  const pageThemes = {};
  for (const [view, theme] of Object.entries(submittedThemes)) {
    if (!UI_PREFERENCE_VIEWS.includes(view) || !UI_PAGE_THEMES.has(theme)) {
      throw httpError(400, "Bitte gültige Seitendarstellungen übermitteln.", "UI_PREFERENCES_INVALID");
    }
    pageThemes[view] = theme;
  }
  const appFontScalePercent = input.appFontScalePercent === undefined ? undefined : input.appFontScalePercent;
  if (appFontScalePercent !== undefined && (
    typeof appFontScalePercent !== "number"
    || normalizeAppFontScalePercent(appFontScalePercent, null) !== appFontScalePercent
  )) {
    throw httpError(
      400,
      `Bitte eine gültige Schriftgröße zwischen ${APP_FONT_SCALE_MIN} und ${APP_FONT_SCALE_MAX} Prozent in ${APP_FONT_SCALE_STEP}er-Schritten angeben.`,
      "UI_PREFERENCES_INVALID",
    );
  }
  const employeeDisplayColumns = input.employeeDisplayColumns === undefined ? undefined : input.employeeDisplayColumns;
  if (employeeDisplayColumns !== undefined && (!Array.isArray(employeeDisplayColumns) || !employeeDisplayColumns.length
    || employeeDisplayColumns.length > UI_EMPLOYEE_DISPLAY_COLUMNS.size
    || new Set(employeeDisplayColumns.map(String)).size !== employeeDisplayColumns.length
    || employeeDisplayColumns.some((column) => !UI_EMPLOYEE_DISPLAY_COLUMNS.has(String(column))))) {
    throw httpError(400, "Bitte gültige Anzeigespalten übermitteln.", "UI_PREFERENCES_INVALID");
  }
  const employeeDisplaySort = input.employeeDisplaySort === undefined ? undefined : input.employeeDisplaySort;
  if (employeeDisplaySort !== undefined && (!employeeDisplaySort || typeof employeeDisplaySort !== "object" || Array.isArray(employeeDisplaySort)
    || !UI_EMPLOYEE_DISPLAY_COLUMNS.has(String(employeeDisplaySort.key || ""))
    || !["asc", "desc"].includes(String(employeeDisplaySort.direction || "")))) {
    throw httpError(400, "Bitte eine gültige Sortierung übermitteln.", "UI_PREFERENCES_INVALID");
  }
  const workRuleAssessmentExpanded = input.workRuleAssessmentExpanded === undefined
    ? undefined
    : input.workRuleAssessmentExpanded;
  if (workRuleAssessmentExpanded !== undefined && typeof workRuleAssessmentExpanded !== "boolean") {
    throw httpError(400, "Bitte einen gültigen Zustand der Arbeitszeit-Regelprüfung übermitteln.", "UI_PREFERENCES_INVALID");
  }
  const allowPastWeekEditing = input.allowPastWeekEditing === undefined
    ? undefined
    : input.allowPastWeekEditing;
  if (allowPastWeekEditing !== undefined && typeof allowPastWeekEditing !== "boolean") {
    throw httpError(400, "Bitte eine gültige persönliche Freigabe für vergangene Kalenderwochen übermitteln.", "UI_PREFERENCES_INVALID");
  }
  if (allowPastWeekEditing !== undefined && !isLocalSystemSession(actor)
    && (!actor.permissions?.includes("schedule:write") || !actor.permissions?.includes("settings:write"))) {
    throw httpError(403, "Für die persönliche Freigabe vergangener Kalenderwochen fehlen die Dienstplan- oder Einstellungsrechte.", "PORTAL_PERMISSION_DENIED");
  }
  const previousAllowPastWeekEditing = allowPastWeekEditing === undefined
    ? undefined
    : isLocalSystemSession(actor)
      ? settingEnabled(getSettings(), "allow_past_week_editing")
      : (await uiPreferencesRepository.get(actor.employeeNumber, "allow_past_week_editing"))?.value === "1";
  const vacationCalendarView = input.vacationCalendarView === undefined
    ? undefined
    : validateVacationCalendarView(input.vacationCalendarView);
  const personnelDashboardLayout = input.personnelDashboardLayout === undefined
    ? undefined
    : validatePersonnelDashboardLayout(input.personnelDashboardLayout);
  const startDashboardPreferences = input.startDashboardPreferences === undefined
    ? undefined
    : validateStartDashboardPreferences(input.startDashboardPreferences);
  const mobilePortalNavigation = input.mobilePortalNavigation === undefined
    ? undefined
    : validateMobilePortalNavigation(input.mobilePortalNavigation);
  const mobilePortalAppearance = input.mobilePortalAppearance === undefined
    ? undefined
    : validateMobilePortalAppearance(input.mobilePortalAppearance);
  const mobilePortalHome = input.mobilePortalHome === undefined
    ? undefined
    : validateMobilePortalHome(input.mobilePortalHome);
  const candidateEvaluationPdfPreferences = input.candidateEvaluationPdfPreferences === undefined
    ? undefined
    : validateCandidateEvaluationPdfPreferences(input.candidateEvaluationPdfPreferences);
  if (candidateEvaluationPdfPreferences !== undefined && !isLocalSystemSession(actor)
    && !personnelLifecycleAccessForSession(actor).canReadCandidates) {
    throw httpError(403, "Für persönliche Bewerbungs-PDF-Optionen fehlt das Bewerber-Leserecht.", "PORTAL_PERMISSION_DENIED");
  }
  if (!Object.keys(pageThemes).length && appFontScalePercent === undefined && employeeDisplayColumns === undefined
    && employeeDisplaySort === undefined && workRuleAssessmentExpanded === undefined
    && allowPastWeekEditing === undefined
    && vacationCalendarView === undefined
    && personnelDashboardLayout === undefined && startDashboardPreferences === undefined
    && mobilePortalNavigation === undefined
    && mobilePortalAppearance === undefined && mobilePortalHome === undefined
    && candidateEvaluationPdfPreferences === undefined) {
    throw httpError(400, "Es wurde keine Darstellung zum Speichern übermittelt.", "UI_PREFERENCES_INVALID");
  }
  if (!isLocalSystemSession(actor)) {
    const upserts = [];
    for (const [view, theme] of Object.entries(pageThemes)) {
      upserts.push({ preferenceKey: `page_theme_${view}`, value: theme });
      if (view === "rightsDashboard") {
        upserts.push({ preferenceKey: "rights_dashboard_theme", value: theme });
      }
    }
    if (appFontScalePercent !== undefined) {
      upserts.push({ preferenceKey: "app_font_scale_percent", value: String(appFontScalePercent) });
    }
    if (employeeDisplayColumns !== undefined) {
      upserts.push({
        preferenceKey: "employee_display_columns",
        value: JSON.stringify(employeeDisplayColumns.map(String)),
      });
    }
    if (employeeDisplaySort !== undefined) {
      upserts.push({
        preferenceKey: "employee_display_sort",
        value: JSON.stringify({
          key: String(employeeDisplaySort.key),
          direction: String(employeeDisplaySort.direction),
        }),
      });
    }
    if (workRuleAssessmentExpanded !== undefined) {
      upserts.push({
        preferenceKey: "work_rule_assessment_expanded",
        value: workRuleAssessmentExpanded ? "1" : "0",
      });
    }
    if (allowPastWeekEditing !== undefined) {
      upserts.push({
        preferenceKey: "allow_past_week_editing",
        value: allowPastWeekEditing ? "1" : "0",
      });
    }
    if (vacationCalendarView !== undefined) {
      upserts.push({
        preferenceKey: "vacation_calendar_view_v1",
        value: JSON.stringify(vacationCalendarView),
      });
    }
    if (personnelDashboardLayout !== undefined) {
      upserts.push({
        preferenceKey: "personnel_dashboard_layout_v1",
        value: JSON.stringify(personnelDashboardLayout),
      });
    }
    if (startDashboardPreferences !== undefined) {
      upserts.push({
        preferenceKey: "start_dashboard_preferences_v3",
        value: JSON.stringify(startDashboardPreferences),
      });
    }
    if (mobilePortalNavigation !== undefined) {
      upserts.push({
        preferenceKey: "mobile_portal_navigation_v1",
        value: JSON.stringify(mobilePortalNavigation),
      });
    }
    if (mobilePortalAppearance !== undefined) {
      upserts.push({
        preferenceKey: "mobile_portal_appearance_v1",
        value: JSON.stringify(mobilePortalAppearance),
      });
    }
    if (mobilePortalHome !== undefined) {
      upserts.push({
        preferenceKey: "mobile_portal_home_v1",
        value: JSON.stringify(mobilePortalHome),
      });
    }
    if (candidateEvaluationPdfPreferences !== undefined) {
      upserts.push({
        preferenceKey: CANDIDATE_EVALUATION_PDF_PREFERENCE_KEY,
        value: JSON.stringify(candidateEvaluationPdfPreferences),
      });
    }
    await uiPreferencesRepository.saveChanges(actor.employeeNumber, {
      upserts,
      deleteKeys: [
        ...(appFontScalePercent === undefined ? [] : ["dashboard_font_size"]),
        ...(startDashboardPreferences === undefined ? [] : ["start_dashboard_preferences_v1", "start_dashboard_preferences_v2"]),
      ],
    });
  }
  if (allowPastWeekEditing !== undefined && previousAllowPastWeekEditing !== allowPastWeekEditing) {
    (await auditPortal(
      actor.employeeNumber,
      "schedule.past-week-preference.update",
      "portal_user",
      actor.employeeNumber,
      JSON.stringify({ previousEnabled: previousAllowPastWeekEditing, enabled: allowPastWeekEditing }),
    ));
  }
  if (candidateEvaluationPdfPreferences !== undefined) {
    (await auditPortal(
      actor.employeeNumber,
      "personnel-lifecycle.evaluation-pdf-preferences.update",
      "portal_user",
      actor.employeeNumber,
      JSON.stringify({
        pageMode: candidateEvaluationPdfPreferences.pageMode,
        orientation: candidateEvaluationPdfPreferences.orientation,
        applyBranding: candidateEvaluationPdfPreferences.applyBranding,
        includeLogo: candidateEvaluationPdfPreferences.includeLogo,
        includeDatePrefix: candidateEvaluationPdfPreferences.includeDatePrefix,
      }),
    ));
  }
  return uiPreferencesForActor(actor, {
    pageThemes,
    appFontScalePercent,
    employeeDisplayColumns,
    employeeDisplaySort,
    workRuleAssessmentExpanded,
    allowPastWeekEditing,
    vacationCalendarView,
    personnelDashboardLayout,
    startDashboardPreferences,
    mobilePortalNavigation,
    mobilePortalAppearance,
    mobilePortalHome,
    candidateEvaluationPdfPreferences,
  });
}

async function rightsDashboardThemeForActor(actor) {
  return (await uiPreferencesForActor(actor)).pageThemes.rightsDashboard;
}

const LOCATION_DASHBOARD_ORDER_PREFERENCE = "dashboard_location_order";
const locationDashboardCategoryCatalog = Object.freeze([
  { id: "sick", label: "Krankenstand", tone: "danger" },
  { id: "vacation", label: "Urlaub", tone: "vacation" },
  { id: "time_off", label: "Zeitausgleich", tone: "warning" },
  { id: "training", label: "Schule / Schulung", tone: "info" },
  { id: "branch", label: "Andere Filiale", tone: "branch" },
  { id: "other", label: "Sonstiges", tone: "neutral" },
]);

function locationDashboardCategory(optionType) {
  if (optionType === "sick") return "sick";
  if (optionType === "vacation") return "vacation";
  if (optionType === "time_off") return "time_off";
  if (["vocational_school", "school"].includes(optionType)) return "training";
  if (optionType === "branch") return "branch";
  return "other";
}

async function locationDashboardOrderForActor(actor, validLocationIds = []) {
  if (!actor?.employeeNumber || isLocalSystemSession(actor)) return [];
  const stored = (await uiPreferencesRepository.get(
    actor.employeeNumber,
    LOCATION_DASHBOARD_ORDER_PREFERENCE,
  ))?.value;
  if (!stored) return [];
  try {
    const parsed = JSON.parse(stored);
    if (!Array.isArray(parsed)) return [];
    const valid = new Set(validLocationIds.map(String));
    return [...new Set(parsed.map((value) => String(value || "").trim()))]
      .filter((locationId) => valid.has(locationId));
  } catch {
    return [];
  }
}

async function validateLocationDashboardOrder(input) {
  if (!Array.isArray(input)) {
    throw httpError(400, "Bitte eine gültige Filialreihenfolge übermitteln.", "DASHBOARD_LOCATION_ORDER_INVALID");
  }
  const submitted = input.map((value) => String(value || "").trim());
  if (submitted.some((value) => !value) || new Set(submitted).size !== submitted.length || submitted.length > 250) {
    throw httpError(400, "Bitte eine gültige Filialreihenfolge übermitteln.", "DASHBOARD_LOCATION_ORDER_INVALID");
  }
  if (!submitted.length) return [];
  const existing = new Set(
    (await planningSettingsRepository.listDashboardLocations()).map((row) => String(row.id)),
  );
  if (submitted.some((locationId) => !existing.has(locationId))) {
    throw httpError(400, "Die Filialreihenfolge enthält einen unbekannten oder inaktiven Standort.", "DASHBOARD_LOCATION_ORDER_INVALID");
  }
  return submitted;
}

async function saveLocationDashboardOrder(actor, input) {
  const locationOrder = await validateLocationDashboardOrder(input);
  if (!isLocalSystemSession(actor)) {
    await uiPreferencesRepository.upsert(
      actor.employeeNumber,
      LOCATION_DASHBOARD_ORDER_PREFERENCE,
      JSON.stringify(locationOrder),
    );
    (await auditPortal(actor.employeeNumber, "dashboard.locations.order.update", "portal_user_preference", actor.employeeNumber,
      JSON.stringify({ locationOrder })));
  }
  return locationOrder;
}

async function locationDashboardPayload(actor, requestedDate) {
  const date = requestedDate ? String(requestedDate) : viennaTodayIso();
  if (!isIsoDate(date)) {
    throw httpError(400, "Bitte ein gültiges Datum für die Filialübersicht auswählen.", "DASHBOARD_DATE_INVALID");
  }
  const [
    storedLocations,
    departments,
    activeTeamCounts,
    scheduledCounts,
    optionRows,
  ] = await Promise.all([
    planningSettingsRepository.listDashboardLocations(),
    planningSettingsRepository.listDashboardDepartments(),
    planningSettingsRepository.listDashboardTeamCounts(),
    planningSettingsRepository.listDashboardScheduledCounts({ date }),
    planningSettingsRepository.listDashboardOptions({ date }),
  ]);
  const locations = storedLocations.map((location) => ({
    id: String(location.id),
    name: location.name,
    minStaff: Math.max(0, Number(location.min_staff || 0)),
    departments: [],
    activeTeamCount: 0,
    scheduledCount: 0,
    absences: [],
  }));
  const locationLookup = new Map(locations.map((location) => [location.id, location]));
  for (const department of departments) {
    locationLookup.get(String(department.location_id))?.departments.push({
      id: Number(department.id),
      name: department.name,
      minStaff: Math.max(0, Number(department.min_staff || 0)),
    });
  }
  for (const location of locations) {
    const day = await dayConfiguration(date, await settingsForLocation(location.id), { locationId: location.id });
    location.open = Boolean(day?.open);
    location.openingHours = day?.open ? { start: day.start, end: day.end } : null;
    location.minStaff = day?.open ? Math.max(0, Number(day.minStaff || 0)) : 0;
  }
  for (const entry of activeTeamCounts) {
    const location = locationLookup.get(String(entry.location_id));
    if (location) location.activeTeamCount = Number(entry.count || 0);
  }
  for (const entry of scheduledCounts) {
    const location = locationLookup.get(String(entry.location_id));
    if (location) location.scheduledCount = Number(entry.count || 0);
  }
  for (const option of optionRows) {
    const location = locationLookup.get(String(option.home_location_id));
    if (!location) continue;
    const category = locationDashboardCategory(option.option_type);
    location.absences.push({
      id: Number(option.id),
      employeeNumber: String(option.employee_number),
      fullName: option.full_name || "",
      nickname: option.nickname || option.full_name || String(option.employee_number),
      color: option.color || "#26785f",
      departmentName: option.department_name || "",
      category,
      label: locationDashboardCategoryCatalog.find((entry) => entry.id === category)?.label || "Sonstiges",
      allDay: Boolean(option.all_day),
      startTime: option.all_day ? null : option.start_time || null,
      endTime: option.all_day ? null : option.end_time || null,
    });
  }
  const requestedOrder = await locationDashboardOrderForActor(actor, locations.map((location) => location.id));
  const orderIndex = new Map(requestedOrder.map((locationId, index) => [locationId, index]));
  locations.sort((left, right) => {
    const leftIndex = orderIndex.has(left.id) ? orderIndex.get(left.id) : Number.MAX_SAFE_INTEGER;
    const rightIndex = orderIndex.has(right.id) ? orderIndex.get(right.id) : Number.MAX_SAFE_INTEGER;
    return leftIndex - rightIndex || left.id.localeCompare(right.id, "de-AT", { numeric: true }) || left.name.localeCompare(right.name, "de-AT");
  });
  const categories = locationDashboardCategoryCatalog.map((category) => ({
    ...category,
    count: locations.reduce((sum, location) => sum + location.absences.filter((entry) => entry.category === category.id).length, 0),
  }));
  for (const location of locations) {
    location.counts = Object.fromEntries(locationDashboardCategoryCatalog.map((category) => [category.id,
      location.absences.filter((entry) => entry.category === category.id).length]));
    location.status = !location.open
      ? "closed"
      : location.minStaff > 0 && location.scheduledCount < location.minStaff
      ? "critical"
      : location.minStaff > 0 && location.scheduledCount === location.minStaff
        ? "attention"
        : "ok";
  }
  return {
    date,
    generatedAt: new Date().toISOString(),
    actor: { employeeNumber: actor.employeeNumber, role: actor.role },
    preferences: { locationOrder: locations.map((location) => location.id) },
    summary: {
      activeLocations: locations.length,
      scheduledEmployees: locations.reduce((sum, location) => sum + location.scheduledCount, 0),
      absentEntries: categories.reduce((sum, category) => sum + category.count, 0),
      criticalLocations: locations.filter((location) => location.status === "critical").length,
    },
    categories,
    locations,
  };
}

const CUSTOM_PROCESS_STATUS = new Set(["draft", "active", "archived"]);
const CUSTOM_PROCESS_SCOPES = new Set(["company", "location", "department"]);
const CUSTOM_PROCESS_TRIGGERS = new Set(["manual", "staffing_shortfall"]);
const CUSTOM_PROCESS_STEP_TYPES = new Set(["actor", "system", "decision", "approval", "finish"]);
const CUSTOM_PROCESS_RESPONSIBILITIES = new Set(["system", "role", "employee"]);
const CUSTOM_PROCESS_CONDITIONS = new Set(["always", "when", "optional"]);
const CUSTOM_PROCESS_NOTIFICATION_CHANNELS = new Set(["internal", "email", "sms"]);
const CUSTOM_PROCESS_MAX_STEPS = 30;
const PROCESS_CATEGORY_CATALOG = Object.freeze([
  Object.freeze({
    id: "personnel_absence",
    label: "Personal & Abwesenheit",
    description: "Urlaub, Zeitausgleich, Krankheit und weitere personenbezogene Abwesenheitsabläufe.",
    sortOrder: 10,
  }),
  Object.freeze({
    id: "time_payroll",
    label: "Arbeitszeit & Abrechnung",
    description: "Zeiterfassung, Tagesprüfung und kontrollierte Übergaben an nachgelagerte Stellen.",
    sortOrder: 20,
  }),
  Object.freeze({
    id: "customer_service",
    label: "Verkauf & Kundenservice",
    description: "Kundenbezogene Abläufe wie Reparaturen, Reklamationen und Second-Hand-Annahmen.",
    sortOrder: 30,
  }),
  Object.freeze({
    id: "goods_equipment",
    label: "Ware & Geräte",
    description: "Leihen, Umlagerungen, Inventur und weitere waren- oder gerätebezogene Abläufe.",
    sortOrder: 40,
  }),
  Object.freeze({
    id: "administration_it",
    label: "Administration & IT",
    description: "Zugänge, Datenschutzfälle, Systemstörungen und administrative Betriebsabläufe.",
    sortOrder: 50,
  }),
  Object.freeze({
    id: "other",
    label: "Weitere eigene Abläufe",
    description: "Eigene Prozessdefinitionen, die noch keinem spezielleren Fachbereich zugeordnet sind.",
    sortOrder: 90,
  }),
]);
const PROCESS_CATEGORY_LOOKUP = new Map(PROCESS_CATEGORY_CATALOG.map((category) => [category.id, category]));

function processCategoryDefinition(value, { strict = false } = {}) {
  const id = String(value || "other").trim();
  const category = PROCESS_CATEGORY_LOOKUP.get(id);
  if (category) return category;
  if (strict) throw httpError(400, "Der Fachbereich des Prozesses ist ungültig.", "CUSTOM_PROCESS_CATEGORY_INVALID");
  return PROCESS_CATEGORY_LOOKUP.get("other");
}

function processCategoryCatalogPublic() {
  return PROCESS_CATEGORY_CATALOG.map((category) => ({ ...category }));
}

function customProcessInputObject(value, label) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw httpError(400, `${label} ist ungültig.`, "CUSTOM_PROCESS_INPUT_INVALID");
  }
  return value;
}

function assertCustomProcessKeys(input, allowed, label) {
  const unexpected = Object.keys(input).filter((key) => !allowed.has(key));
  if (unexpected.length) {
    throw httpError(400, `${label} enthält nicht unterstützte Felder.`, "CUSTOM_PROCESS_INPUT_INVALID");
  }
}

function customProcessText(value, { label, min = 0, max }) {
  const normalized = stripEmoji(String(value ?? ""))
    .replace(/[\u0000-\u001f\u007f]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (normalized.length < min || normalized.length > max) {
    throw httpError(400, `${label} muss zwischen ${min} und ${max} Zeichen lang sein.`, "CUSTOM_PROCESS_INPUT_INVALID");
  }
  return normalized;
}

async function customProcessScope(input = {}, repository = customProcessRepository) {
  const scope = customProcessInputObject(input, "Der Geltungsbereich");
  assertCustomProcessKeys(scope, new Set(["type", "locationId", "departmentId"]), "Der Geltungsbereich");
  const type = String(scope.type || "company").trim();
  if (!CUSTOM_PROCESS_SCOPES.has(type)) {
    throw httpError(400, "Der Geltungsbereich ist ungültig.", "CUSTOM_PROCESS_SCOPE_INVALID");
  }
  const submittedLocationId = String(scope.locationId || "").trim();
  const submittedDepartmentId = Number(scope.departmentId || 0) || null;
  if (type === "company") {
    if (submittedLocationId || submittedDepartmentId) {
      throw httpError(400, "Ein unternehmensweiter Prozess darf keinen versteckten Standortbezug enthalten.", "CUSTOM_PROCESS_SCOPE_INVALID");
    }
    return { type, locationId: null, departmentId: null, label: "Gesamtes Unternehmen" };
  }
  if (type === "location") {
    if (!submittedLocationId || submittedDepartmentId) {
      throw httpError(400, "Bitte genau eine aktive Filiale auswählen.", "CUSTOM_PROCESS_SCOPE_INVALID");
    }
    const location = await repository.activeLocation({ locationId: submittedLocationId });
    if (!location) throw httpError(400, "Die ausgewählte Filiale ist nicht aktiv oder nicht vorhanden.", "CUSTOM_PROCESS_SCOPE_INVALID");
    return { type, locationId: String(location.id), departmentId: null, label: location.name };
  }
  if (!submittedDepartmentId) {
    throw httpError(400, "Bitte eine aktive Abteilung auswählen.", "CUSTOM_PROCESS_SCOPE_INVALID");
  }
  const department = await repository.activeDepartment({
    departmentId: submittedDepartmentId,
  });
  if (!department || (submittedLocationId && submittedLocationId !== String(department.location_id))) {
    throw httpError(400, "Die ausgewählte Abteilung gehört nicht zur aktiven Filiale.", "CUSTOM_PROCESS_SCOPE_INVALID");
  }
  return {
    type,
    locationId: String(department.location_id),
    departmentId: Number(department.id),
    label: `${department.location_name} · ${department.name}`,
  };
}

async function customProcessResponsibilityLabel(
  type,
  reference,
  scope,
  roles = [],
  repository = customProcessRepository,
) {
  if (type === "system") return "Grabenplaner";
  if (type === "role") {
    const role = roles.find((entry) => entry.id === reference);
    if (!role) throw httpError(400, "Die zuständige App-Rolle ist nicht vorhanden.", "CUSTOM_PROCESS_RESPONSIBILITY_INVALID");
    return role.name;
  }
  const employee = await repository.responsibilityCandidate({
    employeeNumber: reference,
  });
  if (!employee) {
    throw httpError(400, "Die zuständige Person hat keinen aktiven Portal-Zugang.", "CUSTOM_PROCESS_RESPONSIBILITY_INVALID");
  }
  if (!customProcessPortalUserInScope(employee, scope)) {
    throw httpError(
      400,
      scope.type === "department"
        ? "Die zuständige Person ist der ausgewählten Abteilung nicht zugeordnet."
        : "Die zuständige Person ist der ausgewählten Filiale nicht zugeordnet.",
      "CUSTOM_PROCESS_RESPONSIBILITY_INVALID",
    );
  }
  return `${employee.full_name || reference} · ${reference}`;
}

async function normalizeCustomProcessStep(
  input,
  index,
  scope,
  usedIds,
  roles = [],
  repository = customProcessRepository,
) {
  const step = customProcessInputObject(input, `Prozessschritt ${index + 1}`);
  assertCustomProcessKeys(step, new Set([
    "id", "type", "title", "description", "responsibilityType", "responsibilityReference",
    "conditionType", "conditionText", "notificationChannels",
  ]), `Prozessschritt ${index + 1}`);
  let id = String(step.id || "").trim();
  if (!id) id = crypto.randomUUID();
  if (!/^[A-Za-z0-9_-]{1,80}$/.test(id) || usedIds.has(id)) {
    throw httpError(400, "Jeder Prozessschritt benötigt eine eindeutige technische ID.", "CUSTOM_PROCESS_STEP_INVALID");
  }
  usedIds.add(id);
  const type = String(step.type || "actor").trim();
  if (!CUSTOM_PROCESS_STEP_TYPES.has(type)) throw httpError(400, "Der Schritttyp ist ungültig.", "CUSTOM_PROCESS_STEP_INVALID");
  const title = customProcessText(step.title, { label: "Der Schritttitel", min: 2, max: 120 });
  const description = customProcessText(step.description, { label: "Die Schrittbeschreibung", max: 600 });
  const responsibilityType = String(step.responsibilityType || (type === "system" ? "system" : "role")).trim();
  if (!CUSTOM_PROCESS_RESPONSIBILITIES.has(responsibilityType)) {
    throw httpError(400, "Die Zuständigkeit des Prozessschritts ist ungültig.", "CUSTOM_PROCESS_RESPONSIBILITY_INVALID");
  }
  const responsibilityReference = responsibilityType === "system"
    ? ""
    : customProcessText(step.responsibilityReference, { label: "Die Zuständigkeitsreferenz", min: 1, max: 80 });
  const responsibilityLabel = await customProcessResponsibilityLabel(
    responsibilityType,
    responsibilityReference,
    scope,
    roles,
    repository,
  );
  const conditionType = String(step.conditionType || "always").trim();
  if (!CUSTOM_PROCESS_CONDITIONS.has(conditionType)) throw httpError(400, "Die Bedingungsart ist ungültig.", "CUSTOM_PROCESS_CONDITION_INVALID");
  const conditionText = conditionType === "always"
    ? ""
    : customProcessText(step.conditionText, { label: "Die Bedingungsbeschreibung", min: conditionType === "when" ? 2 : 0, max: 400 });
  if (!Array.isArray(step.notificationChannels)) {
    throw httpError(400, "Die Benachrichtigungskanäle sind ungültig.", "CUSTOM_PROCESS_NOTIFICATION_INVALID");
  }
  const notificationChannels = [...new Set(step.notificationChannels.map((channel) => String(channel || "").trim()))];
  if (notificationChannels.some((channel) => !CUSTOM_PROCESS_NOTIFICATION_CHANNELS.has(channel))) {
    throw httpError(400, "Ein Benachrichtigungskanal ist nicht freigegeben.", "CUSTOM_PROCESS_NOTIFICATION_INVALID");
  }
  if (responsibilityType === "system" && notificationChannels.length) {
    throw httpError(400, "Ein reiner Systemschritt kann keine Person benachrichtigen.", "CUSTOM_PROCESS_NOTIFICATION_INVALID");
  }
  if (conditionType !== "always" && notificationChannels.length) {
    throw httpError(400, "Automatische Verständigungen sind nur bei eindeutig immer ausgeführten Schritten zulässig.", "CUSTOM_PROCESS_NOTIFICATION_CONDITIONAL");
  }
  return {
    id, type, title, description, responsibilityType, responsibilityReference, responsibilityLabel,
    conditionType, conditionText, notificationChannels, sortOrder: index + 1,
  };
}

async function normalizeCustomProcessInput(
  body = {},
  {
    allowArchived = false,
    roles = [],
    repository = customProcessRepository,
  } = {},
) {
  const input = customProcessInputObject(body, "Die Prozessdefinition");
  assertCustomProcessKeys(input, new Set(["title", "symbol", "description", "summary", "category", "status", "scope", "trigger", "steps", "revision"]), "Die Prozessdefinition");
  const title = customProcessText(input.title, { label: "Der Prozessname", min: 3, max: 120 });
  const rawSymbol = customProcessText(input.symbol || "P", { label: "Das Kurzzeichen", min: 1, max: 5 }).toUpperCase();
  if (!/^[\p{L}\p{N}]{1,5}$/u.test(rawSymbol)) throw httpError(400, "Das Kurzzeichen darf nur Buchstaben und Ziffern enthalten.", "CUSTOM_PROCESS_INPUT_INVALID");
  const description = customProcessText(input.description ?? input.summary, { label: "Die Prozessbeschreibung", max: 600 });
  const category = processCategoryDefinition(input.category || "other", { strict: true });
  const status = String(input.status || "draft").trim();
  if (!CUSTOM_PROCESS_STATUS.has(status) || (!allowArchived && status === "archived")) {
    throw httpError(400, "Der Prozessstatus ist ungültig.", "CUSTOM_PROCESS_STATUS_INVALID");
  }
  const scope = await customProcessScope(
    input.scope || { type: "company" },
    repository,
  );
  const triggerInput = customProcessInputObject(input.trigger || { type: "manual", minimumShortfall: 1 }, "Der Prozessauslöser");
  assertCustomProcessKeys(triggerInput, new Set(["type", "minimumShortfall"]), "Der Prozessauslöser");
  const triggerType = String(triggerInput.type || "manual").trim();
  const minimumShortfall = Number(triggerInput.minimumShortfall ?? 1);
  if (!CUSTOM_PROCESS_TRIGGERS.has(triggerType) || !Number.isInteger(minimumShortfall) || minimumShortfall < 1 || minimumShortfall > 99) {
    throw httpError(400, "Der Prozessauslöser ist ungültig.", "CUSTOM_PROCESS_TRIGGER_INVALID");
  }
  if (!Array.isArray(input.steps) || input.steps.length < 2 || input.steps.length > CUSTOM_PROCESS_MAX_STEPS) {
    throw httpError(400, `Ein eigener Prozess benötigt 2 bis ${CUSTOM_PROCESS_MAX_STEPS} Schritte.`, "CUSTOM_PROCESS_STEPS_INVALID");
  }
  const usedIds = new Set();
  const steps = [];
  for (const [index, step] of input.steps.entries()) {
    steps.push(await normalizeCustomProcessStep(
      step,
      index,
      scope,
      usedIds,
      roles,
      repository,
    ));
  }
  if (status === "active" && !steps.some((step) => step.type === "finish")) {
    throw httpError(422, "Ein aktiver Prozess benötigt einen klaren Abschlussschritt.", "CUSTOM_PROCESS_ACTIVATION_INVALID");
  }
  return { title, symbol: rawSymbol, description, category: category.id, status, scope, trigger: { type: triggerType, minimumShortfall }, steps };
}

async function customProcessRows(
  { includeArchived = false } = {},
  repository = customProcessRepository,
) {
  const processes = await repository.listProcesses({ includeArchived: includeArchived ? 1 : 0 });
  const steps = await repository.listAllSteps();
  const stepsByProcess = new Map();
  for (const step of steps) {
    const processSteps = stepsByProcess.get(step.process_id) || [];
    processSteps.push(step);
    stepsByProcess.set(step.process_id, processSteps);
  }
  return processes.map((process) => ({
    process,
    steps: stepsByProcess.get(process.id) || [],
  }));
}

function customProcessScopeFromRow(row) {
  const type = CUSTOM_PROCESS_SCOPES.has(row.scope_type) ? row.scope_type : "company";
  if (type === "company") {
    return {
      type,
      locationId: null,
      departmentId: null,
      label: "Gesamtes Unternehmen",
      valid: row.scope_type === "company",
    };
  }
  if (type === "location" && row.location_id && row.scope_location_active) {
    return {
      type,
      locationId: String(row.location_id),
      departmentId: null,
      label: row.scope_location_name,
      valid: true,
    };
  }
  if (type === "department"
      && row.location_id
      && row.department_id
      && row.scope_department_active
      && row.scope_department_location_active
      && String(row.scope_department_location_id) === String(row.location_id)) {
    return {
      type,
      locationId: String(row.location_id),
      departmentId: Number(row.department_id),
      label: `${row.scope_department_location_name} · ${row.scope_department_name}`,
      valid: true,
    };
  }
  return {
    type,
    locationId: row.location_id || null,
    departmentId: Number(row.department_id || 0) || null,
    label: "Geltungsbereich nicht mehr verfügbar",
    valid: false,
  };
}

function customProcessDashboardDefinition(row, stepRows = []) {
  const scope = customProcessScopeFromRow(row);
  const category = processCategoryDefinition(row.category);
  const steps = stepRows.map((step) => {
    let notificationChannels = [];
    try {
      const parsed = JSON.parse(step.notification_channels || "[]");
      if (Array.isArray(parsed)) notificationChannels = parsed.filter((channel) => CUSTOM_PROCESS_NOTIFICATION_CHANNELS.has(channel));
    } catch {}
    const conditionLabel = step.condition_type === "always"
      ? "Immer"
      : step.condition_type === "when"
        ? `Wenn: ${step.condition_text}`
        : step.condition_text ? `Optional: ${step.condition_text}` : "Optionaler Schritt";
    return {
      id: step.id,
      type: step.step_type,
      title: step.title,
      description: step.description,
      responsibilityType: step.responsibility_type,
      responsibilityReference: step.responsibility_reference,
      responsibilityLabel: step.responsibility_label,
      conditionType: step.condition_type,
      conditionText: step.condition_text,
      notificationChannels,
      actor: step.responsibility_label || "Grabenplaner",
      state: step.condition_type === "always" ? "active" : "conditional",
      setting: conditionLabel,
      permissions: [],
    };
  });
  const notifications = steps.reduce((sum, step) => sum + step.notificationChannels.length, 0);
  const triggerLabel = row.trigger_type === "staffing_shortfall"
    ? `Notbesetzung ab ${row.trigger_minimum_shortfall} fehlender Person(en)`
    : "Manuell durch PL+";
  return {
    id: row.id,
    source: "custom",
    revision: Number(row.revision || 1),
    status: row.status,
    statusLabel: row.status === "active" ? "Ablauf aktiv" : row.status === "draft" ? "Entwurf" : "Archiviert",
    enabled: row.status === "active",
    category: category.id,
    categoryLabel: category.label,
    symbol: row.symbol,
    title: row.title,
    description: row.description,
    summary: row.description,
    locationSensitive: false,
    scope: { type: scope.type, locationId: scope.locationId, departmentId: scope.departmentId, label: scope.label, valid: scope.valid !== false },
    trigger: { type: row.trigger_type, minimumShortfall: Number(row.trigger_minimum_shortfall || 1), label: triggerLabel },
    rules: [
      { label: "Fachbereich", value: category.label, tone: "neutral" },
      { label: "Geltungsbereich", value: scope.label, tone: "neutral" },
      { label: "Auslöser", value: triggerLabel, tone: row.trigger_type === "staffing_shortfall" ? "attention" : "neutral" },
      { label: "Benachrichtigungen", value: String(notifications), tone: notifications ? "positive" : "neutral" },
      { label: "Status", value: row.status === "active" ? "Aktiv" : row.status === "draft" ? "Entwurf" : "Archiviert", tone: row.status === "active" ? "positive" : "neutral" },
    ],
    simulations: [{ id: "current", label: "Gespeicherter Ablauf", description: "Die Vorschau verändert keine gespeicherten Daten.", stepStates: {} }],
    steps,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

async function customProcessesForDashboard(repository = customProcessRepository) {
  return (await customProcessRows({}, repository))
    .map(({ process, steps }) => customProcessDashboardDefinition(process, steps));
}

async function customProcessEditorCatalog(actor) {
  const canManage = isLocalSystemSession(actor)
    || (RIGHTS_ADMIN_PORTAL_ROLES.has(actor?.role) && actor?.permissions?.includes("processes:write"));
  const roles = (await getPortalRoles()).map((role) => ({ id: role.id, name: role.name }));
  const employees = (await customProcessRepository.listRecipientCandidates()).map((employee) => ({
    employeeNumber: String(employee.personnel_number),
    fullName: employee.full_name || String(employee.personnel_number),
    role: employee.role,
    locationId: employee.home_location_id || null,
    departmentId: Number(employee.preferred_department_id || 0) || null,
  }));
  const locations = (await getLocations(false)).map((location) => ({
    id: String(location.id), name: location.name,
    departments: (location.departments || []).filter((department) => department.active).map((department) => ({ id: Number(department.id), name: department.name })),
  }));
  return {
    canManageCustomProcesses: canManage,
    categories: processCategoryCatalogPublic(),
    statuses: ["draft", "active"],
    scopes: ["company", "location", "department"],
    triggers: ["manual", "staffing_shortfall"],
    notificationChannels: ["internal", "email", "sms"],
    providers: externalNotificationProviderStatus(),
    roles,
    employees,
    locations,
  };
}

async function insertCustomProcessSteps(processId, steps, repository = customProcessRepository) {
  for (const step of steps) {
    await repository.insertProcessStep({
      ...step,
      processId,
      notificationChannels: JSON.stringify(step.notificationChannels),
    });
  }
}

async function assertCustomProcessStepIdsAvailable(
  steps,
  processId = null,
  repository = customProcessRepository,
) {
  const ids = [...new Set((steps || []).map((step) => String(step?.id || "").trim()).filter(Boolean))];
  if (!ids.length) return;
  const conflict = await repository.conflictingStep({
    stepIds: ids,
    processId: processId ? String(processId) : null,
  });
  if (conflict) {
    throw httpError(409, "Eine technische Schritt-ID wird bereits von einem anderen Prozess verwendet.", "CUSTOM_PROCESS_STEP_ID_CONFLICT");
  }
}

async function customProcessById(
  id,
  { includeArchived = false } = {},
  repository = customProcessRepository,
) {
  const process = await repository.processById({
    id: String(id || ""),
    includeArchived: includeArchived ? 1 : 0,
  });
  if (!process) return null;
  const steps = await repository.listProcessSteps({ processId: process.id });
  return { process, steps, dto: customProcessDashboardDefinition(process, steps) };
}

async function persistCustomProcessRevision(
  processId,
  actor = "system",
  repository = customProcessRepository,
) {
  const bundle = await customProcessById(
    processId,
    { includeArchived: true },
    repository,
  );
  if (!bundle) throw httpError(404, "Der eigene Prozess wurde nicht gefunden.", "CUSTOM_PROCESS_NOT_FOUND");
  const snapshot = JSON.stringify(bundle.dto);
  await repository.insertProcessRevision({
    processId,
    revision: Number(bundle.process.revision || 1),
    snapshotJson: snapshot,
    actor: String(actor || "system"),
  });
  return bundle.dto;
}

async function customProcessRevisionDefinition(
  processId,
  revision,
  repository = customProcessRepository,
) {
  const row = await repository.processRevision({
    processId: String(processId || ""),
    revision: Number(revision || 0),
  });
  if (!row?.snapshot_json) return null;
  try {
    const value = JSON.parse(row.snapshot_json);
    if (!value || typeof value !== "object" || value.id !== String(processId) || Number(value.revision) !== Number(revision)
        || !Array.isArray(value.steps)) return null;
    return value;
  } catch {
    return null;
  }
}

async function customProcessRunBundle(run, repository = customProcessRepository) {
  const dto = await customProcessRevisionDefinition(
    run?.process_id,
    run?.process_revision,
    repository,
  );
  if (!dto) return null;
  return {
    process: {
      id: dto.id,
      revision: Number(dto.revision || run.process_revision || 1),
      title: dto.title,
      status: dto.status,
      trigger_type: dto.trigger?.type || run.trigger_type,
    },
    dto,
  };
}

async function backfillCustomProcessRevisionSnapshots() {
  return customProcessRepository.transaction(async (repository) => {
    let inserted = 0;
    for (const { process } of await customProcessRows(
      { includeArchived: true },
      repository,
    )) {
      const exists = await repository.processRevisionExists({
        processId: process.id,
        revision: Number(process.revision || 1),
      });
      if (exists) continue;
      await persistCustomProcessRevision(process.id, "migration", repository);
      inserted += 1;
    }
    return inserted;
  });
}

async function createCustomProcess(actor, body) {
  const value = await normalizeCustomProcessInput(body, { roles: await getPortalRoles() });
  const id = `custom-${crypto.randomUUID()}`;
  return customProcessRepository.transaction(async (repository) => {
    await assertCustomProcessStepIdsAvailable(value.steps, null, repository);
    await repository.insertProcess({
      id,
      title: value.title,
      symbol: value.symbol,
      description: value.description,
      category: value.category,
      scopeType: value.scope.type,
      locationId: value.scope.locationId,
      departmentId: value.scope.departmentId,
      triggerType: value.trigger.type,
      triggerMinimumShortfall: value.trigger.minimumShortfall,
      status: value.status,
      actor: actor.employeeNumber,
    });
    await insertCustomProcessSteps(id, value.steps, repository);
    await persistCustomProcessRevision(id, actor.employeeNumber, repository);
    await repository.insertAudit({
      actor: actor.employeeNumber,
      action: "custom-process.create",
      entityType: "custom_process",
      entityId: id,
      detail: JSON.stringify({
        status: value.status,
        revision: 1,
        category: value.category,
        scope: value.scope.type,
        stepCount: value.steps.length,
        trigger: value.trigger.type,
      }),
    });
    return (await customProcessById(id, {}, repository)).dto;
  });
}

async function updateCustomProcess(actor, id, body) {
  const revision = Number(body?.revision);
  if (!Number.isInteger(revision) || revision < 1) throw httpError(400, "Die Prozessrevision fehlt.", "CUSTOM_PROCESS_REVISION_REQUIRED");
  const existing = await customProcessById(id);
  if (!existing) throw httpError(404, "Der eigene Prozess wurde nicht gefunden.", "CUSTOM_PROCESS_NOT_FOUND");
  if (Number(existing.process.revision) !== revision) throw httpError(409, "Der Prozess wurde zwischenzeitlich geändert. Bitte neu laden.", "CUSTOM_PROCESS_REVISION_CONFLICT");
  const value = await normalizeCustomProcessInput(body, { roles: await getPortalRoles() });
  return customProcessRepository.transaction(async (repository) => {
    await assertCustomProcessStepIdsAvailable(value.steps, id, repository);
    const updated = await repository.updateProcess({
      id,
      revision,
      title: value.title,
      symbol: value.symbol,
      description: value.description,
      category: value.category,
      scopeType: value.scope.type,
      locationId: value.scope.locationId,
      departmentId: value.scope.departmentId,
      triggerType: value.trigger.type,
      triggerMinimumShortfall: value.trigger.minimumShortfall,
      status: value.status,
      actor: actor.employeeNumber,
    });
    if (!updated.rowsAffected) throw httpError(409, "Der Prozess wurde zwischenzeitlich geändert. Bitte neu laden.", "CUSTOM_PROCESS_REVISION_CONFLICT");
    await repository.deleteProcessSteps({ processId: id });
    await insertCustomProcessSteps(id, value.steps, repository);
    await persistCustomProcessRevision(id, actor.employeeNumber, repository);
    await repository.insertAudit({
      actor: actor.employeeNumber,
      action: "custom-process.update",
      entityType: "custom_process",
      entityId: id,
      detail: JSON.stringify({
        status: value.status,
        revision: revision + 1,
        category: value.category,
        scope: value.scope.type,
        stepCount: value.steps.length,
        trigger: value.trigger.type,
      }),
    });
    return (await customProcessById(id, {}, repository)).dto;
  });
}

async function setCustomProcessStatus(actor, id, body = {}) {
  const status = String(body.status || "").trim();
  const revision = Number(body.revision);
  if (!CUSTOM_PROCESS_STATUS.has(status) || !Number.isInteger(revision) || revision < 1) {
    throw httpError(400, "Status oder Prozessrevision ist ungültig.", "CUSTOM_PROCESS_STATUS_INVALID");
  }
  const existing = await customProcessById(id, { includeArchived: true });
  if (!existing) throw httpError(404, "Der eigene Prozess wurde nicht gefunden.", "CUSTOM_PROCESS_NOT_FOUND");
  if (existing.process.status === "archived") throw httpError(409, "Ein archivierter Prozess kann nicht mehr geändert werden.", "CUSTOM_PROCESS_ARCHIVED");
  if (Number(existing.process.revision) !== revision) throw httpError(409, "Der Prozess wurde zwischenzeitlich geändert. Bitte neu laden.", "CUSTOM_PROCESS_REVISION_CONFLICT");
  if (status === "active") {
    await normalizeCustomProcessInput({
      title: existing.process.title,
      symbol: existing.process.symbol,
      description: existing.process.description,
      category: existing.process.category,
      status,
      scope: { type: existing.process.scope_type, locationId: existing.process.location_id, departmentId: existing.process.department_id },
      trigger: { type: existing.process.trigger_type, minimumShortfall: existing.process.trigger_minimum_shortfall },
      steps: existing.dto.steps.map((step) => ({
        id: step.id, type: step.type, title: step.title, description: step.description,
        responsibilityType: step.responsibilityType, responsibilityReference: step.responsibilityReference,
        conditionType: step.conditionType, conditionText: step.conditionText,
        notificationChannels: step.notificationChannels,
      })),
    }, { roles: await getPortalRoles() });
  }
  return customProcessRepository.transaction(async (repository) => {
    const updated = await repository.setProcessStatus({
      id,
      revision,
      status,
      actor: actor.employeeNumber,
    });
    if (!updated.rowsAffected) throw httpError(409, "Der Prozess wurde zwischenzeitlich geändert. Bitte neu laden.", "CUSTOM_PROCESS_REVISION_CONFLICT");
    await persistCustomProcessRevision(id, actor.employeeNumber, repository);
    await repository.insertAudit({
      actor: actor.employeeNumber,
      action: status === "archived" ? "custom-process.archive" : "custom-process.status.update",
      entityType: "custom_process",
      entityId: id,
      detail: JSON.stringify({ status, revision: revision + 1 }),
    });
    if (status === "archived") {
      const openRuns = await repository.listOpenRunsForProcess({ processId: id });
      for (const run of openRuns) {
        await resolveCustomProcessRun(run, { repository });
      }
      return { id, status, revision: revision + 1 };
    }
    return (await customProcessById(id, {}, repository)).dto;
  });
}

function customProcessLookup(kind, value) {
  return crypto.createHash("sha256")
    .update(`grabenplaner-custom-process-v1\0${String(kind || "")}\0${String(value ?? "")}`)
    .digest("hex");
}

function customProcessRunPublic(row) {
  return {
    id: row.id,
    processId: row.process_id,
    processRevision: Number(row.process_revision || 1),
    triggerType: row.trigger_type,
    status: row.status,
    locationId: row.location_id || null,
    departmentId: Number(row.department_id || 0) || null,
    activationCount: Math.max(1, Number(row.activation_count || 1)),
    createdAt: row.created_at,
    resolvedAt: row.resolved_at || null,
  };
}

function customProcessEffectiveScope(bundle, context = {}) {
  const base = bundle.dto.scope;
  if (base.type !== "company") return base;
  const locationId = String(context.locationId || "").trim();
  const departmentId = Number(context.departmentId || 0) || null;
  if (!locationId) return base;
  return { type: departmentId ? "department" : "location", locationId, departmentId };
}

async function customProcessScopeIsActive(
  scope,
  repository = customProcessRepository,
) {
  if (!scope || scope.valid === false) return false;
  if (scope.type === "company") return true;
  const locationId = String(scope.locationId || "").trim();
  if (!locationId) return false;
  const departmentId = Number(scope.departmentId || 0) || null;
  if (scope.type === "department" && !departmentId) return false;
  const row = await repository.scopeIsActive({
    type: scope.type,
    locationId,
    departmentId,
  });
  return Boolean(row?.active);
}

function customProcessPortalUserInScope(user, scope) {
  if (!scope || scope.type === "company" || ["hr", "admin", "it_admin", "developer"].includes(user.role)) return true;
  const scopes = portalAccessScopesForPrincipal({
    employeeNumber: user.employee_number,
    role: user.role,
    homeLocationId: user.home_location_id,
    preferredDepartmentId: user.preferred_department_id,
    scopesValue: user.access_scopes,
  });
  if (!scopes.length && scope.type === "location") {
    return String(user.home_location_id || "") === String(scope.locationId || "");
  }
  return scopes.some((entry) => String(entry.locationId || "") === String(scope.locationId || "")
    && (scope.type !== "department"
      || !entry.departmentId
      || Number(entry.departmentId) === Number(scope.departmentId)));
}

async function customProcessRecipients(
  bundle,
  step,
  context = {},
  repository = customProcessRepository,
) {
  if (!step || step.responsibilityType === "system") return [];
  const scope = customProcessEffectiveScope(bundle, context);
  if (!await customProcessScopeIsActive(scope, repository)) return [];
  const users = await repository.listRecipientCandidates();
  return users.filter((user) => {
    if (step.responsibilityType === "role" && user.role !== step.responsibilityReference) return false;
    if (step.responsibilityType === "employee" && String(user.employee_number) !== String(step.responsibilityReference)) return false;
    return customProcessPortalUserInScope(user, scope);
  }).map((user) => String(user.employee_number));
}

async function customProcessExternalJobValid(
  job,
  payload,
  repository = customProcessRepository,
) {
  void job;
  void payload;
  void repository;
  return null;
}

async function queueCustomProcessExternalNotification(
  bundle,
  run,
  step,
  recipient,
  channel,
  repository = customProcessRepository,
) {
  void bundle;
  void run;
  void step;
  void recipient;
  void channel;
  void repository;
  return { queued: false, blocked: true };
}

async function emitCustomProcessStepNotifications(
  bundle,
  run,
  step,
  repository = customProcessRepository,
) {
  let internal = 0;
  let external = 0;
  let blocked = 0;
  if (!step?.notificationChannels?.length) return { internal, external, blocked };
  const activationCount = Math.max(1, Number(run.activation_count || 1));
  const recipients = await customProcessRecipients(bundle, step, run, repository);
  for (const recipient of recipients) {
    if (step.notificationChannels.includes("internal")) {
      const created = await repository.insertPortalNotification({
        id: crypto.randomUUID(),
        recipient,
        eventType: "custom_process",
        title: "Neue Prozessaufgabe",
        message: `${bundle.process.title}: ${step.title}`,
        target: `/portal.html?tab=processTasks&run=${encodeURIComponent(run.id)}&step=${encodeURIComponent(step.id)}`,
        entityType: "custom_process_run",
        entityId: run.id,
        dedupeKey: `custom-process:${run.id}:${activationCount}:${step.id}`,
      });
      if (created.rowsAffected) internal += 1;
    }
    for (const channel of step.notificationChannels.filter((entry) => entry !== "internal")) {
      const result = await queueCustomProcessExternalNotification(
        bundle,
        run,
        step,
        recipient,
        channel,
        repository,
      );
      if (result.queued) external += 1;
      if (result.blocked) blocked += 1;
    }
  }
  return { internal, external, blocked };
}

async function ensureCustomProcessRunSteps(
  run,
  bundle,
  repository = customProcessRepository,
) {
  const existing = Number((await repository.countRunSteps({
    runId: run.id,
  }))?.count || 0);
  if (existing) return;
  for (const [index, step] of bundle.dto.steps.entries()) {
    await repository.insertRunStep({
      runId: run.id,
      stepId: step.id,
      sortOrder: index + 1,
    });
  }
}

async function ensureCustomProcessRunProgress(
  run,
  repository = customProcessRepository,
) {
  const freshRun = await repository.openRunById({ id: run.id });
  if (!freshRun) return { completed: true, notifications: { internal: 0, external: 0, blocked: 0 } };
  const bundle = await customProcessRunBundle(freshRun, repository);
  if (!bundle) throw httpError(503, "Die gespeicherte Prozessrevision ist nicht verfügbar.", "CUSTOM_PROCESS_REVISION_UNAVAILABLE");
  await ensureCustomProcessRunSteps(freshRun, bundle, repository);
  while (true) {
    const activeState = await repository.activeRunStep({ runId: freshRun.id });
    if (activeState) {
      const activeStep = bundle.dto.steps.find((step) => step.id === activeState.step_id);
      if (!activeStep) throw httpError(503, "Ein gespeicherter Prozessschritt ist nicht verfügbar.", "CUSTOM_PROCESS_STEP_UNAVAILABLE");
      return {
        completed: false,
        step: activeStep,
        notifications: await emitCustomProcessStepNotifications(
          bundle,
          freshRun,
          activeStep,
          repository,
        ),
      };
    }
    const pending = await repository.pendingRunStep({ runId: freshRun.id });
    if (!pending) {
      await resolveCustomProcessRun(freshRun, {
        cancelOpenSteps: false,
        repository,
      });
      return { completed: true, notifications: { internal: 0, external: 0, blocked: 0 } };
    }
    const step = bundle.dto.steps.find((entry) => entry.id === pending.step_id);
    if (!step) throw httpError(503, "Ein gespeicherter Prozessschritt ist nicht verfügbar.", "CUSTOM_PROCESS_STEP_UNAVAILABLE");
    if (step.responsibilityType === "system") {
      await repository.completeSystemRunStep({
        runId: freshRun.id,
        stepId: step.id,
      });
      continue;
    }
    const activated = await repository.activateRunStep({
      runId: freshRun.id,
      stepId: step.id,
    });
    if (!activated.rowsAffected) continue;
    return {
      completed: false,
      step,
      notifications: await emitCustomProcessStepNotifications(
        bundle,
        freshRun,
        step,
        repository,
      ),
    };
  }
}

async function createOrReopenCustomProcessRun(bundle, {
  triggerKey,
  triggeredBy,
  locationId = null,
  departmentId = null,
  reopenResolved = true,
}, repository = customProcessRepository) {
  const existing = await repository.runByTriggerKey({ triggerKey });
  if (existing) {
    if (existing.process_id !== bundle.process.id || Number(existing.process_revision) !== Number(bundle.process.revision)) {
      throw httpError(409, "Die Auslösekennung wurde bereits für einen anderen Prozess verwendet.", "CUSTOM_PROCESS_TRIGGER_CONFLICT");
    }
    if (existing.status === "resolved" && reopenResolved) {
      const reopened = await repository.reopenRun({
        id: existing.id,
        triggeredBy,
      });
      if (!reopened.rowsAffected) {
        return {
          row: await repository.runById({ id: existing.id }),
          created: false,
          reopened: false,
        };
      }
      await repository.deleteRunSteps({ runId: existing.id });
      return {
        row: await repository.runById({ id: existing.id }),
        created: false,
        reopened: true,
      };
    }
    return { row: existing, created: false, reopened: false };
  }
  const id = crypto.randomUUID();
  await repository.insertRun({
    id,
    processId: bundle.process.id,
    processRevision: bundle.process.revision,
    triggerType: bundle.process.trigger_type,
    triggerKey,
    locationId: locationId || null,
    departmentId: departmentId || null,
    triggeredBy,
  });
  return {
    row: await repository.runById({ id }),
    created: true,
    reopened: false,
  };
}

async function triggerCustomProcess(actor, id, body = {}) {
  const input = customProcessInputObject(body, "Die Prozessauslösung");
  assertCustomProcessKeys(input, new Set(["idempotencyKey"]), "Die Prozessauslösung");
  const bundle = await customProcessById(id);
  if (!bundle) throw httpError(404, "Der eigene Prozess wurde nicht gefunden.", "CUSTOM_PROCESS_NOT_FOUND");
  if (bundle.process.status !== "active") throw httpError(409, "Nur aktive Prozesse können ausgelöst werden.", "CUSTOM_PROCESS_NOT_ACTIVE");
  if (!await customProcessScopeIsActive(bundle.dto.scope)) {
    throw httpError(409, "Der Geltungsbereich des Prozesses ist nicht mehr aktiv.", "CUSTOM_PROCESS_SCOPE_INACTIVE");
  }
  const suppliedKey = String(input.idempotencyKey || "").trim();
  if (!/^[A-Za-z0-9._:-]{8,120}$/.test(suppliedKey)) {
    throw httpError(400, "Die Auslösekennung ist ungültig.", "CUSTOM_PROCESS_TRIGGER_KEY_INVALID");
  }
  const triggerKey = customProcessLookup("manual-run", `${id}:${suppliedKey}`);
  return customProcessRepository.transaction(async (repository) => {
    const currentBundle = await customProcessById(id, {}, repository);
    if (await repository.processHasWorkflowPublications({ processId: id })) {
      throw httpError(
        409,
        "Veröffentlichte Personal-Workflows können nur als kontrollierte Personalinstanz gestartet werden.",
        "CUSTOM_PROCESS_PERSONNEL_INSTANCE_REQUIRED",
      );
    }
    if (!currentBundle || currentBundle.process.status !== "active") {
      throw httpError(409, "Nur aktive Prozesse können ausgelöst werden.", "CUSTOM_PROCESS_NOT_ACTIVE");
    }
    if (!await customProcessScopeIsActive(currentBundle.dto.scope, repository)) {
      throw httpError(409, "Der Geltungsbereich des Prozesses ist nicht mehr aktiv.", "CUSTOM_PROCESS_SCOPE_INACTIVE");
    }
    const result = await createOrReopenCustomProcessRun(currentBundle, {
      triggerKey,
      triggeredBy: actor.employeeNumber,
      reopenResolved: false,
    }, repository);
    const progress = await ensureCustomProcessRunProgress(result.row, repository);
    const notifications = progress.notifications;
    if (result.created || result.reopened) {
      await repository.insertAudit({
        actor: actor.employeeNumber,
        action: "custom-process.trigger",
        entityType: "custom_process_run",
        entityId: result.row.id,
        detail: JSON.stringify({
          processId: id,
          revision: currentBundle.process.revision,
          trigger: "manual",
          ...notifications,
        }),
      });
    }
    return {
      run: customProcessRunPublic(result.row),
      notifications,
      duplicate: !result.created && !result.reopened,
    };
  });
}

async function customProcessStaffingContexts(
  bundle,
  date,
  repository = customProcessRepository,
) {
  const scope = bundle.dto.scope;
  if (scope?.valid === false) return [];
  const locationRows = scope.type === "company"
    ? await repository.listActiveLocations()
    : [await repository.activeLocation({ locationId: scope.locationId })].filter(Boolean);
  const contexts = [];
  for (const locationRow of locationRows) {
    const locationId = String(locationRow.id || "");
    if (!locationId) continue;
    if (isVacationHoliday(date, locationId) || getGlobalDayBlockForDate(date, locationId)) continue;
    const day = await dayConfiguration(date, await settingsForLocation(locationId), { locationId, departmentId: null });
    if (!day?.open || !isTime(day.minFrom) || !isTime(day.minTo) || day.minTo <= day.minFrom) continue;
    const department = scope.type === "department"
      ? await repository.activeDepartmentStaffing({
        departmentId: scope.departmentId,
        locationId,
      })
      : null;
    if (scope.type === "department" && !department) continue;
    const departmentId = department ? Number(department.id) : null;
    const required = department ? Number(department.min_staff || 0) : Number(day.minStaff || 0);
    if (required <= 0) continue;
    const context = { locationId, departmentId };
    const input = await vacationCoverageInputForDate(null, date, context);
    let worstShortfall = 0;
    let firstCriticalTime = "";
    const fromMinute = timeToMinutes(day.minFrom);
    const toMinute = timeToMinutes(day.minTo);
    for (let minute = fromMinute; minute < toMinute; minute += 15) {
      const pointTime = minutesToTime(minute);
      const nextPointTime = minutesToTime(Math.min(toMinute, minute + 15));
      const unavailable = vacationUnavailableAt(input, null, pointTime, nextPointTime);
      const counts = vacationCoverageCountsAt(input, unavailable, context, pointTime);
      const available = departmentId ? counts.departmentScheduled : counts.locationScheduled;
      const shortfall = Math.max(0, required - available);
      if (shortfall > worstShortfall) {
        worstShortfall = shortfall;
        firstCriticalTime = pointTime;
      }
    }
    if (worstShortfall >= bundle.process.trigger_minimum_shortfall) {
      contexts.push({ locationId, departmentId, shortfall: worstShortfall, firstCriticalTime });
    }
  }
  return contexts;
}

async function resolveCustomProcessRun(
  run,
  {
    cancelOpenSteps = true,
    repository = customProcessRepository,
  } = {},
) {
  if (cancelOpenSteps) {
    await repository.skipOpenRunSteps({ runId: run.id });
  }
  await repository.resolveRun({ runId: run.id });
  await repository.markRunNotificationsRead({ runId: run.id });
  await repository.cancelOutboundJobsByEntity({
    entityLookup: customProcessLookup("run", run.id),
    purgeAfter: addDays(viennaTodayIso(), OUTBOUND_NOTIFICATION_CANCELLED_RETENTION_DAYS),
  });
}

async function reconcileCustomProcessTriggers(now = new Date()) {
  const date = viennaTodayIso(now);
  const activeKeys = new Set();
  let checked = 0;
  let triggered = 0;
  for (const bundle of (await customProcessRows()).filter(({ process }) => process.status === "active" && process.trigger_type === "staffing_shortfall")
    .map(({ process, steps }) => ({ process, steps, dto: customProcessDashboardDefinition(process, steps) }))) {
    const published = await customProcessRepository.processHasWorkflowPublications({
      processId: bundle.process.id,
    });
    checked += 1;
    for (const context of await customProcessStaffingContexts(bundle, date)) {
      const triggerKey = customProcessLookup("staffing-run", `${bundle.process.id}:${bundle.process.revision}:${date}:${context.locationId}:${context.departmentId || 0}`);
      activeKeys.add(triggerKey);
      if (published) continue;
      const changed = await customProcessRepository.transaction(async (repository) => {
        const current = await customProcessById(bundle.process.id, {}, repository);
        if (!current
            || current.process.status !== "active"
            || current.process.trigger_type !== "staffing_shortfall"
            || Number(current.process.revision) !== Number(bundle.process.revision)) return false;
        if (await repository.processHasWorkflowPublications({
          processId: current.process.id,
        })) return false;
        const result = await createOrReopenCustomProcessRun(
          current,
          { triggerKey, triggeredBy: "system", ...context },
          repository,
        );
        const progress = await ensureCustomProcessRunProgress(result.row, repository);
        if (result.created || result.reopened) {
          await repository.insertAudit({
            actor: "system",
            action: "custom-process.trigger",
            entityType: "custom_process_run",
            entityId: result.row.id,
            detail: JSON.stringify({
              processId: current.process.id,
              revision: current.process.revision,
              trigger: "staffing_shortfall",
              shortfall: context.shortfall,
              ...progress.notifications,
            }),
          });
          return true;
        }
        return false;
      });
      if (changed) triggered += 1;
    }
  }
  let resolved = 0;
  const openRuns = await customProcessRepository.listOpenStaffingRuns();
  for (const run of openRuns) {
    if (activeKeys.has(run.trigger_key)) continue;
    await customProcessRepository.transaction((repository) => (
      resolveCustomProcessRun(run, { repository })
    ));
    resolved += 1;
  }
  let retried = 0;
  const remainingRuns = await customProcessRepository.listOpenRuns();
  for (const run of remainingRuns) {
    const result = await customProcessRepository.transaction(async (repository) => {
      const currentRun = await repository.openRunById({ id: run.id });
      if (!currentRun) return { resolved: false, retried: 0 };
      const bundle = await customProcessRunBundle(currentRun, repository);
      if (!bundle) return { resolved: false, retried: 0 };
      const scope = customProcessEffectiveScope(bundle, currentRun);
      if (!await customProcessScopeIsActive(scope, repository)) {
        await resolveCustomProcessRun(currentRun, { repository });
        return { resolved: true, retried: 0 };
      }
      const progress = await ensureCustomProcessRunProgress(currentRun, repository);
      return {
        resolved: false,
        retried: Number(progress.notifications?.external || 0),
      };
    });
    if (result.resolved) resolved += 1;
    retried += result.retried;
  }
  return { checked, triggered, resolved, retried };
}

function customProcessRunScopeLabel(run, bundle) {
  if (run.department_id && run.run_department_name && run.run_department_location_name) {
    return `${run.run_department_location_name} · ${run.run_department_name}`;
  }
  if (run.location_id && run.run_location_name) return run.run_location_name;
  return bundle.dto.scope?.label || "Gesamtes Unternehmen";
}

async function customProcessTasksForEmployee(
  employeeNumber,
  repository = customProcessRepository,
) {
  const runs = await repository.listActiveTaskRuns();
  const items = [];
  for (const run of runs) {
    const bundle = await customProcessRunBundle(run, repository);
    if (!bundle) continue;
    const step = bundle.dto.steps.find((entry) => entry.id === run.step_id);
    if (!step || !(await customProcessRecipients(bundle, step, run, repository))
      .includes(String(employeeNumber))) continue;
    const counts = await repository.runStepCounts({ runId: run.id });
    items.push({
      runId: run.id,
      processId: run.process_id,
      processRevision: Number(run.process_revision || 1),
      activationCount: Math.max(1, Number(run.activation_count || 1)),
      processTitle: bundle.dto.title,
      processSymbol: bundle.dto.symbol,
      stepId: step.id,
      stepTitle: step.title,
      stepDescription: step.description,
      conditionType: step.conditionType,
      conditionText: step.conditionText,
      canSkip: step.conditionType !== "always",
      scopeLabel: customProcessRunScopeLabel(run, bundle),
      progress: { finished: Number(counts?.finished || 0), total: Number(counts?.total || bundle.dto.steps.length) },
      position: Number(run.sort_order || 1),
      stepCount: Number(counts?.total || bundle.dto.steps.length),
      status: "active",
      canComplete: true,
      activatedAt: run.activated_at || run.created_at,
      assignedAt: run.activated_at || run.created_at,
      createdAt: run.created_at,
    });
  }
  return items;
}

function personnelWorkflowTaskScopeLabel(scope = {}) {
  if (scope.type === "department") return "Freigegebener Abteilungsbereich";
  if (scope.type === "location") return "Freigegebener Standortbereich";
  return "Gesamtes Unternehmen";
}

function personnelWorkflowPortalTask(item) {
  const activatedAt = item.step?.activatedAt || null;
  const completedSteps = Number(item.progress?.completedSteps || 0);
  const totalSteps = Number(item.progress?.totalSteps || 0);
  return Object.freeze({
    runId: item.runId,
    processId: item.workflowCode,
    processRevision: Number(item.versionNumber),
    activationCount: 1,
    processTitle: item.workflowTitle,
    processSymbol: "P",
    stepId: item.step.id,
    stepTitle: item.step.title,
    stepDescription: "",
    conditionType: item.step.canSkip ? "conditional" : "always",
    conditionText: "",
    canSkip: item.step.canSkip,
    scopeLabel: personnelWorkflowTaskScopeLabel(item.scope),
    progress: {
      completedSteps,
      totalSteps,
      finished: completedSteps,
      total: totalSteps,
    },
    position: Number(item.step.position),
    stepCount: totalSteps,
    status: "active",
    canComplete: true,
    completionNoteRequired: false,
    activatedAt,
    assignedAt: activatedAt,
    createdAt: activatedAt,
    personnelWorkflow: true,
    subjectType: item.subjectType,
    workflowCode: item.workflowCode,
    versionNumber: Number(item.versionNumber),
    workflowTitle: item.workflowTitle,
    step: Object.freeze({ ...item.step }),
    scope: Object.freeze({ type: item.scope?.type || "company" }),
  });
}

async function processTasksForPortalSession(session) {
  const legacyItems = await customProcessTasksForEmployee(session.employeeNumber);
  if (!installationFeatureEnabled("personnelLifecycle")) return legacyItems;
  const workflowAccess = createPersonnelWorkflowAccessSnapshot(session);
  if (workflowAccess.canReadInstances !== true) return legacyItems;
  const result = await requirePersonnelWorkflowInstanceService().tasksForEmployee(
    session.employeeNumber,
    {
      access: personnelWorkflowInstanceAccessForSession(session, workflowAccess),
    },
  );
  return [...legacyItems, ...result.items.map(personnelWorkflowPortalTask)]
    .sort((left, right) => (
      String(right.assignedAt || right.createdAt || "")
        .localeCompare(String(left.assignedAt || left.createdAt || ""))
      || String(left.runId).localeCompare(String(right.runId))
    ));
}

async function completeCustomProcessTask(actor, runId, stepId, body = {}) {
  const input = customProcessInputObject(body, "Die Prozessaufgabe");
  assertCustomProcessKeys(input, new Set(["action", "note", "idempotencyKey", "activationCount"]), "Die Prozessaufgabe");
  const action = String(input.action || "complete").trim();
  if (!new Set(["complete", "skip"]).has(action)) {
    throw httpError(400, "Die Aufgabenentscheidung ist ungültig.", "CUSTOM_PROCESS_TASK_ACTION_INVALID");
  }
  const idempotencyKey = String(input.idempotencyKey || "").trim();
  if (!/^[A-Za-z0-9._:-]{8,120}$/.test(idempotencyKey)) {
    throw httpError(400, "Die Bearbeitungskennung ist ungültig.", "CUSTOM_PROCESS_TASK_IDEMPOTENCY_INVALID");
  }
  const activationCount = Number(input.activationCount);
  if (!Number.isInteger(activationCount) || activationCount < 1) {
    throw httpError(400, "Die Prozessaktivierung ist ungültig.", "CUSTOM_PROCESS_TASK_ACTIVATION_INVALID");
  }
  const note = customProcessText(input.note, { label: "Die Aufgabenbemerkung", max: 500 });
  return customProcessRepository.transaction(async (repository) => {
    const run = await repository.runById({ id: String(runId || "") });
    if (!run) throw httpError(404, "Die Prozessaufgabe wurde nicht gefunden.", "CUSTOM_PROCESS_TASK_NOT_FOUND");
    if (Math.max(1, Number(run.activation_count || 1)) !== activationCount) {
      throw httpError(409, "Diese Prozessaufgabe gehört zu einer früheren Aktivierung.", "CUSTOM_PROCESS_TASK_ACTIVATION_CONFLICT");
    }
    const bundle = await customProcessRunBundle(run, repository);
    const step = bundle?.dto.steps.find((entry) => entry.id === String(stepId || ""));
    const state = await repository.runStepById({
      runId: run.id,
      stepId: String(stepId || ""),
    });
    if (state && ["completed", "skipped"].includes(state.status)
        && state.completed_by === String(actor.employeeNumber)
        && state.completion_request_id === idempotencyKey) {
      return { ok: true, duplicate: true, run: customProcessRunPublic(run) };
    }
    if (!bundle || !step || !state
        || !(await customProcessRecipients(bundle, step, run, repository))
          .includes(String(actor.employeeNumber))) {
      throw httpError(404, "Die Prozessaufgabe wurde nicht gefunden.", "CUSTOM_PROCESS_TASK_NOT_FOUND");
    }
    if (run.status !== "open" || state.status !== "active") {
      throw httpError(409, "Die Prozessaufgabe wurde bereits bearbeitet.", "CUSTOM_PROCESS_TASK_CONFLICT");
    }
    if (action === "skip" && step.conditionType === "always") {
      throw httpError(400, "Ein verpflichtender Prozessschritt kann nicht übersprungen werden.", "CUSTOM_PROCESS_TASK_SKIP_FORBIDDEN");
    }
    const updated = await repository.completeRunStep({
      status: action === "skip" ? "skipped" : "completed",
      actor: actor.employeeNumber,
      note,
      idempotencyKey,
      runId: run.id,
      stepId: step.id,
    });
    if (!updated.rowsAffected) throw httpError(409, "Die Prozessaufgabe wurde bereits bearbeitet.", "CUSTOM_PROCESS_TASK_CONFLICT");
    await repository.markTaskNotificationRead({
      recipient: actor.employeeNumber,
      dedupeKey: `custom-process:${run.id}:${Math.max(1, Number(run.activation_count || 1))}:${step.id}`,
    });
    const progress = await ensureCustomProcessRunProgress(run, repository);
    await repository.insertAudit({
      actor: actor.employeeNumber,
      action: action === "skip" ? "custom-process.task.skip" : "custom-process.task.complete",
      entityType: "custom_process_run",
      entityId: run.id,
      detail: JSON.stringify({
        processId: run.process_id,
        revision: run.process_revision,
        stepId: step.id,
      }),
    });
    return {
      ok: true,
      run: customProcessRunPublic(await repository.runById({ id: run.id })),
      progress,
    };
  });
}

async function customProcessTaskOwnedByActor(
  actor,
  runId,
  stepId,
  repository = customProcessRepository,
) {
  const run = await repository.runById({ id: String(runId || "") });
  if (!run) return false;
  const bundle = await customProcessRunBundle(run, repository);
  const step = bundle?.dto.steps.find((entry) => entry.id === String(stepId || ""));
  const state = await repository.runStepById({
    runId: run.id,
    stepId: String(stepId || ""),
  });
  if (!bundle || !step || !state) return false;
  if (["completed", "skipped"].includes(state.status)) {
    return state.completed_by === String(actor.employeeNumber);
  }
  return run.status === "open"
    && state.status === "active"
    && (await customProcessRecipients(bundle, step, run, repository))
      .includes(String(actor.employeeNumber));
}

function customProcessTaskNotFoundError() {
  return httpError(
    404,
    "Die Prozessaufgabe wurde nicht gefunden.",
    "CUSTOM_PROCESS_TASK_NOT_FOUND",
  );
}

