const PERSONNEL_LIFECYCLE_SCOPED_DELEGABLE_PERMISSIONS = Object.freeze([
  PERSONNEL_LIFECYCLE_PERMISSIONS.CANDIDATES_READ,
  PERSONNEL_LIFECYCLE_PERMISSIONS.APPLICATIONS_WRITE,
  PERSONNEL_WORKFLOW_PERMISSIONS.READ,
  PERSONNEL_WORKFLOW_PERMISSIONS.DRAFT_WRITE,
  PERSONNEL_WORKFLOW_PERMISSIONS.PUBLISH,
  PERSONNEL_WORKFLOW_PERMISSIONS.LOCAL_SUPPLEMENT,
  PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.OPERATIONAL_READ,
  PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.OPERATIONAL_UPDATE,
  ...PERSONNEL_PROFILE_SCOPED_PERMISSIONS,
]);

function publicPortalPermissionScopeGrant(scope) {
  return {
    permission: String(scope.permission || ""),
    locationId: String(scope.locationId ?? scope.location_id ?? ""),
    departmentId: Number(scope.departmentId ?? scope.department_id ?? 0) || null,
    approvedBy: String(scope.approvedBy ?? scope.approved_by ?? ""),
  };
}

function personnelLifecyclePermissionScopeKey(scope) {
  return [
    String(scope.permission || ""),
    String(scope.locationId ?? scope.location_id ?? ""),
    Number(scope.departmentId ?? scope.department_id ?? 0) || 0,
  ].join("\u0000");
}

function actorCanManageProtectedPersonnelState(actor, permissions = [], permissionScopes = []) {
  const manageable = manageablePortalPermissionsForActor(actor);
  return permissions.every((permission) => manageable.has(String(permission || "")))
    && permissionScopes.every((scope) => manageable.has(String(scope?.permission || "")));
}

function portalAccessScopeKey(scope) {
  return [
    String(scope.locationId ?? scope.location_id ?? ""),
    Number(scope.departmentId ?? scope.department_id ?? 0) || 0,
  ].join("\u0000");
}

function canonicalPermissionScopeValue(scope) {
  const normalized = publicPortalPermissionScopeGrant(scope);
  return [
    personnelLifecyclePermissionScopeKey(normalized),
    normalized.approvedBy,
  ].join("\u0000");
}

function sortedUniqueValues(values, mapper = (value) => String(value || "")) {
  return [...new Set((Array.isArray(values) ? values : [...(values || [])])
    .map(mapper))].sort();
}

function collectionAuditSummary(values, mapper) {
  const canonical = sortedUniqueValues(values, mapper);
  return Object.freeze({ count: canonical.length, sha256: sha256(JSON.stringify(canonical)) });
}

function stringDelta(beforeValues, afterValues) {
  const before = new Set(sortedUniqueValues(beforeValues));
  const after = new Set(sortedUniqueValues(afterValues));
  return Object.freeze({
    added: [...after].filter((value) => !before.has(value)).sort(),
    removed: [...before].filter((value) => !after.has(value)).sort(),
  });
}

function rightsAuditSummary(snapshot = {}) {
  return Object.freeze({
    granted: collectionAuditSummary(snapshot.grantedPermissions || []),
    denied: collectionAuditSummary(snapshot.deniedPermissions || []),
    effective: collectionAuditSummary(snapshot.effectivePermissions || []),
    scopes: collectionAuditSummary(snapshot.scopes || [], portalAccessScopeKey),
    personnelLifecycleScopes: collectionAuditSummary(
      snapshot.personnelLifecyclePermissionScopes || [],
      canonicalPermissionScopeValue,
    ),
    personnelLearningCrossLocationDenialAuthority:
      snapshot.personnelLearningCrossLocationDenialAuthority || null,
  });
}

function defaultStartDashboardPreferences() {
  return {
    version: 3,
    order: [...UI_START_DASHBOARD_CARDS],
    hidden: [],
    hiddenWidgets: [],
    groupSizes: Object.fromEntries(UI_START_DASHBOARD_GROUPS.map((id) => [id, "standard"])),
    locationId: "",
    departmentId: "",
    salesLocationId: "",
  };
}

function normalizeStartDashboardPreferences(value) {
  const fallback = defaultStartDashboardPreferences();
  const version = Number(value?.version);
  if (!value || typeof value !== "object" || Array.isArray(value) || ![1, 2, 3].includes(version)) {
    return fallback;
  }
  const normalizeScopeId = (candidate, pattern) => {
    const normalized = String(candidate || "").trim();
    return normalized.length <= 80 && pattern.test(normalized) ? normalized : "";
  };
  const legacyHidden = version === 1 ? value.hidden : value.hiddenWidgets;
  const submittedOrder = version >= 2 && Array.isArray(value.order)
    ? [...new Set(value.order.map(String))].filter((id) => UI_START_DASHBOARD_CARD_SET.has(id))
    : [];
  const submittedGroupSizes = version === 3 && value.groupSizes && typeof value.groupSizes === "object" && !Array.isArray(value.groupSizes)
    ? value.groupSizes
    : {};
  return {
    version: 3,
    order: [...submittedOrder, ...UI_START_DASHBOARD_CARDS.filter((id) => !submittedOrder.includes(id))],
    hidden: version >= 2 && Array.isArray(value.hidden)
      ? [...new Set(value.hidden.map(String))].filter((id) => UI_START_DASHBOARD_CARD_SET.has(id))
      : [],
    hiddenWidgets: Array.isArray(legacyHidden)
      ? [...new Set(legacyHidden.map(String))].filter((id) => UI_START_DASHBOARD_WIDGET_SET.has(id))
      : [],
    groupSizes: Object.fromEntries(UI_START_DASHBOARD_GROUPS.map((id) => [
      id,
      UI_START_DASHBOARD_GROUP_SIZE_SET.has(String(submittedGroupSizes[id]))
        ? String(submittedGroupSizes[id])
        : "standard",
    ])),
    locationId: normalizeScopeId(value.locationId, /^[A-Za-z0-9._:-]*$/),
    departmentId: normalizeScopeId(value.departmentId, /^\d*$/),
    salesLocationId: normalizeScopeId(value.salesLocationId, /^[A-Za-z0-9._:-]*$/),
  };
}

function validateStartDashboardPreferences(value) {
  const version = Number(value?.version);
  const allowedKeys = version === 1
    ? ["version", "hidden", "locationId", "departmentId", "salesLocationId"]
    : version === 2
      ? ["version", "order", "hidden", "hiddenWidgets", "locationId", "departmentId", "salesLocationId"]
      : ["version", "order", "hidden", "hiddenWidgets", "groupSizes", "locationId", "departmentId", "salesLocationId"];
  const invalidLegacy = version === 1 && (
    !Array.isArray(value.hidden)
    || value.hidden.length > UI_START_DASHBOARD_WIDGETS.length
    || new Set(value.hidden.map(String)).size !== value.hidden.length
    || value.hidden.some((id) => !UI_START_DASHBOARD_WIDGET_SET.has(String(id)))
  );
  const invalidCurrent = [2, 3].includes(version) && (
    !Array.isArray(value.order)
    || value.order.length > UI_START_DASHBOARD_CARDS.length
    || new Set(value.order.map(String)).size !== value.order.length
    || value.order.some((id) => !UI_START_DASHBOARD_CARD_SET.has(String(id)))
    || !Array.isArray(value.hidden)
    || value.hidden.length > UI_START_DASHBOARD_CARDS.length
    || new Set(value.hidden.map(String)).size !== value.hidden.length
    || value.hidden.some((id) => !UI_START_DASHBOARD_CARD_SET.has(String(id)))
    || !Array.isArray(value.hiddenWidgets)
    || value.hiddenWidgets.length > UI_START_DASHBOARD_WIDGETS.length
    || new Set(value.hiddenWidgets.map(String)).size !== value.hiddenWidgets.length
    || value.hiddenWidgets.some((id) => !UI_START_DASHBOARD_WIDGET_SET.has(String(id)))
    || (version === 3 && (
      !value.groupSizes || typeof value.groupSizes !== "object" || Array.isArray(value.groupSizes)
      || Object.keys(value.groupSizes).length !== UI_START_DASHBOARD_GROUPS.length
      || Object.keys(value.groupSizes).some((id) => !UI_START_DASHBOARD_GROUP_SET.has(id))
      || UI_START_DASHBOARD_GROUPS.some((id) => !UI_START_DASHBOARD_GROUP_SIZE_SET.has(String(value.groupSizes[id])))
    ))
  );
  if (!value || typeof value !== "object" || Array.isArray(value)
    || ![1, 2, 3].includes(version)
    || Object.keys(value).some((key) => !allowedKeys.includes(key))
    || invalidLegacy
    || invalidCurrent
    || ![value.locationId, value.salesLocationId].every((id) => typeof id === "string" && id.length <= 80 && /^[A-Za-z0-9._:-]*$/.test(id))
    || typeof value.departmentId !== "string" || value.departmentId.length > 20 || !/^\d*$/.test(value.departmentId)) {
    throw httpError(400, "Bitte eine gültige persönliche Startdashboard-Konfiguration übermitteln.", "UI_PREFERENCES_INVALID");
  }
  return normalizeStartDashboardPreferences(value);
}

function compactRightsAuditDetail(before = {}, after = {}) {
  const lifecycleRights = (values) => (values || [])
    .filter((permission) => personnelLifecyclePermissionIds.has(permission));
  const scopeBefore = sortedUniqueValues(
    before.personnelLifecyclePermissionScopes || [],
    canonicalPermissionScopeValue,
  );
  const scopeAfter = sortedUniqueValues(
    after.personnelLifecyclePermissionScopes || [],
    canonicalPermissionScopeValue,
  );
  const detail = {
    schemaVersion: 2,
    before: rightsAuditSummary(before),
    after: rightsAuditSummary(after),
    personnelLifecycleDelta: {
      granted: stringDelta(
        lifecycleRights(before.grantedPermissions),
        lifecycleRights(after.grantedPermissions),
      ),
      denied: stringDelta(
        lifecycleRights(before.deniedPermissions),
        lifecycleRights(after.deniedPermissions),
      ),
      effective: stringDelta(
        lifecycleRights(before.effectivePermissions),
        lifecycleRights(after.effectivePermissions),
      ),
      scopes: {
        added: collectionAuditSummary(scopeAfter.filter((value) => !scopeBefore.includes(value))),
        removed: collectionAuditSummary(scopeBefore.filter((value) => !scopeAfter.includes(value))),
      },
    },
  };
  const serialized = JSON.stringify(detail);
  if (serialized.length <= 1900) return serialized;
  const compacted = JSON.stringify({
    schemaVersion: 2,
    compacted: true,
    detailSha256: sha256(serialized),
    before: detail.before,
    after: detail.after,
    personnelLifecycleDelta: {
      granted: {
        added: collectionAuditSummary(detail.personnelLifecycleDelta.granted.added),
        removed: collectionAuditSummary(detail.personnelLifecycleDelta.granted.removed),
      },
      denied: {
        added: collectionAuditSummary(detail.personnelLifecycleDelta.denied.added),
        removed: collectionAuditSummary(detail.personnelLifecycleDelta.denied.removed),
      },
      effective: {
        added: collectionAuditSummary(detail.personnelLifecycleDelta.effective.added),
        removed: collectionAuditSummary(detail.personnelLifecycleDelta.effective.removed),
      },
      scopes: detail.personnelLifecycleDelta.scopes,
    },
  });
  if (compacted.length <= 1900) return compacted;
  return JSON.stringify({
    schemaVersion: 2,
    compacted: true,
    detailSha256: sha256(serialized),
    beforeSha256: sha256(JSON.stringify(detail.before)),
    afterSha256: sha256(JSON.stringify(detail.after)),
    personnelLifecycleDeltaSha256: sha256(JSON.stringify(detail.personnelLifecycleDelta)),
  });
}

function compactPortalUserAuditDetail({
  roleBefore = null,
  roleAfter = null,
  active = false,
  passwordReset = false,
  personnelLifecycleRightsReset = [],
  personnelLifecyclePermissionScopesBefore = [],
  personnelLifecyclePermissionScopesAfter = [],
} = {}) {
  const beforeScopes = sortedUniqueValues(
    personnelLifecyclePermissionScopesBefore,
    canonicalPermissionScopeValue,
  );
  const afterScopes = sortedUniqueValues(
    personnelLifecyclePermissionScopesAfter,
    canonicalPermissionScopeValue,
  );
  const detail = {
    schemaVersion: 2,
    roleBefore,
    roleAfter,
    active: Boolean(active),
    passwordReset: Boolean(passwordReset),
    personnelLifecycleRightsReset: sortedUniqueValues(personnelLifecycleRightsReset),
    personnelLifecyclePermissionScopes: {
      before: collectionAuditSummary(beforeScopes),
      after: collectionAuditSummary(afterScopes),
      added: collectionAuditSummary(beforeScopes.length || afterScopes.length
        ? afterScopes.filter((scope) => !beforeScopes.includes(scope))
        : []),
      removed: collectionAuditSummary(beforeScopes.length || afterScopes.length
        ? beforeScopes.filter((scope) => !afterScopes.includes(scope))
        : []),
    },
  };
  const serialized = JSON.stringify(detail);
  if (serialized.length <= 1900) return serialized;
  const summarizedRole = (value) => {
    if (value === null || value === undefined) return null;
    const normalized = String(value);
    return { length: normalized.length, sha256: sha256(normalized) };
  };
  return JSON.stringify({
    schemaVersion: 2,
    compacted: true,
    detailSha256: sha256(serialized),
    roleBefore: summarizedRole(roleBefore),
    roleAfter: summarizedRole(roleAfter),
    active: Boolean(active),
    passwordReset: Boolean(passwordReset),
    personnelLifecycleRightsReset: collectionAuditSummary(personnelLifecycleRightsReset),
    personnelLifecyclePermissionScopes: detail.personnelLifecyclePermissionScopes,
  });
}

function rightsConcurrencySignature({ target, rolePermissions = [], snapshot = {} }) {
  return sha256(JSON.stringify({
    target: target ? {
      employeeNumber: String(target.employee_number ?? target.employeeNumber ?? ""),
      role: String(target.role || ""),
      active: Boolean(target.active),
      roleLocked: Boolean(target.role_locked ?? target.roleLocked),
    } : null,
    rolePermissions: sortedUniqueValues(rolePermissions),
    grantedPermissions: sortedUniqueValues(snapshot.grantedPermissions || []),
    deniedPermissions: sortedUniqueValues(snapshot.deniedPermissions || []),
    scopes: sortedUniqueValues(snapshot.scopes || [], portalAccessScopeKey),
    personnelLifecyclePermissionScopes: sortedUniqueValues(
      snapshot.personnelLifecyclePermissionScopes || [],
      canonicalPermissionScopeValue,
    ),
    personnelLearningCrossLocationDenialAuthority:
      snapshot.personnelLearningCrossLocationDenialAuthority || null,
  }));
}

function scopeMutationConcurrencySignature(target, scopes, permissionScopes) {
  return sha256(JSON.stringify({
    target: target ? {
      employeeNumber: String(target.employee_number ?? target.employeeNumber ?? ""),
      role: String(target.role || ""),
      roleLocked: Boolean(target.role_locked ?? target.roleLocked),
      active: Boolean(target.active),
      homeLocationId: String(target.home_location_id ?? target.homeLocationId ?? ""),
    } : null,
    scopes: sortedUniqueValues(scopes || [], portalAccessScopeKey),
    permissionScopes: sortedUniqueValues(
      permissionScopes || [],
      canonicalPermissionScopeValue,
    ),
  }));
}

function portalUserMutationConcurrencySignature(
  user,
  lifecycleGrants = [],
  lifecycleScopes = [],
  protectedBirthdayPresentationRights = [],
) {
  return sha256(JSON.stringify({
    user: user ? {
      employeeNumber: String(user.employee_number ?? user.employeeNumber ?? ""),
      role: String(user.role || ""),
      roleLocked: Boolean(user.role_locked ?? user.roleLocked),
      active: Boolean(user.active),
      mustChangePassword: Boolean(user.must_change_password ?? user.mustChangePassword),
      passwordHash: String(user.password_hash ?? user.passwordHash ?? ""),
    } : null,
    lifecycleGrants: sortedUniqueValues(lifecycleGrants),
    lifecycleScopes: sortedUniqueValues(lifecycleScopes, canonicalPermissionScopeValue),
    protectedBirthdayPresentationRights: sortedUniqueValues(
      protectedBirthdayPresentationRights,
    ),
  }));
}

function assertRightsMutationSnapshotCurrent(expected, actual) {
  if (expected === actual) return;
  throw personnelLifecycleConcurrentChangeError();
}

function setDifference(currentValues, desiredValues, key) {
  const current = new Map((currentValues || []).map((value) => [key(value), value]));
  const desired = new Map((desiredValues || []).map((value) => [key(value), value]));
  return Object.freeze({
    added: [...desired].filter(([scopeKey]) => !current.has(scopeKey)).map(([, value]) => value),
    removed: [...current].filter(([scopeKey]) => !desired.has(scopeKey)).map(([, value]) => value),
  });
}

function assertPersonnelLearningPortalScopeDeltaAllowed(
  actor,
  target,
  currentScopes,
  desiredScopes,
) {
  const delta = setDifference(currentScopes, desiredScopes, portalAccessScopeKey);
  if ((!delta.added.length && !delta.removed.length)
    || !roleHasPersonnelLearningDefaults(target?.role)) {
    return delta;
  }
  assertPersonnelLearningRoleAccountAdministrationAllowed(actor, target);
  return delta;
}

function personnelLifecycleScopeMatchesTarget(target, scope, portalScopes) {
  const locationId = String(scope.locationId || "");
  const departmentId = Number(scope.departmentId || 0) || null;
  if (target.role === "manager") {
    return departmentId === null && portalScopes.some((entry) => (
      entry.locationId === locationId && !entry.departmentId
    ));
  }
  if (target.role === "department_manager") {
    return departmentId !== null && portalScopes.some((entry) => (
      entry.locationId === locationId && Number(entry.departmentId || 0) === departmentId
    ));
  }
  return false;
}

function personnelLifecycleScopesForTarget(target, portalScopes) {
  if (target.role === "manager") {
    return portalScopes
      .filter((scope) => !scope.departmentId)
      .map((scope) => ({ locationId: scope.locationId, departmentId: null }));
  }
  if (target.role === "department_manager") {
    return portalScopes
      .filter((scope) => Number(scope.departmentId || 0) > 0)
      .map((scope) => ({
        locationId: scope.locationId,
        departmentId: Number(scope.departmentId),
      }));
  }
  return [];
}

function planPersonnelLifecyclePermissionScopes({
  actor,
  target,
  portalScopes,
  currentGrants,
  finalDirectGrants,
  currentPermissionScopes,
  manageablePermissions,
  scopesInputProvided,
}) {
  if (!["manager", "department_manager"].includes(target.role)) return [];
  const derivedScopes = personnelLifecycleScopesForTarget(target, portalScopes);
  const currentByPermission = new Map(PERSONNEL_LIFECYCLE_SCOPED_DELEGABLE_PERMISSIONS
    .map((permission) => [permission, currentPermissionScopes
      .filter((scope) => scope.permission === permission)
      .filter((scope) => personnelLifecycleScopeMatchesTarget(target, scope, portalScopes))]));
  const planned = [];
  for (const permission of PERSONNEL_LIFECYCLE_SCOPED_DELEGABLE_PERMISSIONS) {
    if (!finalDirectGrants.has(permission)) continue;
    const current = currentByPermission.get(permission) || [];
    const newlyGranted = !currentGrants.has(permission);
    const mayRewrite = manageablePermissions.has(permission);
    const rewrite = mayRewrite && (scopesInputProvided || newlyGranted || !current.length);
    const selected = rewrite
      ? derivedScopes.map((scope) => ({ ...scope, approvedBy: actor.employeeNumber }))
      : current;
    if (rewrite && !selected.length) {
      throw httpError(
        400,
        target.role === "manager"
          ? "Für lokale Personalmodul-Rechte muss PL+ mindestens einen ganzen Standort freigeben."
          : "Für lokale Personalmodul-Rechte muss PL+ mindestens eine konkrete Abteilung freigeben.",
        "PERSONNEL_LIFECYCLE_PERMISSION_SCOPE_REQUIRED",
      );
    }
    for (const scope of selected) {
      planned.push({
        employeeNumber: target.employeeNumber,
        permission,
        locationId: scope.locationId,
        departmentId: Number(scope.departmentId || 0),
        approvedBy: scope.approvedBy || actor.employeeNumber,
      });
    }
  }
  return planned;
}

async function normalizeRightsScopesForTarget(target, submittedScopes, projectedPermissions) {
  if (GLOBAL_SCOPE_PORTAL_ROLES.has(target.role)) {
    if (Array.isArray(submittedScopes) && submittedScopes.length) {
      throw httpError(400, "Globale Rollen benötigen keine Standort- oder Abteilungszuweisung.", "PORTAL_SCOPE_GLOBAL_ROLE");
    }
    return [];
  }
  const scheduleAccess = projectedPermissions.includes("schedule:read") || projectedPermissions.includes("schedule:write");
  const source = Array.isArray(submittedScopes)
    ? submittedScopes
    : await explicitPortalAccessScopesForEmployee(target.employeeNumber);
  let scopes = source.map((scope) => ({
    locationId: normalizeLocationId(scope?.locationId),
    departmentId: normalizeDepartmentId(scope?.departmentId, true),
  }));
  if (!scopes.length && scheduleAccess && target.homeLocationId) {
    const preferredDepartmentId = Number(target.preferredDepartmentId || 0) || null;
    if (["location_planner", "manager"].includes(target.role) || preferredDepartmentId) {
      scopes = [{
        locationId: target.homeLocationId,
        departmentId: ["location_planner", "manager"].includes(target.role) ? null : preferredDepartmentId,
      }];
    }
  }
  const unique = new Map();
  for (const scope of scopes) {
    if (scope.locationId !== target.homeLocationId) {
      throw httpError(403, "Planungsrechte dürfen nur für die eigene Stammfiliale vergeben werden.", "PORTAL_SCOPE_HOME_LOCATION_REQUIRED");
    }
    await validateActiveLocationExists(scope.locationId);
    if (scope.departmentId) {
      await validateActiveDepartmentExists(scope.departmentId, scope.locationId);
    }
    unique.set(`${scope.locationId}:${scope.departmentId || 0}`, scope);
  }
  scopes = [...unique.values()];
  if (scheduleAccess && !scopes.length) {
    throw httpError(400,
      "Für Dienstplanrechte muss mindestens die eigene Abteilung oder die gesamte Stammfiliale zugewiesen werden.",
      "PORTAL_SCOPE_REQUIRED");
  }
  return scopes;
}

async function rightsMutationSnapshot(
  employeeNumber,
  role,
  rolePermissions,
  amuLocalAccessMode = "inherit",
  repository = organizationPersonnelRepository,
) {
  const [
    grantedPermissions,
    deniedPermissions,
    scopes,
    permissionScopeRows,
    personnelLearningDenialAuthority,
  ] = await Promise.all([
    portalPermissionGrantsForEmployee(employeeNumber, role, repository),
    portalPermissionDenialsForEmployee(employeeNumber, repository),
    repository.listPortalAccessScopes(employeeNumber).then((rows) => rows.map((scope) => ({
      locationId: scope.location_id,
      departmentId: Number(scope.department_id || 0) || null,
    }))),
    repository.listPortalPermissionScopeGrants(employeeNumber),
    repository.getPersonnelLearningPermissionDenialAuthority(
      employeeNumber,
      PERSONNEL_LEARNING_PERMISSIONS.CROSS_LOCATION_ASSIGN,
    ),
  ]);
  const permissionState = effectivePortalPermissionState(
    employeeNumber,
    role,
    rolePermissions,
    grantedPermissions,
    deniedPermissions,
    amuLocalAccessMode,
  );
  return {
    grantedPermissions: permissionState.grantedPermissions,
    deniedPermissions: permissionState.deniedPermissions,
    effectivePermissions: permissionState.effectivePermissions,
    scopes,
    personnelLifecyclePermissionScopes: permissionScopeRows.map(publicPortalPermissionScopeGrant),
    personnelLearningCrossLocationDenialAuthority: personnelLearningDenialAuthority ? {
      authorityLevel: String(personnelLearningDenialAuthority.authority_level || ""),
      scopeLocationId: String(personnelLearningDenialAuthority.scope_location_id || ""),
      generationId: String(personnelLearningDenialAuthority.generation_id || ""),
      revision: Number(personnelLearningDenialAuthority.revision || 0),
    } : null,
  };
}

require("./lib/portal-permission-defaults-routes").registerPortalPermissionDefaultsRoutes(app, {
  requireActor: request => requireRightsEditorOrLocal(request, "rights:write"),
  repository: organizationPersonnelRepository,
  transaction: work => personnelLifecycleSerializableTransaction(work),
  catalog: allPortalPermissionCatalog,
  builtinRoles: builtinPortalRoles,
  knownPermissions: allPortalPermissions,
  validateDependencies: permissions => assertPortalPermissionDependencies([...permissions]),
  effectiveState: effectivePortalPermissionState,
  error: httpError,
});

app.put("/api/portal/v1/rights/:employeeNumber", async (request, response) => {
  const actor = requireRightsEditorOrLocal(request, "rights:write");
  const employeeNumber = String(request.params.employeeNumber || "").trim();
  const target = (await portalUsersForAdmin()).find((user) => user.employeeNumber === employeeNumber);
  if (!target?.configured || !target.active) throw httpError(404, "Der aktive Portal-Zugang wurde nicht gefunden.");
  if (!actorCanManagePermissionGrants(actor, target)) throw httpError(403, target.role === "developer"
    ? "Der Developer-Zugang ist geschützt und kann nicht über die App verändert werden."
    : "Für diesen Zugang dürfen keine individuellen Rechte geändert werden.", target.role === "developer" ? "PORTAL_DEVELOPER_PROTECTED" : "PORTAL_ROLE_HIERARCHY_DENIED");
  const grantsInput = Array.isArray(request.body.grantedPermissions)
    ? request.body.grantedPermissions
    : request.body.permissions;
  if (!Array.isArray(grantsInput)) throw httpError(400, "Bitte eine gültige Rechteauswahl übermitteln.");
  const submitted = [...new Set(grantsInput.map((value) => String(value || "").trim()).filter(Boolean))];
  if (actor.role === "manager" && submitted.length) {
    throw httpError(
      403,
      "Filialleitungen können hier ausschließlich die persönliche Leihe ihrer Mitarbeitenden und Grundrechte ihrer Abteilungsleitungen entziehen oder wiederherstellen.",
      "MANAGER_DEPARTMENT_RIGHTS_DENIAL_ONLY",
    );
  }
  const denialInputProvided = Object.prototype.hasOwnProperty.call(request.body || {}, "deniedPermissions");
  if (denialInputProvided && !Array.isArray(request.body.deniedPermissions)) {
    throw httpError(400, "Bitte eine gültige Auswahl entzogener Grundrechte übermitteln.");
  }
  const submittedDenialsInput = denialInputProvided
    ? [...new Set(request.body.deniedPermissions.map((value) => String(value || "").trim()).filter(Boolean))]
    : null;
  const manageablePermissions = manageablePortalPermissionsForTarget(actor, target);
  const [
    currentGrantRows,
    currentDenialRows,
    roleProjection,
    currentPermissionScopeRows,
    currentPortalScopes,
  ] = await Promise.all([
    portalPermissionGrantsForEmployee(employeeNumber, target.role),
    portalPermissionDenialsForEmployee(employeeNumber),
    organizationPersonnelRepository.getPortalAccessProjection(employeeNumber),
    organizationPersonnelRepository.listPortalPermissionScopeGrants(employeeNumber),
    explicitPortalAccessScopesForEmployee(employeeNumber),
  ]);
  const submittedDenials = submittedDenialsInput || currentDenialRows;
  const currentGrants = new Set(currentGrantRows);
  const currentDenials = new Set(currentDenialRows);
  const invalid = [
    ...submitted.filter((permission) => !manageablePermissions.has(permission) && !currentGrants.has(permission)),
    ...submittedDenials.filter((permission) => !manageablePermissions.has(permission) && !currentDenials.has(permission)),
  ];
  if (invalid.length) {
    throw httpError(403, `Diese Rechte dürfen durch den aktuellen Zugang nicht vergeben werden: ${invalid.join(", ")}`, "PORTAL_PERMISSION_NOT_DELEGABLE");
  }
  const roleRestricted = submitted.filter((permission) => actor.role !== "developer" && !currentGrants.has(permission) && !portalPermissionAllowedForRole(permission, target.role));
  if (roleRestricted.length) {
    throw portalPermissionRoleRestrictionError(roleRestricted);
  }
  const rolePermissions = parsePortalPermissions(roleProjection?.permissions)
    .filter((permission) => allPortalPermissions.has(permission));
  const rolePermissionSet = new Set(rolePermissions);
  const invalidDenials = submittedDenials.filter((permission) => !rolePermissionSet.has(permission)
    && !(actor.role === "developer" && allPortalPermissions.has(permission))
    && !currentDenials.has(permission));
  if (invalidDenials.length) {
    throw httpError(400,
      `Nur Grundrechte der aktuellen Rolle können entzogen werden: ${invalidDenials.join(", ")}`,
      "PORTAL_PERMISSION_DENIAL_NOT_ROLE_BASED");
  }
  const normalizedDenials = new Set([
    ...[...currentDenials].filter((permission) => !manageablePermissions.has(permission)),
    ...submittedDenials.filter((permission) => manageablePermissions.has(permission)),
  ]);
  cascadeCrossLocationScheduleRolePermissionDenials(rolePermissionSet, normalizedDenials);
  const projectedPermissions = [...new Set([
    ...rolePermissions,
    ...[...currentGrants].filter((permission) => !manageablePermissions.has(permission)),
    ...submitted.filter((permission) => manageablePermissions.has(permission)),
  ])]
    .filter((permission) => !normalizedDenials.has(permission));
  if (projectedPermissions.includes("schedule:write") && !projectedPermissions.includes("schedule:read")) {
    throw httpError(400,
      "Dienstpläne können nur bearbeitet werden, wenn das Leserecht ebenfalls wirksam ist.",
      "PORTAL_PERMISSION_DEPENDENCY");
  }
  assertPortalPermissionDependencies(projectedPermissions);
  const scopesInputProvided = Object.prototype.hasOwnProperty.call(request.body || {}, "scopes");
  if (scopesInputProvided && !Array.isArray(request.body.scopes)) {
    throw httpError(400, "Bitte eine gültige Bereichsauswahl übermitteln.", "PORTAL_SCOPE_INVALID");
  }
  const scopes = await normalizeRightsScopesForTarget(target,
    scopesInputProvided ? request.body.scopes : currentPortalScopes,
    projectedPermissions);
  if (scopesInputProvided) {
    assertPersonnelLearningPortalScopeDeltaAllowed(
      actor,
      target,
      currentPortalScopes,
      scopes,
    );
  }
  const finalDirectGrants = new Set([
    ...[...currentGrants].filter((permission) => !manageablePermissions.has(permission)),
    ...submitted.filter((permission) => manageablePermissions.has(permission)),
  ]);
  const plannedPermissionScopes = planPersonnelLifecyclePermissionScopes({
    actor,
    target,
    portalScopes: scopes,
    currentGrants,
    finalDirectGrants,
    currentPermissionScopes: currentPermissionScopeRows.map(publicPortalPermissionScopeGrant),
    manageablePermissions,
    scopesInputProvided,
  });
  const plannedPermissionScopeKeys = new Set(
    plannedPermissionScopes.map(personnelLifecyclePermissionScopeKey),
  );
  const protectedPersonnelScopesToRemove = currentPermissionScopeRows
    .map(publicPortalPermissionScopeGrant)
    .filter((scope) => !plannedPermissionScopeKeys.has(
      personnelLifecyclePermissionScopeKey(scope),
    ));
  if (protectedPersonnelScopesToRemove.length
    && !actorCanManageProtectedPersonnelState(actor, [], protectedPersonnelScopesToRemove)) {
    (await auditPortal(
      actor.employeeNumber,
      "portal.rights.update.denied",
      "portal_user",
      employeeNumber,
      JSON.stringify({
        reason: "PERSONNEL_LIFECYCLE_PERMISSION_SCOPE_PROTECTED",
        route: personnelRecordDeniedRoute(request),
      }),
    ));
    throw httpError(
      403,
      "Ein von PL+ freigegebener Personalmodul-Geltungsbereich darf hier nicht entfernt oder verkleinert werden.",
      "PERSONNEL_LIFECYCLE_PERMISSION_SCOPE_PROTECTED",
    );
  }
  const before = await rightsMutationSnapshot(
    employeeNumber,
    target.role,
    rolePermissions,
    target.amuLocalAccessMode,
  );
  const prePlanPermissionState = effectivePortalPermissionState(
    employeeNumber,
    target.role,
    rolePermissions,
    currentGrantRows,
    currentDenialRows,
    target.amuLocalAccessMode,
  );
  const prePlanSnapshot = {
    grantedPermissions: prePlanPermissionState.grantedPermissions,
    deniedPermissions: prePlanPermissionState.deniedPermissions,
    effectivePermissions: prePlanPermissionState.effectivePermissions,
    scopes: currentPortalScopes,
    personnelLifecyclePermissionScopes: currentPermissionScopeRows
      .map(publicPortalPermissionScopeGrant),
    personnelLearningCrossLocationDenialAuthority:
      before.personnelLearningCrossLocationDenialAuthority,
  };
  assertRightsMutationSnapshotCurrent(
    rightsConcurrencySignature({ target, rolePermissions, snapshot: prePlanSnapshot }),
    rightsConcurrencySignature({ target, rolePermissions, snapshot: before }),
  );
  const expectedConcurrencySignature = rightsConcurrencySignature({
    target,
    rolePermissions,
    snapshot: before,
  });
  const learningCrossPermission = PERSONNEL_LEARNING_PERMISSIONS.CROSS_LOCATION_ASSIGN;
  const learningCrossDeniedBefore = before.deniedPermissions.includes(
    learningCrossPermission,
  );
  const learningCrossDeniedAfter = normalizedDenials.has(learningCrossPermission);
  let plannedLearningDenialAuthority = before.personnelLearningCrossLocationDenialAuthority;
  if (denialInputProvided && manageablePermissions.has(learningCrossPermission)) {
    if (!learningCrossDeniedAfter) plannedLearningDenialAuthority = null;
    else if (!learningCrossDeniedBefore) {
      plannedLearningDenialAuthority = {
        authorityLevel: PERSONNEL_LEARNING_DENIAL_AUTHORITIES.PL_PLUS,
        scopeLocationId: "",
        revision: 1,
      };
    }
  }
  const plannedAfter = {
    grantedPermissions: [...finalDirectGrants].sort(),
    deniedPermissions: [...normalizedDenials].sort(),
    effectivePermissions: [...projectedPermissions].sort(),
    scopes,
    personnelLifecyclePermissionScopes: plannedPermissionScopes
      .map(publicPortalPermissionScopeGrant),
    personnelLearningCrossLocationDenialAuthority: plannedLearningDenialAuthority,
  };
  let rightsChanged = false;
  let responseProjectionActor = actor;
  await personnelLifecycleSerializableTransaction(async (organization) => {
    const [liveTarget, liveRoleProjection, liveBefore, liveLearningActor, liveTargetScope] = await Promise.all([
      organization.getPortalUserAccountProjection(employeeNumber),
      organization.getPortalAccessProjection(employeeNumber),
      rightsMutationSnapshot(
        employeeNumber,
        target.role,
        rolePermissions,
        target.amuLocalAccessMode,
        organization,
      ),
      livePersonnelLearningRoleAdministrationActor(actor, organization),
      organization.getEmployeeScopeProjection(employeeNumber),
    ]);
    responseProjectionActor = liveLearningActor;
    assertLivePortalRoutePermission(liveLearningActor, "rights:write", {
      allowedRoles: RIGHTS_EDITOR_PORTAL_ROLES,
    });
    const liveTargetAccess = {
      employeeNumber,
      role: String(liveTarget?.role || ""),
      roleLocked: Boolean(liveTarget?.role_locked),
      configured: Boolean(liveTarget),
      active: Boolean(liveTarget?.active),
      homeLocationId: String(liveTargetScope?.home_location_id || ""),
    };
    const liveRolePermissions = parsePortalPermissions(liveRoleProjection?.permissions)
      .filter((permission) => allPortalPermissions.has(permission));
    assertRightsMutationSnapshotCurrent(
      expectedConcurrencySignature,
      rightsConcurrencySignature({
        target: liveTarget,
        rolePermissions: liveRolePermissions,
        snapshot: liveBefore,
      }),
    );
    const grantDelta = setDifference(
      before.grantedPermissions,
      plannedAfter.grantedPermissions,
      (permission) => permission,
    );
    const denialDelta = denialInputProvided
      ? setDifference(
        before.deniedPermissions,
        plannedAfter.deniedPermissions,
        (permission) => permission,
      )
      : { added: [], removed: [] };
    const accessScopeDelta = scopesInputProvided
      ? setDifference(before.scopes, scopes, portalAccessScopeKey)
      : { added: [], removed: [] };
    const permissionScopeDelta = setDifference(
      before.personnelLifecyclePermissionScopes,
      plannedPermissionScopes,
      personnelLifecyclePermissionScopeKey,
    );
    rightsChanged = [grantDelta, denialDelta, accessScopeDelta, permissionScopeDelta]
      .some((delta) => delta.added.length || delta.removed.length);
    if (!rightsChanged) return;
    if (!actorCanManagePermissionGrants(liveLearningActor, liveTargetAccess)) {
      throw httpError(
        403,
        "Für diesen Zugang dürfen keine individuellen Rechte geändert werden.",
        "PORTAL_ROLE_HIERARCHY_DENIED",
      );
    }
    if (scopesInputProvided) {
      assertPersonnelLearningPortalScopeDeltaAllowed(
        liveLearningActor,
        liveTarget,
        liveBefore.scopes,
        scopes,
      );
    }
    const liveScopeValidation = new Map();
    for (const scope of [
      ...(scopesInputProvided ? scopes : []),
      ...plannedPermissionScopes,
    ]) {
      liveScopeValidation.set(portalAccessScopeKey(scope), scope);
    }
    for (const scope of liveScopeValidation.values()) {
      await validateActiveLocationExists(scope.locationId, organization);
      if (scope.departmentId) {
        await validateActiveDepartmentExists(scope.departmentId, scope.locationId, organization);
      }
    }
    const learningPermissionDelta = [
      ...grantDelta.added,
      ...grantDelta.removed,
      ...denialDelta.added,
      ...denialDelta.removed,
      ...permissionScopeDelta.added.map((scope) => scope.permission),
      ...permissionScopeDelta.removed.map((scope) => scope.permission),
    ].filter((permission) => PERSONNEL_LEARNING_PERMISSION_IDS.includes(permission));
    const liveManageablePermissions = manageablePortalPermissionsForTarget(liveLearningActor, liveTargetAccess);
    const actualPermissionDelta = [
      ...grantDelta.added,
      ...grantDelta.removed,
      ...denialDelta.added,
      ...denialDelta.removed,
      ...permissionScopeDelta.added.map((scope) => scope.permission),
      ...permissionScopeDelta.removed.map((scope) => scope.permission),
    ];
    if (actualPermissionDelta.some((permission) => !liveManageablePermissions.has(permission))) {
      throw httpError(
        403,
        "Mindestens eine tatsächliche Rechteänderung liegt außerhalb der aktuell wirksamen Verwaltungsbefugnis.",
        "PORTAL_ROLE_HIERARCHY_DENIED",
      );
    }
    if (learningPermissionDelta.length
      && !actorCanAdministerPersonnelLearningRoleAccount(liveLearningActor)) {
      throw httpError(
        403,
        "Schulungs- und Wissensrechte dürfen nur mit aktuell wirksamer fachlicher Delegationsbefugnis geändert werden.",
        "PORTAL_ROLE_HIERARCHY_DENIED",
      );
    }
    for (const permission of grantDelta.added) {
      await organization.insertPermissionGrant(employeeNumber, permission, actor.employeeNumber);
    }
    for (const permission of grantDelta.removed) {
      await organization.deletePermissionGrant(employeeNumber, permission);
    }
    if (denialInputProvided) {
      for (const permission of denialDelta.added) {
        await organization.insertPermissionDenial(employeeNumber, permission, actor.employeeNumber);
        if (permission === PERSONNEL_LEARNING_PERMISSIONS.CROSS_LOCATION_ASSIGN
          && liveManageablePermissions.has(permission)) {
          await organization.upsertPersonnelLearningPermissionDenialAuthority({
            employeeNumber,
            permission,
            authorityLevel: PERSONNEL_LEARNING_DENIAL_AUTHORITIES.PL_PLUS,
            scopeLocationId: "",
            actor: actor.employeeNumber,
          });
        }
      }
      for (const permission of denialDelta.removed) {
        if (permission === PERSONNEL_LEARNING_PERMISSIONS.CROSS_LOCATION_ASSIGN
          && liveManageablePermissions.has(permission)) {
          await organization.deletePersonnelLearningPermissionDenialAuthority(
            employeeNumber,
            permission,
          );
        }
        await organization.deletePermissionDenial(employeeNumber, permission);
      }
    }
    if (scopesInputProvided) {
      for (const scope of accessScopeDelta.added) {
        await organization.insertAccessScope({
          employeeNumber,
          locationId: scope.locationId,
          departmentId: scope.departmentId || 0,
          assignedBy: actor.employeeNumber,
        });
      }
    }
    for (const permissionScope of permissionScopeDelta.removed) {
      await organization.deletePermissionScopeGrant({
        employeeNumber,
        permission: permissionScope.permission,
        locationId: permissionScope.locationId,
        departmentId: Number(permissionScope.departmentId || 0),
      });
    }
    if (scopesInputProvided) {
      for (const scope of accessScopeDelta.removed) {
        await organization.deleteAccessScope({
          employeeNumber,
          locationId: scope.locationId,
          departmentId: Number(scope.departmentId || 0),
        });
      }
    }
    for (const permissionScope of permissionScopeDelta.added) {
      await organization.insertPermissionScopeGrant(permissionScope);
    }
    const actualAfter = await rightsMutationSnapshot(
      employeeNumber,
      target.role,
      liveRolePermissions,
      target.amuLocalAccessMode,
      organization,
    );
    await organization.revokePortalSessions(employeeNumber);
    await organization.revokeMobileSessions(employeeNumber, "rights_changed");
    await organization.insertAudit(
      actor.employeeNumber,
      "portal.rights.update",
      "portal_user",
      employeeNumber,
      compactRightsAuditDetail(before, actualAfter),
    );
    const learningAuthorityChanged = JSON.stringify(
      before.personnelLearningCrossLocationDenialAuthority || null,
    ) !== JSON.stringify(
      actualAfter.personnelLearningCrossLocationDenialAuthority || null,
    );
    const learningDenialChanged = before.deniedPermissions.includes(
      PERSONNEL_LEARNING_PERMISSIONS.CROSS_LOCATION_ASSIGN,
    ) !== actualAfter.deniedPermissions.includes(
      PERSONNEL_LEARNING_PERMISSIONS.CROSS_LOCATION_ASSIGN,
    );
    if (denialInputProvided
      && liveManageablePermissions.has(
        PERSONNEL_LEARNING_PERMISSIONS.CROSS_LOCATION_ASSIGN,
      )
      && (learningAuthorityChanged || learningDenialChanged)) {
      await organization.insertAudit(
        actor.employeeNumber,
        "personnel.learning.cross-location-right.update",
        "portal_user",
        employeeNumber,
        JSON.stringify({
          schemaVersion: 1,
          permission: PERSONNEL_LEARNING_PERMISSIONS.CROSS_LOCATION_ASSIGN,
          enabledBefore: !before.deniedPermissions.includes(
            PERSONNEL_LEARNING_PERMISSIONS.CROSS_LOCATION_ASSIGN,
          ),
          enabledAfter: !actualAfter.deniedPermissions.includes(
            PERSONNEL_LEARNING_PERMISSIONS.CROSS_LOCATION_ASSIGN,
          ),
          authorityBefore: before.personnelLearningCrossLocationDenialAuthority
            ?.authorityLevel || null,
          authorityAfter: actualAfter.personnelLearningCrossLocationDenialAuthority
            ?.authorityLevel || null,
          reasonCode: "PL_PLUS_RIGHTS_MANAGEMENT",
        }),
      );
    }
  }, { uniqueAsConcurrent: true });
  const after = await rightsMutationSnapshot(
    employeeNumber,
    target.role,
    rolePermissions,
    target.amuLocalAccessMode,
  );
  const amuRoutingChanged = ["amu:local:manage", "sickness:read"].some((permission) =>
    before.effectivePermissions.includes(permission) !== after.effectivePermissions.includes(permission));
  if (rightsChanged && (scopesInputProvided || amuRoutingChanged)) {
    await reconcileOpenAmuResponsibilities(actor.employeeNumber);
  }
  response.json(await rightsManagementPayload(responseProjectionActor));
});

