app.put("/api/portal/v1/users/:employeeNumber/scopes", async (request, response) => {
  const actor = requirePortalAdminOrLocal(request, "scopes:write");
  const employeeNumber = String(request.params.employeeNumber || "").trim();
  const target = await organizationPersonnelRepository
    .getPortalScopeAssignmentTarget(employeeNumber);
  if (!target || !target.active) throw httpError(404, "Der aktive Zugang wurde nicht gefunden.");
  (await assertPortalUserIsMutable(target, actor));
  if (!actorCanManagePortalRole(actor, target.role)) {
    throw httpError(403, "Dieser Zugang liegt außerhalb der eigenen Verwaltungsebene.", "PORTAL_ROLE_HIERARCHY_DENIED");
  }
  if (!["location_planner", "manager", "department_manager"].includes(target.role)) {
    throw httpError(400, "Nur standortgebundene Planungs- und Leitungsrollen benötigen eine Bereichszuweisung.");
  }
  const submitted = Array.isArray(request.body.scopes) ? request.body.scopes : [];
  const scopes = submitted.map((scope) => ({
    locationId: normalizeLocationId(scope.locationId),
    departmentId: normalizeDepartmentId(scope.departmentId, true),
  }));
  if (!scopes.length) throw httpError(400, "Bitte mindestens einen Bereich zuweisen.");
  for (const scope of scopes) {
    await validateActiveLocationExists(scope.locationId);
    if (target.role === "department_manager") {
      if (!scope.departmentId) throw httpError(400, "Für eine Abteilungsleitung muss eine Abteilung ausgewählt werden.");
      await validateActiveDepartmentExists(scope.departmentId, scope.locationId);
    } else scope.departmentId = null;
    if (actor.role === "manager") assertSessionContextScope(actor, { locationId: scope.locationId });
    if (actor.role === "manager" && target.home_location_id !== scope.locationId) throw httpError(403, "Die Abteilungsleitung gehört nicht zum eigenen Standort.");
  }
  if (actor.role === "manager" && target.role !== "department_manager") throw httpError(403, "Eine Filialleitung darf nur Abteilungsleitungen ihres Standorts zuweisen.");
  const [currentPortalScopes, currentPermissionScopeRows] = await Promise.all([
    explicitPortalAccessScopesForEmployee(employeeNumber),
    organizationPersonnelRepository.listPortalPermissionScopeGrants(employeeNumber),
  ]);
  const portalScopeDelta = setDifference(
    currentPortalScopes,
    scopes,
    portalAccessScopeKey,
  );
  if (portalScopeDelta.added.length || portalScopeDelta.removed.length) {
    await assertItAdminCannotTakeOverPersonnelLifecycleTarget(
      actor,
      target,
      organizationPersonnelRepository,
    );
    assertPersonnelLearningPortalScopeDeltaAllowed(
      actor,
      target,
      currentPortalScopes,
      scopes,
    );
  }
  const currentPermissionScopes = currentPermissionScopeRows.map(publicPortalPermissionScopeGrant);
  const projectedPermissionScopes = currentPermissionScopes.filter((scope) => (
    personnelLifecycleScopeMatchesTarget(
      { ...target, role: target.role },
      scope,
      scopes,
    )
  ));
  const protectedPersonnelScopesToRemove = currentPermissionScopes.filter((scope) => (
    !projectedPermissionScopes.some((projected) => (
      personnelLifecyclePermissionScopeKey(projected) === personnelLifecyclePermissionScopeKey(scope)
    ))
  ));
  if (protectedPersonnelScopesToRemove.length
    && !actorCanManageProtectedPersonnelState(actor, [], protectedPersonnelScopesToRemove)) {
    (await auditPortal(
      actor.employeeNumber,
      "portal.scope.update.denied",
      "portal_user",
      employeeNumber,
      JSON.stringify({
        reason: "PERSONNEL_LIFECYCLE_PERMISSION_SCOPE_PROTECTED",
        route: personnelRecordDeniedRoute(request),
      }),
    ));
    throw httpError(
      403,
      "Ein von PL+ freigegebener Personalmodul-Geltungsbereich darf hier nicht entfernt werden.",
      "PERSONNEL_LIFECYCLE_PERMISSION_SCOPE_PROTECTED",
    );
  }
  const expectedConcurrencySignature = scopeMutationConcurrencySignature(
    target,
    currentPortalScopes,
    currentPermissionScopes,
  );
  const before = {
    scopes: currentPortalScopes,
    personnelLifecyclePermissionScopes: currentPermissionScopes,
  };
  const after = {
    scopes,
    personnelLifecyclePermissionScopes: projectedPermissionScopes,
  };
  let scopesChanged = false;
  let responseProjectionActor = actor;
  await personnelLifecycleSerializableTransaction(async (organization) => {
    const [
      liveTarget,
      livePortalScopeRows,
      livePermissionScopeRows,
      liveLearningActor,
    ] = await Promise.all([
      organization.getPortalScopeAssignmentTarget(employeeNumber),
      organization.listPortalAccessScopes(employeeNumber),
      organization.listPortalPermissionScopeGrants(employeeNumber),
      livePersonnelLearningRoleAdministrationActor(actor, organization),
    ]);
    responseProjectionActor = liveLearningActor;
    assertLivePortalRoutePermission(liveLearningActor, "scopes:write");
    const livePortalScopes = livePortalScopeRows.map((scope) => ({
      locationId: scope.location_id,
      departmentId: Number(scope.department_id || 0) || null,
    }));
    const livePermissionScopes = livePermissionScopeRows.map(publicPortalPermissionScopeGrant);
    assertRightsMutationSnapshotCurrent(
      expectedConcurrencySignature,
      scopeMutationConcurrencySignature(liveTarget, livePortalScopes, livePermissionScopes),
    );
    const accessScopeDelta = setDifference(
      livePortalScopes,
      scopes,
      portalAccessScopeKey,
    );
    const permissionScopeDelta = setDifference(
      livePermissionScopes,
      projectedPermissionScopes,
      personnelLifecyclePermissionScopeKey,
    );
    scopesChanged = Boolean(
      accessScopeDelta.added.length
      || accessScopeDelta.removed.length
      || permissionScopeDelta.added.length
      || permissionScopeDelta.removed.length
    );
    if (!scopesChanged) return;
    (await assertPortalUserIsMutable(liveTarget, liveLearningActor));
    await assertItAdminCannotTakeOverPersonnelLifecycleTarget(
      liveLearningActor,
      liveTarget,
      organization,
    );
    assertPersonnelLearningPortalScopeDeltaAllowed(
      liveLearningActor,
      liveTarget,
      livePortalScopes,
      scopes,
    );
    if (!actorCanManagePortalRole(liveLearningActor, liveTarget.role)) {
      throw httpError(403, "Dieser Zugang liegt außerhalb der eigenen Verwaltungsebene.", "PORTAL_ROLE_HIERARCHY_DENIED");
    }
    if (!actorCanManageProtectedPersonnelState(
      liveLearningActor,
      [],
      permissionScopeDelta.removed,
    )) {
      throw httpError(
        403,
        "Ein von PL+ freigegebener Personalmodul-Geltungsbereich darf hier nicht entfernt werden.",
        "PERSONNEL_LIFECYCLE_PERMISSION_SCOPE_PROTECTED",
      );
    }
    if (liveLearningActor.role === "manager") {
      if (liveTarget.role !== "department_manager") {
        throw httpError(403, "Eine Filialleitung darf nur Abteilungsleitungen ihres Standorts zuweisen.");
      }
      for (const scope of scopes) {
        assertSessionContextScope(liveLearningActor, { locationId: scope.locationId });
        if (String(liveTarget.home_location_id || "") !== String(scope.locationId || "")) {
          throw httpError(403, "Die Abteilungsleitung gehört nicht zum eigenen Standort.");
        }
      }
    }
    for (const scope of scopes) {
      await validateActiveLocationExists(scope.locationId, organization);
      if (scope.departmentId) {
        await validateActiveDepartmentExists(scope.departmentId, scope.locationId, organization);
      }
    }
    for (const scope of accessScopeDelta.added) {
      await organization.insertAccessScope({
        employeeNumber,
        locationId: scope.locationId,
        departmentId: scope.departmentId || 0,
        assignedBy: liveLearningActor.employeeNumber,
      });
    }
    for (const permissionScope of permissionScopeDelta.removed) {
      await organization.deletePermissionScopeGrant({
        employeeNumber,
        permission: permissionScope.permission,
        locationId: permissionScope.locationId,
        departmentId: Number(permissionScope.departmentId || 0),
      });
    }
    for (const scope of accessScopeDelta.removed) {
      await organization.deleteAccessScope({
        employeeNumber,
        locationId: scope.locationId,
        departmentId: Number(scope.departmentId || 0),
      });
    }
    await organization.revokePortalSessions(employeeNumber);
    await organization.revokeMobileSessions(employeeNumber, "scopes_changed");
    await organization.insertAudit(
      liveLearningActor.employeeNumber,
      "portal.scope.update",
      "portal_user",
      employeeNumber,
      compactRightsAuditDetail(before, after),
    );
  }, { uniqueAsConcurrent: true });
  if (scopesChanged) {
    await reconcileOpenAmuResponsibilities(responseProjectionActor.employeeNumber);
  }
  const [users, roles] = await Promise.all([
    portalUsersForActor(responseProjectionActor),
    portalRolesForUserAdministrationActor(responseProjectionActor),
  ]);
  response.json({ users, roles });
});

app.put("/api/portal/v1/users/:employeeNumber", async (request, response) => {
  const actor = requirePortalAdminOrLocal(request, "users:write");
  const employeeNumber = String(request.params.employeeNumber || "").trim();
  assertEmployeePrincipalNotReserved(employeeNumber);
  if (!await organizationPersonnelRepository.employeeExists(employeeNumber)) {
    throw httpError(404, "Das Teammitglied wurde nicht gefunden.");
  }
  const role = String(request.body.role || "employee");
  const roleExists = await organizationPersonnelRepository.portalRoleExists(role);
  if (!roleExists) throw httpError(400, "Die ausgewählte Rolle ist ungültig.");
  if (role === "developer") {
    throw httpError(403, "Die Developer-Rolle kann ausschließlich mit dem lokalen Entwicklerwerkzeug gebunden werden.", "PORTAL_DEVELOPER_PROTECTED");
  }
  const existingUser = await organizationPersonnelRepository
    .getPortalUserAccountProjection(employeeNumber);
  if (roleHasPersonnelLearningDefaults(role)
    && (!existingUser || !roleHasPersonnelLearningDefaults(existingUser.role))
    && !actorCanAdministerPersonnelLearningRoleAccount(actor)) {
    throw httpError(
      403,
      "Ein Zugang mit Schulungs- und Wissensdatenzugriff darf nur mit wirksamer fachlicher Delegationsbefugnis aktiviert werden.",
      "PORTAL_ROLE_HIERARCHY_DENIED",
    );
  }
  let existingPersonnelLifecycleGrants = [];
  let existingPersonnelLifecyclePermissionScopes = [];
  let existingPersonnelLearningDenials = [];
  let existingPortalBirthdayPresentationRights = [];
  if (existingUser) {
    (await assertPortalUserIsMutable(existingUser, actor));
    await assertItAdminCannotTakeOverPersonnelLifecycleTarget(
      actor,
      existingUser,
      organizationPersonnelRepository,
    );
    if (roleHasPersonnelLearningDefaults(existingUser.role)
      && !actorCanAdministerPersonnelLearningRoleAccount(actor)) {
      throw httpError(
        403,
        "Ein Zugang mit Schulungs- und Wissensdatenzugriff darf nur mit wirksamer fachlicher Delegationsbefugnis verwaltet werden.",
        "PORTAL_ROLE_HIERARCHY_DENIED",
      );
    }
    if (actor.employeeNumber === employeeNumber && existingUser.role !== role
      && roleHasPersonnelLearningDefaults(role)) {
      throw httpError(
        403,
        "Das eigene Administrationskonto darf nicht in eine fachlich datenberechtigte Schulungsrolle umgewandelt werden.",
        "PORTAL_ROLE_HIERARCHY_DENIED",
      );
    }
    if (!actorCanManagePortalRole(actor, existingUser.role)) {
      throw httpError(403, "Dieser Zugang liegt außerhalb der eigenen Verwaltungsebene.", "PORTAL_ROLE_HIERARCHY_DENIED");
    }
    if (existingUser.role !== role) {
      const [grantRows, denialRows, permissionScopeRows] = await Promise.all([
        portalPermissionGrantsForEmployee(employeeNumber, existingUser.role),
        portalPermissionDenialsForEmployee(employeeNumber),
        organizationPersonnelRepository.listPortalPermissionScopeGrants(employeeNumber),
      ]);
      existingPersonnelLifecycleGrants = grantRows
        .filter((permission) => personnelLifecyclePermissionIds.has(permission));
      existingPersonnelLifecyclePermissionScopes = permissionScopeRows
        .map(publicPortalPermissionScopeGrant);
      existingPersonnelLearningDenials = denialRows
        .filter((permission) => PERSONNEL_LEARNING_PERMISSION_IDS.includes(permission));
      existingPortalBirthdayPresentationRights = [...grantRows, ...denialRows]
        .filter((permission) => (
          PORTAL_BIRTHDAY_PRESENTATION_PERMISSION_IDS.includes(permission)
        ));
      if (existingPersonnelLearningDenials.length) {
        throw httpError(
          409,
          "Die Rolle kann erst geändert werden, nachdem PL+ die entzogenen Schulungs- und Wissensrechte in der zentralen Rechteverwaltung bereinigt hat.",
          "PERSONNEL_LIFECYCLE_RIGHTS_PROFILE_PROTECTED",
        );
      }
      if (existingPortalBirthdayPresentationRights.length) {
        throw httpError(
          409,
          "Die Rolle kann erst geändert werden, nachdem die Fachrechte für Geburtstagsdarstellungen in der zentralen Rechteverwaltung bereinigt wurden.",
          "PORTAL_BIRTHDAY_PRESENTATION_RIGHTS_PROFILE_PROTECTED",
        );
      }
      if ((existingPersonnelLifecycleGrants.length
          || existingPersonnelLifecyclePermissionScopes.length)
        && !actorCanManageProtectedPersonnelState(
          actor,
          existingPersonnelLifecycleGrants,
          existingPersonnelLifecyclePermissionScopes,
        )) {
        (await auditPortal(
          actor.employeeNumber,
          "portal.user.update.denied",
          "portal_user",
          employeeNumber,
          JSON.stringify({
            reason: "PERSONNEL_LIFECYCLE_PERMISSION_SCOPE_PROTECTED",
            route: personnelRecordDeniedRoute(request),
          }),
        ));
        throw httpError(
          403,
          "Die Rolle kann erst geändert werden, nachdem PL+ die Personalmodul-Freigaben angepasst hat.",
          "PERSONNEL_LIFECYCLE_PERMISSION_SCOPE_PROTECTED",
        );
      }
    }
  }
  if (!actorCanAssignPortalRole(actor, role, roleExists)) {
    throw httpError(403, role === "developer"
      ? "Die Developer-Rolle kann ausschließlich mit dem lokalen Entwicklerwerkzeug gebunden werden."
      : "Diese Rolle darf durch den aktuellen Zugang nicht vergeben werden.", role === "developer" ? "PORTAL_DEVELOPER_PROTECTED" : "PORTAL_ROLE_HIERARCHY_DENIED");
  }
  const password = String(request.body.password || "");
  const passwordHash = password ? await hashPortalPassword(password) : existingUser?.password_hash || "";
  const active = request.body.active !== false ? 1 : 0;
  const mustChangePassword = password
    ? Number(request.body.mustChangePassword !== false)
    : existingUser ? Number(Boolean(existingUser.must_change_password)) : Number(request.body.mustChangePassword !== false);
  if (existingUser?.role === "admin" && (role !== "admin" || !active)) {
    const otherSystemOwners = Number(
      await organizationPersonnelRepository.countOtherSystemOwners(employeeNumber),
    );
    if (!otherSystemOwners) throw httpError(409, "Mindestens ein aktiver Developer- oder Admin-Zugang muss bestehen bleiben.");
  }
  const expectedConcurrencySignature = portalUserMutationConcurrencySignature(
    existingUser,
    existingPersonnelLifecycleGrants,
    existingPersonnelLifecyclePermissionScopes,
    existingPortalBirthdayPresentationRights,
  );
  let responseProjectionActor = actor;
  let userChanged = false;
  await personnelLifecycleSerializableTransaction(async (organization) => {
    const [liveUser, liveLearningActor, liveEmployeeScope] = await Promise.all([
      organization.getPortalUserAccountProjection(employeeNumber),
      livePersonnelLearningRoleAdministrationActor(actor, organization),
      organization.getEmployeeScopeProjection(employeeNumber),
    ]);
    responseProjectionActor = liveLearningActor;
    assertLivePortalRoutePermission(liveLearningActor, "users:write");
    let livePersonnelLifecycleGrants = [];
    let livePersonnelLifecyclePermissionScopes = [];
    let livePersonnelLearningDenials = [];
    let livePortalBirthdayPresentationRights = [];
    if (liveUser && existingUser?.role !== role) {
      const [grantRows, denialRows, permissionScopeRows] = await Promise.all([
        portalPermissionGrantsForEmployee(employeeNumber, liveUser.role, organization),
        portalPermissionDenialsForEmployee(employeeNumber, organization),
        organization.listPortalPermissionScopeGrants(employeeNumber),
      ]);
      livePersonnelLifecycleGrants = grantRows
        .filter((permission) => personnelLifecyclePermissionIds.has(permission));
      livePersonnelLifecyclePermissionScopes = permissionScopeRows
        .map(publicPortalPermissionScopeGrant);
      livePersonnelLearningDenials = denialRows
        .filter((permission) => PERSONNEL_LEARNING_PERMISSION_IDS.includes(permission));
      livePortalBirthdayPresentationRights = [...grantRows, ...denialRows]
        .filter((permission) => (
          PORTAL_BIRTHDAY_PRESENTATION_PERMISSION_IDS.includes(permission)
        ));
      if (livePersonnelLearningDenials.length) {
        throw httpError(
          409,
          "Die Rolle kann erst geändert werden, nachdem PL+ die entzogenen Schulungs- und Wissensrechte in der zentralen Rechteverwaltung bereinigt hat.",
          "PERSONNEL_LIFECYCLE_RIGHTS_PROFILE_PROTECTED",
        );
      }
      if (livePortalBirthdayPresentationRights.length) {
        throw httpError(
          409,
          "Die Rolle kann erst geändert werden, nachdem die Fachrechte für Geburtstagsdarstellungen in der zentralen Rechteverwaltung bereinigt wurden.",
          "PORTAL_BIRTHDAY_PRESENTATION_RIGHTS_PROFILE_PROTECTED",
        );
      }
    }
    assertRightsMutationSnapshotCurrent(
      expectedConcurrencySignature,
      portalUserMutationConcurrencySignature(
        liveUser,
        livePersonnelLifecycleGrants,
        livePersonnelLifecyclePermissionScopes,
        livePortalBirthdayPresentationRights,
      ),
    );
    userChanged = Boolean(
      !liveUser
      || String(liveUser.role || "") !== role
      || Boolean(liveUser.active) !== Boolean(active)
      || Boolean(liveUser.must_change_password) !== Boolean(mustChangePassword)
      || password,
    );
    if (!userChanged) return;
    if (liveUser) {
      (await assertPortalUserIsMutable(liveUser, liveLearningActor));
      if (!actorCanManagePortalRole(liveLearningActor, liveUser.role)) {
        throw httpError(
          403,
          "Dieser Zugang liegt außerhalb der eigenen Verwaltungsebene.",
          "PORTAL_ROLE_HIERARCHY_DENIED",
        );
      }
    }
    if (!actorCanAssignPortalRole(liveLearningActor, role, roleExists)) {
      throw httpError(
        403,
        "Diese Rolle darf durch den aktuellen Zugang nicht vergeben werden.",
        "PORTAL_ROLE_HIERARCHY_DENIED",
      );
    }
    const liveLearningTarget = {
      homeLocationId: liveEmployeeScope?.home_location_id || "",
      preferredDepartmentId: liveEmployeeScope?.preferred_department_id || null,
    };
    if (roleHasPersonnelLearningDefaults(liveUser?.role)) {
      assertPersonnelLearningRoleAccountAdministrationAllowed(liveLearningActor, {
        ...liveLearningTarget,
        role: liveUser.role,
      });
    }
    if (roleHasPersonnelLearningDefaults(role)) {
      assertPersonnelLearningRoleAccountAdministrationAllowed(liveLearningActor, {
        ...liveLearningTarget,
        role,
      });
    }
    if (liveLearningActor?.employeeNumber === employeeNumber
      && liveUser?.role !== role
      && roleHasPersonnelLearningDefaults(role)) {
      throw httpError(
        403,
        "Das eigene Administrationskonto darf nicht in eine fachlich datenberechtigte Schulungsrolle umgewandelt werden.",
        "PORTAL_ROLE_HIERARCHY_DENIED",
      );
    }
    if (liveUser?.role !== role
      && (livePersonnelLifecycleGrants.length || livePersonnelLifecyclePermissionScopes.length)
      && !actorCanManageProtectedPersonnelState(
        liveLearningActor,
        livePersonnelLifecycleGrants,
        livePersonnelLifecyclePermissionScopes,
      )) {
      throw httpError(
        403,
        "Die Rolle kann erst geändert werden, nachdem PL+ die Personalmodul-Freigaben angepasst hat.",
        "PERSONNEL_LIFECYCLE_PERMISSION_SCOPE_PROTECTED",
      );
    }
    await assertItAdminCannotTakeOverPersonnelLifecycleTarget(
      liveLearningActor,
      liveUser,
      organization,
    );
    if (liveUser?.role === "admin" && (role !== "admin" || !active)) {
      const liveOtherSystemOwners = Number(
        await organization.countOtherSystemOwners(employeeNumber),
      );
      if (!liveOtherSystemOwners) {
        throw httpError(409, "Mindestens ein aktiver Developer- oder Admin-Zugang muss bestehen bleiben.");
      }
    }
    await organization.upsertPortalUserAccount({
      employeeNumber,
      passwordHash,
      role,
      active: Boolean(active),
      mustChangePassword: Boolean(mustChangePassword),
      passwordChanged: Boolean(password),
    });
    if (liveUser?.role && liveUser.role !== role) {
      await organization.deletePersonnelLearningPermissionDenialAuthority(
        employeeNumber,
        PERSONNEL_LEARNING_PERMISSIONS.CROSS_LOCATION_ASSIGN,
      );
      await organization.deletePermissionDenials(employeeNumber);
      for (const permission of personnelLifecyclePermissionIds) {
        await organization.deletePermissionGrant(employeeNumber, permission);
      }
    }
    if (!active || password || (liveUser?.role && liveUser.role !== role)) {
      await organization.revokePortalSessions(employeeNumber);
    }
    await organization.revokeMobileSessions(employeeNumber, "account_changed");
    await organization.insertAudit(
      liveLearningActor.employeeNumber,
      "portal.user.update",
      "portal_user",
      employeeNumber,
      compactPortalUserAuditDetail({
        roleBefore: liveUser?.role || null,
        roleAfter: role,
        active: Boolean(active),
        passwordReset: Boolean(password),
        personnelLifecycleRightsReset: livePersonnelLifecycleGrants,
        personnelLifecyclePermissionScopesBefore: livePersonnelLifecyclePermissionScopes,
        personnelLifecyclePermissionScopesAfter: liveUser?.role !== role ? []
          : livePersonnelLifecyclePermissionScopes,
      }),
    );
  });
  if (userChanged) {
    await refreshConfiguredAdminSnapshot();
    await reconcileOpenAmuResponsibilities(responseProjectionActor.employeeNumber);
    if (String(responseProjectionActor.employeeNumber || "") === employeeNumber) {
      responseProjectionActor = await livePersonnelLearningRoleAdministrationActor(
        responseProjectionActor,
      );
    }
  }
  const [users, roles] = await Promise.all([
    portalUsersForActor(responseProjectionActor),
    portalRolesForUserAdministrationActor(responseProjectionActor),
  ]);
  response.json({ users, roles });
});

app.post("/api/portal/v1/users/:employeeNumber/unlock", async (request, response) => {
  const actor = requirePortalAdminOrLocal(request, "users:write");
  const employeeNumber = String(request.params.employeeNumber || "").trim();
  let responseProjectionActor = actor;
  await personnelLifecycleSerializableTransaction(async (organization) => {
    const [liveTarget, liveActor, liveEmployeeScope, liveUsers] = await Promise.all([
      organization.getPortalMutationTarget(employeeNumber),
      livePersonnelLearningRoleAdministrationActor(actor, organization),
      organization.getEmployeeScopeProjection(employeeNumber),
      organization.listPortalUsersForAdmin(),
    ]);
    responseProjectionActor = liveActor;
    assertLivePortalRoutePermission(liveActor, "users:write");
    if (!liveTarget) throw httpError(404, "Der Zugang wurde nicht gefunden.");
    const liveUnlockState = liveUsers.find(
      (user) => String(user.personnel_number || "") === employeeNumber,
    );
    const unlockChanged = Boolean(
      Number(liveUnlockState?.failed_login_attempts || 0)
        || String(liveUnlockState?.locked_until || "").trim(),
    );
    if (!unlockChanged) return;
    (await assertPortalUserIsMutable(liveTarget, liveActor));
    await assertItAdminCannotTakeOverPersonnelLifecycleTarget(liveActor, liveTarget, organization);
    if (!actorCanManagePortalRole(liveActor, liveTarget.role)) {
      throw httpError(403, "Dieser Zugang liegt außerhalb der eigenen Verwaltungsebene.", "PORTAL_ROLE_HIERARCHY_DENIED");
    }
    if (roleHasPersonnelLearningDefaults(liveTarget.role)) {
      assertPersonnelLearningRoleAccountAdministrationAllowed(liveActor, {
        role: liveTarget.role,
        homeLocationId: liveEmployeeScope?.home_location_id || "",
        preferredDepartmentId: liveEmployeeScope?.preferred_department_id || null,
      });
    }
    const result = await organization.unlockPortalUser(employeeNumber);
    if (!result.rowsAffected) throw httpError(404, "Der Zugang wurde nicht gefunden.");
    await organization.insertAudit(
      liveActor.employeeNumber,
      "portal.user.unlock",
      "portal_user",
      employeeNumber,
    );
  });
  const [users, roles] = await Promise.all([
    portalUsersForActor(responseProjectionActor),
    portalRolesForUserAdministrationActor(responseProjectionActor),
  ]);
  response.json({ users, roles });
});

function loanSettingsActor(request, { mutation = false } = {}) {
  const session = requirePortalAnyPermissionOrLocal(request, ["loans:settings"], { csrf: mutation });
  if (!isLocalSystemSession(session) && !RIGHTS_ADMIN_PORTAL_ROLES.has(session.role)) {
    throw httpError(
      403,
      "Die Einstellungen der Leihe sind nur für Personalleitung und höhere Rollen verfügbar.",
      "PORTAL_PERMISSION_DENIED",
    );
  }
  return session;
}

function loanLocationSettingRow(locationId) {
  return loanModuleRepository.getLocationSetting({ locationId });
}

function parsedBranchLoanOverviewColumns(value) {
  if (Array.isArray(value)) return value;
  if (typeof value !== "string") return null;
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

function normalizedBranchLoanOverviewColumns(value) {
  const configured = parsedBranchLoanOverviewColumns(value);
  if (!configured) return [...defaultBranchLoanOverviewColumns];
  const selected = new Set(configured
    .map((column) => String(column || "").trim())
    .filter((column) => branchLoanOverviewColumnIds.includes(column)));
  return branchLoanOverviewColumnIds.filter((column) => (
    column === "borrowerName" || selected.has(column)
  ));
}

function requestedBranchLoanOverviewColumns(value) {
  if (!Array.isArray(value)) {
    throw httpError(
      400,
      "Bitte die sichtbaren Spalten der Filialkonto-Leihansicht angeben.",
      "LOAN_BRANCH_OVERVIEW_COLUMNS_INVALID",
    );
  }
  const invalid = value.some((column) => (
    typeof column !== "string" || !branchLoanOverviewColumnIds.includes(column.trim())
  ));
  if (invalid) {
    throw httpError(
      400,
      "Die Auswahl enthÃ¤lt eine nicht unterstÃ¼tzte Leihspalte.",
      "LOAN_BRANCH_OVERVIEW_COLUMNS_INVALID",
    );
  }
  return normalizedBranchLoanOverviewColumns(value);
}

function loanOverviewColumnsForSession(session, setting) {
  if (session?.sessionKind === "organization" && session?.accountType === "branch") {
    return normalizedBranchLoanOverviewColumns(setting?.branch_overview_columns);
  }
  return [...defaultPersonalLoanOverviewColumns];
}

function publicLoanOverviewItem(row, columns) {
  const values = {
    borrowerName: row.borrower_nickname || row.borrower_full_name || "",
    employeeNumber: row.borrower_employee_number || "",
    description: row.description_snapshot,
    articleNumber: row.article_number,
    serialNumber: row.serial_number || "",
    dueDate: row.due_date || null,
  };
  return Object.fromEntries(columns.map((column) => [column, values[column]]));
}

function publicLoanLocationSetting(row, { includeConfiguration = false } = {}) {
  if (!row) return null;
  const result = {
    locationId: row.location_id,
    locationName: row.location_name,
    locationActive: Boolean(row.location_active),
    enabled: Boolean(row.enabled) && Boolean(row.location_active),
    articleLookup: {
      enabled: Boolean(row.article_lookup_enabled),
      provider: row.article_lookup_provider || "none",
      configured: Boolean(row.article_lookup_enabled && row.article_lookup_base_url),
    },
    documentRecipient: row.document_recipient_employee_number ? {
      employeeNumber: row.document_recipient_employee_number,
      name: row.document_recipient_nickname || row.document_recipient_full_name || row.document_recipient_employee_number,
    } : null,
    photoPdf: {
      outputMode: row.photo_pdf_output_mode === "blackwhite" ? "blackwhite" : "grayscale",
      originalRetention: row.photo_original_retention === "delete" ? "delete" : "retain",
    },
    branchOverview: {
      columns: normalizedBranchLoanOverviewColumns(row.branch_overview_columns),
    },
    updatedBy: row.updated_by || "",
    updatedAt: row.updated_at || null,
  };
  if (includeConfiguration) {
    result.articleLookup.baseUrl = row.article_lookup_base_url || "";
    const provider = externalNotificationProviderStatus().email || {};
    result.emailDelivery = {
      enabled: Boolean(row.document_email_enabled),
      recipient: row.document_recipient_email || "",
      provider: {
        ...provider,
        loanDocumentAvailable: externalNotificationEventAvailable("email", "loan_document"),
      },
    };
  }
  return result;
}

async function loanDocumentRecipientEmailState(employeeNumber) {
  const normalizedEmployeeNumber = String(employeeNumber || "").trim();
  if (!normalizedEmployeeNumber) return { available: false, status: "not_configured", recipient: "" };
  try {
    const [targets, row] = await Promise.all([
      personalNotificationMasterTargets(normalizedEmployeeNumber),
      personalNotificationContactsRepository.get(normalizedEmployeeNumber),
    ]);
    const email = personalNotificationTargetState(row, targets, "email");
    return {
      available: email.verified === true,
      status: email.status,
      recipient: email.verified ? email.value : "",
    };
  } catch {
    return { available: false, status: "unavailable", recipient: "" };
  }
}

async function publicLoanLocationSettingWithEmailState(row, options = {}) {
  const result = publicLoanLocationSetting(row, options);
  if (!result?.documentRecipient) return result;
  const email = await loanDocumentRecipientEmailState(result.documentRecipient.employeeNumber);
  result.documentRecipient.emailDelivery = {
    available: email.available,
    status: email.status,
  };
  return result;
}

async function loanLocationForSession(session, input = {}) {
  let locationId = String(input.locationId || input.location || session?.homeLocationId || "").trim();
  if (!locationId && isLocalSystemSession(session)) {
    locationId = String((await getLocations(false))[0]?.id || "");
  }
  if (!locationId) {
    throw httpError(
      400,
      "Bitte einen Standort für die Leihe auswählen.",
      "LOAN_LOCATION_REQUIRED",
    );
  }
  locationId = normalizeLocationId(locationId);
  await validateLocationExists(locationId);
  const canUseManagedLocation = sessionHasGlobalScope(session)
    || session?.permissions?.some((permission) => [
      "loans:location:read",
      "loans:location:manage",
      "loans:settings",
      LOAN_BRANCH_OVERVIEW_MANAGE_PERMISSION,
    ].includes(permission));
  if (canUseManagedLocation) {
    assertSessionContextScope(session, { locationId });
  } else if (session?.sessionKind === "organization") {
    assertSessionContextScope(session, { locationId });
  } else if (String(session?.homeLocationId || "") !== locationId) {
    throw httpError(
      403,
      "Die Leihe ist nur für den eigenen Standort verfügbar.",
      "PORTAL_SCOPE_DENIED",
    );
  }
  return locationId;
}

async function enabledLoanLocationForSession(session, input = {}) {
  const locationId = await loanLocationForSession(session, input);
  const setting = await loanLocationSettingRow(locationId);
  if (!setting?.location_active || !setting?.enabled) {
    throw httpError(
      403,
      "Die Leihe ist für diesen Standort nicht freigeschaltet.",
      "LOAN_LOCATION_DISABLED",
    );
  }
  return setting;
}

function publicArticle(row) {
  if (!row) return null;
  return {
    articleNumber: row.article_number,
    description: row.description,
    identifiers: (Array.isArray(row.identifiers) ? row.identifiers : []).map((identifier) => ({
      type: identifier.identifier_type,
      value: identifier.identifier_value,
      sourceProvider: identifier.source_provider,
      verifiedAt: identifier.verified_at || null,
    })),
    sourceProvider: row.source_provider,
    sourceProductNumber: row.source_product_number || "",
    sourceUrl: row.source_url || "",
    sourceFetchedAt: row.source_fetched_at || null,
    active: Boolean(row.active),
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function articleRow(articleNumber) {
  return loanModuleRepository.getArticle({ articleNumber });
}

async function articleRowByIdentifier(identifier) {
  if (identifier.type === "internal") return articleRow(identifier.value);
  return loanModuleRepository.getArticleByIdentifier({
    identifierType: identifier.type,
    identifierValue: identifier.value,
  });
}

function normalizedArticleDescription(value, { required = false } = {}) {
  const description = String(value || "").replace(/\s+/g, " ").trim();
  if ((!description && required) || description.length > 300) {
    throw httpError(
      400,
      required
        ? "Bitte eine Artikelbezeichnung mit höchstens 300 Zeichen eintragen."
        : "Die Artikelbezeichnung darf höchstens 300 Zeichen lang sein.",
      "ARTICLE_DESCRIPTION_INVALID",
    );
  }
  return description;
}

function loanArticleArchivedError(articleNumber) {
  return httpError(
    409,
    `Der Artikel ${articleNumber} ist archiviert und kann nicht für neue Leihvorgänge verwendet werden.`,
    "LOAN_ARTICLE_ARCHIVED",
  );
}

function loanArticleIdentityConflictError() {
  return httpError(
    409,
    "Artikelnummer und Quellidentität verweisen auf unterschiedliche Artikel.",
    "LOAN_ARTICLE_IDENTITY_CONFLICT",
  );
}

async function saveArticleRecord(article, actorEmployeeNumber, {
  catalogRepository = salesArticleCatalogRepository,
  readRepository = loanModuleRepository,
  allowArchivedReference = false,
} = {}) {
  const sourceProvider = ["manual", "shopware_storefront", "import"].includes(article.sourceProvider)
    ? article.sourceProvider
    : "manual";
  const articleNumber = normalizeArticleNumber(article.articleNumber);
  const sourceSystem = sourceProvider === "shopware_storefront"
    ? "shopware.storefront"
    : sourceProvider === "import" ? "f18.loan_catalog" : "manual.loan";
  const sourceArticleKey = String(article.sourceProductNumber || articleNumber).trim();
  const [byNumber, bySource] = await Promise.all([
    catalogRepository.getByArticleNumber(articleNumber),
    catalogRepository.getBySource({ sourceSystem, sourceArticleKey }),
  ]);
  if (byNumber && bySource && byNumber.productId !== bySource.productId) {
    throw loanArticleIdentityConflictError();
  }
  const current = byNumber || bySource;
  if (current && !current.active) {
    if (allowArchivedReference) {
      const archived = await readRepository.getArticle({
        articleNumber: current.articleNumber,
      });
      if (archived) return archived;
    }
    throw loanArticleArchivedError(current.articleNumber);
  }
  if (current?.currentSourceSystem === "manual.article-catalog") {
    const governed = await readRepository.getArticle({
      articleNumber: current.articleNumber,
    });
    if (!governed) {
      throw httpError(
        409,
        "Der lokal verwaltete Artikel konnte nicht konsistent aufgelöst werden.",
        "LOAN_ARTICLE_UNRESOLVED",
      );
    }
    return governed;
  }
  const effectiveArticleNumber = bySource ? current.articleNumber : articleNumber;
  const incomingIdentifier = article.identifier && article.identifier.type !== "internal"
    ? article.identifier
    : null;
  const identifiers = (current?.identifiers || []).flatMap((identifier) => {
    const observations = Array.isArray(identifier.equivalentIdentifiers)
      && identifier.equivalentIdentifiers.length
      ? identifier.equivalentIdentifiers
      : [identifier];
    return observations.map((observation) => ({
      identifierType: observation.identifierType,
      identifierValue: observation.identifierValue,
      isPrimary: observation.isPrimary,
      sourceField: observation.sourceField,
      sourceRank: observation.sourceRank,
      sourceProvider: observation.sourceProvider,
      verifiedAt: observation.verifiedAt,
      createdBy: observation.createdBy,
      updatedBy: observation.updatedBy,
      createdAt: observation.createdAt,
      updatedAt: observation.updatedAt,
    }));
  });
  if (incomingIdentifier && !identifiers.some((identifier) => (
    identifier.identifierType === incomingIdentifier.type
    && identifier.identifierValue === incomingIdentifier.value
  ))) {
    identifiers.push({
      identifierType: incomingIdentifier.type,
      identifierValue: incomingIdentifier.value,
      isPrimary: identifiers.length === 0,
      sourceField: `${sourceProvider}.identifier`,
      sourceRank: null,
    });
  }
  const prices = (current?.prices || []).map((price) => ({
    priceType: price.priceType,
    amount: price.amount,
    currency: price.currency,
    priceBasis: price.priceBasis,
    qualityStatus: price.qualityStatus,
    sourceField: price.sourceField,
  }));
  const snapshotAt = article.sourceFetchedAt || new Date().toISOString();
  const importedArticle = {
    sourceArticleKey,
    articleNumber: effectiveArticleNumber,
    description: normalizedArticleDescription(article.description, { required: true }),
    active: true,
    sourceUpdatedAt: article.sourceFetchedAt || null,
    identifiers,
    prices,
    sourceMetadata: {
      provider: sourceProvider,
      productNumber: String(article.sourceProductNumber || ""),
      url: String(article.sourceUrl || ""),
      fetchedAt: article.sourceFetchedAt || null,
      createdBy: String(actorEmployeeNumber),
      updatedBy: String(actorEmployeeNumber),
      createdAt: snapshotAt,
      updatedAt: snapshotAt,
    },
  };
  const contentSha256 = salesArticleImportContentSha256([importedArticle]);
  await catalogRepository.importSnapshot({
    snapshot: {
      sourceSystem,
      sourceProfileVersion: "operational-article-v1",
      sourceSchemaSha256: crypto.createHash("sha256")
        .update("grabenplaner-operational-article-v1")
        .digest("hex"),
      sourceFileSha256: crypto.createHash("sha256").update(JSON.stringify({
        sourceSystem,
        sourceArticleKey,
        sourceUrl: String(article.sourceUrl || "").slice(0, 1000),
        sourceFetchedAt: article.sourceFetchedAt || null,
      })).digest("hex"),
      contentSha256,
      snapshotAt,
      articles: [importedArticle],
    },
    actor: actorEmployeeNumber,
    timestamp: new Date().toISOString(),
  });
  return readRepository.getArticle({ articleNumber: effectiveArticleNumber });
}

function articleLookupHttpError(error) {
  if (!(error instanceof ArticleCatalogError)) return error;
  const status = error.code === "ARTICLE_LOOKUP_NOT_FOUND" ? 404
    : [
      "ARTICLE_NUMBER_INVALID",
      "ARTICLE_IDENTIFIER_INVALID",
      "ARTICLE_IDENTIFIER_CHECKSUM_INVALID",
    ].includes(error.code) ? 400
      : error.code === "ARTICLE_LOOKUP_URL_INVALID" ? 503
        : 502;
  return httpError(status, error.message, error.code);
}

function articleLookupIsFresh(row, now = Date.now()) {
  const storefrontRevision = row?.source_provider === "shopware_storefront"
    || row?.revision_source_system === "shopware.storefront";
  if (!storefrontRevision || !row.source_fetched_at) return false;
  const fetchedAt = new Date(row.source_fetched_at).getTime();
  return Number.isFinite(fetchedAt) && now - fetchedAt < 24 * 60 * 60 * 1000;
}

function assertArticleLookupRateLimit(actor) {
  const key = String(actor?.employeeNumber || "local");
  const now = Date.now();
  if (articleLookupRateLimits.get(key, now).length >= 60) {
    throw httpError(
      429,
      "Zu viele externe Artikelsuchen. Bitte in einigen Minuten erneut versuchen.",
      "ARTICLE_LOOKUP_RATE_LIMITED",
    );
  }
  articleLookupRateLimits.record(key, now);
}

