function publicLoanPhotoAttachment(row) {
  return {
    id: row.id,
    phase: row.phase,
    revision: Number(row.attachment_revision),
    sourcePhotoCount: Number(row.source_photo_count),
    outputMode: row.output_mode,
    originalRetention: row.original_retention,
    filename: row.filename,
    byteSize: Number(row.byte_size),
    sha256: row.sha256,
    createdAt: row.created_at,
    previewUrl: `/api/portal/v1/loans/photo-attachments/${encodeURIComponent(row.id)}/preview`,
    downloadUrl: `/api/portal/v1/loans/photo-attachments/${encodeURIComponent(row.id)}/download`,
  };
}

function loanDocumentDeliveryRows(documentId) {
  return loanModuleRepository.listLoanDocumentDeliveries({
    documentId: String(documentId || "").trim(),
  });
}

function loanDocumentDeliverySummary(document) {
  const rows = Array.isArray(document?.deliveries) ? document.deliveries : [];
  const emailRows = rows.filter((row) => row.channel === "email");
  const latestByRecipient = new Map();
  for (const row of emailRows) {
    const key = String(row.recipient_address || "").trim().toLowerCase()
      || `employee:${String(row.recipient_employee_number || "unknown")}`;
    latestByRecipient.set(key, row);
  }
  const latestEmailRows = [...latestByRecipient.values()];
  const lastEmail = emailRows.at(-1) || null;
  const failedRecipients = latestEmailRows.filter((row) => row.status === "failed");
  const emailStatus = failedRecipients.length
    ? "failed"
    : latestEmailRows.some((row) => row.status === "sent") ? "sent" : "not_requested";
  return {
    internalSent: rows.filter((row) => row.channel === "internal" && row.status === "sent").length,
    emailConfigured: emailRows.length > 0,
    emailStatus,
    emailAttempts: emailRows.length,
    emailRecipients: latestEmailRows.length,
    emailFailedRecipients: failedRecipients.length,
    emailFailureCodes: [...new Set(failedRecipients.map((row) => row.error_code).filter(Boolean))],
    lastEmailAttemptAt: lastEmail?.attempted_at || null,
  };
}

async function insertLoanDocumentDelivery({
  documentId,
  channel,
  recipientEmployeeNumber = null,
  recipientAddress = "",
  status,
  errorCode = "",
  attemptedByEmployeeNumber = null,
}) {
  const id = crypto.randomUUID();
  await loanModuleRepository.insertLoanDocumentDelivery({
    id,
    documentId,
    channel,
    recipientEmployeeNumber: recipientEmployeeNumber || null,
    recipientAddress: String(recipientAddress || "").slice(0, 320),
    status,
    errorCode: String(errorCode || "").slice(0, 120),
    attemptedByEmployeeNumber: attemptedByEmployeeNumber && attemptedByEmployeeNumber !== "local"
      ? attemptedByEmployeeNumber
      : null,
  });
  return id;
}

function publicLoanDocument(row) {
  return {
    id: row.id,
    type: row.document_type,
    label: row.document_type === "return" ? "Rücknahmebeleg" : "Ausgabebeleg",
    revision: Number(row.loan_revision),
    filename: row.filename,
    byteSize: Number(row.byte_size),
    sha256: row.sha256,
    createdAt: row.created_at,
    downloadUrl: `/api/portal/v1/loans/documents/${encodeURIComponent(row.id)}`,
    delivery: loanDocumentDeliverySummary(row),
  };
}

function loanDueState(row, today = viennaTodayIso()) {
  if (row.status !== "issued" || !row.due_date) return row.status === "returned" ? "returned" : "open";
  if (row.due_date < today) return "overdue";
  if (row.due_date === today) return "due_today";
  if (row.due_date <= addDays(today, 3)) return "due_soon";
  return "open";
}

function loanPdfBranding(locationId) {
  const branding = brandingForLocation(locationId);
  const source = mobileBrandingSourceForSession({
    role: "employee",
    homeLocationId: locationId,
  });
  return {
    companyName: branding.companyName,
    logo: localAssetPathFromUrl(branding.logoUrl),
    colors: mobileBrandingTheme(source.raw),
  };
}

async function loanParticipant(employeeNumber) {
  const employee = await loanEmployeeRow(employeeNumber) || {};
  return {
    employeeNumber: String(employeeNumber || ""),
    name: employee.nickname || employee.full_name || String(employeeNumber || ""),
  };
}

async function prepareLoanDocument(spec, actorEmployeeNumber) {
  const pdf = await renderLoanPdf(spec);
  const typeLabel = spec.type === "return" ? "Ruecknahme" : "Ausgabe";
  const filename = `Leihbeleg-${typeLabel}-${String(spec.loanId).slice(0, 8)}-R${Number(spec.revision)}.pdf`;
  const stored = await requireAmuStorage().saveBuffer({
    buffer: pdf,
    originalName: filename,
    maxBytes: 8 * 1024 * 1024,
  });
  return {
    id: crypto.randomUUID(),
    documentType: spec.type,
    loanRevision: Number(spec.revision),
    storageKey: stored.storageKey,
    filename,
    detectedMime: stored.detectedMime,
    byteSize: stored.byteSize,
    sha256: stored.sha256,
    createdByEmployeeNumber: actorEmployeeNumber === "local" ? null : actorEmployeeNumber,
    createdAt: stored.createdAt,
  };
}

async function prepareStoredLoanPhoto(input, actorEmployeeNumber) {
  let prepared;
  try {
    prepared = await prepareLoanPhoto(input);
  } catch (error) {
    if (error instanceof LoanPhotoError) {
      throw httpError(error.status, error.message, error.code);
    }
    throw error;
  }
  const stored = await requireAmuStorage().saveBuffer({
    buffer: prepared.buffer,
    originalName: prepared.filename,
    maxBytes: 3 * 1024 * 1024,
  });
  return {
    id: crypto.randomUUID(),
    buffer: prepared.buffer,
    storageKey: stored.storageKey,
    filename: prepared.filename,
    detectedMime: stored.detectedMime,
    byteSize: stored.byteSize,
    sha256: stored.sha256,
    pixelWidth: prepared.width,
    pixelHeight: prepared.height,
    createdByEmployeeNumber: actorEmployeeNumber === "local" ? null : actorEmployeeNumber,
    createdAt: stored.createdAt,
  };
}

async function prepareStoredLoanPhotoAttachment({
  loan,
  phase,
  preparedPhotos,
  positionOffset = 0,
  outputMode,
  originalRetention,
  actorEmployeeNumber,
}) {
  let pdf;
  try {
    pdf = await renderLoanPhotoPdf({
      photos: preparedPhotos.map((photo, index) => ({
        buffer: photo.buffer,
        filename: photo.filename,
        position: positionOffset + index + 1,
      })),
      phase,
      outputMode,
      titleContext: {
        locationId: loan.location_id,
        locationName: loan.location_name,
        loanId: String(loan.id).slice(0, 12),
        subtitle: "Unveränderliche Teilbeilage dieses Foto-Uploads",
        createdAt: new Date().toISOString(),
      },
    });
  } catch (error) {
    if (error instanceof LoanPhotoPdfError) {
      throw httpError(error.status, error.message, error.code);
    }
    throw error;
  }
  const typeLabel = phase === "return" ? "Rueckgabe" : "Ausgabe";
  const filename = `Leihfoto-Beilage-${typeLabel}-${String(loan.id).slice(0, 8)}.pdf`;
  const stored = await requireAmuStorage().saveBuffer({
    buffer: pdf,
    originalName: filename,
    maxBytes: 8 * 1024 * 1024,
  });
  const sourceFingerprint = crypto.createHash("sha256")
    .update(JSON.stringify(preparedPhotos.map((photo) => photo.sha256)))
    .digest("hex");
  return {
    id: crypto.randomUUID(),
    storageKey: stored.storageKey,
    filename,
    detectedMime: stored.detectedMime,
    byteSize: stored.byteSize,
    sha256: stored.sha256,
    sourcePhotoCount: preparedPhotos.length,
    sourceFingerprint,
    outputMode,
    originalRetention,
    createdByEmployeeNumber: actorEmployeeNumber === "local" ? null : actorEmployeeNumber,
    createdAt: stored.createdAt,
  };
}

const loanPhotoUploadLocks = new Map();

async function acquireLoanPhotoUploadLock(loanId) {
  const key = String(loanId || "").trim();
  const previous = loanPhotoUploadLocks.get(key) || Promise.resolve();
  let releaseCurrent;
  const current = new Promise((resolve) => {
    releaseCurrent = resolve;
  });
  const tail = previous.catch(() => {}).then(() => current);
  loanPhotoUploadLocks.set(key, tail);
  await previous.catch(() => {});
  return () => {
    releaseCurrent();
    if (loanPhotoUploadLocks.get(key) === tail) loanPhotoUploadLocks.delete(key);
  };
}

