    pixelWidth: prepared.pixelWidth,
    pixelHeight: prepared.pixelHeight,
    originalRetained: prepared.originalRetained !== false,
    originalDeletedAt: prepared.originalDeletedAt || null,
    originalDeletionReason: prepared.originalDeletionReason || "",
    createdByEmployeeNumber: prepared.createdByEmployeeNumber,
