async function fallbackLoanDocumentRecipient(locationId) {
  const users = await loanModuleRepository.listFallbackDocumentRecipients();
  for (const user of users) {
    const permissions = effectivePortalPermissionState(
      user.employee_number,
      user.role,
      user.permissions,
      user.granted_permissions,
      user.denied_permissions,
    ).effectivePermissions;
    if (!permissions.includes("loans:documents:read")) continue;
    const scopes = portalAccessScopesForPrincipal({
      employeeNumber: user.employee_number,
      role: user.role,
      homeLocationId: user.home_location_id,
      preferredDepartmentId: user.preferred_department_id,
      scopesValue: user.access_scopes,
    });
    if (portalScopeMatchesAnyContext(user.role, scopes, [{ locationId, departmentId: null }])) {
      return user.employee_number;
    }
  }
  return "";
}

async function loanDocumentRecipients(loan, documentType) {
  const setting = await loanLocationSettingRow(loan.location_id);
  const configured = String(setting?.document_recipient_employee_number || "").trim();
  const fallback = configured ? "" : await fallbackLoanDocumentRecipient(loan.location_id);
  const recipients = new Set([
    loan.borrower_employee_number,
    documentType === "return" ? loan.return_recorded_by_employee_number : loan.created_by_employee_number,
    documentType === "return" ? loan.return_witness_employee_number : "",
    configured || fallback,
  ].filter(Boolean));
  return [...recipients];
}

async function deliverLoanDocumentEmail(loan, document, {
  recipient = "",
  recipientEmployeeNumber = null,
  attemptedByEmployeeNumber = null,
} = {}) {
  const destination = String(recipient || "").trim().toLowerCase();
  if (!destination) return { attempted: false, status: "not_requested" };
  let status = "failed";
  let errorCode = "";
  try {
    const content = requireAmuStorage().readBuffer({
      storageKey: document.storage_key,
      byteSize: document.byte_size,
      sha256: document.sha256,
      detectedMime: document.detected_mime,
      originalFilename: document.filename,
    });
    await externalNotificationAdapter.sendLoanDocument({
      recipient: destination,
      subject: `Grabenplaner · ${document.document_type === "return" ? "Rücknahmebeleg" : "Ausgabebeleg"}`,
      text: [
        `Leihvorgang: ${loan.id}`,
        `Teammitglied: ${loan.borrower_employee_number} · ${loan.borrower_nickname || loan.borrower_full_name}`,
        `Standort: ${loan.location_id} · ${loan.location_name}`,
        "Der unveränderte Beleg ist als PDF beigefügt.",
      ].join("\n"),
      filename: document.filename,
      buffer: content,
    });
    status = "sent";
  } catch (error) {
    errorCode = String(error.code || "LOAN_DOCUMENT_EMAIL_FAILED");
  }
  await insertLoanDocumentDelivery({
    documentId: document.id,
    channel: "email",
    recipientEmployeeNumber,
    recipientAddress: destination,
    status,
    errorCode,
    attemptedByEmployeeNumber,
  });
  (await auditPortal(
    attemptedByEmployeeNumber || "system",
    `loan.document.email.${status}`,
    "loan_document",
    document.id,
    JSON.stringify({ loanId: loan.id, errorCode }),
  ));
  return { attempted: true, status, errorCode };
}

async function configuredLoanDocumentEmailTargets(loan, setting) {
  if (!setting?.document_email_enabled) return { targets: [], internalRecipientStatus: "not_requested" };
  const targets = [];
  const configuredEmployeeNumber = String(setting.document_recipient_employee_number || "").trim();
  const internalEmployeeNumber = configuredEmployeeNumber
    || await fallbackLoanDocumentRecipient(loan.location_id);
  let internalRecipientStatus = "not_configured";
  if (internalEmployeeNumber) {
    const internalEmail = await loanDocumentRecipientEmailState(internalEmployeeNumber);
    internalRecipientStatus = internalEmail.status;
    if (internalEmail.available && internalEmail.recipient) {
      targets.push({
        recipient: internalEmail.recipient,
        recipientEmployeeNumber: internalEmployeeNumber,
        kind: "internal_recipient",
      });
    }
  }
  const additionalEmail = String(setting.document_recipient_email || "").trim().toLowerCase();
  if (additionalEmail) targets.push({ recipient: additionalEmail, recipientEmployeeNumber: null, kind: "additional" });
  const deduplicated = new Map();
  for (const target of targets) {
    const key = target.recipient.toLowerCase();
    const current = deduplicated.get(key);
    deduplicated.set(key, current
      ? { ...current, recipientEmployeeNumber: current.recipientEmployeeNumber || target.recipientEmployeeNumber }
      : target);
  }
  return { targets: [...deduplicated.values()], internalRecipientStatus };
}

function loanDocumentEmailFailureMessage(errorCodes = []) {
  const codes = new Set(errorCodes);
  if (codes.has("EXTERNAL_NOTIFICATION_EVENT_DISABLED")) {
    return "Leihbeleg-E-Mails sind am Server noch nicht freigeschaltet (Ereignis „loan_document“).";
  }
  if (codes.has("EXTERNAL_NOTIFICATION_PROVIDER_NOT_CONFIGURED")
    || codes.has("EXTERNAL_NOTIFICATION_SMTP_REQUIRED")) {
    return "Der SMTP-Versand für Leihbelege ist derzeit nicht betriebsbereit.";
  }
  if (codes.has("EXTERNAL_NOTIFICATION_DISPATCH_DISABLED")) {
    return "Der externe E-Mail-Versand ist administrativ deaktiviert.";
  }
  if (codes.has("EXTERNAL_NOTIFICATION_SENDER_NOT_APPROVED")) {
    return "Der Absender für Leihbeleg-E-Mails ist noch nicht freigegeben.";
  }
  return "Mindestens eine Leihbeleg-E-Mail konnte nicht zugestellt werden.";
}

async function deliverConfiguredLoanDocumentEmails(loan, document, {
  attemptedByEmployeeNumber = null,
} = {}) {
  const setting = await loanLocationSettingRow(loan.location_id);
  const configured = await configuredLoanDocumentEmailTargets(loan, setting);
  const deliveries = [];
  for (const target of configured.targets) {
    deliveries.push(await deliverLoanDocumentEmail(loan, document, {
      recipient: target.recipient,
      recipientEmployeeNumber: target.recipientEmployeeNumber,
      attemptedByEmployeeNumber,
    }));
  }
  const errorCodes = [...new Set(deliveries.map((delivery) => delivery.errorCode).filter(Boolean))];
  const failed = deliveries.filter((delivery) => delivery.status === "failed").length;
  const sent = deliveries.filter((delivery) => delivery.status === "sent").length;
  return {
    attempted: deliveries.length > 0,
    status: failed ? "failed" : sent ? "sent" : "not_requested",
    recipients: deliveries.length,
    sent,
    failed,
    errorCodes,
    internalRecipientStatus: configured.internalRecipientStatus,
  };
}

async function notifyLoanDocumentAvailable(loan, document) {
  const publicDocument = publicLoanDocument(document);
  for (const recipient of await loanDocumentRecipients(loan, document.document_type)) {
    await createPortalNotification(
      recipient,
      "loan.document",
      `${publicDocument.label} verfügbar`,
      `Der Beleg für ${loan.borrower_employee_number} · ${loan.borrower_nickname || loan.borrower_full_name} wurde sicher abgelegt.`,
      {
        target: `/portal.html?tab=loan&loan=${encodeURIComponent(loan.id)}`,
        entityType: "loan_document",
        entityId: document.id,
        dedupeKey: `loan-document:${document.id}:${recipient}`,
      },
    );
    await insertLoanDocumentDelivery({
      documentId: document.id,
      channel: "internal",
      recipientEmployeeNumber: recipient,
      status: "sent",
      attemptedByEmployeeNumber: document.created_by_employee_number,
    });
  }
  await deliverConfiguredLoanDocumentEmails(loan, document, {
    attemptedByEmployeeNumber: document.created_by_employee_number,
  });
}

function assertLoanDocumentAccess(session, document) {
  if (!document) {
    throw httpError(404, "Der Leihbeleg wurde nicht gefunden.", "LOAN_DOCUMENT_NOT_FOUND");
  }
  if (isLocalSystemSession(session)) return;
  const participants = new Set([
    document.borrower_employee_number,
    document.created_by_employee_number,
    document.return_recorded_by_employee_number,
    document.return_witness_employee_number,
  ].filter(Boolean));
  if (participants.has(session.employeeNumber)) return;
  if (!session.permissions?.includes("loans:documents:read")) {
    throw httpError(403, "Für diesen Leihbeleg fehlt die Berechtigung.", "LOAN_DOCUMENT_DENIED");
  }
  assertSessionContextScope(session, { locationId: document.location_id });
}

async function assertLoanPhotoAccess(session, photo) {
  if (!photo) throw httpError(404, "Das Leihfoto wurde nicht gefunden.", "LOAN_PHOTO_NOT_FOUND");
  if (isLocalSystemSession(session)) return;
  const participants = new Set([
    photo.borrower_employee_number,
    photo.created_by_employee_number,
    photo.return_recorded_by_employee_number,
    photo.return_witness_employee_number,
  ].filter(Boolean));
  if (participants.has(session.employeeNumber)) return;
  if (photo.phase === "return") {
    const pendingWitness = await loanModuleRepository.getPendingWitnessPayload({
      loanId: photo.loan_id,
      employeeNumber: session.employeeNumber,
    });
    const pendingPayload = parseLoanReturnConfirmationPayload(pendingWitness);
    if (Array.isArray(pendingPayload.photoIds)
      && pendingPayload.photoIds.includes(photo.id)) return;
  }
  if (!session.permissions?.some((permission) => [
    "loans:location:read",
    "loans:location:manage",
    "loans:documents:read",
  ].includes(permission))) {
    throw httpError(403, "Für dieses Leihfoto fehlt die Berechtigung.", "LOAN_PHOTO_DENIED");
  }
  assertSessionContextScope(session, { locationId: photo.location_id });
}

async function assertLoanPhotoAttachmentAccess(session, attachment) {
  if (!attachment) {
    throw httpError(404, "Die Foto-PDF-Beilage wurde nicht gefunden.", "LOAN_PHOTO_ATTACHMENT_NOT_FOUND");
  }
  if (isLocalSystemSession(session)) return;
  const participants = new Set([
    attachment.borrower_employee_number,
    attachment.created_by_employee_number,
    attachment.return_recorded_by_employee_number,
    attachment.return_witness_employee_number,
  ].filter(Boolean));
  if (participants.has(session.employeeNumber)) return;
  if (attachment.phase === "return") {
    const pendingWitness = await loanModuleRepository.getPendingWitnessPayload({
      loanId: attachment.loan_id,
      employeeNumber: session.employeeNumber,
    });
    const pendingPayload = parseLoanReturnConfirmationPayload(pendingWitness);
    if (Array.isArray(pendingPayload.photoAttachmentIds)
      && pendingPayload.photoAttachmentIds.includes(attachment.id)) return;
  }
  if (!session.permissions?.some((permission) => [
    "loans:location:read",
    "loans:location:manage",
    "loans:documents:read",
  ].includes(permission))) {
    throw httpError(
      403,
      "Für diese Foto-PDF-Beilage fehlt die Berechtigung.",
      "LOAN_PHOTO_ATTACHMENT_DENIED",
    );
  }
  assertSessionContextScope(session, { locationId: attachment.location_id });
}

function publicLoanItem(row) {
  return {
    id: row.id,
    position: Number(row.position),
    articleNumber: row.article_number,
    description: row.description_snapshot,
    serialNumber: row.serial_number || "",
    quantity: Number(row.quantity || 1),
    conditionOut: row.condition_out || "good",
    conditionReturn: row.condition_return || "",
    note: row.item_note || "",
  };
}

function publicLoanEvent(row) {
  let payload = {};
  try {
    const parsed = JSON.parse(String(row.payload_json || "{}"));
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) payload = parsed;
  } catch {}
  return {
    id: Number(row.id),
    actorEmployeeNumber: row.actor_employee_number || "",
    type: row.event_type,
    revision: Number(row.revision),
    payload,
    createdAt: row.created_at,
  };
}

async function publicLoan(row, { includeEvents = true } = {}) {
  if (!row) return null;
  const [
    pendingReturnConfirmation,
    returnPreparation,
    itemRows,
    photoRows,
    attachmentRows,
    documentRows,
    eventRows,
  ] = await Promise.all([
    loanPendingReturnConfirmationRow(row.id),
    loanReturnPreparationRow(row.id),
    loanItemRows(row.id),
    loanPhotoRows(row.id),
    loanPhotoAttachmentRows(row.id),
    loanDocumentRows(row.id),
    includeEvents ? loanEventRows(row.id) : Promise.resolve([]),
  ]);
  return {
    id: row.id,
    location: {
      id: row.location_id,
      name: row.location_name,
    },
    borrower: {
      employeeNumber: row.borrower_employee_number,
      name: row.borrower_nickname || row.borrower_full_name,
    },
    createdBy: {
      employeeNumber: row.created_by_employee_number,
      name: row.creator_nickname || row.creator_full_name,
    },
    dueDate: row.due_date || null,
    dueState: loanDueState(row),
    status: row.status,
    notes: row.notes || "",
    issuedAt: row.issued_at || null,
    returnedAt: row.returned_at || null,
    returnRecordedByEmployeeNumber: row.return_recorded_by_employee_number || "",
    returnWitness: row.return_witness_employee_number ? {
      employeeNumber: row.return_witness_employee_number,
      name: row.witness_nickname || row.witness_full_name || row.return_witness_employee_number,
    } : null,
    pendingReturnConfirmation: pendingReturnConfirmation
      ? await publicLoanReturnConfirmation(pendingReturnConfirmation, { includeLoan: false })
      : null,
    returnPreparation: returnPreparation
      ? await publicLoanReturnPreparation(returnPreparation)
      : null,
    borrowerReturnConfirmed: Boolean(row.borrower_return_confirmed),
    revision: Number(row.revision || 1),
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    items: itemRows.map(publicLoanItem),
    photos: photoRows.map(publicLoanPhoto),
    photoAttachments: attachmentRows.map(publicLoanPhotoAttachment),
    documents: documentRows.map(publicLoanDocument),
    events: eventRows.map(publicLoanEvent),
  };
}

function loanCanManageLocation(session) {
  return isLocalSystemSession(session)
    || session?.permissions?.includes("loans:location:manage") === true;
}

function assertLoanReadAccess(session, row) {
  if (!row) throw httpError(404, "Der Leihvorgang wurde nicht gefunden.", "LOAN_NOT_FOUND");
  if (row.borrower_employee_number === session.employeeNumber
    && session.permissions?.includes("loans:self:read")) return;
  if (isLocalSystemSession(session)
    || session.permissions?.some((permission) => [
      "loans:location:read",
      "loans:location:manage",
    ].includes(permission))) {
    assertSessionContextScope(session, { locationId: row.location_id });
    return;
  }
  throw httpError(403, "Dieser Leihvorgang liegt außerhalb des eigenen Bereichs.", "LOAN_SCOPE_DENIED");
}

function normalizeLoanNotes(value, maximumLength = 1000) {
  try {
    return normalizeLoanText(stripEmoji(String(value || "")), maximumLength);
  } catch (error) {
    throw loanWorkflowHttpError(error);
  }
}

function normalizeLoanIssueBody(body) {
  try {
    return {
      dueDate: normalizeLoanDueDate(body?.dueDate, {
        minimum: viennaTodayIso(),
        maximum: addDays(viennaTodayIso(), 3650),
      }),
      items: normalizeLoanIssueItems(body?.items),
      notes: normalizeLoanText(stripEmoji(String(body?.notes || "")), 1000),
    };
  } catch (error) {
    throw loanWorkflowHttpError(error);
  }
}

function appendLoanEvent(
  loanId,
  actorEmployeeNumber,
  eventType,
  revision,
  payload = {},
  repository = loanModuleRepository,
) {
  return repository.insertLoanEvent({
    loanId,
    actorEmployeeNumber: actorEmployeeNumber === "local" ? null : actorEmployeeNumber,
    eventType: String(eventType),
    revision: Number(revision),
    payloadJson: JSON.stringify(payload && typeof payload === "object" ? payload : {}),
  });
}

function loanExpectedRevision(body) {
  const expectedRevision = Number(body?.expectedRevision);
  if (!Number.isInteger(expectedRevision) || expectedRevision < 1) {
    throw httpError(400, "Die erwartete Revision fehlt.", "LOAN_VERSION_REQUIRED");
  }
  return expectedRevision;
}

function assertLoanManagementAccess(actor, row) {
  if (!row) throw httpError(404, "Der Leihvorgang wurde nicht gefunden.", "LOAN_NOT_FOUND");
  if (!loanCanManageLocation(actor)) {
    throw httpError(403, "Für die Bearbeitung fehlt die Standortberechtigung.", "LOAN_MANAGEMENT_DENIED");
  }
  assertSessionContextScope(actor, { locationId: row.location_id });
}

async function normalizeLoanManagementBody(body, row, { requireReturnCondition = false } = {}) {
  const storedItems = await loanItemRows(row.id);
  if (!Array.isArray(body?.items) || body.items.length !== storedItems.length) {
    throw httpError(
      400,
      "Die Bearbeitung muss alle ausgeliehenen Artikel enthalten.",
      "LOAN_MANAGEMENT_ITEMS_INVALID",
    );
  }
  const byPosition = new Map();
  for (const item of body.items) {
    const position = Number(item?.position);
    if (!Number.isInteger(position) || byPosition.has(position)) {
      throw httpError(
        400,
        "Die Artikelpositionen sind unvollständig oder doppelt.",
        "LOAN_MANAGEMENT_ITEMS_INVALID",
      );
    }
    byPosition.set(position, item);
  }
  try {
    return {
      dueDate: normalizeLoanDueDate(body?.dueDate, {
        maximum: addDays(viennaTodayIso(), 3650),
      }),
      notes: normalizeLoanText(stripEmoji(String(body?.notes || "")), 1000),
      items: storedItems.map((stored) => {
        const item = byPosition.get(Number(stored.position));
        if (!item) {
          throw httpError(
            400,
            "Die Bearbeitung muss alle ausgeliehenen Artikel enthalten.",
            "LOAN_MANAGEMENT_ITEMS_INVALID",
          );
        }
        return {
          position: Number(stored.position),
          serialNumber: normalizeLoanText(item.serialNumber, 100),
          conditionOut: normalizeLoanCondition(item.conditionOut),
          conditionReturn: normalizeLoanCondition(item.conditionReturn, {
            required: requireReturnCondition,
          }),
          note: normalizeLoanText(item.note, 500),
        };
      }),
    };
  } catch (error) {
    throw loanWorkflowHttpError(error);
  }
}

async function cancelPendingLoanReturnConfirmation(
  loanId,
  now,
  reason,
  repository = loanModuleRepository,
) {
  await repository.expireReturnConfirmations();
  const pending = await repository.getPendingReturnConfirmation({ loanId });
  if (!pending) return null;
  await repository.cancelReturnConfirmation({
    confirmationId: pending.id,
    respondedAt: now,
    responseNote: reason,
  });
  await repository.markConfirmationNotificationsRead({
    confirmationId: pending.id,
    readAt: now,
  });
  return pending.id;
}

async function loanBorrowerForIssue(actor, setting, requestedEmployeeNumber) {
  const requested = String(requestedEmployeeNumber || "").trim();
  if (isLocalSystemSession(actor)) {
    throw httpError(
      409,
      "Eine neue Leihe benötigt einen persönlich angemeldeten Mitarbeiterzugang.",
      "LOAN_ISSUE_PORTAL_LOGIN_REQUIRED",
    );
  }
  if (requested && requested !== actor.employeeNumber) {
    throw httpError(
      403,
      "Eine neue Leihe kann nur für den eigenen angemeldeten Zugang erfasst werden.",
      "LOAN_BORROWER_DENIED",
    );
  }
  const borrower = await loanEmployeeRow(actor.employeeNumber, { active: true });
  if (!borrower) {
    throw httpError(404, "Der angemeldete Mitarbeiter wurde nicht gefunden.", "LOAN_BORROWER_NOT_FOUND");
  }
  if (String(borrower.home_location_id || "") !== String(setting.location_id)) {
    throw httpError(
      403,
      "Der angemeldete Mitarbeiter gehört nicht zum ausgewählten Standort.",
      "LOAN_BORROWER_LOCATION_MISMATCH",
    );
  }
  return borrower;
}

async function articleRowsForLoan(items, repository = loanModuleRepository) {
  return Promise.all(items.map(async (item) => {
    const article = await repository.getActiveArticle({ articleNumber: item.articleNumber });
    if (!article?.active || !String(article.description || "").trim()) {
      throw httpError(
        409,
        `Position ${item.position}: Die Artikelbezeichnung muss zuerst aufgelöst oder manuell ergänzt werden.`,
        "LOAN_ARTICLE_UNRESOLVED",
      );
    }
    return article;
  }));
}

