app.post("/api/portal/v1/loans/:loanId/photos", async (request, response) => {
  const actor = requirePortalAnyPermissionOrLocal(
    request,
    ["loans:self:create", "loans:self:return", "loans:location:manage"],
    { csrf: true },
  );
  const loan = await loanRow(request.params.loanId);
  if (!loan) throw httpError(404, "Der Leihvorgang wurde nicht gefunden.", "LOAN_NOT_FOUND");
  const { fields, photos } = await parseLoanPhotoMultipart(request);
  const phase = fields.phase === "return" ? "return" : fields.phase === "issue" ? "issue" : "";
  if (!phase) throw httpError(400, "Bitte Ausgabe oder Rücknahme als Fotophase angeben.", "LOAN_PHOTO_PHASE_INVALID");
  if (loan.status !== "issued") {
    throw httpError(409, "Fotos können nur zu einer offenen Leihe ergänzt werden.", "LOAN_PHOTO_LOAN_CLOSED");
  }
  const managesLocation = loanCanManageLocation(actor);
  const ownPermission = phase === "issue" ? "loans:self:create" : "loans:self:return";
  if (!managesLocation && (loan.borrower_employee_number !== actor.employeeNumber
    || !actor.permissions?.includes(ownPermission))) {
    throw httpError(403, "Für diese Leihfotos fehlt die Berechtigung.", "LOAN_PHOTO_DENIED");
  }
  if (managesLocation) assertSessionContextScope(actor, { locationId: loan.location_id });
  if (phase === "return") {
    await expireLoanReturnConfirmations();
    if (await loanPendingReturnConfirmationRow(loan.id)) {
      throw httpError(
        409,
        "Rückgabefotos können während einer offenen Gegenbestätigung nicht verändert werden.",
        "LOAN_RETURN_CONFIRMATION_PENDING",
      );
    }
  }
  const releaseLoanPhotoUpload = await acquireLoanPhotoUploadLock(loan.id);
  try {
    const initialExistingCount = Number((await loanModuleRepository.countLoanPhotos({
      loanId: loan.id,
      phase,
    })).count);
    if (initialExistingCount + photos.length > MAX_LOAN_PHOTOS_PER_PHASE) {
      throw httpError(413, "Pro Ausgabe oder Rücknahme sind höchstens neun Fotos möglich.", "LOAN_PHOTO_TOO_MANY");
    }
    const photoSetting = await loanLocationSettingRow(loan.location_id);
    const outputMode = photoSetting?.photo_pdf_output_mode === "blackwhite" ? "blackwhite" : "grayscale";
    const originalRetention = photoSetting?.photo_original_retention === "delete" ? "delete" : "retain";
    const preparedPhotos = [];
    let preparedAttachment = null;
    let attachmentRevision = 0;
    amuMutationInProgress += 1;
    try {
      for (const photo of photos) {
        preparedPhotos.push(await prepareStoredLoanPhoto(photo, actor.employeeNumber));
      }
      preparedAttachment = await prepareStoredLoanPhotoAttachment({
        loan,
        phase,
        preparedPhotos,
        positionOffset: initialExistingCount,
        outputMode,
        originalRetention,
        actorEmployeeNumber: actor.employeeNumber,
      });
      if (originalRetention === "delete") {
        discardPreparedLoanPhotoOriginals(preparedPhotos);
      }
      await persistenceProvider.transaction(async (executor) => {
        const repositories = createApplicationRepositories(executor);
        const repository = repositories.loanModule;
        const currentLoan = await repository.getLoan({ loanId: loan.id });
      if (!currentLoan || currentLoan.status !== "issued") {
        throw httpError(
          409,
          "Fotos können nur zu einer offenen Leihe ergänzt werden.",
          "LOAN_PHOTO_LOAN_CLOSED",
        );
      }
      if (phase === "return" && await repository.getPendingReturnConfirmation({ loanId: loan.id })) {
        throw httpError(
          409,
          "Rückgabefotos können während einer offenen Gegenbestätigung nicht verändert werden.",
          "LOAN_RETURN_CONFIRMATION_PENDING",
        );
      }
      const currentExistingCount = Number((await repository.countLoanPhotos({
        loanId: loan.id,
        phase,
      })).count);
      if (currentExistingCount !== initialExistingCount) {
        throw httpError(
          409,
          "Die Leihfotos wurden gleichzeitig verändert. Bitte den Upload erneut durchführen.",
          "LOAN_PHOTO_CONCURRENT_CHANGE",
        );
      }
      if (currentExistingCount + preparedPhotos.length > MAX_LOAN_PHOTOS_PER_PHASE) {
        throw httpError(
          413,
          "Pro Ausgabe oder Rücknahme sind höchstens neun Fotos möglich.",
          "LOAN_PHOTO_TOO_MANY",
        );
      }
      for (const [index, prepared] of preparedPhotos.entries()) {
        await insertPreparedLoanPhoto(
          loan.id,
          phase,
          currentExistingCount + index + 1,
          prepared,
          repository,
        );
      }
      attachmentRevision = Number((await repository.nextPhotoAttachmentRevision({
        loanId: loan.id,
        phase,
      })).revision);
      await insertPreparedLoanPhotoAttachment(
        loan.id,
        phase,
        attachmentRevision,
        preparedAttachment,
        preparedPhotos,
        repository,
      );
      await appendLoanEvent(loan.id, actor.employeeNumber, "photos_added", Number(currentLoan.revision), {
        phase,
        count: preparedPhotos.length,
        photoIds: preparedPhotos.map((photo) => photo.id),
        photoAttachmentId: preparedAttachment.id,
        photoAttachmentRevision: attachmentRevision,
        photoPdfOutputMode: outputMode,
        photoOriginalRetention: originalRetention,
      }, repository);
      await repositories.organizationPersonnel.insertAudit(
        actor.employeeNumber,
        "loan.photos.add",
        "loan",
        loan.id,
        JSON.stringify({
        phase,
        count: preparedPhotos.length,
        photoAttachmentId: preparedAttachment.id,
        photoAttachmentRevision: attachmentRevision,
        photoPdfOutputMode: outputMode,
        photoOriginalRetention: originalRetention,
        }),
      );
      });
    } catch (error) {
      cleanupPreparedLoanPhotos(preparedPhotos);
      cleanupPreparedLoanPhotoAttachment(preparedAttachment);
      throw error;
    } finally {
      amuMutationInProgress = Math.max(0, amuMutationInProgress - 1);
    }
    await refreshLoanProtectedStorageSnapshot();
    const [storedLoan, storedPhotos, storedAttachments] = await Promise.all([
      loanRow(loan.id),
      loanPhotoRows(loan.id),
      loanPhotoAttachmentRows(loan.id),
    ]);
    response.status(201).json({
      loan: await publicLoan(storedLoan),
      photos: storedPhotos.filter((photo) => photo.phase === phase).map(publicLoanPhoto),
      photoAttachments: storedAttachments
        .filter((attachment) => attachment.phase === phase)
        .map(publicLoanPhotoAttachment),
    });
  } finally {
    releaseLoanPhotoUpload();
  }
});

app.post("/api/portal/v1/loans/documents/:documentId/email", async (request, response) => {
  const actor = requirePortalAnyPermissionOrLocal(
    request,
    ["loans:location:manage", "loans:settings"],
    { csrf: true },
  );
  const document = await loanDocumentRow(request.params.documentId);
  assertLoanDocumentAccess(actor, document);
  const loan = await loanRow(document.loan_id);
  const setting = await loanLocationSettingRow(loan.location_id);
  if (!setting?.document_email_enabled || !setting.document_recipient_email) {
    throw httpError(409, "Für diesen Standort ist kein E-Mail-Empfänger aktiviert.", "LOAN_DOCUMENT_EMAIL_NOT_CONFIGURED");
  }
  const delivery = await deliverConfiguredLoanDocumentEmails(loan, document, {
    attemptedByEmployeeNumber: actor.employeeNumber,
  });
  const failed = delivery.status !== "sent";
  response.status(failed ? 503 : 200).json({
    ...(failed ? {
      error: loanDocumentEmailFailureMessage(delivery.errorCodes),
      code: "LOAN_DOCUMENT_EMAIL_DELIVERY_FAILED",
    } : {}),
    delivery,
    document: publicLoanDocument(await loanDocumentRow(document.id)),
  });
});

app.post("/api/portal/v1/loans", async (request, response) => {
  const actor = requirePortalAnyPermissionOrLocal(
    request,
    ["loans:self:create"],
    { csrf: true },
  );
  const setting = await enabledLoanLocationForSession(actor, request.body || {});
  const borrower = await loanBorrowerForIssue(actor, setting, request.body?.borrowerEmployeeNumber);
  const input = normalizeLoanIssueBody(request.body || {});
  const articles = await articleRowsForLoan(input.items);
  const loanId = crypto.randomUUID();
  const now = new Date().toISOString();
  const recordedByEmployeeNumber = actor.employeeNumber;
  let preparedIssueDocument;
  try {
    preparedIssueDocument = await prepareLoanDocument({
      type: "issue",
      loanId,
      revision: 1,
      createdAt: now,
      issuedAt: now,
      dueDate: input.dueDate,
      note: input.notes,
      location: { id: setting.location_id, name: setting.location_name },
      borrower: {
        employeeNumber: borrower.personnel_number,
        name: borrower.nickname || borrower.full_name,
      },
      recordedBy: await loanParticipant(recordedByEmployeeNumber),
      items: input.items.map((item, index) => ({
        position: item.position,
        articleNumber: item.articleNumber,
        description: articles[index].description,
        serialNumber: item.serialNumber,
        conditionOut: item.conditionOut,
        note: item.note,
      })),
      branding: loanPdfBranding(setting.location_id),
    }, actor.employeeNumber);
  } catch (error) {
    throw httpError(
      503,
      `Der Ausgabebeleg konnte nicht sicher erstellt werden: ${String(error.message || error)}`,
      "LOAN_DOCUMENT_CREATE_FAILED",
    );
  }
  try {
    await persistenceProvider.transaction(async (executor) => {
      const repository = createApplicationRepositories(executor).loanModule;
      await repository.insertLoan({
        id: loanId,
        locationId: setting.location_id,
        borrowerEmployeeNumber: borrower.personnel_number,
        createdByEmployeeNumber: recordedByEmployeeNumber,
        dueDate: input.dueDate,
        notes: input.notes,
        issuedAt: now,
      });
      for (const [index, item] of input.items.entries()) {
        await repository.insertLoanItem({
          id: crypto.randomUUID(),
          loanId,
          position: item.position,
          productId: articles[index].product_id,
          productRevisionSnapshot: articles[index].current_revision,
          articleNumber: item.articleNumber,
          descriptionSnapshot: String(articles[index].description).slice(0, 300),
          serialNumber: item.serialNumber,
          conditionOut: item.conditionOut,
          conditionReturn: "",
          itemNote: item.note,
          createdAt: now,
          updatedAt: now,
        });
      }
      await appendLoanEvent(loanId, actor.employeeNumber, "issued", 1, {
        dueDate: input.dueDate,
        itemCount: input.items.length,
        borrowerEmployeeNumber: borrower.personnel_number,
      }, repository);
      await insertPreparedLoanDocument(loanId, preparedIssueDocument, repository);
      await appendLoanEvent(loanId, actor.employeeNumber, "document_created", 1, {
        documentId: preparedIssueDocument.id,
        documentType: preparedIssueDocument.documentType,
        sha256: preparedIssueDocument.sha256,
      }, repository);
    });
  } catch (error) {
    cleanupPreparedLoanDocument(preparedIssueDocument);
    throw error;
  }
  (await auditPortal(actor.employeeNumber, "loan.issue", "loan", loanId, JSON.stringify({
    locationId: setting.location_id,
    borrowerEmployeeNumber: borrower.personnel_number,
    itemCount: input.items.length,
  })));
  if (borrower.personnel_number !== actor.employeeNumber) {
    await createPortalNotification(
      borrower.personnel_number,
      "loan.issued",
      "Leihe erfasst",
      `${input.items.length} ${input.items.length === 1 ? "Artikel wurde" : "Artikel wurden"} auf deinen Zugang ausgegeben.`,
      {
        target: `/portal.html?tab=loan&loan=${encodeURIComponent(loanId)}`,
        entityType: "loan",
        entityId: loanId,
        dedupeKey: `loan:${loanId}:issued`,
      },
    );
  }
  await refreshLoanProtectedStorageSnapshot();
  const [issuedLoan, issueDocument] = await Promise.all([
    loanRow(loanId),
    loanDocumentRow(preparedIssueDocument.id),
  ]);
  await notifyLoanDocumentAvailable(issuedLoan, issueDocument);
  response.status(201).json({ loan: await publicLoan(issuedLoan) });
});

app.put("/api/portal/v1/loans/:loanId/management", async (request, response) => {
  const actor = requirePortalAnyPermissionOrLocal(
    request,
    ["loans:location:manage"],
    { csrf: true },
  );
  const row = await loanRow(request.params.loanId);
  assertLoanManagementAccess(actor, row);
  const expectedRevision = loanExpectedRevision(request.body);
  if (Number(row.revision) !== expectedRevision) {
    throw httpError(409, "Der Leihvorgang wurde inzwischen geändert. Bitte neu laden.", "LOAN_STALE");
  }
  const input = await normalizeLoanManagementBody(request.body, row, {
    requireReturnCondition: row.status === "returned",
  });
  const now = new Date().toISOString();
  const nextRevision = expectedRevision + 1;
  let cancelledConfirmationId = null;
  await persistenceProvider.transaction(async (executor) => {
    const repository = createApplicationRepositories(executor).loanModule;
    const result = await repository.updateManagedLoan({
      loanId: row.id,
      dueDate: input.dueDate,
      notes: input.notes,
      updatedAt: now,
      status: row.status,
      expectedRevision,
    });
    if (!result.rowsAffected) {
      throw httpError(409, "Der Leihvorgang wurde inzwischen geändert. Bitte neu laden.", "LOAN_STALE");
    }
    for (const item of input.items) {
      await repository.updateManagedLoanItem({
        loanId: row.id,
        position: item.position,
        serialNumber: item.serialNumber,
        conditionOut: item.conditionOut,
        conditionReturn: item.conditionReturn,
        itemNote: item.note,
        updatedAt: now,
      });
    }
    cancelledConfirmationId = await cancelPendingLoanReturnConfirmation(
      row.id,
      now,
      "Durch Bearbeitung der Filialleitung aufgehoben.",
      repository,
    );
    await repository.deleteReturnPreparation({ loanId: row.id });
    await appendLoanEvent(row.id, actor.employeeNumber, "manager_edited", nextRevision, {
      previousRevision: expectedRevision,
      status: row.status,
      dueDate: input.dueDate,
      notes: input.notes,
      items: input.items,
      cancelledConfirmationId,
    }, repository);
  });
  (await auditPortal(actor.employeeNumber, "loan.management.edit", "loan", row.id, JSON.stringify({
    locationId: row.location_id,
    borrowerEmployeeNumber: row.borrower_employee_number,
    previousRevision: expectedRevision,
    revision: nextRevision,
    itemCount: input.items.length,
    cancelledConfirmationId,
  })));
  response.json({ loan: await publicLoan(await loanRow(row.id)) });
});

app.post("/api/portal/v1/loans/:loanId/management/close", async (request, response) => {
  const actor = requirePortalAnyPermissionOrLocal(
    request,
    ["loans:location:manage"],
    { csrf: true },
  );
  if (isLocalSystemSession(actor)) {
    throw httpError(
      409,
      "Das manuelle Schließen benötigt einen persönlich angemeldeten Leitungszugang.",
      "LOAN_MANAGEMENT_PORTAL_LOGIN_REQUIRED",
    );
  }
  const row = await loanRow(request.params.loanId);
  assertLoanManagementAccess(actor, row);
  const expectedRevision = loanExpectedRevision(request.body);
  if (row.status !== "issued") {
    throw httpError(409, "Nur eine offene Leihe kann manuell geschlossen werden.", "LOAN_ALREADY_CLOSED");
  }
  if (Number(row.revision) !== expectedRevision) {
    throw httpError(409, "Der Leihvorgang wurde inzwischen geändert. Bitte neu laden.", "LOAN_STALE");
  }
  const input = await normalizeLoanManagementBody(request.body, row, { requireReturnCondition: true });
  const now = new Date().toISOString();
  const nextRevision = expectedRevision + 1;
  let cancelledConfirmationId = null;
  await persistenceProvider.transaction(async (executor) => {
    const repository = createApplicationRepositories(executor).loanModule;
    const result = await repository.closeManagedLoan({
      loanId: row.id,
      dueDate: input.dueDate,
      notes: input.notes,
      returnedAt: now,
      actorEmployeeNumber: actor.employeeNumber,
      expectedRevision,
    });
    if (!result.rowsAffected) {
      throw httpError(409, "Der Leihvorgang wurde inzwischen geändert. Bitte neu laden.", "LOAN_STALE");
    }
    for (const item of input.items) {
      await repository.updateManagedLoanItem({
        loanId: row.id,
        position: item.position,
        serialNumber: item.serialNumber,
        conditionOut: item.conditionOut,
        conditionReturn: item.conditionReturn,
        itemNote: item.note,
        updatedAt: now,
      });
    }
    cancelledConfirmationId = await cancelPendingLoanReturnConfirmation(
      row.id,
      now,
      "Durch manuelles Schließen der Filialleitung aufgehoben.",
      repository,
    );
    await repository.deleteReturnPreparation({ loanId: row.id });
    await appendLoanEvent(row.id, actor.employeeNumber, "manager_closed_without_document", nextRevision, {
      previousRevision: expectedRevision,
      returnRecordedByEmployeeNumber: actor.employeeNumber,
      borrowerConfirmed: false,
      witnessEmployeeNumber: "",
      documentCreated: false,
      dueDate: input.dueDate,
      notes: input.notes,
      items: input.items,
      cancelledConfirmationId,
    }, repository);
  });
  (await auditPortal(actor.employeeNumber, "loan.management.close_without_document", "loan", row.id, JSON.stringify({
    locationId: row.location_id,
    borrowerEmployeeNumber: row.borrower_employee_number,
    previousRevision: expectedRevision,
    revision: nextRevision,
    itemCount: input.items.length,
    cancelledConfirmationId,
  })));
  if (row.borrower_employee_number !== actor.employeeNumber) {
    await createPortalNotification(
      row.borrower_employee_number,
      "loan.returned",
      "Leihe durch Filialleitung geschlossen",
      `Die Leihe wurde von ${actor.employeeNumber} ohne Gegenbestätigung und ohne neuen Rücknahmebeleg geschlossen.`,
      {
        target: `/portal.html?tab=loan&loan=${encodeURIComponent(row.id)}`,
        entityType: "loan",
        entityId: row.id,
        dedupeKey: `loan:${row.id}:manager-closed:${nextRevision}`,
      },
    );
  }
  response.json({ loan: await publicLoan(await loanRow(row.id)) });
});

app.post("/api/portal/v1/loans/:loanId/management/reopen", async (request, response) => {
  const actor = requirePortalAnyPermissionOrLocal(
    request,
    ["loans:location:manage"],
    { csrf: true },
  );
  const row = await loanRow(request.params.loanId);
  assertLoanManagementAccess(actor, row);
  const expectedRevision = loanExpectedRevision(request.body);
  if (!["returned", "cancelled"].includes(row.status)) {
    throw httpError(409, "Nur eine geschlossene Leihe kann wieder geöffnet werden.", "LOAN_NOT_CLOSED");
  }
  if (Number(row.revision) !== expectedRevision) {
    throw httpError(409, "Der Leihvorgang wurde inzwischen geändert. Bitte neu laden.", "LOAN_STALE");
  }
  const now = new Date().toISOString();
  const nextRevision = expectedRevision + 1;
  const [storedItems, storedDocuments] = await Promise.all([
    loanItemRows(row.id),
    loanDocumentRows(row.id),
  ]);
  const previousItems = storedItems.map((item) => ({
    position: Number(item.position),
    conditionReturn: item.condition_return || "",
  }));
  const previousDocuments = storedDocuments.map((document) => ({
    id: document.id,
    type: document.document_type,
    revision: Number(document.loan_revision),
    sha256: document.sha256,
  }));
  await persistenceProvider.transaction(async (executor) => {
    const repository = createApplicationRepositories(executor).loanModule;
    const result = await repository.reopenManagedLoan({
      loanId: row.id,
      updatedAt: now,
      expectedRevision,
    });
    if (!result.rowsAffected) {
      throw httpError(409, "Der Leihvorgang wurde inzwischen geändert. Bitte neu laden.", "LOAN_STALE");
    }
    await repository.clearLoanItemReturnConditions({
      loanId: row.id,
      updatedAt: now,
    });
    await appendLoanEvent(row.id, actor.employeeNumber, "manager_reopened", nextRevision, {
      previousRevision: expectedRevision,
      previousStatus: row.status,
      previousReturnedAt: row.returned_at || null,
      previousReturnRecordedByEmployeeNumber: row.return_recorded_by_employee_number || "",
      previousWitnessEmployeeNumber: row.return_witness_employee_number || "",
      previousBorrowerConfirmed: Boolean(row.borrower_return_confirmed),
      previousItems,
      preservedDocuments: previousDocuments,
    }, repository);
  });
  (await auditPortal(actor.employeeNumber, "loan.management.reopen", "loan", row.id, JSON.stringify({
    locationId: row.location_id,
    borrowerEmployeeNumber: row.borrower_employee_number,
    previousRevision: expectedRevision,
    revision: nextRevision,
    previousStatus: row.status,
    preservedDocumentCount: previousDocuments.length,
  })));
  if (row.borrower_employee_number !== actor.employeeNumber) {
    await createPortalNotification(
      row.borrower_employee_number,
      "loan.reopened",
      "Leihe wieder geöffnet",
      `Die Filialleitung hat eine geschlossene Leihe wieder geöffnet. Sie erscheint erneut unter den offenen Leihen.`,
      {
        target: `/portal.html?tab=loan&loan=${encodeURIComponent(row.id)}`,
        entityType: "loan",
        entityId: row.id,
        dedupeKey: `loan:${row.id}:manager-reopened:${nextRevision}`,
      },
    );
  }
  response.json({ loan: await publicLoan(await loanRow(row.id)) });
});

