async function completePreparedLoanReturn({
  loan,
  expectedRevision,
  returnedItems,
  note = "",
  borrowerConfirmed = false,
  recordedByEmployeeNumber,
  witnessEmployeeNumber = "",
  completionActor,
  confirmationId = "",
  confirmationNote = "",
  directManagement = false,
}) {
  const completedAt = new Date().toISOString();
  const nextRevision = Number(expectedRevision) + 1;
  const sourceItems = await loanItemRows(loan.id);
  const [recordedByParticipant, completionParticipant] = await Promise.all([
    loanParticipant(recordedByEmployeeNumber),
    loanParticipant(completionActor.employeeNumber),
  ]);
  let preparedReturnDocument;
  try {
    preparedReturnDocument = await prepareLoanDocument({
      type: "return",
      confirmationMode: directManagement ? "management" : "witness",
      loanId: loan.id,
      revision: nextRevision,
      createdAt: completedAt,
      issuedAt: loan.issued_at,
      returnedAt: completedAt,
      dueDate: loan.due_date,
      note: [loan.notes, note].filter(Boolean).join(" · "),
      confirmationNote,
      location: { id: loan.location_id, name: loan.location_name },
      borrower: {
        employeeNumber: loan.borrower_employee_number,
        name: loan.borrower_nickname || loan.borrower_full_name,
      },
      recordedBy: recordedByParticipant,
      witness: completionParticipant,
      items: sourceItems.map((item) => {
        const returned = returnedItems.find((entry) => Number(entry.position) === Number(item.position)) || {};
        return {
          position: item.position,
          articleNumber: item.article_number,
          description: item.description_snapshot,
          serialNumber: item.serial_number,
          conditionOut: item.condition_out,
          conditionReturn: returned.conditionReturn,
          note: [item.item_note, returned.note].filter(Boolean).join(" · "),
        };
      }),
      branding: loanPdfBranding(loan.location_id),
    }, completionActor.employeeNumber);
  } catch (error) {
    throw httpError(
      503,
      `Der Rücknahmebeleg konnte nicht sicher erstellt werden: ${String(error.message || error)}`,
      "LOAN_DOCUMENT_CREATE_FAILED",
    );
  }
  try {
    await persistenceProvider.transaction(async (executor) => {
      const repository = createApplicationRepositories(executor).loanModule;
      const result = await repository.markLoanReturned({
        loanId: loan.id,
        returnedAt: completedAt,
        recordedByEmployeeNumber,
        witnessEmployeeNumber: witnessEmployeeNumber || null,
        borrowerReturnConfirmed: Boolean(borrowerConfirmed),
        expectedRevision,
      });
      if (!result.rowsAffected) {
        throw httpError(409, "Der Leihvorgang wurde inzwischen geändert. Bitte neu laden.", "LOAN_STALE");
      }
      for (const item of returnedItems) {
        await repository.updateLoanItemReturnCondition({
          loanId: loan.id,
          position: item.position,
          conditionReturn: item.conditionReturn,
          updatedAt: completedAt,
        });
      }
      if (confirmationId) {
        const confirmationResult = await repository.confirmReturnConfirmation({
          confirmationId,
          respondedAt: completedAt,
          responseNote: confirmationNote,
        });
        if (!confirmationResult.rowsAffected) {
          throw httpError(409, "Diese Rücknahmebestätigung wurde bereits bearbeitet.", "LOAN_RETURN_CONFIRMATION_CLOSED");
        }
      }
      await repository.deleteReturnPreparation({ loanId: loan.id });
      await insertPreparedLoanDocument(loan.id, preparedReturnDocument, repository);
      await appendLoanEvent(loan.id, completionActor.employeeNumber, "returned", nextRevision, {
        confirmationId: confirmationId || null,
        completionMode: directManagement ? "management" : "second_employee",
        requestedByEmployeeNumber: recordedByEmployeeNumber,
        witnessEmployeeNumber: witnessEmployeeNumber || null,
        borrowerConfirmed: Boolean(borrowerConfirmed),
        note,
        responseNote: confirmationNote,
        items: returnedItems,
      }, repository);
      await appendLoanEvent(loan.id, completionActor.employeeNumber, "document_created", nextRevision, {
        documentId: preparedReturnDocument.id,
        documentType: preparedReturnDocument.documentType,
        sha256: preparedReturnDocument.sha256,
      }, repository);
    });
  } catch (error) {
    cleanupPreparedLoanDocument(preparedReturnDocument);
    throw error;
  }
  await refreshLoanProtectedStorageSnapshot();
  const [returnedLoan, returnedDocument] = await Promise.all([
    loanRow(loan.id),
    loanDocumentRow(preparedReturnDocument.id),
  ]);
  const messageText = directManagement
    ? `Die Rücknahme wurde von ${completionActor.employeeNumber} als zuständige Leitung abgeschlossen.`
    : `Die Rücknahme wurde von ${completionActor.employeeNumber} gegengeprüft und abgeschlossen.`;
  for (const recipient of new Set([recordedByEmployeeNumber, loan.borrower_employee_number])) {
    if (!recipient || recipient === completionActor.employeeNumber) continue;
    await createPortalNotification(
      recipient,
      "loan.returned",
      "Leihe zurückgenommen",
      messageText,
      {
        target: `/portal.html?tab=loan&loan=${encodeURIComponent(loan.id)}`,
        entityType: "loan",
        entityId: loan.id,
        dedupeKey: `loan:${loan.id}:returned:${nextRevision}:${recipient}`,
      },
    );
  }
  await notifyLoanDocumentAvailable(returnedLoan, returnedDocument);
  return { returnedLoan, returnedDocument, nextRevision, completedAt };
}

app.post("/api/portal/v1/loans/:loanId/return", async (request, response) => {
  const actor = requirePortalAnyPermissionOrLocal(
    request,
    ["loans:self:return", "loans:location:manage"],
    { csrf: true },
  );
  if (isLocalSystemSession(actor)) {
    throw httpError(
      409,
      "Die Live-Bestätigung benötigt einen persönlich angemeldeten Portalzugang.",
      "LOAN_RETURN_PORTAL_LOGIN_REQUIRED",
    );
  }
  const row = await loanRow(request.params.loanId);
  if (!row) throw httpError(404, "Der Leihvorgang wurde nicht gefunden.", "LOAN_NOT_FOUND");
  const managesLocation = loanCanManageLocation(actor);
  if (row.borrower_employee_number !== actor.employeeNumber && !managesLocation) {
    throw httpError(403, "Nur die ausleihende Person kann diese Rücknahme erfassen.", "LOAN_RETURN_DENIED");
  }
  if (managesLocation) assertSessionContextScope(actor, { locationId: row.location_id });
  const expectedRevision = Number(request.body?.expectedRevision);
  if (!Number.isInteger(expectedRevision) || expectedRevision < 1) {
    throw httpError(400, "Die erwartete Revision fehlt.", "LOAN_VERSION_REQUIRED");
  }
  if (row.status !== "issued") {
    throw httpError(409, "Dieser Leihvorgang ist nicht mehr offen.", "LOAN_ALREADY_CLOSED");
  }
  if (Number(row.revision) !== expectedRevision) {
    throw httpError(409, "Der Leihvorgang wurde inzwischen geändert. Bitte neu laden.", "LOAN_STALE");
  }
  const witnessEmployeeNumber = String(request.body?.witnessEmployeeNumber || "").trim();
  const witness = witnessEmployeeNumber
    ? await loanEmployeeRow(witnessEmployeeNumber, { active: true })
    : null;
  if (witnessEmployeeNumber && (!witness
    || String(witness.home_location_id || "") !== String(row.location_id)
    || witness.personnel_number === row.borrower_employee_number
    || witness.personnel_number === actor.employeeNumber)) {
    throw httpError(
      400,
      "Bitte ein anderes aktives Teammitglied dieses Standorts als Rücknahmebestätigung auswählen.",
      "LOAN_RETURN_WITNESS_INVALID",
    );
  }
  let returnedItems;
  try {
    returnedItems = normalizeLoanReturnItems(request.body?.items, await loanItemRows(row.id));
  } catch (error) {
    throw loanWorkflowHttpError(error);
  }
  const note = normalizeLoanNotes(request.body?.note, 1000);
  await expireLoanReturnConfirmations();
  if (await loanPendingReturnConfirmationRow(row.id)) {
    throw httpError(
      409,
      "Für diese Leihe wartet bereits eine Rücknahme auf Bestätigung.",
      "LOAN_RETURN_CONFIRMATION_PENDING",
    );
  }
  const existingPreparation = await loanReturnPreparationRow(row.id);
  if (existingPreparation
    && existingPreparation.requested_by_employee_number !== actor.employeeNumber
    && !managesLocation) {
    throw httpError(
      409,
      "Diese Rücknahme wurde bereits von einer anderen zuständigen Person vorbereitet.",
      "LOAN_RETURN_PREPARATION_OWNED",
    );
  }
  const requestedAt = new Date().toISOString();
  const borrowerConfirmed = actor.employeeNumber === row.borrower_employee_number;
  let photoIds = [];
  let photoAttachmentIds = [];
  const payload = {
    items: returnedItems,
    note,
    borrowerConfirmed,
    photoIds,
    photoAttachmentIds,
  };

  if (managesLocation && !witness) {
    photoIds = (await loanPhotoRows(row.id))
      .filter((photo) => photo.phase === "return")
      .map((photo) => photo.id);
    photoAttachmentIds = (await loanPhotoAttachmentRows(row.id))
      .filter((attachment) => attachment.phase === "return")
      .map((attachment) => attachment.id);
    payload.photoIds = photoIds;
    payload.photoAttachmentIds = photoAttachmentIds;
    const completed = await completePreparedLoanReturn({
      loan: row,
      expectedRevision,
      returnedItems,
      note,
      borrowerConfirmed,
      recordedByEmployeeNumber: actor.employeeNumber,
      completionActor: actor,
      directManagement: true,
    });
    (await auditPortal(actor.employeeNumber, "loan.return.management-complete", "loan", row.id, JSON.stringify({
      locationId: row.location_id,
      borrowerEmployeeNumber: row.borrower_employee_number,
      itemCount: returnedItems.length,
      photoCount: photoIds.length,
      photoAttachmentCount: photoAttachmentIds.length,
      noteProvided: Boolean(note),
    })));
    response.json({
      direct: true,
      loan: await publicLoan(completed.returnedLoan),
    });
    return;
  }

  const confirmationId = witness ? crypto.randomUUID() : "";
  const expiresAt = witness ? viennaEndOfDayIso() : null;
  await persistenceProvider.transaction(async (executor) => {
    const repository = createApplicationRepositories(executor).loanModule;
    const current = await repository.getLoan({ loanId: row.id });
    if (current?.status !== "issued" || Number(current?.revision) !== expectedRevision) {
      throw httpError(409, "Der Leihvorgang wurde inzwischen geändert. Bitte neu laden.", "LOAN_STALE");
    }
    photoIds = (await repository.listLoanPhotos({ loanId: row.id }))
      .filter((photo) => photo.phase === "return")
      .map((photo) => photo.id);
    photoAttachmentIds = (await repository.listLoanPhotoAttachments({ loanId: row.id }))
      .filter((attachment) => attachment.phase === "return")
      .map((attachment) => attachment.id);
    payload.photoIds = photoIds;
    payload.photoAttachmentIds = photoAttachmentIds;
    const currentPreparation = await repository.getReturnPreparation({ loanId: row.id });
    if (currentPreparation
      && currentPreparation.requested_by_employee_number !== actor.employeeNumber
      && !managesLocation) {
      throw httpError(
        409,
        "Diese Rücknahme wurde bereits von einer anderen zuständigen Person vorbereitet.",
        "LOAN_RETURN_PREPARATION_OWNED",
      );
    }
    await repository.upsertReturnPreparation({
      loanId: row.id,
      requestedByEmployeeNumber: actor.employeeNumber,
      expectedRevision,
      payloadJson: JSON.stringify(payload),
      preparedAt: currentPreparation?.prepared_at || requestedAt,
      updatedAt: requestedAt,
    });
    await appendLoanEvent(row.id, actor.employeeNumber, "return_prepared", expectedRevision, {
      confirmationRequested: Boolean(witness),
      photoIds,
      photoAttachmentIds,
    }, repository);
    if (witness) {
      await repository.insertReturnConfirmation({
        id: confirmationId,
        loanId: row.id,
        requestedByEmployeeNumber: actor.employeeNumber,
        witnessEmployeeNumber: witness.personnel_number,
        expectedRevision,
        payloadJson: JSON.stringify(payload),
        requestedAt,
        expiresAt,
      });
      await appendLoanEvent(row.id, actor.employeeNumber, "return_confirmation_requested", expectedRevision, {
        confirmationId,
        witnessEmployeeNumber: witness.personnel_number,
        expiresAt,
        photoIds,
        photoAttachmentIds,
      }, repository);
    }
  });
  (await auditPortal(actor.employeeNumber, witness ? "loan.return.request" : "loan.return.prepare", "loan", row.id, JSON.stringify({
    locationId: row.location_id,
    borrowerEmployeeNumber: row.borrower_employee_number,
    witnessEmployeeNumber: witness?.personnel_number || null,
    itemCount: returnedItems.length,
    photoCount: photoIds.length,
    photoAttachmentCount: photoAttachmentIds.length,
    noteProvided: Boolean(note),
  })));
  if (witness) {
    await createPortalNotification(
      witness.personnel_number,
      "loan.return_confirmation",
      "Rücknahme bestätigen",
      `${actor.nickname || actor.fullName || actor.employeeNumber} bittet um deine Gegenbestätigung bis heute 23:59 Uhr.`,
      {
        target: `/portal.html?tab=loan&confirmation=${encodeURIComponent(confirmationId)}`,
        entityType: "loan_return_confirmation",
        entityId: confirmationId,
        dedupeKey: `loan-return-confirmation:${confirmationId}`,
      },
    );
  }
  response.status(202).json({
    loan: await publicLoan(await loanRow(row.id)),
    prepared: true,
    preparation: await publicLoanReturnPreparation(await loanReturnPreparationRow(row.id)),
    confirmation: confirmationId
      ? await publicLoanReturnConfirmation(await loanReturnConfirmationRow(confirmationId))
      : null,
  });
});

app.post("/api/portal/v1/loans/return-confirmations/:confirmationId/respond", async (request, response) => {
  const actor = requirePortalAnyPermissionOrLocal(
    request,
    ["loans:self:read", "loans:self:return", "loans:location:manage"],
    { csrf: true },
  );
  if (isLocalSystemSession(actor)) {
    throw httpError(
      409,
      "Die Live-Bestätigung benötigt einen persönlich angemeldeten Portalzugang.",
      "LOAN_RETURN_PORTAL_LOGIN_REQUIRED",
    );
  }
  await expireLoanReturnConfirmations();
  const confirmation = await loanReturnConfirmationRow(request.params.confirmationId);
  if (!confirmation) {
    throw httpError(404, "Die Rücknahmebestätigung wurde nicht gefunden.", "LOAN_RETURN_CONFIRMATION_NOT_FOUND");
  }
  if (confirmation.witness_employee_number !== actor.employeeNumber) {
    throw httpError(
      403,
      "Nur das ausgewählte zweite Teammitglied darf diese Rücknahme bestätigen.",
      "LOAN_RETURN_CONFIRMATION_DENIED",
    );
  }
  if (confirmation.status !== "pending") {
    throw httpError(
      409,
      confirmation.status === "expired"
        ? "Diese Rücknahmebestätigung ist abgelaufen. Bitte neu anfordern."
        : "Diese Rücknahmebestätigung wurde bereits bearbeitet.",
      confirmation.status === "expired"
        ? "LOAN_RETURN_CONFIRMATION_EXPIRED"
        : "LOAN_RETURN_CONFIRMATION_CLOSED",
    );
  }
  const decision = String(request.body?.decision || "").trim();
  if (!["confirm", "reject"].includes(decision)) {
    throw httpError(400, "Bitte die Rücknahme bestätigen oder ablehnen.", "LOAN_RETURN_DECISION_INVALID");
  }
  const responseNote = normalizeLoanNotes(request.body?.note, 500);
  const respondedAt = new Date().toISOString();
  const loan = await loanRow(confirmation.loan_id);
  if (!loan || loan.status !== "issued") {
    throw httpError(409, "Der Leihvorgang ist nicht mehr offen.", "LOAN_ALREADY_CLOSED");
  }
  if (Number(loan.revision) !== Number(confirmation.expected_revision)) {
    throw httpError(409, "Der Leihvorgang wurde inzwischen geändert. Bitte neu laden.", "LOAN_STALE");
  }
  const payload = parseLoanReturnConfirmationPayload(confirmation);

  if (decision === "reject") {
    await persistenceProvider.transaction(async (executor) => {
      const repository = createApplicationRepositories(executor).loanModule;
      const result = await repository.rejectReturnConfirmation({
        confirmationId: confirmation.id,
        respondedAt,
        responseNote,
      });
      if (!result.rowsAffected) {
        throw httpError(409, "Diese Rücknahmebestätigung wurde bereits bearbeitet.", "LOAN_RETURN_CONFIRMATION_CLOSED");
      }
      await appendLoanEvent(loan.id, actor.employeeNumber, "return_confirmation_rejected", loan.revision, {
        confirmationId: confirmation.id,
        requestedByEmployeeNumber: confirmation.requested_by_employee_number,
        note: responseNote,
      }, repository);
    });
    (await auditPortal(actor.employeeNumber, "loan.return.reject", "loan", loan.id, JSON.stringify({
      confirmationId: confirmation.id,
      requestedByEmployeeNumber: confirmation.requested_by_employee_number,
      noteProvided: Boolean(responseNote),
    })));
    await createPortalNotification(
      confirmation.requested_by_employee_number,
      "loan.return_rejected",
      "Rücknahme nicht bestätigt",
      `${actor.nickname || actor.fullName || actor.employeeNumber} hat die Gegenbestätigung abgelehnt.`,
      {
        target: `/portal.html?tab=loan&loan=${encodeURIComponent(loan.id)}`,
        entityType: "loan",
        entityId: loan.id,
        dedupeKey: `loan:${loan.id}:return-rejected:${confirmation.id}`,
      },
    );
    await loanModuleRepository.markRecipientConfirmationNotificationRead({
      employeeNumber: actor.employeeNumber,
      confirmationId: confirmation.id,
    });
    response.json({
      confirmation: await publicLoanReturnConfirmation(
        await loanReturnConfirmationRow(confirmation.id),
      ),
      loan: await publicLoan(await loanRow(loan.id)),
    });
    return;
  }

  const sourceItems = await loanItemRows(loan.id);
  let returnedItems;
  try {
    returnedItems = normalizeLoanReturnItems(payload.items, sourceItems);
  } catch (error) {
    throw loanWorkflowHttpError(error);
  }
  const nextRevision = Number(loan.revision) + 1;
  const [recordedByParticipant, witnessParticipant] = await Promise.all([
    loanParticipant(confirmation.requested_by_employee_number),
    loanParticipant(actor.employeeNumber),
  ]);
  let preparedReturnDocument;
  try {
    preparedReturnDocument = await prepareLoanDocument({
      type: "return",
      loanId: loan.id,
      revision: nextRevision,
      createdAt: respondedAt,
      issuedAt: loan.issued_at,
      returnedAt: respondedAt,
      dueDate: loan.due_date,
      note: [loan.notes, payload.note].filter(Boolean).join(" · "),
      confirmationNote: responseNote,
      location: { id: loan.location_id, name: loan.location_name },
      borrower: {
        employeeNumber: loan.borrower_employee_number,
        name: loan.borrower_nickname || loan.borrower_full_name,
      },
      recordedBy: recordedByParticipant,
      witness: witnessParticipant,
      items: sourceItems.map((item) => {
        const returned = returnedItems.find((entry) => Number(entry.position) === Number(item.position)) || {};
        return {
          position: item.position,
          articleNumber: item.article_number,
          description: item.description_snapshot,
          serialNumber: item.serial_number,
          conditionOut: item.condition_out,
          conditionReturn: returned.conditionReturn,
          note: [item.item_note, returned.note].filter(Boolean).join(" · "),
        };
      }),
      branding: loanPdfBranding(loan.location_id),
    }, actor.employeeNumber);
  } catch (error) {
    throw httpError(
      503,
      `Der Rücknahmebeleg konnte nicht sicher erstellt werden: ${String(error.message || error)}`,
      "LOAN_DOCUMENT_CREATE_FAILED",
    );
  }
  try {
    await persistenceProvider.transaction(async (executor) => {
      const repository = createApplicationRepositories(executor).loanModule;
      const result = await repository.markLoanReturned({
        loanId: loan.id,
        returnedAt: respondedAt,
        recordedByEmployeeNumber: confirmation.requested_by_employee_number,
        witnessEmployeeNumber: actor.employeeNumber,
        borrowerReturnConfirmed: Boolean(payload.borrowerConfirmed),
        expectedRevision: confirmation.expected_revision,
      });
    if (!result.rowsAffected) {
      throw httpError(409, "Der Leihvorgang wurde inzwischen geändert. Bitte neu laden.", "LOAN_STALE");
    }
    for (const item of returnedItems) {
      await repository.updateLoanItemReturnCondition({
        loanId: loan.id,
        position: item.position,
        conditionReturn: item.conditionReturn,
        updatedAt: respondedAt,
      });
    }
    const confirmationResult = await repository.confirmReturnConfirmation({
      confirmationId: confirmation.id,
      respondedAt,
      responseNote,
    });
    if (!confirmationResult.rowsAffected) {
      throw httpError(409, "Diese Rücknahmebestätigung wurde bereits bearbeitet.", "LOAN_RETURN_CONFIRMATION_CLOSED");
    }
    await repository.deleteReturnPreparation({ loanId: loan.id });
    await insertPreparedLoanDocument(loan.id, preparedReturnDocument, repository);
    await appendLoanEvent(loan.id, actor.employeeNumber, "returned", nextRevision, {
      confirmationId: confirmation.id,
      requestedByEmployeeNumber: confirmation.requested_by_employee_number,
      witnessEmployeeNumber: actor.employeeNumber,
      borrowerConfirmed: Boolean(payload.borrowerConfirmed),
      note: String(payload.note || ""),
      responseNote,
      items: returnedItems,
    }, repository);
    await appendLoanEvent(loan.id, actor.employeeNumber, "document_created", nextRevision, {
      documentId: preparedReturnDocument.id,
      documentType: preparedReturnDocument.documentType,
      sha256: preparedReturnDocument.sha256,
    }, repository);
    });
  } catch (error) {
    cleanupPreparedLoanDocument(preparedReturnDocument);
    throw error;
  }
  (await auditPortal(actor.employeeNumber, "loan.return.confirm", "loan", loan.id, JSON.stringify({
    confirmationId: confirmation.id,
    requestedByEmployeeNumber: confirmation.requested_by_employee_number,
    borrowerEmployeeNumber: loan.borrower_employee_number,
    itemCount: returnedItems.length,
  })));
  await loanModuleRepository.markRecipientConfirmationNotificationRead({
    employeeNumber: actor.employeeNumber,
    confirmationId: confirmation.id,
  });
  for (const recipient of new Set([
    confirmation.requested_by_employee_number,
    loan.borrower_employee_number,
  ])) {
    if (!recipient || recipient === actor.employeeNumber) continue;
    await createPortalNotification(
      recipient,
      "loan.returned",
      "Leihe zurückgenommen",
      `Die Rücknahme wurde von ${actor.employeeNumber} gegengeprüft und abgeschlossen.`,
      {
        target: `/portal.html?tab=loan&loan=${encodeURIComponent(loan.id)}`,
        entityType: "loan",
        entityId: loan.id,
        dedupeKey: `loan:${loan.id}:returned:${nextRevision}:${recipient}`,
      },
    );
  }
  await refreshLoanProtectedStorageSnapshot();
  const [returnedLoan, returnedDocument] = await Promise.all([
    loanRow(loan.id),
    loanDocumentRow(preparedReturnDocument.id),
  ]);
  await notifyLoanDocumentAvailable(returnedLoan, returnedDocument);
  response.json({
    confirmation: await publicLoanReturnConfirmation(
      await loanReturnConfirmationRow(confirmation.id),
    ),
    loan: await publicLoan(returnedLoan),
  });
});

const PERSONAL_ACTION_PUBLIC_RECEIPT_PREFIX = "receipt:";
const PERSONAL_ACTION_CURSOR_VERSION = 1;
const PERSONAL_ACTION_LIST_DEFAULT_LIMIT = 25;
const PERSONAL_ACTION_LIST_MAX_LIMIT = 50;
const PERSONAL_ACTION_LEGACY_FETCH_LIMIT = 100;
const PERSONAL_ACTION_LEGACY_SCAN_MAX_ROWS = 1000;
const PERSONAL_ACTION_UNDO_WINDOW_MS = 30 * 60 * 1000;

const PERSONAL_ACTION_EXACT_LABELS = Object.freeze({
  "branding.preference.update": "Branding-Einstellung geändert",
  "crm.customer.create": "Kundenkartei angelegt",
  "crm.customer.update": "Kundenkartei aktualisiert",
  "crm.customer.photo.replace": "Kundenfoto aktualisiert",
  "crm.customer.photo.delete": "Kundenfoto entfernt",
  "personnel-lifecycle.team-evaluation.assign": "Bewerbungsbewertung zugewiesen",
  "personnel-lifecycle.team-evaluation.submit": "Bewerbungsbewertung abgegeben",
  "personnel-lifecycle.team-evaluation.pdf": "Bewerbungsbewertung als PDF exportiert",
  "sales.analytics.preferences.update": "Verkaufsanalyse-Einstellungen geändert",
  "sales.report.charts.export": "Verkaufsanalyse als PDF exportiert",
  "sales.article-catalog.create": "Artikel angelegt",
  "sales.article-catalog.update": "Artikel bearbeitet",
  "sales.article-catalog.copy": "Artikel kopiert",
  "sales.article-catalog.archive": "Artikel archiviert",
  "sales.article-catalog.import": "TradeFoto-Artikelimport übernommen",
  "sales.article-catalog.import.undo": "TradeFoto-Artikelimport rückgängig gemacht",
  "sales.article-catalog.undo": "Artikeländerung rückgängig gemacht",
  "schedule.manual-lock.lock": "Dienstplan gesperrt",
  "schedule.manual-lock.unlock": "Dienstplansperre aufgehoben",
  "schedule.past-week-preference.update": "Persönliche Dienstplanoption geändert",
  "personal.action.undo": "Sperrstatus wiederhergestellt",
});

const PERSONAL_ACTION_VISIBLE_SUFFIXES = Object.freeze(new Set([
  "apply", "applied", "approve", "archive", "assign", "cancel", "close", "confirm",
  "correct", "create", "delete", "export", "import", "lock", "publish", "reject",
  "remove", "reopen", "replace", "restore", "revoke", "save", "submit", "undo",
  "unlock", "update", "upload", "withdraw",
]));

function personalActionIsoTimestamp(value) {
  const source = String(value || "").trim();
  const normalized = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(source)
    ? `${source.replace(" ", "T")}.000Z`
    : source;
  const timestamp = new Date(normalized);
  return Number.isNaN(timestamp.getTime()) ? "" : timestamp.toISOString();
}

function personalActionDomainLabel(action) {
  if (action.startsWith("sales.article-catalog.")) return "Artikelstamm";
  if (action.startsWith("sales.")) return "Verkaufsanalyse";
  if (action.startsWith("crm.")) return "CRM";
  if (action.startsWith("schedule.")) return "Dienstplanung";
  if (action.startsWith("vacation.") || action.startsWith("absence.")) return "Abwesenheit";
  if (action.startsWith("time.") || action.startsWith("time-tracking.")) return "Zeiterfassung";
  if (action.startsWith("personnel-lifecycle.")) return "Pre-Boarding";
  if (action.startsWith("personnel-learning.")) return "Schulung & Wissen";
  if (action.startsWith("personnel.") || action.startsWith("employee.")) return "Personal";
  if (action.startsWith("loan.")) return "Leihe";
  if (action.startsWith("branch-order.")) return "Filialbestellung";
  if (action.startsWith("work-rule.")) return "Regelwerk";
  if (action.startsWith("privacy.")) return "Datenschutz";
  if (action.startsWith("branding.")) return "Branding";
  if (action.startsWith("position.")) return "Positionsverwaltung";
  return "Grabenplaner";
}

function personalActionVerbLabel(suffix) {
  return ({
    apply: "Änderung angewendet",
    applied: "Änderung angewendet",
    approve: "Freigabe erteilt",
    archive: "Eintrag archiviert",
    assign: "Zuweisung gespeichert",
    cancel: "Vorgang storniert",
    close: "Vorgang abgeschlossen",
    confirm: "Vorgang bestätigt",
    correct: "Korrektur gespeichert",
    create: "Eintrag angelegt",
    delete: "Eintrag entfernt",
    export: "Ausgabe exportiert",
    import: "Daten importiert",
    lock: "Sperre aktiviert",
    publish: "Inhalt veröffentlicht",
    reject: "Vorgang abgelehnt",
    remove: "Eintrag entfernt",
    reopen: "Vorgang wieder geöffnet",
    replace: "Inhalt ersetzt",
    restore: "Zustand wiederhergestellt",
    revoke: "Freigabe widerrufen",
    save: "Änderung gespeichert",
    submit: "Vorgang eingereicht",
    undo: "Gegenaktion ausgeführt",
    unlock: "Sperre aufgehoben",
    update: "Änderung gespeichert",
    upload: "Datei hochgeladen",
    withdraw: "Vorgang zurückgezogen",
  })[suffix] || "Aktion protokolliert";
}

function personalLegacyAuditPresentation(row) {
  const action = String(row?.action || "").trim();
  const createdAt = personalActionIsoTimestamp(row?.createdAt);
  const id = Number(row?.id);
  const suffix = action.split(".").at(-1);
  if (!Number.isSafeInteger(id) || id < 1 || !createdAt
    || (!PERSONAL_ACTION_EXACT_LABELS[action] && !PERSONAL_ACTION_VISIBLE_SUFFIXES.has(suffix))) {
    return null;
  }
  const title = PERSONAL_ACTION_EXACT_LABELS[action]
    || `${personalActionDomainLabel(action)} · ${personalActionVerbLabel(suffix)}`;
  const irreversibleOutput = ["export", "import", "upload"].includes(suffix)
    || action.endsWith(".pdf");
  return Object.freeze({
    id: `audit:${id}`,
    source: "audit",
    sourceId: id,
    actionType: action,
    title,
    summary: irreversibleOutput
      ? "Die Ausgabe oder Außenwirkung bleibt als persönlicher Nachweis erhalten."
      : "Die fachliche Aktion wurde in deinem persönlichen Verlauf protokolliert.",
    createdAt,
    canUndo: false,
    undo: Object.freeze({
      available: false,
      reason: irreversibleOutput
        ? "Ausgaben und Außenwirkungen sind nicht rückgängig machbar."
        : "Für diese Aktion ist keine sichere Gegenaktion hinterlegt.",
    }),
  });
}

function personalActionCursorDecode(value) {
  if (!value) return { receiptCreatedAt: null, receiptId: null, auditId: null };
  const source = String(value);
  if (source.length > 600 || !/^[A-Za-z0-9_-]+$/.test(source)) {
    throw httpError(400, "Der Seitenzeiger des persönlichen Aktionslogs ist ungültig.", "PERSONAL_ACTION_CURSOR_INVALID");
  }
  try {
    const parsed = JSON.parse(Buffer.from(source, "base64url").toString("utf8"));
    const keys = Object.keys(parsed || {}).sort();
    if (keys.join(",") !== "auditId,receiptCreatedAt,receiptId,version"
      || parsed.version !== PERSONAL_ACTION_CURSOR_VERSION) throw new Error("invalid cursor");
    const receiptCreatedAt = parsed.receiptCreatedAt === null
      ? null : personalActionIsoTimestamp(parsed.receiptCreatedAt);
    const receiptId = parsed.receiptId === null ? null : String(parsed.receiptId || "");
    const auditId = parsed.auditId === null ? null : Number(parsed.auditId);
    if ((receiptCreatedAt === null) !== (receiptId === null)
      || (receiptId !== null && !/^[0-9a-f-]{36}$/i.test(receiptId))
      || (auditId !== null && (!Number.isSafeInteger(auditId) || auditId < 1))) {
      throw new Error("invalid cursor");
    }
    return { receiptCreatedAt, receiptId, auditId };
  } catch {
    throw httpError(400, "Der Seitenzeiger des persönlichen Aktionslogs ist ungültig.", "PERSONAL_ACTION_CURSOR_INVALID");
  }
}

function personalActionCursorEncode(cursor) {
  return Buffer.from(JSON.stringify({
    version: PERSONAL_ACTION_CURSOR_VERSION,
    receiptCreatedAt: cursor.receiptCreatedAt,
    receiptId: cursor.receiptId,
    auditId: cursor.auditId,
  })).toString("base64url");
}

function personalActionRowsDescribeSameEvent(receipt, audit) {
  if (!receipt || !audit) return false;
  const sourceAuditId = Number(receipt.sourceAuditId);
  if (Number.isSafeInteger(sourceAuditId) && sourceAuditId > 0) {
    return sourceAuditId === Number(audit.id);
  }
  if (String(receipt.actionType || "") !== String(audit.action || "")
    || String(receipt.entityType || "") !== String(audit.entityType || "")
    || String(receipt.entityId || "") !== String(audit.entityId || "")) return false;
  const receiptTime = Date.parse(personalActionIsoTimestamp(receipt.createdAt));
  const auditTime = Date.parse(personalActionIsoTimestamp(audit.createdAt));
  return Number.isFinite(receiptTime)
    && Number.isFinite(auditTime)
    && Math.abs(receiptTime - auditTime) <= 2_000;
}

function personalActionAuditResultId(result) {
  const id = Number(result?.returnedRows?.[0]?.id);
  if (!Number.isSafeInteger(id) || id < 1) {
    throw httpError(500, "Der persönliche Aktionsbeleg konnte nicht mit dem Auditnachweis verknüpft werden.", "PERSONAL_ACTION_AUDIT_LINK_FAILED");
  }
  return id;
}

async function personalActionReceiptPresentation(session, row, now = new Date()) {
  let reason = "Für diese Aktion ist keine sichere Gegenaktion hinterlegt.";
  let available = false;
  let undoLabel = "Rückgängig";
  if (row.compensatesActionId) {
    reason = "Diese Gegenaktion bleibt als eigener Nachweis erhalten.";
  } else if (row.compensatorKey) {
    const compensation = await personalActionLogRepository.findCompensation(
      session.employeeNumber,
      row.id,
    );
    if (compensation) {
      reason = "Bereits rückgängig gemacht.";
    } else if (!row.undoExpiresAt || new Date(row.undoExpiresAt).getTime() <= now.getTime()) {
      reason = "Die Rückgängig-Frist ist abgelaufen.";
    } else if (row.compensatorKey === "schedule.manual-lock.restore.v1") {
      const internal = await personalActionLogRepository.getOwn(session.employeeNumber, row.id);
      const locationId = String(internal?.undoPayload?.locationId || "");
      const weekStart = String(internal?.undoPayload?.weekStart || "");
      let scopeAllowed = false;
      try {
        assertSessionContextScope(session, { locationId });
        scopeAllowed = canManageScheduleManualLock(session, locationId);
      } catch {}
      if (!scopeAllowed) {
        reason = "Das aktuell wirksame Recht oder der Bereich fehlt.";
      } else {
        const current = await organizationPersonnelRepository.getScheduleManualLock(locationId, weekStart);
        if (Number(current?.revision || 0) !== Number(internal?.resultRevision || 0)) {
          reason = "Der Sperrstatus wurde inzwischen erneut geändert.";
        } else {
          available = true;
          undoLabel = "Sperrstatus wiederherstellen";
          reason = "";
        }
      }
    } else if (row.compensatorKey === "sales.article-catalog.import.restore.v1") {
      const internal = await personalActionLogRepository.getOwn(session.employeeNumber, row.id);
      const projection = buildSalesArticleCatalogProjection(session);
      if (!projection.import) {
        reason = "Das aktuell wirksame Artikelimportrecht fehlt.";
      } else {
        const status = await salesArticleCatalogRepository.inspectImportUndo({
          snapshotId: internal.undoPayload.snapshotId,
        });
        if (status.outcome !== "found"
          || status.impactSha256 !== internal.resultFingerprint
          || !status.canUndo) {
          reason = "Mindestens ein Artikel des Importlaufs wurde inzwischen erneut geändert.";
        } else {
          available = true;
          undoLabel = "Artikelimport zurücknehmen";
          reason = "";
        }
      }
    } else if (row.compensatorKey === "sales.article-catalog.restore.v1") {
      const internal = await personalActionLogRepository.getOwn(session.employeeNumber, row.id);
      const productId = String(internal?.undoPayload?.productId || "");
      const projection = buildSalesArticleCatalogProjection(session);
      if (!projection.write) {
        reason = "Das aktuell wirksame Artikelstammrecht fehlt.";
      } else {
        const current = await salesArticleCatalogRepository.getByProductId(productId);
        if (!current || current.currentRevision !== Number(internal?.resultRevision || 0)) {
          reason = "Der Artikel wurde inzwischen erneut geändert.";
        } else {
          available = true;
          undoLabel = "Artikeländerung zurücknehmen";
          reason = "";
        }
      }
    }
  }
  return Object.freeze({
    id: `${PERSONAL_ACTION_PUBLIC_RECEIPT_PREFIX}${row.id}`,
    source: "receipt",
    sourceId: row.id,
    actionType: row.actionType,
    title: row.summary,
    summary: row.scope,
    createdAt: personalActionIsoTimestamp(row.createdAt),
    canUndo: available,
    undo: Object.freeze({ available, label: undoLabel, reason }),
  });
}

function personalActionListLimit(value) {
  const raw = value === undefined ? PERSONAL_ACTION_LIST_DEFAULT_LIMIT : Number(value);
  if (!Number.isSafeInteger(raw) || raw < 1 || raw > PERSONAL_ACTION_LIST_MAX_LIMIT) {
    throw httpError(400, "Bitte eine gültige Seitengröße für das persönliche Aktionslog wählen.", "PERSONAL_ACTION_LIMIT_INVALID");
  }
  return raw;
}

function createPersonalActionLegacyAuditStream(actorId, beforeId) {
  let batch = [];
  let batchIndex = 0;
  let nextBeforeId = beforeId;
  let scannedThroughId = beforeId;
  let scannedRows = 0;
  let exhausted = false;
  let limited = false;
  let pending = null;

  async function peek() {
    if (pending) return pending;
    while (true) {
      while (batchIndex < batch.length) {
        const row = batch[batchIndex];
        batchIndex += 1;
        const presentation = personalLegacyAuditPresentation(row);
        if (presentation) {
          pending = { row, presentation };
          return pending;
        }
      }
      if (exhausted) return null;
      const remainingScanRows = PERSONAL_ACTION_LEGACY_SCAN_MAX_ROWS - scannedRows;
      if (remainingScanRows < 1) {
        limited = true;
        return null;
      }
      const fetchLimit = Math.min(PERSONAL_ACTION_LEGACY_FETCH_LIMIT, remainingScanRows);
      batch = await personalActionLogRepository.listLegacyAuditForActor(actorId, {
        beforeId: nextBeforeId,
        limit: fetchLimit,
      });
      batchIndex = 0;
      scannedRows += batch.length;
      if (!batch.length) {
        exhausted = true;
        return null;
      }
      const lastId = Number(batch.at(-1)?.id);
      if (!Number.isSafeInteger(lastId) || lastId < 1) {
        throw httpError(500, "Das persönliche Aktionslog konnte nicht sicher gelesen werden.", "PERSONAL_ACTION_AUDIT_ORDER_INVALID");
      }
      scannedThroughId = lastId;
      nextBeforeId = lastId;
      if (batch.length < fetchLimit) exhausted = true;
    }
  }

  return Object.freeze({
    peek,
    async take() {
      const value = await peek();
      pending = null;
      return value;
    },
    scannedThroughId() {
      return scannedThroughId;
    },
    scanLimited() {
      return limited;
    },
  });
}

app.get("/api/portal/v1/me/actions", async (request, response) => {
  const session = requireEmployeePortalSession(request);
  if (session.mustChangePassword) {
    throw httpError(428, "Bitte zuerst das persönliche Startpasswort ändern.", "PORTAL_PASSWORD_CHANGE_REQUIRED");
  }
  const limit = personalActionListLimit(request.query.limit);
  const start = personalActionCursorDecode(request.query.cursor);
  const receiptFetchLimit = Math.min(50, limit + 1);
  const auditStream = createPersonalActionLegacyAuditStream(session.employeeNumber, start.auditId);
  const receiptRows = await personalActionLogRepository.listOwn(session.employeeNumber, {
    beforeCreatedAt: start.receiptCreatedAt,
    beforeId: start.receiptId,
    limit: receiptFetchLimit,
  });
  const receiptPresentations = await Promise.all(receiptRows.map((row) => (
    personalActionReceiptPresentation(session, row)
  )));
  const cursor = { ...start };
  const actions = [];
  const emittedReceiptRows = [];
  let receiptIndex = 0;
  while (actions.length < limit) {
    const receipt = receiptRows[receiptIndex] || null;
    const auditEntry = await auditStream.peek();
    const audit = auditEntry?.row || null;
    if (!audit && auditStream.scanLimited()) break;
    if (!receipt && !audit) break;
    const receiptTime = receipt ? Date.parse(personalActionIsoTimestamp(receipt.createdAt)) : Number.NEGATIVE_INFINITY;
    const auditTime = audit ? Date.parse(personalActionIsoTimestamp(audit.createdAt)) : Number.NEGATIVE_INFINITY;
    if (receipt && (!audit || receiptTime >= auditTime)) {
      cursor.receiptCreatedAt = receipt.createdAt;
      cursor.receiptId = receipt.id;
      actions.push(receiptPresentations[receiptIndex]);
      emittedReceiptRows.push(receipt);
      receiptIndex += 1;
      continue;
    }
    await auditStream.take();
    cursor.auditId = audit.id;
    const duplicate = receiptRows.some((candidate) => (
      personalActionRowsDescribeSameEvent(candidate, audit)
    ));
    if (!duplicate) actions.push(auditEntry.presentation);
  }
  while (true) {
    const auditEntry = await auditStream.peek();
    if (!auditEntry) break;
    const audit = auditEntry.row;
    const duplicate = emittedReceiptRows.some((receipt) => (
      personalActionRowsDescribeSameEvent(receipt, audit)
    ));
    if (!duplicate) break;
    await auditStream.take();
    cursor.auditId = audit.id;
  }
  const pendingAudit = await auditStream.peek();
  if (pendingAudit) {
    const resumeBeforeId = Number(pendingAudit.row.id) + 1;
    if (Number.isSafeInteger(resumeBeforeId)) cursor.auditId = resumeBeforeId;
  } else {
    const scannedThroughId = auditStream.scannedThroughId();
    if (Number.isSafeInteger(scannedThroughId) && scannedThroughId > 0) {
      cursor.auditId = scannedThroughId;
    }
  }
  const hasMore = receiptIndex < receiptRows.length
    || receiptRows.length === receiptFetchLimit
    || Boolean(pendingAudit)
    || auditStream.scanLimited();
  response.set({ "Cache-Control": "private, no-store, max-age=0", Pragma: "no-cache" });
  response.json({
    actions: actions.map(({ source: _source, sourceId: _sourceId, ...action }) => action),
    nextCursor: hasMore ? personalActionCursorEncode(cursor) : null,
  });
});

function personalActionReceiptId(value) {
  const source = String(value || "");
  if (!source.startsWith(PERSONAL_ACTION_PUBLIC_RECEIPT_PREFIX)) return "";
  const id = source.slice(PERSONAL_ACTION_PUBLIC_RECEIPT_PREFIX.length);
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)
    ? id : "";
}

async function undoPersonalScheduleLockAction(session, sourceId) {
  try {
    return await persistenceProvider.transaction(async (executor) => {
      const repositories = createApplicationRepositories(executor);
      const personalActions = repositories.personalActionLog;
      const organization = repositories.organizationPersonnel;
      const source = await personalActions.getOwn(session.employeeNumber, sourceId);
      if (!source || source.compensatorKey !== "schedule.manual-lock.restore.v1") {
        throw httpError(404, "Die persönliche Aktion wurde nicht gefunden.", "PERSONAL_ACTION_NOT_FOUND");
      }
      const liveSession = await livePersonnelLearningRoleAdministrationActor(session, organization);
      if (liveSession?.mustChangePassword) {
        throw httpError(428, "Bitte zuerst das persönliche Startpasswort ändern.", "PORTAL_PASSWORD_CHANGE_REQUIRED");
      }
      const locationId = String(source.undoPayload?.locationId || "");
      const weekStart = String(source.undoPayload?.weekStart || "");
      try {
        assertSessionContextScope(liveSession, { locationId });
      } catch {
        throw httpError(403, "Der aktuell wirksame Filialbereich reicht für die Gegenaktion nicht aus.", "PERSONAL_ACTION_UNDO_SCOPE_DENIED");
      }
      if (!canManageScheduleManualLock(liveSession, locationId)) {
        throw httpError(403, "Für diese Gegenaktion fehlt das aktuell wirksame Dienstplanrecht.", "PERSONAL_ACTION_UNDO_PERMISSION_DENIED");
      }
      const existingCompensation = await personalActions.findCompensation(session.employeeNumber, source.id);
      if (existingCompensation) return { alreadyUndone: true, row: null };
      const now = new Date();
      if (!source.undoExpiresAt || new Date(source.undoExpiresAt).getTime() <= now.getTime()) {
        throw httpError(409, "Die Rückgängig-Frist für diese Aktion ist abgelaufen.", "PERSONAL_ACTION_UNDO_EXPIRED");
      }
      const current = await organization.getScheduleManualLock(locationId, weekStart);
      const expectedRevision = Number(source.resultRevision || 0);
      if (!expectedRevision || Number(current?.revision || 0) !== expectedRevision) {
        throw httpError(409, "Der Sperrstatus wurde inzwischen erneut geändert und kann deshalb nicht sicher wiederhergestellt werden.", "PERSONAL_ACTION_UNDO_CONFLICT");
      }
      const restoreLocked = source.undoPayload?.restoreLocked === true;
      const updated = await organization.upsertScheduleManualLock({
        locationId,
        weekStart,
        locked: restoreLocked,
        expectedRevision,
        actor: session.employeeNumber,
      });
      if (!updated) {
        throw httpError(409, "Der Sperrstatus wurde gleichzeitig geändert. Bitte das Aktionslog neu laden.", "PERSONAL_ACTION_UNDO_CONFLICT");
      }
      const createdAt = now.toISOString();
      const auditResult = await organization.insertAudit(
        session.employeeNumber,
        "personal.action.undo",
        "schedule_manual_lock",
        source.entityId,
        JSON.stringify({
          compensator: source.compensatorKey,
          locationId,
          weekStart,
          revisionBefore: expectedRevision,
          revisionAfter: Number(updated.revision),
        }),
      );
      const compensation = await personalActions.record({
        actorId: session.employeeNumber,
        actionType: "personal.action.undo",
        entityType: "schedule_manual_lock",
        entityId: source.entityId,
        scope: source.scope,
        summary: "Sperrstatus wiederhergestellt",
        compensatorKey: null,
        undoPayload: null,
        resultRevision: null,
        resultFingerprint: null,
        sourceAuditId: personalActionAuditResultId(auditResult),
        undoExpiresAt: null,
        compensatesActionId: source.id,
        createdAt,
      });
      return { alreadyUndone: false, row: updated, compensation };
    }, { isolation: "serializable" });
  } catch (error) {
    if (isUniquePersistenceViolation(error)) {
      const compensation = await personalActionLogRepository.findCompensation(
        session.employeeNumber,
        sourceId,
      );
      if (compensation) return { alreadyUndone: true, row: null, compensation };
    }
    throw error;
  }
}

async function undoPersonalSalesArticleAction(session, sourceId) {
  try {
    return await persistenceProvider.transaction(async (executor) => {
      const repositories = createApplicationRepositories(executor);
      const personalActions = repositories.personalActionLog;
      const catalog = repositories.salesArticleCatalog;
      const source = await personalActions.getOwn(session.employeeNumber, sourceId);
      if (!source || source.compensatorKey !== "sales.article-catalog.restore.v1") {
        throw httpError(404, "Die persönliche Aktion wurde nicht gefunden.", "PERSONAL_ACTION_NOT_FOUND");
      }
      const liveSession = await livePersonnelLearningRoleAdministrationActor(
        session,
        repositories.organizationPersonnel,
      );
      if (liveSession?.mustChangePassword) {
        throw httpError(428, "Bitte zuerst das persönliche Startpasswort ändern.", "PORTAL_PASSWORD_CHANGE_REQUIRED");
      }
      if (!buildSalesArticleCatalogProjection(liveSession).write) {
        throw httpError(
          403,
          "Für diese Gegenaktion fehlt das aktuell wirksame Artikelstammrecht.",
          "PERSONAL_ACTION_UNDO_PERMISSION_DENIED",
        );
      }
      const existingCompensation = await personalActions.findCompensation(
        session.employeeNumber,
        source.id,
      );
      if (existingCompensation) {
        return {
          alreadyUndone: true,
          article: await catalog.getByProductId(source.undoPayload.productId),
          liveSession,
        };
      }
      const now = new Date();
      if (!source.undoExpiresAt || new Date(source.undoExpiresAt).getTime() <= now.getTime()) {
        throw httpError(409, "Die Rückgängig-Frist für diese Aktion ist abgelaufen.", "PERSONAL_ACTION_UNDO_EXPIRED");
      }
      const current = await catalog.getByProductId(source.undoPayload.productId);
      const expectedRevision = Number(source.resultRevision || 0);
      if (!current || !expectedRevision || current.currentRevision !== expectedRevision) {
        throw httpError(
          409,
          "Der Artikel wurde inzwischen erneut geändert und kann deshalb nicht sicher wiederhergestellt werden.",
          "PERSONAL_ACTION_UNDO_CONFLICT",
        );
      }
      const createdAt = now.toISOString();
      const outcome = await catalog.restoreManual({
        productId: source.undoPayload.productId,
        expectedRevision,
        restoreRevision: source.undoPayload.restoreRevision,
        actor: session.employeeNumber,
        timestamp: createdAt,
        mutationId: crypto.randomUUID(),
      });
      if (!outcome || outcome.outcome !== "updated") {
        throw salesArticleMutationOutcomeError(outcome);
      }
      const compensation = await personalActions.record({
        actorId: session.employeeNumber,
        actionType: "personal.action.undo",
        entityType: "sales_article",
        entityId: source.entityId,
        scope: source.scope,
        summary: "Artikeländerung rückgängig gemacht",
        compensatorKey: null,
        undoPayload: null,
        resultRevision: null,
        resultFingerprint: null,
        sourceAuditId: outcome.auditId,
        undoExpiresAt: null,
        compensatesActionId: source.id,
        createdAt,
      });
      return {
        alreadyUndone: false,
        article: outcome.article,
        compensation,
        liveSession,
      };
    }, { isolation: "serializable" });
  } catch (error) {
    if (isUniquePersistenceViolation(error)) {
      const compensation = await personalActionLogRepository.findCompensation(
        session.employeeNumber,
        sourceId,
      );
      if (compensation) {
        const source = await personalActionLogRepository.getOwn(
          session.employeeNumber,
          sourceId,
        );
        return {
          alreadyUndone: true,
          article: await salesArticleCatalogRepository.getByProductId(
            source.undoPayload.productId,
          ),
          compensation,
          liveSession: await livePersonnelLearningRoleAdministrationActor(session),
        };
      }
    }
    throw error;
  }
}

async function undoPersonalSalesArticleImportAction(session, sourceId) {
  try {
    return await persistenceProvider.transaction(async (executor) => {
      const repositories = createApplicationRepositories(executor);
      const personalActions = repositories.personalActionLog;
      const catalog = repositories.salesArticleCatalog;
      const source = await personalActions.getOwn(session.employeeNumber, sourceId);
      if (!source
        || source.compensatorKey !== "sales.article-catalog.import.restore.v1") {
        throw httpError(404, "Die persönliche Aktion wurde nicht gefunden.", "PERSONAL_ACTION_NOT_FOUND");
      }
      const liveSession = await livePersonnelLearningRoleAdministrationActor(
        session,
        repositories.organizationPersonnel,
      );
      if (liveSession?.mustChangePassword) {
        throw httpError(428, "Bitte zuerst das persönliche Startpasswort ändern.", "PORTAL_PASSWORD_CHANGE_REQUIRED");
      }
      if (!buildSalesArticleCatalogProjection(liveSession).import) {
        throw httpError(
          403,
          "Für diese Gegenaktion fehlt das aktuell wirksame Artikelimportrecht.",
          "PERSONAL_ACTION_UNDO_PERMISSION_DENIED",
        );
      }
      const existingCompensation = await personalActions.findCompensation(
        session.employeeNumber,
        source.id,
      );
      if (existingCompensation) {
        return {
          alreadyUndone: true,
          snapshotId: source.undoPayload.snapshotId,
          articleCount: 0,
        };
      }
      const now = new Date();
      if (!source.undoExpiresAt || new Date(source.undoExpiresAt).getTime() <= now.getTime()) {
        throw httpError(409, "Die Rückgängig-Frist für diesen Import ist abgelaufen.", "PERSONAL_ACTION_UNDO_EXPIRED");
      }
      const status = await catalog.inspectImportUndo({
        snapshotId: source.undoPayload.snapshotId,
      });
      if (status.outcome !== "found"
        || status.impactSha256 !== source.resultFingerprint
        || !status.canUndo) {
        throw httpError(
          409,
          "Mindestens ein Artikel des Importlaufs wurde inzwischen erneut geändert.",
          "PERSONAL_ACTION_UNDO_CONFLICT",
        );
      }
      const createdAt = now.toISOString();
      const outcome = await catalog.undoImport({
        snapshotId: source.undoPayload.snapshotId,
        expectedImpactSha256: source.resultFingerprint,
        actor: session.employeeNumber,
        timestamp: createdAt,
        undoId: source.id,
      });
      if (!outcome || outcome.outcome !== "updated") {
        throw httpError(
          outcome?.outcome === "not_found" ? 404 : 409,
          outcome?.outcome === "not_found"
            ? "Der bestätigte Importlauf wurde nicht gefunden."
            : "Der Importlauf wurde inzwischen verändert und kann nicht sicher zurückgenommen werden.",
          outcome?.outcome === "not_found"
            ? "PERSONAL_ACTION_NOT_FOUND"
            : "PERSONAL_ACTION_UNDO_CONFLICT",
        );
      }
      const compensation = await personalActions.record({
        actorId: session.employeeNumber,
        actionType: "sales.article-catalog.import.undo",
        entityType: "sales_article_import_snapshot",
        entityId: source.undoPayload.snapshotId,
        scope: source.scope,
        summary: "TradeFoto-Artikelimport rückgängig gemacht",
        compensatorKey: null,
        undoPayload: null,
        resultRevision: null,
        resultFingerprint: null,
        sourceAuditId: outcome.auditId,
        undoExpiresAt: null,
        compensatesActionId: source.id,
        createdAt,
      });
      return {
        alreadyUndone: false,
        snapshotId: outcome.snapshotId,
        articleCount: outcome.articleCount,
        compensation,
      };
    }, { isolation: "serializable" });
  } catch (error) {
    if (isUniquePersistenceViolation(error)) {
      const compensation = await personalActionLogRepository.findCompensation(
        session.employeeNumber,
        sourceId,
      );
      if (compensation) {
        const source = await personalActionLogRepository.getOwn(
          session.employeeNumber,
          sourceId,
        );
        return {
          alreadyUndone: true,
          snapshotId: source.undoPayload.snapshotId,
          articleCount: 0,
          compensation,
        };
      }
    }
    throw error;
  }
}

app.post("/api/portal/v1/me/actions/:actionId/undo", async (request, response) => {
  const session = requireEmployeePortalSession(request);
  assertPortalCsrf(request);
  const sourceId = personalActionReceiptId(request.params.actionId);
  if (!sourceId) {
    throw httpError(404, "Die persönliche Aktion wurde nicht gefunden.", "PERSONAL_ACTION_NOT_FOUND");
  }
  const source = await personalActionLogRepository.getOwn(session.employeeNumber, sourceId);
  if (!source || ![
    "schedule.manual-lock.restore.v1",
    "sales.article-catalog.restore.v1",
    "sales.article-catalog.import.restore.v1",
  ].includes(source.compensatorKey)) {
    throw httpError(404, "Die persönliche Aktion wurde nicht gefunden.", "PERSONAL_ACTION_NOT_FOUND");
  }
  response.set({ "Cache-Control": "private, no-store, max-age=0", Pragma: "no-cache" });
  if (source.compensatorKey === "schedule.manual-lock.restore.v1") {
    const outcome = await undoPersonalScheduleLockAction(session, sourceId);
    const row = outcome.row || await organizationPersonnelRepository.getScheduleManualLock(
      source.undoPayload.locationId,
      source.undoPayload.weekStart,
    );
    response.json({
      undone: true,
      alreadyUndone: outcome.alreadyUndone,
      manualScheduleLock: scheduleManualLockForApi(row, {
        actor: session,
        locationId: source.undoPayload.locationId,
        weekStart: source.undoPayload.weekStart,
      }),
    });
    return;
  }
  if (source.compensatorKey === "sales.article-catalog.import.restore.v1") {
    acquireSalesArticleImportHeavyOperation(request, response, session);
    try {
      const outcome = await undoPersonalSalesArticleImportAction(session, sourceId);
      response.json({
        undone: true,
        alreadyUndone: outcome.alreadyUndone,
        salesArticleImport: {
          snapshotId: outcome.snapshotId,
          articleCount: outcome.articleCount,
        },
      });
    } catch (error) {
      salesArticleImportUndoRouteError(error);
    }
    return;
  }
  try {
    const outcome = await undoPersonalSalesArticleAction(session, sourceId);
    const article = outcome.article;
    if (!article) {
      throw httpError(404, "Der Artikel wurde nicht gefunden.", "SALES_ARTICLE_NOT_FOUND");
    }
    response.json({
      undone: true,
      alreadyUndone: outcome.alreadyUndone,
      salesArticle: await projectSalesArticleDetail(
        article,
        await salesArticleCatalogRepository.listRevisions(article.productId),
        salesArticleCatalogProjectionForSession(outcome.liveSession),
      ),
    });
  } catch (error) {
    salesArticleMutationRouteError(error);
  }
});

