async function createOwnSicknessCase(session, body = {}) {
  const startDate = String(body.startDate || "");
  const expectedEnd = String(body.expectedEnd || "");
  const note = stripEmoji(String(body.note || "").trim()).slice(0, 500);
  const today = viennaTodayIso();
  if (!isIsoDate(startDate) || startDate > today || startDate < addDays(today, -5)) {
    throw httpError(400, "Der Beginn der Krankmeldung darf heute oder höchstens fünf Tage zurückliegen.", "SICKNESS_DATE_INVALID");
  }
  if (expectedEnd && (!isIsoDate(expectedEnd) || expectedEnd < startDate || expectedEnd > addDays(startDate, 365))) {
    throw httpError(400, "Das voraussichtliche Ende muss am oder nach dem Beginn liegen.", "SICKNESS_DATE_INVALID");
  }
  const overlapping = (await sicknessAmuManagementRepository.listActiveSicknessCases({
    statusLookups: [
      sicknessStatusLookup("reported"),
      sicknessStatusLookup("aum_received"),
      sicknessStatusLookup("recovered"),
    ],
  })).find((row) => row.employee_lookup === sicknessEmployeeLookup(session.employeeNumber)
    && sicknessCaseLinksToRange(row, startDate, expectedEnd));
  if (overlapping) throw httpError(409, "Für diesen Zeitraum besteht bereits eine offene Krankmeldung.", "SICKNESS_CASE_OVERLAP");
  const context = await employeeRequestContext(session.employeeNumber, startDate);
  const staffingRisk = await evaluateSicknessStaffingRisk(
    session.employeeNumber,
    startDate,
    expectedEnd,
    context,
    { asOfDate: today },
  );
  const effectiveContext = staffingRisk.contexts?.[0] || context;
  const responsibilityContexts = await sicknessResponsibilityContexts(
    session.employeeNumber,
    startDate,
    expectedEnd,
  );
  const policy = getAmuPolicy();
  const deadlines = sicknessDeadlineState({ startAt: startDate, asOf: new Date(), localDays: policy.localWarningDays, hrDays: policy.hrWarningDays });
  const reportedAt = new Date().toISOString();
  const employeeLookup = sicknessEmployeeLookup(session.employeeNumber);
  const purgeAfter = addDays(expectedEnd || startDate, sicknessCaseRetentionDays());
  const sicknessPayload = await initializeSicknessCaseRules({
    startDate,
    expectedEnd,
    note,
    employeeNumber: session.employeeNumber,
    locationId: effectiveContext.locationId,
    departmentId: effectiveContext.departmentId,
    status: "reported",
    reportedAt,
    aumReceivedAt: "",
    closedAt: "",
    returnToWorkDate: "",
    retentionUntil: purgeAfter,
    localDeadlineDate: deadlines.localDeadlineDate,
    hrDeadlineDate: deadlines.hrDeadlineDate,
    staffingRisk,
    responsibilityContexts,
  }, { hasAum: false, now: new Date(reportedAt) });
  const caseId = await sicknessAmuManagementRepository.transaction(async (repository) => {
    const inserted = await repository.insertSicknessCase({
      employeeLookup,
      statusLookup: sicknessStatusLookup("reported"),
      protectedPayload: "",
      purgeAfter,
    });
    const insertedId = Number(inserted?.returnedRows?.[0]?.data?.id);
    if (!Number.isSafeInteger(insertedId) || insertedId < 1) {
      throw new Error("Die Krankmeldung konnte nicht gespeichert werden.");
    }
    const protectedPayload = protectJson(sicknessPayload,
      sicknessCaseProtectionContext({ id: insertedId, employee_lookup: employeeLookup }));
    await repository.updateSicknessCasePayloadInitial({
      id: insertedId,
      protectedPayload,
    });
    return insertedId;
  });
  const row = await sicknessCaseMetadata(caseId);
  const recipients = await notifySicknessRecipients(row, {
    stage: "local",
    kind: "reported",
  });
  if (staffingRisk.atRisk) {
    const riskAlert = await upsertSicknessAlert(caseId, "staffing_risk", "warning", "local");
    const riskRecipients = await notifySicknessRecipients(row, {
      stage: "local",
      kind: "staffing",
    });
    if (riskAlert.created) await queueExternalStaffingAlerts(row, riskRecipients, reportedAt);
  }
  const createdPayload = sicknessCasePayload(row);
  (await auditPortal(`protected:${sicknessEmployeeLookup(session.employeeNumber)}`, "protected.record.create", "protected_record",
    protectedPortalEntityId("sickness-case", caseId), JSON.stringify({
      staffingRisk: staffingRisk.atRisk,
      plannedShiftCount: staffingRisk.plannedShiftCount,
      aumRequired: createdPayload.aumAllowance?.required !== false,
      allowanceConsumed: createdPayload.aumAllowance?.consumesQuota === true,
      creditedSicknessMinutes: Number(createdPayload.timeValuation?.totalMinutes || 0),
    })));
  await runSicknessEscalationSweep();
  return { case: (await serializeSicknessCases([await sicknessCaseMetadata(caseId)]))[0] };
}

