const PERSONNEL_LIFECYCLE_EDITOR_SOURCE_PERMISSIONS = Object.freeze({
  onboarding: Object.freeze([
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.ONBOARDING_READ,
  ]),
  offboarding: Object.freeze([
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.OFFBOARDING_CONFIDENTIAL_READ,
    PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.HR_CONFIDENTIAL_READ,
  ]),
});

function personnelLifecycleEditorPersonalCentralSession(session, lifecycleAccess) {
  return session?.sessionKind === "employee"
    && session?.isEmployee === true
    && session?.active !== false
    && session?.serviceAccount !== true
    && session?.sharedAccount !== true
    && !isLocalSystemSession(session)
    && lifecycleAccess?.namedActor === true
    && lifecycleAccess?.central === true;
}

function personnelLifecycleEditorAllowedWorkflowTypes(session, lifecycleAccess) {
  const permissions = new Set(Array.isArray(session?.permissions) ? session.permissions : []);
  const allowed = [];
  if (PERSONNEL_LIFECYCLE_EDITOR_SOURCE_PERMISSIONS.onboarding
    .every((permission) => permissions.has(permission))
    && lifecycleAccess?.canReadOnboarding === true) {
    allowed.push("onboarding");
  }
  if (PERSONNEL_LIFECYCLE_EDITOR_SOURCE_PERMISSIONS.offboarding
    .every((permission) => permissions.has(permission))
    && lifecycleAccess?.canReadOffboardingConfidential === true
    && lifecycleAccess?.canReadHrConfidential === true) {
    allowed.push("offboarding");
  }
  return Object.freeze(allowed);
}

async function requirePersonnelLifecycleEditorCatalogAccess(request) {
  const requiredPermission = PERSONNEL_LIFECYCLE_EDITOR_PERMISSIONS.READ;
  let session = portalSessionFromRequest(request);
  try {
    session = requirePortalAnyPermissionOrLocal(request, [requiredPermission]);
    const lifecycleAccess = createPersonnelLifecycleCaseAccessSnapshot(session);
    const workflowTypes = personnelLifecycleEditorAllowedWorkflowTypes(session, lifecycleAccess);
    if (!personnelLifecycleEditorPersonalCentralSession(session, lifecycleAccess)
      || !session.permissions?.includes(requiredPermission)
      || !workflowTypes.length) {
      throw httpError(
        403,
        "Der O8-Workflow-Editor ist für diesen Zugang nicht verfügbar.",
        "PERSONNEL_LIFECYCLE_EDITOR_CATALOG_PERMISSION_REQUIRED",
      );
    }
    return Object.freeze({ session, lifecycleAccess, workflowTypes });
  } catch (error) {
    if (Number(error?.status) === 403) {
      (await auditPersonnelLifecycleAccessDenied(
        session,
        request,
        error.code || "PERSONNEL_LIFECYCLE_EDITOR_CATALOG_PERMISSION_REQUIRED",
        requiredPermission,
      ));
    }
    throw error;
  }
}

function personnelLifecycleEditorSubmittedWorkflowType(body) {
  if (!body || typeof body !== "object" || Array.isArray(body)) return "";
  const descriptor = Object.getOwnPropertyDescriptor(body, "workflowType");
  if (!descriptor || !("value" in descriptor) || typeof descriptor.value !== "string") return "";
  return descriptor.value.trim().toLowerCase();
}

async function requirePersonnelLifecycleEditorValidateAccess(request) {
  const requiredPermissions = Object.freeze([
    PERSONNEL_LIFECYCLE_EDITOR_PERMISSIONS.READ,
    PERSONNEL_LIFECYCLE_EDITOR_PERMISSIONS.DRAFT_WRITE,
    PERSONNEL_LIFECYCLE_EDITOR_PERMISSIONS.VALIDATE,
  ]);
  let session = portalSessionFromRequest(request);
  try {
    session = requirePortalAnyPermissionOrLocal(request, requiredPermissions, { csrf: true });
    const lifecycleAccess = createPersonnelLifecycleCaseAccessSnapshot(session);
    const workflowTypes = personnelLifecycleEditorAllowedWorkflowTypes(session, lifecycleAccess);
    if (!personnelLifecycleEditorPersonalCentralSession(session, lifecycleAccess)
      || !requiredPermissions.every((permission) => session.permissions?.includes(permission))) {
      throw httpError(
        403,
        "Für die O8-Entwurfsprüfung fehlen die vollständigen Fachrechte.",
        "PERSONNEL_LIFECYCLE_EDITOR_VALIDATE_PERMISSION_REQUIRED",
      );
    }
    const submittedWorkflowType = personnelLifecycleEditorSubmittedWorkflowType(request.body);
    if (["onboarding", "offboarding"].includes(submittedWorkflowType)
      && !workflowTypes.includes(submittedWorkflowType)) {
      throw httpError(
        403,
        "Für diese Lifecycle-Prozessart fehlt das getrennte Quellrecht.",
        "PERSONNEL_LIFECYCLE_EDITOR_SOURCE_PERMISSION_REQUIRED",
      );
    }
    return Object.freeze({
      session,
      lifecycleAccess,
      workflowTypes,
      submittedWorkflowType,
    });
  } catch (error) {
    if (Number(error?.status) === 403) {
      (await auditPersonnelLifecycleAccessDenied(
        session,
        request,
        error.code || "PERSONNEL_LIFECYCLE_EDITOR_VALIDATE_PERMISSION_REQUIRED",
        requiredPermissions.join("|"),
      ));
    }
    throw error;
  }
}

function personnelProfileCanReadMasterProjection(accessContext) {
  return accessContext.profileAccess.localSystem
    || accessContext.profileAccess.scoped
    || ((accessContext.profileAccess.personalHr || accessContext.profileAccess.personalDeveloper)
      && actorCanReadPersonnelSensitiveData(accessContext.session)
      && accessContext.recordAccess.canReadSensitive === true);
}

function personnelProfileCanReadDocumentProjection(accessContext) {
  return accessContext.profileAccess.localSystem
    || ((accessContext.profileAccess.personalHr || accessContext.profileAccess.personalDeveloper)
      && actorCanReadPersonnelSensitiveData(accessContext.session)
      && accessContext.recordAccess.canReadDocuments === true);
}

function personnelProfilePreflightCapability(accessContext, tab) {
  if (tab === "overview") return accessContext.profileAccess.canReadProfiles === true;
  if (tab === "master_org") {
    return accessContext.profileAccess.canReadMaster === true
      && personnelProfileCanReadMasterProjection(accessContext);
  }
  if (tab === "onboarding") {
    return personnelLifecycleOnboardingProfileAccessForSession(
      accessContext.session,
    ).canRead === true;
  }
  if (tab === "offboarding") {
    return personnelLifecycleOffboardingProfileAccessForSession(
      accessContext.session,
    ).canRead === true;
  }
  return tab === "documents"
    && accessContext.profileAccess.canReadDocuments === true
    && personnelProfileCanReadDocumentProjection(accessContext);
}

function personnelProfileCapabilities(accessContext, row) {
  const onboardingAccess = personnelLifecycleOnboardingProfileAccessForSession(
    accessContext.session,
  );
  const offboardingAccess = personnelLifecycleOffboardingProfileAccessForSession(
    accessContext.session,
  );
  return Object.freeze({
    canReadOverview: accessContext.profileAccess.canReadSubject(row) === true,
    canReadMasterOrg: accessContext.profileAccess.canReadMasterSubject(row) === true
      && personnelProfileCanReadMasterProjection(accessContext),
    canReadDocuments: accessContext.profileAccess.canReadDocumentsSubject(row) === true
      && personnelProfileCanReadDocumentProjection(accessContext),
    canReadOnboardingPreview: onboardingAccess.canRead === true,
    canStartOnboarding: onboardingAccess.canStart === true,
    canCloseOnboarding: onboardingAccess.canClose === true,
    canReadOffboardingConfidential: offboardingAccess.canRead === true,
    canPrepareOffboarding: offboardingAccess.canPrepare === true,
    canApproveOffboardingException: offboardingAccess.canApproveException === true,
    canReleaseOffboardingCommunication:
      offboardingAccess.canReleaseCommunication === true,
    canConfirmOffboardingInformation: offboardingAccess.canConfirmInformation === true,
    canExecuteOffboarding: offboardingAccess.canExecute === true,
    canCloseOffboarding: offboardingAccess.canClose === true,
    canReadOffboardingConfidentialAudit:
      offboardingAccess.canReadConfidentialAudit === true,
  });
}

function personnelProfileTabs(capabilities) {
  return Object.freeze({
    overview: Object.freeze({ available: capabilities.canReadOverview === true }),
    masterData: Object.freeze({ available: capabilities.canReadMasterOrg === true }),
    documents: Object.freeze({ available: capabilities.canReadDocuments === true }),
    onboarding: Object.freeze({ available: capabilities.canReadOnboardingPreview === true }),
    training: Object.freeze({ available: false }),
    offboarding: Object.freeze({
      available: capabilities.canReadOffboardingConfidential === true,
    }),
    history: Object.freeze({ available: false }),
  });
}

function personnelProfileSubjectProjection(row) {
  return Object.freeze({
    employeeNumber: String(row.personnel_number),
    displayName: String(row.display_name),
    active: Boolean(row.active),
    organization: Object.freeze({
      positionName: row.position_name === null ? null : String(row.position_name),
      costCenter: Object.freeze({
        code: row.cost_center_code === null ? null : String(row.cost_center_code),
        name: row.cost_center_name === null ? null : String(row.cost_center_name),
      }),
      location: Object.freeze({
        id: row.location_id === null ? null : String(row.location_id),
        name: row.location_name === null ? null : String(row.location_name),
      }),
      department: Object.freeze({
        id: row.department_id === null ? null : Number(row.department_id),
        name: row.department_name === null ? null : String(row.department_name),
      }),
    }),
  });
}

async function personnelLifecycleOnboardingExecutionProjection(
  employeeNumber,
  onboardingPreview,
  onboardingAccess,
) {
  const activeCase = await customProcessRepository.currentEpisodeOnboardingCaseForEmployee({
    employeeNumber,
  });
  let activeCaseProjection = null;
  if (activeCase) {
    const caseId = String(activeCase.id || "");
    const progress = await customProcessRepository.lifecycleCaseProgress({ caseId });
    if (!caseId || !progress || progress.case_id !== caseId) {
      throw httpError(
        503,
        "Der aktive Onboarding-Fall konnte nicht sicher geprueft werden.",
        "PERSONNEL_LIFECYCLE_ONBOARDING_INTEGRITY_FAILED",
      );
    }
    activeCaseProjection = Object.freeze({
      caseId,
      state: String(activeCase.state || ""),
      createdAt: String(activeCase.created_at || ""),
      startedAt: String(activeCase.updated_at || activeCase.created_at || ""),
      completedAt: ["completed", "cancelled"].includes(String(activeCase.state || ""))
        ? String(activeCase.updated_at || "")
        : null,
      packageCount: Number(progress.package_count || 0),
      taskCount: Number(progress.total_step_count || 0),
      completedTaskCount: Number(progress.completed_step_count || 0),
      closeAvailable: String(activeCase.state || "") === "active"
        && onboardingAccess.canClose === true
        && Number(progress.package_count || 0) > 0
        && Number(progress.package_count || 0) === Number(progress.linked_run_count || 0)
        && Number(progress.assignment_count || 0) === Number(progress.linked_assignment_count || 0)
        && Number(progress.total_step_count || 0) > 0
        && Number(progress.completed_step_count || 0) === Number(progress.total_step_count || 0)
        && Number(progress.skipped_step_count || 0) === 0
        && Number(progress.linked_run_count || 0) > 0
        && Number(progress.linked_run_count || 0) === Number(progress.resolved_run_count || 0),
    });
  }
  const resolvableCodes = new Set([
    "onboarding_execution_deferred_until_o4",
    "assignment_selection_required",
    "m4_publication_review_required",
    "required_package_family_unmapped",
  ]);
  const hardBlocker = (onboardingPreview.blockers || []).some(({ code }) => (
    !resolvableCodes.has(code)
  ));
  const mandatoryCompanyPackages = onboardingPreview.packageResolution.packages.filter((entry) => (
    entry.scope?.type === "company"
      && entry.requirementKind === "mandatory"
      && entry.authorityLevel === "central"
  ));
  return Object.freeze({
    contractVersion: PERSONNEL_LIFECYCLE_O4_CONTRACT_VERSION,
    mode: "controlled_onboarding_start",
    previewSha256: personnelLifecycleOnboardingPreviewSha256(onboardingPreview),
    formAvailable: onboardingAccess.canStart === true
      && activeCaseProjection === null
      && !hardBlocker
      && mandatoryCompanyPackages.length >= 2,
    requiredConfirmation: "START_ONBOARDING",
    activeCase: activeCaseProjection,
  });
}

function personnelProfileBaseProjection(row, capabilities) {
  return {
    profile: personnelProfileSubjectProjection(row),
    tabs: personnelProfileTabs(capabilities),
    capabilities,
  };
}

function personnelProfileReadableMasterFields(fieldAccess) {
  return PERSONNEL_PROFILE_MASTER_FIELD_ALLOWLIST
    .filter((fieldKey) => ["read", "write"].includes(fieldAccess[fieldKey]));
}

function personnelProfileMasterDataProjection(profile, fieldKeys) {
  const projection = {};
  for (const fieldKey of fieldKeys) {
    setPersonnelPathValue(projection, fieldKey, personnelPathValue(profile, fieldKey) ?? "");
  }
  return projection;
}

function personnelProfileNotFound() {
  return httpError(404, "Das Teammitglied wurde nicht gefunden.", "EMPLOYEE_NOT_FOUND");
}

async function loadPersonnelProfileSubject(accessContext, employeeNumber, request, tab) {
  const row = await organizationPersonnelRepository
    .getEmployeeProfileOverviewProjection(employeeNumber);
  if (!row) {
    (await auditPersonnelRecordDenied(
      accessContext.session,
      employeeNumber,
      request,
      "EMPLOYEE_NOT_FOUND",
    ));
    throw personnelProfileNotFound();
  }
  const capabilities = personnelProfileCapabilities(accessContext, row);
  if (capabilities[PERSONNEL_PROFILE_TAB_CAPABILITIES[tab]] !== true) {
    (await auditPersonnelRecordDenied(
      accessContext.session,
      employeeNumber,
      request,
      "PERSONNEL_PROFILE_SCOPE_DENIED",
      tab === "documents" ? ["documents"] : [],
    ));
    throw personnelProfileNotFound();
  }
  return Object.freeze({ row, capabilities });
}

const PERSONNEL_WORKFLOW_ROUTE_ACTIONS = Object.freeze({
  read: Object.freeze({
    permission: PERSONNEL_WORKFLOW_PERMISSIONS.READ,
    capability: "canRead",
    write: false,
    central: true,
  }),
  publish: Object.freeze({
    permission: PERSONNEL_WORKFLOW_PERMISSIONS.PUBLISH,
    capability: "canPublish",
    write: true,
    central: true,
  }),
  instanceRead: Object.freeze({
    permission: PERSONNEL_WORKFLOW_PERMISSIONS.READ,
    capability: "canReadInstances",
    write: false,
    central: false,
  }),
  instanceStart: Object.freeze({
    permission: PERSONNEL_WORKFLOW_PERMISSIONS.PUBLISH,
    capability: "canStartInstances",
    write: true,
    central: false,
  }),
});

function publicPersonnelWorkflowCapabilities(access) {
  const readScopes = access?.allowedScopesByPermission?.[
    PERSONNEL_WORKFLOW_PERMISSIONS.READ
  ] || [];
  const locationIds = [...new Set(readScopes
    .map((scope) => String(scope.locationId || ""))
    .filter(Boolean))];
  const departmentIds = [...new Set(readScopes
    .map((scope) => Number(scope.departmentId || 0))
    .filter((departmentId) => Number.isSafeInteger(departmentId) && departmentId > 0))];
  const scope = access?.global
    ? { type: "global" }
    : access?.role === "manager"
      ? { type: "location", locationIds }
      : access?.role === "department_manager"
        ? { type: "department", locationIds, departmentIds }
        : { type: "none" };
  return Object.freeze({
    scope,
    canRead: access?.canRead === true,
    canReadInstances: access?.canReadInstances === true,
    canStartInstances: access?.canStartInstances === true,
    canWriteDrafts: access?.canWriteDrafts === true,
    canReview: access?.canReview === true,
    canPublish: access?.canPublish === true,
    canManageLocalSupplements: access?.canManageLocalSupplements === true,
    canReadConfidential: access?.canReadConfidential === true,
    canWriteConfidential: access?.canWriteConfidential === true,
    canDelegate: access?.canDelegate === true,
  });
}

function personnelWorkflowInstanceScope(value = {}) {
  const locationId = String(value.locationId ?? value.location_id ?? "").trim() || null;
  const departmentId = Number(value.departmentId ?? value.department_id ?? 0) || null;
  return {
    type: departmentId ? "department" : (locationId ? "location" : "company"),
    locationId,
    departmentId,
  };
}

function personnelWorkflowRecipientAccess(recipient) {
  const permissionState = effectivePortalPermissionState(
    recipient?.employee_number,
    recipient?.role,
    recipient?.role_permissions,
    recipient?.granted_permissions,
    recipient?.denied_permissions,
  );
  const explicitScopes = portalAccessScopesForPrincipal({
    employeeNumber: recipient?.employee_number,
    role: recipient?.role,
    homeLocationId: recipient?.home_location_id,
    preferredDepartmentId: recipient?.preferred_department_id,
    scopesValue: recipient?.access_scopes,
  });
  return createPersonnelWorkflowAccessSnapshot({
    actorId: recipient?.employee_number,
    role: recipient?.role,
    permissions: permissionState.effectivePermissions,
    explicitScopes,
    permissionScopes: parsePortalPermissionScopes(recipient?.permission_scopes),
  });
}

function personnelLifecycleOnboardingRecipientEligible(recipient, scope, step = {}) {
  if (!recipient || ["it_admin", "developer", "local"].includes(recipient.role)
    || !customProcessPortalUserInScope(recipient, scope)) return false;
  const responsibilityType = String(
    step?.responsibilityType ?? step?.responsibility?.type ?? "",
  );
  const responsibilityReference = String(
    step?.responsibilityReference ?? step?.responsibility?.reference ?? "",
  );
  const explicitlyAssignedEmployee = recipient.role === "employee"
    && responsibilityType === "employee"
    && responsibilityReference === String(recipient.employee_number || "");
  if (explicitlyAssignedEmployee) return true;
  const permissionState = effectivePortalPermissionState(
    recipient.employee_number,
    recipient.role,
    recipient.role_permissions,
    recipient.granted_permissions,
    recipient.denied_permissions,
  );
  const explicitScopes = portalAccessScopesForPrincipal({
    employeeNumber: recipient.employee_number,
    role: recipient.role,
    homeLocationId: recipient.home_location_id,
    preferredDepartmentId: recipient.preferred_department_id,
    scopesValue: recipient.access_scopes,
  });
  const access = createPersonnelLifecycleCaseAccessSnapshot({
    actorId: recipient.employee_number,
    role: recipient.role,
    sessionKind: "employee",
    isEmployee: true,
    active: true,
    permissions: permissionState.effectivePermissions,
    explicitScopes,
    permissionScopes: parsePortalPermissionScopes(recipient.permission_scopes),
  });
  const context = {
    caseType: "onboarding",
    operationalReleased: true,
    scope,
  };
  if (access.central === true) {
    return access.canReadOperational === true && access.canUpdateOperational === true;
  }
  return access.canReadOperationalScope(context) === true
    && access.canUpdateOperationalScope(context) === true;
}

function personnelLifecycleOffboardingRecipientEligible(
  recipient,
  scope,
  subjectEmployeeNumber,
  recipientClass,
) {
  if (!recipient || recipient.role === "local"
    || String(recipient.employee_number || "") === String(subjectEmployeeNumber || "")
    || !customProcessPortalUserInScope(recipient, scope)) return false;
  const permissionState = effectivePortalPermissionState(
    recipient.employee_number,
    recipient.role,
    recipient.role_permissions,
    recipient.granted_permissions,
    recipient.denied_permissions,
  );
  const explicitScopes = portalAccessScopesForPrincipal({
    employeeNumber: recipient.employee_number,
    role: recipient.role,
    homeLocationId: recipient.home_location_id,
    preferredDepartmentId: recipient.preferred_department_id,
    scopesValue: recipient.access_scopes,
  });
  const access = createPersonnelLifecycleCaseAccessSnapshot({
    actorId: recipient.employee_number,
    role: recipient.role,
    sessionKind: "employee",
    isEmployee: true,
    active: true,
    permissions: permissionState.effectivePermissions,
    explicitScopes,
    permissionScopes: parsePortalPermissionScopes(recipient.permission_scopes),
  });
  const rolesByRecipientClass = {
    [PERSONNEL_LIFECYCLE_RECIPIENT_CLASSES.LEADERSHIP]: new Set([
      "manager",
      "department_manager",
      "hr",
      "admin",
      "developer",
    ]),
    [PERSONNEL_LIFECYCLE_RECIPIENT_CLASSES.IT_SECURITY]: new Set([
      "it_admin",
      "developer",
    ]),
    [PERSONNEL_LIFECYCLE_RECIPIENT_CLASSES.ASSET_CUSTODIAN]: new Set([
      "employee",
      "manager",
      "department_manager",
      "admin",
      "it_admin",
      "developer",
    ]),
    [PERSONNEL_LIFECYCLE_RECIPIENT_CLASSES.PAYROLL]: new Set([
      "hr",
      "admin",
      "developer",
    ]),
  };
  const eligibleRoles = rolesByRecipientClass[String(recipientClass || "")];
  if (!eligibleRoles?.has(recipient.role)) return false;
  if (recipient.role === "employee"
    && recipientClass === PERSONNEL_LIFECYCLE_RECIPIENT_CLASSES.ASSET_CUSTODIAN) {
    return true;
  }
  if (access.canReadOperational !== true || access.canUpdateOperational !== true) return false;
  if (access.central === true) return true;
  const context = {
    caseType: "offboarding",
    operationalReleased: true,
    scope,
  };
  return access.canReadOperationalScope(context) === true
    && access.canUpdateOperationalScope(context) === true;
}

function personnelWorkflowInstanceAccessForSession(session, workflowAccess) {
  const lifecycleAccess = personnelLifecycleAccessForSession(session);
  const permissions = new Set(Array.isArray(session?.permissions) ? session.permissions : []);
  const canReadEmployeeSubject = workflowAccess?.localSystem === true
    || permissions.has("employees:read");
  const actorId = portalActorId(session);
  return Object.freeze({
    actorId,
    canStartScope(scope, publication) {
      if (workflowAccess?.canStartScope(scope) !== true) return false;
      const publicationScope = publication?.scope;
      return publicationScope?.type === "company"
        || workflowAccess?.canReadScope(publicationScope) === true;
    },
    canStartCandidateSubject(subject) {
      return lifecycleAccess?.canWriteApplication(subject?.scope) === true;
    },
    canStartEmployeeSubject() {
      return canReadEmployeeSubject;
    },
    canAssignPersonnelWorkflowStep({ scope, recipient } = {}) {
      if (!recipient || ["it_admin", "developer", "local"].includes(recipient.role)) {
        return false;
      }
      const recipientAccess = personnelWorkflowRecipientAccess(recipient);
      return recipientAccess.canReadInstances === true
        && recipientAccess.canReadScope(scope) === true
        && customProcessPortalUserInScope(recipient, scope);
    },
    canCompletePersonnelWorkflowTask({ scope, assignment, recipient } = {}) {
      if (workflowAccess?.canReadInstances !== true
        || workflowAccess?.canReadScope(scope) !== true
        || !assignment || assignment.employeeNumber !== actorId
        || !recipient || recipient.employee_number !== actorId
        || ["it_admin", "developer", "local"].includes(recipient.role)) {
        return false;
      }
      return customProcessPortalUserInScope(recipient, scope);
    },
    canReadPersonnelWorkflowInstance(row) {
      const scope = personnelWorkflowInstanceScope(row);
      if (workflowAccess?.canReadScope(scope) !== true) return false;
      if (row?.subject_type === "candidate") {
        return lifecycleAccess?.canReadApplication(scope) === true;
      }
      return row?.subject_type === "employee" && canReadEmployeeSubject;
    },
  });
}

async function auditPersonnelWorkflowAccessDenied(session, request, reason, requiredPermission = "") {
  if (!session?.employeeNumber) return;
  (await auditPortal(
    session.employeeNumber,
    "personnel-workflow.access.denied",
    "personnel_workflow",
    "access",
    JSON.stringify({
      reason: String(reason || "PERSONNEL_WORKFLOW_ACCESS_DENIED").slice(0, 120),
      requiredPermission: String(requiredPermission || "").slice(0, 120),
      route: personnelRecordDeniedRoute(request),
    }),
  ));
}

async function requirePersonnelWorkflowAccess(request, { action = "read" } = {}) {
  const definition = PERSONNEL_WORKFLOW_ROUTE_ACTIONS[action];
  if (!definition) throw new TypeError(`Unbekannte Workflow-Center-Aktion: ${action}`);
  let session = portalSessionFromRequest(request);
  try {
    session = requirePortalAnyPermissionOrLocal(
      request,
      [definition.permission],
      { csrf: definition.write },
    );
    const access = createPersonnelWorkflowAccessSnapshot(session);
    if (access?.[definition.capability] !== true) {
      throw httpError(
        403,
        "Für diese Workflow-Center-Aktion fehlt die fachliche Freigabe.",
        "PERSONNEL_WORKFLOW_PERMISSION_REQUIRED",
      );
    }
    if (definition.central && access.global && !access.localSystem) {
      const requiredCentral = definition.write
        ? ["personnel:central:read", "personnel:central:write"]
        : ["personnel:central:read"];
      if (requiredCentral.some((permission) => !session.permissions?.includes(permission))) {
        throw httpError(
          403,
          "Für diese Aktion fehlt die zentrale Personalberechtigung.",
          "PERSONNEL_WORKFLOW_CENTRAL_PERMISSION_REQUIRED",
        );
      }
    }
    return Object.freeze({
      session,
      access,
      capabilities: publicPersonnelWorkflowCapabilities(access),
    });
  } catch (error) {
    if (Number(error?.status) === 403) {
      (await auditPersonnelWorkflowAccessDenied(
        session,
        request,
        error.code || "PERSONNEL_WORKFLOW_ACCESS_DENIED",
        definition.permission,
      ));
    }
    throw error;
  }
}

function personnelWorkflowRouteError(error) {
  if (error instanceof PersonnelWorkflowInstanceError) {
    const status = error.kind === PERSONNEL_WORKFLOW_INSTANCE_ERROR_KINDS.FORBIDDEN
      ? 403
      : error.kind === PERSONNEL_WORKFLOW_INSTANCE_ERROR_KINDS.NOT_FOUND
        ? 404
        : error.kind === PERSONNEL_WORKFLOW_INSTANCE_ERROR_KINDS.CONFLICT
          ? 409
          : error.kind === PERSONNEL_WORKFLOW_INSTANCE_ERROR_KINDS.INTEGRITY
            ? 503
            : 400;
    throw httpError(status, error.message, error.code);
  }
  if (error instanceof PersonnelWorkflowError) {
    const status = error.kind === PERSONNEL_WORKFLOW_ERROR_KINDS.FORBIDDEN
      ? 403
      : error.kind === PERSONNEL_WORKFLOW_ERROR_KINDS.NOT_FOUND
        ? 404
        : error.kind === PERSONNEL_WORKFLOW_ERROR_KINDS.CONFLICT
          ? 409
          : error.kind === PERSONNEL_WORKFLOW_ERROR_KINDS.INTEGRITY
            ? 503
            : 400;
    throw httpError(status, error.message, error.code);
  }
  if (["PERSISTENCE_UNIQUE_VIOLATION", "PERSISTENCE_RETRYABLE_TRANSACTION", "PERSISTENCE_BUSY"]
    .includes(error?.code)) {
    throw httpError(
      409,
      "Die Workflow-Version wurde parallel geändert. Bitte neu laden.",
      "PERSONNEL_WORKFLOW_CONCURRENT_CHANGE",
    );
  }
  if ([
    "PERSISTENCE_FOREIGN_KEY_VIOLATION",
    "PERSISTENCE_NOT_NULL_VIOLATION",
    "PERSISTENCE_CHECK_VIOLATION",
  ].includes(error?.code)) {
    throw httpError(
      400,
      "Die Workflow-Version verweist auf einen ungültigen Bereich oder verletzt eine gespeicherte Regel.",
      "PERSONNEL_WORKFLOW_REFERENCE_INVALID",
    );
  }
  throw error;
}

function personnelLifecycleOnboardingRouteError(error) {
  if (error instanceof PersonnelLifecycleOnboardingExecutionError) {
    const status = error.kind === PERSONNEL_LIFECYCLE_ONBOARDING_EXECUTION_ERROR_KINDS.FORBIDDEN
      ? 403
      : error.kind === PERSONNEL_LIFECYCLE_ONBOARDING_EXECUTION_ERROR_KINDS.NOT_FOUND
        ? 404
        : error.kind === PERSONNEL_LIFECYCLE_ONBOARDING_EXECUTION_ERROR_KINDS.CONFLICT
          ? 409
          : error.kind === PERSONNEL_LIFECYCLE_ONBOARDING_EXECUTION_ERROR_KINDS.INTEGRITY
            ? 503
            : 400;
    throw httpError(status, error.message, error.code);
  }
  if (error instanceof PersonnelWorkflowInstanceError) {
    personnelWorkflowRouteError(error);
  }
  if ([
    "PERSISTENCE_FOREIGN_KEY_VIOLATION",
    "PERSISTENCE_NOT_NULL_VIOLATION",
    "PERSISTENCE_CHECK_VIOLATION",
  ].includes(error?.code)) {
    throw httpError(
      409,
      "Die Onboarding-Grundlage hat sich geaendert. Bitte neu laden.",
      "PERSONNEL_LIFECYCLE_ONBOARDING_PREVIEW_STALE",
    );
  }
  throw error;
}

function personnelLifecycleOnboardingTaskRouteError(error) {
  if (error instanceof PersonnelLifecycleOnboardingTaskError) {
    const status = error.kind === PERSONNEL_LIFECYCLE_ONBOARDING_TASK_ERROR_KINDS.FORBIDDEN
      ? 403
      : error.kind === PERSONNEL_LIFECYCLE_ONBOARDING_TASK_ERROR_KINDS.NOT_FOUND
        ? 404
        : error.kind === PERSONNEL_LIFECYCLE_ONBOARDING_TASK_ERROR_KINDS.CONFLICT
          ? 409
          : error.kind === PERSONNEL_LIFECYCLE_ONBOARDING_TASK_ERROR_KINDS.INTEGRITY
            ? 503
            : 400;
    throw httpError(status, error.message, error.code);
  }
  if (error instanceof PersonnelWorkflowInstanceError) {
    personnelWorkflowRouteError(error);
  }
  throw error;
}

function personnelLifecycleOffboardingRouteError(error) {
  if (error instanceof PersonnelLifecycleOffboardingContractError) {
    throw httpError(400, error.message, error.code);
  }
  if (error instanceof PersonnelLifecycleOffboardingServiceError) {
    const status = error.kind === PERSONNEL_LIFECYCLE_OFFBOARDING_SERVICE_ERROR_KINDS.FORBIDDEN
      ? 403
      : error.kind === PERSONNEL_LIFECYCLE_OFFBOARDING_SERVICE_ERROR_KINDS.NOT_FOUND
        ? 404
        : error.kind === PERSONNEL_LIFECYCLE_OFFBOARDING_SERVICE_ERROR_KINDS.CONFLICT
          ? 409
          : error.kind === PERSONNEL_LIFECYCLE_OFFBOARDING_SERVICE_ERROR_KINDS.INTEGRITY
            ? 503
            : 400;
    throw httpError(status, error.message, error.code);
  }
  if (["PERSISTENCE_UNIQUE_VIOLATION", "PERSISTENCE_RETRYABLE_TRANSACTION", "PERSISTENCE_BUSY"]
    .includes(error?.code)) {
    throw httpError(
      409,
      "Der Offboarding-Stand wurde parallel geändert. Bitte neu laden.",
      "PERSONNEL_LIFECYCLE_OFFBOARDING_CONCURRENT_CHANGE",
    );
  }
  if ([
    "PERSISTENCE_FOREIGN_KEY_VIOLATION",
    "PERSISTENCE_NOT_NULL_VIOLATION",
    "PERSISTENCE_CHECK_VIOLATION",
  ].includes(error?.code)) {
    throw httpError(
      409,
      "Die geschützte Offboarding-Grundlage hat sich geändert. Bitte neu laden.",
      "PERSONNEL_LIFECYCLE_OFFBOARDING_REFERENCE_CONFLICT",
    );
  }
  throw error;
}

async function auditPersonnelWorkflowServiceDenied(accessContext, request, error) {
  if (!(error instanceof PersonnelWorkflowError)
    && !(error instanceof PersonnelWorkflowInstanceError)) return;
  const scopedNotFound = accessContext?.access?.global !== true
    && [PERSONNEL_WORKFLOW_ERROR_KINDS.NOT_FOUND,
      PERSONNEL_WORKFLOW_INSTANCE_ERROR_KINDS.NOT_FOUND].includes(error.kind);
  if (![PERSONNEL_WORKFLOW_ERROR_KINDS.FORBIDDEN,
    PERSONNEL_WORKFLOW_INSTANCE_ERROR_KINDS.FORBIDDEN].includes(error.kind)
    && !scopedNotFound) return;
  (await auditPersonnelWorkflowAccessDenied(
    accessContext.session,
    request,
    scopedNotFound ? "PERSONNEL_WORKFLOW_SCOPED_NOT_FOUND" : error.code,
    PERSONNEL_WORKFLOW_PERMISSIONS.READ,
  ));
}

function personnelLifecycleConversionInput(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw httpError(
      400,
      "Bitte einen gültigen Einstellvorgang übermitteln.",
      "PERSONNEL_LIFECYCLE_CONVERSION_INPUT_INVALID",
    );
  }
  const allowed = new Set([
    "operationId",
    "candidateRevision",
    "applicationRevision",
    "employee",
  ]);
  if (Object.keys(value).some((key) => !allowed.has(key))) {
    throw httpError(
      400,
      "Der Einstellvorgang enthält unbekannte Felder.",
      "PERSONNEL_LIFECYCLE_CONVERSION_INPUT_INVALID",
    );
  }
  const operationId = String(value.operationId || "").trim().toLowerCase();
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(operationId)) {
    throw httpError(
      400,
      "Für den Einstellvorgang wird eine neue UUID benötigt.",
      "PERSONNEL_LIFECYCLE_CONVERSION_ID_INVALID",
    );
  }
  const candidateRevision = Number(value.candidateRevision);
  const applicationRevision = Number(value.applicationRevision);
  if (!Number.isSafeInteger(candidateRevision) || candidateRevision < 1
    || !Number.isSafeInteger(applicationRevision) || applicationRevision < 1) {
    throw httpError(
      400,
      "Für Bewerber und Bewerbung werden die zuletzt gelesenen Revisionen benötigt.",
      "PERSONNEL_LIFECYCLE_REVISION_INVALID",
    );
  }
  const submittedEmployee = value.employee;
  if (!submittedEmployee || typeof submittedEmployee !== "object" || Array.isArray(submittedEmployee)) {
    throw httpError(
      400,
      "Bitte die Mitarbeiter-Zieldaten vollständig angeben.",
      "PERSONNEL_LIFECYCLE_CONVERSION_EMPLOYEE_INVALID",
    );
  }
  const allowedEmployeeFields = new Set([
    "personnelNumber",
    "nickname",
    "color",
    "contractedHours",
    "targetWorkdaysPerWeek",
    "preferredDayOff",
    "fixedWorkdays",
    "positionId",
    "costCenterId",
    "preferredDepartmentId",
  ]);
  const requiredEmployeeFields = [
    "personnelNumber",
    "nickname",
    "contractedHours",
    "targetWorkdaysPerWeek",
    "positionId",
    "costCenterId",
  ];
  if (Object.keys(submittedEmployee).some((key) => !allowedEmployeeFields.has(key))
    || requiredEmployeeFields.some((key) => !own(submittedEmployee, key))) {
    throw httpError(
      400,
      "Die Mitarbeiter-Zieldaten sind unvollständig oder enthalten unbekannte Felder.",
      "PERSONNEL_LIFECYCLE_CONVERSION_EMPLOYEE_INVALID",
    );
  }
  const fixedWorkdays = normalizeFixedWorkdays(submittedEmployee.fixedWorkdays)
    .sort((left, right) => fixedWorkdayKeys.indexOf(left) - fixedWorkdayKeys.indexOf(right));
  const employee = {
    personnelNumber: String(submittedEmployee.personnelNumber || "").trim(),
    nickname: String(submittedEmployee.nickname || "").trim(),
    color: String(submittedEmployee.color || "#0b84c6").trim().toLowerCase(),
    contractedHours: Number(submittedEmployee.contractedHours),
    targetWorkdaysPerWeek: Number(submittedEmployee.targetWorkdaysPerWeek),
    preferredDayOff: String(submittedEmployee.preferredDayOff || "").trim(),
    fixedWorkdays,
    positionId: String(submittedEmployee.positionId || "").trim(),
    costCenterId: String(submittedEmployee.costCenterId || "").trim(),
    preferredDepartmentId: normalizeDepartmentId(
      submittedEmployee.preferredDepartmentId,
      true,
    ),
  };
  if (!/^[A-Za-z0-9._-]{1,24}$/.test(employee.personnelNumber)) {
    throw httpError(
      400,
      "Bitte eine gültige Personalnummer eingeben.",
      "PERSONNEL_LIFECYCLE_EMPLOYEE_NUMBER_INVALID",
    );
  }
  return Object.freeze({
    id: operationId,
    candidateRevision,
    applicationRevision,
    employee: Object.freeze(employee),
  });
}

function candidatePersonnelRecordInput(profile = {}) {
  const identity = {
    firstName: String(profile.firstName || ""),
    lastName: String(profile.lastName || ""),
  };
  if (profile.birthDate) identity.birthDate = String(profile.birthDate);
  if (Array.isArray(profile.citizenships) && profile.citizenships.length) {
    identity.nationality = profile.citizenships.join(", ").slice(0, 160);
  }
  const address = Object.fromEntries(Object.entries(profile.address || {})
    .filter(([, fieldValue]) => String(fieldValue || "").trim()));
  const sensitive = { identity };
  if (Object.keys(address).length) sensitive.address = address;
  if (profile.email) sensitive.privateEmail = String(profile.email);
  return {
    ...(profile.phone ? { phone: String(profile.phone) } : {}),
    sensitive,
  };
}

async function auditPersonnelLifecycleConversionFieldDenied(session, request, operationId, denial) {
  const reason = String(denial?.reason || "");
  if (!PERSONNEL_RECORD_FIELD_DENIAL_CODES.has(reason)) return;
  const fieldKeys = [...new Set((Array.isArray(denial?.fieldKeys) ? denial.fieldKeys : [])
    .map((fieldKey) => String(fieldKey || ""))
    .filter((fieldKey) => personnelFieldKeys.has(fieldKey)))];
  (await auditPortal(
    portalActorId(session),
    "personnel-lifecycle.candidate.convert.denied",
    "candidate_conversion",
    String(operationId || ""),
    JSON.stringify({
      reason,
      route: personnelRecordDeniedRoute(request),
      fieldKeys,
    }),
  ));
}

function personnelLifecycleRouteError(error) {
  if (error instanceof PersonnelLifecycleError) {
    const status = error.kind === PERSONNEL_LIFECYCLE_ERROR_KINDS.NOT_FOUND
      ? 404
      : error.kind === PERSONNEL_LIFECYCLE_ERROR_KINDS.FORBIDDEN
        ? 403
      : error.kind === PERSONNEL_LIFECYCLE_ERROR_KINDS.CONFLICT
        ? 409
        : error.kind === PERSONNEL_LIFECYCLE_ERROR_KINDS.INTEGRITY
          ? 503
          : 400;
    throw httpError(status, error.message, error.code);
  }
  if (error?.code === "PERSISTENCE_UNIQUE_VIOLATION") {
    throw httpError(409, "Der Datensatz ist bereits vorhanden.", "PERSONNEL_LIFECYCLE_CONFLICT");
  }
  if (["PERSISTENCE_RETRYABLE_TRANSACTION", "PERSISTENCE_BUSY"].includes(error?.code)) {
    throw personnelLifecycleConcurrentChangeError();
  }
  if ([
    "PERSISTENCE_FOREIGN_KEY_VIOLATION",
    "PERSISTENCE_NOT_NULL_VIOLATION",
    "PERSISTENCE_CHECK_VIOLATION",
  ].includes(error?.code)) {
    throw httpError(
      400,
      "Die Bewerberdaten verweisen auf einen ungültigen Bereich oder verletzen eine gespeicherte Regel.",
      "PERSONNEL_LIFECYCLE_REFERENCE_INVALID",
    );
  }
  throw error;
}

function personnelCandidateEvaluationLocationIds(application) {
  return new Set([
    application?.desiredLocationId,
    ...(Array.isArray(application?.targetAreas)
      ? application.targetAreas.map((area) => area?.locationId)
      : []),
    ...(Array.isArray(application?.trialAppointments)
      ? application.trialAppointments.map((appointment) => appointment?.locationId)
      : []),
  ].map((value) => String(value || "").trim()).filter(Boolean));
}

async function personnelCandidateEligibleEvaluators(application, access, actorEmployeeNumber) {
  const users = await portalUsersForAdmin();
  const locations = personnelCandidateEvaluationLocationIds(application);
  const writeScopes = access?.allowedScopesByPermission?.[
    PERSONNEL_LIFECYCLE_PERMISSIONS.APPLICATIONS_WRITE
  ] || [];
  const actor = String(actorEmployeeNumber || "").trim();
  return users
    .filter((user) => {
      if (!user || user.employeeNumber === actor
        || !user.employeeActive || !user.configured || !user.active || !user.passwordConfigured) {
        return false;
      }
      const locationId = String(user.homeLocationId || "").trim();
      const departmentId = Number(user.preferredDepartmentId || 0) || null;
      const inApplicationTeam = Boolean(locationId && locations.has(locationId));
      const inWritableScope = access?.global === true || writeScopes.some((scope) => (
        String(scope.locationId || "") === locationId
          && (!scope.departmentId || Number(scope.departmentId) === departmentId)
      ));
      const otherBranchManager = user.role === "manager";
      return otherBranchManager || (inApplicationTeam && inWritableScope);
    })
    .map((user) => ({
      employeeNumber: user.employeeNumber,
      fullName: user.fullName || user.nickname || user.employeeNumber,
      role: user.role,
      roleName: user.roleName || (user.role === "manager" ? "Filialleitung" : "Mitarbeiter"),
      homeLocationId: user.homeLocationId || "",
      preferredDepartmentId: user.preferredDepartmentId || null,
      group: locations.has(String(user.homeLocationId || "")) ? "team" : "manager",
    }))
    .sort((left, right) => (
      String(left.group).localeCompare(String(right.group))
        || String(left.fullName).localeCompare(String(right.fullName), "de-AT", {
          numeric: true,
          sensitivity: "base",
        })
    ));
}

const PERSONNEL_LIFECYCLE_APPLICATION_UPDATE_FIELDS = new Set([
  "revision",
  "desiredPositionId",
  "desiredLocationId",
  "desiredDepartmentId",
  "desiredWeeklyMinutes",
  "desiredWeeklyHours",
  "availableFrom",
  "ownerEmployeeNumber",
  "retentionDueAt",
  "desiredRoleTitle",
  "employmentType",
  "source",
  "internalRating",
  "internalNotes",
  "communicationNotes",
  "competencyRatings",
  "targetAreas",
  "trialAppointments",
  "tags",
]);
const PERSONNEL_LIFECYCLE_LOCAL_APPLICATION_UPDATE_FIELDS = new Set([
  "revision",
  "desiredPositionId",
  "desiredWeeklyMinutes",
  "desiredWeeklyHours",
  "availableFrom",
  "desiredRoleTitle",
  "employmentType",
  "competencyRatings",
  "targetAreas",
  "trialAppointments",
]);
const PERSONNEL_LIFECYCLE_CONFIDENTIAL_APPLICATION_FIELDS = new Set([
  "ownerEmployeeNumber",
  "retentionDueAt",
  "source",
  "internalRating",
  "internalNotes",
  "communicationNotes",
  "tags",
]);
const PERSONNEL_LIFECYCLE_LOCAL_CANDIDATE_CREATE_FIELDS = new Set([
  "dataProcessingAuthorizationConfirmed",
  "profile",
  "application",
]);
const PERSONNEL_LIFECYCLE_LOCAL_CANDIDATE_PROFILE_CREATE_FIELDS = new Set([
  "firstName",
  "lastName",
  "email",
  "phone",
  "address",
  "birthDate",
  "citizenships",
]);
const PERSONNEL_LIFECYCLE_LOCAL_APPLICATION_CREATE_FIELDS = new Set([
  "desiredPositionId",
  "desiredLocationId",
  "desiredDepartmentId",
  "desiredWeeklyMinutes",
  "desiredWeeklyHours",
  "availableFrom",
  "desiredRoleTitle",
  "employmentType",
  "competencyRatings",
  "targetAreas",
  "trialAppointments",
]);
const PERSONNEL_LIFECYCLE_CANDIDATE_CREATE_AUDIT_FIELD_KEYS = new Set([
  "root",
  "profile",
  "application",
  "application.desiredLocationId",
  "application.desiredDepartmentId",
]);

function personnelLifecyclePlainObject(value) {
  return Boolean(value && typeof value === "object" && !Array.isArray(value));
}

function personnelLifecycleStructuredApplicationScopes(submitted) {
  const scopes = [];
  for (const field of ["targetAreas", "trialAppointments"]) {
    if (!Object.prototype.hasOwnProperty.call(submitted, field)) continue;
    if (!Array.isArray(submitted[field])) {
      throw httpError(400, "Die Bewerbungsbereiche sind ungültig.", "PERSONNEL_LIFECYCLE_INVALID");
    }
    for (const entry of submitted[field]) {
      if (!personnelLifecyclePlainObject(entry)) {
        throw httpError(400, "Ein Bewerbungsbereich ist ungültig.", "PERSONNEL_LIFECYCLE_INVALID");
      }
      const locationId = String(entry.locationId || "").trim();
      const departmentId = entry.departmentId === null || entry.departmentId === undefined
          || entry.departmentId === ""
        ? null
        : Number(entry.departmentId);
      if (!locationId || (departmentId !== null
        && (!Number.isSafeInteger(departmentId) || departmentId <= 0))) {
        throw httpError(400, "Ein Bewerbungsbereich ist ungültig.", "PERSONNEL_LIFECYCLE_INVALID");
      }
      scopes.push({ field, locationId, departmentId });
    }
  }
  return scopes;
}

async function assertPersonnelLifecycleStructuredApplicationScopes(
  submitted,
  accessContext,
  request,
  {
    deferUnwritableEntriesToDeltaCheck = false,
    auditScopeDenial = true,
  } = {},
) {
  const scopes = personnelLifecycleStructuredApplicationScopes(submitted);
  if (!scopes.length) return;
  const { access, session } = accessContext;
  for (const scope of scopes) {
    const accessScope = {
      desiredLocationId: scope.locationId,
      desiredDepartmentId: scope.departmentId,
    };
    const writable = access.global || (access.canReadApplication(accessScope)
      && access.canWriteApplication(accessScope));
    // Only the lifecycle service can compare the protected current payload transactionally.
    // Deferral does not authorize the entry; any non-identical foreign delta is rejected there.
    if (!writable && !deferUnwritableEntriesToDeltaCheck) {
      if (auditScopeDenial) {
        (await auditPersonnelLifecycleAccessDenied(
          session,
          request,
          "PERSONNEL_LIFECYCLE_STRUCTURED_SCOPE_DENIED",
          PERSONNEL_LIFECYCLE_PERMISSIONS.APPLICATIONS_WRITE,
        ));
      }
      throw httpError(
        403,
        "Schnuppertermine und Zielfilialen dürfen nur im freigegebenen eigenen Bereich erfasst werden.",
        "PERSONNEL_LIFECYCLE_STRUCTURED_SCOPE_DENIED",
      );
    }
    scope.writable = writable;
  }
  const [locations, departments] = await Promise.all([
    organizationPersonnelRepository.listLocations(false),
    organizationPersonnelRepository.listDepartments(false),
  ]);
  for (const scope of scopes) {
    if (!scope.writable) continue;
    if (!locations.some((entry) => String(entry.id || "") === scope.locationId
      && entry.active !== false && Number(entry.active) !== 0)) {
      throw httpError(
        400,
        "Eine ausgewählte Filiale ist nicht aktiv.",
        "PERSONNEL_LIFECYCLE_REFERENCE_INVALID",
      );
    }
    if (scope.departmentId !== null && !departments.some((entry) => (
      Number(entry.id) === scope.departmentId
        && String(entry.location_id || entry.locationId || "") === scope.locationId
        && entry.active !== false
        && Number(entry.active) !== 0
    ))) {
      throw httpError(
        400,
        "Eine ausgewählte Abteilung ist nicht aktiv oder gehört nicht zur Filiale.",
        "PERSONNEL_LIFECYCLE_REFERENCE_INVALID",
      );
    }
  }
}

async function auditPersonnelLifecycleCandidateCreateDenied(
  accessContext,
  request,
  reason,
  fieldKeys = [],
) {
  const safeFieldKeys = [...new Set((Array.isArray(fieldKeys) ? fieldKeys : [])
    .map((field) => String(field || "").trim())
    .filter((field) => PERSONNEL_LIFECYCLE_CANDIDATE_CREATE_AUDIT_FIELD_KEYS.has(field)))].sort();
  (await auditPortal(
    accessContext.session.employeeNumber,
    "personnel-lifecycle.candidate.create.denied",
    "candidate",
    "new",
    JSON.stringify({
      reason: String(reason || "PERSONNEL_LIFECYCLE_CREATE_DENIED").slice(0, 120),
      route: personnelRecordDeniedRoute(request),
      fieldKeys: safeFieldKeys,
    }),
  ));
}

async function localPersonnelLifecycleCandidateCreateInput(request, accessContext) {
  const submitted = request.body;
  if (!personnelLifecyclePlainObject(submitted)) {
    throw httpError(400, "Bitte gültige Bewerberdaten übermitteln.", "PERSONNEL_LIFECYCLE_INVALID");
  }
  const unknownRootFields = Object.keys(submitted)
    .filter((field) => !PERSONNEL_LIFECYCLE_LOCAL_CANDIDATE_CREATE_FIELDS.has(field));
  if (unknownRootFields.length) {
    (await auditPersonnelLifecycleCandidateCreateDenied(
      accessContext,
      request,
      "PERSONNEL_LIFECYCLE_LOCAL_FIELD_FORBIDDEN",
      ["root"],
    ));
    throw httpError(
      403,
      "Die Filialleitung darf bei der Bewerberanlage nur die vorgesehenen Stammdaten und die erste Bewerbung erfassen.",
      "PERSONNEL_LIFECYCLE_LOCAL_FIELD_FORBIDDEN",
    );
  }
  const profile = submitted.profile;
  if (!personnelLifecyclePlainObject(profile)) {
    throw httpError(400, "Bitte gültige Bewerberstammdaten übermitteln.", "PERSONNEL_LIFECYCLE_INVALID");
  }
  const forbiddenProfileFields = Object.keys(profile)
    .filter((field) => !PERSONNEL_LIFECYCLE_LOCAL_CANDIDATE_PROFILE_CREATE_FIELDS.has(field));
  if (forbiddenProfileFields.length) {
    (await auditPersonnelLifecycleCandidateCreateDenied(
      accessContext,
      request,
      "PERSONNEL_LIFECYCLE_LOCAL_PROFILE_FIELD_FORBIDDEN",
      ["profile"],
    ));
    throw httpError(
      403,
      "Die Filialleitung darf bei der Anlage nur die vorgesehenen Bewerberstammdaten erfassen.",
      "PERSONNEL_LIFECYCLE_LOCAL_PROFILE_FIELD_FORBIDDEN",
    );
  }
  const application = submitted.application;
  if (!personnelLifecyclePlainObject(application)) {
    throw httpError(
      400,
      "Die Filialleitung muss bei der Anlage eine erste Bewerbung zuordnen.",
      "PERSONNEL_LIFECYCLE_INITIAL_APPLICATION_REQUIRED",
    );
  }
  const forbiddenApplicationFields = Object.keys(application)
    .filter((field) => !PERSONNEL_LIFECYCLE_LOCAL_APPLICATION_CREATE_FIELDS.has(field));
  if (forbiddenApplicationFields.length) {
    (await auditPersonnelLifecycleCandidateCreateDenied(
      accessContext,
      request,
      "PERSONNEL_LIFECYCLE_LOCAL_APPLICATION_FIELD_FORBIDDEN",
      ["application"],
    ));
    throw httpError(
      403,
      "Die Filialleitung darf keine vertraulichen oder internen Bewerbungsfelder erfassen.",
      "PERSONNEL_LIFECYCLE_LOCAL_APPLICATION_FIELD_FORBIDDEN",
    );
  }
  const desiredLocationId = String(application.desiredLocationId || "").trim();
  if (!desiredLocationId) {
    throw httpError(
      400,
      "Für die erste Bewerbung muss der eigene Standort ausgewählt werden.",
      "PERSONNEL_LIFECYCLE_LOCATION_REQUIRED",
    );
  }
  const desiredDepartmentIdValue = application.desiredDepartmentId;
  const desiredDepartmentId = desiredDepartmentIdValue === null
      || desiredDepartmentIdValue === undefined
      || desiredDepartmentIdValue === ""
    ? null
    : Number(desiredDepartmentIdValue);
  if (desiredDepartmentId !== null
    && (!Number.isSafeInteger(desiredDepartmentId) || desiredDepartmentId <= 0)) {
    throw httpError(400, "Die ausgewählte Abteilung ist ungültig.", "PERSONNEL_LIFECYCLE_INVALID");
  }
  const scope = { desiredLocationId, desiredDepartmentId };
  if (!accessContext.access.canCreateCandidate(scope)
    || !accessContext.access.canReadApplication(scope)
    || !accessContext.access.canWriteApplication(scope)) {
    (await auditPersonnelLifecycleCandidateCreateDenied(
      accessContext,
      request,
      "PERSONNEL_LIFECYCLE_CREATE_SCOPE_DENIED",
      ["application.desiredLocationId", ...(desiredDepartmentId ? ["application.desiredDepartmentId"] : [])],
    ));
    throw httpError(
      403,
      "Der Bewerber darf nur im eigenen, für Bewerbungen freigegebenen Standort angelegt werden.",
      "PERSONNEL_LIFECYCLE_CREATE_SCOPE_DENIED",
    );
  }
  const [locations, departments] = await Promise.all([
    organizationPersonnelRepository.listLocations(false),
    organizationPersonnelRepository.listDepartments(false),
  ]);
  const location = locations.find((entry) => (
    String(entry.id || "") === desiredLocationId && entry.active !== false && Number(entry.active) !== 0
  ));
  if (!location) {
    throw httpError(
      400,
      "Der ausgewählte Standort ist nicht aktiv.",
      "PERSONNEL_LIFECYCLE_REFERENCE_INVALID",
    );
  }
  if (desiredDepartmentId !== null) {
    const department = departments.find((entry) => (
      Number(entry.id) === desiredDepartmentId
        && String(entry.location_id || entry.locationId || "") === desiredLocationId
        && entry.active !== false
        && Number(entry.active) !== 0
    ));
    if (!department) {
      throw httpError(
        400,
        "Die ausgewählte Abteilung ist nicht aktiv oder gehört nicht zum ausgewählten Standort.",
        "PERSONNEL_LIFECYCLE_REFERENCE_INVALID",
      );
    }
  }
  await assertPersonnelLifecycleStructuredApplicationScopes(
    application,
    accessContext,
    request,
  );
  const sanitizedApplication = {};
  for (const field of PERSONNEL_LIFECYCLE_LOCAL_APPLICATION_CREATE_FIELDS) {
    if (!Object.prototype.hasOwnProperty.call(application, field)) continue;
    if (field === "desiredLocationId") sanitizedApplication[field] = desiredLocationId;
    else if (field === "desiredDepartmentId") {
      if (desiredDepartmentId !== null) sanitizedApplication[field] = desiredDepartmentId;
    } else sanitizedApplication[field] = application[field];
  }
  const sanitizedProfile = {};
  for (const field of PERSONNEL_LIFECYCLE_LOCAL_CANDIDATE_PROFILE_CREATE_FIELDS) {
    if (!Object.prototype.hasOwnProperty.call(profile, field)) continue;
    if (field === "address") {
      const address = personnelLifecyclePlainObject(profile.address) ? profile.address : {};
      sanitizedProfile.address = Object.fromEntries(["postalCode", "city"]
        .filter((key) => Object.prototype.hasOwnProperty.call(address, key))
        .map((key) => [key, address[key]]));
    } else sanitizedProfile[field] = profile[field];
  }
  return {
    dataProcessingAuthorizationConfirmed: submitted.dataProcessingAuthorizationConfirmed,
    profile: sanitizedProfile,
    application: sanitizedApplication,
  };
}

async function assertPersonnelLifecycleApplicationInput(
  request,
  accessContext,
  { statusOnly = false, deferStructuredScopeDeltaCheck = false } = {},
) {
  const submitted = request.body;
  if (!submitted || typeof submitted !== "object" || Array.isArray(submitted)) {
    throw httpError(400, "Bitte gültige Bewerbungsdaten übermitteln.", "PERSONNEL_LIFECYCLE_INVALID");
  }
  const allowed = statusOnly
    ? new Set(["status", "reason", "revision"])
    : PERSONNEL_LIFECYCLE_APPLICATION_UPDATE_FIELDS;
  const unknown = Object.keys(submitted).filter((key) => !allowed.has(key));
  if (unknown.length) {
    throw httpError(400, "Die Bewerbungsdaten enthalten unbekannte Felder.", "PERSONNEL_LIFECYCLE_INVALID");
  }
  const { access, session } = accessContext;
  if (!access.global) {
    const localAllowed = statusOnly
      ? allowed
      : PERSONNEL_LIFECYCLE_LOCAL_APPLICATION_UPDATE_FIELDS;
    const forbidden = Object.keys(submitted).filter((key) => !localAllowed.has(key));
    if (forbidden.length) {
      (await auditPersonnelLifecycleAccessDenied(
        session,
        request,
        "PERSONNEL_LIFECYCLE_LOCAL_FIELD_FORBIDDEN",
        PERSONNEL_LIFECYCLE_PERMISSIONS.APPLICATIONS_WRITE,
      ));
      throw httpError(
        403,
        "Standort- und Abteilungsleitungen dürfen nur strukturierte Bewerbungsfelder und den Status bearbeiten.",
        "PERSONNEL_LIFECYCLE_LOCAL_FIELD_FORBIDDEN",
      );
    }
    await assertPersonnelLifecycleStructuredApplicationScopes(
      submitted,
      accessContext,
      request,
      { deferUnwritableEntriesToDeltaCheck: deferStructuredScopeDeltaCheck },
    );
    return;
  }
  const requestedFields = Object.keys(submitted);
  const changesScope = requestedFields.some((key) => (
    key === "desiredLocationId" || key === "desiredDepartmentId"
      || key === "targetAreas" || key === "trialAppointments"
  ));
  if (changesScope && !access.canWriteCandidates) {
    (await auditPersonnelLifecycleAccessDenied(
      session,
      request,
      "PERSONNEL_LIFECYCLE_SCOPE_CHANGE_PERMISSION_REQUIRED",
      PERSONNEL_LIFECYCLE_PERMISSIONS.CANDIDATES_WRITE,
    ));
    throw httpError(
      403,
      "Für eine Änderung des Bewerbungsbereichs fehlt das zentrale Bewerberrecht.",
      "PERSONNEL_LIFECYCLE_SCOPE_CHANGE_PERMISSION_REQUIRED",
    );
  }
  const writesConfidential = requestedFields.some((key) => (
    PERSONNEL_LIFECYCLE_CONFIDENTIAL_APPLICATION_FIELDS.has(key)
  ));
  if (writesConfidential && !access.canWriteConfidential) {
    (await auditPersonnelLifecycleAccessDenied(
      session,
      request,
      "PERSONNEL_LIFECYCLE_CONFIDENTIAL_PERMISSION_REQUIRED",
      PERSONNEL_LIFECYCLE_PERMISSIONS.CONFIDENTIAL_WRITE,
    ));
    throw httpError(
      403,
      "Für vertrauliche Bewerbungsfelder fehlt das gesonderte Schreibrecht.",
      "PERSONNEL_LIFECYCLE_CONFIDENTIAL_PERMISSION_REQUIRED",
    );
  }
  await assertPersonnelLifecycleStructuredApplicationScopes(
    submitted,
    accessContext,
    request,
  );
}

async function auditPersonnelLifecycleScopedNotFound(accessContext, request, error) {
  if (!accessContext?.access?.global
    && error instanceof PersonnelLifecycleError
    && error.kind === PERSONNEL_LIFECYCLE_ERROR_KINDS.NOT_FOUND) {
    (await auditPersonnelLifecycleAccessDenied(
      accessContext.session,
      request,
      "PERSONNEL_LIFECYCLE_SCOPED_NOT_FOUND",
      PERSONNEL_LIFECYCLE_PERMISSIONS.CANDIDATES_READ,
    ));
  }
}

const PERSONNEL_LIFECYCLE_OFFBOARDING_FAMILY_TITLES = Object.freeze({
  hr_contract_end: "Vertragsende und Personaladministration",
  communication_release_information: "Kommunikationsfreigabe und Information",
  accounts_permissions: "Konten und Berechtigungen",
  work_access_assets: "Arbeitszugänge und Betriebsmittel",
  handover_open_responsibilities: "Übergabe und offene Verantwortungen",
  closing_documents_follow_up: "Abschlussdokumente und Nachbearbeitung",
});

function personnelLifecycleOffboardingSubjectScope(subject) {
  if (!subject || subject.subject_type !== "employee"
    || subject.employee_active !== 1
    || !subject.location_id
    || subject.location_active !== 1) {
    throw personnelProfileNotFound();
  }
  const departmentId = subject.department_id === null
    || subject.department_id === undefined
    ? null
    : Number(subject.department_id);
  if (departmentId !== null) {
    if (!Number.isSafeInteger(departmentId) || departmentId < 1
      || subject.department_active !== 1
      || String(subject.department_location_id || "") !== String(subject.location_id)) {
      throw httpError(
        503,
        "Der Organisationsbereich des Offboardings ist widersprüchlich.",
        "PERSONNEL_LIFECYCLE_OFFBOARDING_SCOPE_INTEGRITY_FAILED",
      );
    }
  }
  return Object.freeze({
    type: departmentId === null ? "location" : "department",
    locationId: String(subject.location_id),
    departmentId,
  });
}

function personnelLifecycleOffboardingCandidatePublicValue(row) {
  const actorId = String(row?.employee_number || "").trim();
  const displayName = String(row?.full_name || actorId).trim();
  const role = String(row?.role || "").trim();
  const roleLabel = builtinPortalRoles.find(({ id }) => id === role)?.name || role;
  if (!actorId || !displayName || !roleLabel) return null;
  return Object.freeze({ actorId, displayName, roleLabel });
}

async function personnelLifecycleOffboardingPreparationPackages(employeeNumber, scope) {
  const recipients = await customProcessRepository.listRecipientCandidates();
  if (!Array.isArray(recipients)) {
    throw httpError(
      503,
      "Die Offboarding-Empfängerliste konnte nicht sicher geprüft werden.",
      "PERSONNEL_LIFECYCLE_OFFBOARDING_RECIPIENT_INTEGRITY_FAILED",
    );
  }
  return Object.freeze(PERSONNEL_LIFECYCLE_OFFBOARDING_FAMILY_DEFINITIONS.map((definition) => {
    const candidates = recipients.flatMap((recipient) => {
      if (!personnelLifecycleOffboardingRecipientEligible(
        recipient,
        scope,
        employeeNumber,
        definition.recipientClass,
      )) return [];
      const candidate = personnelLifecycleOffboardingCandidatePublicValue(recipient);
      return candidate ? [candidate] : [];
    }).sort((left, right) => left.displayName.localeCompare(
      right.displayName,
      "de-AT",
      { sensitivity: "base" },
    ) || left.actorId.localeCompare(right.actorId));
    return Object.freeze({
      familyCode: definition.familyCode,
      title: PERSONNEL_LIFECYCLE_OFFBOARDING_FAMILY_TITLES[definition.familyCode],
      recipientClass: definition.recipientClass,
      candidates: Object.freeze(candidates),
    });
  }));
}

function personnelLifecycleOffboardingAllowedActions(projection, accessContext) {
  const state = projection.state;
  const lifecycleAccess = accessContext.lifecycleAccess;
  const timeCritical = projection.urgency?.mode === "time_critical";
  const approved = projection.urgency?.approved === true;
  const allComplete = projection.families.every(({ runtimeStatus }) => (
    runtimeStatus === "complete"
  ));
  return Object.freeze({
    approveTimeCritical: state === "internally_prepared"
      && timeCritical
      && !approved
      && accessContext.canApproveException === true,
    releaseCommunication: state === "internally_prepared"
      && (!timeCritical || approved)
      && accessContext.canReleaseCommunication === true,
    confirmInformation: state === "communication_released"
      && accessContext.canConfirmInformation === true,
    activate: state === "employee_informed" && accessContext.canExecute === true,
    cancel: [
      "internally_prepared",
      "communication_released",
      "employee_informed",
      "active",
    ].includes(state)
      && accessContext.canClose === true
      && (state === "internally_prepared"
        ? lifecycleAccess.canPrepareOffboarding === true
        : lifecycleAccess.canReleaseOffboardingCommunication === true),
    close: state === "active" && allComplete && accessContext.canClose === true,
  });
}

function personnelLifecycleOffboardingProfileCase(
  projection,
  accessContext,
  expectedEmployeeNumber,
) {
  const confidential = projection.case;
  if (!confidential
    || confidential.employeeNumber !== expectedEmployeeNumber
    || !Array.isArray(projection.families)
    || projection.families.length !== PERSONNEL_LIFECYCLE_OFFBOARDING_FAMILY_DEFINITIONS.length) {
    throw httpError(
      503,
      "Die vertrauliche Offboarding-Projektion ist widersprüchlich.",
      "PERSONNEL_LIFECYCLE_OFFBOARDING_PROJECTION_INTEGRITY_FAILED",
    );
  }
  const candidatesByFamily = new Map(
    projection.families.map(({ familyCode, candidates }) => [familyCode, candidates]),
  );
  const packages = projection.families.map((family) => {
    const assignee = (candidatesByFamily.get(family.familyCode) || [])
      .find(({ actorId }) => actorId === family.assigneeActorId);
    return Object.freeze({
      familyCode: family.familyCode,
      title: family.title,
      recipientClass: family.recipientClass,
      assigneeActorId: family.assigneeActorId,
      assigneeDisplayName: assignee?.displayName || family.assigneeActorId,
      orderId: family.orderId,
      status: family.runtimeStatus,
      dueAt: null,
    });
  });
  return Object.freeze({
    caseId: confidential.caseId,
    employeeNumber: confidential.employeeNumber,
    state: projection.state,
    revision: projection.revision,
    responsibleActorId: projection.responsibleActorId,
    createdAt: projection.createdAt,
    updatedAt: projection.updatedAt,
    referenceTimes: Object.freeze({
      plannedExitAt: confidential.plannedExitAt,
      lastWorkingDay: confidential.lastWorkingDay,
      legalExitDate: confidential.legalExitDate,
      accessBlockAt: confidential.accessBlockAt,
    }),
    urgency: Object.freeze({
      mode: projection.urgency.mode,
      exceptionReasonCode: projection.urgency.exceptionReason?.code || null,
      followUpDueAt: projection.urgency.followUpDueAt || null,
      approved: projection.urgency.approved === true,
    }),
    confidential: Object.freeze({
      exitReasonCode: confidential.exitReasonCode,
      exitReasonNote: confidential.exitReasonNote,
      hrNote: confidential.hrNote || "",
      documentReferenceIds: Object.freeze([...(confidential.documentReferenceIds || [])]),
    }),
    packages: Object.freeze(packages),
    allowedActions: personnelLifecycleOffboardingAllowedActions(projection, accessContext),
  });
}

function setPersonnelLifecycleOffboardingNoStore(response) {
  response.setHeader("Cache-Control", "no-store");
  response.setHeader("Pragma", "no-cache");
}

function sendPersonnelLifecycleOffboardingJson(response, payload, status = 200) {
  setPersonnelLifecycleOffboardingNoStore(response);
  response.statusCode = status;
  response.setHeader("Content-Type", "application/json; charset=utf-8");
  response.removeHeader("ETag");
  response.end(JSON.stringify(payload));
}

function sendPersonnelLifecycleAutomationJson(response, payload) {
  setPersonnelLifecycleOffboardingNoStore(response);
  response.statusCode = 200;
  response.setHeader("Content-Type", "application/json; charset=utf-8");
  response.removeHeader("ETag");
  response.end(JSON.stringify(payload));
}

function sendPersonnelLifecycleEditorJson(response, payload, status = 200) {
  setPersonnelLifecycleOffboardingNoStore(response);
  response.statusCode = status;
  response.setHeader("Content-Type", "application/json; charset=utf-8");
  response.removeHeader("ETag");
  response.end(JSON.stringify(payload));
}

function personnelLifecycleEditorRouteError(error) {
  if (error instanceof PersonnelLifecycleEditorContractError) {
    throw httpError(
      400,
      "Der O8-Workflow-Entwurf ist strukturell ungültig.",
      error.code || "O8_VALUE_INVALID",
    );
  }
  throw error;
}

function personnelLifecycleAutomationCanonicalScope(value) {
  const locationId = String(value?.locationId ?? value?.location_id ?? "").trim();
  const rawDepartmentId = value?.departmentId ?? value?.department_id ?? null;
  const hasDepartment = rawDepartmentId !== null
    && rawDepartmentId !== undefined
    && rawDepartmentId !== ""
    && rawDepartmentId !== 0
    && rawDepartmentId !== "0";
  const departmentId = hasDepartment ? Number(rawDepartmentId) : null;
  if (!locationId || locationId.length > 80 || locationId.includes("\0")
    || (hasDepartment && (!Number.isSafeInteger(departmentId) || departmentId < 1))) {
    throw httpError(
      503,
      "Der Organisationsbereich der O7-Aufgabenvorschau ist widersprüchlich.",
      "PERSONNEL_LIFECYCLE_AUTOMATION_SCOPE_INTEGRITY_FAILED",
    );
  }
  return Object.freeze(hasDepartment
    ? { type: "department", id: String(departmentId) }
    : { type: "location", id: locationId });
}

function personnelLifecycleAutomationOnboardingTask(item) {
  const runId = String(item?.runId || "").trim();
  const stepId = String(item?.stepId || "").trim();
  const title = String(item?.step?.title || "").trim();
  if (!runId || !stepId || !title) {
    throw httpError(
      503,
      "Die freigegebene Onboarding-Aufgabe ist für O7 widersprüchlich.",
      "PERSONNEL_LIFECYCLE_AUTOMATION_TASK_INTEGRITY_FAILED",
    );
  }
  return Object.freeze({
    source: "onboarding",
    runId,
    processVersionId: null,
    stepId,
    title,
    status: "active",
    scope: personnelLifecycleAutomationCanonicalScope(item.scope),
    referenceKind: null,
    referenceDate: null,
    responsibilityState: "unknown",
    policyBinding: null,
  });
}

function personnelLifecycleAutomationOffboardingTask(item) {
  const projected = personnelLifecycleOffboardingTaskProjection(item);
  const status = String(projected.status || "").trim();
  if (!["pending", "active"].includes(status)) {
    throw httpError(
      503,
      "Die freigegebene Offboarding-Aufgabe ist für O7 widersprüchlich.",
      "PERSONNEL_LIFECYCLE_AUTOMATION_TASK_INTEGRITY_FAILED",
    );
  }
  return Object.freeze({
    source: "offboarding",
    runId: projected.runId,
    processVersionId: null,
    stepId: projected.stepId,
    title: projected.title,
    status,
    scope: personnelLifecycleAutomationCanonicalScope(projected),
    referenceKind: null,
    referenceDate: null,
    responsibilityState: "unknown",
    policyBinding: null,
  });
}

function personnelLifecycleOffboardingBody(request, forbiddenFields = []) {
  const body = request.body;
  if (!body || typeof body !== "object" || Array.isArray(body)
    || ![Object.prototype, null].includes(Object.getPrototypeOf(body))
    || forbiddenFields.some((field) => Object.hasOwn(body, field))) {
    throw httpError(
      400,
      "Der vertrauliche Offboarding-Auftrag ist ungültig.",
      "PERSONNEL_LIFECYCLE_OFFBOARDING_INPUT_INVALID",
    );
  }
  return body;
}

function personnelLifecycleOffboardingTaskCompletionBody(request) {
  const body = personnelLifecycleOffboardingBody(request, [
    "actorId",
    "employeeNumber",
    "responsibleActorId",
    "caseId",
    "runId",
    "stepId",
  ]);
  const keys = Reflect.ownKeys(body);
  if (!Object.hasOwn(body, "operationId")
    || !Object.hasOwn(body, "action")
    || keys.some((key) => !["operationId", "action", "evidenceReference"].includes(key))
    || (Object.hasOwn(body, "evidenceReference") && body.evidenceReference !== null)) {
    throw httpError(
      400,
      "O5 erlaubt keinen Nachweistext oder freien Abschlussinhalt.",
      "PERSONNEL_LIFECYCLE_OFFBOARDING_TASK_INPUT_INVALID",
    );
  }
  return Object.freeze({ operationId: body.operationId, action: body.action });
}

function personnelLifecycleOffboardingTaskProjection(item) {
  const runId = String(item?.runId || "").trim();
  const stepId = String(item?.stepId || "").trim();
  const task = item?.task;
  const definition = PERSONNEL_LIFECYCLE_OFFBOARDING_FAMILY_DEFINITIONS.find(
    (entry) => entry.stepId === stepId,
  );
  if (!runId || !stepId || !definition || !task
    || typeof task !== "object" || Array.isArray(task)) {
    throw httpError(
      503,
      "Die freigegebene Offboarding-Aufgabe ist widersprüchlich.",
      "PERSONNEL_LIFECYCLE_OFFBOARDING_TASK_INTEGRITY_FAILED",
    );
  }
  const title = String(
    task.title
      || task.action
      || task.payrollAction
      || PERSONNEL_LIFECYCLE_OFFBOARDING_FAMILY_TITLES[definition.familyCode]
      || "Offboarding-Auftrag",
  ).trim();
  return Object.freeze({
    runId,
    stepId,
    projection: definition.projection,
    title,
    ...task,
  });
}

async function handlePersonnelLifecycleOffboardingCaseAction(
  request,
  response,
  { action, serviceMethod },
) {
  const accessContext = (await requirePersonnelLifecycleOffboardingActionAccess(request, action));
  setPersonnelLifecycleOffboardingNoStore(response);
  const body = personnelLifecycleOffboardingBody(request, [
    "actorId",
    "employeeNumber",
    "responsibleActorId",
    "caseId",
  ]);
  try {
    const result = await requirePersonnelLifecycleOffboardingService()[serviceMethod](
      portalActorId(accessContext.session),
      { ...body, caseId: request.params.caseId },
      { access: accessContext.lifecycleAccess },
    );
    if (result.replayed) response.setHeader("Idempotency-Replayed", "true");
    sendPersonnelLifecycleOffboardingJson(response, { offboardingCase: result });
  } catch (error) {
    if (error instanceof PersonnelLifecycleOffboardingServiceError
      && [
        PERSONNEL_LIFECYCLE_OFFBOARDING_SERVICE_ERROR_KINDS.FORBIDDEN,
        PERSONNEL_LIFECYCLE_OFFBOARDING_SERVICE_ERROR_KINDS.NOT_FOUND,
      ].includes(error.kind)) {
      (await auditPersonnelLifecycleAccessDenied(
        accessContext.session,
        request,
        error.code,
        PERSONNEL_LIFECYCLE_CASE_PERMISSIONS.OFFBOARDING_CONFIDENTIAL_READ,
      ));
    }
    personnelLifecycleOffboardingRouteError(error);
  }
}

function personnelLifecycleOffboardingPreparationFromFamilies(families, available) {
  return Object.freeze({
    available: available === true
      && families.every(({ candidates }) => candidates.length > 0),
    packages: Object.freeze(families.map((family) => Object.freeze({
      familyCode: family.familyCode,
      title: PERSONNEL_LIFECYCLE_OFFBOARDING_FAMILY_TITLES[family.familyCode]
        || family.title,
      recipientClass: family.recipientClass,
      candidates: Object.freeze([...(family.candidates || [])]),
    }))),
  });
}

