app.put("/api/portal/v1/personnel-lifecycle/candidates/:candidateId/applications/:applicationId/trial-appointments/:trialAppointmentId", async (request, response) => {
  const accessContext = (await requirePersonnelLifecycleAccess(request, { action: "applicationWrite" }));
  const { session, access, capabilities } = accessContext;
  try {
    const service = requirePersonnelLifecycleService();
    const detail = await service.getCandidate(request.params.candidateId, { access });
    const currentApplication = detail?.applications?.find((application) => (
      application.id === String(request.params.applicationId || "")
        && access.canWriteApplication(application)
    ));
    const currentAppointment = currentApplication?.trialAppointments?.find((appointment) => (
      appointment.id === String(request.params.trialAppointmentId || "")
    ));
    const currentAppointmentScope = currentAppointment ? {
      desiredLocationId: currentAppointment.locationId,
      desiredDepartmentId: currentAppointment.departmentId ?? null,
    } : null;
    if (!currentApplication || !currentAppointment || (!access.global
      && (!access.canReadApplication(currentAppointmentScope)
        || !access.canWriteApplication(currentAppointmentScope)))) {
      throw new PersonnelLifecycleError(
        "Der Schnuppertermin wurde nicht gefunden.",
        "PERSONNEL_LIFECYCLE_TRIAL_APPOINTMENT_NOT_FOUND",
        PERSONNEL_LIFECYCLE_ERROR_KINDS.NOT_FOUND,
      );
    }
    const submitted = personnelLifecyclePlainObject(request.body) ? request.body : {};
    const replacement = personnelLifecyclePlainObject(submitted.replacement)
      ? submitted.replacement
      : null;
    await assertPersonnelLifecycleStructuredApplicationScopes({
      trialAppointments: [{
        ...currentAppointment,
        ...submitted,
        locationId: submitted.locationId ?? currentAppointment.locationId,
        departmentId: Object.prototype.hasOwnProperty.call(submitted, "departmentId")
          ? submitted.departmentId
          : currentAppointment.departmentId,
      }, ...(replacement ? [{
        ...replacement,
        locationId: replacement.locationId
          ?? submitted.locationId
          ?? currentAppointment.locationId,
        departmentId: Object.prototype.hasOwnProperty.call(replacement, "departmentId")
          ? replacement.departmentId
          : (Object.prototype.hasOwnProperty.call(submitted, "departmentId")
            ? submitted.departmentId
            : currentAppointment.departmentId),
      }] : [])],
    }, accessContext, request, { auditScopeDenial: false });
    const updated = await service.updateTrialAppointment(
      request.params.candidateId,
      request.params.applicationId,
      request.params.trialAppointmentId,
      request.body || {},
      session.employeeNumber,
      { access },
    );
    const application = projectPersonnelLifecycleApplication(updated, access);
    const appointment = application.trialAppointments?.find((entry) => (
      entry.id === String(request.params.trialAppointmentId || "")
    ));
    (await auditPortal(
      session.employeeNumber,
      "personnel-lifecycle.trial-appointment.update",
      "candidate_trial_appointment",
      request.params.trialAppointmentId,
      JSON.stringify({
        revision: application.revision,
        status: appointment?.status || null,
        cancellationRecorded: Boolean(appointment?.cancelledAt),
        replacementCreated: Boolean(submitted.replacement),
      }),
    ));
    response.json({ application, capabilities });
  } catch (error) {
    if (error?.code === "PERSONNEL_LIFECYCLE_STRUCTURED_SCOPE_DENIED") {
      (await auditPersonnelLifecycleAccessDenied(
        session,
        request,
        error.code,
        PERSONNEL_LIFECYCLE_PERMISSIONS.APPLICATIONS_WRITE,
      ));
    }
    (await auditPersonnelLifecycleScopedNotFound(accessContext, request, error));
    personnelLifecycleRouteError(error);
  }
});

app.post("/api/portal/v1/personnel-lifecycle/candidates/:candidateId/applications/:applicationId/team-feedback", async (request, response) => {
  const accessContext = (await requirePersonnelLifecycleAccess(request, { action: "applicationWrite" }));
  const { session, access, capabilities } = accessContext;
  try {
    const detail = await requirePersonnelLifecycleService().getCandidate(
      request.params.candidateId,
      { access },
    );
    const application = detail?.applications?.find((entry) => (
      entry.id === String(request.params.applicationId || "")
        && access.canWriteApplication(entry)
    ));
    if (!application) {
      throw new PersonnelLifecycleError(
        "Die Bewerbung wurde nicht gefunden.",
        "PERSONNEL_LIFECYCLE_APPLICATION_NOT_FOUND",
        PERSONNEL_LIFECYCLE_ERROR_KINDS.NOT_FOUND,
      );
    }
    const employeeNumber = String(request.body?.employeeNumber || "").trim();
    const employee = (await organizationPersonnelRepository.listEmployees()).find((entry) => (
      String(entry.personnel_number || entry.employeeNumber || "") === employeeNumber
        && entry.active !== false
        && Number(entry.active) !== 0
    ));
    if (!employee) {
      throw httpError(
        400,
        "Das rückmeldende aktive Teammitglied wurde nicht gefunden.",
        "PERSONNEL_LIFECYCLE_TEAM_MEMBER_INVALID",
      );
    }
    if (!access.global) {
      const locationIds = new Set([
        application.desiredLocationId,
        ...(application.targetAreas || []).map((area) => area.locationId),
        ...(application.trialAppointments || []).map((appointment) => appointment.locationId),
      ].map((value) => String(value || "")).filter(Boolean));
      const employeeLocationId = String(employee.home_location_id || employee.homeLocationId || "");
      const employeeDepartmentId = Number(
        employee.preferred_department_id || employee.preferredDepartmentId || 0,
      ) || null;
      const feedbackScopes = access.allowedScopesByPermission?.[
        PERSONNEL_LIFECYCLE_PERMISSIONS.APPLICATIONS_WRITE
      ] || [];
      const employeeInWritableScope = feedbackScopes.some((scope) => (
        String(scope.locationId || "") === employeeLocationId
          && (!scope.departmentId || Number(scope.departmentId) === employeeDepartmentId)
      ));
      if (!locationIds.has(employeeLocationId) || !employeeInWritableScope) {
        throw httpError(
          403,
          "Teamrückmeldungen dürfen nur für Teammitglieder des freigegebenen Bewerbungsbereichs erfasst werden.",
          "PERSONNEL_LIFECYCLE_TEAM_MEMBER_SCOPE_DENIED",
        );
      }
    }
    const updated = await requirePersonnelLifecycleService().addTeamFeedback(
      detail.id,
      application.id,
      request.body || {},
      session.employeeNumber,
      { access },
    );
    const projected = projectPersonnelLifecycleApplication(updated, access);
    (await auditPortal(
      session.employeeNumber,
      "personnel-lifecycle.application.team-feedback.add",
      "candidate_application",
      application.id,
      JSON.stringify({
        candidateId: detail.id,
        employeeNumber,
        trialAppointmentLinked: Boolean(request.body?.trialAppointmentId),
        ratingProvided: request.body?.rating !== null && request.body?.rating !== undefined
          && request.body?.rating !== "",
      }),
    ));
    response.status(201).json({ application: projected, capabilities });
  } catch (error) {
    if (error?.code === "PERSONNEL_LIFECYCLE_STRUCTURED_SCOPE_DENIED") {
      (await auditPersonnelLifecycleAccessDenied(
        session,
        request,
        error.code,
        PERSONNEL_LIFECYCLE_PERMISSIONS.APPLICATIONS_WRITE,
      ));
    }
    (await auditPersonnelLifecycleScopedNotFound(accessContext, request, error));
    personnelLifecycleRouteError(error);
  }
});

