app.get("/api/portal/v1/personnel-lifecycle/candidates/:candidateId/applications/:applicationId/evaluation.pdf", async (request, response) => {
  const accessContext = (await requirePersonnelLifecycleAccess(request, { action: "read" }));
  const { session, access } = accessContext;
  try {
    const detail = await requirePersonnelLifecycleService().getCandidate(
      request.params.candidateId,
      { access },
    );
    const application = detail?.applications?.find((entry) => (
      entry.id === String(request.params.applicationId || "")
        && access.canReadApplication(entry)
    ));
    if (!detail || !application) {
      throw new PersonnelLifecycleError(
        "Die Bewerbung wurde nicht gefunden.",
        "PERSONNEL_LIFECYCLE_APPLICATION_NOT_FOUND",
        PERSONNEL_LIFECYCLE_ERROR_KINDS.NOT_FOUND,
      );
    }
    const candidateName = [detail.profile?.firstName, detail.profile?.lastName]
      .map((value) => String(value || "").trim())
      .filter(Boolean)
      .join(" ") || "Bewerbung";
    const reviewerNames = Object.fromEntries((await portalUsersForAdmin()).map((user) => ([
      user.employeeNumber,
      user.fullName || user.nickname || user.employeeNumber,
    ])));
    const generatedAt = new Date();
    const exportOptions = await candidateEvaluationPdfPreferencesForActor(session);
    const branding = candidateEvaluationPdfBrandingForActor(session, application);
    const { buffer: pdf, pageCount } = await createCandidateEvaluationPdfArtifact({
      candidateName,
      desiredRoleTitle: application.desiredRoleTitle,
      evaluationSummary: application.evaluationSummary,
      reviewerNames,
      generatedAt,
      exportOptions,
      branding,
    });
    const filename = candidateEvaluationPdfFilename(
      exportOptions,
      candidateName,
      application.desiredRoleTitle,
      generatedAt,
    );
    response.set({
      "Cache-Control": "private, no-store, max-age=0",
      Pragma: "no-cache",
      "Content-Type": "application/pdf",
      "Content-Length": String(pdf.length),
      "Content-Disposition": contentDispositionHeader(filename),
    });
    (await auditPortal(
      session.employeeNumber,
      "personnel-lifecycle.team-evaluation.pdf",
      "candidate_application",
      application.id,
      JSON.stringify({
        candidateId: detail.id,
        pageCount,
        pageMode: exportOptions.pageMode,
        orientation: exportOptions.orientation,
        applyBranding: exportOptions.applyBranding,
        includeLogo: exportOptions.includeLogo,
      }),
    ));
    response.send(pdf);
  } catch (error) {
    (await auditPersonnelLifecycleScopedNotFound(accessContext, request, error));
    if (error instanceof CandidateEvaluationPdfError) {
      const status = error.code === "CANDIDATE_EVALUATION_PDF_LOGO_INVALID" ? 422 : 409;
      throw httpError(status, error.message, error.code);
    }
    personnelLifecycleRouteError(error);
  }
});

