app.post("/api/portal/v1/personnel-lifecycle/candidates/:candidateId/applications/:applicationId/convert", async (request, response) => {
  const accessContext = (await requirePersonnelLifecycleAccess(request, { action: "convert" }));
  const { session, capabilities } = accessContext;
  const submitted = personnelLifecycleConversionInput(request.body || {});
  const candidateId = String(request.params.candidateId || "").trim();
  const applicationId = String(request.params.applicationId || "").trim();
  const requestSha256 = workRuleSha256({
    schemaVersion: 1,
    operationId: submitted.id,
    candidateId,
    applicationId,
    candidateRevision: submitted.candidateRevision,
    applicationRevision: submitted.applicationRevision,
    employee: submitted.employee,
  });
  let deferredFieldDenial = null;
  try {
    const result = await runPersonnelLifecycleSerializableMutation(() => (
      persistenceProvider.transaction(async (executor) => {
        const repositories = createApplicationRepositories(executor);
        const lifecycle = createPersonnelLifecycleService(
          repositories.personnelLifecycle,
          { protectJson, parseProtectedJson },
        );
        return lifecycle.convertCandidateInTransaction(
        candidateId,
        applicationId,
        {
          ...submitted,
          employeeNumber: submitted.employee.personnelNumber,
          requestSha256,
        },
        session.employeeNumber,
        async (employeeProposal, { candidate }) => {
          const employee = await validateEmployee({
            ...employeeProposal,
            fullName: `${candidate.profile.firstName} ${candidate.profile.lastName}`.trim(),
            active: true,
            timeConfirmationLevel: "C",
            sicknessWithoutAumEnabled: false,
          }, true, {
            repository: repositories.organizationPersonnel,
          });
          employee.timeConfirmationLevel = "C";
          employee.sicknessWithoutAumEnabled = 0;
          employee.active = 1;
          assertSessionContextScope(session, {
            locationId: employee.homeLocationId,
            departmentId: employee.preferredDepartmentId,
          });
          const personnelRecordInputValue = candidatePersonnelRecordInput(candidate.profile);
          const submittedFields = submittedPersonnelRecordFieldKeys(personnelRecordInputValue);
          (await assertPersonnelRecordContextScope(
            session,
            {
              locationId: employee.homeLocationId,
              departmentId: employee.preferredDepartmentId,
            },
            request,
            employee.personnelNumber,
            submittedFields,
          ));
          let personnelRecordMutation;
          try {
            personnelRecordMutation = await preparePersonnelRecordMutation(
              request,
              employee.personnelNumber,
              personnelRecordInputValue,
              { assumeNew: true, auditDenied: false },
            );
          } catch (error) {
            if (PERSONNEL_RECORD_FIELD_DENIAL_CODES.has(String(error?.code || ""))) {
              deferredFieldDenial = {
                error,
                reason: error.code,
                fieldKeys: error[PERSONNEL_RECORD_DENIED_FIELD_KEYS] || [],
              };
            }
            throw error;
          }
          await repositories.organizationPersonnel.insertEmployee(employee);
          await persistPersonnelRecordMutationWithRepository(
            repositories.organizationPersonnel,
            personnelRecordMutation,
            "create-from-candidate",
          );
          await repositories.organizationPersonnel.insertAudit(
            session.employeeNumber,
            "personnel-lifecycle.candidate.convert",
            "candidate_conversion",
            submitted.id,
            JSON.stringify({
              candidateId,
              applicationId,
              employeeNumber: employee.personnelNumber,
              documentTransfer: "none",
              onboarding: "deferred",
              portalAccess: "none",
            }),
          );
          return employee;
        },
        );
      }, { isolation: "serializable" })
    ));
    const application = result.candidate.applications
      .find(({ id }) => id === result.conversion.applicationId);
    if (result.replayed) response.set("Idempotency-Replayed", "true");
    response.status(result.replayed ? 200 : 201).json({
      conversion: {
        id: result.conversion.id,
        candidateId: result.conversion.candidateId,
        applicationId: result.conversion.applicationId,
        employeeNumber: result.conversion.employeeNumber,
        createdAt: result.conversion.createdAt,
        documentTransfer: "none",
        onboarding: "deferred",
      },
      candidate: {
        id: result.candidate.id,
        state: result.candidate.state,
        revision: result.candidate.revision,
      },
      application: {
        id: application.id,
        status: application.status,
        revision: application.revision,
      },
      capabilities,
      replayed: result.replayed,
    });
  } catch (error) {
    if (deferredFieldDenial?.error === error) {
      (await auditPersonnelLifecycleConversionFieldDenied(
        session,
        request,
        submitted.id,
        deferredFieldDenial,
      ));
      deferredFieldDenial = null;
    }
    if (isUniquePersistenceViolation(error)) {
      throw httpError(
        409,
        "Diese Personalnummer oder Umwandlung ist bereits vergeben.",
        "PERSONNEL_LIFECYCLE_EMPLOYEE_NUMBER_CONFLICT",
      );
    }
    personnelLifecycleRouteError(error);
  }
});

app.get("/api/portal/v1/personnel-records/:employeeNumber", async (request, response) => {
  const { session, access } = (await requirePersonnelRecordSession(request));
  const employeeNumber = String(request.params.employeeNumber || "").trim();
  await assertPersonnelRecordEmployeeScope(session, employeeNumber, request);
  const employee = await sicknessAmuManagementRepository
    .getEmployeePersonnelRecordProjection({ employeeNumber });
  if (!employee) {
    (await auditPersonnelRecordDenied(session, employeeNumber, request, "EMPLOYEE_NOT_FOUND"));
    throw httpError(404, "Das Teammitglied wurde nicht gefunden.", "EMPLOYEE_NOT_FOUND");
  }
  const protectedProfile = access.canReadPhone || access.canReadSensitive
    ? await personnelSensitiveProfile(employeeNumber) : emptyPersonnelSensitiveProfile();
  const redactedProfile = redactPersonnelSensitiveProfile(protectedProfile, access.fieldAccess);
  const personnelDocuments = access.canReadDocuments
    ? await personnelRecordDocumentRows(employeeNumber)
    : [];
  let serialized = [];
  if (access.canReadAmu) {
    let reports = await sicknessAmuManagementRepository.listAmuReportsForEmployee({
      employeeNumber,
    });
    reports = reports.filter((report) => sessionCanListAmuReport(session, report));
    const reportLookup = new Map(reports.map((report) => [Number(report.id), report]));
    serialized = (await Promise.all((await serializeAmuReports(reports, {
      includeIdentityCheck: access.canReadAmuSensitiveMetadata,
    })).map(async (report) => ({
        ...report,
        responsibility: await amuResponsibilityForActor(
          reportLookup.get(Number(report.id)),
          session,
        ),
      }))))
      .sort((left, right) => String(right.incapacity_from).localeCompare(String(left.incapacity_from)) || Number(right.id) - Number(left.id));
    if (!access.canOpenFiles) {
      for (const report of serialized) {
        report.employee_note = "";
        report.review_note = "";
        report.documents = report.documents.map(({ id, detected_mime, size, byte_size, scan_status, status, created_at }, index) => ({
          id, original_name: `Dokument ${index + 1}`, original_filename: `Dokument ${index + 1}`, detected_mime, size, byte_size,
          scan_status, status, created_at, content_access: false,
        }));
      }
    }
  }
  const sections = [access.canReadPhone ? "phone" : "", access.canReadSensitive ? "sensitive" : "",
    access.canReadDocuments ? "documents" : "", access.canReadAmu ? "amu" : ""].filter(Boolean);
  (await auditPortal(session.employeeNumber, "personnel-record.view", "employee", employeeNumber,
    JSON.stringify({ sections, documentEntries: personnelDocuments.length, amuEntries: serialized.length })));
  response.json({
    employee,
    profile: {
      phone: access.canReadPhone ? protectedProfile.phone : null,
      sensitive: access.canReadSensitive ? redactedProfile : null,
    },
    documents: personnelDocuments,
    reports: serialized,
    access,
    canOpenFiles: access.canOpenFiles,
  });
});

app.put("/api/portal/v1/personnel-records/:employeeNumber", async (request, response) => {
  const { session, access } = (await requirePersonnelRecordSession(request, { write: true }));
  const employeeNumber = String(request.params.employeeNumber || "").trim();
  await assertPersonnelRecordEmployeeScope(session, employeeNumber, request,
    submittedPersonnelRecordFieldKeys(request.body || {}));
  const employee = await sicknessAmuManagementRepository
    .getEmployeePersonnelRecordProjection({ employeeNumber });
  if (!employee) {
    (await auditPersonnelRecordDenied(session, employeeNumber, request, "EMPLOYEE_NOT_FOUND",
      submittedPersonnelRecordFieldKeys(request.body || {})));
    throw httpError(404, "Das Teammitglied wurde nicht gefunden.", "EMPLOYEE_NOT_FOUND");
  }
  const hasSensitiveInput = Object.prototype.hasOwnProperty.call(request.body || {}, "sensitive");
  const hasPhoneInput = Object.prototype.hasOwnProperty.call(request.body || {}, "phone");
  if (!hasSensitiveInput && !hasPhoneInput) {
    throw httpError(400, "Es wurden keine Personalakt-Daten übermittelt.", "PERSONNEL_RECORD_INPUT_REQUIRED");
  }
  const submittedFields = submittedPersonnelRecordFieldKeys(request.body || {});
  if (!submittedFields.length) {
    throw httpError(400, "Es wurden keine gültigen Personalakt-Daten übermittelt.", "PERSONNEL_RECORD_INPUT_REQUIRED");
  }
  (await assertPersonnelRecordFieldsWritable(request, session, access, submittedFields, employeeNumber));
  const before = await personnelSensitiveProfile(employeeNumber);
  const next = mergePersonnelSensitiveProfile(before, hasSensitiveInput ? request.body.sensitive || {} : {});
  if (hasPhoneInput) next.phone = normalizePersonnelPhone(request.body.phone);
  const changedFields = changedPersonnelProfileFields(before, next);
  if (!changedFields.length) {
    return response.json({ ok: true, changedFields: [], access });
  }
  const socialSecurityLookup = next.socialSecurityNumber
    ? personnelSensitiveLookup("social-security-number", next.socialSecurityNumber) : "";
  const protectedPayload = protectJson(next, personnelSensitiveProtectionContext({ employee_number: employeeNumber }));
  try {
    await sicknessAmuManagementRepository.upsertPersonnelSensitiveRecord({
      employeeNumber,
      socialSecurityLookup,
      protectedPayload,
      actor: session.employeeNumber,
    });
  } catch (error) {
    if (isUniquePersistenceViolation(error)) {
      throw httpError(409, "Diese SV-Nummer ist bereits einem anderen Personalakt zugeordnet.", "PERSONNEL_SOCIAL_SECURITY_DUPLICATE");
    }
    throw error;
  }
  if (personalNotificationMasterFieldsChanged(changedFields)) {
    await reconcilePersonalNotificationTargets(employeeNumber, null, session.employeeNumber);
  }
  (await auditPortal(session.employeeNumber, "personnel-record.update", "employee", employeeNumber,
    JSON.stringify({ fields: changedFields })));
  response.json({ ok: true, changedFields, access });
});

app.post("/api/portal/v1/personnel-records/:employeeNumber/documents", async (request, response) => {
  const { session, access } = (await requirePersonnelRecordSession(request, { write: true }));
  if (!access.canWriteDocuments) {
    (await auditPersonnelRecordDenied(session, request.params.employeeNumber, request,
      "PERSONNEL_DOCUMENT_WRITE_DENIED", ["documents"]));
    throw httpError(403, "Personalakt-Dokumente dürfen mit diesem Zugang nicht hinzugefügt werden.", "PERSONNEL_DOCUMENT_WRITE_DENIED");
  }
  const employeeNumber = String(request.params.employeeNumber || "").trim();
  await assertPersonnelRecordEmployeeScope(session, employeeNumber, request, ["documents"]);
  if (!await sicknessAmuManagementRepository
    .getEmployeePersonnelRecordProjection({ employeeNumber })) {
    (await auditPersonnelRecordDenied(session, employeeNumber, request, "EMPLOYEE_NOT_FOUND", ["documents"]));
    throw httpError(404, "Das Teammitglied wurde nicht gefunden.", "EMPLOYEE_NOT_FOUND");
  }
  const { fields, document } = await parsePersonnelDocumentMultipart(request);
  const documentFields = validatePersonnelDocumentFields(fields);
  const storage = requireAmuStorage();
  let stored = null;
  let committed = false;
  amuMutationInProgress += 1;
  try {
    stored = await storage.saveBuffer({
      buffer: document.buffer,
      originalName: document.originalName,
      maxBytes: 15 * 1024 * 1024,
    });
    const documentId = crypto.randomUUID();
    const protectedPayload = protectJson({
      ...documentFields,
      originalFilename: stored.originalFilename,
      detectedMime: stored.detectedMime,
      byteSize: stored.byteSize,
      sha256: stored.sha256,
      uploadedBy: session.employeeNumber,
    }, personnelRecordDocumentProtectionContext({ id: documentId, employee_number: employeeNumber }));
    const createdAt = new Date().toISOString();
    await sicknessAmuManagementRepository.transaction(async (repository) => {
      await repository.insertPersonnelDocument({
        id: documentId,
        employeeNumber,
        storageKey: stored.storageKey,
        protectedPayload,
      });
      await repository.insertPersonnelDocumentVersion({
        documentId,
        versionNumber: 1,
        storageKey: stored.storageKey,
        protectedPayload,
        createdBy: session.employeeNumber,
        createdAt,
      });
      const pointed = await repository.replacePersonnelDocumentCurrentPointer({
        id: documentId,
        employeeNumber,
        expectedCurrentVersion: 0,
        versionNumber: 1,
        storageKey: stored.storageKey,
        protectedPayload,
        updatedAt: createdAt,
      });
      if (!pointed.rowsAffected) {
        throw httpError(
          409,
          "Das Dokument wurde gleichzeitig geändert. Bitte erneut versuchen.",
          "PERSONNEL_DOCUMENT_CONCURRENT_CHANGE",
        );
      }
      await repository.insertPersonnelDocumentEvent(personnelDocumentEvent({
        documentId,
        eventType: "registered",
        actorEmployeeNumber: session.employeeNumber,
        createdAt,
      }));
      await repository.recordAudit({
        actor: session.employeeNumber,
        action: "personnel-record.document.upload",
        entityType: "personnel_record_document",
        entityId: documentId,
        detail: JSON.stringify({
          fields: ["category", "visibility", "title", "documentDate", "description", "file"],
          versionNumber: 1,
        }),
      });
    });
    committed = true;
    const created = (await personnelRecordDocumentRows(employeeNumber))
      .find((entry) => entry.id === documentId);
    response.status(201).json({ document: created, access });
  } catch (error) {
    if (!committed && stored?.storageKey) {
      try { storage.deleteBlob(stored.storageKey); } catch {}
    }
    if (error.status) throw error;
    if (error.code?.startsWith?.("AMU_")) {
      const status = error.code.includes("TOO_LARGE") || error.code.includes("LIMIT")
        ? 413 : error.code.includes("TYPE") || error.code.includes("HEIC") ? 415 : 400;
      const code = error.code.replace(/^AMU_DOCUMENT_/, "PERSONNEL_DOCUMENT_")
        .replace(/^AMU_/, "PERSONNEL_DOCUMENT_");
      throw httpError(status, error.message, code);
    }
    throw error;
  } finally {
    amuMutationInProgress = Math.max(0, amuMutationInProgress - 1);
  }
});

app.post("/api/portal/v1/personnel-records/:employeeNumber/documents/:documentId/versions", async (request, response) => {
  const { session, access } = (await requirePersonnelRecordSession(request, { write: true }));
  if (!access.canWriteDocuments) {
    (await auditPersonnelRecordDenied(session, request.params.employeeNumber, request,
      "PERSONNEL_DOCUMENT_WRITE_DENIED", ["documents"]));
    throw httpError(
      403,
      "Personalakt-Dokumente dürfen mit diesem Zugang nicht versioniert werden.",
      "PERSONNEL_DOCUMENT_WRITE_DENIED",
    );
  }
  const employeeNumber = String(request.params.employeeNumber || "").trim();
  const documentId = String(request.params.documentId || "").trim();
  await assertPersonnelRecordEmployeeScope(session, employeeNumber, request, ["documents"]);
  const current = await personnelRecordDocumentMetadata(employeeNumber, documentId);
  if (!current || Number(current.current_version || 0) < 1) {
    (await auditPersonnelRecordDenied(session, employeeNumber, request,
      "PERSONNEL_DOCUMENT_NOT_FOUND", ["documents"]));
    throw httpError(
      404,
      "Das Personalakt-Dokument wurde nicht gefunden.",
      "PERSONNEL_DOCUMENT_NOT_FOUND",
    );
  }
  const currentPayload = personnelRecordDocumentPayload(current);
  const { fields, document } = await parsePersonnelDocumentMultipart(request);
  const documentFields = personnelDocumentVersionFields(fields, currentPayload);
  const storage = requireAmuStorage();
  let stored = null;
  let committed = false;
  amuMutationInProgress += 1;
  try {
    stored = await storage.saveBuffer({
      buffer: document.buffer,
      originalName: document.originalName,
      maxBytes: 15 * 1024 * 1024,
    });
    const expectedCurrentVersion = Number(current.current_version);
    const versionNumber = expectedCurrentVersion + 1;
    const createdAt = new Date().toISOString();
    const protectedPayload = protectJson({
      ...documentFields,
      originalFilename: stored.originalFilename,
      detectedMime: stored.detectedMime,
      byteSize: stored.byteSize,
      sha256: stored.sha256,
      uploadedBy: session.employeeNumber,
    }, personnelRecordDocumentProtectionContext({ id: documentId, employee_number: employeeNumber }));
    await sicknessAmuManagementRepository.transaction(async (repository) => {
      const live = await repository.getPersonnelDocument({
        employeeNumber,
        documentId,
        activeOnly: 1,
      });
      if (!live || Number(live.current_version) !== expectedCurrentVersion) {
        throw httpError(
          409,
          "Das Dokument wurde gleichzeitig geändert. Bitte neu laden.",
          "PERSONNEL_DOCUMENT_CONCURRENT_CHANGE",
        );
      }
      await repository.insertPersonnelDocumentVersion({
        documentId,
        versionNumber,
        storageKey: stored.storageKey,
        protectedPayload,
        createdBy: session.employeeNumber,
        createdAt,
      });
      const pointed = await repository.replacePersonnelDocumentCurrentPointer({
        id: documentId,
        employeeNumber,
        expectedCurrentVersion,
        versionNumber,
        storageKey: stored.storageKey,
        protectedPayload,
        updatedAt: createdAt,
      });
      if (!pointed.rowsAffected) {
        throw httpError(
          409,
          "Das Dokument wurde gleichzeitig geändert. Bitte neu laden.",
          "PERSONNEL_DOCUMENT_CONCURRENT_CHANGE",
        );
      }
      const previousEvent = await repository.getLatestPersonnelDocumentEvent({ documentId });
      await repository.insertPersonnelDocumentEvent(personnelDocumentEvent({
        documentId,
        eventType: "version_added",
        actorEmployeeNumber: session.employeeNumber,
        previousEvent,
        createdAt,
      }));
      await repository.recordAudit({
        actor: session.employeeNumber,
        action: "personnel-record.document.version.add",
        entityType: "personnel_record_document",
        entityId: documentId,
        detail: JSON.stringify({ versionNumber }),
      });
    });
    committed = true;
    const updated = await personnelRecordDocumentMetadata(employeeNumber, documentId);
    const version = await sicknessAmuManagementRepository.getPersonnelDocumentVersion({
      documentId,
      versionNumber,
    });
    response.status(201).json({
      document: personnelRecordDocumentProjection(updated),
      version: personnelRecordDocumentVersionProjection(updated, version),
      access,
    });
  } catch (error) {
    if (!committed && stored?.storageKey) {
      try { storage.deleteBlob(stored.storageKey); } catch {}
    }
    if (error.status) throw error;
    if (error.code?.startsWith?.("AMU_")) {
      const status = error.code.includes("TOO_LARGE") || error.code.includes("LIMIT")
        ? 413 : error.code.includes("TYPE") || error.code.includes("HEIC") ? 415 : 400;
      const code = error.code.replace(/^AMU_DOCUMENT_/, "PERSONNEL_DOCUMENT_")
        .replace(/^AMU_/, "PERSONNEL_DOCUMENT_");
      throw httpError(status, error.message, code);
    }
    throw error;
  } finally {
    amuMutationInProgress = Math.max(0, amuMutationInProgress - 1);
  }
});

