async function createOwnTimeOffChangeRequest(session, body = {}) {
  const originalRequestId = Number(body.requestId || body.originalRequestId || 0);
  const requestType = String(body.requestType || "");
  if (!Number.isInteger(originalRequestId) || !["change", "cancel"].includes(requestType)) {
    throw httpError(400, "Bitte eine gueltige ZA-Aenderung auswaehlen.", "TIME_OFF_CHANGE_INVALID");
  }
  let input = { dateFrom: null, dateTo: null, allDay: false, startTime: null, endTime: null, note: stripEmoji(String(body.note || "").trim()).slice(0, 500) };
  if (requestType === "change") {
    input = { ...normalizedTimeOffInput(body), note: stripEmoji(String(body.note || "").trim()).slice(0, 500) };
  }
  return absenceManagementRepository.transaction(async (repository) => {
    const original = await repository.approvedTimeOffForOwner({
      id: originalRequestId,
      employeeNumber: session.employeeNumber,
      fromDate: viennaTodayIso(),
    });
    if (!original) throw httpError(404, "Der genehmigte Zeitausgleich wurde nicht gefunden.", "TIME_OFF_REQUEST_NOT_FOUND");
    if (await repository.pendingTimeOffChange({ originalRequestId: Number(original.id) })) {
      throw httpError(409, "Fuer diesen Zeitausgleich besteht bereits ein offener Aenderungs- oder Stornoantrag.", "TIME_OFF_CHANGE_EXISTS");
    }
    const context = requestType === "change"
      ? await assertTimeOffResponsibility(session.employeeNumber, input, repository)
      : {
        locationId: original.location_id,
        originLocationId: original.origin_location_id || original.location_id,
        departmentId: Number(original.review_department_id || 0) || null,
        lendingId: original.lending_id || null,
      };
    const check = requestType === "change"
      ? await evaluateTimeOffRequest(
        session.employeeNumber,
        { ...input, excludeRequestId: original.id },
        context,
        repository,
      )
      : null;
    if (check && !check.allowed) {
      throw httpError(409, check.reason, check.code || "TIME_OFF_NOT_POSSIBLE");
    }
    const result = await repository.insertTimeOffChange({
      employeeNumber: session.employeeNumber,
      locationId: context.locationId,
      originLocationId: context.originLocationId,
      reviewDepartmentId: context.departmentId,
      lendingId: context.lendingId,
      originalRequestId: Number(original.id),
      requestType,
      requestedDateFrom: input.dateFrom,
      requestedDateTo: input.dateTo,
      requestedAllDay: input.allDay ? 1 : 0,
      requestedStartTime: input.startTime,
      requestedEndTime: input.endTime,
      note: input.note,
      approvalType: original.approval_type || "local",
    });
    const id = Number(result.rows[0]?.id);
    const entry = {
      id,
      employee_number: session.employeeNumber,
      location_id: context.locationId,
      origin_location_id: context.originLocationId,
      review_department_id: context.departmentId,
      date_from: input.dateFrom || original.date_from,
    };
    await recordRequestDecision("time_off_change", id, "employee", requestType, session.employeeNumber, input.note, repository);
    await notifyAbsenceRequestReviewers(repository, entry, "time_off_change", "local", session.employeeNumber);
    await auditAbsence(
      repository,
      session.employeeNumber,
      `time_off.${requestType}.request`,
      "time_off_change_request",
      String(id),
      check ? JSON.stringify(check) : "",
    );
    return { id, status: "pending", ...(check ? { check } : {}) };
  });
}

async function withdrawOwnTimeOffChangeRequest(session, changeId) {
  const entry = await absenceManagementRepository.openTimeOffChangeForOwner({
    id: Number(changeId),
    employeeNumber: session.employeeNumber,
  });
  if (!entry) throw httpError(404, "Der offene Aenderungs- oder Stornoantrag wurde nicht gefunden.", "TIME_OFF_CHANGE_NOT_FOUND");
  return absenceManagementRepository.transaction(async (repository) => {
    const result = await repository.withdrawTimeOffChange({
      id: Number(entry.id),
      actor: session.employeeNumber,
    });
    if (!result.rowsAffected) throw httpError(409, "Der Antrag wurde bereits bearbeitet.", "TIME_OFF_CHANGE_CHANGED");
    await recordRequestDecision("time_off_change", entry.id, "employee", "withdraw", session.employeeNumber, "", repository);
    await resolveAbsenceRequestReviewNotifications(repository, "time_off_change", entry.id);
    await auditAbsence(repository, session.employeeNumber, "time_off.change_request.withdraw", "time_off_change_request", String(entry.id));
    return { id: Number(entry.id), status: "withdrawn" };
  });
}

async function mobileNotificationPage(employeeNumber, query = {}) {
  const limit = Math.min(100, Math.max(1, Number(query.limit || 30) || 30));
  let beforeRowId = Number.MAX_SAFE_INTEGER;
  if (query.cursor) {
    try {
      const decoded = JSON.parse(Buffer.from(String(query.cursor), "base64url").toString("utf8"));
      if (!Number.isInteger(decoded.before) || decoded.before <= 0) throw new Error();
      beforeRowId = decoded.before;
    } catch {
      throw httpError(400, "Der Benachrichtigungs-Cursor ist ungueltig.", "MOBILE_CURSOR_INVALID");
    }
  }
  const unreadOnly = String(query.unread || "") === "1";
  const rows = await absenceManagementRepository.mobileNotifications({
    employeeNumber,
    cursor: beforeRowId,
    limit: limit + 1,
  }, unreadOnly);
  const hasMore = rows.length > limit;
  const page = rows.slice(0, limit);
  const nextCursor = hasMore
    ? Buffer.from(JSON.stringify({ before: Number(page.at(-1).cursor_rowid) }), "utf8").toString("base64url")
    : null;
  const notifications = page.map(({ cursor_rowid, ...item }) => ({ ...item, request_id: item.entity_id || null }));
  const unreadCount = Number(
    (await absenceManagementRepository.mobileUnreadCount(employeeNumber))?.count || 0,
  );
  return { notifications, unreadCount, nextCursor, hasMore };
}

