app.put("/api/branding/assignments", async (request, response) => {
  const actor = requirePortalAdminOrLocal(request, "branding:write");
  const submittedAssignments = Array.isArray(request.body.assignments) ? request.body.assignments : null;
  if (submittedAssignments) {
    if (!submittedAssignments.length || submittedAssignments.length > 250) {
      throw httpError(400, "Bitte mindestens eine und hoechstens 250 Standortzuordnungen uebermitteln.", "BRANDING_ASSIGNMENTS_INVALID");
    }
    const preparedAssignments = await Promise.all(
      (await persistenceAsyncCollections.map(submittedAssignments, prepareBrandingAssignment)),
    );
    if (new Set(preparedAssignments.map(({ assignment }) => assignment.locationId)).size !== preparedAssignments.length) {
      throw httpError(400, "Jeder Standort darf pro Speichervorgang nur einmal enthalten sein.", "BRANDING_ASSIGNMENTS_DUPLICATE");
    }
    const results = await persistenceProvider.transaction(async (executor) => {
      const repositories = createApplicationRepositories(executor);
      const saved = [];
      for (const prepared of preparedAssignments) {
        saved.push(await applyBrandingAssignment(prepared.assignment, actor, {
          manageTransaction: false,
          repository: repositories.planningSettings,
          auditRepository: repositories.organizationPersonnel,
          prepared,
        }));
      }
      return saved;
    });
    await refreshPlanningSettingsReadModel();
    const refreshedResults = await Promise.all(results.map(async (result) => {
      const settings = await settingsForLocation(result.locationId);
      return { ...result, settings, branding: brandingFromSettings(settings) };
    }));
    response.json({ ok: true, results: refreshedResults, assignments: await locationBrandingAssignments(), kits: listBrandingKits() });
    return;
  }
  const result = await applyBrandingAssignment(request.body, actor);
  response.json({ ...result, assignments: await locationBrandingAssignments(), kits: listBrandingKits(result.locationId) });
});

