app.put("/api/vacation-entitlements", async (request, response) => {
  const actor = requirePortalAdminOrLocal(request, "vacation_accounts:manage");
  const year = validateYear(request.body.year);
  const entries = Array.isArray(request.body.entries) ? request.body.entries : [];
  const preparedEntries = await Promise.all(entries.map(async (entry) => {
    const employeeNumber = String(entry.employeeNumber || "").trim();
    const days = Number(entry.days || 0);
    await assertSessionEmployeeScope(actor, employeeNumber);
    if (!Number.isFinite(days) || days < 0 || days > 365) {
      throw httpError(400, "Der Jahresurlaub muss zwischen 0 und 365 Tagen liegen.");
    }
    let employmentStart = "";
    try {
      employmentStart = (await personnelSensitiveProfile(employeeNumber)).employment?.startDate || "";
    } catch {}
    return { employeeNumber, days, employmentStart };
  }));

  await persistenceProvider.transaction(async (executor) => {
    const repositories = createApplicationRepositories(executor);
    const repository = repositories.governanceStore;
    const store = createGovernanceStore(repository, {
      protectJson,
      parseProtectedJson,
    });
    for (const entry of preparedEntries) {
      const employee = await repository.vacationEntitlementEmployee(entry.employeeNumber);
      if (!employee) {
        throw httpError(404, "Ein ausgewähltes Teammitglied wurde nicht gefunden.");
      }
      await repository.upsertVacationEntitlement({
        employeeNumber: entry.employeeNumber,
        year,
        days: entry.days,
      });
      await store.ensureVacationAccount({
        employeeNumber: entry.employeeNumber,
        year,
        totalDays: entry.days,
        consumedDays: 0,
        plannedDays: 0,
        weeklyWorkdays: Number(employee.target_workdays_per_week || 5),
        employmentStart: entry.employmentStart,
        actor: actor.employeeNumber,
      });
    }
  });

  response.json(await getVacationPlan(year, request.body, actor));
});

